fn execution_context_from_summary_block(summary_block: Option<&str>) -> Option<String> {
    let summary_block = summary_block?;
    let plain = strip_ansi_codes(summary_block);
    plain.lines().find_map(|line| {
        line.trim_start()
            .strip_prefix("Context:")
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToString::to_string)
    })
}

fn container_from_summary_block(summary_block: Option<&str>) -> Option<String> {
    let summary_block = summary_block?;
    let plain = strip_ansi_codes(summary_block);
    plain.lines().find_map(|line| {
        line.trim_start()
            .strip_prefix("Container:")
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToString::to_string)
    })
}

fn split_summary_block(message: &str) -> (Option<String>, String) {
    let mut lines = message.lines();
    let Some(first_line) = lines.next() else {
        return (None, message.to_string());
    };

    let (title_line, mut lines) = if first_line.trim().is_empty() {
        let Some(title_line) = lines.next() else {
            return (None, message.to_string());
        };
        (title_line, lines)
    } else {
        (first_line, lines)
    };

    if !title_line.contains("RUN SUMMARY") && !title_line.contains("UP SUMMARY") {
        return (None, message.to_string());
    }

    let Some(blank_line) = lines.next() else {
        return (Some(message.to_string()), String::new());
    };

    if !blank_line.trim().is_empty() {
        return (None, message.to_string());
    }

    let mut summary_lines = vec![String::new(), title_line.to_string(), String::new()];
    let mut remainder_lines = Vec::new();
    let mut in_remainder = false;

    for line in lines {
        if in_remainder {
            remainder_lines.push(line.to_string());
        } else if line.trim().is_empty() {
            in_remainder = true;
        } else {
            summary_lines.push(line.to_string());
        }
    }

    if !in_remainder {
        return (Some(summary_lines.join("\n")), String::new());
    }

    (Some(summary_lines.join("\n")), remainder_lines.join("\n"))
}

fn append_summary_block(out: &mut String, summary_block: Option<&str>) {
    if let Some(summary_block) = summary_block {
        let trailing_newlines = out.chars().rev().take_while(|ch| *ch == '\n').count();
        for _ in trailing_newlines..2 {
            out.push('\n');
        }
        let summary_block = summary_block
            .trim_start_matches('\n')
            .lines()
            .filter(|line| !strip_ansi_codes(line).trim_start().starts_with("Next:"))
            .collect::<Vec<_>>()
            .join("\n");
        out.push_str(&summary_block);
    }
}

fn append_receipt_next_block(out: &mut String, receipt: &ExecutionReceipt) {
    let next_steps = execution_receipt_next_steps(receipt);
    if next_steps.is_empty() {
        return;
    }

    append_post_summary_next_block(out, &next_steps);
}

fn append_post_summary_next_block(out: &mut String, next_steps: &[String]) {
    if next_steps.is_empty() {
        return;
    }

    let trailing_newlines = out.chars().rev().take_while(|ch| *ch == '\n').count();
    for _ in trailing_newlines..2 {
        out.push('\n');
    }
    if next_steps.len() == 1 {
        out.push_str(&format!(
            "{} {}",
            paint_next_key(),
            render_backticked_text(&next_steps[0], None)
        ));
        return;
    }
    let mut next_block = String::new();
    append_error_detail_section(&mut next_block, "Next:", next_steps, None);
    out.push_str(next_block.trim_start_matches('\n'));
}

fn split_embedded_next_block(message: &str) -> Option<(String, Vec<String>)> {
    let plain = strip_ansi_codes(message);

    if let Some((why, next)) = plain.split_once(" | Next: | ") {
        let next_steps = next
            .split(" | ")
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .map(|line| {
                line.trim_start_matches('▸')
                    .trim_start_matches('»')
                    .trim_start_matches('-')
                    .trim_start_matches('*')
                    .trim()
                    .to_string()
            })
            .filter(|line| !line.is_empty())
            .collect::<Vec<_>>();
        return Some((why.trim().to_string(), next_steps));
    }

    let lines = plain
        .replace("\r\n", "\n")
        .lines()
        .map(ToString::to_string)
        .collect::<Vec<_>>();
    let marker_idx = lines
        .iter()
        .position(|line| line.trim() == "Next:" || line.trim_start().starts_with("Next:"))?;
    let mut next_steps = Vec::new();

    let marker_line = lines[marker_idx].trim_start();
    if let Some(rest) = marker_line.strip_prefix("Next:") {
        let value = rest.trim();
        if !value.is_empty() {
            next_steps.push(value.to_string());
        }
    }

    for line in lines.iter().skip(marker_idx + 1) {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        let item = trimmed
            .trim_start_matches('▸')
            .trim_start_matches('»')
            .trim_start_matches('-')
            .trim_start_matches('*')
            .trim();
        if !item.is_empty() {
            next_steps.push(item.to_string());
        }
    }

    let why = lines
        .iter()
        .take(marker_idx)
        .map(String::as_str)
        .collect::<Vec<_>>()
        .join("\n");
    Some((why, next_steps))
}

fn strip_ansi_codes(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    let mut chars = input.chars().peekable();

    while let Some(ch) = chars.next() {
        if ch == '\u{1b}' && chars.peek() == Some(&'[') {
            let _ = chars.next();
            for c in chars.by_ref() {
                if c.is_ascii_alphabetic() {
                    break;
                }
            }
            continue;
        }
        out.push(ch);
    }

    out
}

fn visible_display_width(value: &str) -> usize {
    strip_ansi_codes(value).chars().count()
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MissingContractContext {
    Repo,
    Workspace,
}

fn detect_missing_contract_context(message: &str) -> Option<MissingContractContext> {
    if message.contains("no `ota.workspace.yaml` found") && message.contains(" upward") {
        return Some(MissingContractContext::Workspace);
    }
    if message.contains("explicit workspace path does not contain `ota.workspace.yaml`")
        || message.contains("workspace path does not exist:")
    {
        return Some(MissingContractContext::Workspace);
    }
    if message.contains("no `ota.yaml` found") && message.contains(" upward") {
        return Some(MissingContractContext::Repo);
    }
    if message.contains("explicit repo path does not contain `ota.yaml`")
        || message.contains("contract path does not exist:")
    {
        return Some(MissingContractContext::Repo);
    }
    None
}

fn render_missing_contract_guidance(
    out: &mut String,
    where_label: &str,
    message: &str,
    context: MissingContractContext,
    include_where: bool,
) {
    if include_where {
        out.push_str(&format!(
            "\n{} {}",
            error_key("Where:"),
            paint_code(where_label)
        ));
    }
    let why = split_embedded_next_block(message)
        .map(|(why, _)| why)
        .filter(|why| !why.trim().is_empty())
        .unwrap_or_else(|| message.to_string());
    out.push_str(&format!("\n{} {}", error_key("Why:"), why));
    match context {
        MissingContractContext::Repo => {
            out.push_str(&format_error_next_timeline(&[
                String::from("run this command from a repo directory that contains `ota.yaml`"),
                format!(
                    "run {} to create a starter contract",
                    paint_code("`ota init`")
                ),
                format!(
                    "or run {} to preview what Ota would generate",
                    paint_code("`ota init --dry-run`")
                ),
            ]));
        }
        MissingContractContext::Workspace => {
            let workspace_target = where_label;
            out.push_str(&format_error_next_timeline(&[
                format!(
                    "run {} to preview the current workspace draft",
                    paint_code(&format!(
                        "`ota workspace detect --dry-run {workspace_target}`"
                    ))
                ),
                format!(
                    "or run {} to preview the conservative starter path",
                    paint_code(&format!(
                        "`ota workspace init --dry-run {workspace_target}`"
                    ))
                ),
            ]));
        }
    }
}

pub fn stylize_inline_text(value: &str) -> String {
    stylize_inline_code(value)
}

fn infer_failure_where(default: &str, message: &str) -> String {
    if let Some(from_idx) = message.find("from `") {
        let after_from = &message[from_idx + 6..];
        if let Some(end_idx) = after_from.find('`') {
            let candidate = &after_from[..end_idx];
            if !candidate.trim().is_empty() {
                if is_path_token(candidate) {
                    return compact_path(Path::new(candidate), "path");
                }
                return candidate.to_string();
            }
        }
    }

    for token in backticked_tokens(message) {
        if looks_like_location_token(token) {
            if is_path_token(token) {
                return compact_path(Path::new(token), "path");
            }
            return token.to_string();
        }
    }
    default.to_string()
}

fn looks_like_location_token(token: &str) -> bool {
    token == "."
        || token.starts_with("./")
        || token.starts_with("../")
        || token.starts_with('/')
        || token.starts_with('~')
        || token.contains('/')
        || token.contains('\\')
}

fn backticked_tokens(value: &str) -> Vec<&str> {
    let mut tokens = Vec::new();
    let mut rest = value;
    loop {
        let Some(start) = rest.find('`') else {
            break;
        };
        let after_start = &rest[start + 1..];
        let Some(end) = after_start.find('`') else {
            break;
        };
        tokens.push(&after_start[..end]);
        rest = &after_start[end + 1..];
    }
    tokens
}

fn explicit_run_command(next: &str) -> Option<&str> {
    for prefix in ["run `", "rerun `"] {
        if let Some(rest) = next.strip_prefix(prefix)
            && let Some(end) = rest.find('`')
        {
            return Some(&rest[..end]);
        }
    }
    None
}

fn policy_finding_source(summary: &str, why: &str) -> Option<String> {
    if summary != "Repo does not satisfy org policy pack" && summary != "Invalid org policy pack" {
        return None;
    }

    let source = backticked_tokens(why)
        .into_iter()
        .find(|token| token.contains("org-policy.yaml"))?;

    Some(format!("org policy pack {}", stylize_inline_text(source)))
}

pub fn validate(
    path: Option<&Path>,
    file_override: Option<&Path>,
    member: Option<&str>,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => {
                        missing_repo_contract_command_output("VALIDATE", "ota validate", &error)
                            .unwrap_or_else(|| CommandOutput::failure(error.to_string()))
                    }
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=validate")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let text_path_display = display_contract_target(&compact_path_display, member);
    let mut debug_lines = vec![
        String::from("DEBUG command=validate"),
        format!("DEBUG contract_path={path_display}"),
    ];
    if let Some(member) = member {
        debug_lines.push(format!("DEBUG member={member}"));
    }

    if is_org_policy_pack_path(&resolved_path) {
        return finalize_debug(
            wrong_repo_contract_target_output(
                "VALIDATE",
                &resolved_path,
                "Wrong validation target",
                &[
                    String::from("`ota validate` validates repo contracts such as `ota.yaml`"),
                    format!(
                        "{} is an org policy pack, not a repo contract",
                        paint_code(&compact_path(&resolved_path, DEFAULT_POLICY_FILE))
                    ),
                ],
                wrong_target_next_steps_for_validate(&resolved_path),
                format,
            ),
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, member) {
            Ok(target) => match validate_declared_monorepo_members(&resolved_path) {
                Ok(()) => match format {
                    OutputFormat::Text => {
                        let advisories = collect_contract_advisories_with_contract_path(
                            &target.contract,
                            Some(&resolved_path),
                        );
                        CommandOutput::success(render_validate_success_output(
                            &resolved_path,
                            member,
                            &text_path_display,
                            &advisories,
                        ))
                    }
                    OutputFormat::Json => {
                        let warnings =
                            collect_validate_warnings(&target.contract, Some(&resolved_path));
                        let warning_details = collect_validate_warning_details(
                            &target.contract,
                            Some(&resolved_path),
                        );
                        CommandOutput::success(to_json(&ValidateSuccess {
                            ok: true,
                            path: &path_display,
                            summary: Some(ValidateSummary {
                                error_count: 0,
                                warn_count: warnings.len(),
                            }),
                            warnings,
                            warning_details,
                        }))
                    }
                },
                Err(errors) => invalid_repo_contract_output(
                    "VALIDATE",
                    &resolved_path,
                    &errors,
                    validate_invalid_contract_next_steps(&resolved_path),
                    format,
                ),
            },
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => render_task_runtime_bind_validation_text(
                    "VALIDATE",
                    &resolved_path,
                    member,
                    &errors,
                    &["ota validate"],
                )
                .map(CommandOutput::failure)
                .unwrap_or_else(|| {
                    invalid_repo_contract_output(
                        "VALIDATE",
                        &resolved_path,
                        &errors
                            .errors()
                            .iter()
                            .map(ToString::to_string)
                            .collect::<Vec<_>>(),
                        validate_invalid_contract_next_steps(&resolved_path),
                        format,
                    )
                }),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    ok: false,
                    path: &path_display,
                    summary: Some(ValidateSummary {
                        error_count: errors.errors().len(),
                        warn_count: 0,
                    }),
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "VALIDATE",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &validate_invalid_contract_next_steps(&resolved_path),
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    ok: false,
                    path: &path_display,
                    summary: Some(ValidateSummary {
                        error_count: 1,
                        warn_count: 0,
                    }),
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

fn collect_validate_warnings(contract: &Contract, contract_path: Option<&Path>) -> Vec<String> {
    collect_contract_advisories_with_contract_path(contract, contract_path)
        .into_iter()
        .map(|advisory| format!("{} | Why: {}", advisory.summary(), advisory.why()))
        .collect()
}

fn collect_validate_warning_details(
    contract: &Contract,
    contract_path: Option<&Path>,
) -> Vec<ValidateWarning> {
    collect_contract_advisories_with_contract_path(contract, contract_path)
        .into_iter()
        .map(|advisory| ValidateWarning {
            code: advisory.code().to_string(),
            category: advisory.category().to_string(),
            owner: advisory.owner().to_string(),
            severity: String::from("warn"),
            summary: advisory.summary(),
            why: advisory.why(),
            next: advisory.next(),
            provenance: validate_warning_provenance(&advisory),
        })
        .collect()
}

fn validate_warning_provenance(
    advisory: &ContractAdvisory,
) -> Option<crate::output::DependencyPlaneProvenance> {
    match advisory {
        ContractAdvisory::DependsOnBoundary(value) => {
            Some(crate::output::DependencyPlaneProvenance {
                parent_task: value.parent_task.clone(),
                dependency_task: value.dependency_task.clone(),
                parent_backend: format_backend(value.parent.backend).to_string(),
                parent_context: value.parent.context_name.clone(),
                parent_backend_selection_source: value.parent_backend_selection_source.clone(),
                dependency_backend: format_backend(value.dependency.backend).to_string(),
                dependency_context: value.dependency.context_name.clone(),
                dependency_backend_selection_source: value
                    .dependency_backend_selection_source
                    .clone(),
            })
        }
        _ => None,
    }
}

fn validate_depends_on_why(
    parent: &crate::validator::TaskExecutionBoundary,
    dependency: &crate::validator::TaskExecutionBoundary,
) -> String {
    if parent.context_name == dependency.context_name
        && parent.backend == dependency.backend
        && parent.lifecycle != dependency.lifecycle
    {
        return String::from("in-process and container-local prep does not carry across");
    }
    String::from("only durable external side effects survive this edge")
}

fn render_validate_warning_detail(value: &str) -> String {
    if plain_mode() {
        return value.replace(" -> ", " → ");
    }

    let arrow = paint("→", "1;37");
    value
        .split('`')
        .enumerate()
        .map(|(index, segment)| {
            if index % 2 == 1 {
                paint_backticked_code(segment)
            } else {
                segment
                    .split(" -> ")
                    .map(paint_group_meta)
                    .collect::<Vec<_>>()
                    .join(&format!(" {arrow} "))
            }
        })
        .collect::<String>()
}

