fn render_validate_success_output(
    resolved_path: &Path,
    member: Option<&str>,
    text_path_display: &str,
    advisories: &[ContractAdvisory],
) -> String {
    let mut stdout = format!(
        "{}\n\n{}{}",
        format_command_header("VALIDATE", text_path_display),
        render_valid_status(),
        render_validate_ready_next(resolved_path, member)
    );
    if !advisories.is_empty() {
        let warnings_title = if plain_mode() {
            String::from("Warnings")
        } else {
            paint("Warnings", "1;33")
        };
        stdout.push_str(&format!("\n\n{}", warnings_title));
        for (index, advisory) in advisories.iter().enumerate() {
            if index == 0 {
                stdout.push('\n');
            } else {
                stdout.push_str("\n\n");
            }
            stdout.push_str(&render_validate_warning(advisory));
        }
    }
    stdout
}

fn validate_invalid_contract_next_steps(contract_path: &Path) -> Vec<String> {
    vec![
        format!(
            "repair {}",
            paint_code(&format!("`{}`", compact_contract_path(contract_path)))
        ),
        format!(
            "rerun {}",
            paint_code(&format!(
                "`{}`",
                command_for_repo_contract_target("ota validate", contract_path)
            ))
        ),
    ]
}

fn render_validate_ready_next(contract_path: &Path, member: Option<&str>) -> String {
    let doctor = match member {
        Some(member) => format!(
            "run `{}` to inspect readiness",
            command_for_repo_contract_target(
                &format!("ota doctor --member {member}"),
                contract_path
            )
        ),
        None => format!(
            "run `{}` to inspect readiness",
            command_for_repo_contract_target("ota doctor", contract_path)
        ),
    };
    let tasks = match member {
        Some(member) => format!(
            "run `{}` to inspect runnable task usage",
            command_for_repo_contract_target(
                &format!("ota tasks --member {member} --use"),
                contract_path
            )
        ),
        None => format!(
            "run `{}` to inspect runnable task usage",
            command_for_repo_contract_target("ota tasks --use", contract_path)
        ),
    };

    format_next_timeline(&[doctor, tasks])
}

fn ci_projection_for_contract(
    contract: &Contract,
    contract_path: &Path,
    workflow: &str,
    requested_mode: Option<&str>,
    target_os: &str,
) -> Result<CiProjection, (String, String, Option<CiProjection>)> {
    let task = contract
        .workflows
        .as_ref()
        .and_then(|workflows| workflows.items.get(workflow))
        .and_then(|workflow| workflow.run.as_ref())
        .map(|run| run.task.as_str())
        .ok_or_else(|| {
            (
                String::from("projection_unavailable"),
                format!("workflow `{workflow}` does not declare `run.task`"),
                None,
            )
        })?;
    let requested_backend = match requested_mode {
        Some("native") => Some(Backend::Native),
        Some("container") => Some(Backend::Container),
        Some("remote") => Some(Backend::Remote),
        Some(mode) => {
            return Err((
                String::from("projection_mode_unsupported"),
                format!("unsupported execution mode `{mode}`"),
                None,
            ));
        }
        None => None,
    };
    let effective = effective_task_execution(
        contract,
        task,
        ExecutionOverrides {
            backend: requested_backend,
            ..ExecutionOverrides::default()
        },
    );
    let mode = match effective.backend {
        Backend::Native => "native",
        Backend::Container => "container",
        Backend::Remote => "remote",
    };
    let unsupported_task = contract
        .task_dependency_closure_names([task.to_string()])
        .into_iter()
        .filter_map(|task_name| {
            contract
                .tasks
                .get(task_name.as_str())
                .map(|candidate| (task_name, candidate))
        })
        // Aggregate nodes are orchestration-only. Their selected executable closure owns mode support.
        .find(|(_, candidate)| {
            candidate.aggregate.is_none()
                && (!candidate.active_for_os(target_os)
                    || !candidate.supports_execution_backend(
                        contract.execution.as_ref(),
                        effective.backend,
                        target_os,
                    ))
        })
        .map(|(task_name, _)| task_name);
    if let Some(unsupported_task) = unsupported_task {
        return Err((
            String::from("projection_mode_unavailable"),
            format!(
                "workflow `{workflow}` task closure member `{unsupported_task}` does not support `{mode}` execution on `{target_os}`"
            ),
            None,
        ));
    }
    let projection = build_ci_projection(contract, workflow, mode, target_os)
        .map_err(|message| (String::from("projection_unavailable"), message, None))?;
    let loaded_policy = load_org_policy_pack_auto_details(contract_path).map_err(|error| {
        (
            String::from("org_policy_unavailable"),
            error.to_string(),
            Some(projection.clone()),
        )
    })?;
    apply_ci_projection_governance(
        contract,
        contract_path,
        workflow,
        mode,
        projection,
        loaded_policy.as_ref(),
    )
}

fn apply_ci_projection_governance(
    contract: &Contract,
    contract_path: &Path,
    workflow: &str,
    mode: &str,
    mut projection: CiProjection,
    loaded_policy: Option<&LoadedOrgPolicyPack>,
) -> Result<CiProjection, (String, String, Option<CiProjection>)> {
    let policy_snapshot = DoctorPolicySnapshot {
        loaded: loaded_policy,
        load_error: None,
    };
    let overrides = ExecutionOverrides {
        backend: Some(match mode {
            "native" => Backend::Native,
            "container" => Backend::Container,
            "remote" => Backend::Remote,
            _ => unreachable!("projection mode was validated by build_ci_projection"),
        }),
        ..ExecutionOverrides::default()
    };
    if let Some(refusal) = agent_workflow_execution_refusal_with_policy(
        contract,
        contract_path,
        Some(workflow),
        overrides,
        UpRunBehaviorPreference::Auto,
        policy_snapshot,
    ) {
        projection.governance.agent_admission.decision = if refusal.reason.contains("review") {
            String::from("review")
        } else {
            String::from("deny")
        };
        projection.governance.agent_admission.basis = vec![refusal.reason.to_string()];
        let _ = refresh_ci_projection_identity(&mut projection);
        return Err((
            refusal.reason.to_string(),
            format!(
                "workflow `{workflow}` cannot be projected for agent execution because closure task `{}` is not admitted",
                refusal.requested_task
            ),
            Some(projection),
        ));
    } else {
        projection.governance.agent_admission.decision = String::from("allow");
        projection.governance.agent_admission.basis = vec![String::from("agent_closure_admitted")];
    }

    // Project the same selected phase roots as `ota up`; the typed planner expands their active
    // dependencies and hooks without admitting an unselected mode's dependency graph.
    let effect_policy_roots = selected_workflow_phase_task_roots(contract, Some(workflow));
    let effect_closure = build_typed_effect_closure_admission(
        contract,
        contract_path,
        effect_policy_roots.as_slice(),
        overrides,
    )
    .map_err(|error| {
        (
            String::from("effect_policy_evaluation_unavailable"),
            format!("workflow `{workflow}` typed effect admission could not be derived: {error}"),
            Some(projection.clone()),
        )
    })?;
    let effect_policy_decision = typed_effect_policy_decision_from_loaded_policy(
        contract,
        Some(workflow),
        projection.task.as_str(),
        &effect_closure,
        loaded_policy,
        Some(&current_effect_governance_overrides()),
    )
    .map_err(|error| {
        (
            String::from("effect_policy_evaluation_unavailable"),
            format!("workflow `{workflow}` typed effect policy could not be evaluated: {error}"),
            Some(projection.clone()),
        )
    })?;
    projection.governance.effect_policy_decision = effect_policy_decision;
    if projection
        .governance
        .effect_policy_decision
        .as_ref()
        .is_some_and(|decision| decision.aggregate_decision == PolicyEffectDecision::Deny)
    {
        let _ = refresh_ci_projection_identity(&mut projection);
        return Err((
            String::from("effect_policy_denied"),
            format!(
                "workflow `{workflow}` typed effect policy is denied in this checkout before provider execution"
            ),
            Some(projection),
        ));
    }

    if projection.proof_required {
        let record = doctor_claim_assurance_with_overrides(
            contract,
            contract_path,
            overrides,
            policy_snapshot.loaded,
        )
        .into_iter()
        .find(|record| {
            record.subject.kind == "workflow"
                && record.subject.name == workflow
                && record.family == "proof_breadth"
        })
        .ok_or_else(|| {
            (
                String::from("proof_assurance_unavailable"),
                format!("workflow `{workflow}` declares proof without a proof-assurance record"),
                None,
            )
        })?;
        projection.governance.proof_assurance = Some(CiProjectionProofAssurance {
            status: record.assurance.status,
            policy_decision: record.policy.decision.clone(),
            basis: record.policy.basis,
        });
        if matches!(record.policy.decision.as_str(), "deny" | "review") {
            let _ = refresh_ci_projection_identity(&mut projection);
            return Err((
                format!("proof_assurance_policy_{}", record.policy.decision),
                format!(
                    "workflow `{workflow}` proof assurance is `{}` under the selected policy",
                    record.policy.decision
                ),
                Some(projection),
            ));
        }
    }
    if let Some(loaded_policy) = loaded_policy {
        let evaluation = evaluate_replay_input_policy(
            contract,
            contract_path.parent().unwrap_or_else(|| Path::new(".")),
            &loaded_policy.pack,
            ReplayInputPolicySubject::Workflow(workflow),
        );
        if evaluation.required {
            projection.governance.replay_input_policy =
                Some(CiProjectionReplayInputPolicyRequirement {
                    policy_identity: evaluation.policy_identity.clone(),
                    rule_identities: evaluation
                        .applicable_rules
                        .iter()
                        .map(|rule| rule.identity.clone())
                        .collect(),
                    selected_closure: selected_replay_input_policy_closure(
                        contract,
                        ReplayInputPolicySubject::Workflow(workflow),
                    ),
                    unknown_selector_identities: evaluation
                        .unknown_selectors
                        .iter()
                        .map(|selector| selector.identity.clone())
                        .collect(),
                });
        }
        if !evaluation.unknown_selectors.is_empty() {
            let identities = evaluation
                .unknown_selectors
                .iter()
                .map(|selector| selector.identity.clone())
                .collect::<Vec<_>>();
            let _ = refresh_ci_projection_identity(&mut projection);
            return Err((
                String::from("replay_input_policy_selector_unknown"),
                format!(
                    "workflow `{workflow}` cannot be projected while replay-input policy selectors are unresolved: {}",
                    identities.join(", ")
                ),
                Some(projection),
            ));
        }
        if evaluation.required {
            if matches!(evaluation.decision.as_str(), "deny" | "review") {
                let decision = evaluation.decision.clone();
                let _ = refresh_ci_projection_identity(&mut projection);
                return Err((
                    format!("replay_input_policy_{decision}"),
                    format!(
                        "workflow `{workflow}` replay-input identity policy decision is `{decision}` in this checkout"
                    ),
                    Some(projection),
                ));
            }
        }
    }
    refresh_ci_projection_identity(&mut projection).map_err(|message| {
        (
            String::from("projection_identity_unavailable"),
            message,
            None,
        )
    })?;
    Ok(projection)
}

pub fn authority_inspect(format: OutputFormat) -> CommandOutput {
    let report = crate::crossing_authority::inspect_prebound_authority(Path::new("."));
    let exit_code = if report.ok { 0 } else { 1 };
    let stdout = match format {
        OutputFormat::Json => to_json(&report),
        OutputFormat::Text => {
            let required_failures = report
                .observations
                .iter()
                .filter(|observation| {
                    observation.required
                        && observation.status
                            != crate::crossing_authority::AuthorityInspectObservationStatus::Passed
                })
                .map(|observation| format!("{} ({})", observation.id, observation.reason))
                .collect::<Vec<_>>();
            let next = if report.ok {
                "use this diagnostic together with provider/launcher evidence; it is not crossing authority"
            } else {
                "have the runner administrator repair the fixed prebound-file boundary, then inspect again"
            };
            format!(
                "Profile: {} v{}\nVerdict: {}\nAuthority source: {}\nSeparation posture: {}\nPlatform: {}/{}\nRequired gaps: {}\nNext: {}",
                report.profile.id,
                report.profile.version,
                report.profile.verdict,
                report.authority_source,
                report.authority_separation_posture,
                report.platform.os,
                report.platform.architecture,
                if required_failures.is_empty() {
                    String::from("none")
                } else {
                    required_failures.join(", ")
                },
                next,
            )
        }
    };
    CommandOutput {
        stdout,
        stderr: None,
        exit_code,
    }
}

pub fn ci_projection(
    path: Option<&Path>,
    file_override: Option<&Path>,
    workflow: &str,
    mode: Option<&str>,
    target_os: &str,
    expected_identity: Option<&str>,
    format: OutputFormat,
) -> CommandOutput {
    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => return ci_github_failure(format, "contract_not_found", error.to_string()),
    };
    let contract = match load_contract(&resolved_path) {
        Ok(contract) => contract,
        Err(error) => return ci_github_failure(format, "contract_invalid", error.to_string()),
    };
    let projection =
        match ci_projection_for_contract(&contract, &resolved_path, workflow, mode, target_os) {
            Ok(projection) => projection,
            Err((code, message, Some(projection))) if matches!(format, OutputFormat::Json) => {
                return CommandOutput::failure(
                    serde_json::to_string_pretty(&json!({
                        "ok": false,
                        "operation": "projection",
                        "code": code,
                        "message": message,
                        "projection": projection,
                        "refusal": { "code": code, "message": message },
                    }))
                    .expect("CI projection refusal JSON is serializable"),
                );
            }
            Err((code, message, _)) => return ci_github_failure(format, &code, message),
        };
    if expected_identity.is_some_and(|expected| expected != projection.identity) {
        return ci_github_failure(
            format,
            "projection_identity_mismatch",
            format!(
                "expected projection identity `{}`, observed `{}`",
                expected_identity.expect("identity checked"),
                projection.identity
            ),
        );
    }
    match format {
        OutputFormat::Text => CommandOutput::success(
            serde_json::to_string_pretty(&projection).expect("CI projection JSON is serializable"),
        ),
        OutputFormat::Json => CommandOutput::success(
            serde_json::to_string_pretty(&json!({
                "ok": true,
                "operation": "projection",
                "projection": projection,
            }))
            .expect("CI projection JSON is serializable"),
        ),
    }
}

pub fn ci_github_render(
    path: Option<&Path>,
    file_override: Option<&Path>,
    workflow: &str,
    output: Option<&Path>,
    runner: &str,
    mode: Option<&str>,
    target_os: &str,
    format: OutputFormat,
    _debug: bool,
) -> CommandOutput {
    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => return ci_github_failure(format, "contract_not_found", error.to_string()),
    };
    let contract = match load_contract(&resolved_path) {
        Ok(contract) => contract,
        Err(error) => return ci_github_failure(format, "contract_invalid", error.to_string()),
    };
    let projection =
        match ci_projection_for_contract(&contract, &resolved_path, workflow, mode, target_os) {
            Ok(projection) => render_github_projection_from_projection(projection, runner),
            Err((code, message, _)) => return ci_github_failure(format, &code, message),
        };
    let projection = match projection {
        Ok(projection) => projection,
        Err(error) => return ci_github_failure(format, "projection_unavailable", error),
    };
    let root = resolved_path.parent().unwrap_or_else(|| Path::new("."));
    let output = match output {
        Some(output) => match ci_github_repo_path(root, output, "output") {
            Ok(path) => Some(path),
            Err(error) => return ci_github_failure(format, "invalid_output_path", error),
        },
        None => None,
    };

    match format {
        OutputFormat::Text => CommandOutput::success(projection.rendered),
        OutputFormat::Json => CommandOutput::success(
            serde_json::to_string_pretty(&json!({
                "ok": true,
                "operation": "render",
                "projection": projection,
                "output_path": output.map(|path| path.display().to_string()),
                "mutated": false,
            }))
            .expect("GitHub projection JSON is serializable"),
        ),
    }
}

pub fn ci_github_check(
    path: Option<&Path>,
    file_override: Option<&Path>,
    workflow: &str,
    output: &Path,
    caller: &Path,
    runner: &str,
    mode: Option<&str>,
    target_os: &str,
    sync: bool,
    format: OutputFormat,
    _debug: bool,
) -> CommandOutput {
    let operation = if sync { "sync" } else { "check" };
    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => return ci_github_failure(format, "contract_not_found", error.to_string()),
    };
    let root = resolved_path.parent().unwrap_or_else(|| Path::new("."));
    let output = match ci_github_repo_path(root, output, "output") {
        Ok(path) => path,
        Err(error) => return ci_github_failure(format, "invalid_output_path", error),
    };
    let caller = match ci_github_repo_path(root, caller, "caller") {
        Ok(path) => path,
        Err(error) => return ci_github_failure(format, "invalid_caller_path", error),
    };
    if output == caller {
        return ci_github_failure(
            format,
            "caller_is_managed_output",
            String::from(
                "the human-owned caller path must differ from the Ota-managed output path",
            ),
        );
    }
    let contract = match load_contract(&resolved_path) {
        Ok(contract) => contract,
        Err(error) => return ci_github_failure(format, "contract_invalid", error.to_string()),
    };
    let projection =
        match ci_projection_for_contract(&contract, &resolved_path, workflow, mode, target_os) {
            Ok(projection) => render_github_projection_from_projection(projection, runner),
            Err((code, message, _)) => return ci_github_failure(format, &code, message),
        };
    let projection = match projection {
        Ok(projection) => projection,
        Err(error) => return ci_github_failure(format, "projection_unavailable", error),
    };
    let caller_contents = match fs::read_to_string(&caller) {
        Ok(contents) => contents,
        Err(error) => {
            return ci_github_failure(
                format,
                "caller_unavailable",
                format!("could not read caller `{}`: {error}", caller.display()),
            );
        }
    };
    let Some(caller_binding) = caller_projection_binding(
        &caller_contents,
        &output,
        root,
        &projection.projection.identity,
        &projection.projection.target_os,
    ) else {
        return ci_github_failure(
            format,
            "caller_projection_reference_mismatch",
            format!(
                "caller `{}` must reference `{}` with ota_projection_identity `{}` and ota_target_os `{}`",
                caller.display(),
                output.strip_prefix(root).unwrap_or(&output).display(),
                projection.projection.identity,
                projection.projection.target_os,
            ),
        );
    };

    let existing = match fs::read_to_string(&output) {
        Ok(contents) => Some(contents),
        Err(error) if error.kind() == io::ErrorKind::NotFound => None,
        Err(error) => {
            return ci_github_failure(
                format,
                "managed_output_unavailable",
                format!(
                    "could not read managed GitHub workflow `{}`: {error}",
                    output.display()
                ),
            );
        }
    };
    if sync {
        if let Some(existing) = existing.as_deref() {
            if managed_projection_identity(existing).is_none() {
                return ci_github_failure(
                    format,
                    "managed_output_unowned",
                    format!(
                        "refusing to overwrite unowned GitHub workflow `{}`; only files starting with `{OWNERSHIP_MARKER}` are sync targets",
                        output.display()
                    ),
                );
            }
            if managed_projection_identity(existing)
                == Some(projection.projection.identity.as_str())
                && ci_github_projection_semantically_matches(existing, &projection.rendered)
            {
                return ci_github_success(
                    format,
                    operation,
                    &projection,
                    &output,
                    &caller,
                    &caller_binding,
                    false,
                );
            }
        }
        if let Err(error) = ci_github_atomic_write(&output, projection.rendered.as_bytes()) {
            return ci_github_failure(format, "sync_write_failed", error);
        }
        return ci_github_success(
            format,
            operation,
            &projection,
            &output,
            &caller,
            &caller_binding,
            true,
        );
    }

    let Some(existing) = existing.as_deref() else {
        return ci_github_failure(
            format,
            "managed_output_missing",
            format!(
                "managed GitHub workflow `{}` does not exist",
                output.display()
            ),
        );
    };
    if managed_projection_identity(existing) != Some(projection.projection.identity.as_str())
        || !ci_github_projection_semantically_matches(existing, &projection.rendered)
    {
        return ci_github_failure(
            format,
            "managed_output_stale",
            format!(
                "managed GitHub workflow `{}` does not match projection `{}`; run `ota ci github sync --workflow {workflow} --output {}` after updating its human-owned caller reference",
                output.display(),
                projection.projection.identity,
                output.display()
            ),
        );
    }
    ci_github_success(
        format,
        operation,
        &projection,
        &output,
        &caller,
        &caller_binding,
        false,
    )
}

fn ci_github_repo_path(root: &Path, path: &Path, label: &str) -> Result<PathBuf, String> {
    if path.is_absolute()
        || path.components().any(|component| {
            matches!(
                component,
                Component::ParentDir | Component::RootDir | Component::Prefix(_)
            )
        })
    {
        return Err(format!(
            "{label} path must be a normalized repo-relative path: `{}`",
            path.display()
        ));
    }
    let candidate = root.join(path);
    if !candidate.starts_with(root) {
        return Err(format!(
            "{label} path escapes the contract repository: `{}`",
            path.display()
        ));
    }
    let workflow_dir = root.join(".github/workflows");
    let yaml_extension = candidate
        .extension()
        .and_then(|extension| extension.to_str())
        .is_some_and(|extension| matches!(extension, "yml" | "yaml"));
    if !candidate.starts_with(&workflow_dir) || !yaml_extension {
        return Err(format!(
            "{label} path must name a .yml or .yaml file under `.github/workflows`: `{}`",
            path.display()
        ));
    }
    ci_github_verify_existing_path_containment(root, &candidate, label)?;
    Ok(candidate)
}

// Check the nearest existing ancestor so a managed workflow path cannot traverse a symlink out of
// the repository before sync creates or replaces the file.
fn ci_github_verify_existing_path_containment(
    root: &Path,
    candidate: &Path,
    label: &str,
) -> Result<(), String> {
    let canonical_root = fs::canonicalize(root).map_err(|error| {
        format!(
            "could not canonicalize contract repository `{}`: {error}",
            root.display()
        )
    })?;
    let mut existing = candidate;
    while !existing.exists() {
        existing = existing.parent().ok_or_else(|| {
            format!(
                "{label} path has no existing repository ancestor: `{}`",
                candidate.display()
            )
        })?;
    }
    let canonical_existing = fs::canonicalize(existing).map_err(|error| {
        format!(
            "could not canonicalize {label} path ancestor `{}`: {error}",
            existing.display()
        )
    })?;
    if !canonical_existing.starts_with(&canonical_root) {
        return Err(format!(
            "{label} path escapes the contract repository through a symlink: `{}`",
            candidate.display()
        ));
    }
    Ok(())
}

fn ci_github_projection_semantically_matches(actual: &str, expected: &str) -> bool {
    let actual = actual.lines().skip(1).collect::<Vec<_>>().join("\n");
    let expected = expected.lines().skip(1).collect::<Vec<_>>().join("\n");
    match (
        serde_yaml::from_str::<YamlValue>(&actual),
        serde_yaml::from_str::<YamlValue>(&expected),
    ) {
        (Ok(actual), Ok(expected)) => actual == expected,
        // A malformed managed workflow is drift, never semantic equivalence.
        _ => false,
    }
}

fn ci_github_atomic_write(path: &Path, contents: &[u8]) -> Result<(), String> {
    let parent = path.parent().ok_or_else(|| {
        format!(
            "managed output `{}` has no parent directory",
            path.display()
        )
    })?;
    fs::create_dir_all(parent)
        .map_err(|error| format!("could not create `{}`: {error}", parent.display()))?;
    let root = path
        .ancestors()
        .find(|ancestor| ancestor.file_name().is_some_and(|name| name == ".github"))
        .and_then(Path::parent)
        .ok_or_else(|| format!("managed output `{}` has no repository root", path.display()))?;
    ci_github_verify_existing_path_containment(root, path, "output")?;
    let nonce = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or_default();
    let temporary = parent.join(format!(
        ".{}.ota-tmp-{}-{nonce}",
        path.file_name()
            .and_then(|name| name.to_str())
            .unwrap_or("projection.yml"),
        std::process::id()
    ));
    fs::write(&temporary, contents)
        .map_err(|error| format!("could not write `{}`: {error}", temporary.display()))?;
    atomic_replace_file(&temporary, path).map_err(|error| {
        let _ = fs::remove_file(&temporary);
        format!("could not atomically replace `{}`: {error}", path.display())
    })
}

#[cfg(not(windows))]
fn atomic_replace_file(temporary: &Path, path: &Path) -> io::Result<()> {
    fs::rename(temporary, path)
}

#[cfg(windows)]
fn atomic_replace_file(temporary: &Path, path: &Path) -> io::Result<()> {
    use std::iter::once;
    use std::os::windows::ffi::OsStrExt;

    if !path.exists() {
        return fs::rename(temporary, path);
    }
    let target = path
        .as_os_str()
        .encode_wide()
        .chain(once(0))
        .collect::<Vec<_>>();
    let replacement = temporary
        .as_os_str()
        .encode_wide()
        .chain(once(0))
        .collect::<Vec<_>>();
    let replaced = unsafe {
        windows_sys::Win32::Storage::FileSystem::ReplaceFileW(
            target.as_ptr(),
            replacement.as_ptr(),
            std::ptr::null(),
            0,
            std::ptr::null(),
            std::ptr::null(),
        )
    };
    if replaced == 0 {
        Err(io::Error::last_os_error())
    } else {
        Ok(())
    }
}

fn ci_github_success(
    format: OutputFormat,
    operation: &str,
    projection: &GitHubProjection,
    output: &Path,
    caller: &Path,
    caller_binding: &CallerProjectionBinding,
    mutated: bool,
) -> CommandOutput {
    let binding_identity = format!(
        "sha256:{:x}",
        Sha256::digest(
            serde_json::to_vec(&(1u8, &projection.render_identity, caller_binding,))
                .expect("GitHub binding identity is serializable")
        )
    );
    match format {
        OutputFormat::Text => CommandOutput::success(format!(
            "Ota GitHub projection {operation} succeeded\nProjection: {}\nManaged output: {}\nCaller: {}\n",
            projection.projection.identity,
            output.display(),
            caller.display()
        )),
        OutputFormat::Json => CommandOutput::success(
            serde_json::to_string_pretty(&json!({
                "ok": true,
                "operation": operation,
                "projection": projection,
                "binding_identity": binding_identity,
                "output_path": output.display().to_string(),
                "caller_path": caller.display().to_string(),
                "mutated": mutated,
            }))
            .expect("GitHub projection JSON is serializable"),
        ),
    }
}

fn ci_github_failure(format: OutputFormat, code: &str, message: String) -> CommandOutput {
    match format {
        OutputFormat::Text => {
            CommandOutput::failure(format!("GitHub projection failed [{code}]: {message}"))
        }
        OutputFormat::Json => CommandOutput {
            stdout: serde_json::to_string_pretty(&json!({
                "ok": false,
                "code": code,
                "message": message,
            }))
            .expect("GitHub projection failure JSON is serializable"),
            stderr: None,
            exit_code: 1,
        },
    }
}

pub fn execution_plan(
    path: Option<&Path>,
    file_override: Option<&Path>,
    member: Option<&str>,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => missing_repo_contract_command_output(
                        "EXECUTION PLAN",
                        "ota execution plan",
                        &error,
                    )
                    .unwrap_or_else(|| CommandOutput::failure(error.to_string())),
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=execution-plan")],
            );
        }
    };

    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let text_path_display = display_contract_target(&compact_path_display, member);
    let mut debug_lines = vec![
        String::from("DEBUG command=execution-plan"),
        format!("DEBUG contract_path={path_display}"),
    ];
    if let Some(member) = member {
        debug_lines.push(format!("DEBUG member={member}"));
    }
    if let Some(workflow_name) = workflow_name {
        debug_lines.push(format!("DEBUG workflow={workflow_name}"));
    }
    if let Some(backend) = overrides.backend {
        debug_lines.push(format!(
            "DEBUG backend_override={}",
            format_backend(backend)
        ));
    }
    if let Some(lifecycle) = overrides.lifecycle {
        debug_lines.push(format!(
            "DEBUG lifecycle_override={}",
            format_lifecycle(lifecycle)
        ));
    }
    if overrides.skip_deps {
        debug_lines.push(String::from("DEBUG skip_deps=true"));
    }
    if let Some(host_port) = overrides.host_port {
        debug_lines.push(format!("DEBUG host_port_override={host_port}"));
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, member) {
            Ok(target) => {
                let contract_path_display = target.contract_path.display().to_string();
                let contract_identity = repo_contract_identity(&target.contract);
                let declared_execution =
                    ExecutionSummary::from_contract(&target.contract, &target.contract_path);
                let workflow_summary = match resolve_selected_workflow_summary(
                    &target.contract,
                    &target.contract_path,
                    workflow_name,
                ) {
                    Ok(summary) => summary,
                    Err(error) => {
                        return finalize_debug(
                            CommandOutput::failure_with_code(error, 2),
                            debug,
                            debug_lines,
                        );
                    }
                };
                let selected_task =
                    selected_execution_plan_task_name(&target.contract, workflow_name);
                match resolve_execution_plan(
                    &target.contract,
                    &target.contract_path,
                    overrides,
                    workflow_name,
                ) {
                    Ok(resolved_execution) => {
                        let applied_overrides = execution_plan_overrides(overrides);
                        let workflow_env_artifacts =
                            selected_workflow_env_profile_rendered_artifact_entries(
                                &target.contract,
                                &target.contract_path,
                                workflow_name,
                            );

                        match format {
                            OutputFormat::Text => {
                                CommandOutput::success(render_execution_plan_text(
                                    &text_path_display,
                                    &target.contract_path,
                                    &contract_identity,
                                    workflow_summary.as_ref(),
                                    selected_task,
                                    declared_execution.as_ref(),
                                    &workflow_env_artifacts,
                                    &resolved_execution,
                                    applied_overrides.as_ref(),
                                ))
                            }
                            OutputFormat::Json => {
                                CommandOutput::success(to_json(&ExecutionPlanSuccess {
                                    ok: true,
                                    path: &path_display,
                                    contract: &contract_path_display,
                                    member,
                                    workflow: workflow_summary,
                                    task: selected_task,
                                    contract_identity,
                                    declared_execution,
                                    workflow_env_artifacts,
                                    resolved: resolved_execution,
                                    overrides: applied_overrides,
                                }))
                            }
                        }
                    }
                    Err(error) => match format {
                        OutputFormat::Text => {
                            CommandOutput::failure(render_execution_plan_structured_error(
                                &target.contract,
                                &target.contract_path,
                                member,
                                overrides,
                                &error,
                            ))
                        }
                        OutputFormat::Json => {
                            CommandOutput::failure(to_json(&ExecutionPlanFailure {
                                ok: false,
                                path: &path_display,
                                member,
                                errors: Vec::new(),
                                error: Some(execution_plan_error(&error)),
                            }))
                        }
                    },
                }
            }
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_repo_contract_output(
                    "EXECUTION PLAN",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota validate", &resolved_path)
                            ))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target(
                                    "ota execution plan",
                                    &resolved_path
                                )
                            ))
                        ),
                    ],
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&ExecutionPlanFailure {
                    ok: false,
                    path: &path_display,
                    member,
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "EXECUTION PLAN",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &[
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota validate", &resolved_path)
                            ))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target(
                                    "ota execution plan",
                                    &resolved_path
                                )
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ExecutionPlanFailure {
                    ok: false,
                    path: &path_display,
                    member,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

