fn build_assist_readiness_proposal(
    contract: &Contract,
    task: Option<&str>,
    service: Option<&str>,
    endpoint: Option<&str>,
    requested_style: Option<AssistReadinessStyleArg>,
) -> Result<AssistReadinessProposal, (String, String)> {
    match (task, service) {
        (Some(_), Some(_)) => {
            return Err((
                String::from("select either `--task` or `--service`, not both"),
                String::from(
                    "rerun `ota assist declare-readiness` with exactly one target selector",
                ),
            ));
        }
        (None, None) => {
            return Err((
                String::from("one target selector is required"),
                String::from("rerun with `--task <name>` or `--service <name>`"),
            ));
        }
        _ => {}
    }

    match resolve_assist_readiness_target(contract, task, service, endpoint, requested_style) {
        Ok(ResolvedAssistReadinessTarget::Task {
            name,
            listener,
            existing,
        }) => {
            let style = resolve_assist_style_for_task(contract, &name, &listener, requested_style)?;
            let after = match style {
                AssistReadinessStyleArg::SpringHttp => TaskRuntimeReadinessSpec {
                    probe: None,
                    signal_probes: Vec::new(),
                    kind: Some(TaskRuntimeReadinessKind::Http),
                    listener: Some(listener.clone()),
                    method: Some(TaskRuntimeReadinessHttpMethod::Get),
                    path: Some(String::from("/actuator/health")),
                    headers: BTreeMap::from([(
                        String::from("Accept"),
                        String::from("application/json"),
                    )]),
                    success: Some(TaskRuntimeReadinessHttpSuccessSpec { status: vec![200] }),
                    body: Some(TaskRuntimeReadinessHttpBodySpec {
                        contains: String::from("\"status\":\"UP\""),
                    }),
                    interval: Some(String::from("5s")),
                    timeout: Some(String::from("3s")),
                    retries: Some(5),
                    start_period: Some(String::from("10s")),
                },
                AssistReadinessStyleArg::Http => TaskRuntimeReadinessSpec {
                    probe: None,
                    signal_probes: Vec::new(),
                    kind: Some(TaskRuntimeReadinessKind::Http),
                    listener: Some(listener.clone()),
                    method: Some(TaskRuntimeReadinessHttpMethod::Get),
                    path: Some(String::from("/health")),
                    headers: BTreeMap::new(),
                    success: Some(TaskRuntimeReadinessHttpSuccessSpec { status: vec![200] }),
                    body: None,
                    interval: Some(String::from("5s")),
                    timeout: Some(String::from("3s")),
                    retries: Some(5),
                    start_period: Some(String::from("10s")),
                },
                AssistReadinessStyleArg::Tcp => TaskRuntimeReadinessSpec {
                    probe: None,
                    signal_probes: Vec::new(),
                    kind: Some(TaskRuntimeReadinessKind::Tcp),
                    listener: Some(listener.clone()),
                    method: None,
                    path: None,
                    headers: BTreeMap::new(),
                    success: None,
                    body: None,
                    interval: Some(String::from("5s")),
                    timeout: Some(String::from("3s")),
                    retries: Some(5),
                    start_period: Some(String::from("10s")),
                },
                AssistReadinessStyleArg::ComposeHealth => unreachable!(
                    "compose-health style is service-only and rejected for task targets"
                ),
                AssistReadinessStyleArg::SystemdActive => unreachable!(
                    "systemd-active style is service-only and rejected for task targets"
                ),
            };
            let before_value = existing
                .as_ref()
                .map(serde_yaml::to_value)
                .transpose()
                .map_err(|error| {
                    (
                        format!("failed to capture existing readiness for preview: {error}"),
                        String::from("rerun the assist command after repairing the contract"),
                    )
                })?
                .unwrap_or(YamlValue::Null);
            let after_value = serde_yaml::to_value(&after).map_err(|error| {
                (
                    format!("failed to build readiness proposal: {error}"),
                    String::from("rerun the assist command after repairing the contract"),
                )
            })?;
            Ok(AssistReadinessProposal {
                subject_kind: "task",
                subject_name: name.clone(),
                endpoint: None,
                style,
                assumptions: vec![
                    format!("task `{name}` already declares a service runtime"),
                    format!("listener `{listener}` is the readiness surface"),
                ],
                change_path: format!("tasks.{name}.runtime.readiness"),
                yaml_path: vec![
                    String::from("tasks"),
                    name,
                    String::from("runtime"),
                    String::from("readiness"),
                ],
                before_value,
                after_value,
            })
        }
        Ok(ResolvedAssistReadinessTarget::Service {
            name,
            from,
            endpoint,
            compose_managed,
            systemd_managed,
            existing,
        }) => {
            let style = resolve_assist_style_for_service(
                existing.as_ref(),
                requested_style,
                compose_managed,
                systemd_managed,
            )?;
            let endpoint_from = from.unwrap_or_else(|| String::from("host"));
            let after = match style {
                AssistReadinessStyleArg::SpringHttp => ServiceReadinessSpec {
                    from: Some(endpoint_from.clone()),
                    endpoint: endpoint.clone(),
                    run: None,
                    probe: None,
                    kind: Some(ServiceReadinessKind::Http),
                    method: Some(TaskRuntimeReadinessHttpMethod::Get),
                    path: Some(String::from("/actuator/health")),
                    headers: BTreeMap::from([(
                        String::from("Accept"),
                        String::from("application/json"),
                    )]),
                    success: Some(TaskRuntimeReadinessHttpSuccessSpec { status: vec![200] }),
                    body: Some(TaskRuntimeReadinessHttpBodySpec {
                        contains: String::from("\"status\":\"UP\""),
                    }),
                    interval: Some(String::from("5s")),
                    timeout: Some(String::from("3s")),
                    retries: Some(5),
                    start_period: Some(String::from("10s")),
                },
                AssistReadinessStyleArg::Http => ServiceReadinessSpec {
                    from: Some(endpoint_from.clone()),
                    endpoint: endpoint.clone(),
                    run: None,
                    probe: None,
                    kind: Some(ServiceReadinessKind::Http),
                    method: Some(TaskRuntimeReadinessHttpMethod::Get),
                    path: Some(String::from("/health")),
                    headers: BTreeMap::new(),
                    success: Some(TaskRuntimeReadinessHttpSuccessSpec { status: vec![200] }),
                    body: None,
                    interval: Some(String::from("5s")),
                    timeout: Some(String::from("3s")),
                    retries: Some(5),
                    start_period: Some(String::from("10s")),
                },
                AssistReadinessStyleArg::Tcp => ServiceReadinessSpec {
                    from: Some(endpoint_from.clone()),
                    endpoint: endpoint.clone(),
                    run: None,
                    probe: None,
                    kind: Some(ServiceReadinessKind::Tcp),
                    method: None,
                    path: None,
                    headers: BTreeMap::new(),
                    success: None,
                    body: None,
                    interval: Some(String::from("5s")),
                    timeout: Some(String::from("3s")),
                    retries: Some(5),
                    start_period: Some(String::from("10s")),
                },
                AssistReadinessStyleArg::ComposeHealth => ServiceReadinessSpec {
                    from: None,
                    endpoint: None,
                    run: None,
                    probe: None,
                    kind: Some(ServiceReadinessKind::ComposeHealth),
                    method: None,
                    path: None,
                    headers: BTreeMap::new(),
                    success: None,
                    body: None,
                    interval: Some(String::from("5s")),
                    timeout: None,
                    retries: Some(5),
                    start_period: Some(String::from("10s")),
                },
                AssistReadinessStyleArg::SystemdActive => ServiceReadinessSpec {
                    from: None,
                    endpoint: None,
                    run: None,
                    probe: None,
                    kind: Some(ServiceReadinessKind::SystemdActive),
                    method: None,
                    path: None,
                    headers: BTreeMap::new(),
                    success: None,
                    body: None,
                    interval: Some(String::from("5s")),
                    timeout: None,
                    retries: Some(5),
                    start_period: Some(String::from("2s")),
                },
            };
            let before_value = existing
                .as_ref()
                .map(serde_yaml::to_value)
                .transpose()
                .map_err(|error| {
                    (
                        format!(
                            "failed to capture existing service readiness for preview: {error}"
                        ),
                        String::from("rerun the assist command after repairing the contract"),
                    )
                })?
                .unwrap_or(YamlValue::Null);
            let after_value = serde_yaml::to_value(&after).map_err(|error| {
                (
                    format!("failed to build service readiness proposal: {error}"),
                    String::from("rerun the assist command after repairing the contract"),
                )
            })?;
            Ok(AssistReadinessProposal {
                subject_kind: "service",
                subject_name: name.clone(),
                endpoint: endpoint.clone(),
                style,
                assumptions: if is_compose_health_readiness_style(style) {
                    vec![
                        format!("service `{name}` is compose-managed"),
                        String::from("structured readiness should follow compose health state"),
                    ]
                } else {
                    match endpoint.as_deref() {
                        Some(endpoint_name) if endpoint_name != endpoint_from => vec![
                            format!("service `{name}` already declares endpoint `{endpoint_name}`"),
                            format!(
                                "structured readiness should anchor to endpoint `{endpoint_name}` in context `{endpoint_from}`"
                            ),
                        ],
                        Some(endpoint_name) => vec![
                            format!("service `{name}` already declares endpoint `{endpoint_name}`"),
                            format!(
                                "structured readiness should anchor to endpoint `{endpoint_name}`"
                            ),
                        ],
                        None => vec![
                            format!("service `{name}` already declares endpoint `{endpoint_from}`"),
                            format!(
                                "structured readiness should anchor to endpoint `{endpoint_from}`"
                            ),
                        ],
                    }
                },
                change_path: format!("services.{name}.readiness"),
                yaml_path: vec![String::from("services"), name, String::from("readiness")],
                before_value,
                after_value,
            })
        }
        Err(error) => Err(error),
    }
}

fn resolve_assist_style_for_task(
    contract: &Contract,
    task: &str,
    listener_name: &str,
    requested_style: Option<AssistReadinessStyleArg>,
) -> Result<AssistReadinessStyleArg, (String, String)> {
    if matches!(
        requested_style,
        Some(AssistReadinessStyleArg::ComposeHealth | AssistReadinessStyleArg::SystemdActive)
    ) {
        return Err((
            String::from(
                "`--style compose-health` and `--style systemd-active` are only valid for `--service` targets",
            ),
            String::from("rerun with `--task` and `--style tcp|http|spring-http`"),
        ));
    }

    let runtime = contract
        .tasks
        .get(task)
        .and_then(|task| task.runtime.as_ref())
        .ok_or_else(|| {
            (
                format!("task `{task}` does not declare a runtime service"),
                String::from(
                    "declare `tasks.<name>.runtime` first, then rerun this assist command",
                ),
            )
        })?;

    let listener = runtime.listeners.get(listener_name).ok_or_else(|| {
        (
            format!(
                "task `{task}` readiness target `{listener_name}` is no longer a declared listener"
            ),
            String::from("repair the runtime listener declaration, then rerun this assist command"),
        )
    })?;
    let inferred = match listener.protocol {
        TaskRuntimeProtocol::Tcp => AssistReadinessStyleArg::Tcp,
        TaskRuntimeProtocol::Http | TaskRuntimeProtocol::Https => AssistReadinessStyleArg::Http,
    };

    if let Some(style) = requested_style {
        let requested_http = is_http_readiness_style(style);
        let listener_http = is_http_readiness_style(inferred);
        if requested_http != listener_http {
            return Err((
                format!(
                    "task `{task}` readiness listener `{listener_name}` uses `protocol: {}`, so `--style {}` does not fit that listener",
                    match listener.protocol {
                        TaskRuntimeProtocol::Http => "http",
                        TaskRuntimeProtocol::Https => "https",
                        TaskRuntimeProtocol::Tcp => "tcp",
                    },
                    assist_readiness_style_name(style)
                ),
                String::from(
                    "rerun with a style that matches the selected listener protocol, or change `runtime.readiness.listener` first",
                ),
            ));
        }
        return Ok(style);
    }

    Ok(inferred)
}

fn resolve_assist_style_for_service(
    existing: Option<&ServiceReadinessSpec>,
    requested_style: Option<AssistReadinessStyleArg>,
    compose_managed: bool,
    systemd_managed: bool,
) -> Result<AssistReadinessStyleArg, (String, String)> {
    if let Some(style) = requested_style {
        if is_compose_health_readiness_style(style) && !compose_managed {
            return Err((
                String::from(
                    "`--style compose-health` requires a compose-managed service (`manager.kind: compose`)",
                ),
                String::from(
                    "set `services.<name>.manager.kind: compose`, or choose `--style tcp` / `--style http`",
                ),
            ));
        }
        if is_systemd_active_readiness_style(style) && !systemd_managed {
            return Err((
                String::from(
                    "`--style systemd-active` requires a host-managed systemd service (`manager.kind: host` with `manager.host.kind: systemd`)",
                ),
                String::from(
                    "set `services.<name>.manager.kind: host` with `manager.host.kind: systemd`, or choose `--style tcp` / `--style http`",
                ),
            ));
        }
        return Ok(style);
    }

    match existing.and_then(ServiceReadinessSpec::structured_kind) {
        Some(ServiceReadinessKind::Tcp) => Ok(AssistReadinessStyleArg::Tcp),
        Some(ServiceReadinessKind::Http) => Ok(AssistReadinessStyleArg::Http),
        Some(ServiceReadinessKind::ComposeHealth) => Ok(AssistReadinessStyleArg::ComposeHealth),
        Some(ServiceReadinessKind::SystemdActive) => Ok(AssistReadinessStyleArg::SystemdActive),
        None => Err((
            String::from(
                "managed service readiness style is ambiguous without an explicit `--style`",
            ),
            String::from(
                "rerun with `--style compose-health` for compose health state, `--style systemd-active` for systemd-managed host services, `--style tcp` for raw port checks, or `--style http` / `spring-http` for HTTP health endpoints",
            ),
        )),
    }
}

fn resolve_assist_readiness_target(
    contract: &Contract,
    task: Option<&str>,
    service: Option<&str>,
    requested_endpoint: Option<&str>,
    requested_style: Option<AssistReadinessStyleArg>,
) -> Result<ResolvedAssistReadinessTarget, (String, String)> {
    if let Some(task) = task {
        if requested_endpoint.is_some() {
            return Err((
                String::from("`--endpoint` is only valid together with `--service`"),
                String::from("rerun with `--service <name> --endpoint <name>`"),
            ));
        }
        let task_spec = contract.tasks.get(task).ok_or_else(|| {
            (
                format!("unknown task `{task}`"),
                String::from("run `ota tasks --use` to inspect runnable task usage"),
            )
        })?;
        let runtime = task_spec.runtime.as_ref().ok_or_else(|| {
            (
                format!("task `{task}` does not declare `runtime`"),
                String::from(
                    "declare a task runtime service first, then rerun this assist command",
                ),
            )
        })?;
        let listener = select_assist_task_listener(task, runtime, requested_style)?;
        return Ok(ResolvedAssistReadinessTarget::Task {
            name: task.to_string(),
            listener,
            existing: runtime.readiness.clone(),
        });
    }

    let service = service.expect("service target required when task is absent");
    let spec = contract.services.get(service).ok_or_else(|| {
        (
            format!("unknown service `{service}`"),
            String::from("run `ota services` to inspect declared managed services"),
        )
    })?;
    let compose_managed = spec
        .manager
        .as_ref()
        .is_some_and(|manager| manager.kind == crate::schema::ServiceManagerKind::Compose);
    let systemd_managed = spec
        .manager
        .as_ref()
        .and_then(|manager| {
            (manager.kind == crate::schema::ServiceManagerKind::Host)
                .then_some(manager.host.as_ref())
                .flatten()
        })
        .is_some_and(|host| host.kind == crate::schema::HostServiceManagerKind::Systemd);
    let wants_compose_health = matches!(
        requested_style,
        Some(AssistReadinessStyleArg::ComposeHealth)
    ) || matches!(
        spec.readiness
            .as_ref()
            .and_then(ServiceReadinessSpec::structured_kind),
        Some(ServiceReadinessKind::ComposeHealth)
    );
    let wants_systemd_active = matches!(
        requested_style,
        Some(AssistReadinessStyleArg::SystemdActive)
    ) || matches!(
        spec.readiness
            .as_ref()
            .and_then(ServiceReadinessSpec::structured_kind),
        Some(ServiceReadinessKind::SystemdActive)
    );
    if (wants_compose_health || wants_systemd_active) && requested_endpoint.is_some() {
        return Err((
            String::from(
                "`--endpoint` does not apply to `--style compose-health` or `--style systemd-active`",
            ),
            String::from("rerun without `--endpoint`, or choose `--style tcp|http|spring-http`"),
        ));
    }
    let endpoint = if wants_compose_health || wants_systemd_active {
        None
    } else if let Some(endpoint) = requested_endpoint {
        let endpoint = endpoint.trim();
        if endpoint.is_empty() {
            return Err((
                String::from("`--endpoint` must not be empty"),
                String::from("rerun with a non-empty endpoint name such as `host`"),
            ));
        }
        if spec.endpoint_named(endpoint).is_none() {
            return Err((
                format!("service `{service}` does not declare endpoint `{endpoint}`"),
                String::from("run `ota services` to inspect declared service endpoints"),
            ));
        }
        Some(endpoint.to_string())
    } else if let Some(existing) = spec
        .readiness
        .as_ref()
        .and_then(|readiness| readiness.endpoint.clone())
    {
        Some(existing)
    } else {
        None
    };
    let from = if wants_compose_health || wants_systemd_active {
        None
    } else if let Some(endpoint_name) = endpoint.as_deref() {
        Some(
            spec.endpoint_named(endpoint_name)
                .expect("selected endpoint must exist")
                .context_name(endpoint_name)
                .to_string(),
        )
    } else if let Some(existing) = spec
        .readiness
        .as_ref()
        .and_then(|readiness| readiness.from.clone())
    {
        Some(existing)
    } else if spec.has_endpoint_for_context("host") && spec.endpoint_count_for_context("host") == 1
    {
        Some(String::from("host"))
    } else if spec.endpoints.len() == 1 {
        Some(
            spec.endpoint_named(spec.sole_endpoint_name().expect("single endpoint"))
                .and_then(|endpoint| endpoint.context.clone())
                .unwrap_or_else(|| {
                    spec.sole_endpoint_name()
                        .expect("single endpoint")
                        .to_string()
                }),
        )
    } else {
        return Err((
            format!(
                "service `{service}` has multiple endpoints; assist cannot pick readiness.from safely"
            ),
            String::from(
                "rerun with `--endpoint <name>` to pick the service projection explicitly",
            ),
        ));
    };
    Ok(ResolvedAssistReadinessTarget::Service {
        name: service.to_string(),
        from,
        endpoint,
        compose_managed,
        systemd_managed,
        existing: spec.readiness.clone(),
    })
}

fn select_assist_task_listener(
    task: &str,
    runtime: &crate::schema::TaskRuntimeSpec,
    requested_style: Option<AssistReadinessStyleArg>,
) -> Result<String, (String, String)> {
    if let Some(existing) = runtime
        .readiness
        .as_ref()
        .and_then(|readiness| readiness.listener.clone())
    {
        return Ok(existing);
    }

    let desired_http = matches!(
        requested_style,
        Some(AssistReadinessStyleArg::SpringHttp | AssistReadinessStyleArg::Http)
    );
    let desired_tcp = matches!(requested_style, Some(AssistReadinessStyleArg::Tcp));

    if let Some(listener) = runtime.listeners.get("http") {
        if !desired_tcp
            && matches!(
                listener.protocol,
                TaskRuntimeProtocol::Http | TaskRuntimeProtocol::Https
            )
        {
            return Ok(String::from("http"));
        }
    }

    let matching = runtime
        .listeners
        .iter()
        .filter(|(_, listener)| {
            if desired_http {
                matches!(
                    listener.protocol,
                    TaskRuntimeProtocol::Http | TaskRuntimeProtocol::Https
                )
            } else if desired_tcp {
                matches!(listener.protocol, TaskRuntimeProtocol::Tcp)
            } else {
                true
            }
        })
        .map(|(name, _)| name.clone())
        .collect::<Vec<_>>();

    if matching.len() == 1 {
        return Ok(matching[0].clone());
    }

    Err((
        format!("task `{task}` does not expose one unambiguous listener for readiness declaration"),
        String::from(
            "declare `runtime.readiness.listener` manually or rerun with a narrower style",
        ),
    ))
}

fn compact_yaml_inline(value: &YamlValue) -> String {
    if value.is_null() {
        return String::from("<absent>");
    }

    serde_yaml::to_string(value)
        .unwrap_or_else(|_| String::from("<unavailable>"))
        .trim()
        .replace('\n', " ")
}

fn merge_yaml_value(root: &mut YamlValue, override_value: YamlValue) {
    match (root, override_value) {
        (YamlValue::Mapping(root_map), YamlValue::Mapping(override_map)) => {
            for (key, override_entry) in override_map {
                match root_map.get_mut(&key) {
                    Some(root_entry) => merge_yaml_value(root_entry, override_entry),
                    None => {
                        root_map.insert(key, override_entry);
                    }
                }
            }
        }
        (root_value, override_value) => {
            *root_value = override_value;
        }
    }
}

fn get_yaml_path_value(document: &YamlValue, path: &[&str]) -> Option<YamlValue> {
    let mut current = document;
    for segment in path {
        let mapping = current.as_mapping()?;
        current = mapping.get(YamlValue::String((*segment).to_string()))?;
    }
    Some(current.clone())
}

fn set_yaml_path(document: &mut YamlValue, path: &[&str], value: YamlValue) {
    debug_assert!(!path.is_empty());
    let mut current = document;
    for segment in &path[..path.len() - 1] {
        if !matches!(current, YamlValue::Mapping(_)) {
            *current = YamlValue::Mapping(Mapping::new());
        }
        let mapping = current.as_mapping_mut().expect("mapping");
        current = mapping
            .entry(YamlValue::String((*segment).to_string()))
            .or_insert_with(|| YamlValue::Mapping(Mapping::new()));
    }
    if !matches!(current, YamlValue::Mapping(_)) {
        *current = YamlValue::Mapping(Mapping::new());
    }
    current
        .as_mapping_mut()
        .expect("mapping")
        .insert(YamlValue::String(path[path.len() - 1].to_string()), value);
}

fn remove_yaml_path(document: &mut YamlValue, path: &[&str]) {
    debug_assert!(!path.is_empty());
    if path.len() == 1 {
        if let Some(mapping) = document.as_mapping_mut() {
            mapping.remove(YamlValue::String(path[0].to_string()));
        }
        return;
    }

    let mut current = document;
    for segment in &path[..path.len() - 1] {
        let Some(mapping) = current.as_mapping_mut() else {
            return;
        };
        let Some(next) = mapping.get_mut(YamlValue::String((*segment).to_string())) else {
            return;
        };
        current = next;
    }
    if let Some(mapping) = current.as_mapping_mut() {
        mapping.remove(YamlValue::String(path[path.len() - 1].to_string()));
    }
}

fn validate_assist_contract_update(
    resolved_path: &Path,
    member: Option<&str>,
    target_contract_path: &Path,
    yaml: &str,
) -> Result<(), String> {
    match member {
        Some(member) => load_contract_for_member_with_contents(resolved_path, member, Some(yaml))
            .map(|(contract, _)| contract)
            .map_err(|error| error.to_string())
            .and_then(|contract| {
                validate_contract_with_path(&contract, Some(target_contract_path))
                    .map_err(|error| error.to_string())
            }),
        None => parse_contract_str(target_contract_path, yaml)
            .map_err(|error| error.to_string())
            .and_then(|contract| {
                validate_contract_with_path(&contract, Some(target_contract_path))
                    .map_err(|error| error.to_string())
            }),
    }
}

