fn build_env_report(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    task_name: Option<&str>,
) -> Result<EnvReport, String> {
    build_env_report_with_overrides(
        contract,
        contract_path,
        workflow_name,
        task_name,
        ExecutionOverrides::default(),
    )
}

fn build_env_report_with_overrides(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    task_name: Option<&str>,
    overrides: ExecutionOverrides,
) -> Result<EnvReport, String> {
    let adjusted_contract =
        contract_adjusted_for_selected_workflow_env_profile(contract, workflow_name);
    let contract = adjusted_contract.as_ref().unwrap_or(contract);
    let (task_env, explicit_task_env) = match task_name {
        Some(task_name) => {
            let Some(task) = contract.tasks.get(task_name) else {
                return Err(RunError::UnknownTask {
                    task: task_name.to_string(),
                }
                .to_string());
            };
            let effective = effective_task_execution(contract, task_name, overrides);
            let backend = effective.backend;
            let target_os = crate::runner::target_os_for_declared_backend(
                backend,
                effective.container,
                current_os(),
            );
            let planned_env_files =
                planned_env_file_outputs_for_task_closure(contract, task_name, backend);
            ensure_task_env_files_ready_with_planned_outputs(
                task_name,
                task,
                backend,
                target_os,
                contract_working_dir(contract_path),
                &planned_env_files,
            )
            .map_err(|error| error.to_string())?;
            ensure_task_adapter_inputs_ready(
                task_name,
                task,
                backend,
                contract_working_dir(contract_path),
            )
            .map_err(|error| error.to_string())?;
            (
                effective_task_env_for_selection(
                    contract,
                    task_name,
                    overrides,
                    contract_working_dir(contract_path),
                ),
                Some(&task.env),
            )
        }
        None => (None, None),
    };

    let policy_env = load_policy_env_overlay(contract_path).map_err(|error| error.to_string())?;
    let declared_sources = load_declared_env_sources(contract, contract_path);
    let selected_required_env_names = match (task_name, workflow_name) {
        (Some(task_name), _) => Some(contract.task_required_env_names(task_name)),
        (None, Some(_workflow_name)) => {
            let names = contract.selected_workflow_required_env_names(workflow_name);
            (!names.is_empty()).then_some(names)
        }
        (None, None) => None,
    };
    let mut env = Vec::new();
    let mut sources = Vec::new();
    let rendered_artifacts = selected_workflow_env_profile_rendered_artifact_entries(
        contract,
        contract_path,
        workflow_name,
    );
    let mut contract_resolved_count = 0usize;
    let mut missing_count = 0usize;
    let mut invalid_count = 0usize;
    let mut source_issue_count = 0usize;

    for source in &declared_sources {
        let status = env_source_status_from_declared(source.status);
        let detail = source.details.clone().or_else(|| match source.status {
            DeclaredEnvSourceStatus::MissingRequired => {
                Some(String::from("declared source missing"))
            }
            _ => None,
        });
        let next = env_source_next_step(source, workflow_name, task_name);
        let issue_count = usize::from(env_source_status_counts_as_issue(status));
        source_issue_count += issue_count;
        sources.push(EnvSourceEntry {
            kind: source.kind.to_string(),
            path: source.path.clone(),
            label: source.label(),
            must_exist: source.must_exist,
            status,
            detail,
            next,
        });
    }

    for (name, requirement) in &contract.env {
        let task_override = task_env.as_ref().and_then(|task_env| task_env.get(name));
        let required_for_selected_path = requirement.required
            || selected_required_env_names
                .as_ref()
                .is_some_and(|names| names.contains(name));

        if let Some(value) = task_override {
            let source = if explicit_task_env.is_some_and(|task_env| task_env.contains_key(name)) {
                "task"
            } else {
                "execution"
            };
            env.push(build_task_overridden_env_entry(
                name,
                requirement,
                required_for_selected_path,
                value,
                source,
            ));
            contract_resolved_count += 1;
            continue;
        }

        let mut resolved = policy_env
            .values
            .get(name)
            .cloned()
            .map(|value| (policy_env.label.clone(), value))
            .or_else(|| {
                std::env::var(name)
                    .ok()
                    .map(|value| (String::from("process"), value))
            })
            .or_else(|| {
                resolve_declared_env_source_value(name, &declared_sources)
                    .map(|(value, source)| (env_resolution_source_label(&source), value))
            })
            .or_else(|| {
                requirement
                    .default
                    .clone()
                    .map(|value| (String::from("default"), value))
            });

        match resolved.as_mut() {
            Some((source, value)) => {
                if name == "PATH" {
                    *value = compose_env_path_value(name, value.as_str(), requirement)?;
                }

                if !requirement.allowed.is_empty()
                    && !requirement.allowed.iter().any(|allowed| allowed == value)
                {
                    invalid_count += 1;
                    let (source_kind, source_path, source_status, source_label) =
                        env_entry_source_metadata(source.as_str(), &declared_sources);
                    env.push(EnvEntry {
                        name: name.clone(),
                        kind: EnvEntryKind::Contract,
                        required: required_for_selected_path,
                        default: requirement.default.clone(),
                        allowed: requirement.allowed.clone(),
                        value: Some(display_env_value(value.as_str(), requirement.secret)),
                        source: source.clone(),
                        source_kind,
                        source_path,
                        source_status,
                        source_label,
                        status: EnvEntryStatus::Invalid,
                        next: Some(env_next_for_invalid(
                            name,
                            workflow_name,
                            task_name,
                            &requirement.allowed,
                        )),
                    });
                } else {
                    contract_resolved_count += 1;
                    let (source_kind, source_path, source_status, source_label) =
                        env_entry_source_metadata(source.as_str(), &declared_sources);
                    env.push(EnvEntry {
                        name: name.clone(),
                        kind: EnvEntryKind::Contract,
                        required: required_for_selected_path,
                        default: requirement.default.clone(),
                        allowed: requirement.allowed.clone(),
                        value: Some(display_env_value(value.as_str(), requirement.secret)),
                        source: source.clone(),
                        source_kind,
                        source_path,
                        source_status,
                        source_label,
                        status: EnvEntryStatus::Resolved,
                        next: None,
                    });
                }
            }
            None if required_for_selected_path => {
                missing_count += 1;
                env.push(EnvEntry {
                    name: name.clone(),
                    kind: EnvEntryKind::Contract,
                    required: true,
                    default: requirement.default.clone(),
                    allowed: requirement.allowed.clone(),
                    value: None,
                    source: String::from("missing"),
                    source_kind: None,
                    source_path: None,
                    source_status: None,
                    source_label: None,
                    status: EnvEntryStatus::Missing,
                    next: Some(env_next_for_missing(name, workflow_name, task_name)),
                });
            }
            None => {
                env.push(EnvEntry {
                    name: name.clone(),
                    kind: EnvEntryKind::Contract,
                    required: false,
                    default: requirement.default.clone(),
                    allowed: requirement.allowed.clone(),
                    value: None,
                    source: String::from("missing"),
                    source_kind: None,
                    source_path: None,
                    source_status: None,
                    source_label: None,
                    status: EnvEntryStatus::Optional,
                    next: None,
                });
            }
        }
    }

    if let Some(task_env) = task_env.as_ref() {
        for (name, value) in task_env {
            if contract.env.contains_key(name) {
                continue;
            }
            let source = if explicit_task_env.is_some_and(|raw_env| raw_env.contains_key(name)) {
                String::from("task")
            } else {
                String::from("execution")
            };
            env.push(EnvEntry {
                name: name.clone(),
                kind: EnvEntryKind::Task,
                required: false,
                default: None,
                allowed: Vec::new(),
                value: Some(value.clone()),
                source,
                source_kind: None,
                source_path: None,
                source_status: None,
                source_label: None,
                status: EnvEntryStatus::Task,
                next: None,
            });
        }
    }

    let task_count = env
        .iter()
        .filter(|entry| matches!(entry.kind, EnvEntryKind::Task))
        .count();

    Ok(EnvReport {
        ok: missing_count == 0 && invalid_count == 0 && source_issue_count == 0,
        workflow: workflow_name.map(ToString::to_string),
        profile: contract
            .selected_workflow_env_profile_name(workflow_name)
            .map(ToString::to_string),
        summary: EnvSummary {
            contract_count: contract.env.len(),
            source_count: declared_sources.len(),
            source_issue_count,
            task_count,
            resolved_count: contract_resolved_count,
            missing_count,
            invalid_count,
        },
        sources,
        rendered_artifacts,
        env,
    })
}

fn env_source_status_from_declared(status: DeclaredEnvSourceStatus) -> EnvSourceStatus {
    match status {
        DeclaredEnvSourceStatus::Loaded => EnvSourceStatus::Loaded,
        DeclaredEnvSourceStatus::MissingOptional => EnvSourceStatus::MissingOptional,
        DeclaredEnvSourceStatus::MissingRequired => EnvSourceStatus::MissingRequired,
        DeclaredEnvSourceStatus::ParseFailed => EnvSourceStatus::ParseFailed,
        DeclaredEnvSourceStatus::InvalidStructure => EnvSourceStatus::InvalidStructure,
        DeclaredEnvSourceStatus::Collision => EnvSourceStatus::Collision,
    }
}

fn env_source_status_counts_as_issue(status: EnvSourceStatus) -> bool {
    !matches!(
        status,
        EnvSourceStatus::Loaded | EnvSourceStatus::MissingOptional
    )
}

fn env_source_next_step(
    source: &LoadedDeclaredEnvSource,
    workflow_name: Option<&str>,
    task_name: Option<&str>,
) -> Option<String> {
    match source.status {
        DeclaredEnvSourceStatus::Loaded | DeclaredEnvSourceStatus::MissingOptional => None,
        DeclaredEnvSourceStatus::MissingRequired => Some(format!(
            "create `{}` or remove `must_exist: true`, then rerun {}",
            source.path,
            env_rerun_command(workflow_name, task_name)
        )),
        DeclaredEnvSourceStatus::ParseFailed
        | DeclaredEnvSourceStatus::InvalidStructure
        | DeclaredEnvSourceStatus::Collision => Some(format!(
            "fix `{}` so ota can load declared source `{}`, then rerun {}",
            source.path,
            source.label(),
            env_rerun_command(workflow_name, task_name)
        )),
    }
}

fn env_rerun_command(workflow_name: Option<&str>, task_name: Option<&str>) -> String {
    let mut command = String::from("`ota env");
    if let Some(workflow_name) = workflow_name {
        command.push_str(" --workflow ");
        command.push_str(workflow_name);
    }
    if let Some(task_name) = task_name {
        command.push_str(" --task ");
        command.push_str(task_name);
    }
    command.push('`');
    command
}

fn env_entry_source_metadata(
    source: &str,
    declared_sources: &[LoadedDeclaredEnvSource],
) -> (
    Option<String>,
    Option<String>,
    Option<EnvSourceStatus>,
    Option<String>,
) {
    let Some(declared) = declared_sources
        .iter()
        .find(|candidate| candidate.label() == source)
    else {
        return (None, None, None, None);
    };
    (
        Some(declared.kind.to_string()),
        Some(declared.path.clone()),
        Some(env_source_status_from_declared(declared.status)),
        Some(declared.label()),
    )
}

fn build_task_overridden_env_entry(
    name: &str,
    requirement: &EnvRequirement,
    required: bool,
    value: &str,
    source: &str,
) -> EnvEntry {
    EnvEntry {
        name: name.to_string(),
        kind: EnvEntryKind::Contract,
        required,
        default: requirement.default.clone(),
        allowed: requirement.allowed.clone(),
        value: Some(display_env_value(value, requirement.secret)),
        source: String::from(source),
        source_kind: None,
        source_path: None,
        source_status: None,
        source_label: None,
        status: EnvEntryStatus::Resolved,
        next: None,
    }
}

fn display_env_value(value: &str, secret: bool) -> String {
    if secret {
        String::from("<redacted>")
    } else {
        value.to_string()
    }
}

fn env_next_for_missing(
    name: &str,
    workflow_name: Option<&str>,
    task_name: Option<&str>,
) -> String {
    match task_name {
        Some(task_name) => format!(
            "set {name} in policy env, the shell, a declared env source, or task env for `{task_name}`, then rerun {}",
            env_rerun_command(workflow_name, Some(task_name))
        ),
        None => format!(
            "set {name} in policy env, the shell, or a declared env source, then rerun {}",
            env_rerun_command(workflow_name, None)
        ),
    }
}

fn env_next_for_invalid(
    name: &str,
    workflow_name: Option<&str>,
    task_name: Option<&str>,
    allowed: &[String],
) -> String {
    format!(
        "set {name} to one of: {}, then rerun {}",
        allowed.join(", "),
        env_rerun_command(workflow_name, task_name)
    )
}

fn compose_env_path_value(
    name: &str,
    base: &str,
    requirement: &EnvRequirement,
) -> Result<String, String> {
    if requirement.prepend.is_empty() && requirement.append.is_empty() {
        return Ok(base.to_string());
    }

    let mut entries = Vec::with_capacity(1 + requirement.prepend.len() + requirement.append.len());
    entries.extend(requirement.prepend.iter().cloned().map(OsString::from));
    entries.extend(std::env::split_paths(base).map(|path| path.into_os_string()));
    entries.extend(requirement.append.iter().cloned().map(OsString::from));

    std::env::join_paths(entries)
        .map(|joined| joined.to_string_lossy().into_owned())
        .map_err(|source| {
            format!("could not compose environment variable `{name}` as a PATH: {source}")
        })
}

fn render_env_text(path: &str, task: Option<&str>, report: &EnvReport) -> String {
    let mut stdout = format!(
        "{}\n\n{}",
        format_command_header("ENV", path),
        render_readiness_status(report.ok)
    );
    if let Some(workflow) = report.workflow.as_deref() {
        stdout.push_str(&format!("\n\n{} {}", paint("Workflow:", "1"), workflow));
    }
    if let Some(profile) = report.profile.as_deref() {
        stdout.push_str(&format!("\n{} {}", paint("Profile:", "1"), profile));
    }
    if let Some(task) = task {
        stdout.push_str(&format!("\n\n{} {}", paint("Task:", "1"), task));
    }
    stdout.push_str(&format!("\n\n{}", paint_section_title("Overview")));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Contract env:"),
        report.summary.contract_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Declared sources:"),
        report.summary.source_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Source issues:"),
        report.summary.source_issue_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Task env:"),
        report.summary.task_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Resolved:"),
        report.summary.resolved_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Missing:"),
        report.summary.missing_count
    ));
    stdout.push_str(&format!(
        "\n{} {} {}",
        summary_bullet(),
        paint_key("Invalid:"),
        report.summary.invalid_count
    ));

    stdout.push_str("\n\n");
    stdout.push_str(&paint_section_title("Contract env"));
    if report.summary.contract_count == 0 {
        stdout.push_str(&format!("\n{} none", info_bullet()));
    } else {
        for entry in report
            .env
            .iter()
            .filter(|entry| matches!(entry.kind, EnvEntryKind::Contract))
        {
            stdout.push_str(&render_env_entry_text(entry));
        }
    }

    if !report.sources.is_empty() {
        stdout.push_str(&format!(
            "\n\n{}",
            paint_section_title("Declared env sources")
        ));
        for source in &report.sources {
            stdout.push_str(&render_env_source_text(source));
        }
    }

    if !report.rendered_artifacts.is_empty() {
        stdout.push_str(&format!(
            "\n\n{}",
            paint_section_title("Rendered env artifacts")
        ));
        for artifact in &report.rendered_artifacts {
            stdout.push_str(&render_env_rendered_artifact_text(artifact));
        }
    }

    if task.is_some() && report.summary.task_count > 0 {
        stdout.push_str(&format!("\n\n{}", paint_section_title("Task env")));
        for entry in report
            .env
            .iter()
            .filter(|entry| matches!(entry.kind, EnvEntryKind::Task))
        {
            stdout.push_str(&render_env_entry_text(entry));
        }
    }

    stdout
}

fn render_env_entry_text(entry: &EnvEntry) -> String {
    let mut output = String::from("\n\n");
    output.push_str(&format!("{} {}", list_bullet(), paint(&entry.name, "1")));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Kind:"),
        render_env_kind(entry.kind)
    ));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Required:"),
        if entry.required { "true" } else { "false" }
    ));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Value:"),
        entry.value.as_deref().unwrap_or("-")
    ));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Source:"),
        render_env_entry_provenance(entry)
    ));
    if let Some(source_kind) = entry.source_kind.as_deref() {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Source Kind:"),
            source_kind
        ));
    }
    if let Some(source_path) = entry.source_path.as_deref() {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Source Path:"),
            source_path
        ));
    }
    if let Some(source_status) = entry.source_status {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Source Status:"),
            render_env_source_status(source_status)
        ));
    }
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Status:"),
        render_env_status(entry.status)
    ));
    if !entry.allowed.is_empty() {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Allowed:"),
            entry.allowed.join(", ")
        ));
    }
    if let Some(default) = entry.default.as_deref() {
        output.push_str(&format!("\n  {} {}", paint_key("Default:"), default));
    }
    if let Some(next) = entry.next.as_deref() {
        output.push_str(&format!("\n  {} {}", paint_key("Next:"), next));
    }
    output
}

fn render_env_source_text(source: &EnvSourceEntry) -> String {
    let mut output = String::from("\n\n");
    output.push_str(&format!(
        "{} {}:{}",
        list_bullet(),
        paint(&source.kind, "1"),
        source.path
    ));
    output.push_str(&format!("\n  {} {}", paint_key("Label:"), source.label));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Must Exist:"),
        if source.must_exist { "true" } else { "false" }
    ));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Status:"),
        render_env_source_status(source.status)
    ));
    if let Some(detail) = &source.detail {
        output.push_str(&format!("\n  {} {}", paint_key("Detail:"), detail));
    }
    if let Some(next) = &source.next {
        output.push_str(&format!("\n  {} {}", paint_key("Next:"), next));
    }
    output
}

fn render_env_rendered_artifact_text(artifact: &EnvRenderedArtifactEntry) -> String {
    let mut output = String::from("\n\n");
    output.push_str(&format!("{} {}", list_bullet(), paint(&artifact.path, "1")));
    output.push_str(&format!("\n  {} {}", paint_key("Kind:"), artifact.kind));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Exists:"),
        if artifact.exists { "true" } else { "false" }
    ));
    if let Some(profile) = artifact.profile.as_deref() {
        output.push_str(&format!("\n  {} {}", paint_key("Profile:"), profile));
    }
    if !artifact.includes.is_empty() {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Includes:"),
            artifact.includes.join(", ")
        ));
    }
    if !artifact.sources.is_empty() {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Sources:"),
            artifact.sources.join(", ")
        ));
    }
    if !artifact.consumers.is_empty() {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Consumers:"),
            artifact.consumers.join(", ")
        ));
    }
    output
}

fn render_env_source_status(status: EnvSourceStatus) -> &'static str {
    match status {
        EnvSourceStatus::Loaded => "loaded",
        EnvSourceStatus::MissingOptional => "missing optional",
        EnvSourceStatus::MissingRequired => "missing required",
        EnvSourceStatus::ParseFailed => "parse failed",
        EnvSourceStatus::InvalidStructure => "invalid structure",
        EnvSourceStatus::Collision => "collision",
    }
}

fn render_env_entry_provenance(entry: &EnvEntry) -> &'static str {
    if entry.source_kind.is_some() {
        "source file"
    } else {
        match entry.source.as_str() {
            "process" => "existing env",
            "default" => "default",
            "task" => "task env",
            "execution" => "execution env",
            "missing" => "missing",
            _ if entry.source.contains("policy") => "policy",
            _ => "other",
        }
    }
}

fn render_env_kind(kind: EnvEntryKind) -> &'static str {
    match kind {
        EnvEntryKind::Contract => "contract",
        EnvEntryKind::Task => "task",
    }
}

fn render_env_status(status: EnvEntryStatus) -> &'static str {
    match status {
        EnvEntryStatus::Resolved => "resolved",
        EnvEntryStatus::Missing => "missing",
        EnvEntryStatus::Optional => "optional",
        EnvEntryStatus::Invalid => "invalid",
        EnvEntryStatus::Task => "task",
    }
}

pub fn diff(base: &Path, target: &Path, format: OutputFormat, debug: bool) -> CommandOutput {
    let base_input = base.display().to_string();
    let target_input = target.display().to_string();

    let base_path = match resolve_diff_contract_path(base) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => CommandOutput::failure(error.clone()),
                    OutputFormat::Json => CommandOutput::failure(to_json(&DiffFailure {
                        ok: false,
                        base: &base_input,
                        target: &target_input,
                        base_input: None,
                        target_input: None,
                        error: &error,
                    })),
                },
                debug,
                vec![String::from("DEBUG command=diff")],
            );
        }
    };
    let target_path = match resolve_diff_contract_path(target) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => CommandOutput::failure(error.clone()),
                    OutputFormat::Json => CommandOutput::failure(to_json(&DiffFailure {
                        ok: false,
                        base: &base_input,
                        target: &target_input,
                        base_input: None,
                        target_input: None,
                        error: &error,
                    })),
                },
                debug,
                vec![String::from("DEBUG command=diff")],
            );
        }
    };

    let base_display = base_path.display().to_string();
    let target_display = target_path.display().to_string();
    let debug_lines = vec![
        String::from("DEBUG command=diff"),
        format!("DEBUG base_path={base_display}"),
        format!("DEBUG target_path={target_display}"),
    ];

    finalize_debug(
        match (
            load_diff_contract(&base_path),
            load_diff_contract(&target_path),
        ) {
            (Ok(base_contract), Ok(target_contract)) => {
                let changes =
                    collect_diff_changes(&base_contract.semantic, &target_contract.semantic);
                let summary = summarize_diff_changes(&changes);
                let base_snapshot_display = base_contract
                    .snapshot_path
                    .as_ref()
                    .map(|path| path.to_string_lossy().into_owned());
                let target_snapshot_display = target_contract
                    .snapshot_path
                    .as_ref()
                    .map(|path| path.to_string_lossy().into_owned());
                match format {
                    OutputFormat::Text => {
                        let mut stdout = format!(
                            "{}\n\n{}",
                            format_command_header(
                                "DIFF",
                                &format!(
                                    "{} -> {}",
                                    compact_contract_path(&base_path),
                                    compact_contract_path(&target_path)
                                )
                            ),
                            render_diff_status_word(changes.is_empty())
                        );
                        stdout.push_str("\n\n");
                        stdout.push_str(&paint_section_title("Inputs"));
                        stdout.push_str(&format!(
                            "\n{} {} {}",
                            summary_bullet(),
                            paint_key("Base:"),
                            compact_path(&base_path, ".")
                        ));
                        stdout.push_str(&format!(
                            "\n{} {} {}",
                            summary_bullet(),
                            paint_key("Base kind:"),
                            diff_input_kind_label(base_contract.kind)
                        ));
                        if let Some(snapshot_path) = base_contract.snapshot_path.as_ref() {
                            stdout.push_str(&format!(
                                "\n{} {} {}",
                                summary_bullet(),
                                paint_key("Base snapshot:"),
                                compact_path(snapshot_path, ".")
                            ));
                        }
                        stdout.push_str(&format!(
                            "\n{} {} {}",
                            summary_bullet(),
                            paint_key("Target:"),
                            compact_path(&target_path, ".")
                        ));
                        stdout.push_str(&format!(
                            "\n{} {} {}",
                            summary_bullet(),
                            paint_key("Target kind:"),
                            diff_input_kind_label(target_contract.kind)
                        ));
                        if let Some(snapshot_path) = target_contract.snapshot_path.as_ref() {
                            stdout.push_str(&format!(
                                "\n{} {} {}",
                                summary_bullet(),
                                paint_key("Target snapshot:"),
                                compact_path(snapshot_path, ".")
                            ));
                        }
                        if changes.is_empty() {
                            stdout.push_str("\n\nno semantic differences");
                        } else {
                            render_diff_section(
                                &mut stdout,
                                "Added",
                                changes.iter().filter(|change| change.status == "add"),
                            );
                            render_diff_section(
                                &mut stdout,
                                "Removed",
                                changes.iter().filter(|change| change.status == "remove"),
                            );
                            render_diff_section(
                                &mut stdout,
                                "Changed",
                                changes.iter().filter(|change| change.status == "change"),
                            );
                        }
                        stdout.push_str(&render_diff_summary_text(&summary));
                        CommandOutput {
                            stdout,
                            stderr: None,
                            exit_code: 0,
                        }
                    }
                    OutputFormat::Json => CommandOutput {
                        stdout: to_json(&DiffSuccess {
                            ok: changes.is_empty(),
                            base: &base_display,
                            target: &target_display,
                            base_input: crate::output::DiffInputSide {
                                path: &base_display,
                                kind: base_contract.kind,
                                snapshot_path: base_snapshot_display.as_deref(),
                            },
                            target_input: crate::output::DiffInputSide {
                                path: &target_display,
                                kind: target_contract.kind,
                                snapshot_path: target_snapshot_display.as_deref(),
                            },
                            summary,
                            changes: &changes,
                        }),
                        stderr: None,
                        exit_code: 0,
                    },
                }
            }
            (Err(error), _) | (_, Err(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(error),
                OutputFormat::Json => CommandOutput::failure(to_json(&DiffFailure {
                    ok: false,
                    base: &base_display,
                    target: &target_display,
                    base_input: None,
                    target_input: None,
                    error: &error,
                })),
            },
        },
        debug,
        debug_lines,
    )
}

fn listed_task_summaries<'a>(
    contract: &'a Contract,
    include_internal: bool,
    filters: &TasksListFilters,
) -> Vec<TaskSummary<'a>> {
    let mut tasks = Vec::new();
    for (name, task) in &contract.tasks {
        if !include_internal && task.internal {
            continue;
        }
        if !task_matches_tasks_filters(contract, name, task, filters) {
            continue;
        }
        tasks.push(TaskSummary::from_spec(name, task, current_os(), contract));
    }

    let visible_task_names = tasks
        .iter()
        .map(|task| task.name.to_string())
        .collect::<BTreeSet<_>>();
    for task in &mut tasks {
        task.retain_visible_task_relationships(&visible_task_names);
    }

    tasks
}

#[derive(Clone, Copy)]
enum TasksSafetyFilter {
    Safe,
    Unsafe,
}

#[derive(Clone, Copy, Default)]
struct TasksListFilters {
    safety: Option<TasksSafetyFilter>,
    via_backend: Option<crate::schema::Backend>,
}

fn task_is_effectively_safe(
    contract: &Contract,
    task_name: &str,
    _task: &crate::schema::TaskSpec,
) -> bool {
    task_effective_safety(contract, task_name).effective_safe
}

fn task_supports_backend(
    contract: &Contract,
    task: &crate::schema::TaskSpec,
    backend: crate::schema::Backend,
) -> bool {
    task.supports_execution_backend(contract.execution.as_ref(), backend, current_os())
}

fn task_matches_tasks_filters(
    contract: &Contract,
    task_name: &str,
    task: &crate::schema::TaskSpec,
    filters: &TasksListFilters,
) -> bool {
    if let Some(safety) = filters.safety {
        let is_safe = task_is_effectively_safe(contract, task_name, task);
        match safety {
            TasksSafetyFilter::Safe if !is_safe => return false,
            TasksSafetyFilter::Unsafe if is_safe => return false,
            _ => {}
        }
    }

    if let Some(backend) = filters.via_backend
        && !task_supports_backend(contract, task, backend)
    {
        return false;
    }

    true
}

fn listed_agent_summary<'a>(
    contract: &'a Contract,
    include_internal: bool,
    tasks: &[TaskSummary<'a>],
) -> Option<AgentSummary<'a>> {
    let mut agent = contract
        .agent
        .as_ref()
        .and_then(AgentSummary::from_config)?;
    if !include_internal {
        let visible_task_names = tasks
            .iter()
            .map(|task| task.name.to_string())
            .collect::<BTreeSet<_>>();
        agent.retain_visible_tasks(&visible_task_names);
    }
    (!agent.is_empty()).then_some(agent)
}

fn agent_boundary_summary(contract: &Contract) -> Option<AgentSummary<'_>> {
    let agent = contract
        .agent
        .as_ref()
        .and_then(AgentSummary::from_config)?;
    (!agent.is_empty()).then_some(agent)
}

fn merge_network_kind(
    current: Option<crate::schema::TaskNetworkEffectKind>,
    next: crate::schema::TaskNetworkEffectKind,
) -> Option<crate::schema::TaskNetworkEffectKind> {
    Some(match (current, next) {
        (Some(crate::schema::TaskNetworkEffectKind::Broad), _) => {
            crate::schema::TaskNetworkEffectKind::Broad
        }
        (_, crate::schema::TaskNetworkEffectKind::Broad) => {
            crate::schema::TaskNetworkEffectKind::Broad
        }
        (Some(crate::schema::TaskNetworkEffectKind::ToolBootstrap), _)
        | (_, crate::schema::TaskNetworkEffectKind::ToolBootstrap) => {
            crate::schema::TaskNetworkEffectKind::ToolBootstrap
        }
        (Some(crate::schema::TaskNetworkEffectKind::ContainerImageHydration), _)
        | (_, crate::schema::TaskNetworkEffectKind::ContainerImageHydration) => {
            crate::schema::TaskNetworkEffectKind::ContainerImageHydration
        }
        (Some(crate::schema::TaskNetworkEffectKind::IntegrationTest), _)
        | (_, crate::schema::TaskNetworkEffectKind::IntegrationTest) => {
            crate::schema::TaskNetworkEffectKind::IntegrationTest
        }
        (Some(crate::schema::TaskNetworkEffectKind::ServiceReadiness), _)
        | (_, crate::schema::TaskNetworkEffectKind::ServiceReadiness) => {
            crate::schema::TaskNetworkEffectKind::ServiceReadiness
        }
        _ => crate::schema::TaskNetworkEffectKind::DependencyHydration,
    })
}

fn collect_task_closure_effects_summary(
    contract: &Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
) -> crate::output::TaskEffectsSummary {
    let mut summary = crate::output::TaskEffectsSummary::default();
    let mut seen_declared = BTreeSet::new();
    let mut seen_writes = BTreeSet::new();
    let mut seen_workspace_writes = BTreeSet::new();
    let mut seen_adapter_state = BTreeSet::new();
    let mut seen_external_state = BTreeSet::new();

    for reachable in collect_reachable_task_names_for_visibility(contract, task_name, overrides) {
        let Some(task) = contract.tasks.get(reachable.as_str()) else {
            continue;
        };
        if task.effects.network {
            summary.network = true;
        }
        if let Some(kind) = task.effects.effective_network_kind() {
            summary.network_kind = merge_network_kind(summary.network_kind, kind);
        }
        for effect in &task.effects.declared {
            if seen_declared.insert(effect.clone()) {
                summary.declared.push(effect.clone());
            }
        }
        for path in &task.effects.writes {
            if seen_writes.insert(path.clone()) {
                summary.writes.push(path.clone());
            }
        }
        for path in &task.effects.workspace_writes {
            if seen_workspace_writes.insert(path.clone()) {
                summary.workspace_writes.push(path.clone());
            }
        }
        for value in &task.effects.adapter_state {
            if seen_adapter_state.insert(value.clone()) {
                summary.adapter_state.push(value.clone());
            }
        }
        for value in &task.effects.external_state {
            if seen_external_state.insert(value.clone()) {
                summary.external_state.push(value.clone());
            }
        }
    }

    summary
}

fn harness_preflight_for_task(
    task: &TaskSummary<'_>,
    refusal: Option<&AgentExecutionRefusal>,
) -> crate::output::GovernancePreflightEvaluation {
    let (crossing_required, crossing_classification, crossing_boundary_family) =
        crossing_preflight_posture(
            Some(task.effective_safe_for_agent),
            refusal.is_some(),
            &task.unsafe_closure_tasks,
            "task",
        );
    let decision_basis = governance_preflight_decision_basis(
        Some(task.safe_for_agent),
        Some(task.effective_safe_for_agent),
        refusal,
        &task.unsafe_closure_tasks,
        crossing_required,
        crossing_classification.as_deref(),
        crossing_boundary_family.as_deref(),
    );
    let review_required = Some(!task.effective_safe_for_agent);
    let refusal_reason_family = refusal.map(|entry| entry.reason);
    let crossing_classification_for_evidence = crossing_classification.clone();
    let crossing_boundary_family_for_evidence = crossing_boundary_family.clone();
    let mut evaluation = crate::output::GovernancePreflightEvaluation {
        state: if refusal.is_some() {
            String::from("refused")
        } else {
            String::from("allowed")
        },
        sandbox_admission: None,
        review_required,
        declared_safe_for_agent: Some(task.safe_for_agent),
        effective_safe_for_agent: Some(task.effective_safe_for_agent),
        unsafe_closure_tasks: task.unsafe_closure_tasks.clone(),
        refusal_reason_family: refusal_reason_family.map(str::to_string),
        refusal: refusal.map(AgentExecutionRefusal::governance_record),
        crossing_required,
        crossing_classification,
        crossing_boundary_family,
        decision_basis,
        decision_inputs: governance_preflight_decision_inputs(
            &format!("task:{}", task.name),
            "task",
            "agent",
            "task_agent_capability_preflight",
            None,
            Some(task.safe_for_agent),
            Some(task.effective_safe_for_agent),
            &task.unsafe_closure_tasks,
            refusal,
            true,
            false,
        ),
        replay: crate::output::GovernanceReplayResult {
            status: String::new(),
            mismatches: Vec::new(),
        },
        evidence_classes: governance_preflight_evidence_classes(
            review_required,
            Some(task.safe_for_agent),
            Some(task.effective_safe_for_agent),
            &task.unsafe_closure_tasks,
            refusal_reason_family,
            refusal.is_some(),
            crossing_required,
            crossing_classification_for_evidence.as_deref(),
            crossing_boundary_family_for_evidence.as_deref(),
        ),
        receipt_expected: true,
        proof_expected: false,
    };
    evaluation.replay = reconcile_preflight_replay(&evaluation);
    evaluation
}

