const PROOF_PARENT_AUTHORITY_FD_ENV: &str = "OTA_PROOF_PARENT_AUTHORITY_FD";
const PROOF_PARENT_AUTHORITY_MAX_BYTES: usize = 64 * 1024;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct ProofParentInvocation {
    kind: String,
    name: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    proof_invocation: Option<CrossingProofInvocation>,
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(tag = "carrier", rename_all = "snake_case")]
enum ProofParentAuthorityEvidence {
    PreboundFile {
        admission: GrantAdmissionEvidence,
        carrier_admission: crate::crossing_authority::CrossingAuthorityAdmission,
        transaction: crate::crossing_transaction::CrossingTransactionEvidence,
    },
    AuthorityBroker {
        admission: crate::broker_session::BrokerAdmissionEvidence,
        transaction: crate::crossing_transaction::CrossingTransactionEvidence,
    },
}

impl ProofParentAuthorityEvidence {
    fn semantic_scope(&self) -> &crate::crossing::CrossingSemanticScope {
        match self {
            Self::PreboundFile { admission, .. } => &admission.semantic_scope,
            Self::AuthorityBroker { admission, .. } => &admission.semantic_scope,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
struct ProofParentAuthorityCapability {
    schema_version: u32,
    identity: String,
    challenge_identity: String,
    parent_pid: u32,
    invocation: ProofParentInvocation,
    authority: ProofParentAuthorityEvidence,
}

fn proof_parent_authority_capability_identity(
    capability: &ProofParentAuthorityCapability,
) -> Result<String, String> {
    let mut unsigned = capability.clone();
    unsigned.identity.clear();
    crate::semantic_identity::semantic_contract_identity(&unsigned)
}

fn active_proof_parent_authority_capability(
    invocation: ProofParentInvocation,
) -> Result<Option<ProofParentAuthorityCapability>, String> {
    let admission = ACTIVE_CROSSING_GRANT_ADMISSION.with(|active| active.borrow().clone());
    let Some(admission) = admission else {
        return Ok(None);
    };
    let transaction = active_crossing_transaction_evidence()
        .ok_or_else(|| String::from("proof authority has no active crossing transaction"))?;
    if transaction.state != "pending" {
        return Err(String::from(
            "proof authority transaction is no longer pending",
        ));
    }
    let authority = match admission {
        VerifiedCrossingAuthorityAdmission::PreboundFile(admission) => {
            let carrier_admission = admission.crossing_admission()?;
            crate::crossing_transaction::verify_pending_crossing_transaction_evidence(
                &transaction,
                &carrier_admission,
            )?;
            ProofParentAuthorityEvidence::PreboundFile {
                admission,
                carrier_admission,
                transaction,
            }
        }
        VerifiedCrossingAuthorityAdmission::AuthorityBroker(admission) => {
            crate::broker_session::verify_pending_broker_consumption_evidence(
                &admission,
                &transaction,
            )?;
            ProofParentAuthorityEvidence::AuthorityBroker {
                admission,
                transaction,
            }
        }
        VerifiedCrossingAuthorityAdmission::AuthorityBrokerPreview { .. } => {
            return Err(String::from(
                "proof authority preview cannot authorize a child invocation",
            ));
        }
    };
    let mut capability = ProofParentAuthorityCapability {
        schema_version: 1,
        identity: String::new(),
        challenge_identity: String::new(),
        parent_pid: std::process::id(),
        invocation,
        authority,
    };
    capability.identity = proof_parent_authority_capability_identity(&capability)?;
    Ok(Some(capability))
}

fn proof_parent_task_invocation(
    invocation_id: &str,
    invocation_kind: &str,
    task: &str,
) -> Result<ProofParentInvocation, String> {
    let admission = ACTIVE_CROSSING_GRANT_ADMISSION.with(|active| active.borrow().clone());
    let Some(admission) = admission else {
        return Ok(ProofParentInvocation {
            kind: String::from("proof_task"),
            name: task.to_string(),
            proof_invocation: None,
        });
    };
    let scope = match &admission {
        VerifiedCrossingAuthorityAdmission::PreboundFile(admission) => &admission.semantic_scope,
        VerifiedCrossingAuthorityAdmission::AuthorityBroker(admission) => &admission.semantic_scope,
        VerifiedCrossingAuthorityAdmission::AuthorityBrokerPreview { semantic_scope, .. } => {
            semantic_scope
        }
    };
    let matches = scope
        .proof_invocations
        .iter()
        .filter(|invocation| {
            invocation.id == invocation_id
                && invocation.kind == invocation_kind
                && invocation.task == task
        })
        .cloned()
        .collect::<Vec<_>>();
    let [proof_invocation] = matches.as_slice() else {
        return Err(String::from(
            "proof helper does not have one exact authorized invocation identity",
        ));
    };
    Ok(ProofParentInvocation {
        kind: String::from("proof_task"),
        name: task.to_string(),
        proof_invocation: Some(proof_invocation.clone()),
    })
}

fn proof_scope_overrides(scope: &crate::crossing::CrossingSemanticScope) -> ExecutionOverrides {
    ExecutionOverrides {
        backend: scope.execution_selection.backend,
        lifecycle: scope.execution_selection.lifecycle,
        host_port: scope.execution_selection.host_port,
        memory: scope.execution_selection.memory,
        skip_deps: scope.execution_selection.skip_dependencies,
        ..ExecutionOverrides::default()
    }
}

fn rederive_proof_parent_scope(
    contract: &Contract,
    expected: &crate::crossing::CrossingSemanticScope,
) -> Result<crate::crossing::CrossingSemanticScope, String> {
    let workflow_name = (expected.lane.kind == crate::sandbox_policy::SandboxLaneKind::Workflow)
        .then(|| {
            expected
                .execution_selection
                .workflow_instance
                .as_ref()
                .map(|selection| selection.selector.as_str())
                .unwrap_or(expected.lane.name.as_str())
        });
    let overrides = proof_scope_overrides(expected);
    let proof_roots = expected
        .proof_invocations
        .iter()
        .map(|invocation| invocation.task.clone())
        .collect::<Vec<_>>();
    let policy = crate::sandbox_policy::sandbox_policy_for_workflow_with_proof_roots(
        contract,
        workflow_name,
        overrides,
        &proof_roots,
    )?;
    crossing_scope_from_policy(
        policy,
        overrides,
        &[],
        &expected.execution_selection.effect_overrides,
        expected.execution_selection.sandbox_target.as_deref(),
        expected.execution_selection.run_behavior.as_deref(),
        expected.execution_selection.ready_timeout_seconds,
        expected.boundary_family.as_str(),
        expected.classification.as_str(),
    )
    .and_then(|scope| match workflow_name {
        Some(workflow_name) => {
            crossing_scope_with_workflow_instance_selection(scope, contract, Some(workflow_name))
        }
        None => Ok(scope),
    })
    .and_then(|scope| {
        crossing_scope_with_proof_invocations(scope, expected.proof_invocations.clone())
    })
    .and_then(|scope| match expected.proof_transaction_selection.clone() {
        Some(selection) => crossing_scope_with_proof_transaction_selection(scope, selection),
        None => Ok(scope),
    })
}

fn verify_proof_parent_authority_capability(
    contract: &Contract,
    contract_path: &Path,
    capability: &ProofParentAuthorityCapability,
    expected_kind: &str,
    expected_name: &str,
) -> Result<(), String> {
    if capability.schema_version != 1
        || capability.identity != proof_parent_authority_capability_identity(capability)?
        || capability.challenge_identity.is_empty()
        || capability.parent_pid != current_parent_process_id()?
        || capability.invocation.kind != expected_kind
        || capability.invocation.name != expected_name
    {
        return Err(String::from(
            "proof parent authority capability does not match this child invocation",
        ));
    }
    let root = contract_working_dir(contract_path);
    match &capability.authority {
        ProofParentAuthorityEvidence::PreboundFile {
            admission,
            carrier_admission,
            transaction,
        } => {
            crate::crossing_authority::verify_archived_grant_admission(contract, root, admission)
                .map_err(|error| error.public_details())?;
            if admission.crossing_admission()? != *carrier_admission {
                return Err(String::from(
                    "proof parent prebound carrier admission does not reconcile",
                ));
            }
            crate::crossing_transaction::verify_pending_crossing_transaction_evidence(
                transaction,
                carrier_admission,
            )?;
            crate::crossing_transaction::verify_pending_crossing_transaction_journal(
                root,
                transaction,
            )?;
        }
        ProofParentAuthorityEvidence::AuthorityBroker {
            admission,
            transaction,
        } => {
            crate::broker_session::verify_pending_broker_archive_evidence(
                root,
                admission,
                transaction,
            )?;
            crate::crossing_transaction::verify_pending_crossing_transaction_journal(
                root,
                transaction,
            )?;
        }
    }
    let rederived = rederive_proof_parent_scope(contract, capability.authority.semantic_scope())?;
    if rederived != *capability.authority.semantic_scope() {
        return Err(String::from(
            "proof parent authority scope no longer matches the selected contract",
        ));
    }
    match expected_kind {
        "workflow"
            if rederived.lane.name == expected_name
                || (rederived.lane.kind == crate::sandbox_policy::SandboxLaneKind::Task
                    && expected_name == "default") =>
        {
            Ok(())
        }
        "workflow_task" => {
            let selected = match rederived.lane.kind {
                crate::sandbox_policy::SandboxLaneKind::Workflow => contract
                    .selected_workflow_task_closure_names(Some(rederived.lane.name.as_str())),
                crate::sandbox_policy::SandboxLaneKind::Task => {
                    contract.task_dependency_closure_names([rederived.lane.name.clone()])
                }
            };
            selected
                .into_iter()
                .any(|task| task == expected_name)
                .then_some(())
                .ok_or_else(|| {
                    String::from("proof child task is outside the authorized workflow closure")
                })
        }
        "proof_task" => capability
            .invocation
            .proof_invocation
            .as_ref()
            .filter(|invocation| invocation.task == expected_name)
            .filter(|invocation| {
                rederived
                    .proof_invocations
                    .iter()
                    .any(|expected| expected == *invocation)
            })
            .map(|_| ())
            .ok_or_else(|| {
                String::from("proof helper invocation does not match its authorized role and order")
            }),
        _ => Err(String::from(
            "proof parent authority capability uses an unsupported invocation kind",
        )),
    }
}

#[cfg(unix)]
fn current_parent_process_id() -> Result<u32, String> {
    // SAFETY: `getppid` has no preconditions and does not dereference memory.
    Ok(unsafe { libc::getppid() as u32 })
}

#[cfg(target_os = "linux")]
fn proof_parent_peer_pid(stream: &std::os::unix::net::UnixStream) -> Result<u32, String> {
    use std::os::fd::AsRawFd as _;
    let mut credentials = std::mem::MaybeUninit::<libc::ucred>::uninit();
    let mut length = std::mem::size_of::<libc::ucred>() as libc::socklen_t;
    // SAFETY: the output buffer and length describe a valid `ucred` allocation.
    let result = unsafe {
        libc::getsockopt(
            stream.as_raw_fd(),
            libc::SOL_SOCKET,
            libc::SO_PEERCRED,
            credentials.as_mut_ptr().cast(),
            &mut length,
        )
    };
    if result != 0 || length as usize != std::mem::size_of::<libc::ucred>() {
        return Err(String::from(
            "proof parent authority peer credentials are unavailable",
        ));
    }
    // SAFETY: successful `getsockopt` initialized the complete `ucred` value.
    let credentials = unsafe { credentials.assume_init() };
    u32::try_from(credentials.pid)
        .map_err(|_| String::from("proof parent authority peer PID is invalid"))
}

#[cfg(target_os = "macos")]
fn proof_parent_peer_pid(stream: &std::os::unix::net::UnixStream) -> Result<u32, String> {
    use std::os::fd::AsRawFd as _;
    let mut pid = 0_i32;
    let mut length = std::mem::size_of::<i32>() as libc::socklen_t;
    // SAFETY: the output buffer and length describe a valid PID allocation.
    let result = unsafe {
        libc::getsockopt(
            stream.as_raw_fd(),
            libc::SOL_LOCAL,
            libc::LOCAL_PEERPID,
            (&mut pid as *mut i32).cast(),
            &mut length,
        )
    };
    if result != 0 || length as usize != std::mem::size_of::<i32>() {
        return Err(String::from(
            "proof parent authority peer credentials are unavailable",
        ));
    }
    u32::try_from(pid).map_err(|_| String::from("proof parent authority peer PID is invalid"))
}

#[cfg(all(unix, not(any(target_os = "linux", target_os = "macos"))))]
fn proof_parent_peer_pid(_stream: &std::os::unix::net::UnixStream) -> Result<u32, String> {
    Err(String::from(
        "proof parent authority peer verification is unsupported on this Unix platform",
    ))
}

#[cfg(target_os = "linux")]
fn proof_parent_executable(pid: u32) -> Result<PathBuf, String> {
    fs::read_link(format!("/proc/{pid}/exe"))
        .map_err(|_| String::from("proof parent executable identity is unavailable"))
}

#[cfg(target_os = "macos")]
fn proof_parent_executable(pid: u32) -> Result<PathBuf, String> {
    use std::os::unix::ffi::OsStringExt as _;
    let mut buffer = vec![0_u8; libc::PROC_PIDPATHINFO_MAXSIZE as usize];
    // SAFETY: the buffer is valid for the supplied length and `proc_pidpath` writes at most it.
    let written =
        unsafe { libc::proc_pidpath(pid as i32, buffer.as_mut_ptr().cast(), buffer.len() as u32) };
    if written <= 0 {
        return Err(String::from(
            "proof parent executable identity is unavailable",
        ));
    }
    buffer.truncate(written as usize);
    Ok(PathBuf::from(OsString::from_vec(buffer)))
}

#[cfg(all(unix, not(any(target_os = "linux", target_os = "macos"))))]
fn proof_parent_executable(_pid: u32) -> Result<PathBuf, String> {
    Err(String::from(
        "proof parent executable verification is unsupported on this Unix platform",
    ))
}

#[cfg(unix)]
fn verify_proof_parent_stream(stream: &std::os::unix::net::UnixStream) -> Result<u32, String> {
    use std::os::fd::AsRawFd as _;
    let mut peer_address = std::mem::MaybeUninit::<libc::sockaddr_storage>::zeroed();
    let mut peer_address_length = std::mem::size_of::<libc::sockaddr_storage>() as libc::socklen_t;
    // SAFETY: the address buffer and length describe valid writable storage.
    let peer_result = unsafe {
        libc::getpeername(
            stream.as_raw_fd(),
            peer_address.as_mut_ptr().cast(),
            &mut peer_address_length,
        )
    };
    if peer_result != 0 {
        return Err(String::from(
            "proof parent authority descriptor is not a connected socket",
        ));
    }
    // SAFETY: successful `getpeername` initialized at least the address family.
    let peer_address = unsafe { peer_address.assume_init() };
    if peer_address.ss_family != libc::AF_UNIX as libc::sa_family_t {
        return Err(String::from(
            "proof parent authority descriptor is not a Unix stream",
        ));
    }
    let mut socket_type = 0_i32;
    let mut length = std::mem::size_of::<i32>() as libc::socklen_t;
    // SAFETY: the output buffer and length describe a valid integer allocation.
    let result = unsafe {
        libc::getsockopt(
            stream.as_raw_fd(),
            libc::SOL_SOCKET,
            libc::SO_TYPE,
            (&mut socket_type as *mut i32).cast(),
            &mut length,
        )
    };
    if result != 0 || socket_type != libc::SOCK_STREAM {
        return Err(String::from(
            "proof parent authority descriptor is not a Unix stream",
        ));
    }
    let peer_pid = proof_parent_peer_pid(stream)?;
    if peer_pid != current_parent_process_id()? {
        return Err(String::from(
            "proof parent authority stream is not connected to the immediate parent",
        ));
    }
    let parent_executable = fs::canonicalize(proof_parent_executable(peer_pid)?)
        .map_err(|_| String::from("proof parent executable identity is unavailable"))?;
    let current_executable = fs::canonicalize(
        env::current_exe()
            .map_err(|_| String::from("current Ota executable identity is unavailable"))?,
    )
    .map_err(|_| String::from("current Ota executable identity is unavailable"))?;
    if parent_executable != current_executable {
        return Err(String::from(
            "proof parent authority peer is not the matching Ota executable",
        ));
    }
    Ok(peer_pid)
}

#[cfg(not(unix))]
fn current_parent_process_id() -> Result<u32, String> {
    Err(String::from(
        "proof parent authority capabilities are supported only on Unix platforms",
    ))
}

#[cfg(unix)]
fn load_proof_parent_authority_capability() -> Result<Option<ProofParentAuthorityCapability>, String>
{
    if let Some(capability) = ACTIVE_PROOF_PARENT_AUTHORITY.with(|active| active.borrow().clone()) {
        return Ok(Some(capability));
    }
    let Some(raw_fd) = env::var_os(PROOF_PARENT_AUTHORITY_FD_ENV) else {
        return Ok(None);
    };
    // SAFETY: command admission is single-threaded at this boundary; remove the descriptor
    // carrier before any selected execution or child spawn can observe it.
    unsafe { env::remove_var(PROOF_PARENT_AUTHORITY_FD_ENV) };
    let raw_fd = raw_fd
        .to_string_lossy()
        .parse::<std::os::fd::RawFd>()
        .map_err(|_| String::from("proof parent authority descriptor is invalid"))?;
    // SAFETY: `fcntl` only inspects and updates the supplied descriptor flags.
    let flags = unsafe { libc::fcntl(raw_fd, libc::F_GETFD) };
    if flags < 0 {
        return Err(String::from(
            "proof parent authority descriptor is not open",
        ));
    }
    // SAFETY: the descriptor was proven open above. Set close-on-exec before reading any
    // authority data so no later child can inherit it accidentally.
    if unsafe { libc::fcntl(raw_fd, libc::F_SETFD, flags | libc::FD_CLOEXEC) } < 0 {
        return Err(String::from(
            "proof parent authority descriptor could not be made non-inheritable",
        ));
    }
    use std::os::fd::{FromRawFd as _, OwnedFd};
    use std::os::unix::net::UnixStream;
    // SAFETY: ownership is transferred exactly once after the descriptor was proven open.
    let owned = unsafe { OwnedFd::from_raw_fd(raw_fd) };
    let mut stream = UnixStream::from(owned);
    stream
        .set_read_timeout(Some(Duration::from_secs(5)))
        .map_err(|_| String::from("proof parent authority timeout could not be applied"))?;
    let peer_pid = verify_proof_parent_stream(&stream)?;
    let mut challenge = [0_u8; 32];
    getrandom::getrandom(&mut challenge)
        .map_err(|_| String::from("proof parent authority challenge is unavailable"))?;
    stream
        .write_all(&challenge)
        .map_err(|_| String::from("proof parent authority challenge could not be delivered"))?;
    let challenge_identity = format!("sha256:{:x}", Sha256::digest(challenge));
    let mut length = [0_u8; 4];
    stream
        .read_exact(&mut length)
        .map_err(|_| String::from("proof parent authority frame is incomplete"))?;
    let length = u32::from_be_bytes(length) as usize;
    if length == 0 || length > PROOF_PARENT_AUTHORITY_MAX_BYTES {
        return Err(String::from(
            "proof parent authority frame exceeds its bounded carrier",
        ));
    }
    let mut payload = vec![0_u8; length];
    stream
        .read_exact(&mut payload)
        .map_err(|_| String::from("proof parent authority payload is incomplete"))?;
    let capability = serde_json::from_slice::<ProofParentAuthorityCapability>(&payload)
        .map_err(|_| String::from("proof parent authority payload is invalid"))?;
    if capability.parent_pid != peer_pid || capability.challenge_identity != challenge_identity {
        return Err(String::from(
            "proof parent authority payload does not match its connected challenge",
        ));
    }
    ACTIVE_PROOF_PARENT_AUTHORITY.with(|active| {
        active.replace(Some(capability.clone()));
    });
    Ok(Some(capability))
}

#[cfg(not(unix))]
fn load_proof_parent_authority_capability() -> Result<Option<ProofParentAuthorityCapability>, String>
{
    if env::var_os(PROOF_PARENT_AUTHORITY_FD_ENV).is_some() {
        return Err(String::from(
            "proof parent authority capabilities are supported only on Unix platforms",
        ));
    }
    Ok(None)
}

fn proof_parent_authorizes_invocation(
    contract: &Contract,
    contract_path: &Path,
    kinds: &[&str],
    name: &str,
) -> Result<bool, GrantAdmissionError> {
    let Some(capability) = load_proof_parent_authority_capability()
        .map_err(|details| GrantAdmissionError::new("proof_parent_authority_invalid", details))?
    else {
        return Ok(false);
    };
    if !kinds.iter().any(|kind| capability.invocation.kind == *kind) {
        return Err(GrantAdmissionError::new(
            "proof_parent_authority_invalid",
            "proof parent authority capability does not select this command surface",
        )
        .with_scope(capability.authority.semantic_scope().clone()));
    }
    verify_proof_parent_authority_capability(
        contract,
        contract_path,
        &capability,
        capability.invocation.kind.as_str(),
        name,
    )
    .map_err(|details| {
        GrantAdmissionError::new("proof_parent_authority_invalid", details)
            .with_scope(capability.authority.semantic_scope().clone())
    })?;
    Ok(true)
}

#[cfg(unix)]
fn spawn_with_proof_parent_authority(
    command: &mut Command,
    capability: Option<ProofParentAuthorityCapability>,
) -> Result<std::process::Child, String> {
    use std::os::fd::AsRawFd as _;
    use std::os::unix::net::UnixStream;
    let Some(capability) = capability else {
        return command.spawn().map_err(|error| error.to_string());
    };
    let payload = serde_json::to_vec(&capability)
        .map_err(|error| format!("could not serialize proof parent authority: {error}"))?;
    if payload.is_empty() || payload.len() > PROOF_PARENT_AUTHORITY_MAX_BYTES {
        return Err(String::from(
            "proof parent authority payload exceeds its bounded carrier",
        ));
    }
    let (mut parent_stream, child_stream) = UnixStream::pair()
        .map_err(|error| format!("could not create proof authority channel: {error}"))?;
    let child_fd = child_stream.as_raw_fd();
    // SAFETY: the descriptor belongs to `child_stream`; clearing close-on-exec is required only
    // for the immediate Ota child and the child sets it again before parsing the frame.
    let flags = unsafe { libc::fcntl(child_fd, libc::F_GETFD) };
    if flags < 0 || unsafe { libc::fcntl(child_fd, libc::F_SETFD, flags & !libc::FD_CLOEXEC) } < 0 {
        return Err(String::from(
            "could not make the proof authority channel available to the Ota child",
        ));
    }
    command.env(PROOF_PARENT_AUTHORITY_FD_ENV, child_fd.to_string());
    let mut child = command.spawn().map_err(|error| error.to_string())?;
    drop(child_stream);
    parent_stream
        .set_read_timeout(Some(Duration::from_secs(5)))
        .map_err(|error| format!("could not bound proof authority challenge wait: {error}"))?;
    let mut challenge = [0_u8; 32];
    if let Err(error) = parent_stream.read_exact(&mut challenge) {
        let _ = child.kill();
        let _ = child.wait();
        return Err(format!(
            "could not receive proof authority challenge from the Ota child: {error}"
        ));
    }
    let mut capability = capability;
    capability.challenge_identity = format!("sha256:{:x}", Sha256::digest(challenge));
    capability.identity = proof_parent_authority_capability_identity(&capability)?;
    let payload = serde_json::to_vec(&capability)
        .map_err(|error| format!("could not serialize proof parent authority: {error}"))?;
    if payload.is_empty() || payload.len() > PROOF_PARENT_AUTHORITY_MAX_BYTES {
        let _ = child.kill();
        let _ = child.wait();
        return Err(String::from(
            "proof parent authority payload exceeds its bounded carrier",
        ));
    }
    if let Err(error) = parent_stream
        .write_all(&(payload.len() as u32).to_be_bytes())
        .and_then(|_| parent_stream.write_all(&payload))
    {
        let _ = child.kill();
        let _ = child.wait();
        return Err(format!(
            "could not deliver proof authority to the Ota child: {error}"
        ));
    }
    Ok(child)
}

fn output_with_proof_parent_authority(
    command: &mut Command,
    capability: Option<ProofParentAuthorityCapability>,
) -> Result<std::process::Output, String> {
    command.stdout(Stdio::piped()).stderr(Stdio::piped());
    spawn_with_proof_parent_authority(command, capability)?
        .wait_with_output()
        .map_err(|error| error.to_string())
}

#[cfg(not(unix))]
fn spawn_with_proof_parent_authority(
    command: &mut Command,
    capability: Option<ProofParentAuthorityCapability>,
) -> Result<std::process::Child, String> {
    if capability.is_some() {
        return Err(String::from(
            "proof parent authority capabilities are supported only on Unix platforms",
        ));
    }
    command.spawn().map_err(|error| error.to_string())
}

struct ActiveCrossingGrantGuard {
    previous: Option<VerifiedCrossingAuthorityAdmission>,
}

impl ActiveCrossingGrantGuard {
    fn activate(admission: Option<VerifiedCrossingAuthorityAdmission>) -> Self {
        let previous = ACTIVE_CROSSING_GRANT_ADMISSION.with(|active| active.replace(admission));
        Self { previous }
    }

    fn activate_preview(plan: Option<CrossingAuthorityPlan>) -> Self {
        Self::activate(plan.map(|plan| match plan {
            CrossingAuthorityPlan::PreboundFile(admission) => {
                VerifiedCrossingAuthorityAdmission::PreboundFile(admission)
            }
            CrossingAuthorityPlan::AuthorityBroker {
                binding,
                semantic_scope,
                actor_mode,
            } => VerifiedCrossingAuthorityAdmission::AuthorityBrokerPreview {
                binding,
                semantic_scope,
                actor_mode,
            },
        }))
    }
}

impl Drop for ActiveCrossingGrantGuard {
    fn drop(&mut self) {
        let previous = self.previous.take();
        ACTIVE_CROSSING_GRANT_ADMISSION.with(|active| {
            active.replace(previous);
        });
    }
}

fn active_crossing_grant_authority() -> Option<crate::output::ExecutionBoundaryCrossingAuthority> {
    ACTIVE_CROSSING_GRANT_ADMISSION.with(|active| {
        let admission = active.borrow();
        let admission = admission.as_ref()?;
        let transaction = active_crossing_transaction_evidence()?;
        crossing_authority_output_with_transaction(admission, Some(transaction), true).ok()
    })
}

fn active_crossing_authority_is_configured() -> bool {
    ACTIVE_CROSSING_GRANT_ADMISSION.with(|active| active.borrow().is_some())
}

fn active_crossing_grant_preview() -> Option<crate::output::CrossingGrantAdmissionPreview> {
    ACTIVE_CROSSING_GRANT_ADMISSION.with(|active| {
        active
            .borrow()
            .as_ref()
            .and_then(|admission| match admission {
                VerifiedCrossingAuthorityAdmission::PreboundFile(admission) => {
                    Some(crossing_authority_plan_preview(
                        &CrossingAuthorityPlan::PreboundFile(admission.clone()),
                    ))
                }
                VerifiedCrossingAuthorityAdmission::AuthorityBrokerPreview {
                    binding,
                    semantic_scope,
                    actor_mode,
                } => Some(crossing_authority_plan_preview(
                    &CrossingAuthorityPlan::AuthorityBroker {
                        binding: binding.clone(),
                        semantic_scope: semantic_scope.clone(),
                        actor_mode: actor_mode.clone(),
                    },
                )),
                VerifiedCrossingAuthorityAdmission::AuthorityBroker(_) => None,
            })
    })
}

struct ActiveCrossingTransactionGuard {
    previous: Option<Rc<RefCell<crate::crossing_transaction::CrossingTransactionGuard>>>,
    #[cfg(unix)]
    previous_systemd_completion:
        Option<Rc<RefCell<crate::broker_session::SystemdExecutionCompletion>>>,
}

impl ActiveCrossingTransactionGuard {
    fn activate_prebound(
        repo_root: &Path,
        admission: Option<&GrantAdmissionEvidence>,
    ) -> Result<Option<Self>, String> {
        let Some(admission) = admission else {
            return Ok(None);
        };
        let transaction_admission = admission.crossing_admission()?;
        let transaction = Rc::new(RefCell::new(
            crate::crossing_transaction::CrossingTransactionGuard::begin(
                repo_root,
                &transaction_admission,
            )?,
        ));
        let previous = ACTIVE_CROSSING_TRANSACTION.with(|active| active.replace(Some(transaction)));
        Ok(Some(Self {
            previous,
            #[cfg(unix)]
            previous_systemd_completion: None,
        }))
    }

    fn activate_existing(
        transaction: crate::crossing_transaction::CrossingTransactionGuard,
        #[cfg(unix)] systemd_completion: Option<crate::broker_session::SystemdExecutionCompletion>,
    ) -> Self {
        let transaction = Rc::new(RefCell::new(transaction));
        let previous = ACTIVE_CROSSING_TRANSACTION.with(|active| active.replace(Some(transaction)));
        #[cfg(unix)]
        let previous_systemd_completion = ACTIVE_SYSTEMD_EXECUTION_COMPLETION.with(|active| {
            active.replace(systemd_completion.map(|completion| Rc::new(RefCell::new(completion))))
        });
        Self {
            previous,
            #[cfg(unix)]
            previous_systemd_completion,
        }
    }
}

fn crossing_authority_plan_preview(
    plan: &CrossingAuthorityPlan,
) -> crate::output::CrossingGrantAdmissionPreview {
    match plan {
        CrossingAuthorityPlan::PreboundFile(admission) => {
            crate::output::CrossingGrantAdmissionPreview {
                decision: String::from("admissible_not_consumed"),
                authority_carrier: None,
                authority_id: admission.authority_id.clone(),
                authority_binding_identity: admission.authority_binding_identity.clone(),
                issuer_id: Some(admission.issuer_id.clone()),
                key_id: Some(admission.key_id.clone()),
                key_fingerprint: Some(admission.key_fingerprint.clone()),
                bundle_id: Some(admission.bundle_id.clone()),
                bundle_identity: Some(admission.bundle_identity.clone()),
                bundle_sequence: Some(admission.bundle_sequence),
                grant_id: Some(admission.grant_id.clone()),
                grant_identity: Some(admission.grant_identity.clone()),
                scope_identity: admission.scope_identity.clone(),
                contract_identity: admission.contract_identity.clone(),
                boundary_family: admission.boundary_family.clone(),
                classification: admission.classification.clone(),
                actor_mode: admission.actor_mode.clone(),
                environment_posture: Some(admission.environment_posture.clone()),
                expiry_kind: Some(admission.expiry_kind.clone()),
                issued_at: Some(admission.issued_at.clone()),
                not_before: Some(admission.not_before.clone()),
                next_update: Some(admission.next_update.clone()),
                expires_at: Some(admission.expires_at.clone()),
                clock_evidence: Some(admission.clock_evidence.clone()),
                sequence_evidence: Some(admission.sequence_evidence.clone()),
                revocation_evidence: Some(admission.revocation_evidence.clone()),
                admitted_at: Some(admission.admitted_at.clone()),
            }
        }
        CrossingAuthorityPlan::AuthorityBroker {
            binding,
            semantic_scope,
            actor_mode,
        } => crate::output::CrossingGrantAdmissionPreview {
            decision: String::from("requires_live_authorization"),
            authority_carrier: Some(String::from("authority_broker")),
            authority_id: binding.authority_id.clone(),
            authority_binding_identity: binding.identity.clone(),
            issuer_id: None,
            key_id: None,
            key_fingerprint: None,
            bundle_id: None,
            bundle_identity: None,
            bundle_sequence: None,
            grant_id: None,
            grant_identity: None,
            scope_identity: semantic_scope.identity.clone(),
            contract_identity: semantic_scope.contract_identity.clone(),
            boundary_family: semantic_scope.boundary_family.clone(),
            classification: semantic_scope.classification.clone(),
            actor_mode: actor_mode.clone(),
            environment_posture: None,
            expiry_kind: None,
            issued_at: None,
            not_before: None,
            next_update: None,
            expires_at: None,
            clock_evidence: None,
            sequence_evidence: None,
            revocation_evidence: None,
            admitted_at: None,
        },
    }
}

fn activate_crossing_authority_plan(
    repo_root: &Path,
    plan: CrossingAuthorityPlan,
) -> Result<(ActiveCrossingGrantGuard, ActiveCrossingTransactionGuard), GrantAdmissionError> {
    match plan {
        CrossingAuthorityPlan::PreboundFile(admission) => {
            let transaction =
                ActiveCrossingTransactionGuard::activate_prebound(repo_root, Some(&admission))
                    .map_err(|details| {
                        GrantAdmissionError::new("crossing_transaction_unavailable", details)
                            .with_scope(admission.semantic_scope.clone())
                    })?
                    .expect("a verified prebound admission should create one transaction");
            let authority = ActiveCrossingGrantGuard::activate(Some(
                VerifiedCrossingAuthorityAdmission::PreboundFile(admission),
            ));
            Ok((authority, transaction))
        }
        CrossingAuthorityPlan::AuthorityBroker {
            binding,
            semantic_scope,
            actor_mode,
        } => {
            #[cfg(unix)]
            {
                let interrupt_epoch = crate::runner::begin_command_interrupt_observation();
                let prepared = crate::broker_session::PreparedBrokerCrossing::prepare(
                    repo_root,
                    binding.clone(),
                    &semantic_scope,
                    actor_mode.as_str(),
                    binding.maximum_lease_seconds,
                    || crate::runner::command_interrupted_since(interrupt_epoch),
                )
                .map_err(|details| {
                    GrantAdmissionError::new("crossing_broker_admission_refused", details)
                        .with_authority_source("authority_broker")
                        .with_scope(semantic_scope.clone())
                })?;
                let consumed = prepared
                    .consume(repo_root, || {
                        crate::runner::command_interrupted_since(interrupt_epoch)
                    })
                    .map_err(|details| {
                        GrantAdmissionError::new("crossing_broker_consumption_refused", details)
                            .with_authority_source("authority_broker")
                            .with_scope(semantic_scope.clone())
                    })?;
                let (admission, transaction, systemd_completion) = consumed.into_parts();
                let transaction = ActiveCrossingTransactionGuard::activate_existing(
                    transaction,
                    systemd_completion,
                );
                let authority = ActiveCrossingGrantGuard::activate(Some(
                    VerifiedCrossingAuthorityAdmission::AuthorityBroker(admission),
                ));
                Ok((authority, transaction))
            }
            #[cfg(not(unix))]
            {
                let _ = (binding, actor_mode, repo_root);
                Err(GrantAdmissionError::new(
                    "crossing_broker_platform_unsupported",
                    "the launcher-session broker carrier is supported only on Unix platforms",
                )
                .with_authority_source("authority_broker")
                .with_scope(semantic_scope))
            }
        }
    }
}

impl Drop for ActiveCrossingTransactionGuard {
    fn drop(&mut self) {
        ACTIVE_CROSSING_TRANSACTION.with(|active| {
            active.replace(self.previous.take());
        });
        #[cfg(unix)]
        ACTIVE_SYSTEMD_EXECUTION_COMPLETION.with(|active| {
            active.replace(self.previous_systemd_completion.take());
        });
    }
}

#[derive(Debug, Serialize, Deserialize, Clone, PartialEq, Eq)]
struct ArchivedCrossingGrantEvidence {
    admission: GrantAdmissionEvidence,
    #[serde(skip_serializing_if = "Option::is_none")]
    carrier_admission: Option<crate::crossing_authority::CrossingAuthorityAdmission>,
    #[serde(skip_serializing_if = "Option::is_none")]
    transaction: Option<crate::crossing_transaction::CrossingTransactionEvidence>,
}

#[derive(Debug, Serialize, Deserialize, Clone, PartialEq, Eq)]
#[serde(untagged)]
enum ArchivedCrossingAuthorityEvidence {
    PreboundFile(ArchivedCrossingGrantEvidence),
    AuthorityBroker(crate::broker_session::BrokerArchiveEvidence),
}

impl ArchivedCrossingAuthorityEvidence {
    fn semantic_scope(&self) -> &crate::crossing::CrossingSemanticScope {
        match self {
            Self::PreboundFile(evidence) => &evidence.admission.semantic_scope,
            Self::AuthorityBroker(evidence) => &evidence.admission.semantic_scope,
        }
    }
}

fn verify_terminal_proof_crossing_evidence(
    contract: &Contract,
    root: &Path,
    crossing: &ProofRuntimeCrossingEvidence,
    expected_scope: &crate::crossing::CrossingSemanticScope,
    proof_execution_id: &str,
    proof_status: &str,
    proof_ok: bool,
) -> Result<(), String> {
    if crossing.scope_identity != expected_scope.identity
        || crossing.proof_execution_id.as_deref() != Some(proof_execution_id)
        || crossing.receipt_archive_identity.is_some()
        || crossing.receipt_archive_path.is_some()
    {
        return Err(String::from(
            "proof crossing linkage does not match its canonical semantic scope",
        ));
    }
    let authority = crossing
        .authority
        .as_ref()
        .ok_or_else(|| String::from("proof crossing linkage omits terminal authority evidence"))?;
    if authority.scope_identity != expected_scope.identity
        || authority.contract_identity != expected_scope.contract_identity
    {
        return Err(String::from(
            "proof crossing authority does not match its canonical semantic scope",
        ));
    }
    let archived = serde_json::from_value::<ArchivedCrossingAuthorityEvidence>(
        authority.archive_evidence.clone(),
    )
    .map_err(|error| format!("proof crossing archive evidence is invalid: {error}"))?;
    if archived.semantic_scope() != expected_scope {
        return Err(String::from(
            "proof crossing archive authority does not re-derive from contract truth",
        ));
    }
    let (transaction, expected_authority) = match &archived {
        ArchivedCrossingAuthorityEvidence::PreboundFile(evidence) => {
            crate::crossing_authority::verify_archived_grant_admission(
                contract,
                root,
                &evidence.admission,
            )
            .map_err(|error| error.public_details())?;
            let carrier = evidence.carrier_admission.as_ref().ok_or_else(|| {
                String::from("proof crossing prebound archive omits its carrier admission")
            })?;
            if evidence.admission.crossing_admission()? != *carrier {
                return Err(String::from(
                    "proof crossing prebound carrier admission does not reconcile",
                ));
            }
            let transaction = evidence.transaction.as_ref().ok_or_else(|| {
                String::from("proof crossing prebound archive omits its transaction")
            })?;
            crate::crossing_transaction::verify_crossing_transaction_evidence(
                transaction,
                carrier,
            )?;
            let expected = crossing_authority_output_with_transaction(
                &VerifiedCrossingAuthorityAdmission::PreboundFile(evidence.admission.clone()),
                Some(transaction.clone()),
                true,
            )?;
            (transaction, expected)
        }
        ArchivedCrossingAuthorityEvidence::AuthorityBroker(evidence) => {
            crate::broker_session::verify_broker_archive_evidence(root, evidence)?;
            let expected = crossing_authority_output_with_transaction(
                &VerifiedCrossingAuthorityAdmission::AuthorityBroker(evidence.admission.clone()),
                Some(evidence.transaction.clone()),
                true,
            )?;
            (&evidence.transaction, expected)
        }
    };
    verify_exact_proof_authority_projection(authority, &expected_authority)?;
    verify_terminal_proof_transaction_binding(
        transaction,
        crossing,
        proof_execution_id,
        proof_status,
        proof_ok,
    )
}

fn verify_exact_proof_authority_projection(
    actual: &crate::output::ExecutionBoundaryCrossingAuthority,
    expected: &crate::output::ExecutionBoundaryCrossingAuthority,
) -> Result<(), String> {
    if actual != expected {
        return Err(String::from(
            "proof crossing public authority projection does not reconcile with verified archive evidence",
        ));
    }
    Ok(())
}

fn verify_terminal_proof_transaction_binding(
    transaction: &crate::crossing_transaction::CrossingTransactionEvidence,
    crossing: &ProofRuntimeCrossingEvidence,
    proof_execution_id: &str,
    proof_status: &str,
    proof_ok: bool,
) -> Result<(), String> {
    let expected_receipt_status = format!("proof:{proof_execution_id}:{proof_status}");
    if crossing.proof_execution_id.as_deref() != Some(proof_execution_id)
        || transaction.transaction_id != crossing.transaction_id
        || transaction.scope_identity != crossing.scope_identity
        || transaction.receipt_status.as_deref() != Some(expected_receipt_status.as_str())
        || proof_ok != (transaction.state == "completed")
    {
        return Err(String::from(
            "proof crossing terminal transaction does not match the proof outcome",
        ));
    }
    Ok(())
}

fn active_crossing_transaction_evidence()
-> Option<crate::crossing_transaction::CrossingTransactionEvidence> {
    ACTIVE_CROSSING_TRANSACTION.with(|active| {
        active
            .borrow()
            .as_ref()
            .map(|transaction| transaction.borrow().evidence())
    })
}

fn active_crossing_transaction_is_pending() -> bool {
    active_crossing_transaction_evidence().is_some_and(|evidence| evidence.state == "pending")
}

#[cfg(unix)]
fn persist_active_systemd_execution_completion(
    transaction: &crate::crossing_transaction::CrossingTransactionEvidence,
    receipt_archive_identity: Option<&str>,
    ok: bool,
    interrupted: bool,
    exit_code: Option<i32>,
    receipt_status: &str,
) -> Result<(), String> {
    #[cfg(test)]
    EXPECT_SYSTEMD_COMPLETION_AFTER_RECEIPT_ARCHIVE.with(|expected| {
        if let Some(root) = expected.borrow_mut().take() {
            let archive_dir = receipt_archive_dir(&root);
            let archive_exists = fs::read_dir(archive_dir).is_ok_and(|entries| {
                entries.filter_map(Result::ok).any(|entry| {
                    entry.file_name().to_str().is_some_and(|name| {
                        name.starts_with("repo-receipt-") && name.ends_with(".json")
                    })
                })
            });
            assert!(
                archive_exists,
                "systemd completion must follow durable receipt archive publication"
            );
        }
    });
    ACTIVE_SYSTEMD_EXECUTION_COMPLETION.with(|completion| {
        let Some(completion) = completion.borrow().as_ref().cloned() else {
            return Ok::<(), String>(());
        };
        completion.borrow_mut().persist_terminal_completion(
            transaction,
            receipt_archive_identity,
            ok,
            interrupted,
            exit_code,
            receipt_status,
        )?;
        Ok(())
    })
}

fn finalize_active_crossing_transaction(
    receipt: &ExecutionReceipt,
    terminal_exit_code: Option<i32>,
) -> Result<(), String> {
    ACTIVE_CROSSING_TRANSACTION.with(|active| {
        let Some(transaction) = active.borrow().as_ref().cloned() else {
            return Ok(());
        };
        let state = if receipt.ok {
            "completed"
        } else if receipt.status.as_deref() == Some("interrupted") {
            "interrupted"
        } else {
            "failed"
        };
        transaction
            .borrow_mut()
            .finalize(state, receipt.status.as_deref())?;
        let _ = terminal_exit_code;
        Ok(())
    })
}

#[cfg(unix)]
fn persist_active_crossing_systemd_completion(
    receipt: &ExecutionReceipt,
    receipt_archive_identity: &str,
    terminal_exit_code: Option<i32>,
) -> Result<(), String> {
    let Some(transaction) = active_crossing_transaction_evidence() else {
        return Ok(());
    };
    let receipt_status = transaction
        .receipt_status
        .as_deref()
        .unwrap_or(if receipt.ok { "completed" } else { "failed" });
    persist_active_systemd_execution_completion(
        &transaction,
        Some(receipt_archive_identity),
        receipt.ok,
        receipt.status.as_deref() == Some("interrupted"),
        terminal_exit_code,
        receipt_status,
    )
}

fn finalize_and_attach_active_crossing_transaction(
    receipt: &mut ExecutionReceipt,
    terminal_exit_code: Option<i32>,
) -> Result<(), String> {
    if active_crossing_transaction_evidence().is_none() {
        return Ok(());
    }
    finalize_active_crossing_transaction(receipt, terminal_exit_code)?;
    let authority = active_crossing_grant_authority().ok_or_else(|| {
        String::from("active crossing transaction has no matching verified grant admission")
    })?;
    let crossing = receipt.crossing.as_mut().ok_or_else(|| {
        String::from("active crossing transaction cannot be attached without a crossing record")
    })?;
    let transaction_id = authority
        .transaction
        .as_ref()
        .and_then(|transaction| transaction.get("transaction_id"))
        .and_then(JsonValue::as_str)
        .ok_or_else(|| {
            String::from("terminal crossing transaction is missing its transaction identity")
        })?;
    if crossing.id != transaction_id {
        return Err(String::from(
            "crossing record identity does not match the active crossing transaction",
        ));
    }
    crossing.authority = Some(authority);
    Ok(())
}

fn finalize_active_proof_crossing_transaction(
    ok: bool,
    interrupted: bool,
    status: &str,
    proof_execution_id: &str,
) -> Result<Option<ProofRuntimeCrossingEvidence>, String> {
    let Some(transaction) = ACTIVE_CROSSING_TRANSACTION.with(|active| active.borrow().clone())
    else {
        return Ok(None);
    };
    let state = if ok {
        "completed"
    } else if interrupted {
        "interrupted"
    } else {
        "failed"
    };
    let receipt_status = format!("proof:{proof_execution_id}:{status}");
    transaction
        .borrow_mut()
        .finalize(state, Some(receipt_status.as_str()))?;
    #[cfg(unix)]
    {
        let terminal_transaction = transaction.borrow().evidence();
        persist_active_systemd_execution_completion(
            &terminal_transaction,
            None,
            ok,
            interrupted,
            Some(proof_command_exit_code(ok, interrupted)),
            receipt_status.as_str(),
        )?;
    }
    let authority = active_crossing_grant_authority().ok_or_else(|| {
        String::from("proof crossing transaction has no matching verified authority admission")
    })?;
    let transaction = active_crossing_transaction_evidence().ok_or_else(|| {
        String::from("proof crossing transaction disappeared before evidence emission")
    })?;
    Ok(Some(ProofRuntimeCrossingEvidence {
        receipt_archive_identity: None,
        receipt_archive_path: None,
        transaction_id: transaction.transaction_id,
        proof_execution_id: Some(proof_execution_id.to_string()),
        scope_identity: authority.scope_identity.clone(),
        authority: Some(authority),
    }))
}

fn proof_command_exit_code(ok: bool, interrupted: bool) -> i32 {
    if ok {
        0
    } else if interrupted {
        130
    } else {
        1
    }
}

fn fail_active_proof_crossing_transaction(
    message: impl Into<String>,
    proof_execution_id: &str,
) -> CommandOutput {
    let message = message.into();
    if !active_crossing_transaction_is_pending() {
        return CommandOutput::failure(message);
    }
    match finalize_active_proof_crossing_transaction(
        false,
        false,
        "failed_before_terminal_output",
        proof_execution_id,
    ) {
        Ok(_) => CommandOutput::failure(message),
        Err(error) => CommandOutput::failure(format!(
            "{message}; proof crossing finalization failed: {error}"
        )),
    }
}

fn crossing_grant_authority_output_with_transaction(
    admission: &GrantAdmissionEvidence,
    transaction: Option<crate::crossing_transaction::CrossingTransactionEvidence>,
    include_carrier_admission: bool,
) -> crate::output::ExecutionBoundaryCrossingAuthority {
    crate::output::ExecutionBoundaryCrossingAuthority {
        decision: admission.decision.clone(),
        authority_carrier: None,
        authority_id: admission.authority_id.clone(),
        authority_separation_posture: String::from("current_process_filesystem_guarded"),
        authority_binding_identity: admission.authority_binding_identity.clone(),
        broker: None,
        issuer_id: Some(admission.issuer_id.clone()),
        key_id: Some(admission.key_id.clone()),
        key_fingerprint: Some(admission.key_fingerprint.clone()),
        bundle_id: Some(admission.bundle_id.clone()),
        bundle_identity: Some(admission.bundle_identity.clone()),
        bundle_sequence: Some(admission.bundle_sequence),
        grant_id: Some(admission.grant_id.clone()),
        grant_identity: Some(admission.grant_identity.clone()),
        scope_identity: admission.scope_identity.clone(),
        contract_identity: admission.contract_identity.clone(),
        boundary_family: admission.boundary_family.clone(),
        classification: admission.classification.clone(),
        actor_mode: admission.actor_mode.clone(),
        environment_posture: Some(admission.environment_posture.clone()),
        expiry_kind: Some(admission.expiry_kind.clone()),
        issued_at: Some(admission.issued_at.clone()),
        not_before: Some(admission.not_before.clone()),
        next_update: Some(admission.next_update.clone()),
        expires_at: Some(admission.expires_at.clone()),
        clock_evidence: Some(admission.clock_evidence.clone()),
        sequence_evidence: Some(admission.sequence_evidence.clone()),
        revocation_evidence: Some(admission.revocation_evidence.clone()),
        admitted_at: admission.admitted_at.clone(),
        transaction: transaction
            .as_ref()
            .map(|evidence| serde_json::to_value(evidence).expect("transaction should serialize")),
        archive_evidence: serde_json::to_value(ArchivedCrossingGrantEvidence {
            admission: admission.clone(),
            carrier_admission: include_carrier_admission.then(|| {
                admission
                    .crossing_admission()
                    .expect("verified crossing grant admission should derive its carrier envelope")
            }),
            transaction,
        })
        .expect("verified crossing grant admission should serialize"),
    }
}

fn crossing_authority_output_with_transaction(
    admission: &VerifiedCrossingAuthorityAdmission,
    transaction: Option<crate::crossing_transaction::CrossingTransactionEvidence>,
    include_carrier_admission: bool,
) -> Result<crate::output::ExecutionBoundaryCrossingAuthority, String> {
    match admission {
        VerifiedCrossingAuthorityAdmission::PreboundFile(admission) => {
            Ok(crossing_grant_authority_output_with_transaction(
                admission,
                transaction,
                include_carrier_admission,
            ))
        }
        VerifiedCrossingAuthorityAdmission::AuthorityBrokerPreview { .. } => Err(String::from(
            "broker preview evidence cannot be attached to an execution receipt",
        )),
        VerifiedCrossingAuthorityAdmission::AuthorityBroker(admission) => {
            let transaction = transaction.ok_or_else(|| {
                String::from("broker authority output requires a consumed crossing transaction")
            })?;
            let archive =
                crate::broker_session::build_broker_archive_evidence(admission, &transaction)?;
            Ok(crate::output::ExecutionBoundaryCrossingAuthority {
                decision: String::from("allowed"),
                authority_carrier: Some(String::from("authority_broker")),
                authority_id: admission.binding_snapshot.authority_id.clone(),
                authority_separation_posture: String::from(
                    admission.authority_separation_posture(),
                ),
                authority_binding_identity: admission.binding_snapshot.identity.clone(),
                broker: Some(crate::output::ExecutionBoundaryBrokerAuthority {
                    admission_identity: admission.identity.clone(),
                    attestation_identity: admission.attestation_identity.clone(),
                    authorization_decision_identity: admission
                        .authorization_decision_identity
                        .clone(),
                    prepared_lease_identity: admission.prepared_lease_identity.clone(),
                    work_unit_identity: admission.challenge.work_unit_identity.clone(),
                    challenge_nonce_commitment: admission.challenge.nonce_commitment.clone(),
                    broker_revision: admission.broker_revision,
                    runner_principal: admission.attestation.runner_principal().to_string(),
                    approval_reference: admission
                        .authorization_decision
                        .payload
                        .approval_reference
                        .clone(),
                }),
                issuer_id: None,
                key_id: None,
                key_fingerprint: None,
                bundle_id: None,
                bundle_identity: None,
                bundle_sequence: None,
                grant_id: None,
                grant_identity: None,
                scope_identity: admission.semantic_scope.identity.clone(),
                contract_identity: admission.semantic_scope.contract_identity.clone(),
                boundary_family: admission.semantic_scope.boundary_family.clone(),
                classification: admission.semantic_scope.classification.clone(),
                actor_mode: admission.actor_mode.clone(),
                environment_posture: None,
                expiry_kind: None,
                issued_at: None,
                not_before: None,
                next_update: None,
                expires_at: Some(admission.prepared_lease.payload.expires_at.clone()),
                clock_evidence: None,
                sequence_evidence: None,
                revocation_evidence: None,
                admitted_at: admission.admitted_at.clone(),
                transaction: Some(
                    serde_json::to_value(&transaction).map_err(|error| {
                        format!("failed to serialize broker transaction: {error}")
                    })?,
                ),
                archive_evidence: serde_json::to_value(archive)
                    .map_err(|error| format!("failed to serialize broker archive: {error}"))?,
            })
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn evaluate_task_crossing_grant(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    overrides: ExecutionOverrides,
    task_inputs: &[String],
    effect_overrides: &[String],
    agent: bool,
    grant: Option<&str>,
    sandbox_target: Option<&str>,
) -> Result<Option<CrossingAuthorityPlan>, GrantAdmissionError> {
    let task_name = canonical_declared_task_name(contract, task_name);
    if proof_parent_authorizes_invocation(
        contract,
        contract_path,
        &["proof_task", "workflow_task"],
        task_name.as_str(),
    )? {
        if grant.is_some() {
            return Err(GrantAdmissionError::new(
                "proof_parent_authority_conflict",
                "a proof child invocation cannot also select independent crossing authority",
            ));
        }
        return Ok(None);
    }
    let authority_configured = contract.governance.crossing_authority.is_some();
    if !authority_configured {
        return match grant {
            Some(_) => Err(GrantAdmissionError::new(
                "crossing_authority_missing",
                "`--grant` requires `governance.crossing_authority.authority_id` in the selected contract",
            )),
            None => Ok(None),
        };
    }

    let safety = task_effective_safety_with_overrides(contract, task_name.as_str(), overrides);
    let requirement = evaluate_crossing_requirement(
        Some(safety.effective_safe),
        false,
        &safety.unsafe_closure_tasks,
        "task",
    );
    evaluate_selected_crossing_grant(
        contract,
        contract_path,
        crossing_scope_for_task(
            contract,
            task_name.as_str(),
            overrides,
            task_inputs,
            effect_overrides,
            sandbox_target,
            requirement
                .boundary_family
                .map(|family| family.label())
                .unwrap_or("unknown"),
            requirement
                .classification
                .map(|classification| classification.label())
                .unwrap_or("unknown"),
        ),
        requirement,
        agent,
        grant,
    )
}

#[allow(clippy::too_many_arguments)]
fn evaluate_workflow_crossing_grant(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    effect_overrides: &[String],
    run_behavior_preference: UpRunBehaviorPreference,
    ready_timeout: Option<Duration>,
    agent: bool,
    grant: Option<&str>,
    sandbox_target: Option<&str>,
) -> Result<Option<CrossingAuthorityPlan>, GrantAdmissionError> {
    let selected_workflow = contract
        .selected_workflow(workflow_name)
        .map(|(name, _)| name)
        .unwrap_or_else(|| workflow_name.unwrap_or("default"));
    if proof_parent_authorizes_invocation(
        contract,
        contract_path,
        &["workflow"],
        selected_workflow,
    )? {
        if grant.is_some() {
            return Err(GrantAdmissionError::new(
                "proof_parent_authority_conflict",
                "a proof child workflow cannot also select independent crossing authority",
            ));
        }
        return Ok(None);
    }
    let authority_configured = contract.governance.crossing_authority.is_some();
    if !authority_configured {
        return match grant {
            Some(_) => Err(GrantAdmissionError::new(
                "crossing_authority_missing",
                "`--grant` requires `governance.crossing_authority.authority_id` in the selected contract",
            )),
            None => Ok(None),
        };
    }

    let safety =
        selected_up_workflow_effective_safety(contract, workflow_name, run_behavior_preference);
    let requirement = evaluate_crossing_requirement(
        safety.effective_safe,
        false,
        &safety.unsafe_closure_tasks,
        "workflow",
    );
    if agent && requirement.required == Some(true) {
        // V11.3 agent safety is a harder boundary than a human crossing grant.
        // The existing agent refusal path remains authoritative and a grant cannot bypass it.
        return Ok(None);
    }
    evaluate_selected_crossing_grant(
        contract,
        contract_path,
        crossing_scope_for_workflow(
            contract,
            workflow_name,
            overrides,
            effect_overrides,
            sandbox_target,
            up_run_behavior_preference_label(run_behavior_preference),
            ready_timeout.map(|timeout| timeout.as_secs()),
            requirement
                .boundary_family
                .map(|family| family.label())
                .unwrap_or("unknown"),
            requirement
                .classification
                .map(|classification| classification.label())
                .unwrap_or("unknown"),
        ),
        requirement,
        agent,
        grant,
    )
}

/// Evaluates one proof transaction, including declared proof-only tasks, before the proof can
/// create artifacts or start its primary workflow. These roots are intentionally part of the
/// signed scope rather than post-workflow helpers.
#[allow(clippy::too_many_arguments)]
fn evaluate_proof_workflow_crossing_grant(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    proof_invocations: &[CrossingProofInvocation],
    proof_transaction_selection: CrossingProofTransactionSelection,
    proof_kind: &str,
    agent: bool,
    grant: Option<&str>,
) -> Result<Option<CrossingAuthorityPlan>, GrantAdmissionError> {
    let authority_configured = contract.governance.crossing_authority.is_some();
    if !authority_configured {
        return match grant {
            Some(_) => Err(GrantAdmissionError::new(
                "crossing_authority_missing",
                "`--grant` requires `governance.crossing_authority.authority_id` in the selected contract",
            )),
            None => Ok(None),
        };
    }
    let proof_roots = proof_invocations
        .iter()
        .map(|invocation| invocation.task.clone())
        .collect::<Vec<_>>();
    let policy = crate::sandbox_policy::sandbox_policy_for_workflow_with_proof_roots(
        contract,
        workflow_name,
        overrides,
        &proof_roots,
    )
    .map_err(|details| {
        GrantAdmissionError::new(
            "crossing_scope_unavailable",
            format!("failed to derive the canonical proof crossing scope: {details}"),
        )
    })?;
    let mut unsafe_closure_tasks = policy
        .segments
        .iter()
        .filter_map(|segment| {
            (!task_effective_safety_with_overrides(
                contract,
                segment.task.as_str(),
                ExecutionOverrides {
                    backend: Some(segment.backend),
                    ..overrides
                },
            )
            .effective_safe)
                .then(|| segment.task.clone())
        })
        .collect::<Vec<_>>();
    unsafe_closure_tasks.sort();
    unsafe_closure_tasks.dedup();
    let requirement = evaluate_crossing_requirement(
        Some(unsafe_closure_tasks.is_empty()),
        false,
        &unsafe_closure_tasks,
        "workflow",
    );
    if agent && requirement.required == Some(true) {
        return Err(GrantAdmissionError::new(
            "requested_workflow_not_safe",
            "the proof transaction includes a task outside the agent-safe closure",
        ));
    }
    evaluate_selected_crossing_grant(
        contract,
        contract_path,
        crossing_scope_from_policy(
            policy,
            overrides,
            &[],
            &[],
            None,
            Some(proof_kind),
            None,
            requirement
                .boundary_family
                .map(|family| family.label())
                .unwrap_or("unknown"),
            requirement
                .classification
                .map(|classification| classification.label())
                .unwrap_or("unknown"),
        )
        .and_then(|scope| {
            crossing_scope_with_workflow_instance_selection(scope, contract, workflow_name)
        })
        .and_then(|scope| crossing_scope_with_proof_invocations(scope, proof_invocations.to_vec()))
        .and_then(|scope| {
            crossing_scope_with_proof_transaction_selection(scope, proof_transaction_selection)
        }),
        requirement,
        agent,
        grant,
    )
}

fn evaluate_selected_crossing_grant(
    contract: &Contract,
    contract_path: &Path,
    scope: Result<crate::crossing::CrossingSemanticScope, String>,
    requirement: crate::crossing::CrossingRequirement,
    agent: bool,
    grant: Option<&str>,
) -> Result<Option<CrossingAuthorityPlan>, GrantAdmissionError> {
    match requirement.required {
        Some(false) => {
            return match grant {
                Some(_) => Err(GrantAdmissionError::new(
                    "crossing_grant_inapplicable",
                    "the selected execution closure does not cross a governed boundary",
                )),
                None => Ok(None),
            };
        }
        None => {
            return Err(GrantAdmissionError::new(
                "crossing_requirement_unknown",
                "Ota cannot derive whether the selected closure requires an authority grant",
            ));
        }
        Some(true) => {}
    }
    let scope = scope.map_err(|details| {
        GrantAdmissionError::new(
            "crossing_scope_unavailable",
            format!("failed to derive the canonical crossing scope: {details}"),
        )
    })?;
    let boundary_family = requirement
        .boundary_family
        .map(|family| family.label())
        .ok_or_else(|| {
            GrantAdmissionError::new(
                "crossing_requirement_invalid",
                "a required crossing is missing its derived boundary family",
            )
        })?;
    let classification = requirement
        .classification
        .map(|classification| classification.label())
        .ok_or_else(|| {
            GrantAdmissionError::new(
                "crossing_requirement_invalid",
                "a required crossing is missing its derived classification",
            )
        })?;
    let authority_id = contract
        .governance
        .crossing_authority
        .as_ref()
        .map(|authority| authority.authority_id.trim())
        .filter(|authority| !authority.is_empty())
        .ok_or_else(|| {
            GrantAdmissionError::new(
                "crossing_authority_missing",
                "the selected contract does not name a crossing authority",
            )
        })?;
    let selected = crate::crossing_authority::select_crossing_authority_binding(
        contract_working_dir(contract_path),
        authority_id,
    )
    .or_else(|error| {
        if grant.is_none() && error.reason == "crossing_authority_unknown" {
            Err(GrantAdmissionError::new(
                "crossing_grant_required",
                "the selected execution closure crosses a governed boundary and requires `--grant <id>` unless the contract authority resolves to a protected broker binding",
            )
            .with_scope(scope.clone()))
        } else {
            Err(error.with_scope(scope.clone()))
        }
    })?;
    match selected {
        crate::crossing_authority::SelectedCrossingAuthorityBinding::PreboundFile(_) => {
            let grant = grant.ok_or_else(|| {
                GrantAdmissionError::new(
                    "crossing_grant_required",
                    "the selected execution closure crosses a governed boundary and requires `--grant <id>`",
                )
                .with_scope(scope.clone())
            })?;
            admit_prebound_file_grant(
                contract,
                contract_working_dir(contract_path),
                &scope,
                grant,
                boundary_family,
                classification,
                grant_actor_mode_label(agent),
                OffsetDateTime::now_utc(),
            )
            .map(|admission| Some(CrossingAuthorityPlan::PreboundFile(admission)))
            .map_err(|error| error.with_scope(scope))
        }
        crate::crossing_authority::SelectedCrossingAuthorityBinding::AuthorityBroker(binding) => {
            if let Some(selected_authority) = grant
                && selected_authority != authority_id
            {
                return Err(GrantAdmissionError::new(
                    "crossing_authority_selection_mismatch",
                    "`--grant` may only select the contract-bound broker authority label; broker lease identities are not caller inputs",
                )
                .with_authority_source("authority_broker")
                .with_scope(scope));
            }
            Ok(Some(CrossingAuthorityPlan::AuthorityBroker {
                binding,
                semantic_scope: scope,
                actor_mode: grant_actor_mode_label(agent).to_string(),
            }))
        }
    }
}

fn build_task_crossing_record(
    contract: &Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
    agent: bool,
    reason: Option<&str>,
) -> Option<crate::output::ExecutionBoundaryCrossing> {
    let task_name = canonical_declared_task_name(contract, task_name);
    let safety = task_effective_safety(contract, task_name.as_str());
    let (crossing_required, crossing_classification, crossing_boundary_family) =
        crossing_preflight_posture(
            Some(safety.effective_safe),
            false,
            &safety.unsafe_closure_tasks,
            "task",
        );
    if crossing_required != Some(true) {
        return None;
    }

    let _ = overrides;
    Some(crate::output::ExecutionBoundaryCrossing {
        id: new_crossing_id(),
        created_at: crossing_created_at(),
        lane_id: format!("task:{task_name}"),
        lane_kind: String::from("task"),
        boundary_family: crossing_boundary_family.unwrap_or_else(|| String::from("unsafe_task")),
        classification: crossing_classification.unwrap_or_else(|| String::from("escalated")),
        requirement_source: String::from("derived"),
        actor_mode: actor_mode_label(agent).to_string(),
        principal_attribution_state: String::from("runner_mode_only"),
        intent_source: if reason.is_some() {
            String::from("caller_supplied")
        } else {
            String::from("runner_defaulted")
        },
        reason_present: reason.is_some(),
        reason: reason.map(str::to_string),
        evidence_attachment_state: String::from("receipt_attached"),
        evidence_classes: crossing_evidence_classes(reason.is_some()),
        authority: active_crossing_grant_authority(),
    })
}

fn build_workflow_crossing_record(
    contract: &Contract,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    run_behavior_preference: UpRunBehaviorPreference,
    agent: bool,
    reason: Option<&str>,
) -> Option<crate::output::ExecutionBoundaryCrossing> {
    let safety =
        selected_up_workflow_effective_safety(contract, workflow_name, run_behavior_preference);
    let (crossing_required, crossing_classification, crossing_boundary_family) =
        crossing_preflight_posture(
            safety.effective_safe,
            false,
            &safety.unsafe_closure_tasks,
            "workflow",
        );
    if crossing_required != Some(true) {
        return None;
    }

    let _ = overrides;
    Some(crate::output::ExecutionBoundaryCrossing {
        id: new_crossing_id(),
        created_at: crossing_created_at(),
        lane_id: format!("workflow:{}", workflow_name.unwrap_or("default")),
        lane_kind: String::from("workflow"),
        boundary_family: crossing_boundary_family.unwrap_or_else(|| String::from("unsafe_task")),
        classification: crossing_classification.unwrap_or_else(|| String::from("escalated")),
        requirement_source: String::from("derived"),
        actor_mode: actor_mode_label(agent).to_string(),
        principal_attribution_state: String::from("runner_mode_only"),
        intent_source: if reason.is_some() {
            String::from("caller_supplied")
        } else {
            String::from("runner_defaulted")
        },
        reason_present: reason.is_some(),
        reason: reason.map(str::to_string),
        evidence_attachment_state: String::from("receipt_attached"),
        evidence_classes: crossing_evidence_classes(reason.is_some()),
        authority: active_crossing_grant_authority(),
    })
}

fn attach_task_crossing_to_receipt(
    receipt: &mut ExecutionReceipt,
    contract: &Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
    agent: bool,
    reason: Option<&str>,
) {
    receipt.crossing =
        build_task_crossing_record(contract, task_name, overrides, agent, reason).map(Box::new);
}

fn attach_workflow_crossing_to_receipt(
    receipt: &mut ExecutionReceipt,
    contract: &Contract,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    run_behavior_preference: UpRunBehaviorPreference,
    agent: bool,
    reason: Option<&str>,
) {
    let existing_authority = receipt
        .crossing
        .as_ref()
        .and_then(|crossing| crossing.authority.clone());
    let mut crossing = build_workflow_crossing_record(
        contract,
        workflow_name,
        overrides,
        run_behavior_preference,
        agent,
        reason,
    );
    if let Some(crossing) = crossing.as_mut()
        && crossing.authority.is_none()
    {
        crossing.authority = existing_authority;
    }
    receipt.crossing = crossing.map(Box::new);
}

fn up_lane_proof_expected(
    contract: &Contract,
    workflow_name: Option<&str>,
    _overrides: ExecutionOverrides,
    _run_behavior_preference: UpRunBehaviorPreference,
) -> bool {
    contract.selected_workflow(workflow_name).is_some()
}

fn up_phase_proof_present(phase: &str) -> bool {
    matches!(
        phase,
        "services" | "readiness" | "post-up diagnosis" | "cleanup"
    )
}

fn task_harness_environment_boundary(task: &TaskSummary<'_>) -> Option<HarnessEnvironmentBoundary> {
    Some(HarnessEnvironmentBoundary {
        kind: String::from("task"),
        backend: Some(task.effective_default_mode.to_string()),
        context: task.context.map(str::to_string),
        default_mode: Some(task.effective_default_mode.to_string()),
        primary_task: None,
    })
}

fn harness_effect_policy_binding(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    roots: &[EffectPolicyInvocation],
    loaded_policy: Result<Option<&LoadedOrgPolicyPack>, &str>,
) -> HarnessEffectPolicyBinding {
    let typed_applicable =
        match typed_effect_closure_applies(contract, roots, ExecutionOverrides::default()) {
            Ok(applicable) => applicable,
            Err(error) => {
                return HarnessEffectPolicyBinding {
                    status: String::from("unavailable"),
                    aggregate_decision: None,
                    decision_identity: None,
                    policy_snapshot_identity: None,
                    execution_graph_identity: None,
                    effect_set_identity: None,
                    provider_execution: String::from("disabled"),
                    error: Some(error.to_string()),
                };
            }
        };
    if !typed_applicable {
        return HarnessEffectPolicyBinding {
            status: String::from("not_applicable"),
            aggregate_decision: None,
            decision_identity: None,
            policy_snapshot_identity: None,
            execution_graph_identity: None,
            effect_set_identity: None,
            provider_execution: String::from("not_applicable"),
            error: None,
        };
    }
    let loaded_policy = match loaded_policy {
        Ok(loaded) => loaded,
        Err(error) => {
            return HarnessEffectPolicyBinding {
                status: String::from("unavailable"),
                aggregate_decision: None,
                decision_identity: None,
                policy_snapshot_identity: None,
                execution_graph_identity: None,
                effect_set_identity: None,
                provider_execution: String::from("disabled"),
                error: Some(error.to_string()),
            };
        }
    };
    let admission = match admit_typed_effect_closure_from_loaded_policy(
        contract,
        contract_path,
        workflow_name,
        roots,
        ExecutionOverrides::default(),
        loaded_policy,
        Some(&current_effect_governance_overrides()),
    ) {
        Ok(admission) => admission,
        Err(error) => {
            return HarnessEffectPolicyBinding {
                status: String::from("unavailable"),
                aggregate_decision: None,
                decision_identity: None,
                policy_snapshot_identity: None,
                execution_graph_identity: None,
                effect_set_identity: None,
                provider_execution: String::from("disabled"),
                error: Some(error.to_string()),
            };
        }
    };
    if admission.closure.application_plans.is_empty() {
        return HarnessEffectPolicyBinding {
            status: String::from("unavailable"),
            aggregate_decision: None,
            decision_identity: None,
            policy_snapshot_identity: None,
            execution_graph_identity: None,
            effect_set_identity: None,
            provider_execution: String::from("disabled"),
            error: Some(String::from(
                "typed effect capability did not retain its application plans",
            )),
        };
    }
    match admission.policy_decision {
        Some(decision) => HarnessEffectPolicyBinding {
            status: String::from("evaluated"),
            aggregate_decision: Some(decision.aggregate_decision.as_str().to_string()),
            decision_identity: Some(decision.identity),
            policy_snapshot_identity: Some(decision.policy_snapshot_identity),
            execution_graph_identity: Some(decision.execution_graph_identity),
            effect_set_identity: Some(decision.effect_set_identity),
            provider_execution: String::from("disabled"),
            error: None,
        },
        None => HarnessEffectPolicyBinding {
            status: String::from("unavailable"),
            aggregate_decision: None,
            decision_identity: None,
            policy_snapshot_identity: None,
            execution_graph_identity: None,
            effect_set_identity: None,
            provider_execution: String::from("disabled"),
            error: Some(String::from(
                "typed effect capability did not produce an effect-policy decision",
            )),
        },
    }
}

fn bind_effect_policy_to_harness_preflight(
    preflight: &mut crate::output::GovernancePreflightEvaluation,
    binding: &HarnessEffectPolicyBinding,
) {
    if binding.status == "not_applicable" {
        return;
    }
    let reason = if binding.status == "unavailable" {
        "effect_policy_unavailable"
    } else if binding.aggregate_decision.as_deref() == Some("deny") {
        "effect_policy_denied"
    } else {
        "typed_effect_provider_execution_disabled"
    };
    preflight.state = String::from("refused");
    preflight.review_required = Some(true);
    preflight.refusal_reason_family = Some(reason.to_string());
    preflight
        .decision_basis
        .push(crate::output::GovernanceDecisionBasisEntry {
            id: format!("effect_policy:{reason}"),
            family: String::from("effect_policy_gate"),
            evidence_class: String::from("derived"),
            detail: binding.decision_identity.clone(),
        });
    preflight
        .decision_inputs
        .push(crate::output::GovernanceDecisionInputEntry {
            id: binding.decision_identity.as_ref().map_or_else(
                || format!("effect_policy:{reason}"),
                |identity| format!("effect_policy_decision:{identity}"),
            ),
            family: String::from("effect_policy_decision"),
            evidence_class: String::from("derived"),
            replay_class: String::from("pinned"),
            detail: binding.aggregate_decision.clone(),
        });
    preflight.evidence_classes.review_required = Some(String::from("derived"));
    preflight.evidence_classes.refusal_reason_family = Some(String::from("derived"));
    preflight.replay = reconcile_preflight_replay(preflight);
}

fn task_harness_capability(
    contract: &Contract,
    contract_path: &Path,
    agent: Option<&AgentSummary<'_>>,
    task: &TaskSummary<'_>,
    loaded_policy: Result<Option<&LoadedOrgPolicyPack>, &str>,
) -> HarnessLaneCapability {
    let refusal =
        agent_execution_refusal_for_task(contract, task.name, ExecutionOverrides::default());
    let effects =
        collect_task_closure_effects_summary(contract, task.name, ExecutionOverrides::default());
    let effect_policy = harness_effect_policy_binding(
        contract,
        contract_path,
        None,
        &[EffectPolicyInvocation {
            task: task.name.to_string(),
            origin: String::from("task_capability"),
        }],
        loaded_policy,
    );
    let mut preflight = harness_preflight_for_task(task, refusal.as_ref());
    bind_effect_policy_to_harness_preflight(&mut preflight, &effect_policy);
    HarnessLaneCapability {
        lane_id: format!("task:{}", task.name),
        lane_kind: String::from("task"),
        name: task.name.to_string(),
        command: format!("ota run {} --agent", task.name),
        environment_boundary: task_harness_environment_boundary(task),
        preflight,
        sandbox_policy: Some(compiled_codex_local_sandbox_policy_for_task(
            contract, agent, task.name, &effects,
        )),
        effect_policy,
        effects: (!effects.is_empty()).then_some(effects),
        blocked_task: refusal.as_ref().map(|entry| entry.blocked_task.clone()),
        closure_path: refusal.map(|entry| entry.path).unwrap_or_default(),
    }
}

fn workflow_agent_refusal(
    contract: &Contract,
    workflow_name: &str,
) -> Option<AgentExecutionRefusal> {
    selected_up_agent_task_names(contract, Some(workflow_name), UpRunBehaviorPreference::Auto)
        .into_iter()
        .find_map(|task_name| {
            agent_execution_refusal_for_task(
                contract,
                task_name.as_str(),
                ExecutionOverrides::default(),
            )
        })
}

fn workflow_harness_environment_boundary(
    contract: &Contract,
    workflow: &WorkflowSummary<'_>,
) -> Option<HarnessEnvironmentBoundary> {
    let primary_task = selected_up_run_task_name(contract, Some(workflow.name))
        .or_else(|| selected_up_setup_task_name(contract, Some(workflow.name)))
        .or_else(|| selected_up_prepare_task_name(contract, Some(workflow.name)))?;
    let effective = effective_task_execution(contract, primary_task, ExecutionOverrides::default());
    Some(HarnessEnvironmentBoundary {
        kind: String::from("workflow"),
        backend: Some(format_backend(effective.backend).to_string()),
        context: effective.context_name.map(str::to_string),
        default_mode: None,
        primary_task: Some(primary_task.to_string()),
    })
}

fn workflow_effects_summary(
    contract: &Contract,
    workflow_name: &str,
) -> crate::output::TaskEffectsSummary {
    let mut summary = crate::output::TaskEffectsSummary::default();
    let mut seen_declared = BTreeSet::new();
    let mut seen_writes = BTreeSet::new();
    let mut seen_workspace_writes = BTreeSet::new();
    let mut seen_adapter_state = BTreeSet::new();
    let mut seen_external_state = BTreeSet::new();
    for task_name in
        selected_up_agent_task_names(contract, Some(workflow_name), UpRunBehaviorPreference::Auto)
    {
        let task_summary = collect_task_closure_effects_summary(
            contract,
            task_name.as_str(),
            ExecutionOverrides::default(),
        );
        summary.network |= task_summary.network;
        if let Some(kind) = task_summary.network_kind {
            summary.network_kind = merge_network_kind(summary.network_kind, kind);
        }
        for effect in task_summary.declared {
            if seen_declared.insert(effect.clone()) {
                summary.declared.push(effect);
            }
        }
        for path in task_summary.writes {
            if seen_writes.insert(path.clone()) {
                summary.writes.push(path);
            }
        }
        for path in task_summary.workspace_writes {
            if seen_workspace_writes.insert(path.clone()) {
                summary.workspace_writes.push(path);
            }
        }
        for value in task_summary.adapter_state {
            if seen_adapter_state.insert(value.clone()) {
                summary.adapter_state.push(value);
            }
        }
        for value in task_summary.external_state {
            if seen_external_state.insert(value.clone()) {
                summary.external_state.push(value);
            }
        }
    }
    summary
}

fn harness_preflight_for_workflow(
    contract: &Contract,
    workflow: &WorkflowSummary<'_>,
    refusal: Option<&AgentExecutionRefusal>,
) -> crate::output::GovernancePreflightEvaluation {
    let (crossing_required, crossing_classification, crossing_boundary_family) =
        crossing_preflight_posture(
            workflow.effective_safe_for_agent,
            refusal.is_some(),
            &workflow.unsafe_closure_tasks,
            "workflow",
        );
    let decision_basis = governance_preflight_decision_basis(
        workflow.declared_safe_for_agent,
        workflow.effective_safe_for_agent,
        refusal,
        &workflow.unsafe_closure_tasks,
        crossing_required,
        crossing_classification.as_deref(),
        crossing_boundary_family.as_deref(),
    );
    let review_required = workflow.effective_safe_for_agent.map(std::ops::Not::not);
    let refusal_reason_family = refusal.map(|entry| entry.reason);
    let crossing_classification_for_evidence = crossing_classification.clone();
    let crossing_boundary_family_for_evidence = crossing_boundary_family.clone();
    let proof_expected = up_lane_proof_expected(
        contract,
        Some(workflow.name),
        ExecutionOverrides::default(),
        UpRunBehaviorPreference::Auto,
    );
    let mut evaluation = crate::output::GovernancePreflightEvaluation {
        state: if refusal.is_some() {
            String::from("refused")
        } else {
            String::from("allowed")
        },
        sandbox_admission: None,
        review_required,
        declared_safe_for_agent: workflow.declared_safe_for_agent,
        effective_safe_for_agent: workflow.effective_safe_for_agent,
        unsafe_closure_tasks: workflow.unsafe_closure_tasks.clone(),
        refusal_reason_family: refusal_reason_family.map(str::to_string),
        refusal: refusal.map(AgentExecutionRefusal::governance_record),
        crossing_required,
        crossing_classification,
        crossing_boundary_family,
        decision_basis,
        decision_inputs: governance_preflight_decision_inputs(
            &format!("workflow:{}", workflow_selector_from_summary(workflow)),
            "workflow",
            "agent",
            "workflow_agent_capability_preflight",
            None,
            workflow.declared_safe_for_agent,
            workflow.effective_safe_for_agent,
            &workflow.unsafe_closure_tasks,
            refusal,
            true,
            proof_expected,
        ),
        replay: crate::output::GovernanceReplayResult {
            status: String::new(),
            mismatches: Vec::new(),
        },
        evidence_classes: governance_preflight_evidence_classes(
            review_required,
            workflow.declared_safe_for_agent,
            workflow.effective_safe_for_agent,
            &workflow.unsafe_closure_tasks,
            refusal_reason_family,
            refusal.is_some(),
            crossing_required,
            crossing_classification_for_evidence.as_deref(),
            crossing_boundary_family_for_evidence.as_deref(),
        ),
        receipt_expected: true,
        proof_expected,
    };
    evaluation.replay = reconcile_preflight_replay(&evaluation);
    evaluation
}

fn workflow_harness_capability(
    contract: &Contract,
    contract_path: &Path,
    agent: Option<&AgentSummary<'_>>,
    workflow: &WorkflowSummary<'_>,
    loaded_policy: Result<Option<&LoadedOrgPolicyPack>, &str>,
) -> HarnessLaneCapability {
    let selector = workflow_selector_from_summary(workflow);
    let refusal = workflow_agent_refusal(contract, workflow.name);
    let effects = workflow_effects_summary(contract, workflow.name);
    let effect_policy = harness_effect_policy_binding(
        contract,
        contract_path,
        Some(workflow.name),
        selected_workflow_phase_task_roots(contract, Some(workflow.name)).as_slice(),
        loaded_policy,
    );
    let mut preflight = harness_preflight_for_workflow(contract, workflow, refusal.as_ref());
    bind_effect_policy_to_harness_preflight(&mut preflight, &effect_policy);
    HarnessLaneCapability {
        lane_id: format!("workflow:{selector}"),
        lane_kind: String::from("workflow"),
        name: selector.clone(),
        command: format!("ota up --workflow {selector} --agent"),
        environment_boundary: workflow_harness_environment_boundary(contract, workflow),
        preflight,
        sandbox_policy: Some(compiled_codex_local_sandbox_policy_for_workflow(
            contract,
            agent,
            workflow.name,
            &effects,
        )),
        effect_policy,
        effects: (!effects.is_empty()).then_some(effects),
        blocked_task: refusal.as_ref().map(|entry| entry.blocked_task.clone()),
        closure_path: refusal.map(|entry| entry.path).unwrap_or_default(),
    }
}

#[derive(Debug, Clone)]
struct EffectiveRuntimeBoundary {
    filesystem: Option<crate::schema::RuntimeBoundaryFilesystemSpec>,
    network: Option<crate::schema::RuntimeBoundaryNetworkSpec>,
    filesystem_source: Option<&'static str>,
    network_source: Option<&'static str>,
}

fn compiled_codex_local_sandbox_policy_for_task(
    contract: &Contract,
    agent: Option<&AgentSummary<'_>>,
    task_name: &str,
    effects: &crate::output::TaskEffectsSummary,
) -> crate::output::HarnessSandboxPolicy {
    let boundary = effective_runtime_boundary_for_task(contract, task_name);
    compiled_codex_local_sandbox_policy(agent, Some(effects), Some(&boundary))
}

fn compiled_codex_local_sandbox_policy_for_workflow(
    contract: &Contract,
    agent: Option<&AgentSummary<'_>>,
    workflow_name: &str,
    effects: &crate::output::TaskEffectsSummary,
) -> crate::output::HarnessSandboxPolicy {
    let boundary = effective_runtime_boundary_for_workflow(contract, workflow_name);
    compiled_codex_local_sandbox_policy(agent, Some(effects), Some(&boundary))
}

fn compiled_codex_local_sandbox_policy(
    agent: Option<&AgentSummary<'_>>,
    effects: Option<&crate::output::TaskEffectsSummary>,
    boundary: Option<&EffectiveRuntimeBoundary>,
) -> crate::output::HarnessSandboxPolicy {
    let filesystem = match boundary.and_then(|entry| entry.filesystem.as_ref()) {
        Some(filesystem) => crate::output::HarnessSandboxFilesystemPolicy {
            state: String::from("compiled"),
            repo_root_mode: filesystem
                .repo_root_mode
                .map(crate::schema::RuntimeBoundaryRepoRootMode::as_str)
                .map(str::to_string),
            writable_paths: filesystem.writable_paths.clone(),
            protected_paths: filesystem.protected_paths.clone(),
            source: boundary
                .and_then(|entry| entry.filesystem_source)
                .unwrap_or("runtime_boundary")
                .to_string(),
        },
        None => match agent {
            Some(agent)
                if !(agent.writable_paths.is_empty() && agent.protected_paths.is_empty()) =>
            {
                crate::output::HarnessSandboxFilesystemPolicy {
                    state: String::from("compiled"),
                    repo_root_mode: Some(String::from("read_only")),
                    writable_paths: agent.writable_paths.clone(),
                    protected_paths: agent.protected_paths.clone(),
                    source: String::from("agent_boundary_derived"),
                }
            }
            _ => crate::output::HarnessSandboxFilesystemPolicy {
                state: String::from("unavailable"),
                repo_root_mode: None,
                writable_paths: Vec::new(),
                protected_paths: Vec::new(),
                source: String::from("missing_agent_boundary"),
            },
        },
    };

    let network = match boundary.and_then(|entry| entry.network.as_ref()) {
        Some(network) => crate::output::HarnessSandboxNetworkPolicy {
            state: String::from("compiled"),
            default: network
                .default
                .unwrap_or(crate::schema::RuntimeBoundaryNetworkDefault::Deny)
                .as_str()
                .to_string(),
            scope: if network.outbound_targets.is_empty() {
                String::from("broad")
            } else {
                String::from("targeted")
            },
            enforcement: String::from("advisory_only"),
            source: boundary
                .and_then(|entry| entry.network_source)
                .unwrap_or("runtime_boundary")
                .to_string(),
            outbound_targets: network
                .outbound_targets
                .iter()
                .map(|target| crate::output::HarnessSandboxOutboundTarget {
                    kind: target.kind.as_str().to_string(),
                    value: target.value.clone(),
                    destination_shape: target
                        .destination_shape
                        .map(crate::schema::RuntimeBoundaryDestinationShape::as_str)
                        .map(str::to_string),
                    destination_constraint: target.destination_constraint.as_ref().map(
                        |constraint| crate::output::HarnessSandboxDestinationConstraint {
                            kind: constraint.kind.as_str().to_string(),
                            values: constraint.values.clone(),
                            source_posture: constraint.source_posture.as_str().to_string(),
                            enforcement: constraint.enforcement.as_str().to_string(),
                            shared_pin: constraint.shared_pin.as_ref().map(|pin| {
                                crate::output::HarnessSandboxSharedPin {
                                    r#ref: pin.r#ref.clone(),
                                    freshness: pin.freshness.as_str().to_string(),
                                }
                            }),
                        },
                    ),
                })
                .collect(),
        },
        None if effects.is_some_and(|entry| entry.network) => {
            crate::output::HarnessSandboxNetworkPolicy {
                state: String::from("compiled"),
                default: String::from("allow"),
                scope: String::from("broad"),
                enforcement: String::from("advisory_only"),
                source: String::from("lane_effect_network"),
                outbound_targets: Vec::new(),
            }
        }
        None => crate::output::HarnessSandboxNetworkPolicy {
            state: String::from("compiled"),
            default: String::from("deny"),
            scope: String::from("none"),
            enforcement: String::from("advisory_only"),
            source: String::from("no_network_effect"),
            outbound_targets: Vec::new(),
        },
    };

    crate::output::HarnessSandboxPolicy {
        target: String::from("codex_local"),
        filesystem,
        network,
    }
}

fn effective_runtime_boundary_for_task(
    contract: &Contract,
    task_name: &str,
) -> EffectiveRuntimeBoundary {
    let mut boundary = EffectiveRuntimeBoundary {
        filesystem: contract
            .execution
            .as_ref()
            .and_then(|execution| execution.runtime_boundary.as_ref())
            .and_then(|entry| entry.filesystem.clone()),
        network: contract
            .execution
            .as_ref()
            .and_then(|execution| execution.runtime_boundary.as_ref())
            .and_then(|entry| entry.network.clone()),
        filesystem_source: contract
            .execution
            .as_ref()
            .and_then(|execution| execution.runtime_boundary.as_ref())
            .and_then(|entry| entry.filesystem.as_ref())
            .map(|_| "execution.runtime_boundary"),
        network_source: contract
            .execution
            .as_ref()
            .and_then(|execution| execution.runtime_boundary.as_ref())
            .and_then(|entry| entry.network.as_ref())
            .map(|_| "execution.runtime_boundary"),
    };
    if let Some(task) = contract.tasks.get(task_name)
        && let Some(runtime_boundary) = task.runtime_boundary.as_ref()
    {
        if runtime_boundary.filesystem.is_some() {
            boundary.filesystem = runtime_boundary.filesystem.clone();
            boundary.filesystem_source = Some("tasks.<name>.runtime_boundary");
        }
        if runtime_boundary.network.is_some() {
            boundary.network = runtime_boundary.network.clone();
            boundary.network_source = Some("tasks.<name>.runtime_boundary");
        }
    }
    boundary
}

fn effective_runtime_boundary_for_workflow(
    contract: &Contract,
    workflow_name: &str,
) -> EffectiveRuntimeBoundary {
    let mut boundary = EffectiveRuntimeBoundary {
        filesystem: contract
            .execution
            .as_ref()
            .and_then(|execution| execution.runtime_boundary.as_ref())
            .and_then(|entry| entry.filesystem.clone()),
        network: contract
            .execution
            .as_ref()
            .and_then(|execution| execution.runtime_boundary.as_ref())
            .and_then(|entry| entry.network.clone()),
        filesystem_source: contract
            .execution
            .as_ref()
            .and_then(|execution| execution.runtime_boundary.as_ref())
            .and_then(|entry| entry.filesystem.as_ref())
            .map(|_| "execution.runtime_boundary"),
        network_source: contract
            .execution
            .as_ref()
            .and_then(|execution| execution.runtime_boundary.as_ref())
            .and_then(|entry| entry.network.as_ref())
            .map(|_| "execution.runtime_boundary"),
    };
    if let Some((_, workflow)) = contract.selected_workflow(Some(workflow_name))
        && let Some(runtime_boundary) = workflow.runtime_boundary.as_ref()
    {
        if runtime_boundary.filesystem.is_some() {
            boundary.filesystem = runtime_boundary.filesystem.clone();
            boundary.filesystem_source = Some("workflows.<name>.runtime_boundary");
        }
        if runtime_boundary.network.is_some() {
            boundary.network = runtime_boundary.network.clone();
            boundary.network_source = Some("workflows.<name>.runtime_boundary");
        }
    }
    if let Some(task_name) = selected_up_run_task_name(contract, Some(workflow_name))
        .or_else(|| selected_up_setup_task_name(contract, Some(workflow_name)))
        .or_else(|| selected_up_prepare_task_name(contract, Some(workflow_name)))
        && let Some(task) = contract.tasks.get(task_name)
        && let Some(runtime_boundary) = task.runtime_boundary.as_ref()
    {
        if runtime_boundary.filesystem.is_some() {
            boundary.filesystem = runtime_boundary.filesystem.clone();
            boundary.filesystem_source = Some("tasks.<name>.runtime_boundary");
        }
        if runtime_boundary.network.is_some() {
            boundary.network = runtime_boundary.network.clone();
            boundary.network_source = Some("tasks.<name>.runtime_boundary");
        }
    }
    boundary
}

fn harness_capability_profile_for_tasks(
    contract: &Contract,
    contract_path: &Path,
    agent: Option<&AgentSummary<'_>>,
    tasks: &[TaskSummary<'_>],
) -> HarnessCapabilityProfile {
    let loaded_policy = load_org_policy_pack_auto_details(contract_path);
    let loaded_policy = loaded_policy
        .as_ref()
        .map(|loaded| loaded.as_ref())
        .map_err(|error| error.to_string());
    let mut callable_tasks = Vec::new();
    let mut refused_tasks = Vec::new();
    for task in tasks {
        let capability = task_harness_capability(
            contract,
            contract_path,
            agent,
            task,
            loaded_policy
                .as_ref()
                .map(|loaded| *loaded)
                .map_err(String::as_str),
        );
        if capability.preflight.state == "allowed"
            && capability.effect_policy.status == "not_applicable"
        {
            callable_tasks.push(capability);
        } else {
            refused_tasks.push(capability);
        }
    }
    HarnessCapabilityProfile {
        actor_mode: String::from("agent"),
        posture: agent.map(|entry| entry.posture.to_string()),
        entrypoint: agent.and_then(|entry| entry.entrypoint.map(str::to_string)),
        default_task: agent.and_then(|entry| entry.default_task.map(str::to_string)),
        verify_after_changes: agent
            .map(|entry| entry.verify_after_changes.clone())
            .unwrap_or_default(),
        writable_paths: agent
            .map(|entry| entry.writable_paths.clone())
            .unwrap_or_default(),
        protected_paths: agent
            .map(|entry| entry.protected_paths.clone())
            .unwrap_or_default(),
        callable_tasks,
        refused_tasks,
        callable_workflows: Vec::new(),
        refused_workflows: Vec::new(),
    }
}

fn harness_capability_profile_for_workflows(
    contract: &Contract,
    contract_path: &Path,
    agent: Option<&AgentSummary<'_>>,
    workflows: &[ListedWorkflowSummary<'_>],
) -> HarnessCapabilityProfile {
    let loaded_policy = load_org_policy_pack_auto_details(contract_path);
    let loaded_policy = loaded_policy
        .as_ref()
        .map(|loaded| loaded.as_ref())
        .map_err(|error| error.to_string());
    let mut callable_workflows = Vec::new();
    let mut refused_workflows = Vec::new();
    for listed in workflows {
        let capability = workflow_harness_capability(
            contract,
            contract_path,
            agent,
            &listed.workflow,
            loaded_policy
                .as_ref()
                .map(|loaded| *loaded)
                .map_err(String::as_str),
        );
        if capability.preflight.state == "allowed"
            && capability.effect_policy.status == "not_applicable"
        {
            callable_workflows.push(capability);
        } else {
            refused_workflows.push(capability);
        }
    }
    HarnessCapabilityProfile {
        actor_mode: String::from("agent"),
        posture: agent.map(|entry| entry.posture.to_string()),
        entrypoint: agent.and_then(|entry| entry.entrypoint.map(str::to_string)),
        default_task: agent.and_then(|entry| entry.default_task.map(str::to_string)),
        verify_after_changes: agent
            .map(|entry| entry.verify_after_changes.clone())
            .unwrap_or_default(),
        writable_paths: agent
            .map(|entry| entry.writable_paths.clone())
            .unwrap_or_default(),
        protected_paths: agent
            .map(|entry| entry.protected_paths.clone())
            .unwrap_or_default(),
        callable_tasks: Vec::new(),
        refused_tasks: Vec::new(),
        callable_workflows,
        refused_workflows,
    }
}

pub fn tasks(
    path: Option<&Path>,
    file_override: Option<&Path>,
    members: &[String],
    workflow_name: Option<&str>,
    use_cmd: bool,
    all: bool,
    safe: bool,
    unsafe_tasks: bool,
    via_backend: Option<crate::schema::Backend>,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    if safe && unsafe_tasks {
        return finalize_debug(
            CommandOutput::failure_with_code(
                String::from("`--safe` and `--unsafe` cannot be used together"),
                2,
            ),
            debug,
            vec![String::from("DEBUG command=tasks")],
        );
    }

    if let Some(duplicate) = duplicate_member(members) {
        return finalize_debug(
            CommandOutput::failure_with_code(
                format!("`--member {duplicate}` was provided more than once"),
                2,
            ),
            debug,
            vec![String::from("DEBUG command=tasks")],
        );
    }

    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => {
                        missing_repo_contract_command_output("TASKS", "ota tasks", &error)
                            .unwrap_or_else(|| CommandOutput::failure(error.to_string()))
                    }
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=tasks")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let single_member = (members.len() == 1).then(|| members[0].as_str());
    let text_path_display = display_contract_target(&compact_path_display, single_member);
    let mut debug_lines = vec![
        String::from("DEBUG command=tasks"),
        format!("DEBUG contract_path={path_display}"),
    ];
    for member in members {
        debug_lines.push(format!("DEBUG member={member}"));
    }
    if safe {
        debug_lines.push(String::from("DEBUG filter.safety=safe"));
    }
    if unsafe_tasks {
        debug_lines.push(String::from("DEBUG filter.safety=unsafe"));
    }
    if let Some(backend) = via_backend {
        let backend_label = match backend {
            crate::schema::Backend::Native => "native",
            crate::schema::Backend::Container => "container",
            crate::schema::Backend::Remote => "remote",
        };
        debug_lines.push(format!("DEBUG filter.via_backend={backend_label}"));
    }
    let filters = TasksListFilters {
        safety: if safe {
            Some(TasksSafetyFilter::Safe)
        } else if unsafe_tasks {
            Some(TasksSafetyFilter::Unsafe)
        } else {
            None
        },
        via_backend,
    };

    if is_org_policy_pack_path(&resolved_path) {
        return finalize_debug(
            wrong_repo_contract_target_output(
                "TASKS",
                &resolved_path,
                "Wrong command target",
                &[
                    String::from("`ota tasks` reads repo contracts such as `ota.yaml`"),
                    format!(
                        "{} is an org policy pack, not a repo contract",
                        paint_code(&compact_path(&resolved_path, DEFAULT_POLICY_FILE))
                    ),
                ],
                wrong_target_next_steps_for_repo_command("ota tasks", &resolved_path),
                format,
            ),
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, single_member) {
            Ok(target) if members.is_empty() || members.len() == 1 => {
                let adjusted_contract = contract_adjusted_for_selected_workflow_env_profile(
                    &target.contract,
                    workflow_name,
                );
                let contract = adjusted_contract.as_ref().unwrap_or(&target.contract);
                let task_summaries = listed_task_summaries(contract, all, &filters);
                let agent_summary = listed_agent_summary(contract, all, &task_summaries);
                let workflow_summary = match resolve_selected_workflow_summary(
                    contract,
                    &target.contract_path,
                    workflow_name,
                ) {
                    Ok(summary) => summary,
                    Err(error) => {
                        return finalize_debug(
                            CommandOutput::failure_with_code(error, 2),
                            debug,
                            debug_lines,
                        );
                    }
                };

                if members.is_empty()
                    && target.contract_path == resolved_path
                    && target.contract.workspace.as_ref().is_some_and(|workspace| {
                        workspace.workspace_type == crate::schema::RepoWorkspaceType::Monorepo
                    })
                {
                    let mut text_sections = vec![render_tasks_output_text(
                        use_cmd,
                        &text_path_display,
                        workflow_summary.as_ref(),
                        agent_summary.as_ref(),
                        &task_summaries,
                    )];
                    let mut member_targets = Vec::new();
                    let mut member_results = Vec::new();

                    if let Some(workspace) = target.contract.workspace.as_ref() {
                        for member in &workspace.members {
                            let member_target =
                                match load_and_validate_target(&resolved_path, Some(member)) {
                                    Ok(target) => target,
                                    Err(ContractProblem::Validation(errors)) => {
                                        return finalize_debug(
                                            match format {
                                                OutputFormat::Text => {
                                                    CommandOutput::failure(errors.to_string())
                                                }
                                                OutputFormat::Json => {
                                                    CommandOutput::failure(to_json(&TasksFailure {
                                                        ok: false,
                                                        path: &path_display,
                                                        errors: errors
                                                            .errors()
                                                            .iter()
                                                            .map(ToString::to_string)
                                                            .collect(),
                                                        error: None,
                                                    }))
                                                }
                                            },
                                            debug,
                                            debug_lines,
                                        );
                                    }
                                    Err(ContractProblem::Load(error)) => {
                                        return finalize_debug(
                                            match format {
                                                OutputFormat::Text => {
                                                    CommandOutput::failure(error.to_string())
                                                }
                                                OutputFormat::Json => {
                                                    CommandOutput::failure(to_json(&TasksFailure {
                                                        ok: false,
                                                        path: &path_display,
                                                        errors: Vec::new(),
                                                        error: Some(error.to_string()),
                                                    }))
                                                }
                                            },
                                            debug,
                                            debug_lines,
                                        );
                                    }
                                };
                            member_targets.push((member.as_str(), member_target));
                        }
                    }
                    for (member, member_target) in &member_targets {
                        let member_tasks =
                            listed_task_summaries(&member_target.contract, all, &filters);
                        let member_agent =
                            listed_agent_summary(&member_target.contract, all, &member_tasks);
                        let member_workflow = match resolve_selected_workflow_summary(
                            &member_target.contract,
                            &member_target.contract_path,
                            workflow_name,
                        ) {
                            Ok(summary) => summary,
                            Err(error) => {
                                return finalize_debug(
                                    CommandOutput::failure_with_code(error, 2),
                                    debug,
                                    debug_lines,
                                );
                            }
                        };
                        text_sections.push(render_tasks_output_text(
                            use_cmd,
                            &display_contract_target(&compact_path_display, Some(member)),
                            member_workflow.as_ref(),
                            member_agent.as_ref(),
                            &member_tasks,
                        ));
                        let member_capability_profile = Some(harness_capability_profile_for_tasks(
                            &member_target.contract,
                            &member_target.contract_path,
                            member_agent.as_ref(),
                            &member_tasks,
                        ));
                        member_results.push(MemberTasksSuccess {
                            member,
                            workflow: member_workflow,
                            agent: member_agent,
                            capability_profile: member_capability_profile,
                            tasks: member_tasks,
                        });
                    }

                    let capability_profile = Some(harness_capability_profile_for_tasks(
                        contract,
                        &target.contract_path,
                        agent_summary.as_ref(),
                        &task_summaries,
                    ));

                    match format {
                        OutputFormat::Text => CommandOutput::success(text_sections.join("\n\n")),
                        OutputFormat::Json => CommandOutput::success(to_json(&TasksSuccess {
                            ok: true,
                            path: &path_display,
                            workflow: workflow_summary,
                            agent: agent_summary,
                            capability_profile,
                            artifacts: contract.artifacts.clone(),
                            members: member_results,
                            tasks: task_summaries,
                        })),
                    }
                } else {
                    let capability_profile = Some(harness_capability_profile_for_tasks(
                        contract,
                        &target.contract_path,
                        agent_summary.as_ref(),
                        &task_summaries,
                    ));
                    match format {
                        OutputFormat::Text => CommandOutput::success(render_tasks_output_text(
                            use_cmd,
                            &text_path_display,
                            workflow_summary.as_ref(),
                            agent_summary.as_ref(),
                            &task_summaries,
                        )),
                        OutputFormat::Json => CommandOutput::success(to_json(&TasksSuccess {
                            ok: true,
                            path: &path_display,
                            workflow: workflow_summary,
                            agent: agent_summary,
                            capability_profile,
                            artifacts: contract.artifacts.clone(),
                            members: Vec::new(),
                            tasks: task_summaries,
                        })),
                    }
                }
            }
            Ok(_) => {
                let mut text_sections = Vec::new();
                let mut member_targets = Vec::new();
                let mut member_results = Vec::new();
                for member in members {
                    let target =
                        match load_and_validate_target(&resolved_path, Some(member.as_str())) {
                            Ok(target) => target,
                            Err(ContractProblem::Validation(errors)) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(errors.to_string())
                                        }
                                        OutputFormat::Json => {
                                            CommandOutput::failure(to_json(&TasksFailure {
                                                ok: false,
                                                path: &path_display,
                                                errors: errors
                                                    .errors()
                                                    .iter()
                                                    .map(ToString::to_string)
                                                    .collect(),
                                                error: None,
                                            }))
                                        }
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                            Err(ContractProblem::Load(error)) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(error.to_string())
                                        }
                                        OutputFormat::Json => {
                                            CommandOutput::failure(to_json(&TasksFailure {
                                                ok: false,
                                                path: &path_display,
                                                errors: Vec::new(),
                                                error: Some(error.to_string()),
                                            }))
                                        }
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                        };
                    member_targets.push((member.as_str(), target));
                }
                for (member, target) in &member_targets {
                    let tasks = listed_task_summaries(&target.contract, all, &filters);
                    let agent = listed_agent_summary(&target.contract, all, &tasks);
                    let workflow = match resolve_selected_workflow_summary(
                        &target.contract,
                        &target.contract_path,
                        workflow_name,
                    ) {
                        Ok(summary) => summary,
                        Err(error) => {
                            return finalize_debug(
                                CommandOutput::failure_with_code(error, 2),
                                debug,
                                debug_lines,
                            );
                        }
                    };
                    text_sections.push(render_tasks_output_text(
                        use_cmd,
                        &display_contract_target(&compact_path_display, Some(member)),
                        workflow.as_ref(),
                        agent.as_ref(),
                        &tasks,
                    ));
                    let capability_profile = Some(harness_capability_profile_for_tasks(
                        &target.contract,
                        &target.contract_path,
                        agent.as_ref(),
                        &tasks,
                    ));
                    member_results.push(MemberTasksSuccess {
                        member,
                        workflow,
                        agent,
                        capability_profile,
                        tasks,
                    });
                }

                match format {
                    OutputFormat::Text => CommandOutput::success(text_sections.join("\n\n")),
                    OutputFormat::Json => CommandOutput::success(to_json(&TasksSuccess {
                        ok: true,
                        path: &path_display,
                        workflow: None,
                        agent: None,
                        capability_profile: None,
                        artifacts: BTreeMap::new(),
                        members: member_results,
                        tasks: Vec::new(),
                    })),
                }
            }
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_repo_contract_output(
                    "TASKS",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota tasks", &resolved_path)
                            ))
                        ),
                    ],
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&TasksFailure {
                    ok: false,
                    path: &path_display,
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "TASKS",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &[
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota tasks", &resolved_path)
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&TasksFailure {
                    ok: false,
                    path: &path_display,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

pub fn services(
    path: Option<&Path>,
    file_override: Option<&Path>,
    members: &[String],
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    if let Some(duplicate) = duplicate_member(members) {
        return finalize_debug(
            CommandOutput::failure_with_code(
                format!("`--member {duplicate}` was provided more than once"),
                2,
            ),
            debug,
            vec![String::from("DEBUG command=services")],
        );
    }

    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => {
                        missing_repo_contract_command_output("SERVICES", "ota services", &error)
                            .unwrap_or_else(|| CommandOutput::failure(error.to_string()))
                    }
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=services")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let single_member = (members.len() == 1).then(|| members[0].as_str());
    let text_path_display = display_contract_target(&compact_path_display, single_member);
    let mut debug_lines = vec![
        String::from("DEBUG command=services"),
        format!("DEBUG contract_path={path_display}"),
    ];
    for member in members {
        debug_lines.push(format!("DEBUG member={member}"));
    }

    if is_org_policy_pack_path(&resolved_path) {
        return finalize_debug(
            wrong_repo_contract_target_output(
                "SERVICES",
                &resolved_path,
                "Wrong command target",
                &[
                    String::from("`ota services` reads repo contracts such as `ota.yaml`"),
                    format!(
                        "{} is an org policy pack, not a repo contract",
                        paint_code(&compact_path(&resolved_path, DEFAULT_POLICY_FILE))
                    ),
                ],
                wrong_target_next_steps_for_repo_command("ota services", &resolved_path),
                format,
            ),
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, single_member) {
            Ok(target) if members.is_empty() || members.len() == 1 => {
                let service_summaries = target
                    .contract
                    .services
                    .iter()
                    .map(|(name, service)| ServiceSummary::from_spec(name, service))
                    .collect::<Vec<_>>();

                if members.is_empty()
                    && target.contract_path == resolved_path
                    && target.contract.workspace.as_ref().is_some_and(|workspace| {
                        workspace.workspace_type == crate::schema::RepoWorkspaceType::Monorepo
                    })
                {
                    let mut text_sections = vec![render_services_output_text(
                        &text_path_display,
                        &service_summaries,
                    )];
                    let mut member_results = Vec::new();

                    if let Some(workspace) = target.contract.workspace.as_ref() {
                        for member in &workspace.members {
                            let member_target =
                                match load_and_validate_target(&resolved_path, Some(member)) {
                                    Ok(target) => target,
                                    Err(ContractProblem::Validation(errors)) => {
                                        return finalize_debug(
                                            match format {
                                                OutputFormat::Text => {
                                                    CommandOutput::failure(errors.to_string())
                                                }
                                                OutputFormat::Json => CommandOutput::failure(
                                                    to_json(&ServicesFailure {
                                                        ok: false,
                                                        path: &path_display,
                                                        errors: errors
                                                            .errors()
                                                            .iter()
                                                            .map(ToString::to_string)
                                                            .collect(),
                                                        error: None,
                                                    }),
                                                ),
                                            },
                                            debug,
                                            debug_lines,
                                        );
                                    }
                                    Err(ContractProblem::Load(error)) => {
                                        return finalize_debug(
                                            match format {
                                                OutputFormat::Text => {
                                                    CommandOutput::failure(error.to_string())
                                                }
                                                OutputFormat::Json => CommandOutput::failure(
                                                    to_json(&ServicesFailure {
                                                        ok: false,
                                                        path: &path_display,
                                                        errors: Vec::new(),
                                                        error: Some(error.to_string()),
                                                    }),
                                                ),
                                            },
                                            debug,
                                            debug_lines,
                                        );
                                    }
                                };
                            let member_services = member_target
                                .contract
                                .services
                                .iter()
                                .map(|(name, service)| ServiceSummary::from_spec(name, service))
                                .collect::<Vec<_>>();
                            text_sections.push(render_services_output_text(
                                &display_contract_target(
                                    &compact_path_display,
                                    Some(member.as_str()),
                                ),
                                &member_services,
                            ));
                            member_results.push(MemberServicesSuccess {
                                member: member.to_string(),
                                services: member_services,
                            });
                        }
                    }

                    match format {
                        OutputFormat::Text => CommandOutput::success(text_sections.join("\n\n")),
                        OutputFormat::Json => CommandOutput::success(to_json(&ServicesSuccess {
                            ok: true,
                            path: &path_display,
                            members: member_results,
                            services: service_summaries,
                        })),
                    }
                } else {
                    match format {
                        OutputFormat::Text => CommandOutput::success(render_services_output_text(
                            &text_path_display,
                            &service_summaries,
                        )),
                        OutputFormat::Json => CommandOutput::success(to_json(&ServicesSuccess {
                            ok: true,
                            path: &path_display,
                            members: Vec::new(),
                            services: service_summaries,
                        })),
                    }
                }
            }
            Ok(_) => {
                let mut text_sections = Vec::new();
                let mut member_results = Vec::new();
                for member in members {
                    let target =
                        match load_and_validate_target(&resolved_path, Some(member.as_str())) {
                            Ok(target) => target,
                            Err(ContractProblem::Validation(errors)) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(errors.to_string())
                                        }
                                        OutputFormat::Json => {
                                            CommandOutput::failure(to_json(&ServicesFailure {
                                                ok: false,
                                                path: &path_display,
                                                errors: errors
                                                    .errors()
                                                    .iter()
                                                    .map(ToString::to_string)
                                                    .collect(),
                                                error: None,
                                            }))
                                        }
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                            Err(ContractProblem::Load(error)) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(error.to_string())
                                        }
                                        OutputFormat::Json => {
                                            CommandOutput::failure(to_json(&ServicesFailure {
                                                ok: false,
                                                path: &path_display,
                                                errors: Vec::new(),
                                                error: Some(error.to_string()),
                                            }))
                                        }
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                        };
                    let services = target
                        .contract
                        .services
                        .iter()
                        .map(|(name, service)| ServiceSummary::from_spec(name, service))
                        .collect::<Vec<_>>();
                    text_sections.push(render_services_output_text(
                        &display_contract_target(&compact_path_display, Some(member.as_str())),
                        &services,
                    ));
                    member_results.push(MemberServicesSuccess {
                        member: member.to_string(),
                        services,
                    });
                }

                match format {
                    OutputFormat::Text => CommandOutput::success(text_sections.join("\n\n")),
                    OutputFormat::Json => CommandOutput::success(to_json(&ServicesSuccess {
                        ok: true,
                        path: &path_display,
                        members: member_results,
                        services: Vec::new(),
                    })),
                }
            }
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_repo_contract_output(
                    "SERVICES",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota services", &resolved_path)
                            ))
                        ),
                    ],
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&ServicesFailure {
                    ok: false,
                    path: &path_display,
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "SERVICES",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &[
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota services", &resolved_path)
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ServicesFailure {
                    ok: false,
                    path: &path_display,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

pub fn workflows(
    path: Option<&Path>,
    file_override: Option<&Path>,
    members: &[String],
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    if let Some(duplicate) = duplicate_member(members) {
        return finalize_debug(
            CommandOutput::failure_with_code(
                format!("`--member {duplicate}` was provided more than once"),
                2,
            ),
            debug,
            vec![String::from("DEBUG command=workflows")],
        );
    }

    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            let unresolved_path = unresolved_contract_target_path(path, file_override);
            return finalize_debug(
                match format {
                    OutputFormat::Text => {
                        missing_repo_contract_command_output("WORKFLOWS", "ota workflows", &error)
                            .unwrap_or_else(|| CommandOutput::failure(error.to_string()))
                    }
                    OutputFormat::Json => CommandOutput::failure(to_json(&WorkflowsFailure {
                        ok: false,
                        path: &unresolved_path,
                        errors: Vec::new(),
                        error: Some(error.to_string()),
                    })),
                },
                debug,
                vec![String::from("DEBUG command=workflows")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let single_member = (members.len() == 1).then(|| members[0].as_str());
    let text_path_display = display_contract_target(&compact_path_display, single_member);
    let mut debug_lines = vec![
        String::from("DEBUG command=workflows"),
        format!("DEBUG contract_path={path_display}"),
    ];
    for member in members {
        debug_lines.push(format!("DEBUG member={member}"));
    }

    if is_org_policy_pack_path(&resolved_path) {
        return finalize_debug(
            wrong_repo_contract_target_output(
                "WORKFLOWS",
                &resolved_path,
                "Wrong command target",
                &[
                    String::from("`ota workflows` reads repo contracts such as `ota.yaml`"),
                    format!(
                        "{} is an org policy pack, not a repo contract",
                        paint_code(&compact_path(&resolved_path, DEFAULT_POLICY_FILE))
                    ),
                ],
                wrong_target_next_steps_for_repo_command("ota workflows", &resolved_path),
                format,
            ),
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, single_member) {
            Ok(target) if members.is_empty() || members.len() == 1 => {
                let workflows = WorkflowSummary::list_from_contract_with_path(
                    &target.contract,
                    &target.contract_path,
                );
                let default = target
                    .contract
                    .workflows
                    .as_ref()
                    .map(|workflows| workflows.default.as_str());

                if members.is_empty()
                    && target.contract_path == resolved_path
                    && target.contract.workspace.as_ref().is_some_and(|workspace| {
                        workspace.workspace_type == crate::schema::RepoWorkspaceType::Monorepo
                    })
                {
                    let mut text_sections = vec![render_workflows_output_text(
                        &text_path_display,
                        default,
                        &workflows,
                    )];
                    let mut member_targets = Vec::new();

                    if let Some(workspace) = target.contract.workspace.as_ref() {
                        for member in &workspace.members {
                            let member_target =
                                match load_and_validate_target(&resolved_path, Some(member)) {
                                    Ok(target) => target,
                                    Err(ContractProblem::Validation(errors)) => {
                                        return finalize_debug(
                                            match format {
                                                OutputFormat::Text => {
                                                    CommandOutput::failure(errors.to_string())
                                                }
                                                OutputFormat::Json => CommandOutput::failure(
                                                    to_json(&WorkflowsFailure {
                                                        ok: false,
                                                        path: &path_display,
                                                        errors: errors
                                                            .errors()
                                                            .iter()
                                                            .map(ToString::to_string)
                                                            .collect(),
                                                        error: None,
                                                    }),
                                                ),
                                            },
                                            debug,
                                            debug_lines,
                                        );
                                    }
                                    Err(ContractProblem::Load(error)) => {
                                        return finalize_debug(
                                            match format {
                                                OutputFormat::Text => {
                                                    CommandOutput::failure(error.to_string())
                                                }
                                                OutputFormat::Json => CommandOutput::failure(
                                                    to_json(&WorkflowsFailure {
                                                        ok: false,
                                                        path: &path_display,
                                                        errors: Vec::new(),
                                                        error: Some(error.to_string()),
                                                    }),
                                                ),
                                            },
                                            debug,
                                            debug_lines,
                                        );
                                    }
                                };
                            member_targets.push((member.as_str(), member_target));
                        }
                    }

                    let mut member_results = Vec::new();
                    for (member, member_target) in &member_targets {
                        let member_workflows = WorkflowSummary::list_from_contract_with_path(
                            &member_target.contract,
                            &member_target.contract_path,
                        );
                        let member_tasks = listed_task_summaries(
                            &member_target.contract,
                            false,
                            &TasksListFilters::default(),
                        );
                        let member_agent =
                            listed_agent_summary(&member_target.contract, false, &member_tasks);
                        let member_default = member_target
                            .contract
                            .workflows
                            .as_ref()
                            .map(|workflows| workflows.default.as_str());
                        text_sections.push(render_workflows_output_text(
                            &display_contract_target(&compact_path_display, Some(member)),
                            member_default,
                            &member_workflows,
                        ));
                        member_results.push(MemberWorkflowsSuccess {
                            member,
                            default: member_default,
                            capability_profile: Some(harness_capability_profile_for_workflows(
                                &member_target.contract,
                                &member_target.contract_path,
                                member_agent.as_ref(),
                                &member_workflows,
                            )),
                            workflows: member_workflows,
                        });
                    }

                    let tasks = listed_task_summaries(
                        &target.contract,
                        false,
                        &TasksListFilters::default(),
                    );
                    let agent = listed_agent_summary(&target.contract, false, &tasks);

                    match format {
                        OutputFormat::Text => CommandOutput::success(text_sections.join("\n\n")),
                        OutputFormat::Json => CommandOutput::success(to_json(&WorkflowsSuccess {
                            ok: true,
                            path: &path_display,
                            default,
                            capability_profile: Some(harness_capability_profile_for_workflows(
                                &target.contract,
                                &target.contract_path,
                                agent.as_ref(),
                                &workflows,
                            )),
                            members: member_results,
                            workflows,
                        })),
                    }
                } else {
                    let tasks = listed_task_summaries(
                        &target.contract,
                        false,
                        &TasksListFilters::default(),
                    );
                    let agent = listed_agent_summary(&target.contract, false, &tasks);
                    match format {
                        OutputFormat::Text => CommandOutput::success(render_workflows_output_text(
                            &text_path_display,
                            default,
                            &workflows,
                        )),
                        OutputFormat::Json => CommandOutput::success(to_json(&WorkflowsSuccess {
                            ok: true,
                            path: &path_display,
                            default,
                            capability_profile: Some(harness_capability_profile_for_workflows(
                                &target.contract,
                                &target.contract_path,
                                agent.as_ref(),
                                &workflows,
                            )),
                            members: Vec::new(),
                            workflows,
                        })),
                    }
                }
            }
            Ok(_) => {
                let mut text_sections = Vec::new();
                let mut member_targets = Vec::new();
                for member in members {
                    let target =
                        match load_and_validate_target(&resolved_path, Some(member.as_str())) {
                            Ok(target) => target,
                            Err(ContractProblem::Validation(errors)) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(errors.to_string())
                                        }
                                        OutputFormat::Json => {
                                            CommandOutput::failure(to_json(&WorkflowsFailure {
                                                ok: false,
                                                path: &path_display,
                                                errors: errors
                                                    .errors()
                                                    .iter()
                                                    .map(ToString::to_string)
                                                    .collect(),
                                                error: None,
                                            }))
                                        }
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                            Err(ContractProblem::Load(error)) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(error.to_string())
                                        }
                                        OutputFormat::Json => {
                                            CommandOutput::failure(to_json(&WorkflowsFailure {
                                                ok: false,
                                                path: &path_display,
                                                errors: Vec::new(),
                                                error: Some(error.to_string()),
                                            }))
                                        }
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                        };
                    member_targets.push((member.as_str(), target));
                }

                let mut member_results = Vec::new();
                for (member, target) in &member_targets {
                    let workflows = WorkflowSummary::list_from_contract_with_path(
                        &target.contract,
                        &target.contract_path,
                    );
                    let tasks = listed_task_summaries(
                        &target.contract,
                        false,
                        &TasksListFilters::default(),
                    );
                    let agent = listed_agent_summary(&target.contract, false, &tasks);
                    let default = target
                        .contract
                        .workflows
                        .as_ref()
                        .map(|workflows| workflows.default.as_str());
                    text_sections.push(render_workflows_output_text(
                        &display_contract_target(&compact_path_display, Some(member)),
                        default,
                        &workflows,
                    ));
                    member_results.push(MemberWorkflowsSuccess {
                        member,
                        default,
                        capability_profile: Some(harness_capability_profile_for_workflows(
                            &target.contract,
                            &target.contract_path,
                            agent.as_ref(),
                            &workflows,
                        )),
                        workflows,
                    });
                }

                match format {
                    OutputFormat::Text => CommandOutput::success(text_sections.join("\n\n")),
                    OutputFormat::Json => CommandOutput::success(to_json(&WorkflowsSuccess {
                        ok: true,
                        path: &path_display,
                        default: None,
                        capability_profile: None,
                        members: member_results,
                        workflows: Vec::new(),
                    })),
                }
            }
            Err(ContractProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_repo_contract_output(
                    "WORKFLOWS",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota workflows", &resolved_path)
                            ))
                        ),
                    ],
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&WorkflowsFailure {
                    ok: false,
                    path: &path_display,
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                })),
            },
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                    "WORKFLOWS",
                    &resolved_path,
                    "Contract could not be loaded",
                    &error.to_string(),
                    &[
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota workflows", &resolved_path)
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&WorkflowsFailure {
                    ok: false,
                    path: &path_display,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

fn render_services_output_text(path: &str, services: &[ServiceSummary]) -> String {
    let mut output = format_command_header("SERVICES", path);
    output.push('\n');

    if services.is_empty() {
        output.push_str(&format!(
            "\n\n{} {}",
            list_bullet(),
            paint("No declared services.", "1")
        ));
        output.push_str(&format_next_timeline(&[
            String::from("run `ota doctor` to inspect readiness without managed services"),
            String::from("add `services` to `ota.yaml` when repo readiness depends on local infra"),
        ]));
        return output;
    }

    for service in services {
        output.push_str(&format!(
            "\n\n{} {} [{}]",
            list_bullet(),
            paint(&service.name, "1"),
            if service.required {
                "required"
            } else {
                "optional"
            }
        ));

        if let Some(producer) = service.producer.as_ref() {
            let producer_label = match producer.listener.as_deref() {
                Some(listener) => format!(
                    "workspace repo {} task {} listener {} ({})",
                    producer.repo, producer.task, listener, producer.address_view
                ),
                None => format!(
                    "workspace repo {} task {} ({})",
                    producer.repo, producer.task, producer.address_view
                ),
            };
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("producer:"),
                producer_label
            ));
        }
        if service.producer.is_none() {
            let manager = service
                .manager
                .as_ref()
                .map(|manager| manager.kind.as_str())
                .or(service.provider.as_deref())
                .unwrap_or("-");
            output.push_str(&format!("\n  {} {manager}", paint_key("manager:")));
        }
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("depends on:"),
            if service.depends_on.is_empty() {
                String::from("-")
            } else {
                service.depends_on.join(", ")
            }
        ));
        if let Some(readiness) = service.readiness.as_ref() {
            append_wrapped_detail(
                &mut output,
                "readiness:",
                &format_service_readiness_summary(readiness),
                "  ",
                84,
                stylize_inline_text,
            );
        }
        if let Some(healthcheck) = service.healthcheck.as_deref() {
            append_wrapped_detail(
                &mut output,
                "healthcheck:",
                healthcheck,
                "  ",
                84,
                stylize_inline_text,
            );
        }
        if let Some(timeout) = service.timeout {
            output.push_str(&format!("\n  {} {timeout}s", paint_key("timeout:")));
        }

        if !service.endpoints.is_empty() {
            let endpoint_width = service
                .endpoints
                .keys()
                .map(|endpoint_name| endpoint_name.len())
                .max()
                .unwrap_or(0);
            output.push_str(&format!("\n  {}", paint_key("endpoints:")));
            for (endpoint_name, endpoint) in &service.endpoints {
                let context = endpoint
                    .context
                    .as_deref()
                    .unwrap_or(endpoint_name.as_str());
                output.push_str(&format!(
                    "\n    {:<endpoint_width$}  {}:{}{}",
                    endpoint_name,
                    endpoint.address,
                    endpoint.port,
                    if context == endpoint_name {
                        String::new()
                    } else {
                        format!(" ({context})")
                    },
                    endpoint_width = endpoint_width
                ));
            }
        }

        if service.start.is_some() || service.stop.is_some() {
            let command_label_width = ["start", "stop"]
                .into_iter()
                .filter(|label| match *label {
                    "start" => service.start.is_some(),
                    "stop" => service.stop.is_some(),
                    _ => false,
                })
                .map(str::len)
                .max()
                .unwrap_or(0);
            output.push_str(&format!("\n  {}", paint_key("commands:")));
            if let Some(start) = service.start.as_deref() {
                output.push_str(&format!(
                    "\n    {} {}",
                    paint_key(&format!("{:<command_label_width$}", "start")),
                    stylize_inline_text(start)
                ));
            }
            if let Some(stop) = service.stop.as_deref() {
                output.push_str(&format!(
                    "\n    {} {}",
                    paint_key(&format!("{:<command_label_width$}", "stop")),
                    stylize_inline_text(stop)
                ));
            }
        }

        output.push_str(&format!(
            "\n  {} {}, {}",
            paint_key("managed by:"),
            paint_code("ota doctor"),
            paint_code("ota up")
        ));
    }

    output
}

fn format_service_readiness_summary(readiness: &ServiceReadinessSummary) -> String {
    if let Some(probe) = readiness.probe.as_deref() {
        let mut detail = format!("probe {probe}");
        if let Some(interval) = readiness.interval.as_deref() {
            detail.push_str(&format!(" interval={interval}"));
        }
        if let Some(retries) = readiness.retries {
            detail.push_str(&format!(" retries={retries}"));
        }
        if let Some(start_period) = readiness.start_period.as_deref() {
            detail.push_str(&format!(" start_period={start_period}"));
        }
        return detail;
    }

    let from = readiness.from.as_deref().unwrap_or("?");
    if let Some(run) = readiness.run.as_deref() {
        return format!("from {from} -> {run}");
    }

    let mut detail = String::new();
    if let Some(kind) = readiness.kind.as_deref() {
        detail.push_str(kind);
    }
    if let Some(method) = readiness.method.as_deref() {
        if !detail.is_empty() {
            detail.push(' ');
        }
        detail.push_str(method);
    }
    if let Some(path) = readiness.path.as_deref() {
        if !detail.is_empty() {
            detail.push(' ');
        }
        detail.push_str(path);
    }
    if let Some(success) = readiness.success.as_ref()
        && !success.status.is_empty()
    {
        detail.push_str(" status=");
        detail.push_str(
            &success
                .status
                .iter()
                .map(|status: &u16| status.to_string())
                .collect::<Vec<_>>()
                .join(","),
        );
    }
    if let Some(body) = readiness.body.as_ref() {
        detail.push_str(" contains=");
        detail.push_str(body.contains.as_str());
    }
    if detail.is_empty() {
        detail.push_str("structured probe");
    }
    format!("from {from} -> {detail}")
}

fn parse_effect_override_decision(value: &str) -> Option<PolicyEffectDecision> {
    match value.trim() {
        "allow" => Some(PolicyEffectDecision::Allow),
        "warn" => Some(PolicyEffectDecision::Warn),
        "deny" => Some(PolicyEffectDecision::Deny),
        _ => None,
    }
}

fn parse_effect_override_selector(value: &str) -> Option<String> {
    let selector = value.trim();
    if selector.eq_ignore_ascii_case("network") {
        return Some(String::from("network:broad"));
    }
    if selector.eq_ignore_ascii_case("network:broad") {
        return Some(String::from("network:broad"));
    }
    if selector.eq_ignore_ascii_case("network:dependency_hydration") {
        return Some(String::from("network:dependency_hydration"));
    }
    if selector.eq_ignore_ascii_case("network:container_image_hydration") {
        return Some(String::from("network:container_image_hydration"));
    }
    if selector.eq_ignore_ascii_case("network:service_readiness") {
        return Some(String::from("network:service_readiness"));
    }
    if selector.eq_ignore_ascii_case("network:integration_test") {
        return Some(String::from("network:integration_test"));
    }
    if selector.eq_ignore_ascii_case("network:tool_bootstrap") {
        return Some(String::from("network:tool_bootstrap"));
    }
    if let Some(state) = selector.strip_prefix("adapter_state:") {
        let token = state.trim();
        if token.is_empty() {
            return None;
        }
        if is_valid_adapter_state_effect_token(token) {
            return Some(format!("adapter_state:{token}"));
        }
    }
    if let Some(state) = selector.strip_prefix("external_state:") {
        let token = state.trim();
        if token.is_empty() {
            return None;
        }
        if is_valid_external_state_effect_token(token) {
            return Some(format!("external_state:{token}"));
        }
    }
    None
}

fn is_valid_adapter_state_effect_token(value: &str) -> bool {
    let Some((family, state)) = value.split_once(':') else {
        return false;
    };
    !state.contains(':')
        && is_valid_external_state_effect_token(family)
        && is_valid_external_state_effect_token(state)
}

fn is_valid_external_state_effect_token(value: &str) -> bool {
    let mut chars = value.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    if !first.is_ascii_lowercase() {
        return false;
    }

    let mut last_was_separator = false;
    let mut last = first;
    for ch in chars {
        if ch == '-' || ch == '_' {
            if last_was_separator {
                return false;
            }
            last_was_separator = true;
        } else if ch.is_ascii_lowercase() || ch.is_ascii_digit() {
            last_was_separator = false;
        } else {
            return false;
        }
        last = ch;
    }

    !matches!(last, '-' | '_')
}

fn parse_effect_governance_overrides(
    values: &[String],
) -> Result<EffectGovernanceOverrides, String> {
    let mut overrides = EffectGovernanceOverrides::default();
    for raw in values {
        let Some((selector_raw, decision_raw)) = raw.split_once('=') else {
            return Err(format!(
                "invalid `--effect-override {raw}`; expected `<effect>=<allow|warn|deny>`"
            ));
        };
        let Some(selector) = parse_effect_override_selector(selector_raw) else {
            return Err(format!(
                "invalid `--effect-override {raw}` effect selector; use one of `network`, `network:broad`, `network:dependency_hydration`, `network:container_image_hydration`, `network:service_readiness`, `network:integration_test`, `network:tool_bootstrap`, `adapter_state:<adapter_family>:<state_name>`, or `external_state:<token>`"
            ));
        };
        let Some(decision) = parse_effect_override_decision(decision_raw) else {
            return Err(format!(
                "invalid `--effect-override {raw}` decision; use `allow`, `warn`, or `deny`"
            ));
        };
        overrides.decisions.insert(selector, decision);
    }
    Ok(overrides)
}

fn current_effect_governance_overrides() -> EffectGovernanceOverrides {
    EFFECT_GOVERNANCE_OVERRIDE_CONTEXT.with(|context| context.borrow().clone())
}

fn with_effect_governance_override_map<T>(
    overrides: &EffectGovernanceOverrides,
    action: impl FnOnce() -> T,
) -> T {
    if overrides.decisions.is_empty() {
        return action();
    }
    EFFECT_GOVERNANCE_OVERRIDE_CONTEXT.with(|context| {
        let previous = context.replace(overrides.clone());
        let output = std::panic::catch_unwind(std::panic::AssertUnwindSafe(action));
        context.replace(previous);
        match output {
            Ok(output) => output,
            Err(payload) => std::panic::resume_unwind(payload),
        }
    })
}

