#[allow(clippy::too_many_arguments)]
pub(crate) fn run_command_with_agent_reason_and_grant_and_effect_canary(
    task_name: &str,
    path: Option<&Path>,
    file_override: Option<&Path>,
    format: OutputFormat,
    overrides: ExecutionOverrides,
    effect_overrides: &[String],
    members: &[String],
    task_inputs: &[String],
    agent: bool,
    expect_refusal: bool,
    expect_effect_refusal: Option<&str>,
    reason: Option<&str>,
    grant: Option<&str>,
    sandbox_target: Option<&str>,
    dry_run: bool,
    debug: bool,
    show_receipt: bool,
    stream: bool,
    persist_logs: bool,
) -> CommandOutput {
    activate_mise_paths_for_current_process();
    if dry_run && stream {
        return finalize_debug(
            CommandOutput::failure_with_code(
                String::from("`--stream` cannot be used with `ota run --dry-run`"),
                2,
            ),
            debug,
            vec![
                String::from("DEBUG command=run"),
                format!("DEBUG task={task_name}"),
                String::from("DEBUG dry_run=true"),
                String::from("DEBUG stream=true"),
            ],
        );
    }
    if matches!(format, OutputFormat::Json)
        && !dry_run
        && !expect_refusal
        && expect_effect_refusal.is_none()
    {
        return finalize_debug(
            CommandOutput::failure_with_code(
                String::from("`--json` currently requires `ota run --dry-run`"),
                2,
            ),
            debug,
            vec![
                String::from("DEBUG command=run"),
                format!("DEBUG task={task_name}"),
                String::from("DEBUG json=true"),
            ],
        );
    }
    if let Some(duplicate) = duplicate_member(members) {
        return finalize_debug(
            CommandOutput::failure_with_code(
                format!("`--member {duplicate}` was provided more than once"),
                2,
            ),
            debug,
            vec![
                String::from("DEBUG command=run"),
                format!("DEBUG task={task_name}"),
            ],
        );
    }
    let parsed_effect_overrides = match parse_effect_governance_overrides(effect_overrides) {
        Ok(overrides) => overrides,
        Err(error) => {
            return finalize_debug(
                CommandOutput::failure_with_code(error, 2),
                debug,
                vec![
                    String::from("DEBUG command=run"),
                    format!("DEBUG task={task_name}"),
                ],
            );
        }
    };

    let (resolved_path, normalized_task_inputs) = match resolve_repo_run_path_and_inputs(
        task_name,
        path,
        file_override,
        members,
        task_inputs,
    ) {
        Ok(target) => target,
        Err(error) => {
            return finalize_debug(
                missing_repo_contract_command_output("RUN", "ota run", &error).unwrap_or_else(
                    || CommandOutput::failure(stylize_text_failure("ota run", &error.to_string())),
                ),
                debug,
                vec![
                    String::from("DEBUG command=run"),
                    format!("DEBUG task={task_name}"),
                ],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let mut debug_lines = vec![
        String::from("DEBUG command=run"),
        format!("DEBUG task={task_name}"),
        format!("DEBUG contract_path={path_display}"),
    ];
    if dry_run {
        debug_lines.push(String::from("DEBUG dry_run=true"));
    }
    if agent {
        debug_lines.push(String::from("DEBUG agent=true"));
    }
    if let Some(canary_id) = expect_effect_refusal {
        debug_lines.push(format!("DEBUG expect_effect_refusal={canary_id}"));
    }
    if let Some(reason) = reason {
        debug_lines.push(format!("DEBUG reason={reason}"));
    }
    if let Some(grant) = grant {
        debug_lines.push(format!("DEBUG grant={grant}"));
    }
    if let Some(target) = sandbox_target {
        debug_lines.push(format!("DEBUG sandbox_target={target}"));
    }
    if normalized_task_inputs != task_inputs {
        debug_lines.push(format!(
            "DEBUG task_inputs={}",
            normalized_task_inputs.join(" ")
        ));
    }
    if let Some(backend) = overrides.backend {
        debug_lines.push(format!(
            "DEBUG backend_override={}",
            format_backend(backend)
        ));
    }
    if let Some(lifecycle) = overrides.lifecycle {
        debug_lines.push(format!(
            "DEBUG lifecycle_override={}",
            format_lifecycle(lifecycle)
        ));
    }
    for member in members {
        debug_lines.push(format!("DEBUG member={member}"));
    }
    if !parsed_effect_overrides.decisions.is_empty() {
        for (effect, decision) in &parsed_effect_overrides.decisions {
            debug_lines.push(format!(
                "DEBUG effect_override={effect}={}",
                decision.as_str()
            ));
        }
    }

    with_effect_governance_override_map(&parsed_effect_overrides, || {
        finalize_debug(
            if let Some(canary_id) = expect_effect_refusal {
                run_effect_refusal_canary_command(
                    task_name,
                    canary_id,
                    &resolved_path,
                    overrides,
                    effect_overrides,
                    members,
                    &normalized_task_inputs,
                    reason,
                    grant,
                    sandbox_target,
                    format,
                )
            } else if expect_refusal {
                run_refusal_canary_command(
                    task_name,
                    &resolved_path,
                    overrides,
                    members,
                    &normalized_task_inputs,
                    format,
                )
            } else if dry_run {
                run_preview_command(
                    task_name,
                    &resolved_path,
                    overrides,
                    members,
                    agent,
                    grant,
                    &normalized_task_inputs,
                    effect_overrides,
                    sandbox_target,
                    format,
                    persist_logs,
                )
            } else {
                match run_contract_targets(
                    task_name,
                    &resolved_path,
                    overrides,
                    members,
                    &normalized_task_inputs,
                    effect_overrides,
                    agent,
                    grant,
                    sandbox_target,
                    reason,
                    show_receipt,
                    stream,
                    run_command_streaming_enabled(stream),
                    persist_logs,
                ) {
                    Ok(stderr) => CommandOutput {
                        stdout: String::new(),
                        stderr: (!stderr.is_empty()).then_some(stderr),
                        exit_code: 0,
                    },
                    Err(error) => CommandOutput {
                        stdout: String::new(),
                        stderr: Some(match (error.summary, error.receipt) {
                            (Some(summary), Some(receipt)) if error.message.is_empty() => {
                                format!("{summary}\n{receipt}")
                            }
                            (Some(summary), Some(receipt)) => {
                                format!("{summary}\n\n{}\n{}", error.message, receipt)
                            }
                            (Some(summary), None) if error.message.is_empty() => summary,
                            (Some(summary), None) => format!("{summary}\n\n{}", error.message),
                            (None, Some(receipt)) if error.message.is_empty() => receipt,
                            (None, Some(receipt)) => format!("{}\n{}", error.message, receipt),
                            (None, None) => error.message,
                        }),
                        exit_code: error.exit_code,
                    },
                }
            },
            debug,
            debug_lines,
        )
    })
}

fn resolve_repo_run_path_and_inputs(
    task_name: &str,
    path: Option<&Path>,
    file_override: Option<&Path>,
    members: &[String],
    task_inputs: &[String],
) -> Result<(PathBuf, Vec<String>), ResolveContractError> {
    match resolve_contract_path(path, file_override) {
        Ok(path) => Ok((path, task_inputs.to_vec())),
        Err(error @ ResolveContractError::MissingExplicitPath { .. }) => {
            maybe_reinterpret_missing_repo_run_path(
                task_name,
                path,
                file_override,
                members,
                task_inputs,
            )
            .ok_or(error)
        }
        Err(error) => Err(error),
    }
}

fn maybe_reinterpret_missing_repo_run_path(
    task_name: &str,
    path: Option<&Path>,
    file_override: Option<&Path>,
    members: &[String],
    task_inputs: &[String],
) -> Option<(PathBuf, Vec<String>)> {
    let shorthand_value = path?;
    if !task_inputs.is_empty() || !can_reinterpret_missing_repo_run_path(shorthand_value) {
        return None;
    }

    let resolved_path = resolve_contract_path(None, file_override).ok()?;
    let contract = load_repo_run_shorthand_contract(&resolved_path, members)?;
    let task = contract.tasks.get(task_name)?;
    if task.inputs.len() != 1 {
        return None;
    }

    Some((
        resolved_path,
        vec![shorthand_value.as_os_str().to_string_lossy().to_string()],
    ))
}

fn load_repo_run_shorthand_contract(path: &Path, members: &[String]) -> Option<Contract> {
    match members {
        [] => load_contract(path).ok(),
        [member] => load_contract_for_member(path, member)
            .ok()
            .map(|(contract, _)| contract),
        _ => None,
    }
}

fn can_reinterpret_missing_repo_run_path(path: &Path) -> bool {
    let value = path.as_os_str().to_string_lossy();
    !value.is_empty()
        && !value.starts_with('.')
        && !value.contains('/')
        && !value.contains('\\')
        && !value.ends_with(".yaml")
        && !value.ends_with(".yml")
}

fn run_command_streaming_enabled(force_stream: bool) -> bool {
    force_stream || (!plain_mode() && (io::stdout().is_terminal() || io::stderr().is_terminal()))
}

fn run_preview_command(
    task_name: &str,
    resolved_path: &Path,
    overrides: ExecutionOverrides,
    members: &[String],
    agent: bool,
    grant: Option<&str>,
    task_inputs: &[String],
    effect_overrides: &[String],
    sandbox_target: Option<&str>,
    format: OutputFormat,
    persist_logs: bool,
) -> CommandOutput {
    let path_display = resolved_path.display().to_string();
    if members.is_empty() {
        return match load_and_validate_target(resolved_path, None) {
            Ok(target) => render_run_preview_target(
                task_name,
                overrides,
                None,
                target,
                agent,
                grant,
                task_inputs,
                effect_overrides,
                sandbox_target,
                format,
                persist_logs,
            ),
            Err(error) => render_run_preview_contract_problem(
                resolved_path,
                None,
                task_name,
                format,
                &path_display,
                error,
            ),
        };
    }

    let mut overall_ok = true;
    let mut text_sections = Vec::new();
    let mut member_results = Vec::new();
    for member in members {
        let target = match load_and_validate_target(resolved_path, Some(member.as_str())) {
            Ok(target) => target,
            Err(error) => {
                return render_run_preview_contract_problem(
                    resolved_path,
                    Some(member.as_str()),
                    task_name,
                    format,
                    &path_display,
                    error,
                );
            }
        };
        let output = render_run_preview_target(
            task_name,
            overrides,
            Some(member.as_str()),
            target,
            agent,
            grant,
            task_inputs,
            effect_overrides,
            sandbox_target,
            format,
            persist_logs,
        );
        overall_ok &= output.exit_code == 0;
        match format {
            OutputFormat::Text => {
                text_sections.push(output.stdout);
            }
            OutputFormat::Json => {
                let parsed = serde_json::from_str::<JsonValue>(&output.stdout)
                    .expect("run preview json should be valid");
                member_results.push(parsed);
            }
        }
    }

    match format {
        OutputFormat::Text => CommandOutput {
            stdout: text_sections.join("\n\n"),
            stderr: None,
            exit_code: if overall_ok { 0 } else { 1 },
        },
        OutputFormat::Json => CommandOutput {
            stdout: to_json_value(json!({
                "ok": overall_ok,
                "path": path_display,
                "task": task_name,
                "dry_run": true,
                "members": member_results,
            })),
            stderr: None,
            exit_code: if overall_ok { 0 } else { 1 },
        },
    }
}

fn render_run_preview_contract_problem(
    resolved_path: &Path,
    member: Option<&str>,
    task_name: &str,
    format: OutputFormat,
    path_display: &str,
    error: ContractProblem,
) -> CommandOutput {
    match error {
        ContractProblem::Validation(errors) => match format {
            OutputFormat::Text => render_task_runtime_bind_validation_text(
                "RUN PREVIEW",
                resolved_path,
                member,
                &errors,
                &["ota validate", "ota run"],
            )
            .map(CommandOutput::failure)
            .unwrap_or_else(|| {
                invalid_repo_contract_output(
                    "RUN PREVIEW",
                    resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    vec![
                        format!(
                            "repair {}",
                            paint_code(&format!("`{}`", compact_contract_path(resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota validate", resolved_path)
                            ))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target(
                                    &repo_run_preview_command(task_name, member),
                                    resolved_path
                                )
                            ))
                        ),
                    ],
                    format,
                )
            }),
            OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                summary: None,
                ok: false,
                path: path_display,
                errors: errors.errors().iter().map(ToString::to_string).collect(),
                error: None,
                warnings: Vec::new(),
                warning_details: Vec::new(),
            })),
        },
        ContractProblem::Load(error) => match format {
            OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                "RUN PREVIEW",
                resolved_path,
                "Contract could not be loaded",
                &error.to_string(),
                &[
                    format!(
                        "repair {}",
                        paint_code(&format!("`{}`", compact_contract_path(resolved_path)))
                    ),
                    format!(
                        "rerun {}",
                        paint_code(&format!(
                            "`{}`",
                            command_for_repo_contract_target("ota validate", resolved_path)
                        ))
                    ),
                    format!(
                        "rerun `{}`",
                        command_for_repo_contract_target(
                            &repo_run_preview_command(task_name, member),
                            resolved_path
                        )
                    ),
                ],
            )),
            OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                summary: None,
                ok: false,
                path: path_display,
                errors: Vec::new(),
                error: Some(error.to_string()),
                warnings: Vec::new(),
                warning_details: Vec::new(),
            })),
        },
    }
}

fn run_preview_preconditions_report(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    overrides: ExecutionOverrides,
    replay_input_preflight: &TaskReplayInputPreflight,
) -> DoctorReport {
    let mode = doctor_mode_from_backend(Some(format_backend(
        effective_task_execution(contract, task_name, overrides).backend,
    )))
    .unwrap_or(DoctorMode::Native);
    let mut report =
        diagnose_preconditions_non_mutating_with_mode_for_task_with_overrides_and_replay_input_policy(
            contract,
            contract_path,
            mode,
            task_name,
            overrides,
            replay_input_preflight.policy.as_ref(),
            replay_input_preflight.doctor_policy_snapshot(),
        );
    append_safe_task_effect_policy_findings(
        contract,
        task_name,
        overrides,
        replay_input_preflight.loaded_policy.as_ref(),
        &mut report,
    );
    report
}

fn run_execution_preconditions_report(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    overrides: ExecutionOverrides,
    replay_input_preflight: &TaskReplayInputPreflight,
) -> DoctorReport {
    let mode = doctor_mode_from_backend(Some(format_backend(
        effective_task_execution(contract, task_name, overrides).backend,
    )))
    .unwrap_or(DoctorMode::Native);
    let mut report =
        diagnose_preconditions_with_mode_for_task_with_overrides_and_replay_input_policy(
            contract,
            contract_path,
            mode,
            task_name,
            overrides,
            replay_input_preflight.policy.as_ref(),
            replay_input_preflight.doctor_policy_snapshot(),
        );
    append_safe_task_effect_policy_findings(
        contract,
        task_name,
        overrides,
        replay_input_preflight.loaded_policy.as_ref(),
        &mut report,
    );
    report
}

fn task_is_declared_agent_safe(contract: &Contract, task_name: &str) -> bool {
    contract
        .tasks
        .get(task_name)
        .is_some_and(|task| task.safe_for_agent)
        || contract
            .agent
            .as_ref()
            .is_some_and(|agent| agent.safe_tasks.iter().any(|safe| safe == task_name))
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct TaskEffectiveSafety {
    pub declared_safe: bool,
    pub effective_safe: bool,
    pub unsafe_closure_tasks: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct WorkflowEffectiveSafety {
    pub declared_safe: Option<bool>,
    pub effective_safe: Option<bool>,
    pub unsafe_closure_tasks: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct AgentExecutionRefusal {
    requested_task: String,
    blocked_task: String,
    path: Vec<String>,
    reason: &'static str,
}

impl AgentExecutionRefusal {
    fn closure_status(&self) -> &'static str {
        match self.reason {
            "unsafe_dependency_closure" => "unsafe_dependency_closure",
            "claim_assurance_policy_denied" => "policy_denied",
            "claim_assurance_policy_review_required" => "policy_review_required",
            "org_policy_unavailable" => "policy_unavailable",
            _ => "unsafe",
        }
    }

    fn governance_record(&self) -> crate::output::GovernanceRefusalRecord {
        crate::output::GovernanceRefusalRecord {
            reason_family: self.reason.to_string(),
            boundary_family: String::from("agent_safety_boundary"),
            closure_status: self.closure_status().to_string(),
            requested_task: self.requested_task.clone(),
            blocked_task: self.blocked_task.clone(),
            closure_path: self.path.clone(),
            evidence_class: String::from("derived"),
            authority_source: None,
            authority_id: None,
            requested_grant_id: None,
            scope_identity: None,
            contract_identity: None,
            scope_boundary_family: None,
            scope_classification: None,
            evaluation_details: None,
            execution_started: None,
        }
    }
}

/// The authoritative pre-execution result for agent-mode admission.
///
/// Normal execution and refusal canaries consume this one decision so a canary cannot exercise a
/// parallel, weaker policy path.
#[derive(Debug, Clone, PartialEq, Eq)]
enum AgentExecutionAdmission {
    SafetyRefused(AgentExecutionRefusal),
    PolicyRefused(AgentExecutionRefusal),
    Admitted,
}

impl AgentExecutionAdmission {
    fn refusal(&self) -> Option<&AgentExecutionRefusal> {
        match self {
            Self::SafetyRefused(refusal) | Self::PolicyRefused(refusal) => Some(refusal),
            Self::Admitted => None,
        }
    }
}

fn collect_reachable_task_names_for_visibility(
    contract: &Contract,
    root_task_name: &str,
    overrides: ExecutionOverrides,
) -> Vec<String> {
    let mut ordered = Vec::new();
    let mut visited = BTreeSet::new();
    let mut stack = vec![(root_task_name.to_string(), overrides)];
    while let Some((task_name, current_overrides)) = stack.pop() {
        let backend =
            effective_task_execution(contract, task_name.as_str(), current_overrides).backend;
        if !visited.insert((task_name.clone(), format_backend(backend).to_string())) {
            continue;
        }
        ordered.push(task_name.clone());
        let Some(task) = contract.tasks.get(task_name.as_str()) else {
            continue;
        };
        for dependency in task
            .aggregate
            .iter()
            .flat_map(|aggregate| aggregate.tasks.iter())
        {
            if contract.tasks.contains_key(dependency) {
                stack.push((dependency.clone(), ExecutionOverrides::default()));
            }
        }
        for dependency in task.depends_on_for_backend(backend) {
            let Some(dependency_task) = contract.tasks.get(dependency) else {
                continue;
            };
            stack.push((
                dependency.clone(),
                ExecutionOverrides {
                    backend: dependency_task
                        .dependency_backend_override_for_parent(current_overrides.backend, backend),
                    ..current_overrides
                },
            ));
        }
        for hook in task
            .after_success
            .iter()
            .chain(task.after_failure.iter())
            .chain(task.after_always.iter())
        {
            if contract.tasks.contains_key(hook) {
                stack.push((hook.clone(), ExecutionOverrides::default()));
            }
        }
    }
    ordered
}

fn first_unsafe_task_path_for_visibility(
    contract: &Contract,
    root_task_name: &str,
    overrides: ExecutionOverrides,
) -> Vec<String> {
    if !task_is_declared_agent_safe(contract, root_task_name) {
        return vec![root_task_name.to_string()];
    }

    fn visit(
        contract: &Contract,
        current: &str,
        overrides: ExecutionOverrides,
        path: &mut Vec<String>,
        visited: &mut BTreeSet<(String, String)>,
    ) -> Option<Vec<String>> {
        let backend = effective_task_execution(contract, current, overrides).backend;
        if !visited.insert((current.to_string(), format_backend(backend).to_string())) {
            return None;
        }
        path.push(current.to_string());
        let Some(task) = contract.tasks.get(current) else {
            path.pop();
            return None;
        };

        for dependency in task
            .aggregate
            .iter()
            .flat_map(|aggregate| aggregate.tasks.iter())
        {
            if !contract.tasks.contains_key(dependency) {
                continue;
            }
            if !task_is_declared_agent_safe(contract, dependency) {
                let mut refusal_path = path.clone();
                refusal_path.push(dependency.clone());
                path.pop();
                return Some(refusal_path);
            }
            if let Some(found) = visit(
                contract,
                dependency,
                ExecutionOverrides::default(),
                path,
                visited,
            ) {
                path.pop();
                return Some(found);
            }
        }

        for dependency in task.depends_on_for_backend(backend) {
            let Some(dependency_task) = contract.tasks.get(dependency) else {
                continue;
            };
            let dependency_overrides = ExecutionOverrides {
                backend: dependency_task
                    .dependency_backend_override_for_parent(overrides.backend, backend),
                ..overrides
            };
            if !task_is_declared_agent_safe(contract, dependency) {
                let mut refusal_path = path.clone();
                refusal_path.push(dependency.to_string());
                path.pop();
                return Some(refusal_path);
            }
            if let Some(found) = visit(contract, dependency, dependency_overrides, path, visited) {
                path.pop();
                return Some(found);
            }
        }

        for hook in task
            .after_success
            .iter()
            .chain(task.after_failure.iter())
            .chain(task.after_always.iter())
        {
            if !contract.tasks.contains_key(hook) {
                continue;
            }
            if !task_is_declared_agent_safe(contract, hook) {
                let mut refusal_path = path.clone();
                refusal_path.push(hook.clone());
                path.pop();
                return Some(refusal_path);
            }
            if let Some(found) = visit(contract, hook, ExecutionOverrides::default(), path, visited)
            {
                path.pop();
                return Some(found);
            }
        }

        path.pop();
        None
    }

    visit(
        contract,
        root_task_name,
        overrides,
        &mut Vec::new(),
        &mut BTreeSet::new(),
    )
    .unwrap_or_else(|| vec![root_task_name.to_string()])
}

fn agent_execution_refusal_for_task(
    contract: &Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
) -> Option<AgentExecutionRefusal> {
    let task_name = canonical_declared_task_name(contract, task_name);
    let safety = task_effective_safety_with_overrides(contract, task_name.as_str(), overrides);
    if safety.declared_safe && safety.effective_safe {
        return None;
    }

    let path = if safety.declared_safe {
        first_unsafe_task_path_for_visibility(contract, task_name.as_str(), overrides)
    } else {
        vec![task_name.to_string()]
    };
    let blocked_task = path.last().cloned().unwrap_or_else(|| task_name.clone());
    let reason = if safety.declared_safe {
        "unsafe_dependency_closure"
    } else {
        "requested_task_not_safe"
    };

    Some(AgentExecutionRefusal {
        requested_task: task_name,
        blocked_task,
        path,
        reason,
    })
}

fn agent_execution_admission(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    overrides: ExecutionOverrides,
    policy_snapshot: DoctorPolicySnapshot<'_>,
) -> AgentExecutionAdmission {
    if policy_snapshot.load_error.is_some() {
        let task_name = canonical_declared_task_name(contract, task_name);
        return AgentExecutionAdmission::PolicyRefused(AgentExecutionRefusal {
            requested_task: task_name.clone(),
            blocked_task: task_name.clone(),
            path: vec![task_name],
            reason: "org_policy_unavailable",
        });
    }
    if let Some(refusal) = agent_execution_refusal_for_task(contract, task_name, overrides) {
        return AgentExecutionAdmission::SafetyRefused(refusal);
    }
    let task_name = canonical_declared_task_name(contract, task_name);
    let policy_refusal = doctor_claim_assurance_with_overrides(
        contract,
        contract_path,
        overrides,
        policy_snapshot.loaded,
    )
    .into_iter()
    .find(|record| {
        record.subject.kind == "task"
            && record.subject.name == task_name
            && record.family == "agent_safety"
            && matches!(record.policy.decision.as_str(), "deny" | "review")
    })
    .map(|record| AgentExecutionRefusal {
        requested_task: task_name.clone(),
        blocked_task: task_name.clone(),
        path: vec![task_name],
        reason: if record.policy.decision == "deny" {
            "claim_assurance_policy_denied"
        } else {
            "claim_assurance_policy_review_required"
        },
    });
    match policy_refusal {
        Some(refusal) => AgentExecutionAdmission::PolicyRefused(refusal),
        None => AgentExecutionAdmission::Admitted,
    }
}

fn agent_execution_refusal_with_policy(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    overrides: ExecutionOverrides,
    policy_snapshot: DoctorPolicySnapshot<'_>,
) -> Option<AgentExecutionRefusal> {
    agent_execution_admission(
        contract,
        contract_path,
        task_name,
        overrides,
        policy_snapshot,
    )
    .refusal()
    .cloned()
}

/// CI projection must use the same ordered workflow roots as `ota up --agent`; checking only the
/// run task could publish a lane whose setup or prepare phase the runner later refuses.
fn agent_workflow_execution_refusal_with_policy(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    run_behavior_preference: UpRunBehaviorPreference,
    policy_snapshot: DoctorPolicySnapshot<'_>,
) -> Option<AgentExecutionRefusal> {
    selected_up_agent_task_names(contract, workflow_name, run_behavior_preference)
        .into_iter()
        .find_map(|task_name| {
            agent_execution_admission(
                contract,
                contract_path,
                task_name.as_str(),
                overrides,
                policy_snapshot,
            )
            .refusal()
            .cloned()
        })
}

