#[allow(clippy::too_many_arguments)]
pub(crate) fn up_with_agent_reason_and_grant_and_effect_canary(
    path: Option<&Path>,
    file_override: Option<&Path>,
    overrides: ExecutionOverrides,
    effect_overrides: &[String],
    members: &[String],
    workflow_name: Option<&str>,
    agent: bool,
    expect_refusal: bool,
    expect_effect_refusal: Option<&str>,
    archive_effect_refusal: bool,
    reason: Option<&str>,
    grant: Option<&str>,
    sandbox_target: Option<&str>,
    format: OutputFormat,
    debug: bool,
    dry_run: bool,
    stream: bool,
    show_receipt: bool,
    replay_baseline: Option<&str>,
    attach: bool,
    detach: bool,
    ready_timeout: Option<&str>,
) -> CommandOutput {
    activate_mise_paths_for_current_process();
    if let Some(duplicate) = duplicate_member(members) {
        return finalize_debug(
            CommandOutput::failure_with_code(
                format!("`--member {duplicate}` was provided more than once"),
                2,
            ),
            debug,
            vec![String::from("DEBUG command=up")],
        );
    }
    let parsed_effect_overrides = match parse_effect_governance_overrides(effect_overrides) {
        Ok(overrides) => overrides,
        Err(error) => {
            return finalize_debug(
                CommandOutput::failure_with_code(error, 2),
                debug,
                vec![String::from("DEBUG command=up")],
            );
        }
    };
    if stream && matches!(format, OutputFormat::Json) {
        return finalize_debug(
            CommandOutput::failure_with_code(
                String::from("`--stream` is only supported for text output"),
                2,
            ),
            debug,
            vec![
                String::from("DEBUG command=up"),
                String::from("DEBUG stream=true"),
            ],
        );
    }
    if stream && dry_run {
        return finalize_debug(
            CommandOutput::failure_with_code(
                String::from("`--stream` is only supported for mutating `ota up`"),
                2,
            ),
            debug,
            vec![
                String::from("DEBUG command=up"),
                String::from("DEBUG stream=true"),
                String::from("DEBUG dry_run=true"),
            ],
        );
    }
    if replay_baseline.is_some() && dry_run {
        return finalize_debug(
            CommandOutput::failure_with_code(
                String::from("`--replay-baseline` is only supported for mutating `ota up`"),
                2,
            ),
            debug,
            vec![
                String::from("DEBUG command=up"),
                String::from("DEBUG dry_run=true"),
            ],
        );
    }
    if replay_baseline.is_some() && stream {
        return finalize_debug(
            CommandOutput::failure_with_code(
                String::from("`--replay-baseline` is not supported with `--stream`"),
                2,
            ),
            debug,
            vec![
                String::from("DEBUG command=up"),
                String::from("DEBUG stream=true"),
            ],
        );
    }
    if replay_baseline.is_some() && !members.is_empty() {
        return finalize_debug(
            CommandOutput::failure_with_code(
                String::from("`--replay-baseline` is not supported with `--member`"),
                2,
            ),
            debug,
            vec![
                String::from("DEBUG command=up"),
                format!("DEBUG members={}", members.len()),
            ],
        );
    }
    let run_behavior_preference = if detach {
        UpRunBehaviorPreference::Detach
    } else if attach {
        UpRunBehaviorPreference::Attach
    } else {
        UpRunBehaviorPreference::Auto
    };
    let ready_timeout = match ready_timeout {
        Some(value) => match parse_readiness_duration_spec(value) {
            Some(duration) => Some(duration),
            None => {
                return finalize_debug(
                    CommandOutput::failure_with_code(
                        format!(
                            "`--ready-timeout {value}` is invalid; expected values like `90s`, `5m`, or `1h`"
                        ),
                        2,
                    ),
                    debug,
                    vec![
                        String::from("DEBUG command=up"),
                        format!("DEBUG stream={stream}"),
                    ],
                );
            }
        },
        None => None,
    };

    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => {
                        missing_repo_contract_command_output("UP", "ota up", &error)
                            .unwrap_or_else(|| CommandOutput::failure(error.to_string()))
                    }
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=up")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let single_member = (members.len() == 1).then(|| members[0].as_str());
    let text_path_display = display_contract_target(&compact_path_display, single_member);
    let mut debug_lines = vec![
        String::from("DEBUG command=up"),
        format!("DEBUG contract_path={path_display}"),
        format!("DEBUG stream={stream}"),
        format!("DEBUG up_behavior_preference={run_behavior_preference:?}"),
    ];
    if let Some(timeout) = ready_timeout {
        debug_lines.push(format!("DEBUG ready_timeout_secs={}", timeout.as_secs()));
    }
    if agent {
        debug_lines.push(String::from("DEBUG agent=true"));
    }
    if let Some(canary_id) = expect_effect_refusal {
        debug_lines.push(format!("DEBUG expect_effect_refusal={canary_id}"));
    }
    if let Some(reason) = reason {
        debug_lines.push(format!("DEBUG reason={reason}"));
    }
    if let Some(grant) = grant {
        debug_lines.push(format!("DEBUG grant={grant}"));
    }
    if let Some(baseline) = replay_baseline {
        debug_lines.push(format!("DEBUG replay_baseline={baseline}"));
    }
    for member in members {
        debug_lines.push(format!("DEBUG member={member}"));
    }
    if !parsed_effect_overrides.decisions.is_empty() {
        for (effect, decision) in &parsed_effect_overrides.decisions {
            debug_lines.push(format!(
                "DEBUG effect_override={effect}={}",
                decision.as_str()
            ));
        }
    }
    let execution_mode = if stream {
        RepoExecutionMode::Stream
    } else {
        RepoExecutionMode::Capture
    };

    if is_org_policy_pack_path(&resolved_path) {
        return finalize_debug(
            wrong_repo_contract_target_output(
                "UP",
                &resolved_path,
                "Wrong command target",
                &[
                    String::from("`ota up` prepares repo contracts such as `ota.yaml`"),
                    format!(
                        "{} is an org policy pack, not a repo contract",
                        paint_code(&compact_path(&resolved_path, DEFAULT_POLICY_FILE))
                    ),
                ],
                wrong_target_next_steps_for_repo_command("ota up", &resolved_path),
                format,
            ),
            debug,
            debug_lines,
        );
    }

    with_effect_governance_override_map(&parsed_effect_overrides, || {
        finalize_debug(
            match load_and_validate_target(&resolved_path, single_member) {
                Ok(target) if members.is_empty() || members.len() == 1 => {
                    if let Some(canary_id) = expect_effect_refusal {
                        return match workflow_name {
                            Some(workflow_name) => up_effect_refusal_canary_command(
                                &target,
                                workflow_name,
                                canary_id,
                                overrides,
                                effect_overrides,
                                members,
                                reason,
                                grant,
                                sandbox_target,
                                format,
                            ),
                            None => CommandOutput::failure_with_code(
                                String::from(
                                    "`ota up --expect-effect-refusal` requires an explicit `--workflow` canary target",
                                ),
                                2,
                            ),
                        };
                    }
                    if expect_refusal {
                        return match workflow_name {
                            Some(workflow_name) => {
                                up_refusal_canary_command(&target, workflow_name, overrides, format)
                            }
                            None => CommandOutput::failure_with_code(
                                String::from(
                                    "`ota up --expect-refusal` requires an explicit `--workflow` canary target",
                                ),
                                2,
                            ),
                        };
                    }
                    if archive_effect_refusal {
                        let result = match typed_effect_up_pre_execution_result(
                            &target.contract,
                            &target.contract_path,
                            overrides,
                            workflow_name,
                            agent,
                            false,
                            true,
                        ) {
                            Ok(Some(result)) => result,
                            Ok(None) => {
                                return CommandOutput::failure_with_code(
                                    String::from(
                                        "`--archive-effect-refusal` is not applicable because the selected workflow has no explicit typed policy refusal",
                                    ),
                                    1,
                                );
                            }
                            Err(TypedEffectRefusalArchiveError::Failed(error)) => {
                                return CommandOutput::failure(error);
                            }
                            Err(TypedEffectRefusalArchiveError::DurabilityUncertain(outcome)) => {
                                let receipt_published = outcome.artifact_kind == "receipt";
                                let code = if receipt_published {
                                    "effect_refusal_archive_durability_uncertain"
                                } else {
                                    "effect_refusal_snapshot_durability_uncertain"
                                };
                                let recovery = if receipt_published {
                                    "retain the published receipt, verify it with `ota receipt --history --json`, and copy the repository only after the containing directory is durably synchronized"
                                } else {
                                    "retain the published snapshot and rerun the same archive command; no refusal receipt was published by this attempt"
                                };
                                return CommandOutput {
                                    stdout: to_json(&json!({
                                        "ok": false,
                                        "path": path_display,
                                        "code": code,
                                        "published": true,
                                        "durability": "uncertain",
                                        "artifact_kind": outcome.artifact_kind,
                                        "receipt_published": receipt_published,
                                        "archive_path": receipt_storage_path_display(&outcome.path),
                                        "message": outcome.message,
                                        "recovery": recovery,
                                    })),
                                    stderr: None,
                                    exit_code: 1,
                                };
                            }
                            Err(TypedEffectRefusalArchiveError::PostPublicationFailure(
                                outcome,
                            )) => {
                                return CommandOutput {
                                    stdout: to_json(&json!({
                                        "ok": false,
                                        "path": path_display,
                                        "code": "effect_refusal_archive_post_publication_failed",
                                        "published": true,
                                        "durability": "confirmed",
                                        "artifact_kind": outcome.artifact_kind,
                                        "receipt_published": true,
                                        "archive_path": receipt_storage_path_display(&outcome.path),
                                        "message": outcome.message,
                                        "recovery": "retain the published receipt, verify it with `ota receipt --history --json`, then resolve the archive maintenance failure before retrying",
                                    })),
                                    stderr: None,
                                    exit_code: 1,
                                };
                            }
                        };
                        return CommandOutput {
                            stdout: to_json_value(up_result_json_value(&path_display, &result)),
                            stderr: None,
                            exit_code: if result.ok { 0 } else { 1 },
                        };
                    }
                    if members.is_empty()
                        && target.contract_path == resolved_path
                        && target.contract.workspace.as_ref().is_some_and(|workspace| {
                            workspace.workspace_type == crate::schema::RepoWorkspaceType::Monorepo
                        })
                    {
                        if replay_baseline.is_some() {
                            return CommandOutput::failure_with_code(
                                String::from(
                                    "`--replay-baseline` is not supported for monorepo root `ota up`; select a concrete repo contract or member lane first",
                                ),
                                2,
                            );
                        }
                        let mut root_result =
                            match execute_repo_up_with_behavior_with_agent_and_grant(
                                &target.contract,
                                &target.contract_path,
                                overrides,
                                workflow_name,
                                effect_overrides,
                                agent,
                                grant,
                                reason,
                                sandbox_target,
                                None,
                                dry_run,
                                execution_mode,
                                run_behavior_preference,
                                ready_timeout,
                            ) {
                                Ok(result) => result,
                                Err(error) => return CommandOutput::failure(error),
                            };
                        attach_crossing_to_up_result(
                            &mut root_result,
                            &target.contract,
                            workflow_name,
                            overrides,
                            run_behavior_preference,
                            agent,
                            reason,
                        );
                        let mut overall_ok = root_result.ok;
                        let mut text_sections = vec![render_up_section_with_receipt(
                            &text_path_display,
                            &root_result,
                            show_receipt,
                        )];
                        let mut member_results = Vec::new();

                        if let Some(workspace) = target.contract.workspace.as_ref() {
                            for member in &workspace.members {
                                let member_target =
                                    match load_and_validate_target(&resolved_path, Some(member)) {
                                        Ok(target) => target,
                                        Err(ContractProblem::Validation(errors)) => {
                                            return match format {
                                                OutputFormat::Text => {
                                                    CommandOutput::failure(errors.to_string())
                                                }
                                                OutputFormat::Json => CommandOutput::failure(
                                                    to_json(&ValidateFailure {
                                                        summary: None,
                                                        ok: false,
                                                        path: &path_display,
                                                        errors: errors
                                                            .errors()
                                                            .iter()
                                                            .map(ToString::to_string)
                                                            .collect(),
                                                        error: None,
                                                        warnings: Vec::new(),
                                                        warning_details: Vec::new(),
                                                    }),
                                                ),
                                            };
                                        }
                                        Err(ContractProblem::Load(error)) => {
                                            return match format {
                                                OutputFormat::Text => {
                                                    CommandOutput::failure(error.to_string())
                                                }
                                                OutputFormat::Json => CommandOutput::failure(
                                                    to_json(&ValidateFailure {
                                                        summary: None,
                                                        ok: false,
                                                        path: &path_display,
                                                        errors: Vec::new(),
                                                        error: Some(error.to_string()),
                                                        warnings: Vec::new(),
                                                        warning_details: Vec::new(),
                                                    }),
                                                ),
                                            };
                                        }
                                    };
                                let mut member_result =
                                    match execute_repo_up_with_behavior_with_agent_and_grant(
                                        &member_target.contract,
                                        &member_target.contract_path,
                                        overrides,
                                        workflow_name,
                                        effect_overrides,
                                        agent,
                                        grant,
                                        reason,
                                        sandbox_target,
                                        None,
                                        dry_run,
                                        execution_mode,
                                        run_behavior_preference,
                                        ready_timeout,
                                    ) {
                                        Ok(result) => result,
                                        Err(error) => return CommandOutput::failure(error),
                                    };
                                attach_crossing_to_up_result(
                                    &mut member_result,
                                    &member_target.contract,
                                    workflow_name,
                                    overrides,
                                    run_behavior_preference,
                                    agent,
                                    reason,
                                );
                                if !member_result.ok {
                                    overall_ok = false;
                                }
                                text_sections.push(render_up_section_with_receipt(
                                    &display_contract_target(
                                        &compact_path_display,
                                        Some(member.as_str()),
                                    ),
                                    &member_result,
                                    show_receipt,
                                ));
                                member_results
                                    .push(up_member_result_json_value(member, &member_result));
                            }
                        }

                        match format {
                            OutputFormat::Text => CommandOutput {
                                stdout: text_sections.join("\n\n"),
                                stderr: None,
                                exit_code: if overall_ok { 0 } else { 1 },
                            },
                            OutputFormat::Json => {
                                let mut root_value =
                                    up_result_json_value(&path_display, &root_result);
                                root_value["members"] = JsonValue::Array(member_results);
                                CommandOutput {
                                    stdout: to_json_value(root_value),
                                    stderr: None,
                                    exit_code: if overall_ok { 0 } else { 1 },
                                }
                            }
                        }
                    } else {
                        let replay_baseline = match replay_baseline {
                            Some(selection) => {
                                let root = contract_working_dir(&target.contract_path);
                                match load_repo_receipt_baseline(
                                    root,
                                    &target.contract_path,
                                    workflow_name,
                                    selection,
                                ) {
                                    Ok(baseline) => Some(baseline),
                                    Err(error) => return CommandOutput::failure(error),
                                }
                            }
                            None => None,
                        };
                        match execute_repo_up_with_behavior_with_agent_and_grant(
                            &target.contract,
                            &target.contract_path,
                            overrides,
                            workflow_name,
                            effect_overrides,
                            agent,
                            grant,
                            reason,
                            sandbox_target,
                            None,
                            dry_run,
                            execution_mode,
                            run_behavior_preference,
                            ready_timeout,
                        ) {
                            Ok(mut result) => {
                                if let Err(error) = attach_repo_contract_snapshot_to_receipt(
                                    &target.contract_path,
                                    &target.contract,
                                    &mut result.receipt,
                                ) {
                                    return CommandOutput::failure(error);
                                }
                                attach_crossing_to_up_result(
                                    &mut result,
                                    &target.contract,
                                    workflow_name,
                                    overrides,
                                    run_behavior_preference,
                                    agent,
                                    reason,
                                );
                                if let Some(baseline) = replay_baseline {
                                    let current_contract_identity = repo_receipt_contract_identity(
                                        contract_working_dir(&target.contract_path),
                                        &target.contract_path,
                                        workflow_name,
                                    );
                                    match build_repo_receipt_diff_report(
                                        baseline,
                                        &target.contract,
                                        current_contract_identity,
                                        &result.receipt,
                                        &result.report.findings,
                                        workflow_name,
                                    ) {
                                        Ok(report) => render_up_replay_result(
                                            &path_display,
                                            &text_path_display,
                                            result,
                                            format,
                                            show_receipt,
                                            build_up_replay_execution(report),
                                        ),
                                        Err(error) => CommandOutput::failure(error),
                                    }
                                } else {
                                    render_up_result(
                                        &path_display,
                                        &text_path_display,
                                        result,
                                        format,
                                        show_receipt,
                                    )
                                }
                            }
                            Err(error) => CommandOutput::failure(error),
                        }
                    }
                }
                Ok(_) => {
                    let mut overall_ok = true;
                    let mut text_sections = Vec::new();
                    let mut member_results = Vec::new();
                    for member in members {
                        let target =
                            match load_and_validate_target(&resolved_path, Some(member.as_str())) {
                                Ok(target) => target,
                                Err(ContractProblem::Validation(errors)) => {
                                    return match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(errors.to_string())
                                        }
                                        OutputFormat::Json => {
                                            CommandOutput::failure(to_json(&ValidateFailure {
                                                summary: None,
                                                ok: false,
                                                path: &path_display,
                                                errors: errors
                                                    .errors()
                                                    .iter()
                                                    .map(ToString::to_string)
                                                    .collect(),
                                                error: None,
                                                warnings: Vec::new(),
                                                warning_details: Vec::new(),
                                            }))
                                        }
                                    };
                                }
                                Err(ContractProblem::Load(error)) => {
                                    return match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(error.to_string())
                                        }
                                        OutputFormat::Json => {
                                            CommandOutput::failure(to_json(&ValidateFailure {
                                                summary: None,
                                                ok: false,
                                                path: &path_display,
                                                errors: Vec::new(),
                                                error: Some(error.to_string()),
                                                warnings: Vec::new(),
                                                warning_details: Vec::new(),
                                            }))
                                        }
                                    };
                                }
                            };
                        let mut result = match execute_repo_up_with_behavior_with_agent_and_grant(
                            &target.contract,
                            &target.contract_path,
                            overrides,
                            workflow_name,
                            effect_overrides,
                            agent,
                            grant,
                            reason,
                            sandbox_target,
                            None,
                            dry_run,
                            execution_mode,
                            run_behavior_preference,
                            ready_timeout,
                        ) {
                            Ok(result) => result,
                            Err(error) => return CommandOutput::failure(error),
                        };
                        attach_crossing_to_up_result(
                            &mut result,
                            &target.contract,
                            workflow_name,
                            overrides,
                            run_behavior_preference,
                            agent,
                            reason,
                        );
                        if !result.ok {
                            overall_ok = false;
                        }
                        text_sections.push(render_up_section_with_receipt(
                            &display_contract_target(&compact_path_display, Some(member.as_str())),
                            &result,
                            show_receipt,
                        ));
                        member_results.push(up_member_result_json_value(member, &result));
                    }

                    match format {
                        OutputFormat::Text => CommandOutput {
                            stdout: text_sections.join("\n\n"),
                            stderr: None,
                            exit_code: if overall_ok { 0 } else { 1 },
                        },
                        OutputFormat::Json => CommandOutput {
                            stdout: to_json_value(json!({
                                "ok": overall_ok,
                                "path": path_display,
                                "dry_run": dry_run,
                                "members": member_results,
                                "status": "MULTI",
                                "phase": "aggregate",
                                "findings": Vec::<JsonValue>::new(),
                            })),
                            stderr: None,
                            exit_code: if overall_ok { 0 } else { 1 },
                        },
                    }
                }
                Err(ContractProblem::Validation(errors)) => match format {
                    OutputFormat::Text => invalid_repo_contract_output(
                        "UP",
                        &resolved_path,
                        &errors
                            .errors()
                            .iter()
                            .map(ToString::to_string)
                            .collect::<Vec<_>>(),
                        vec![
                            format!(
                                "repair {}",
                                paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                            ),
                            format!(
                                "rerun {}",
                                paint_code(&format!(
                                    "`{}`",
                                    command_for_repo_contract_target(
                                        "ota validate",
                                        &resolved_path
                                    )
                                ))
                            ),
                            format!(
                                "rerun {}",
                                paint_code(&format!(
                                    "`{}`",
                                    command_for_repo_contract_target("ota up", &resolved_path)
                                ))
                            ),
                        ],
                        format,
                    ),
                    OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                        summary: None,
                        ok: false,
                        path: &path_display,
                        errors: errors.errors().iter().map(ToString::to_string).collect(),
                        error: None,
                        warnings: Vec::new(),
                        warning_details: Vec::new(),
                    })),
                },
                Err(ContractProblem::Load(error)) => match format {
                    OutputFormat::Text => CommandOutput::failure(repo_contract_load_text(
                        "UP",
                        &resolved_path,
                        "Contract could not be loaded",
                        &error.to_string(),
                        &[
                            format!(
                                "repair {}",
                                paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                            ),
                            format!(
                                "rerun {}",
                                paint_code(&format!(
                                    "`{}`",
                                    command_for_repo_contract_target(
                                        "ota validate",
                                        &resolved_path
                                    )
                                ))
                            ),
                            format!(
                                "rerun {}",
                                paint_code(&format!(
                                    "`{}`",
                                    command_for_repo_contract_target("ota up", &resolved_path)
                                ))
                            ),
                        ],
                    )),
                    OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                        summary: None,
                        ok: false,
                        path: &path_display,
                        errors: Vec::new(),
                        error: Some(error.to_string()),
                        warnings: Vec::new(),
                        warning_details: Vec::new(),
                    })),
                },
            },
            debug,
            debug_lines,
        )
    })
}

pub fn clean(
    path: Option<&Path>,
    file_override: Option<&Path>,
    members: &[String],
    stale: bool,
    dry_run: bool,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let unresolved_target_display = unresolved_contract_target_path(path, file_override);
    if stale {
        let mut debug_lines = vec![
            String::from("DEBUG command=clean"),
            String::from("DEBUG stale=true"),
        ];
        if dry_run {
            debug_lines.push(String::from("DEBUG dry_run=true"));
        }
        if let Some(path) = path {
            debug_lines.push(format!("DEBUG rejected_path={}", path.display()));
        }
        if let Some(file_override) = file_override {
            debug_lines.push(format!("DEBUG rejected_file={}", file_override.display()));
        }
        if !members.is_empty() {
            for member in members {
                debug_lines.push(format!("DEBUG rejected_member={member}"));
            }
        }

        if path.is_some() || file_override.is_some() || !members.is_empty() {
            return finalize_debug(
                CommandOutput::failure_with_code(
                    String::from(
                        "`ota clean --stale` is global and does not take PATH, `--file`, or `--member`",
                    ),
                    2,
                ),
                debug,
                debug_lines,
            );
        }

        return finalize_debug(
            {
                match clean_stale_execution(dry_run) {
                    Ok(report) => {
                        let matched_count = report.containers.len();
                        let engines = report.engines;
                        let containers = report.containers;
                        match format {
                            OutputFormat::Text => CommandOutput::success(render_stale_clean_text(
                                &containers,
                                dry_run,
                            )),
                            OutputFormat::Json => CommandOutput::success(to_json_value(json!({
                                "ok": true,
                                "scope": "stale",
                                "dry_run": dry_run,
                                "engines": engines,
                                "summary": {
                                    "matched_count": matched_count,
                                    "removed_count": if dry_run { 0 } else { matched_count },
                                    "would_remove_count": if dry_run { matched_count } else { 0 }
                                },
                                "containers": containers.iter().map(|container| json!({
                                    "engine": container.engine,
                                    "name": container.name,
                                    "ownership": match container.ownership {
                                        StaleContainerOwnership::Label => "label",
                                        StaleContainerOwnership::LegacyName => "legacy_name"
                                    }
                                })).collect::<Vec<_>>()
                            }))),
                        }
                    }
                    Err(error) => match format {
                        OutputFormat::Text => CommandOutput::failure(render_clean_failure_text(
                            "ota clean --stale",
                            &error,
                            "Stale cleanup failed",
                        )),
                        OutputFormat::Json => {
                            CommandOutput::failure(to_json_value(clean_failure_json_value(
                                "ota clean --stale",
                                &error,
                                "Stale cleanup failed",
                            )))
                        }
                    },
                }
            },
            debug,
            debug_lines,
        );
    }

    if let Some(duplicate) = duplicate_member(members) {
        return finalize_debug(
            CommandOutput::failure_with_code(
                format!("`--member {duplicate}` was provided more than once"),
                2,
            ),
            debug,
            vec![String::from("DEBUG command=clean")],
        );
    }

    let resolved_path = match resolve_contract_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => {
                        missing_repo_contract_command_output("CLEAN", "ota clean", &error)
                            .unwrap_or_else(|| {
                                CommandOutput::failure(command_message_failure_text(
                                    "CLEAN",
                                    "ota clean",
                                    "Contract target could not be resolved",
                                    &error.to_string(),
                                    &[],
                                ))
                            })
                    }
                    OutputFormat::Json => clean_generic_failure_json_output(
                        &unresolved_target_display,
                        "Contract target could not be resolved",
                        error.to_string(),
                    ),
                },
                debug,
                vec![String::from("DEBUG command=clean")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_contract_path(&resolved_path);
    let single_member = (members.len() == 1).then(|| members[0].as_str());
    let text_path_display = display_contract_target(&compact_path_display, single_member);
    let mut debug_lines = vec![
        String::from("DEBUG command=clean"),
        format!("DEBUG contract_path={path_display}"),
    ];
    for member in members {
        debug_lines.push(format!("DEBUG member={member}"));
    }

    if is_org_policy_pack_path(&resolved_path) {
        let why_lines = vec![
            format!(
                "{} reads repo contracts such as {}",
                paint_code("`ota clean`"),
                paint_code("`ota.yaml`")
            ),
            format!(
                "{} is an org policy pack, not a repo contract",
                paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
            ),
        ];
        return finalize_debug(
            match format {
                OutputFormat::Text => wrong_repo_contract_target_output(
                    "CLEAN",
                    &resolved_path,
                    "Wrong command target",
                    &why_lines,
                    wrong_target_next_steps_for_repo_command("ota clean", &resolved_path),
                    format,
                ),
                OutputFormat::Json => clean_generic_failure_json_output(
                    &text_path_display,
                    "Wrong command target",
                    why_lines.join(" "),
                ),
            },
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match load_and_validate_target(&resolved_path, single_member) {
            Ok(target) if members.is_empty() => {
                if let Some(workspace) = target.contract.workspace.as_ref() {
                    let mut sections =
                        match clean_execution_report(&target.contract, &target.contract_path) {
                            Ok(report) => vec![report],
                            Err(error) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(render_clean_failure_text(
                                                &text_path_display,
                                                &error,
                                                "Cleanup failed",
                                            ))
                                        }
                                        OutputFormat::Json => CommandOutput::failure(
                                            to_json_value(clean_failure_json_value(
                                                &text_path_display,
                                                &error,
                                                "Cleanup failed",
                                            )),
                                        ),
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                        };

                    for member in &workspace.members {
                        let member_target =
                            match load_and_validate_target(&resolved_path, Some(member.as_str())) {
                                Ok(target) => target,
                                Err(ContractProblem::Validation(errors)) => {
                                    let error_lines = errors
                                        .errors()
                                        .iter()
                                        .map(ToString::to_string)
                                        .collect::<Vec<_>>();
                                    return finalize_debug(
                                        match format {
                                            OutputFormat::Text => invalid_repo_contract_output(
                                                "CLEAN",
                                                &resolved_path,
                                                &error_lines,
                                                vec![
                                                    format!(
                                                        "repair {}",
                                                        paint_code(&format!(
                                                            "`{}`",
                                                            compact_contract_path(&resolved_path)
                                                        ))
                                                    ),
                                                    format!(
                                                        "rerun {}",
                                                        paint_code(&format!(
                                                            "`{}`",
                                                            command_for_contract(
                                                                "ota validate",
                                                                &resolved_path
                                                            )
                                                        ))
                                                    ),
                                                    format!(
                                                        "rerun {}",
                                                        paint_code(&format!(
                                                            "`{}`",
                                                            command_for_contract(
                                                                "ota clean",
                                                                &resolved_path
                                                            )
                                                        ))
                                                    ),
                                                ],
                                                format,
                                            ),
                                            OutputFormat::Json => {
                                                clean_invalid_contract_json_output(
                                                    &display_contract_target(
                                                        &compact_path_display,
                                                        Some(member.as_str()),
                                                    ),
                                                    &error_lines,
                                                )
                                            }
                                        },
                                        debug,
                                        debug_lines,
                                    );
                                }
                                Err(ContractProblem::Load(error)) => {
                                    return finalize_debug(
                                        match format {
                                            OutputFormat::Text => CommandOutput::failure(
                                                clean_repo_contract_load_text(
                                                    "CLEAN",
                                                    &resolved_path,
                                                    &error.to_string(),
                                                    &[
                                                        format!(
                                                            "inspect {}",
                                                            paint_code(&format!(
                                                                "`{}`",
                                                                compact_contract_path(
                                                                    &resolved_path
                                                                )
                                                            ))
                                                        ),
                                                        format!(
                                                            "rerun {}",
                                                            paint_code(&format!(
                                                                "`{}`",
                                                                command_for_contract(
                                                                    "ota validate",
                                                                    &resolved_path
                                                                )
                                                            ))
                                                        ),
                                                        format!(
                                                            "rerun {}",
                                                            paint_code(&format!(
                                                                "`{}`",
                                                                command_for_contract(
                                                                    "ota clean",
                                                                    &resolved_path
                                                                )
                                                            ))
                                                        ),
                                                    ],
                                                ),
                                            ),
                                            OutputFormat::Json => {
                                                clean_generic_failure_json_output(
                                                    &display_contract_target(
                                                        &compact_path_display,
                                                        Some(member.as_str()),
                                                    ),
                                                    "Cleanup failed",
                                                    error.to_string(),
                                                )
                                            }
                                        },
                                        debug,
                                        debug_lines,
                                    );
                                }
                            };
                        match clean_execution_report(
                            &member_target.contract,
                            &member_target.contract_path,
                        ) {
                            Ok(report) => sections.push(report),
                            Err(error) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(render_clean_failure_text(
                                                &display_contract_target(
                                                    &compact_path_display,
                                                    Some(member.as_str()),
                                                ),
                                                &error,
                                                "Cleanup failed",
                                            ))
                                        }
                                        OutputFormat::Json => CommandOutput::failure(
                                            to_json_value(clean_failure_json_value(
                                                &display_contract_target(
                                                    &compact_path_display,
                                                    Some(member.as_str()),
                                                ),
                                                &error,
                                                "Cleanup failed",
                                            )),
                                        ),
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                        }
                    }

                    match format {
                        OutputFormat::Text => {
                            let mut rendered =
                                vec![render_clean_text(&text_path_display, &sections[0])];
                            for (index, member) in workspace.members.iter().enumerate() {
                                let report = &sections[index + 1];
                                rendered.push(render_clean_text(
                                    &display_contract_target(
                                        &compact_path_display,
                                        Some(member.as_str()),
                                    ),
                                    report,
                                ));
                            }
                            CommandOutput::success(rendered.join("\n\n"))
                        }
                        OutputFormat::Json => {
                            let root_report = &sections[0];
                            let members_json = workspace
                                .members
                                .iter()
                                .enumerate()
                                .map(|(index, member)| {
                                    let member_path = display_contract_target(
                                        &compact_path_display,
                                        Some(member.as_str()),
                                    );
                                    json!({
                                        "member": member,
                                        "report": clean_report_json_value(&member_path, &sections[index + 1])
                                    })
                                })
                                .collect::<Vec<_>>();
                            CommandOutput::success(to_json_value(json!({
                                "ok": true,
                                "path": text_path_display,
                                "workspace": {
                                    "root": clean_report_json_value(&text_path_display, root_report),
                                    "members": members_json
                                }
                            })))
                        }
                    }
                } else {
                    match clean_execution_report(&target.contract, &target.contract_path) {
                        Ok(report) => match format {
                            OutputFormat::Text => CommandOutput::success(render_clean_text(
                                &text_path_display,
                                &report,
                            )),
                            OutputFormat::Json => CommandOutput::success(to_json_value(
                                clean_report_json_value(&text_path_display, &report),
                            )),
                        },
                        Err(error) => match format {
                            OutputFormat::Text => {
                                CommandOutput::failure(render_clean_failure_text(
                                    &text_path_display,
                                    &error,
                                    "Cleanup failed",
                                ))
                            }
                            OutputFormat::Json => {
                                CommandOutput::failure(to_json_value(clean_failure_json_value(
                                    &text_path_display,
                                    &error,
                                    "Cleanup failed",
                                )))
                            }
                        },
                    }
                }
            }
            Ok(_) => {
                let mut sections = Vec::new();
                for member in members {
                    let target =
                        match load_and_validate_target(&resolved_path, Some(member.as_str())) {
                            Ok(target) => target,
                            Err(ContractProblem::Validation(errors)) => {
                                let error_lines = errors
                                    .errors()
                                    .iter()
                                    .map(ToString::to_string)
                                    .collect::<Vec<_>>();
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => invalid_repo_contract_output(
                                            "CLEAN",
                                            &resolved_path,
                                            &error_lines,
                                            vec![
                                                format!(
                                                    "repair {}",
                                                    paint_code(&format!(
                                                        "`{}`",
                                                        compact_contract_path(&resolved_path)
                                                    ))
                                                ),
                                                format!(
                                                    "rerun {}",
                                                    paint_code(&format!(
                                                        "`{}`",
                                                        command_for_contract(
                                                            "ota validate",
                                                            &resolved_path
                                                        )
                                                    ))
                                                ),
                                                format!(
                                                    "rerun {}",
                                                    paint_code(&format!(
                                                        "`{}`",
                                                        command_for_contract(
                                                            "ota clean",
                                                            &resolved_path
                                                        )
                                                    ))
                                                ),
                                            ],
                                            format,
                                        ),
                                        OutputFormat::Json => clean_invalid_contract_json_output(
                                            &display_contract_target(
                                                &compact_path_display,
                                                Some(member.as_str()),
                                            ),
                                            &error_lines,
                                        ),
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                            Err(ContractProblem::Load(error)) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(clean_repo_contract_load_text(
                                                "CLEAN",
                                                &resolved_path,
                                                &error.to_string(),
                                                &[
                                                    format!(
                                                        "inspect {}",
                                                        paint_code(&format!(
                                                            "`{}`",
                                                            compact_contract_path(&resolved_path)
                                                        ))
                                                    ),
                                                    format!(
                                                        "rerun {}",
                                                        paint_code(&format!(
                                                            "`{}`",
                                                            command_for_contract(
                                                                "ota validate",
                                                                &resolved_path
                                                            )
                                                        ))
                                                    ),
                                                    format!(
                                                        "rerun {}",
                                                        paint_code(&format!(
                                                            "`{}`",
                                                            command_for_contract(
                                                                "ota clean",
                                                                &resolved_path
                                                            )
                                                        ))
                                                    ),
                                                ],
                                            ))
                                        }
                                        OutputFormat::Json => clean_generic_failure_json_output(
                                            &display_contract_target(
                                                &compact_path_display,
                                                Some(member.as_str()),
                                            ),
                                            "Cleanup failed",
                                            error.to_string(),
                                        ),
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                        };
                    match clean_execution_report(&target.contract, &target.contract_path) {
                        Ok(report) => sections.push((member.clone(), report)),
                        Err(error) => {
                            return finalize_debug(
                                match format {
                                    OutputFormat::Text => {
                                        CommandOutput::failure(render_clean_failure_text(
                                            &display_contract_target(
                                                &compact_path_display,
                                                Some(member.as_str()),
                                            ),
                                            &error,
                                            "Cleanup failed",
                                        ))
                                    }
                                    OutputFormat::Json => CommandOutput::failure(to_json_value(
                                        clean_failure_json_value(
                                            &display_contract_target(
                                                &compact_path_display,
                                                Some(member.as_str()),
                                            ),
                                            &error,
                                            "Cleanup failed",
                                        ),
                                    )),
                                },
                                debug,
                                debug_lines,
                            );
                        }
                    }
                }

                match format {
                    OutputFormat::Text => CommandOutput::success(
                        sections
                            .iter()
                            .map(|(member, report)| {
                                render_clean_text(
                                    &display_contract_target(
                                        &compact_path_display,
                                        Some(member.as_str()),
                                    ),
                                    report,
                                )
                            })
                            .collect::<Vec<_>>()
                            .join("\n\n"),
                    ),
                    OutputFormat::Json => CommandOutput::success(to_json_value(json!({
                        "ok": true,
                        "path": text_path_display,
                        "members": sections.iter().map(|(member, report)| {
                            let member_path = display_contract_target(
                                &compact_path_display,
                                Some(member.as_str()),
                            );
                            json!({
                                "member": member,
                                "report": clean_report_json_value(&member_path, report)
                            })
                        }).collect::<Vec<_>>()
                    }))),
                }
            }
            Err(ContractProblem::Validation(errors)) => {
                let error_lines = errors
                    .errors()
                    .iter()
                    .map(ToString::to_string)
                    .collect::<Vec<_>>();
                match format {
                    OutputFormat::Text => invalid_repo_contract_output(
                        "CLEAN",
                        &resolved_path,
                        &error_lines,
                        vec![
                            format!(
                                "repair {}",
                                paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                            ),
                            format!(
                                "rerun {}",
                                paint_code(&format!(
                                    "`{}`",
                                    command_for_repo_contract_target(
                                        "ota validate",
                                        &resolved_path
                                    )
                                ))
                            ),
                            format!(
                                "rerun {}",
                                paint_code(&format!(
                                    "`{}`",
                                    command_for_repo_contract_target("ota clean", &resolved_path)
                                ))
                            ),
                        ],
                        format,
                    ),
                    OutputFormat::Json => {
                        clean_invalid_contract_json_output(&text_path_display, &error_lines)
                    }
                }
            }
            Err(ContractProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(clean_repo_contract_load_text(
                    "CLEAN",
                    &resolved_path,
                    &error.to_string(),
                    &[
                        format!(
                            "inspect {}",
                            paint_code(&format!("`{}`", compact_contract_path(&resolved_path)))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota validate", &resolved_path)
                            ))
                        ),
                        format!(
                            "rerun {}",
                            paint_code(&format!(
                                "`{}`",
                                command_for_repo_contract_target("ota clean", &resolved_path)
                            ))
                        ),
                    ],
                )),
                OutputFormat::Json => clean_generic_failure_json_output(
                    &text_path_display,
                    "Cleanup failed",
                    error.to_string(),
                ),
            },
        },
        debug,
        debug_lines,
    )
}

fn render_clean_text(path: &str, report: &CleanExecutionReport) -> String {
    if report.total_removed() == 0 && report.total_skipped_ambiguous() == 0 {
        return format!("No cleanup needed for {path}");
    }

    let header = if report.total_removed() > 0 {
        format!("Cleaned {path}")
    } else {
        format!("Reviewed cleanup for {path}")
    };
    let mut lines = vec![header];
    if report.stopped_host_services > 0 {
        lines.push(format!(
            "  {} stopped host-managed services: {}",
            summary_bullet(),
            report.stopped_host_services
        ));
    }
    if report.removed_current_persistent_containers > 0 {
        lines.push(format!(
            "  {} removed current persistent containers: {}",
            summary_bullet(),
            report.removed_current_persistent_containers
        ));
    }
    if report.removed_drift_persistent_containers > 0 {
        lines.push(format!(
            "  {} removed drifted persistent containers: {}",
            summary_bullet(),
            report.removed_drift_persistent_containers
        ));
    }
    if report.removed_drift_attached_containers > 0 {
        lines.push(format!(
            "  {} removed drifted volume-holding containers: {}",
            summary_bullet(),
            report.removed_drift_attached_containers
        ));
    }
    if report.removed_current_dependency_isolation_volumes > 0 {
        lines.push(format!(
            "  {} removed current dependency-isolation volumes: {}",
            summary_bullet(),
            report.removed_current_dependency_isolation_volumes
        ));
    }
    if report.removed_drift_dependency_isolation_volumes > 0 {
        lines.push(format!(
            "  {} removed drifted dependency-isolation volumes: {}",
            summary_bullet(),
            report.removed_drift_dependency_isolation_volumes
        ));
    }
    if report.skipped_ambiguous_persistent_containers > 0
        || report.skipped_ambiguous_dependency_isolation_volumes > 0
    {
        lines.push(format!(
            "  {} skipped ownership-ambiguous state (not removed): {} containers, {} volumes",
            summary_bullet(),
            report.skipped_ambiguous_persistent_containers,
            report.skipped_ambiguous_dependency_isolation_volumes
        ));
    }
    if !report.queried_engines.is_empty() {
        lines.push(format!(
            "  {} queried engines: {}",
            summary_bullet(),
            report.queried_engines.join(", ")
        ));
    }
    lines.join("\n")
}

fn render_clean_failure_text(path: &str, error: &CleanExecutionError, summary: &str) -> String {
    match error {
        CleanExecutionError::Cleanup(cleanup) => {
            render_structured_clean_failure_text(path, cleanup)
        }
        CleanExecutionError::Other(RunError::WorkflowInstanceCleanupConflict {
            workflow,
            instance,
            dependents,
            compose_projects,
        }) => render_structured_clean_instance_topology_conflict_text(
            path,
            workflow,
            instance,
            dependents,
            compose_projects,
        ),
        CleanExecutionError::Other(RunError::RepoExecutionConflict {
            path: registry_path,
            reasons,
            owners,
            ..
        }) => render_structured_clean_execution_conflict_text(path, registry_path, reasons, owners),
        CleanExecutionError::Other(error) => {
            command_message_failure_text("CLEAN", path, summary, &error.to_string(), &[])
        }
    }
}

fn render_structured_clean_instance_topology_conflict_text(
    path: &str,
    workflow: &str,
    instance: &str,
    dependents: &[String],
    compose_projects: &[String],
) -> String {
    let mut details = vec![
        format!("workflow: `{workflow}`"),
        format!("instance: `{instance}`"),
    ];
    if !dependents.is_empty() {
        details.push(format!(
            "dependent instances: {}",
            dependents
                .iter()
                .map(|dependent| format!("`{dependent}`"))
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    if !compose_projects.is_empty() {
        details.push(format!(
            "compose projects: {}",
            compose_projects
                .iter()
                .map(|project| format!("`{project}`"))
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    structured_error_text_with_details(
        "CLEAN",
        path,
        "Workflow instance topology conflict",
        &[format!(
            "`ota clean` cannot remove prerequisite instance `{workflow}@{instance}` while dependent workflow instances are still present."
        )],
        &[
            String::from("clean or stop the dependent instance(s) first"),
            String::from("then rerun `ota clean` for the prerequisite instance"),
        ],
        &details,
    )
}

fn render_structured_clean_failure_text(path: &str, failure: &CleanExecutionFailure) -> String {
    let (summary, why) = clean_failure_summary_and_why(failure);

    let details = summarize_clean_engine_details(failure.details.as_str());
    structured_error_text_with_details(
        "CLEAN",
        path,
        summary,
        &[why],
        &clean_failure_next_steps(failure),
        &[details],
    )
}

fn render_structured_clean_execution_conflict_text(
    path: &str,
    registry_path: &str,
    reasons: &[RepoExecutionConflictReason],
    owners: &[RepoExecutionLockOwner],
) -> String {
    let details = repo_execution_conflict_detail_lines(reasons, owners);
    let mut output = structured_error_text(
        "CLEAN",
        path,
        "Active execution conflict",
        &[format!(
            "`ota clean` cannot remove repo state while active executions recorded in `{registry_path}` still own it."
        )],
        &[
            String::from("wait for the active execution to finish before rerunning `ota clean`"),
            String::from(
                "or stop the conflicting execution first if you intentionally want cleanup now",
            ),
        ],
    );
    if !details.is_empty() {
        output.push('\n');
        append_error_detail_section(&mut output, "Conflicting execution:", &details, None);
    }
    output
}

fn clean_failure_summary_and_why(failure: &CleanExecutionFailure) -> (&'static str, String) {
    let engine_label = display_container_engine_name(failure.engine.as_str());
    let summary = match failure.reason {
        CleanExecutionFailureReason::EngineUnavailable => "Container engine unavailable",
        CleanExecutionFailureReason::Other => "Cleanup failed",
    };
    let why = match (
        &failure.resource_kind,
        failure.resource_name.as_deref(),
        &failure.reason,
    ) {
        (CleanExecutionResourceKind::HostService, Some(service_name), _) => format!(
            "`ota clean` could not {} host-managed service `{service_name}` before cleaning repo state.",
            failure.action
        ),
        (
            CleanExecutionResourceKind::PersistentContainer,
            Some(state_name),
            CleanExecutionFailureReason::EngineUnavailable,
        ) => format!(
            "`ota clean` needs {engine_label} to remove persistent repo state for `{state_name}`, but {engine_label} is not reachable."
        ),
        (
            CleanExecutionResourceKind::DependencyIsolationVolume,
            Some(state_name),
            CleanExecutionFailureReason::EngineUnavailable,
        ) => format!(
            "`ota clean` needs {engine_label} to remove dependency-isolation repo state for `{state_name}`, but {engine_label} is not reachable."
        ),
        (
            CleanExecutionResourceKind::StaleContainers,
            _,
            CleanExecutionFailureReason::EngineUnavailable,
        ) => format!(
            "`ota clean` needs {engine_label} to inspect stale ota-managed container state, but {engine_label} is not reachable."
        ),
        (CleanExecutionResourceKind::PersistentContainer, Some(state_name), _) => format!(
            "`ota clean` could not {} persistent repo state `{state_name}` using {engine_label}.",
            failure.action
        ),
        (CleanExecutionResourceKind::DependencyIsolationVolume, Some(state_name), _) => format!(
            "`ota clean` could not {} dependency-isolation repo state `{state_name}` using {engine_label}.",
            failure.action
        ),
        (CleanExecutionResourceKind::StaleContainers, _, _) => format!(
            "`ota clean` could not inspect stale ota-managed container state using {engine_label}."
        ),
        _ => format!(
            "`ota clean` could not {} repo execution state using {engine_label}.",
            failure.action
        ),
    };
    (summary, why)
}

fn summarize_clean_engine_details(details: &str) -> String {
    details
        .lines()
        .rev()
        .map(str::trim)
        .find(|line| !line.is_empty())
        .map(|line| line.strip_prefix("Error: ").unwrap_or(line).to_string())
        .unwrap_or_else(|| details.trim().to_string())
}

fn clean_failure_next_steps(failure: &CleanExecutionFailure) -> Vec<String> {
    if matches!(
        failure.reason,
        CleanExecutionFailureReason::EngineUnavailable
    ) {
        return match failure.engine.as_str() {
            "podman" => vec![
                String::from("start Podman and rerun `ota clean`"),
                String::from("run `podman system connection list`"),
                String::from("if needed, run `podman machine init` and `podman machine start`"),
            ],
            "docker" => vec![
                String::from("start Docker and rerun `ota clean`"),
                String::from("run `docker info`"),
                String::from("if needed, start Docker Desktop or the Docker daemon"),
            ],
            _ => vec![
                format!("start `{}` and rerun `ota clean`", failure.engine),
                format!("verify `{}` is reachable from this shell", failure.engine),
            ],
        };
    }

    let state_kind = match failure.resource_kind {
        CleanExecutionResourceKind::HostService => "host-managed service state",
        CleanExecutionResourceKind::PersistentContainer => "persistent container state",
        CleanExecutionResourceKind::DependencyIsolationVolume => {
            "dependency-isolation volume state"
        }
        CleanExecutionResourceKind::StaleContainers => "stale ota-managed container state",
    };
    if matches!(
        failure.resource_kind,
        CleanExecutionResourceKind::HostService
    ) {
        let service_name = failure
            .resource_name
            .as_deref()
            .unwrap_or("selected host-managed service");
        return vec![
            format!("inspect the stop command for `{service_name}` and rerun `ota clean`"),
            String::from("verify the service can be stopped from this shell without Ota"),
        ];
    }
    vec![
        format!("repair the selected {state_kind} and rerun `ota clean`"),
        format!(
            "verify `{}` is healthy before retrying cleanup",
            failure.engine
        ),
    ]
}

fn clean_resource_kind_json_label(kind: &CleanExecutionResourceKind) -> &'static str {
    match kind {
        CleanExecutionResourceKind::HostService => "host_service",
        CleanExecutionResourceKind::PersistentContainer => "persistent_container",
        CleanExecutionResourceKind::DependencyIsolationVolume => "dependency_isolation_volume",
        CleanExecutionResourceKind::StaleContainers => "stale_containers",
    }
}

fn clean_failure_reason_json_label(reason: &CleanExecutionFailureReason) -> &'static str {
    match reason {
        CleanExecutionFailureReason::EngineUnavailable => "engine_unavailable",
        CleanExecutionFailureReason::Other => "other",
    }
}

fn clean_execution_conflict_json_value(
    path: &str,
    registry_path: &str,
    reasons: &[RepoExecutionConflictReason],
    owners: &[RepoExecutionLockOwner],
) -> JsonValue {
    json!({
        "ok": false,
        "path": path,
        "summary": "Active execution conflict",
        "error": format!(
            "ota clean cannot proceed while active executions recorded in `{registry_path}` still own repo cleanup state"
        ),
        "why": format!(
            "`ota clean` cannot remove repo state while active executions recorded in `{registry_path}` still own it."
        ),
        "next": [
            "wait for the active execution to finish before rerunning `ota clean`",
            "or stop the conflicting execution first if you intentionally want cleanup now"
        ],
        "reason": "active_execution_conflict",
        "registry_path": registry_path,
        "reasons": reasons
            .iter()
            .map(|reason| repo_execution_conflict_reason_label(*reason))
            .collect::<Vec<_>>(),
        "active_execution_count": owners.len(),
        "owners": owners.iter().map(|owner| json!({
            "task": owner.task,
            "requested_mode": owner.requested_mode,
            "execution_mode": owner.execution_mode,
            "lifecycle": owner.lifecycle,
            "host_services": owner.host_services,
            "compose_projects": owner.compose_projects,
            "persistent_backend_families": owner.persistent_backend_families,
            "env_materialization_paths": owner.env_materialization_paths,
            "write_paths": owner.write_paths,
            "write_owners": owner.write_owners,
            "runtime_owners": owner.runtime_owners,
            "service_task": owner.service_task,
            "pid": owner.pid,
            "started_at": owner.started_at
        })).collect::<Vec<_>>()
    })
}

fn clean_failure_detail_json_value(error: &CleanExecutionError) -> Option<JsonValue> {
    match error {
        CleanExecutionError::Cleanup(failure) => {
            let (derived_summary, why) = clean_failure_summary_and_why(failure);
            let next_steps = clean_failure_next_steps(failure);
            Some(json!({
                "summary": derived_summary,
                "error": failure.to_string(),
                "why": why,
                "next": next_steps,
                "reason": clean_failure_reason_json_label(&failure.reason),
                "engine": failure.engine,
                "action": failure.action,
                "resource_kind": clean_resource_kind_json_label(&failure.resource_kind),
                "resource_name": failure.resource_name,
                "details": summarize_clean_engine_details(failure.details.as_str())
            }))
        }
        CleanExecutionError::Other(RunError::RepoExecutionConflict {
            path: registry_path,
            reasons,
            owners,
            ..
        }) => Some(
            clean_execution_conflict_json_value("", registry_path, reasons, owners)
                .as_object()
                .map(|value| {
                    let mut detail = value.clone();
                    detail.remove("ok");
                    detail.remove("path");
                    JsonValue::Object(detail)
                })
                .expect("clean execution conflict json should be an object"),
        ),
        CleanExecutionError::Other(RunError::WorkflowInstanceCleanupConflict {
            workflow,
            instance,
            dependents,
            compose_projects,
        }) => Some(json!({
            "summary": "Workflow instance topology conflict",
            "error": format!(
                "workflow `{workflow}` instance `{instance}` cannot be cleaned while dependent instances are still present"
            ),
            "why": format!(
                "`ota clean` cannot remove prerequisite instance `{workflow}@{instance}` while dependent workflow instances are still present."
            ),
            "next": [
                "clean or stop the dependent instance(s) first",
                "then rerun `ota clean` for the prerequisite instance"
            ],
            "reason": "workflow_instance_topology_conflict",
            "workflow": workflow,
            "instance": instance,
            "dependents": dependents,
            "compose_projects": compose_projects
        })),
        CleanExecutionError::Other(_) => None,
    }
}

fn clean_report_json_value(path: &str, report: &CleanExecutionReport) -> JsonValue {
    json!({
        "ok": true,
        "path": path,
        "summary": {
            "stopped_host_services": report.stopped_host_services,
            "removed_current_persistent_containers": report.removed_current_persistent_containers,
            "removed_drift_persistent_containers": report.removed_drift_persistent_containers,
            "removed_drift_attached_containers": report.removed_drift_attached_containers,
            "removed_current_dependency_isolation_volumes": report.removed_current_dependency_isolation_volumes,
            "removed_drift_dependency_isolation_volumes": report.removed_drift_dependency_isolation_volumes,
            "skipped_ambiguous_persistent_containers": report.skipped_ambiguous_persistent_containers,
            "skipped_ambiguous_dependency_isolation_volumes": report.skipped_ambiguous_dependency_isolation_volumes,
            "total_removed": report.total_removed(),
            "total_skipped_ambiguous": report.total_skipped_ambiguous()
        },
        "host_services": report.host_services,
        "queried_engines": report.queried_engines
    })
}

fn clean_failure_json_value(path: &str, error: &CleanExecutionError, summary: &str) -> JsonValue {
    if let Some(JsonValue::Object(mut detail)) = clean_failure_detail_json_value(error) {
        detail.insert(String::from("ok"), json!(false));
        detail.insert(String::from("path"), json!(path));
        return JsonValue::Object(detail);
    }
    match error {
        CleanExecutionError::Other(error) => json!({
            "ok": false,
            "path": path,
            "summary": summary,
            "error": error.to_string()
        }),
        CleanExecutionError::Cleanup(_) => {
            unreachable!("structured cleanup failures should be handled above")
        }
    }
}

fn clean_generic_failure_json_output(
    path: &str,
    summary: &str,
    error: impl Into<String>,
) -> CommandOutput {
    CommandOutput::failure(to_json_value(json!({
        "ok": false,
        "path": path,
        "summary": summary,
        "error": error.into(),
    })))
}

fn clean_invalid_contract_json_output(path: &str, errors: &[String]) -> CommandOutput {
    clean_generic_failure_json_output(
        path,
        "Invalid contract",
        if errors.len() == 1 {
            errors[0].clone()
        } else {
            errors.join("; ")
        },
    )
}

fn display_container_engine_name(engine: &str) -> String {
    match engine {
        "podman" => String::from("Podman"),
        "docker" => String::from("Docker"),
        _ => {
            let mut chars = engine.chars();
            match chars.next() {
                Some(first) => {
                    let mut out = first.to_uppercase().collect::<String>();
                    out.push_str(chars.as_str());
                    out
                }
                None => String::from("Container engine"),
            }
        }
    }
}

fn render_stale_clean_text(
    containers: &[crate::runner::StaleContainerCleanupTarget],
    dry_run: bool,
) -> String {
    if containers.is_empty() {
        return String::from("No stale ota-managed containers to clean");
    }

    let mut stdout = if dry_run {
        format!(
            "Dry run stale ota-managed containers ({})",
            containers.len()
        )
    } else {
        format!(
            "Cleaned stale ota-managed containers ({})",
            containers.len()
        )
    };

    for container in containers {
        stdout.push_str("\n  ");
        stdout.push_str(&summary_bullet());
        stdout.push(' ');
        stdout.push_str(&paint_code(&container.engine));
        stdout.push(' ');
        stdout.push_str(&paint_code(&container.name));
    }

    stdout
}

pub fn detect(
    path: Option<&Path>,
    write: bool,
    dry_run: bool,
    contract: bool,
    merge: bool,
    apply: &[String],
    apply_all: bool,
    rewrite: bool,
    yes: bool,
    candidate_out: Option<&Path>,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    if merge || !apply.is_empty() || apply_all || rewrite || yes {
        let removed_flags = [
            merge.then_some("--merge"),
            (!apply.is_empty()).then_some("--apply"),
            apply_all.then_some("--apply-all"),
            rewrite.then_some("--rewrite"),
            yes.then_some("--yes"),
        ]
        .into_iter()
        .flatten()
        .collect::<Vec<_>>();
        let replacement = "ota detect --candidate-out .ota/candidates/detect.json";
        let error = format!(
            "repo-level detect mutation flags {} were removed; detection is read-only and contract mutation requires a reviewed candidate",
            removed_flags.join(", ")
        );
        return match format {
            OutputFormat::Text => CommandOutput::failure_with_code(
                command_message_failure_text(
                    "DETECT",
                    "legacy mutation flags",
                    "Legacy detect mutation was removed",
                    &format!("detect_legacy_mutation_removed: {error}"),
                    &[
                        format!("create a review artifact with `{replacement}`"),
                        String::from(
                            "apply additions with `ota contract apply-candidate <candidate> --write`; rewrite and removal have no replacement carrier",
                        ),
                    ],
                ),
                2,
            ),
            OutputFormat::Json => CommandOutput::failure_with_code(
                to_json_value(json!({
                    "ok": false,
                    "path": path.map(|path| path.display().to_string()).unwrap_or_else(|| String::from(".")),
                    "written": false,
                    "code": "detect_legacy_mutation_removed",
                    "removed_flags": removed_flags,
                    "replacement": replacement,
                    "error": error
                })),
                2,
            ),
        };
    }
    let root = resolve_repo_path(path);
    let contract_path = root.join(DEFAULT_CONTRACT_FILE);
    let path_display = contract_path.display().to_string();
    let debug_lines = vec![
        String::from("DEBUG command=detect"),
        format!("DEBUG repo_root={}", root.display()),
        format!("DEBUG contract_path={path_display}"),
        format!("DEBUG write={write}"),
        format!("DEBUG dry_run={dry_run}"),
        format!("DEBUG contract={contract}"),
        format!("DEBUG merge={merge}"),
        format!("DEBUG apply={}", apply.join(",")),
        format!("DEBUG rewrite={rewrite}"),
        format!("DEBUG yes={yes}"),
        format!(
            "DEBUG candidate_out={}",
            candidate_out
                .map(|candidate_out| candidate_out.display().to_string())
                .unwrap_or_else(|| String::from("none"))
        ),
    ];
    let dry_run = if candidate_out.is_some() {
        false
    } else if contract {
        true
    } else {
        dry_run || !write
    };
    finalize_debug(
        match detect_repo(&root) {
            Ok(report) if let Some(candidate_out) = candidate_out => {
                write_detect_candidate_artifact(report, candidate_out, format)
            }
            Ok(report) if dry_run => {
                let compact_root_display = compact_repo_path(&report.root);
                if contract {
                    return match format {
                        OutputFormat::Text => {
                            render_detect_contract_preview(&report, &contract_path)
                        }
                        OutputFormat::Json => CommandOutput::failure(String::from(
                            "`ota detect --contract` is only supported with text output",
                        )),
                    };
                }
                let comparison =
                    compare_detected_contract(&contract_path, &report, DetectRemovalScope::Drift);
                let selected_fields = apply.iter().cloned().collect::<BTreeSet<_>>();
                let comparison =
                    selected_detect_comparison(comparison.as_ref(), &report, &selected_fields);
                let mut preview_contract = report.contract.clone();
                apply_detected_starter_contract_defaults(&mut preview_contract, &report);
                let agent_boundary = starter_agent_boundary_outcome_from_detect_report(&report);
                let toolchain_opportunities = detect_toolchain_opportunities(&report);
                let yaml = serde_yaml::to_string(&preview_contract)
                    .expect("serializing detected contract should not fail");
                match format {
                    OutputFormat::Text => {
                        let mut stdout =
                            format_command_header("DETECT PREVIEW", &compact_root_display);
                        stdout.push_str(&format!("\n\n{}", format_mode_line("dry-run (no write)")));
                        let comparison_mode = DetectComparisonMode::Preview;
                        let comparison_first = comparison
                            .as_ref()
                            .is_some_and(|comparison| comparison.existing_contract);
                        if comparison_first {
                            render_detect_comparison_section(
                                &mut stdout,
                                comparison.as_ref(),
                                comparison_mode,
                            );
                        }
                        stdout.push_str(&format!("\n\n{}\n", paint_section_title("Contract")));
                        stdout.push_str(&stylize_yaml_preview(yaml.trim_end()));
                        render_inference_section(
                            &mut stdout,
                            "Annotations",
                            report.inferences.iter(),
                        );
                        render_toolchain_opportunity_section(&mut stdout, &toolchain_opportunities);
                        if !comparison_first {
                            render_detect_comparison_section(
                                &mut stdout,
                                comparison.as_ref(),
                                comparison_mode,
                            );
                        }
                        append_agent_boundary_outcome_section(
                            &mut stdout,
                            &preview_contract,
                            &agent_boundary,
                            &report.root,
                            AgentBoundaryRenderContext::DetectPreview,
                        );
                        let next_lines = detect_preview_next_steps(
                            comparison_mode,
                            &compact_root_display,
                            comparison.as_ref(),
                        );
                        append_detect_preview_next(&mut stdout, comparison.as_ref(), &next_lines);
                        CommandOutput::success(stdout)
                    }
                    OutputFormat::Json => CommandOutput::success(to_json(&DetectSuccess {
                        ok: true,
                        path: &path_display,
                        written: false,
                        config: detect_json_config_value(&preview_contract),
                        inferred: &report.inferences,
                        toolchain_opportunities: toolchain_opportunities
                            .iter()
                            .map(|opportunity| opportunity.advisory.clone())
                            .collect(),
                        comparison: comparison.as_ref(),
                        candidate_path: None,
                        candidate_published: None,
                        candidate_publication: None,
                        candidate: None,
                        write_candidate: None,
                    })),
                }
            }
            Ok(report) => write_detected_contract(report, format),
            Err(error) => {
                let error = error.to_string();
                match format {
                    OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                        "DETECT",
                        &compact_repo_path(&root),
                        "Repo could not be detected",
                        &error,
                        &[format!(
                            "inspect repo signals, then rerun `{}`",
                            command_for_repo("ota detect --dry-run", &root)
                        )],
                    )),
                    OutputFormat::Json => CommandOutput::failure(to_json(&DetectFailure {
                        ok: false,
                        path: &path_display,
                        written: false,
                        error: &error,
                        next: None,
                    })),
                }
            }
        },
        debug,
        debug_lines,
    )
}

fn write_detect_candidate_artifact(
    report: DetectReport,
    requested_path: &Path,
    format: OutputFormat,
) -> CommandOutput {
    let contract_path = report.root.join(DEFAULT_CONTRACT_FILE);
    let contract_path_display = contract_path.display().to_string();
    let requested_path_display = requested_path.display().to_string();
    let candidate_capture = match report.source_bound_candidate() {
        Ok(candidate) => candidate,
        Err(error) => {
            let error = format!("failed to construct source-bound candidate: {error}");
            return match format {
                OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                    "DETECT CANDIDATE",
                    &compact_repo_path(&report.root),
                    "Candidate could not be constructed",
                    &error,
                    &[],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&DetectFailure {
                    ok: false,
                    path: &contract_path_display,
                    written: false,
                    error: &error,
                    next: None,
                })),
            };
        }
    };
    let candidate = candidate_capture.candidate;
    let candidate_report = DetectReport {
        root: report.root.clone(),
        contract: candidate_capture.contract,
        inferences: candidate_capture.inferences,
    };
    let output = match write_candidate_create_new(&report.root, requested_path, &candidate) {
        Ok(output) => output,
        Err(error) => {
            let next = "choose a new root-relative path below an existing non-evidence directory";
            let message = error.message();
            let candidate_published = error.candidate_published();
            let candidate_publication = error.posture();
            return match format {
                OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                    "DETECT CANDIDATE",
                    &compact_repo_path(&report.root),
                    if candidate_published {
                        "Candidate publication durability is uncertain"
                    } else {
                        "Candidate was not published"
                    },
                    message,
                    &[next.to_string()],
                )),
                OutputFormat::Json => {
                    CommandOutput::failure(to_json(&DetectCandidatePublicationFailure {
                        ok: false,
                        path: &contract_path_display,
                        written: false,
                        candidate_path: &requested_path_display,
                        candidate_published,
                        candidate_publication,
                        error: message,
                        next,
                    }))
                }
            };
        }
    };
    let output_display = compact_path(&output, ".");
    match format {
        OutputFormat::Text => {
            let mut stdout = format!(
                "{}\n\n{}\n{}\n{}",
                format_command_header("DETECT CANDIDATE", &compact_repo_path(&report.root)),
                format_result_line(&format!("wrote {}", paint_code(&output_display))),
                format_result_line(&format!("identity {}", paint_code(&candidate.identity))),
                "Review this artifact before any future candidate-application command. It does not modify ota.yaml."
            );
            let dispositions =
                candidate
                    .changes
                    .iter()
                    .fold(BTreeMap::new(), |mut counts, change| {
                        *counts
                            .entry(format!("{:?}", change.disposition).to_lowercase())
                            .or_insert(0_usize) += 1;
                        counts
                    });
            if !dispositions.is_empty() {
                stdout.push_str("\n\n");
                stdout.push_str(&paint_section_title("Review summary"));
                for (disposition, count) in dispositions {
                    stdout.push_str(&format!("\n- {count} {disposition}"));
                }
            }
            CommandOutput::success(stdout)
        }
        OutputFormat::Json => {
            let candidate = serde_json::to_value(&candidate)
                .expect("serializing verified candidate should not fail");
            CommandOutput::success(to_json(&DetectSuccess {
                ok: true,
                path: &contract_path_display,
                written: false,
                config: detect_json_config_value(&candidate_report.contract),
                inferred: &candidate_report.inferences,
                toolchain_opportunities: detect_toolchain_opportunities(&candidate_report)
                    .into_iter()
                    .map(|opportunity| opportunity.advisory)
                    .collect(),
                comparison: None,
                candidate_path: Some(&output_display),
                candidate_published: Some(true),
                candidate_publication: Some("durable"),
                candidate: Some(candidate),
                write_candidate: None,
            }))
        }
    }
}

/// Produces one registered, lossless contract-upgrade review artifact without changing ota.yaml.
pub fn upgrade_contract_candidate(
    path: Option<&Path>,
    candidate_out: &Path,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let root = resolve_repo_path(path);
    let root_display = compact_repo_path(&root);
    let candidate_path_display = candidate_out.display().to_string();
    let debug_lines = vec![
        String::from("DEBUG command=contract upgrade"),
        format!("DEBUG repo_root={}", root.display()),
        format!("DEBUG candidate_out={candidate_path_display}"),
    ];
    let failure = |code: &'static str,
                   error: String,
                   next: Option<&str>,
                   candidate_published: bool,
                   candidate_publication: &'static str| {
        let output = match format {
            OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                "CONTRACT UPGRADE",
                &root_display,
                if candidate_published {
                    "Upgrade candidate publication durability is uncertain"
                } else {
                    "Upgrade candidate was not published"
                },
                &format!("{code}: {error}"),
                &next.into_iter().map(str::to_string).collect::<Vec<_>>(),
            )),
            OutputFormat::Json => CommandOutput::failure(to_json(&ContractUpgradeFailure {
                ok: false,
                path: &root_display,
                written: false,
                candidate_path: &candidate_path_display,
                candidate_published,
                candidate_publication,
                code,
                error: &error,
                next,
            })),
        };
        finalize_debug(output, debug, debug_lines.clone())
    };
    let capture = match build_contract_upgrade_candidate(&root) {
        Ok(capture) => capture,
        Err(error) => {
            let code = match error {
                ContractUpgradeError::UnsupportedVersion
                | ContractUpgradeError::NoRegisteredMigration => "upgrade_unsupported",
                ContractUpgradeError::MissingOrUnsafeContract
                | ContractUpgradeError::ContractTooLarge
                | ContractUpgradeError::Read(_)
                | ContractUpgradeError::RawParse(_)
                | ContractUpgradeError::LegacyParse(_)
                | ContractUpgradeError::Candidate(_) => "upgrade_failed",
            };
            return failure(
                code,
                error.to_string(),
                Some("review ota.yaml and select a registered lossless migration"),
                false,
                "not_published",
            );
        }
    };
    let migration_id = capture
        .candidate
        .migration
        .as_ref()
        .expect("upgrade candidate carries migration evidence")
        .id
        .clone();
    if let Err(error) = write_candidate_create_new(&root, candidate_out, &capture.candidate) {
        return failure(
            "upgrade_write_failed",
            error.message().to_string(),
            Some("choose a new in-repository candidate path and retry"),
            error.candidate_published(),
            error.posture(),
        );
    }
    let candidate_json = match serde_json::to_value(&capture.candidate) {
        Ok(value) => value,
        Err(error) => {
            return failure(
                "upgrade_failed",
                error.to_string(),
                None,
                false,
                "not_published",
            );
        }
    };
    let output = match format {
        OutputFormat::Text => CommandOutput::success(format!(
            "{}\n\n{}\n{}\n{}",
            format_command_header("CONTRACT UPGRADE", &root_display),
            format_result_line("lossless upgrade candidate produced"),
            format_result_line(&format!("migration {}", paint_code(&migration_id))),
            format!(
                "Review: {}\nNext: ota contract apply-candidate {} --json",
                paint_code(&candidate_path_display),
                paint_code(&candidate_path_display)
            )
        )),
        OutputFormat::Json => CommandOutput::success(to_json(&ContractUpgradeSuccess {
            ok: true,
            path: &root_display,
            written: false,
            candidate_path: &candidate_path_display,
            candidate_published: true,
            candidate_publication: "durable",
            migration_id: &migration_id,
            candidate: candidate_json,
        })),
    };
    finalize_debug(output, debug, debug_lines)
}

/// Re-derives a reviewed candidate and, only with `--write`, atomically creates a missing ota.yaml.
pub fn apply_contract_candidate(
    path: Option<&Path>,
    candidate_path: &Path,
    write: bool,
    carrier: Option<ContractCandidateUpdateCarrier>,
    require_complete: bool,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let mode = if write { "write" } else { "dry_run" };
    let root = resolve_repo_path(path);
    let candidate_file = if candidate_path.is_absolute() {
        candidate_path.to_path_buf()
    } else {
        root.join(candidate_path)
    };
    let candidate_path_display = candidate_path.display().to_string();
    let debug_lines = vec![
        String::from("DEBUG command=contract apply-candidate"),
        format!("DEBUG repo_root={}", root.display()),
        format!("DEBUG candidate_path={candidate_path_display}"),
        format!("DEBUG write={write}"),
        format!(
            "DEBUG carrier={}",
            match carrier {
                Some(ContractCandidateUpdateCarrier::Git) => "git",
                None => "none",
            }
        ),
        format!("DEBUG require_complete={require_complete}"),
    ];
    let failure = |code: &'static str, error: String, next: Option<&str>| {
        let output = match format {
            OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                "CONTRACT CANDIDATE",
                &compact_repo_path(&root),
                "Candidate was not admitted",
                &format!("{code}: {error}"),
                &next.into_iter().map(str::to_string).collect::<Vec<_>>(),
            )),
            OutputFormat::Json => {
                CommandOutput::failure(to_json(&ContractCandidateApplicationFailure {
                    ok: false,
                    mode,
                    candidate_path: &candidate_path_display,
                    written: false,
                    code,
                    error: &error,
                    carrier: None,
                    previous_commit: None,
                    resulting_commit: None,
                    branch_ref: None,
                    next,
                }))
            }
        };
        finalize_debug(output, debug, debug_lines.clone())
    };

    #[cfg(not(any(target_os = "linux", target_os = "macos")))]
    if write && matches!(carrier, Some(ContractCandidateUpdateCarrier::Git)) {
        return failure(
            "candidate_write_unsupported_platform",
            String::from(
                "the Git candidate writer requires Linux or macOS no-follow directory support",
            ),
            Some("review the candidate in dry-run mode on this platform"),
        );
    }

    // The lock is rooted directly in the repository and covers source re-derivation through
    // create-new publication. It is not relied on to overwrite external writers.
    let _write_lock = if write {
        match acquire_candidate_application_lock(&root) {
            Ok(lock) => Some(lock),
            Err(error) => {
                return failure(
                    "candidate_write_failed",
                    error,
                    Some("wait for the active candidate application to finish, then retry"),
                );
            }
        }
    } else {
        None
    };

    let candidate = match fs::read(&candidate_file)
        .map_err(|error| format!("failed to read candidate artifact: {error}"))
        .and_then(|bytes| {
            serde_json::from_slice::<ContractCandidate>(&bytes)
                .map_err(|error| format!("failed to parse candidate artifact: {error}"))
        }) {
        Ok(candidate) => candidate,
        Err(error) => return failure("candidate_malformed", error, None),
    };
    if let Err(error) = candidate.verify_identities() {
        let code = match error {
            CandidateError::IdentityMismatch | CandidateError::ClosureIdentityMismatch => {
                "candidate_identity_invalid"
            }
            _ => "candidate_malformed",
        };
        return failure(code, error.to_string(), None);
    }
    if write
        && matches!(carrier, Some(ContractCandidateUpdateCarrier::Git))
        && git_text(&root, &["symbolic-ref", "-q", "HEAD"]).is_err()
    {
        return failure(
            "candidate_write_failed",
            String::from("the Git carrier refuses a detached HEAD"),
            Some("check out a local branch, then retry the reviewed candidate"),
        );
    }
    if candidate.kind == CandidateKind::Upgrade {
        if write && carrier.is_none() {
            return failure(
                "candidate_unsupported",
                String::from(
                    "upgrade candidates are reviewable, but existing-contract publication is not enabled because the create-new writer cannot safely replace ota.yaml",
                ),
                Some(
                    "review the dry-run result; do not replace ota.yaml until Ota ships an owned existing-contract update carrier",
                ),
            );
        }
        let already_applied = matches!(
            build_contract_upgrade_candidate(&root),
            Err(ContractUpgradeError::NoRegisteredMigration)
        ) && write
            && matches!(carrier, Some(ContractCandidateUpdateCarrier::Git))
            && git_contract_matches_head(
                &root,
                _write_lock
                    .as_ref()
                    .expect("write mode retains a protected repository directory"),
            )
            && candidate.migration.as_ref().is_some_and(|migration| {
                fs::read(root.join(DEFAULT_CONTRACT_FILE))
                    .ok()
                    .is_some_and(|bytes| {
                        contract_snapshot_hash(&bytes) == migration.resulting_content_identity
                    })
            })
            && candidate
                .application_projection
                .as_ref()
                .is_some_and(|projection| {
                    current_contract_semantic_identity(&root)
                        .ok()
                        .flatten()
                        .is_some_and(|identity| identity == projection.resulting_contract_identity)
                });
        if already_applied {
            let application_projection = candidate
                .application_projection
                .as_ref()
                .expect("verified upgrade candidate has an application projection");
            let output = match format {
                OutputFormat::Text => CommandOutput::success(format!(
                    "{}\n\n{}\n{}\nNo-op: ota.yaml already matches the committed reviewed contract.",
                    format_command_header("CONTRACT CANDIDATE", &compact_repo_path(&root)),
                    format_result_line("upgrade candidate admission remains reproducible"),
                    format_result_line(&format!("identity {}", paint_code(&candidate.identity))),
                )),
                OutputFormat::Json => {
                    CommandOutput::success(to_json(&ContractCandidateApplicationSuccess {
                        ok: true,
                        mode,
                        candidate_path: &candidate_path_display,
                        candidate_identity: &candidate.identity,
                        implementation_identity: &candidate.implementation_identity,
                        application_projection_identity: &application_projection.identity,
                        resulting_contract_identity: &application_projection
                            .resulting_contract_identity,
                        admitted: true,
                        written: false,
                        carrier: None,
                        previous_commit: None,
                        resulting_commit: None,
                        branch_ref: None,
                        no_op: true,
                        residual_dispositions: Vec::new(),
                    }))
                }
            };
            return finalize_debug(output, debug, debug_lines);
        }
        let current = match build_contract_upgrade_candidate(&root) {
            Ok(current) => current,
            Err(error) => {
                return failure(
                    "candidate_not_reproducible",
                    format!("failed to re-derive the registered contract migration: {error}"),
                    Some("rerun `ota contract upgrade --candidate-out <path>` and review it"),
                );
            }
        };
        if candidate != current.candidate {
            return failure(
                "candidate_stale",
                String::from("current ota.yaml did not re-derive the reviewed upgrade candidate"),
                Some("rerun `ota contract upgrade --candidate-out <path>` and review it"),
            );
        }
        let projected_contract = match verify_candidate_application_projection(
            &candidate,
            Some(&current.existing_contract_value),
        ) {
            Ok(contract) => contract,
            Err(error) => {
                return failure(
                    "candidate_incomplete",
                    format!("upgrade projection did not re-derive a valid contract: {error}"),
                    Some("regenerate and review the upgrade candidate"),
                );
            }
        };
        let resulting_bytes = match serde_yaml::to_string(&projected_contract) {
            Ok(value) => value.into_bytes(),
            Err(error) => return failure("candidate_incomplete", error.to_string(), None),
        };
        let migration = candidate
            .migration
            .as_ref()
            .expect("verified upgrade candidate has migration evidence");
        if contract_snapshot_hash(&resulting_bytes) != migration.resulting_content_identity {
            return failure(
                "candidate_identity_invalid",
                String::from("upgrade resulting content identity did not re-derive"),
                None,
            );
        }
        let application_projection = candidate
            .application_projection
            .as_ref()
            .expect("verified upgrade candidate has an application projection");
        let carrier_publication = if write && !already_applied {
            let carrier = carrier.expect("upgrade write requires an explicit carrier");
            let publication = match carrier {
                ContractCandidateUpdateCarrier::Git => write_candidate_contract_git(
                    &root,
                    _write_lock
                        .as_ref()
                        .expect("write mode retains a protected repository directory"),
                    &projected_contract,
                    candidate.existing_contract_snapshot_identity.as_deref(),
                    &candidate.identity,
                ),
            };
            match publication {
                Ok(publication) => Some(publication),
                Err(error) => {
                    return match error {
                        CandidatePublicationError::PrePublication(error) => failure(
                            "candidate_write_failed",
                            error,
                            Some(
                                "review current Git and contract state, then regenerate the candidate before retrying",
                            ),
                        ),
                        CandidatePublicationError::DurabilityUncertain(error) => {
                            candidate_publication_uncertain_failure(
                                format,
                                debug,
                                debug_lines,
                                mode,
                                &candidate_path_display,
                                error,
                            )
                        }
                        CandidatePublicationError::CommittedButWorktreeUnsynced {
                            error,
                            publication,
                        } => candidate_publication_committed_unsynced_failure(
                            format,
                            debug,
                            debug_lines,
                            mode,
                            &candidate_path_display,
                            error,
                            &publication,
                        ),
                    };
                }
            }
        } else {
            None
        };
        let output = match format {
            OutputFormat::Text => CommandOutput::success(format!(
                "{}\n\n{}\n{}\n{}",
                format_command_header("CONTRACT CANDIDATE", &compact_repo_path(&root)),
                format_result_line("upgrade candidate admission is reproducible"),
                format_result_line(&format!("identity {}", paint_code(&candidate.identity))),
                if already_applied {
                    "No-op: ota.yaml already matches the committed reviewed contract."
                } else if write {
                    "Applied through the Git carrier: ota.yaml now matches the committed reviewed contract."
                } else {
                    "Dry-run only: ota.yaml was not changed; existing-contract publication remains disabled."
                },
            )),
            OutputFormat::Json => {
                CommandOutput::success(to_json(&ContractCandidateApplicationSuccess {
                    ok: true,
                    mode,
                    candidate_path: &candidate_path_display,
                    candidate_identity: &candidate.identity,
                    implementation_identity: &candidate.implementation_identity,
                    application_projection_identity: &application_projection.identity,
                    resulting_contract_identity: &application_projection
                        .resulting_contract_identity,
                    admitted: true,
                    written: write && !already_applied,
                    carrier: carrier_publication.as_ref().map(|_| "git"),
                    previous_commit: carrier_publication
                        .as_ref()
                        .map(|publication| publication.previous_commit.as_str()),
                    resulting_commit: carrier_publication
                        .as_ref()
                        .map(|publication| publication.resulting_commit.as_str()),
                    branch_ref: carrier_publication
                        .as_ref()
                        .map(|publication| publication.branch_ref.as_str()),
                    no_op: already_applied,
                    residual_dispositions: Vec::new(),
                }))
            }
        };
        return finalize_debug(output, debug, debug_lines);
    }
    if candidate.application_projection.is_none() {
        return failure(
            "candidate_incomplete",
            String::from("candidate has no complete validated application projection"),
            Some("review the unresolved candidate evidence and regenerate the candidate"),
        );
    }
    let application_projection = candidate
        .application_projection
        .as_ref()
        .expect("candidate projection was checked above");

    let current = match detect_repo(&root).and_then(|report| {
        if candidate.profile == Some(CandidateProfile::DetectConservativeFirstContractV1) {
            build_conservative_first_contract_candidate(&report)
                .map(|(capture, _)| capture)
                .map_err(crate::detector::DetectError::Candidate)
        } else {
            report.source_bound_candidate()
        }
    }) {
        Ok(current) => current,
        Err(error) => {
            return failure(
                "candidate_not_reproducible",
                format!("failed to re-derive candidate from current repository truth: {error}"),
                Some(
                    "rerun `ota detect --candidate-out <path>` after resolving repository discovery errors",
                ),
            );
        }
    };
    if candidate.implementation_identity != current.candidate.implementation_identity {
        return failure(
            "candidate_implementation_incompatible",
            String::from("candidate was produced by a different detector implementation"),
            Some("regenerate the candidate with the current Ota version"),
        );
    }
    let semantic_no_op = write
        && current_contract_semantic_identity(&root)
            .ok()
            .flatten()
            .is_some_and(|identity| identity == application_projection.resulting_contract_identity);
    if candidate.existing_contract_snapshot_identity
        != current.candidate.existing_contract_snapshot_identity
        && !semantic_no_op
    {
        return failure(
            "candidate_contract_mismatch",
            String::from("the current ota.yaml snapshot differs from the reviewed candidate"),
            Some("review and regenerate the candidate against the current contract"),
        );
    }
    let source_evidence_matches = if semantic_no_op {
        candidate_evidence_matches_root(&candidate, &root)
    } else {
        candidate.evidence_manifest_identity == current.candidate.evidence_manifest_identity
    };
    if candidate.discovery_inventory_identity != current.candidate.discovery_inventory_identity
        || !source_evidence_matches
    {
        return failure(
            "candidate_stale",
            String::from("the recorded discovery inventory or selected evidence has changed"),
            Some("rerun `ota detect --candidate-out <path>` and review the new artifact"),
        );
    }
    if !semantic_no_op && candidate != current.candidate {
        return failure(
            "candidate_not_reproducible",
            String::from("current source evidence did not re-derive the reviewed candidate"),
            Some("regenerate the candidate and review the semantic differences"),
        );
    }
    let projected_contract = match verify_candidate_application_projection(
        &candidate,
        current.existing_contract_value.as_ref(),
    ) {
        Ok(contract) => Some(contract),
        Err(_) if semantic_no_op => None,
        Err(error) => {
            return failure(
                "candidate_incomplete",
                format!(
                    "candidate application projection did not re-derive a valid contract: {error}"
                ),
                Some("regenerate and review the candidate before attempting contract application"),
            );
        }
    };
    if candidate
        .changes
        .iter()
        .any(|change| change.disposition == CandidateDisposition::Conflict)
    {
        return failure(
            "candidate_conflict",
            String::from("candidate retains a conflict with existing contract truth"),
            Some("resolve the contract disagreement, then regenerate the candidate"),
        );
    }
    let residual_dispositions = candidate
        .changes
        .iter()
        .filter_map(|change| match change.disposition {
            CandidateDisposition::Unknown => Some("unknown"),
            CandidateDisposition::Unsupported => Some("unsupported"),
            CandidateDisposition::Applicable | CandidateDisposition::Conflict => None,
        })
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    if require_complete && !residual_dispositions.is_empty() {
        return failure(
            "candidate_incomplete",
            format!("candidate retains {}", residual_dispositions.join(" and ")),
            Some("review the residual findings or rerun without `--require-complete`"),
        );
    }
    if write
        && semantic_no_op
        && matches!(carrier, Some(ContractCandidateUpdateCarrier::Git))
        && !git_contract_matches_head(
            &root,
            _write_lock
                .as_ref()
                .expect("write mode retains a protected repository directory"),
        )
    {
        return failure(
            "candidate_write_failed",
            String::from(
                "the Git carrier requires ota.yaml to match HEAD in both the index and worktree before a semantic no-op",
            ),
            Some("commit or discard the ota.yaml change before retrying the reviewed candidate"),
        );
    }

    let git_carrier_publication = if write && !semantic_no_op {
        let contract = projected_contract
            .as_ref()
            .expect("non-no-op write must have a verified projected contract");
        let publication = match carrier {
            Some(ContractCandidateUpdateCarrier::Git) => write_candidate_contract_git(
                &root,
                _write_lock
                    .as_ref()
                    .expect("write mode retains a protected repository directory"),
                contract,
                candidate.existing_contract_snapshot_identity.as_deref(),
                &candidate.identity,
            )
            .map(Some),
            None => {
                let guard = _write_lock
                    .as_ref()
                    .expect("write mode retains a protected repository directory");
                if candidate.profile == Some(CandidateProfile::DetectConservativeFirstContractV1) {
                    write_profile_candidate_contract_create_new(guard, &candidate, contract)
                } else {
                    write_candidate_contract_create_new(
                        guard,
                        contract,
                        candidate.existing_contract_snapshot_identity.as_deref(),
                    )
                }
                .map(|_| None)
            }
        };
        if let Err(error) = publication {
            let (error, code) = match error {
                CandidatePublicationError::PrePublication(error) => {
                    (error, "candidate_write_failed")
                }
                CandidatePublicationError::DurabilityUncertain(error) => {
                    return candidate_publication_uncertain_failure(
                        format,
                        debug,
                        debug_lines,
                        mode,
                        &candidate_path_display,
                        error,
                    );
                }
                CandidatePublicationError::CommittedButWorktreeUnsynced { error, publication } => {
                    return candidate_publication_committed_unsynced_failure(
                        format,
                        debug,
                        debug_lines,
                        mode,
                        &candidate_path_display,
                        error,
                        &publication,
                    );
                }
            };
            return failure(
                code,
                error,
                Some("review current contract state and regenerate the candidate before retrying"),
            );
        }
        publication.expect("candidate publication succeeded")
    } else {
        None
    };
    let written = write && !semantic_no_op;

    let output = match format {
        OutputFormat::Text => {
            let terminal = if write {
                if semantic_no_op {
                    "No-op: ota.yaml already matches the reviewed resulting contract."
                } else {
                    "Applied: ota.yaml was atomically created after lock-held revalidation."
                }
            } else {
                "Dry-run only: ota.yaml was not changed. Pass --write to apply after review."
            };
            let mut stdout = format!(
                "{}\n\n{}\n{}\n{}",
                format_command_header("CONTRACT CANDIDATE", &compact_repo_path(&root)),
                format_result_line("candidate admission is reproducible"),
                format_result_line(&format!("identity {}", paint_code(&candidate.identity))),
                terminal
            );
            if !residual_dispositions.is_empty() {
                stdout.push_str(&format!(
                    "\n\n{} {}",
                    paint_key("Residual review:"),
                    residual_dispositions.join(", ")
                ));
            }
            CommandOutput::success(stdout)
        }
        OutputFormat::Json => {
            CommandOutput::success(to_json(&ContractCandidateApplicationSuccess {
                ok: true,
                mode,
                candidate_path: &candidate_path_display,
                candidate_identity: &candidate.identity,
                implementation_identity: &candidate.implementation_identity,
                application_projection_identity: &application_projection.identity,
                resulting_contract_identity: &application_projection.resulting_contract_identity,
                admitted: true,
                written,
                carrier: git_carrier_publication.as_ref().map(|_| "git"),
                previous_commit: git_carrier_publication
                    .as_ref()
                    .map(|publication| publication.previous_commit.as_str()),
                resulting_commit: git_carrier_publication
                    .as_ref()
                    .map(|publication| publication.resulting_commit.as_str()),
                branch_ref: git_carrier_publication
                    .as_ref()
                    .map(|publication| publication.branch_ref.as_str()),
                no_op: semantic_no_op,
                residual_dispositions,
            }))
        }
    };
    finalize_debug(output, debug, debug_lines)
}

fn candidate_evidence_matches_root(candidate: &ContractCandidate, root: &Path) -> bool {
    let canonical_root = match fs::canonicalize(root) {
        Ok(root) => root,
        Err(_) => return false,
    };
    candidate.evidence_manifest.iter().all(|evidence| {
        let path = root.join(&evidence.path);
        let canonical_path = match fs::canonicalize(&path) {
            Ok(path) => path,
            Err(_) => return false,
        };
        canonical_path.starts_with(&canonical_root)
            && fs::read(&path)
                .ok()
                .is_some_and(|bytes| contract_snapshot_hash(&bytes) == evidence.content_identity)
    })
}

struct CandidateApplicationWriteGuard {
    #[cfg(unix)]
    root_directory: File,
}

#[cfg(unix)]
fn acquire_candidate_application_lock(
    root: &Path,
) -> Result<CandidateApplicationWriteGuard, String> {
    use std::os::unix::fs::OpenOptionsExt as _;

    let mut options = OpenOptions::new();
    options
        .read(true)
        .custom_flags(libc::O_CLOEXEC | libc::O_DIRECTORY | libc::O_NOFOLLOW);
    let root_directory = options.open(root).map_err(|error| {
        format!(
            "failed to open repository root `{}` without following aliases: {error}",
            root.display()
        )
    })?;
    root_directory.lock_exclusive().map_err(|error| {
        format!("failed to acquire repository candidate application lock: {error}")
    })?;
    Ok(CandidateApplicationWriteGuard { root_directory })
}

fn candidate_publication_uncertain_failure(
    format: OutputFormat,
    debug: bool,
    debug_lines: Vec<String>,
    mode: &'static str,
    candidate_path: &str,
    error: String,
) -> CommandOutput {
    let output = match format {
        OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
            "CONTRACT CANDIDATE",
            ".",
            "Candidate contract was created but durability is uncertain",
            &format!("candidate_write_durability_uncertain: {error}"),
            &[String::from(
                "verify ota.yaml before retrying; do not assume this invocation can be repeated safely",
            )],
        )),
        OutputFormat::Json => {
            CommandOutput::failure(to_json(&ContractCandidateApplicationFailure {
                ok: false,
                mode,
                candidate_path,
                written: true,
                code: "candidate_write_durability_uncertain",
                error: &error,
                carrier: None,
                previous_commit: None,
                resulting_commit: None,
                branch_ref: None,
                next: Some(
                    "verify ota.yaml before retrying; do not assume this invocation can be repeated safely",
                ),
            }))
        }
    };
    finalize_debug(output, debug, debug_lines)
}

fn candidate_publication_committed_unsynced_failure(
    format: OutputFormat,
    debug: bool,
    debug_lines: Vec<String>,
    mode: &'static str,
    candidate_path: &str,
    error: String,
    publication: &GitCarrierPublication,
) -> CommandOutput {
    let output = match format {
        OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
            "CONTRACT CANDIDATE",
            ".",
            "Candidate contract commit succeeded but ota.yaml was not reconciled",
            &format!("candidate_write_committed_worktree_unsynced: {error}"),
            &[String::from(
                "inspect the recorded commit and reconcile ota.yaml before retrying; do not rerun this candidate blindly",
            )],
        )),
        OutputFormat::Json => {
            CommandOutput::failure(to_json(&ContractCandidateApplicationFailure {
                ok: false,
                mode,
                candidate_path,
                written: true,
                code: "candidate_write_committed_worktree_unsynced",
                error: &error,
                carrier: Some("git"),
                previous_commit: Some(&publication.previous_commit),
                resulting_commit: Some(&publication.resulting_commit),
                branch_ref: Some(&publication.branch_ref),
                next: Some(
                    "inspect the recorded commit and reconcile ota.yaml before retrying; do not rerun this candidate blindly",
                ),
            }))
        }
    };
    finalize_debug(output, debug, debug_lines)
}

#[cfg(not(unix))]
fn acquire_candidate_application_lock(
    _root: &Path,
) -> Result<CandidateApplicationWriteGuard, String> {
    Err(String::from(
        "candidate publication requires Unix no-follow directory support",
    ))
}

fn current_contract_semantic_identity(root: &Path) -> Result<Option<String>, String> {
    let path = root.join(DEFAULT_CONTRACT_FILE);
    let metadata = match fs::symlink_metadata(&path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == io::ErrorKind::NotFound => return Ok(None),
        Err(error) => {
            return Err(format!(
                "failed to inspect current contract `{}`: {error}",
                path.display()
            ));
        }
    };
    if metadata.file_type().is_symlink() || !metadata.is_file() {
        return Err(format!(
            "current contract `{}` must be a regular non-symlink file",
            path.display()
        ));
    }
    let contents = fs::read_to_string(&path).map_err(|error| {
        format!(
            "failed to read current contract `{}`: {error}",
            path.display()
        )
    })?;
    let contract = parse_contract_str(&path, &contents).map_err(|error| {
        format!(
            "failed to parse current contract `{}`: {error}",
            path.display()
        )
    })?;
    semantic_contract_identity(&contract)
        .map(Some)
        .map_err(|error| {
            format!(
                "failed to identify current contract `{}`: {error}",
                path.display()
            )
        })
}

#[derive(Debug)]
enum CandidatePublicationError {
    PrePublication(String),
    DurabilityUncertain(String),
    CommittedButWorktreeUnsynced {
        error: String,
        publication: GitCarrierPublication,
    },
}

#[derive(Debug, Clone)]
struct GitCarrierPublication {
    previous_commit: String,
    resulting_commit: String,
    branch_ref: String,
}

fn git_command(root: &Path) -> Command {
    let mut command = Command::new("git");
    command.current_dir(root);
    // A reviewed candidate must reconcile against this checkout, never a caller-selected
    // index, object store, config overlay, or work tree. The carrier supplies its temporary
    // index explicitly after this scrub.
    for (name, _) in env::vars_os() {
        if name.to_string_lossy().starts_with("GIT_") {
            command.env_remove(name);
        }
    }
    // The carrier never asks Git to refresh an index through a configured helper or invoke a
    // hook. Candidate bytes reach Git only through stdin/cacheinfo, never attributes filters.
    command.args([
        "-c",
        "core.fsmonitor=false",
        "-c",
        "core.hooksPath=/dev/null",
        "-c",
        "commit.gpgSign=false",
    ]);
    command
}

fn git_output(root: &Path, arguments: &[&str]) -> Result<std::process::Output, String> {
    git_command(root)
        .args(arguments)
        .output()
        .map_err(|error| format!("failed to invoke Git: {error}"))
}

fn git_text(root: &Path, arguments: &[&str]) -> Result<String, String> {
    let output = git_output(root, arguments)?;
    if !output.status.success() {
        return Err(format!(
            "Git {} failed: {}",
            arguments.join(" "),
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }
    Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
}

fn git_success(root: &Path, arguments: &[&str], context: &str) -> Result<(), String> {
    let output = git_output(root, arguments)?;
    if output.status.success() {
        return Ok(());
    }
    Err(format!(
        "{context}: {}",
        String::from_utf8_lossy(&output.stderr).trim()
    ))
}

fn git_contract_matches_head(root: &Path, guard: &CandidateApplicationWriteGuard) -> bool {
    let head_commit = match git_text(root, &["rev-parse", "HEAD"]) {
        Ok(identity) => identity,
        Err(_) => return false,
    };
    let head = match git_text(root, &["rev-parse", "--verify", "HEAD:ota.yaml"]) {
        Ok(identity) => identity,
        Err(_) => return false,
    };
    git_index_and_worktree_match(root, guard, &head_commit, &head, None).unwrap_or(false)
}

fn git_index_and_worktree_match(
    root: &Path,
    guard: &CandidateApplicationWriteGuard,
    commit: &str,
    expected_blob: &str,
    expected_bytes: Option<&[u8]>,
) -> Result<bool, String> {
    if git_text(root, &["rev-parse", "HEAD"])? != commit {
        return Ok(false);
    }
    if git_text(root, &["rev-parse", "--verify", ":ota.yaml"])? != expected_blob {
        return Ok(false);
    }
    let bytes = read_git_carrier_contract(guard)?;
    if let Some(expected_bytes) = expected_bytes {
        Ok(bytes == expected_bytes)
    } else {
        let output = git_output(root, &["show", &format!("{commit}:ota.yaml")])?;
        Ok(output.status.success() && bytes == output.stdout)
    }
}

fn temporary_git_index_path(git_dir: &Path) -> Result<PathBuf, String> {
    for attempt in 0..32_u32 {
        let nonce = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map(|duration| duration.as_nanos())
            .unwrap_or_default();
        let path = git_dir.join(format!(
            "ota-candidate-index-{}-{nonce}-{attempt}",
            std::process::id()
        ));
        match OpenOptions::new().write(true).create_new(true).open(&path) {
            Ok(_) => {
                fs::remove_file(&path).map_err(|error| {
                    format!(
                        "failed to prepare temporary Git index `{}`: {error}",
                        path.display()
                    )
                })?;
                return Ok(path);
            }
            Err(error) if error.kind() == io::ErrorKind::AlreadyExists => continue,
            Err(error) => {
                return Err(format!(
                    "failed to reserve temporary Git index `{}`: {error}",
                    path.display()
                ));
            }
        }
    }
    Err(String::from(
        "failed to reserve a unique temporary Git index",
    ))
}

fn git_with_index(
    root: &Path,
    index: &Path,
    arguments: &[&str],
    context: &str,
) -> Result<String, String> {
    let output = git_command(root)
        .args(arguments)
        .env("GIT_INDEX_FILE", index)
        .output()
        .map_err(|error| format!("failed to invoke Git for {context}: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "{context}: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }
    Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
}

fn git_commit_tree(root: &Path, tree: &str, parent: &str, message: &str) -> Result<String, String> {
    let mut child = git_command(root)
        .args(["commit-tree", tree, "-p", parent])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|error| format!("failed to invoke Git commit-tree: {error}"))?;
    child
        .stdin
        .as_mut()
        .expect("Git commit-tree stdin is piped")
        .write_all(message.as_bytes())
        .map_err(|error| format!("failed to write Git commit message: {error}"))?;
    let output = child
        .wait_with_output()
        .map_err(|error| format!("failed to wait for Git commit-tree: {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "failed to create contract-only Git commit: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }
    Ok(String::from_utf8_lossy(&output.stdout).trim().to_string())
}

#[cfg(unix)]
fn read_git_carrier_contract(guard: &CandidateApplicationWriteGuard) -> Result<Vec<u8>, String> {
    let target = CString::new(DEFAULT_CONTRACT_FILE).expect("static contract name has no NUL");
    let target_fd = unsafe {
        libc::openat(
            guard.root_directory.as_raw_fd(),
            target.as_ptr(),
            libc::O_RDONLY | libc::O_CLOEXEC | libc::O_NOFOLLOW,
        )
    };
    if target_fd < 0 {
        return Err(format!(
            "failed to reopen tracked ota.yaml without following aliases: {}",
            io::Error::last_os_error()
        ));
    }
    let mut current = unsafe { File::from_raw_fd(target_fd) };
    if !current
        .metadata()
        .map_err(|error| format!("failed to inspect tracked ota.yaml: {error}"))?
        .is_file()
    {
        return Err(String::from("tracked ota.yaml is not a regular file"));
    }
    let mut bytes = Vec::new();
    current
        .read_to_end(&mut bytes)
        .map_err(|error| format!("failed to read tracked ota.yaml: {error}"))?;
    Ok(bytes)
}

#[cfg(not(unix))]
fn read_git_carrier_contract(_guard: &CandidateApplicationWriteGuard) -> Result<Vec<u8>, String> {
    Err(String::from(
        "Git-carrier contract materialization requires Unix no-follow directory support",
    ))
}

#[cfg(unix)]
fn materialize_git_carrier_contract(
    guard: &CandidateApplicationWriteGuard,
    bytes: &[u8],
    expected_head_bytes: &[u8],
) -> Result<(), String> {
    let target = CString::new(DEFAULT_CONTRACT_FILE).expect("static contract name has no NUL");
    let current_bytes = read_git_carrier_contract(guard)?;
    if current_bytes != expected_head_bytes {
        return Err(String::from(
            "ota.yaml changed after branch compare-and-swap; refusing to overwrite it",
        ));
    }

    let nonce = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or_default();
    let temporary = CString::new(format!(
        ".ota.yaml.git-carrier-{}-{nonce}",
        std::process::id()
    ))
    .expect("generated temporary name has no NUL");
    let temporary_fd = unsafe {
        libc::openat(
            guard.root_directory.as_raw_fd(),
            temporary.as_ptr(),
            libc::O_WRONLY | libc::O_CREAT | libc::O_EXCL | libc::O_CLOEXEC,
            0o600,
        )
    };
    if temporary_fd < 0 {
        return Err(format!(
            "failed to create Git-carrier materialization temporary: {}",
            io::Error::last_os_error()
        ));
    }
    let mut temporary_file = unsafe { File::from_raw_fd(temporary_fd) };
    if let Err(error) = temporary_file
        .write_all(bytes)
        .and_then(|_| temporary_file.sync_all())
    {
        let cleanup = remove_candidate_publication_temporary(&guard.root_directory, &temporary)
            .err()
            .map(|cleanup| format!("; temporary cleanup failed: {cleanup}"))
            .unwrap_or_default();
        return Err(format!(
            "failed to write Git-carrier contract materialization: {error}{cleanup}"
        ));
    }
    drop(temporary_file);
    let renamed = unsafe {
        libc::renameat(
            guard.root_directory.as_raw_fd(),
            temporary.as_ptr(),
            guard.root_directory.as_raw_fd(),
            target.as_ptr(),
        )
    };
    if renamed < 0 {
        let cleanup = remove_candidate_publication_temporary(&guard.root_directory, &temporary)
            .err()
            .map(|cleanup| format!("; temporary cleanup failed: {cleanup}"))
            .unwrap_or_default();
        return Err(format!(
            "failed to materialize committed ota.yaml: {}{cleanup}",
            io::Error::last_os_error()
        ));
    }
    guard
        .root_directory
        .sync_all()
        .map_err(|error| format!("failed to sync Git-carrier contract directory: {error}"))
}

#[cfg(any(target_os = "linux", target_os = "macos"))]
fn write_candidate_contract_git(
    root: &Path,
    guard: &CandidateApplicationWriteGuard,
    contract: &Contract,
    expected_base_identity: Option<&str>,
    candidate_identity: &str,
) -> Result<GitCarrierPublication, CandidatePublicationError> {
    let Some(expected_base_identity) = expected_base_identity else {
        return Err(CandidatePublicationError::PrePublication(String::from(
            "the Git carrier applies only candidates bound to an existing ota.yaml",
        )));
    };
    let canonical_root = fs::canonicalize(root).map_err(|error| {
        CandidatePublicationError::PrePublication(format!(
            "failed to canonicalize repository root `{}`: {error}",
            root.display()
        ))
    })?;
    let git_root = git_text(root, &["rev-parse", "--show-toplevel"])
        .map_err(CandidatePublicationError::PrePublication)?;
    if fs::canonicalize(&git_root).ok().as_deref() != Some(canonical_root.as_path()) {
        return Err(CandidatePublicationError::PrePublication(String::from(
            "the Git carrier requires the candidate repository root to be the checkout root",
        )));
    }
    let branch_ref = git_text(root, &["symbolic-ref", "-q", "HEAD"]).map_err(|_| {
        CandidatePublicationError::PrePublication(String::from(
            "the Git carrier refuses a detached HEAD",
        ))
    })?;
    let previous_commit = git_text(root, &["rev-parse", "HEAD"])
        .map_err(CandidatePublicationError::PrePublication)?;
    let head_blob = git_text(root, &["rev-parse", "--verify", "HEAD:ota.yaml"]).map_err(|_| {
        CandidatePublicationError::PrePublication(String::from(
            "the Git carrier requires ota.yaml to be tracked at HEAD",
        ))
    })?;
    let head_bytes = git_output(root, &["show", "HEAD:ota.yaml"])
        .map_err(CandidatePublicationError::PrePublication)?;
    if !head_bytes.status.success() {
        return Err(CandidatePublicationError::PrePublication(format!(
            "failed to read HEAD:ota.yaml: {}",
            String::from_utf8_lossy(&head_bytes.stderr).trim()
        )));
    }
    let expected_head_bytes = head_bytes.stdout;
    let head_identity = contract_snapshot_hash(&expected_head_bytes);
    if head_identity != expected_base_identity {
        return Err(CandidatePublicationError::PrePublication(String::from(
            "the candidate base identity does not match the tracked HEAD:ota.yaml",
        )));
    }
    if git_text(root, &["rev-parse", "--verify", ":ota.yaml"])
        .map_err(CandidatePublicationError::PrePublication)?
        != head_blob
    {
        return Err(CandidatePublicationError::PrePublication(String::from(
            "the Git carrier refuses a staged ota.yaml change",
        )));
    }
    if read_git_carrier_contract(guard).map_err(CandidatePublicationError::PrePublication)?
        != expected_head_bytes
    {
        return Err(CandidatePublicationError::PrePublication(String::from(
            "the Git carrier refuses a working-tree ota.yaml change",
        )));
    }

    let bytes = serde_yaml::to_string(contract)
        .map_err(|error| {
            CandidatePublicationError::PrePublication(format!(
                "failed to serialize projected contract: {error}"
            ))
        })?
        .into_bytes();
    let git_dir = git_text(root, &["rev-parse", "--git-dir"])
        .map_err(CandidatePublicationError::PrePublication)?;
    let git_dir = if Path::new(&git_dir).is_absolute() {
        PathBuf::from(git_dir)
    } else {
        root.join(git_dir)
    };
    let index =
        temporary_git_index_path(&git_dir).map_err(CandidatePublicationError::PrePublication)?;
    let mut committed_publication = None;
    let result = (|| {
        let blob = git_command(root)
            .args(["hash-object", "-w", "--stdin"])
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .map_err(|error| format!("failed to invoke Git hash-object: {error}"))?;
        let mut blob = blob;
        blob.stdin
            .as_mut()
            .expect("Git hash-object stdin is piped")
            .write_all(&bytes)
            .map_err(|error| format!("failed to write projected contract to Git: {error}"))?;
        let blob_output = blob
            .wait_with_output()
            .map_err(|error| format!("failed to wait for Git hash-object: {error}"))?;
        if !blob_output.status.success() {
            return Err(format!(
                "failed to store projected contract blob: {}",
                String::from_utf8_lossy(&blob_output.stderr).trim()
            ));
        }
        let blob_identity = String::from_utf8_lossy(&blob_output.stdout)
            .trim()
            .to_string();
        git_with_index(
            root,
            &index,
            &["read-tree", "HEAD"],
            "failed to prepare temporary Git index",
        )?;
        git_with_index(
            root,
            &index,
            &[
                "update-index",
                "--add",
                "--cacheinfo",
                &format!("100644,{blob_identity},ota.yaml"),
            ],
            "failed to stage projected ota.yaml in temporary Git index",
        )?;
        let tree = git_with_index(
            root,
            &index,
            &["write-tree"],
            "failed to write contract-only Git tree",
        )?;
        let commit = git_commit_tree(
            root,
            &tree,
            &previous_commit,
            &format!("ota: apply contract candidate {candidate_identity}\n"),
        )?;
        if git_text(root, &["rev-parse", "HEAD"])? != previous_commit
            || git_text(root, &["rev-parse", "--verify", ":ota.yaml"])? != head_blob
        {
            return Err(String::from(
                "the staged ota.yaml changed before Git carrier publication",
            ));
        }
        if read_git_carrier_contract(guard)? != expected_head_bytes {
            return Err(String::from(
                "the working-tree ota.yaml changed before Git carrier publication",
            ));
        }
        if candidate_publication_fault("git_temporary_index_cleanup") {
            return Err(String::from(
                "test fault injected before temporary Git-index cleanup",
            ));
        }
        fs::remove_file(&index).map_err(|error| {
            format!("failed to remove temporary Git index before branch compare-and-swap: {error}")
        })?;
        if candidate_publication_fault("git_pre_cas_ref_change") {
            let parent = git_text(root, &["rev-parse", "HEAD^"])?;
            git_success(
                root,
                &["update-ref", &branch_ref, &parent, &previous_commit],
                "test fault failed to change the branch before compare-and-swap",
            )?;
        }
        git_success(
            root,
            &["update-ref", &branch_ref, &commit, &previous_commit],
            "the checked-out branch advanced before the reviewed candidate could be committed",
        )?;
        committed_publication = Some(GitCarrierPublication {
            previous_commit: previous_commit.clone(),
            resulting_commit: commit.clone(),
            branch_ref: branch_ref.clone(),
        });
        if candidate_publication_fault("git_post_cas") {
            return Err(String::from(
                "test fault injected after Git branch compare-and-swap",
            ));
        }
        if git_text(root, &["rev-parse", "HEAD"])? != commit {
            return Err(format!(
                "committed {commit}, but the checked-out branch advanced before ota.yaml could be reconciled"
            ));
        }
        if let Err(error) = materialize_git_carrier_contract(guard, &bytes, &expected_head_bytes) {
            return Err(format!("committed {commit}, but {error}"));
        }
        if let Err(error) = git_success(
            root,
            &[
                "update-index",
                "--add",
                "--cacheinfo",
                &format!("100644,{blob_identity},ota.yaml"),
            ],
            "failed to synchronize ota.yaml in the primary Git index",
        ) {
            return Err(format!("committed {commit}, but {error}"));
        }
        if !git_index_and_worktree_match(root, guard, &commit, &blob_identity, Some(&bytes))? {
            return Err(format!(
                "committed {commit}, but ota.yaml no longer matches the committed contract"
            ));
        }
        if git_text(root, &["rev-parse", "HEAD"])? != commit {
            return Err(format!(
                "committed {commit}, but the checked-out branch advanced during ota.yaml reconciliation"
            ));
        }
        Ok::<_, String>(commit)
    })();
    let _ = fs::remove_file(&index);
    match result {
        Ok(resulting_commit) => Ok(GitCarrierPublication {
            previous_commit,
            resulting_commit,
            branch_ref,
        }),
        Err(error) if committed_publication.is_some() => {
            Err(CandidatePublicationError::CommittedButWorktreeUnsynced {
                error,
                publication: committed_publication
                    .expect("publication remains available after CAS"),
            })
        }
        Err(error) => Err(CandidatePublicationError::PrePublication(error)),
    }
}

#[cfg(not(any(target_os = "linux", target_os = "macos")))]
fn write_candidate_contract_git(
    _root: &Path,
    _guard: &CandidateApplicationWriteGuard,
    _contract: &Contract,
    _expected_base_identity: Option<&str>,
    _candidate_identity: &str,
) -> Result<GitCarrierPublication, CandidatePublicationError> {
    Err(CandidatePublicationError::PrePublication(String::from(
        "the Git candidate writer requires Linux or macOS no-follow directory support",
    )))
}

fn candidate_publication_fault(stage: &str) -> bool {
    #[cfg(feature = "test-candidate-publication-faults")]
    {
        env::var("OTA_TEST_CANDIDATE_PUBLICATION_FAULT")
            .ok()
            .is_some_and(|configured| configured.split(',').any(|value| value == stage))
    }
    #[cfg(not(feature = "test-candidate-publication-faults"))]
    {
        let _ = stage;
        false
    }
}

#[cfg(unix)]
fn remove_candidate_publication_temporary(
    directory: &File,
    temporary: &CString,
) -> Result<(), String> {
    if candidate_publication_fault("temporary_cleanup") {
        return Err(String::from("test fault injected before temporary cleanup"));
    }
    let result = unsafe { libc::unlinkat(directory.as_raw_fd(), temporary.as_ptr(), 0) };
    if result < 0 {
        return Err(io::Error::last_os_error().to_string());
    }
    Ok(())
}

#[cfg(unix)]
fn write_candidate_contract_create_new(
    guard: &CandidateApplicationWriteGuard,
    contract: &Contract,
    expected_base_identity: Option<&str>,
) -> Result<(), CandidatePublicationError> {
    let bytes = serde_yaml::to_string(contract)
        .map_err(|error| {
            CandidatePublicationError::PrePublication(format!(
                "failed to serialize projected contract: {error}"
            ))
        })?
        .into_bytes();
    write_candidate_contract_bytes_create_new(guard, &bytes, expected_base_identity)
}

fn write_profile_candidate_contract_create_new(
    guard: &CandidateApplicationWriteGuard,
    candidate: &ContractCandidate,
    contract: &Contract,
) -> Result<(), CandidatePublicationError> {
    let document = derive_candidate_application_document(candidate, None).map_err(|error| {
        CandidatePublicationError::PrePublication(format!(
            "failed to derive profile candidate document: {error}"
        ))
    })?;
    let bytes = serde_yaml::to_string(&document)
        .map_err(|error| {
            CandidatePublicationError::PrePublication(format!(
                "failed to serialize profile candidate document: {error}"
            ))
        })?
        .into_bytes();
    let parsed = std::str::from_utf8(&bytes)
        .map_err(|error| CandidatePublicationError::PrePublication(error.to_string()))
        .and_then(|yaml| {
            parse_contract_str(Path::new(DEFAULT_CONTRACT_FILE), yaml).map_err(|error| {
                CandidatePublicationError::PrePublication(format!(
                    "profile candidate document is invalid: {error}"
                ))
            })
        })?;
    let parsed_identity = semantic_contract_identity(&parsed).map_err(|error| {
        CandidatePublicationError::PrePublication(format!(
            "failed to identify profile candidate document: {error}"
        ))
    })?;
    let expected_identity = semantic_contract_identity(contract).map_err(|error| {
        CandidatePublicationError::PrePublication(format!(
            "failed to identify projected contract: {error}"
        ))
    })?;
    if parsed_identity != expected_identity {
        return Err(CandidatePublicationError::PrePublication(String::from(
            "profile candidate document does not match the verified projected contract",
        )));
    }
    #[cfg(unix)]
    {
        write_candidate_contract_bytes_create_new(guard, &bytes, None)
    }
    #[cfg(not(unix))]
    {
        write_candidate_contract_create_new(guard, contract, None)
    }
}

#[cfg(unix)]
fn write_candidate_contract_bytes_create_new(
    guard: &CandidateApplicationWriteGuard,
    bytes: &[u8],
    expected_base_identity: Option<&str>,
) -> Result<(), CandidatePublicationError> {
    if expected_base_identity.is_some() {
        return Err(CandidatePublicationError::PrePublication(String::from(
            "candidate publication refuses to replace an existing ota.yaml; review the candidate and apply the contract through an owned update flow",
        )));
    }

    let nonce = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or_default();
    let temporary_name = format!(".ota.yaml.candidate-apply-{}-{nonce}", std::process::id());
    let temporary =
        CString::new(temporary_name.clone()).expect("generated temporary name has no NUL");
    let target = CString::new(DEFAULT_CONTRACT_FILE).expect("static contract name contains no NUL");
    let fd = unsafe {
        libc::openat(
            guard.root_directory.as_raw_fd(),
            temporary.as_ptr(),
            libc::O_WRONLY | libc::O_CREAT | libc::O_EXCL | libc::O_CLOEXEC,
            0o600,
        )
    };
    if fd < 0 {
        return Err(CandidatePublicationError::PrePublication(format!(
            "failed to create candidate publication temporary file: {}",
            io::Error::last_os_error()
        )));
    }
    let mut file = unsafe { File::from_raw_fd(fd) };
    if let Err(error) = file.write_all(bytes).and_then(|_| file.sync_all()) {
        let cleanup = remove_candidate_publication_temporary(&guard.root_directory, &temporary)
            .err()
            .map(|cleanup| format!("; temporary cleanup failed: {cleanup}"))
            .unwrap_or_default();
        return Err(CandidatePublicationError::PrePublication(format!(
            "failed to persist candidate publication temporary file: {error}{cleanup}",
        )));
    }
    if candidate_publication_fault("after_temporary_sync") {
        let cleanup = remove_candidate_publication_temporary(&guard.root_directory, &temporary)
            .err()
            .map(|cleanup| format!("; temporary cleanup failed: {cleanup}"))
            .unwrap_or_default();
        return Err(CandidatePublicationError::PrePublication(format!(
            "test fault injected after candidate publication temporary file sync{cleanup}",
        )));
    }
    if candidate_publication_fault("concurrent_target_creation") {
        let external = unsafe {
            libc::openat(
                guard.root_directory.as_raw_fd(),
                target.as_ptr(),
                libc::O_WRONLY | libc::O_CREAT | libc::O_EXCL | libc::O_CLOEXEC,
                0o600,
            )
        };
        if external >= 0 {
            unsafe { libc::close(external) };
        }
    }
    let published = publish_candidate_create_new(&guard.root_directory, &temporary, &target);
    if published < 0 {
        let cleanup = remove_candidate_publication_temporary(&guard.root_directory, &temporary)
            .err()
            .map(|cleanup| format!("; temporary cleanup failed: {cleanup}"))
            .unwrap_or_default();
        return Err(CandidatePublicationError::PrePublication(format!(
            "failed to atomically create ota.yaml from candidate projection: {}{cleanup}",
            io::Error::last_os_error(),
        )));
    }
    if candidate_publication_fault("directory_sync") {
        return Err(CandidatePublicationError::DurabilityUncertain(
            String::from(
                "test fault injected after ota.yaml publication before repository directory sync",
            ),
        ));
    }
    guard.root_directory.sync_all().map_err(|error| {
        CandidatePublicationError::DurabilityUncertain(format!(
            "ota.yaml was created but the repository directory could not be synced: {error}",
        ))
    })
}

#[cfg(target_os = "linux")]
fn publish_candidate_create_new(directory: &File, temporary: &CString, target: &CString) -> i32 {
    unsafe {
        libc::renameat2(
            directory.as_raw_fd(),
            temporary.as_ptr(),
            directory.as_raw_fd(),
            target.as_ptr(),
            libc::RENAME_NOREPLACE,
        )
    }
}

#[cfg(target_os = "macos")]
fn publish_candidate_create_new(directory: &File, temporary: &CString, target: &CString) -> i32 {
    unsafe {
        libc::renameatx_np(
            directory.as_raw_fd(),
            temporary.as_ptr(),
            directory.as_raw_fd(),
            target.as_ptr(),
            libc::RENAME_EXCL,
        )
    }
}

#[cfg(all(unix, not(any(target_os = "linux", target_os = "macos"))))]
fn publish_candidate_create_new(_directory: &File, _temporary: &CString, _target: &CString) -> i32 {
    unsafe {
        *libc::__error() = libc::ENOTSUP;
    }
    -1
}

