fn render_detect_contract_preview(
    report: &crate::detector::DetectReport,
    contract_path: &Path,
) -> CommandOutput {
    let compact_root_display = compact_repo_path(
        contract_path
            .parent()
            .expect("contract path has a repository parent"),
    );
    let bootstrap_contract = bootstrap_init_contract(report);
    let review_yaml = serde_yaml::to_string(&bootstrap_contract)
        .expect("serializing detected starter contract should not fail");

    if let Err(error) = parse_contract_str(contract_path, &review_yaml)
        .map_err(|error| error.to_string())
        .and_then(|contract| {
            validate_contract_with_path(&contract, Some(contract_path))
                .map_err(|error| error.to_string())
        })
    {
        return CommandOutput::failure(command_message_failure_text(
            "DETECT CONTRACT PREVIEW",
            &compact_root_display,
            "Starter contract preview is invalid",
            &error,
            &[format!(
                "review detected fields with `{}`",
                command_for_repo("ota detect --dry-run", &report.root)
            )],
        ));
    }

    let mut stdout = format_command_header("DETECT CONTRACT PREVIEW", &compact_root_display);
    stdout.push_str(&format!(
        "\n\n{}",
        stylize_yaml_preview(review_yaml.trim_end())
    ));
    CommandOutput::success(stdout)
}

pub fn workspace_validate(
    path: Option<&Path>,
    file_override: Option<&Path>,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let resolved_path = match resolve_workspace_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => CommandOutput::failure(workspace_target_resolution_text(
                        "WORKSPACE VALIDATE",
                        "ota workspace validate",
                        &error.to_string(),
                    )),
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=workspace.validate")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_workspace_path(&resolved_path);
    let debug_lines = vec![
        String::from("DEBUG command=workspace.validate"),
        format!("DEBUG workspace_path={path_display}"),
    ];

    finalize_debug(
        match load_and_validate_workspace(&resolved_path) {
            Ok(()) => match format {
                OutputFormat::Text => CommandOutput::success(format!(
                    "{}\n\n{}{}",
                    format_command_header("WORKSPACE VALIDATE", &compact_path_display),
                    render_valid_status(),
                    render_workspace_validate_ready_next()
                )),
                OutputFormat::Json => CommandOutput::success(to_json(&ValidateSuccess {
                    ok: true,
                    path: &path_display,
                    summary: Some(ValidateSummary {
                        error_count: 0,
                        warn_count: 0,
                    }),
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                })),
            },
            Err(WorkspaceProblem::Validation(errors)) => match format {
                OutputFormat::Text => CommandOutput::failure(render_workspace_validate_failure(
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    None,
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    ok: false,
                    path: &path_display,
                    summary: Some(ValidateSummary {
                        error_count: errors.errors().len(),
                        warn_count: 0,
                    }),
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                })),
            },
            Err(WorkspaceProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(render_workspace_validate_failure(
                    &resolved_path,
                    &[],
                    Some(&error.to_string()),
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    ok: false,
                    path: &path_display,
                    summary: Some(ValidateSummary {
                        error_count: 1,
                        warn_count: 0,
                    }),
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

fn render_workspace_validate_ready_next() -> String {
    format_next_timeline(&[
        String::from("run `ota workspace doctor` to inspect readiness"),
        String::from("run `ota workspace up` to prepare the workspace end to end"),
        String::from("run `ota workspace tasks` to inspect runnable task usage"),
    ])
}

fn invalid_workspace_contract_output(
    command: &str,
    workspace_path: &Path,
    why_lines: &[String],
    next_steps: Vec<String>,
    format: OutputFormat,
) -> CommandOutput {
    let compact_target = compact_workspace_path(workspace_path);
    let path_display = workspace_path.display().to_string();
    let compact_why_lines = why_lines
        .iter()
        .map(|line| compact_backticked_text_in_context(line, Some(workspace_path)))
        .collect::<Vec<_>>();
    match format {
        OutputFormat::Text => CommandOutput::failure(structured_error_text(
            command,
            &compact_target,
            "Invalid workspace contract",
            &compact_why_lines,
            &next_steps,
        )),
        OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
            ok: false,
            path: &path_display,
            summary: Some(ValidateSummary {
                error_count: why_lines.len(),
                warn_count: 0,
            }),
            warnings: Vec::new(),
            warning_details: Vec::new(),
            errors: compact_why_lines,
            error: Some(String::from("Invalid workspace contract")),
        })),
    }
}

fn workspace_contract_load_text(
    command: &str,
    workspace_path: &Path,
    summary: &str,
    error: &str,
    next_steps: &[String],
) -> String {
    let compact_error = compact_backticked_text_in_context(error, Some(workspace_path));
    structured_error_text(
        command,
        &compact_workspace_path(workspace_path),
        summary,
        &[compact_error],
        next_steps,
    )
}

fn workspace_target_resolution_text(command: &str, rerun_command: &str, error: &str) -> String {
    let compact_error = compact_backticked_paths(error);
    let where_value = infer_failure_where(rerun_command, &compact_error);

    if let Some(missing) = detect_missing_contract_context(&compact_error) {
        let mut stdout = format_command_header(command, &where_value);
        stdout.push_str(&format!(
            "\n\n{}  {}",
            render_severity(FindingSeverity::Error),
            paint("Workspace target could not be resolved", "1;37")
        ));
        render_missing_contract_guidance(&mut stdout, &where_value, &compact_error, missing, true);
        return stdout;
    }

    if let Some((why, next_steps)) = split_embedded_next_block(&compact_error) {
        let why_lines = why
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .map(ToOwned::to_owned)
            .collect::<Vec<_>>();
        return structured_error_text(
            command,
            &where_value,
            "Workspace target could not be resolved",
            &why_lines,
            &next_steps,
        );
    }

    structured_error_text(
        command,
        &where_value,
        "Workspace target could not be resolved",
        &[compact_error],
        &[format!(
            "ensure the workspace path points to `{DEFAULT_WORKSPACE_FILE}`, then rerun `{rerun_command}`"
        )],
    )
}

