fn render_workspace_validate_failure(
    workspace_path: &Path,
    errors: &[String],
    load_error: Option<&str>,
) -> String {
    let mut out = format!(
        "{}  {}",
        render_severity(FindingSeverity::Error),
        paint("Workspace validation failed", "1;37")
    );
    out.push_str(&format!(
        "\n{} {}",
        paint_key("Where:"),
        paint_code(&compact_workspace_path(workspace_path))
    ));

    match load_error {
        Some(error) => {
            let compact_error = compact_backticked_text_in_context(error, Some(workspace_path));
            if let Some(missing) = detect_missing_contract_context(&compact_error) {
                render_missing_contract_guidance(
                    &mut out,
                    "ota workspace validate",
                    &compact_error,
                    missing,
                    false,
                );
            } else {
                out.push_str(&format!(
                    "\n{} {}",
                    error_key("Why:"),
                    render_backticked_text(&compact_error, None)
                ));
            }
        }
        None if errors.is_empty() => {
            out.push_str(&format!(
                "\n{} workspace validation returned an unknown error",
                error_key("Why:")
            ));
        }
        None => {
            if errors.len() == 1 {
                let compact_error =
                    compact_backticked_text_in_context(&errors[0], Some(workspace_path));
                out.push_str(&format!(
                    "\n{} {}",
                    error_key("Why:"),
                    render_backticked_text(&compact_error, None)
                ));
            } else {
                let joined = errors
                    .iter()
                    .map(|error| compact_backticked_text_in_context(error, Some(workspace_path)))
                    .collect::<Vec<_>>()
                    .join(" | ");
                out.push_str(&format!(
                    "\n{} {}",
                    error_key("Why:"),
                    render_backticked_text(&joined, None)
                ));
            }
        }
    }

    out.push_str(&format_error_next_timeline(&[format!(
        "repair the listed issue(s), then rerun `{}`",
        paint_code("ota workspace validate")
    )]));
    out
}

fn compact_backticked_paths(value: &str) -> String {
    render_backticked_text(value, None)
}

fn compact_backticked_text_in_context(value: &str, contract_path: Option<&Path>) -> String {
    transform_backticked_text(value, contract_path, |rendered| rendered.to_string())
}

fn render_backticked_text(value: &str, contract_path: Option<&Path>) -> String {
    transform_backticked_text(value, contract_path, paint_code)
}

fn transform_backticked_text<F>(value: &str, contract_path: Option<&Path>, render_code: F) -> String
where
    F: Fn(&str) -> String,
{
    let mut output = String::with_capacity(value.len());
    let mut rest = value;

    loop {
        let Some(start) = rest.find('`') else {
            output.push_str(rest);
            break;
        };
        output.push_str(&rest[..start]);
        let after_start = &rest[start + 1..];
        let Some(end) = after_start.find('`') else {
            output.push_str(&rest[start..]);
            break;
        };

        let token = &after_start[..end];
        let rendered = compact_backticked_token(token, contract_path);
        output.push('`');
        output.push_str(&render_code(&rendered));
        output.push('`');
        rest = &after_start[end + 1..];
    }

    output
}

fn compact_backticked_token(token: &str, contract_path: Option<&Path>) -> String {
    if let Some(contract_path) = contract_path
        && let Some(command) = contextualize_repo_command(token, contract_path)
    {
        return command;
    }

    if is_path_token(token) {
        return match contract_path {
            Some(contract_path) => compact_path_relative_to(
                Path::new(token),
                DEFAULT_CONTRACT_FILE,
                Some(contract_working_dir(contract_path)),
            ),
            None => compact_path(Path::new(token), DEFAULT_CONTRACT_FILE),
        };
    }

    token.to_string()
}

fn is_path_token(token: &str) -> bool {
    let token = token.trim();
    if token.is_empty() || token.chars().any(char::is_whitespace) || token.contains("://") {
        return false;
    }

    let path = Path::new(token);
    path.is_absolute()
        || token.starts_with("./")
        || token.starts_with("../")
        || token.starts_with(r".\")
        || token.starts_with(r"..\")
        || token.starts_with('~')
        || token.contains('\\')
        || is_windows_drive_path_token(token)
}

fn is_windows_drive_path_token(token: &str) -> bool {
    let bytes = token.as_bytes();
    bytes.len() >= 3
        && bytes[0].is_ascii_alphabetic()
        && bytes[1] == b':'
        && matches!(bytes[2], b'\\' | b'/')
}

fn contextualize_repo_command(token: &str, contract_path: &Path) -> Option<String> {
    let normalized = match token {
        "ota doctor" => Some("ota doctor"),
        "ota explain" => Some("ota explain"),
        "ota up" => Some("ota up"),
        "ota check" => Some("ota check"),
        "ota tasks --use" => Some("ota tasks --use"),
        "ota detect --dry-run" | "ota detect --dry-run ." => Some("ota detect --dry-run"),
        "ota detect --candidate-out .ota/candidates/detect.json" => {
            Some("ota detect --candidate-out .ota/candidates/detect.json")
        }
        "ota agents --write" => Some("ota agents --write"),
        _ if token.starts_with("ota run ") => Some(token),
        _ if token.starts_with("ota doctor --member ") => Some(token),
        _ if token.starts_with("ota tasks --member ") => Some(token),
        _ => None,
    }?;

    if matches!(
        normalized,
        "ota detect --dry-run" | "ota detect --candidate-out .ota/candidates/detect.json"
    ) {
        return Some(command_for_repo_from_contract_path(
            normalized,
            contract_path,
        ));
    }

    Some(command_for_contract(normalized, contract_path))
}

#[derive(Debug, Serialize)]
struct WorkspaceInitContract {
    version: u32,
    workspace: WorkspaceInitWorkspace,
    repos: BTreeMap<String, WorkspaceInitRepoSpec>,
}

#[derive(Debug, Serialize)]
struct WorkspaceInitWorkspace {
    name: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    description: Option<String>,
}

#[derive(Debug, Serialize)]
struct WorkspaceInitRepoSpec {
    path: String,
    required: bool,
}

#[derive(Debug, Clone, Serialize)]
struct WorkspaceInitRepoSummary {
    name: String,
    path: String,
}

#[derive(Debug, Serialize)]
struct WorkspaceInitComparison {
    existing_contract: bool,
    additions: Vec<WorkspaceInitRepoSummary>,
}

struct WorkspaceInitDraft {
    contract: WorkspaceInitContract,
    included: Vec<WorkspaceInitRepoSummary>,
    missing_contract: Vec<WorkspaceInitRepoSummary>,
}

struct WorkspaceAutoProvisionResult {
    provisioned: Vec<WorkspaceInitRepoSummary>,
    skipped: Vec<(WorkspaceInitRepoSummary, String)>,
}

struct WorkspaceRepoRewriteResult {
    rewritten: Vec<WorkspaceInitRepoSummary>,
    skipped: Vec<(WorkspaceInitRepoSummary, String)>,
}

struct WorkspaceInitMergeState {
    yaml: String,
    contract: WorkspaceContract,
    comparison: WorkspaceInitComparison,
}

pub enum WorkspaceScaffoldSurface {
    Init,
    Detect,
}

fn workspace_scaffold_write_steps(workspace_path: &Path) -> Vec<String> {
    vec![
        format!(
            "run `{}`",
            command_for_workspace("ota workspace validate", workspace_path)
        ),
        format!(
            "run `{}`",
            command_for_workspace("ota workspace up --dry-run", workspace_path)
        ),
        format!(
            "run `{}` when you are ready to prepare the workspace",
            command_for_workspace("ota workspace up", workspace_path)
        ),
    ]
}

pub fn workspace_init(
    path: Option<&Path>,
    write: bool,
    bootstrap: bool,
    merge: bool,
    rewrite: bool,
    yes: bool,
    surface: WorkspaceScaffoldSurface,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let workspace_command_name = match surface {
        WorkspaceScaffoldSurface::Init => "ota workspace init",
        WorkspaceScaffoldSurface::Detect => "ota workspace detect",
    };
    let workspace_command_label = match surface {
        WorkspaceScaffoldSurface::Init => "WORKSPACE INIT",
        WorkspaceScaffoldSurface::Detect => "WORKSPACE DETECT",
    };
    let (workspace_root, workspace_path) = match resolve_workspace_init_target(path) {
        Ok(target) => target,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                        workspace_command_label,
                        workspace_command_name,
                        "Workspace target could not be resolved",
                        &error,
                        &[format!(
                            "ensure the workspace path is a directory or `ota.workspace.yaml` target, then rerun `{workspace_command_name}`"
                        )],
                    )),
                    OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
                        "ok": false,
                        "path": serde_json::Value::Null,
                        "written": false,
                        "mode": "scaffold",
                        "error": error,
                    }))),
                },
                debug,
                vec![String::from("DEBUG command=workspace.init")],
            );
        }
    };

    let path_display = workspace_path.display().to_string();
    let compact_path_display = compact_workspace_path(&workspace_path);
    let compact_root_display = compact_repo_path(&workspace_root);
    let debug_lines = vec![
        String::from("DEBUG command=workspace.init"),
        format!("DEBUG workspace_root={}", workspace_root.display()),
        format!("DEBUG workspace_path={path_display}"),
        format!("DEBUG write={write}"),
        format!("DEBUG bootstrap={bootstrap}"),
        format!("DEBUG merge={merge}"),
        format!("DEBUG rewrite={rewrite}"),
        format!("DEBUG yes={yes}"),
    ];
    let command_name = workspace_command_name;
    let command_label = match surface {
        WorkspaceScaffoldSurface::Init => "INIT",
        WorkspaceScaffoldSurface::Detect => "DETECT",
    };

    if merge && !workspace_path.exists() {
        let error = if write {
            format!(
                "`{command_name} --merge` requires an existing `{DEFAULT_WORKSPACE_FILE}`{}",
                format_next_timeline(&[
                    format!("use `{command_name}` to write a first workspace contract"),
                    format!("use `{command_name} --dry-run` to review one"),
                ]),
            )
        } else {
            format!(
                "`{command_name} --merge --dry-run` requires an existing `{DEFAULT_WORKSPACE_FILE}`{}",
                format_next_timeline(&[format!(
                    "use `{command_name} --dry-run` to preview a first workspace contract",
                )]),
            )
        };
        let next = if write {
            format!("{command_name} {}", compact_workspace_path(&workspace_root))
        } else {
            format!(
                "{command_name} --dry-run {}",
                compact_workspace_path(&workspace_root)
            )
        };
        return finalize_debug(
            match format {
                OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                    &format!("WORKSPACE {command_label}"),
                    command_name,
                    "Existing workspace contract is required",
                    &error,
                    &[],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
                    "ok": false,
                    "path": path_display,
                    "written": false,
                    "mode": "scaffold",
                    "error": error,
                    "next": next,
                }))),
            },
            debug,
            debug_lines,
        );
    }
    if rewrite && !workspace_path.exists() {
        let error = if write {
            format!(
                "`{command_name} --rewrite` requires an existing `{DEFAULT_WORKSPACE_FILE}`{}",
                format_next_timeline(&[
                    format!("use `{command_name} --write` to write a first workspace contract"),
                    format!("use `{command_name} --dry-run` to review one"),
                ]),
            )
        } else {
            format!(
                "`{command_name} --rewrite --dry-run` requires an existing `{DEFAULT_WORKSPACE_FILE}`{}",
                format_next_timeline(&[format!(
                    "use `{command_name} --dry-run` to preview a first workspace contract",
                )]),
            )
        };
        let next = if write {
            format!("{command_name} {}", compact_workspace_path(&workspace_root))
        } else {
            format!(
                "{command_name} --dry-run {}",
                compact_workspace_path(&workspace_root)
            )
        };
        return finalize_debug(
            match format {
                OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                    &format!("WORKSPACE {command_label}"),
                    command_name,
                    "Existing workspace contract is required",
                    &error,
                    &[],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
                    "ok": false,
                    "path": path_display,
                    "written": false,
                    "mode": "scaffold",
                    "error": error,
                    "next": next,
                }))),
            },
            debug,
            debug_lines,
        );
    }
    if rewrite && write && !yes {
        let error = format!(
            "`{command_name} --rewrite` is destructive and requires `--yes`{}",
            format_next_timeline(&[
                format!("run `{command_name} --rewrite --dry-run` to preview replacement"),
                format!("run `{command_name} --rewrite --yes` to apply replacement"),
            ]),
        );
        return finalize_debug(
            match format {
                OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                    &format!("WORKSPACE {command_label}"),
                    command_name,
                    "Rewrite confirmation is required",
                    &error,
                    &[],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
                    "ok": false,
                    "path": path_display,
                    "written": false,
                    "mode": "scaffold",
                    "error": error,
                    "next": format!("{command_name} --rewrite --dry-run"),
                }))),
            },
            debug,
            debug_lines,
        );
    }

    finalize_debug(
        match build_workspace_init_draft(&workspace_root) {
            Ok(draft) if rewrite && !write => match format {
                OutputFormat::Text => {
                    let yaml = match serde_yaml::to_string(&draft.contract) {
                        Ok(yaml) => yaml,
                        Err(error) => {
                            return CommandOutput::failure(command_message_failure_text(
                                &format!("WORKSPACE {command_label}"),
                                &compact_path_display,
                                "Workspace contract could not be serialized",
                                &format!(
                                    "failed to serialize workspace contract for `{}`: {error}",
                                    compact_path_display
                                ),
                                &[],
                            ));
                        }
                    };
                    let mut stdout = format_command_header(
                        &format!("WORKSPACE {command_label} REWRITE PREVIEW"),
                        &compact_root_display,
                    );
                    stdout.push_str(&format!("\n\n{}", format_mode_line("dry-run (no write)")));
                    stdout.push_str(&format_next_timeline(&[format!(
                        "run `{command_name} --rewrite --yes {compact_root_display}` to replace the existing workspace contract",
                    )]));
                    stdout.push_str(&format!("\n\n{}:\n", paint_section_title("Contract")));
                    stdout.push_str(&stylize_yaml_preview(yaml.trim_end()));
                    render_workspace_init_discovery_sections(
                        &mut stdout,
                        &draft.included,
                        &draft.missing_contract,
                    );
                    CommandOutput::success(stdout)
                }
                OutputFormat::Json => CommandOutput::success(to_json_value(json!({
                    "ok": true,
                    "path": path_display,
                    "written": false,
                    "mode": "scaffold",
                    "config": draft.contract,
                    "provenance": workspace_init_contract_provenance(&draft.contract, &workspace_root),
                    "included": draft.included,
                    "missing_contract": draft.missing_contract,
                }))),
            },
            Ok(draft) if rewrite => {
                let mut draft = draft;
                let rewrite_result = rewrite_workspace_repo_contracts(
                    &workspace_root,
                    &draft.included,
                    &draft.missing_contract,
                );
                if !rewrite_result.rewritten.is_empty() {
                    draft = match build_workspace_init_draft(&workspace_root) {
                        Ok(updated) => updated,
                        Err(error) => {
                            return CommandOutput::failure(command_message_failure_text(
                                &format!("WORKSPACE {command_label}"),
                                &compact_root_display,
                                "Workspace contract could not be inferred",
                                &error,
                                &[],
                            ));
                        }
                    };
                }

                let yaml = match serde_yaml::to_string(&draft.contract) {
                    Ok(yaml) => yaml,
                    Err(error) => {
                        return CommandOutput::failure(command_message_failure_text(
                            &format!("WORKSPACE {command_label}"),
                            &compact_path_display,
                            "Workspace contract could not be serialized",
                            &format!(
                                "failed to serialize workspace contract for `{}`: {error}",
                                compact_path_display
                            ),
                            &[],
                        ));
                    }
                };
                if let Err(error) = parse_workspace_contract_str(&workspace_path, &yaml)
                    .map_err(|error| error.to_string())
                {
                    return match format {
                        OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                            &format!("WORKSPACE {command_label}"),
                            &compact_path_display,
                            "Workspace contract is invalid",
                            &error,
                            &[format!(
                                "repair the generated workspace contract, then rerun `{command_name}`"
                            )],
                        )),
                        OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
                            "ok": false,
                            "path": path_display,
                            "written": false,
                            "mode": "scaffold",
                            "error": error,
                        }))),
                    };
                }
                let backup_path = match create_timestamped_backup(&workspace_path) {
                    Ok(path) => path,
                    Err(error) => {
                        return match format {
                            OutputFormat::Text => {
                                CommandOutput::failure(command_message_failure_text(
                                    &format!("WORKSPACE {command_label}"),
                                    &compact_path_display,
                                    "Workspace contract could not be written",
                                    &error,
                                    &[],
                                ))
                            }
                            OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
                                "ok": false,
                                "path": path_display,
                                "written": false,
                                "mode": "scaffold",
                                "error": error,
                            }))),
                        };
                    }
                };
                if let Err(error) = fs::write(&workspace_path, yaml) {
                    return match format {
                        OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                            &format!("WORKSPACE {command_label}"),
                            &compact_path_display,
                            "Workspace contract could not be written",
                            &format!(
                                "failed to write `{}`: {}",
                                compact_workspace_path(&workspace_path),
                                error
                            ),
                            &[],
                        )),
                        OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
                            "ok": false,
                            "path": path_display,
                            "written": false,
                            "mode": "scaffold",
                            "error": format!(
                                "failed to write `{}`: {}",
                                compact_workspace_path(&workspace_path),
                                error
                            ),
                        }))),
                    };
                }
                match format {
                    OutputFormat::Text => {
                        let mut stdout = format_command_header(
                            &format!("WORKSPACE {command_label}"),
                            &compact_workspace_path(&workspace_path),
                        );
                        stdout.push_str(&format!("\n\n{}\n", render_status_line("REWRITTEN")));
                        stdout.push_str(&format!("\n{}\n", paint_section_title("Result")));
                        stdout.push_str(&format!(
                            "\n {}  Wrote {}",
                            summary_bullet(),
                            paint_code(&compact_workspace_path(&workspace_path))
                        ));
                        stdout.push_str(&format!(
                            "\n {}  {} {}",
                            summary_bullet(),
                            paint_key("Backup:"),
                            paint_code(&compact_workspace_path(&backup_path))
                        ));
                        render_workspace_repo_rewrite_sections(
                            &mut stdout,
                            &rewrite_result.rewritten,
                            &rewrite_result.skipped,
                        );
                        stdout.push_str(&format_next_timeline(&workspace_scaffold_write_steps(
                            &workspace_path,
                        )));
                        CommandOutput::success(stdout)
                    }
                    OutputFormat::Json => CommandOutput::success(to_json_value(json!({
                        "ok": true,
                        "path": path_display,
                        "written": true,
                        "mode": "scaffold",
                        "config": draft.contract,
                        "provenance": workspace_init_contract_provenance(&draft.contract, &workspace_root),
                        "included": draft.included,
                        "missing_contract": draft.missing_contract,
                    }))),
                }
            }
            Ok(draft) if merge && !write => {
                let merge_state = match build_workspace_init_merge_state(&workspace_path, &draft) {
                    Ok(state) => state,
                    Err(error) => {
                        return match format {
                            OutputFormat::Text => {
                                CommandOutput::failure(command_message_failure_text(
                                    &format!("WORKSPACE {command_label}"),
                                    &compact_path_display,
                                    "Workspace merge preview could not be prepared",
                                    &error,
                                    &[],
                                ))
                            }
                            OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
                                "ok": false,
                                "path": path_display,
                                "written": false,
                                "mode": "scaffold",
                                "error": error,
                            }))),
                        };
                    }
                };
                match format {
                    OutputFormat::Text => {
                        let mut stdout = format_command_header(
                            &format!("WORKSPACE {command_label} MERGE PREVIEW"),
                            &compact_root_display,
                        );
                        stdout.push_str(&format!("\n\n{}", format_mode_line("dry-run (no write)")));
                        stdout.push_str(&format_next_timeline(&[format!(
                            "run `{command_name} --merge {compact_root_display}` to apply additive repo entries",
                        )]));
                        stdout.push_str(&format!("\n\n{}\n", paint_section_title("Contract")));
                        stdout.push_str(&stylize_yaml_preview(merge_state.yaml.trim_end()));
                        render_workspace_init_merge_section(
                            &mut stdout,
                            "Additive merge preview",
                            &merge_state.comparison.additions,
                        );
                        render_workspace_init_discovery_sections(
                            &mut stdout,
                            &draft.included,
                            &draft.missing_contract,
                        );
                        CommandOutput::success(stdout)
                    }
                    OutputFormat::Json => CommandOutput::success(to_json_value(json!({
                        "ok": true,
                        "path": path_display,
                        "written": false,
                        "mode": "scaffold",
                        "config": merge_state.contract,
                        "provenance": workspace_merge_contract_provenance(&merge_state.contract, &merge_state.comparison.additions),
                        "included": draft.included,
                        "missing_contract": draft.missing_contract,
                        "comparison": merge_state.comparison,
                    }))),
                }
            }
            Ok(draft) if merge => {
                let mut draft = draft;
                let mut auto_provision = WorkspaceAutoProvisionResult {
                    provisioned: Vec::new(),
                    skipped: Vec::new(),
                };
                if write
                    && matches!(surface, WorkspaceScaffoldSurface::Detect)
                    && !draft.missing_contract.is_empty()
                {
                    auto_provision = auto_provision_workspace_repo_contracts(
                        &workspace_root,
                        &draft.missing_contract,
                    );
                    if !auto_provision.provisioned.is_empty() {
                        draft = match build_workspace_init_draft(&workspace_root) {
                            Ok(updated) => updated,
                            Err(error) => {
                                return CommandOutput::failure(command_message_failure_text(
                                    &format!("WORKSPACE {command_label}"),
                                    &compact_root_display,
                                    "Workspace contract could not be inferred",
                                    &error,
                                    &[],
                                ));
                            }
                        };
                    }
                }

                let merge_state = match apply_workspace_init_merge(&workspace_path, &draft) {
                    Ok(state) => state,
                    Err(error) => {
                        return match format {
                            OutputFormat::Text => {
                                CommandOutput::failure(command_message_failure_text(
                                    &format!("WORKSPACE {command_label}"),
                                    &compact_path_display,
                                    "Workspace contract could not be merged",
                                    &error,
                                    &[],
                                ))
                            }
                            OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
                                "ok": false,
                                "path": path_display,
                                "written": false,
                                "mode": "scaffold",
                                "error": error,
                            }))),
                        };
                    }
                };

                if merge_state.comparison.additions.is_empty() {
                    return match format {
                        OutputFormat::Text => {
                            let mut stdout = format_command_header(
                                &format!("WORKSPACE {command_label}"),
                                &compact_workspace_path(&workspace_path),
                            );
                            stdout.push_str(&format!("\n\n{}\n", render_status_line("NO CHANGES")));
                            stdout.push_str(&format!("\n{}\n", paint_section_title("Result")));
                            stdout.push_str(&format!(
                                "\n {}  No additive workspace changes were needed",
                                summary_bullet()
                            ));
                            render_workspace_init_merge_section(
                                &mut stdout,
                                "Additive merge preview",
                                &merge_state.comparison.additions,
                            );
                            render_workspace_auto_provision_sections(
                                &mut stdout,
                                &auto_provision.provisioned,
                                &auto_provision.skipped,
                            );
                            CommandOutput::success(stdout)
                        }
                        OutputFormat::Json => CommandOutput::success(to_json_value(json!({
                            "ok": true,
                            "path": path_display,
                            "written": false,
                            "mode": "scaffold",
                            "config": merge_state.contract,
                            "provenance": workspace_merge_contract_provenance(&merge_state.contract, &merge_state.comparison.additions),
                            "included": draft.included,
                            "missing_contract": draft.missing_contract,
                            "comparison": merge_state.comparison,
                        }))),
                    };
                }

                match format {
                    OutputFormat::Text => {
                        let mut stdout = format_command_header(
                            &format!("WORKSPACE {command_label}"),
                            &compact_workspace_path(&workspace_path),
                        );
                        stdout.push_str(&format!("\n\n{}\n", render_status_line("MERGED")));
                        stdout.push_str(&format!("\n{}\n", paint_section_title("Result")));
                        stdout.push_str(&format!(
                            "\n {}  Applied additive workspace entries",
                            summary_bullet()
                        ));
                        render_workspace_init_merge_section(
                            &mut stdout,
                            "Applied additions",
                            &merge_state.comparison.additions,
                        );
                        render_workspace_auto_provision_sections(
                            &mut stdout,
                            &auto_provision.provisioned,
                            &auto_provision.skipped,
                        );
                        render_workspace_init_discovery_sections(
                            &mut stdout,
                            &draft.included,
                            &draft.missing_contract,
                        );
                        stdout.push_str(&format_next_timeline(&workspace_scaffold_write_steps(
                            &workspace_path,
                        )));
                        CommandOutput::success(stdout)
                    }
                    OutputFormat::Json => CommandOutput::success(to_json_value(json!({
                        "ok": true,
                        "path": path_display,
                        "written": true,
                        "mode": "scaffold",
                        "config": merge_state.contract,
                        "provenance": workspace_merge_contract_provenance(&merge_state.contract, &merge_state.comparison.additions),
                        "included": draft.included,
                        "missing_contract": draft.missing_contract,
                        "comparison": merge_state.comparison,
                    }))),
                }
            }
            Ok(_draft) if write && workspace_path.exists() => {
                let error = match surface {
                    WorkspaceScaffoldSurface::Init => {
                        let next_detect_merge =
                            command_for_workspace("ota workspace detect --merge", &workspace_path);
                        let next_detect_rewrite = command_for_workspace(
                            "ota workspace detect --rewrite --yes",
                            &workspace_path,
                        );
                        format!(
                            "`{}` already exists; refusing to overwrite an existing workspace contract{}\n{}",
                            compact_workspace_path(&workspace_path),
                            format_next_timeline(&[
                                format!(
                                    "use `{next_detect_merge}` to apply additive workspace updates"
                                ),
                                format!(
                                    "use `{next_detect_rewrite}` to replace the workspace contract"
                                ),
                            ]),
                            ""
                        )
                    }
                    WorkspaceScaffoldSurface::Detect => {
                        format!(
                            "`{}` already exists; `{command_name} --write` only writes first contracts{}\n{}",
                            compact_workspace_path(&workspace_path),
                            format_next_timeline(&[
                                format!(
                                    "use `{command_name} --merge --dry-run {compact_root_display}` to review additive merge changes"
                                ),
                                format!(
                                    "use `{command_name} --merge {compact_root_display}` to apply additive repo entries"
                                ),
                            ]),
                            ""
                        )
                    }
                };
                match format {
                    OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                        &format!("WORKSPACE {command_label}"),
                        &compact_path_display,
                        "Workspace contract already exists",
                        error.trim_end(),
                        &[],
                    )),
                    OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
                        "ok": false,
                        "path": path_display,
                        "written": false,
                        "mode": "scaffold",
                        "error": error.trim_end(),
                        "next": command_for_workspace("ota workspace detect --merge", &workspace_path),
                    }))),
                }
            }
            Ok(draft) if write => {
                let mut draft = draft;
                let mut auto_provision = WorkspaceAutoProvisionResult {
                    provisioned: Vec::new(),
                    skipped: Vec::new(),
                };
                if matches!(surface, WorkspaceScaffoldSurface::Init)
                    && bootstrap
                    && !draft.missing_contract.is_empty()
                {
                    auto_provision = auto_provision_workspace_repo_contracts(
                        &workspace_root,
                        &draft.missing_contract,
                    );
                    if !auto_provision.provisioned.is_empty() {
                        draft = match build_workspace_init_draft(&workspace_root) {
                            Ok(updated) => updated,
                            Err(error) => {
                                return finalize_debug(
                                    match format {
                                        OutputFormat::Text => {
                                            CommandOutput::failure(command_message_failure_text(
                                                &format!("WORKSPACE {command_label}"),
                                                &compact_root_display,
                                                "Workspace contract could not be inferred",
                                                &error,
                                                &[],
                                            ))
                                        }
                                        OutputFormat::Json => {
                                            CommandOutput::failure(to_json_value(json!({
                                                "ok": false,
                                                "path": path_display,
                                                "written": false,
                                                "mode": "scaffold",
                                                "error": error,
                                            })))
                                        }
                                    },
                                    debug,
                                    debug_lines,
                                );
                            }
                        };
                    }
                }

                if draft.included.is_empty() {
                    let error = if matches!(surface, WorkspaceScaffoldSurface::Init) && bootstrap {
                        format!(
                            "workspace init could not bootstrap any repo contracts from `{}`{}",
                            compact_root_display,
                            format_next_timeline(&[
                                String::from("create repo contracts with `ota init <repo-path>`"),
                                String::from(
                                    "or preview repo contracts with `ota detect --dry-run <repo-path>`",
                                ),
                                format!(
                                    "then compare `ota workspace detect --dry-run {compact_root_display}` with `ota workspace init --dry-run {compact_root_display}` before writing a workspace contract"
                                ),
                            ]),
                        )
                    } else if matches!(surface, WorkspaceScaffoldSurface::Init) {
                        format!(
                            "workspace init could not find any repos with `ota.yaml`{}",
                            format_next_timeline(&[
                                String::from(
                                    "run `ota workspace init --bootstrap` to scaffold missing repo contracts",
                                ),
                                String::from(
                                    "or create repo contracts with `ota init <repo-path>`"
                                ),
                                String::from(
                                    "or preview repo contracts with `ota detect --dry-run <repo-path>`",
                                ),
                                format!(
                                    "then compare `ota workspace detect --dry-run {compact_root_display}` with `ota workspace init --dry-run {compact_root_display}` before writing a workspace contract"
                                ),
                            ]),
                        )
                    } else {
                        format!(
                            "workspace init could not bootstrap any repo contracts from `{}`{}",
                            compact_root_display,
                            format_next_timeline(&[
                                String::from("create repo contracts with `ota init <repo-path>`"),
                                String::from(
                                    "or preview repo contracts with `ota detect --dry-run <repo-path>`",
                                ),
                                format!(
                                    "then compare `ota workspace detect --dry-run {compact_root_display}` with `ota workspace init --dry-run {compact_root_display}` before writing a workspace contract"
                                ),
                            ]),
                        )
                    };
                    return finalize_debug(
                        match format {
                            OutputFormat::Text => {
                                CommandOutput::failure(command_message_failure_text(
                                    &format!("WORKSPACE {command_label}"),
                                    &compact_root_display,
                                    "No repo contracts were available",
                                    &error,
                                    &[],
                                ))
                            }
                            OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
                                "ok": false,
                                "path": path_display,
                                "written": false,
                                "mode": "scaffold",
                                "error": error,
                            }))),
                        },
                        debug,
                        debug_lines,
                    );
                }

                let yaml = match serde_yaml::to_string(&draft.contract) {
                    Ok(yaml) => yaml,
                    Err(error) => {
                        let error = format!(
                            "failed to serialize workspace contract for `{}`: {error}",
                            compact_path_display
                        );
                        return finalize_debug(
                            match format {
                                OutputFormat::Text => {
                                    CommandOutput::failure(command_message_failure_text(
                                        &format!("WORKSPACE {command_label}"),
                                        &compact_path_display,
                                        "Workspace contract could not be serialized",
                                        &error,
                                        &[],
                                    ))
                                }
                                OutputFormat::Json => {
                                    CommandOutput::failure(to_json_value(json!({
                                        "ok": false,
                                        "path": path_display,
                                        "written": false,
                                        "mode": "scaffold",
                                        "error": error,
                                    })))
                                }
                            },
                            debug,
                            debug_lines,
                        );
                    }
                };

                if let Err(error) = fs::write(&workspace_path, &yaml) {
                    let error = format!(
                        "failed to write `{}`: {error}",
                        compact_workspace_path(&workspace_path)
                    );
                    return finalize_debug(
                        match format {
                            OutputFormat::Text => {
                                CommandOutput::failure(command_message_failure_text(
                                    &format!("WORKSPACE {command_label}"),
                                    &compact_path_display,
                                    "Workspace contract could not be written",
                                    &error,
                                    &[],
                                ))
                            }
                            OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
                                "ok": false,
                                "path": path_display,
                                "written": false,
                                "mode": "scaffold",
                                "error": error,
                            }))),
                        },
                        debug,
                        debug_lines,
                    );
                }

                match format {
                    OutputFormat::Text => {
                        let mut stdout = format_command_header(
                            &format!("WORKSPACE {command_label} WRITE"),
                            &compact_root_display,
                        );
                        stdout.push_str(&format!(
                            "\n\n{}",
                            format_result_line(&format!(
                                "wrote `{}`",
                                compact_workspace_path(&workspace_path)
                            ))
                        ));
                        stdout.push_str(&format!("\n\n{}", format_mode_line("scaffold")));
                        if bootstrap {
                            render_workspace_auto_provision_sections(
                                &mut stdout,
                                &auto_provision.provisioned,
                                &auto_provision.skipped,
                            );
                        }
                        stdout.push_str(&format_next_timeline(&workspace_scaffold_write_steps(
                            &workspace_path,
                        )));
                        render_workspace_init_discovery_sections(
                            &mut stdout,
                            &draft.included,
                            &draft.missing_contract,
                        );
                        CommandOutput::success(stdout)
                    }
                    OutputFormat::Json => CommandOutput::success(to_json_value(json!({
                        "ok": true,
                        "path": path_display,
                        "written": true,
                        "mode": "scaffold",
                        "config": draft.contract,
                        "provenance": workspace_init_contract_provenance(&draft.contract, &workspace_root),
                        "included": draft.included,
                        "missing_contract": draft.missing_contract,
                    }))),
                }
            }
            Ok(draft) => match format {
                OutputFormat::Text => {
                    let yaml = match serde_yaml::to_string(&draft.contract) {
                        Ok(yaml) => yaml,
                        Err(error) => {
                            return CommandOutput::failure(command_message_failure_text(
                                &format!("WORKSPACE {command_label}"),
                                &compact_path_display,
                                "Workspace contract could not be serialized",
                                &format!(
                                    "failed to serialize workspace contract for `{}`: {error}",
                                    compact_path_display
                                ),
                                &[],
                            ));
                        }
                    };

                    let mut stdout = format_command_header(
                        &format!("WORKSPACE {command_label} PREVIEW"),
                        &compact_root_display,
                    );
                    stdout.push_str(&format!("\n\n{}", format_mode_line("dry-run (no write)")));
                    let write_command = match surface {
                        WorkspaceScaffoldSurface::Init => {
                            if bootstrap {
                                format!("{command_name} --bootstrap {compact_root_display}")
                            } else {
                                format!("{command_name} {compact_root_display}")
                            }
                        }
                        WorkspaceScaffoldSurface::Detect => {
                            format!("{command_name} --write {compact_root_display}")
                        }
                    };
                    let mut next_steps = Vec::new();
                    if !workspace_path.exists() {
                        match surface {
                            WorkspaceScaffoldSurface::Init => next_steps.push(format!(
                                "run `ota workspace detect --dry-run {compact_root_display}` to compare the detector-led workspace draft"
                            )),
                            WorkspaceScaffoldSurface::Detect => next_steps.push(format!(
                                "run `ota workspace init --dry-run {compact_root_display}` to compare the conservative starter path"
                            )),
                        }
                    }
                    next_steps.push(format!(
                        "run `{write_command}` to write `{}`",
                        compact_workspace_path(&workspace_path)
                    ));
                    stdout.push_str(&format_next_timeline(&next_steps));
                    stdout.push_str(&format!("\n\n{}\n", paint_section_title("Contract")));
                    stdout.push_str(&stylize_yaml_preview(yaml.trim_end()));
                    render_workspace_init_discovery_sections(
                        &mut stdout,
                        &draft.included,
                        &draft.missing_contract,
                    );
                    CommandOutput::success(stdout)
                }
                OutputFormat::Json => CommandOutput::success(to_json_value(json!({
                    "ok": true,
                    "path": path_display,
                    "written": false,
                    "mode": "scaffold",
                    "config": draft.contract,
                    "provenance": workspace_init_contract_provenance(&draft.contract, &workspace_root),
                    "included": draft.included,
                    "missing_contract": draft.missing_contract,
                }))),
            },
            Err(error) => match format {
                OutputFormat::Text => CommandOutput::failure(command_message_failure_text(
                    &format!("WORKSPACE {command_label}"),
                    &compact_root_display,
                    "Workspace contract could not be inferred",
                    &error,
                    &[],
                )),
                OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
                    "ok": false,
                    "path": path_display,
                    "written": false,
                    "mode": "scaffold",
                    "error": error,
                }))),
            },
        },
        debug,
        debug_lines,
    )
}

pub fn workspace_tasks(
    path: Option<&Path>,
    file_override: Option<&Path>,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let resolved_path = match resolve_workspace_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => CommandOutput::failure(workspace_target_resolution_text(
                        "WORKSPACE TASKS",
                        "ota workspace tasks",
                        &error.to_string(),
                    )),
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=workspace.tasks")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_workspace_path(&resolved_path);
    let debug_lines = vec![
        String::from("DEBUG command=workspace.tasks"),
        format!("DEBUG workspace_path={path_display}"),
    ];

    finalize_debug(
        match load_workspace_contract(&resolved_path) {
            Ok(workspace) => {
                if let Err(errors) = validate_workspace_contract(&resolved_path, &workspace) {
                    return match format {
                        OutputFormat::Text | OutputFormat::Json => {
                            invalid_workspace_contract_output(
                                "WORKSPACE TASKS",
                                &resolved_path,
                                &errors
                                    .errors()
                                    .iter()
                                    .map(ToString::to_string)
                                    .collect::<Vec<_>>(),
                                workspace_invalid_contract_next_steps(
                                    "ota workspace tasks",
                                    &resolved_path,
                                ),
                                format,
                            )
                        }
                    };
                }

                let repo_refs = match ordered_workspace_repo_refs(&resolved_path, &workspace) {
                    Ok(repo_refs) => repo_refs,
                    Err(errors) => {
                        return match format {
                            OutputFormat::Text | OutputFormat::Json => {
                                invalid_workspace_contract_output(
                                    "WORKSPACE TASKS",
                                    &resolved_path,
                                    &errors
                                        .errors()
                                        .iter()
                                        .map(ToString::to_string)
                                        .collect::<Vec<_>>(),
                                    workspace_invalid_contract_next_steps(
                                        "ota workspace tasks",
                                        &resolved_path,
                                    ),
                                    format,
                                )
                            }
                        };
                    }
                };

                let mut repos = Vec::with_capacity(repo_refs.len());
                for repo in repo_refs {
                    if !repo.present {
                        repos.push(WorkspaceRepoTasksReport {
                            name: repo.name,
                            path: repo.path.display().to_string(),
                            contract_path: repo.contract_path.display().to_string(),
                            workflow: repo.workflow,
                            required: repo.required,
                            acquired: false,
                            depends_on: repo.depends_on,
                            tasks: Vec::new(),
                        });
                        continue;
                    }

                    let contract = match load_contract(&repo.contract_path) {
                        Ok(contract) => contract,
                        Err(error) => {
                            return match format {
                                OutputFormat::Text => {
                                    CommandOutput::failure(workspace_repo_contract_load_text(
                                        "WORKSPACE TASKS",
                                        &resolved_path,
                                        &repo.contract_path,
                                        &error.to_string(),
                                    ))
                                }
                                OutputFormat::Json => {
                                    CommandOutput::failure(to_json(&ValidateFailure {
                                        summary: None,
                                        ok: false,
                                        path: &path_display,
                                        errors: Vec::new(),
                                        error: Some(error.to_string()),
                                        warnings: Vec::new(),
                                        warning_details: Vec::new(),
                                    }))
                                }
                            };
                        }
                    };

                    if let Err(errors) =
                        validate_contract_with_path(&contract, Some(&repo.contract_path))
                    {
                        return match format {
                            OutputFormat::Text => {
                                CommandOutput::failure(workspace_repo_contract_invalid_text(
                                    "WORKSPACE TASKS",
                                    &resolved_path,
                                    &repo.contract_path,
                                    &errors
                                        .errors()
                                        .iter()
                                        .map(ToString::to_string)
                                        .collect::<Vec<_>>(),
                                ))
                            }
                            OutputFormat::Json => {
                                CommandOutput::failure(to_json(&ValidateFailure {
                                    summary: None,
                                    ok: false,
                                    path: &path_display,
                                    errors: errors
                                        .errors()
                                        .iter()
                                        .map(ToString::to_string)
                                        .collect(),
                                    error: None,
                                    warnings: Vec::new(),
                                    warning_details: Vec::new(),
                                }))
                            }
                        };
                    }

                    let visible_task_names = contract
                        .tasks
                        .iter()
                        .filter(|(_, task)| !task.internal)
                        .map(|(name, _)| name.as_str())
                        .collect::<BTreeSet<_>>();
                    let summarize_workspace_task =
                        |workspace_name: String, repo_task: Option<String>, task: &TaskSpec| {
                            let execution = task.resolved_execution(current_os()).expect(
                                "validated task must resolve to a default or variant execution",
                            );
                            let filter_relationships = |relationships: &[String]| {
                                relationships
                                    .iter()
                                    .filter(|dependency| {
                                        visible_task_names.contains(dependency.as_str())
                                    })
                                    .cloned()
                                    .collect::<Vec<_>>()
                            };
                            WorkspaceTaskSummary {
                                name: workspace_name,
                                kind: execution.kind.to_string(),
                                repo_task,
                                description: task.description.clone(),
                                run: (execution.kind == "run")
                                    .then(|| execution.shell_body().map(str::to_string))
                                    .flatten(),
                                script: (execution.kind == "script")
                                    .then(|| execution.shell_body().map(str::to_string))
                                    .flatten(),
                                launch: crate::output::summarize_task_launch_owned(
                                    execution.launch(),
                                ),
                                action: crate::output::summarize_task_action_owned(
                                    execution.action(),
                                ),
                                prepare: crate::output::summarize_task_prepare_owned(
                                    execution.prepare(),
                                ),
                                aggregate: crate::output::summarize_task_aggregate(
                                    execution.aggregate(),
                                ),
                                effects: crate::output::TaskEffectsSummary::from_spec(
                                    &task.effects,
                                ),
                                depends_on: filter_relationships(&task.depends_on),
                                requires_services: task.requires_services.clone(),
                                requires_artifacts: task.requires_artifacts.clone(),
                                after_success: filter_relationships(&task.after_success),
                                after_failure: filter_relationships(&task.after_failure),
                                after_always: filter_relationships(&task.after_always),
                            }
                        };
                    let mut tasks = contract
                        .tasks
                        .iter()
                        .filter(|(_, task)| !task.internal)
                        .map(|(name, task)| summarize_workspace_task(name.clone(), None, task))
                        .collect::<Vec<_>>();

                    for (workspace_task, repo_task) in &repo.task_bindings {
                        if tasks.iter().any(|task| task.name == *workspace_task) {
                            continue;
                        }
                        let Some(task) = contract.tasks.get(repo_task) else {
                            continue;
                        };
                        if task.internal {
                            continue;
                        }
                        tasks.push(summarize_workspace_task(
                            workspace_task.clone(),
                            Some(repo_task.clone()),
                            task,
                        ));
                    }
                    tasks.sort_by(|left, right| left.name.cmp(&right.name));

                    repos.push(WorkspaceRepoTasksReport {
                        name: repo.name,
                        path: repo.path.display().to_string(),
                        contract_path: repo.contract_path.display().to_string(),
                        workflow: repo.workflow,
                        required: repo.required,
                        acquired: true,
                        depends_on: repo.depends_on,
                        tasks,
                    });
                }

                match format {
                    OutputFormat::Text => {
                        render_workspace_tasks_text(&compact_path_display, &repos)
                    }
                    OutputFormat::Json => CommandOutput::success(to_json(&WorkspaceTasksSuccess {
                        ok: true,
                        path: &path_display,
                        summary: workspace_tasks_summary(&repos),
                        repos: &repos,
                    })),
                }
            }
            Err(error) => match format {
                OutputFormat::Text => CommandOutput::failure(workspace_contract_load_text(
                    "WORKSPACE TASKS",
                    &resolved_path,
                    "Workspace contract could not be loaded",
                    &error.to_string(),
                    &workspace_contract_load_next_steps("ota workspace tasks", &resolved_path),
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    summary: None,
                    ok: false,
                    path: &path_display,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

pub fn workspace_list(
    path: Option<&Path>,
    file_override: Option<&Path>,
    status_filter: Option<WorkspaceDoctorStatusFilter>,
    repo_filter: Option<&str>,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let resolved_path = match resolve_workspace_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => CommandOutput::failure(workspace_target_resolution_text(
                        "WORKSPACE LIST",
                        "ota workspace list",
                        &error.to_string(),
                    )),
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=workspace.list")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_workspace_path(&resolved_path);
    let debug_lines = vec![
        String::from("DEBUG command=workspace.list"),
        format!("DEBUG workspace_path={path_display}"),
        format!("DEBUG filter_repo={}", repo_filter.unwrap_or("-")),
    ];

    finalize_debug(
        match load_workspace_contract(&resolved_path) {
            Ok(workspace) => {
                let repo_refs = match ordered_workspace_repo_refs(&resolved_path, &workspace) {
                    Ok(repo_refs) => repo_refs,
                    Err(errors) => {
                        return match format {
                            OutputFormat::Text | OutputFormat::Json => {
                                invalid_workspace_contract_output(
                                    "WORKSPACE LIST",
                                    &resolved_path,
                                    &errors
                                        .errors()
                                        .iter()
                                        .map(ToString::to_string)
                                        .collect::<Vec<_>>(),
                                    workspace_invalid_contract_next_steps(
                                        "ota workspace list",
                                        &resolved_path,
                                    ),
                                    format,
                                )
                            }
                        };
                    }
                };

                if let Some(target_repo) = repo_filter {
                    let known_repos = repo_refs
                        .iter()
                        .map(|repo| repo.name.as_str())
                        .collect::<Vec<_>>();
                    if !known_repos.contains(&target_repo) {
                        let known_list = if known_repos.is_empty() {
                            String::from("none")
                        } else {
                            known_repos.join(", ")
                        };
                        let error = format!(
                            "{}  {}\n{} {}\n{} unknown workspace repo `{target_repo}`\nKnown repos: {known_list}\n{} ensure repo name is correct and matches one of `Known repos`",
                            render_severity(FindingSeverity::Error),
                            paint("Workspace list filter failed", "1;37"),
                            paint_key("Where:"),
                            paint_code(&compact_path_display),
                            error_key("Why:"),
                            error_next_key("Next:")
                        );
                        return match format {
                            OutputFormat::Text => CommandOutput::failure(error),
                            OutputFormat::Json => {
                                CommandOutput::failure(to_json(&ValidateFailure {
                                    summary: None,
                                    ok: false,
                                    path: &path_display,
                                    errors: Vec::new(),
                                    error: Some(error),
                                    warnings: Vec::new(),
                                    warning_details: Vec::new(),
                                }))
                            }
                        };
                    }
                }

                let repos = repo_refs
                    .into_iter()
                    .filter(|repo| match repo_filter {
                        Some(target) => repo.name == target,
                        None => true,
                    })
                    .filter_map(|repo| {
                        let (status, execution) = if !repo.present {
                            (String::from("NOT READY"), None)
                        } else if !repo.contract_path.is_file() {
                            (String::from("MISSING CONTRACT"), None)
                        } else {
                            match load_contract(&repo.contract_path) {
                                Ok(contract) => {
                                    if validate_contract_with_path(
                                        &contract,
                                        Some(&repo.contract_path),
                                    )
                                    .is_err()
                                    {
                                        (String::from("INVALID CONTRACT"), None)
                                    } else if let Some(workflow_name) = repo.workflow.as_deref() {
                                        if !selected_workflow_selector_is_valid(
                                            &contract,
                                            workflow_name,
                                        ) {
                                            (
                                                String::from("INVALID WORKFLOW"),
                                                WorkspaceExecutionSummary::from_contract_with_policy(
                                                    &contract,
                                                    &repo.contract_path,
                                                    Some(&repo.policy_env),
                                                ),
                                            )
                                        } else {
                                            let ready =
                                                diagnose_contract_with_mode_and_lifecycle_for_workflow(
                                                    &contract,
                                                    &repo.contract_path,
                                                    DoctorMode::Native,
                                                    None,
                                                    repo.workflow.as_deref(),
                                                )
                                                .ok;
                                            (
                                                if ready {
                                                    String::from("READY")
                                                } else {
                                                    String::from("NOT READY")
                                                },
                                                WorkspaceExecutionSummary::from_contract_with_policy(
                                                    &contract,
                                                    &repo.contract_path,
                                                    Some(&repo.policy_env),
                                                ),
                                            )
                                        }
                                    } else {
                                        let ready = diagnose_preconditions(&contract, &repo.contract_path).ok;
                                        (
                                            if ready {
                                                String::from("READY")
                                            } else {
                                                String::from("NOT READY")
                                            },
                                            WorkspaceExecutionSummary::from_contract_with_policy(
                                                &contract,
                                                &repo.contract_path,
                                                Some(&repo.policy_env),
                                            ),
                                        )
                                    }
                                }
                                Err(_) => (String::from("UNREADABLE CONTRACT"), None),
                            }
                        };

                        match status_filter {
                            Some(WorkspaceDoctorStatusFilter::Ready) if status != "READY" => {
                                return None;
                            }
                            Some(WorkspaceDoctorStatusFilter::NotReady) if status == "READY" => {
                                return None;
                            }
                            _ => {}
                        }

                        Some(WorkspaceRepoListReport {
                            status,
                            name: repo.name,
                            path: repo.path.display().to_string(),
                            contract_path: repo.contract_path.display().to_string(),
                            workflow: repo.workflow,
                            contract_present: repo.contract_path.is_file(),
                            required: repo.required,
                            acquired: repo.present,
                            depends_on: repo.depends_on,
                            execution,
                        })
                    })
                    .collect::<Vec<_>>();

                match format {
                    OutputFormat::Text => render_workspace_list_text(&compact_path_display, &repos),
                    OutputFormat::Json => CommandOutput::success(to_json(&WorkspaceListSuccess {
                        ok: true,
                        path: &path_display,
                        summary: workspace_list_summary(&repos),
                        repos: &repos,
                    })),
                }
            }
            Err(error) => match format {
                OutputFormat::Text => CommandOutput::failure(workspace_contract_load_text(
                    "WORKSPACE LIST",
                    &resolved_path,
                    "Workspace contract could not be loaded",
                    &error.to_string(),
                    &workspace_contract_load_next_steps("ota workspace list", &resolved_path),
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    summary: None,
                    ok: false,
                    path: &path_display,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

pub fn workspace_execution_plan(
    path: Option<&Path>,
    file_override: Option<&Path>,
    repo_filter: Option<&str>,
    overrides: ExecutionOverrides,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    let resolved_path = match resolve_workspace_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => CommandOutput::failure(workspace_target_resolution_text(
                        "WORKSPACE EXECUTION PLAN",
                        "ota workspace execution plan",
                        &error.to_string(),
                    )),
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=workspace.execution.plan")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_workspace_path(&resolved_path);
    let debug_lines = vec![
        String::from("DEBUG command=workspace.execution.plan"),
        format!("DEBUG workspace_path={path_display}"),
        format!("DEBUG filter_repo={}", repo_filter.unwrap_or("-")),
        format!(
            "DEBUG override_backend={}",
            overrides.backend.map(format_backend).unwrap_or("default")
        ),
        format!(
            "DEBUG override_lifecycle={}",
            overrides
                .lifecycle
                .map(format_lifecycle)
                .unwrap_or("default")
        ),
    ];

    finalize_debug(
        match load_workspace_contract(&resolved_path) {
            Ok(workspace) => {
                let repo_refs = match ordered_workspace_repo_refs(&resolved_path, &workspace) {
                    Ok(repo_refs) => repo_refs,
                    Err(errors) => {
                        return match format {
                            OutputFormat::Text | OutputFormat::Json => {
                                invalid_workspace_contract_output(
                                    "WORKSPACE EXECUTION PLAN",
                                    &resolved_path,
                                    &errors
                                        .errors()
                                        .iter()
                                        .map(ToString::to_string)
                                        .collect::<Vec<_>>(),
                                    workspace_invalid_contract_next_steps(
                                        "ota workspace execution plan",
                                        &resolved_path,
                                    ),
                                    format,
                                )
                            }
                        };
                    }
                };

                if let Some(target_repo) = repo_filter {
                    let known_repos = repo_refs
                        .iter()
                        .map(|repo| repo.name.as_str())
                        .collect::<Vec<_>>();
                    if !known_repos.contains(&target_repo) {
                        let known_list = if known_repos.is_empty() {
                            String::from("none")
                        } else {
                            known_repos.join(", ")
                        };
                        let error = format!(
                            "unknown workspace repo `{target_repo}`; known repos: {known_list}"
                        );
                        let text_error = format!(
                            "{}  {}\n{} {}\n{} unknown workspace repo `{target_repo}`\nKnown repos: {known_list}\n{} ensure repo name is correct and matches one of `Known repos`",
                            render_severity(FindingSeverity::Error),
                            paint("Workspace execution filter failed", "1;37"),
                            paint_key("Where:"),
                            paint_code(&compact_path_display),
                            error_key("Why:"),
                            error_next_key("Next:")
                        );
                        return match format {
                            OutputFormat::Text => CommandOutput::failure(text_error),
                            OutputFormat::Json => {
                                CommandOutput::failure(to_json(&ValidateFailure {
                                    summary: None,
                                    ok: false,
                                    path: &path_display,
                                    errors: Vec::new(),
                                    error: Some(error),
                                    warnings: Vec::new(),
                                    warning_details: Vec::new(),
                                }))
                            }
                        };
                    }
                }

                let repos = repo_refs
                    .into_iter()
                    .filter(|repo| match repo_filter {
                        Some(target) => repo.name == target,
                        None => true,
                    })
                    .map(|repo| run_workspace_repo_execution_plan(repo, overrides, &resolved_path))
                    .collect::<Vec<_>>();

                render_workspace_execution_plan(
                    &compact_path_display,
                    &WorkspaceExecutionPlanReport { repos },
                    format,
                    execution_plan_overrides(overrides),
                )
            }
            Err(error) => match format {
                OutputFormat::Text => CommandOutput::failure(workspace_contract_load_text(
                    "WORKSPACE EXECUTION PLAN",
                    &resolved_path,
                    "Workspace contract could not be loaded",
                    &error.to_string(),
                    &workspace_contract_load_next_steps(
                        "ota workspace execution plan",
                        &resolved_path,
                    ),
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    summary: None,
                    ok: false,
                    path: &path_display,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

pub fn workspace_doctor(
    path: Option<&Path>,
    file_override: Option<&Path>,
    jobs: usize,
    stream: bool,
    progress_json: bool,
    filters: WorkspaceDoctorFilters,
    format: OutputFormat,
    debug: bool,
) -> CommandOutput {
    if jobs == 0 {
        return finalize_debug(
            CommandOutput::failure_with_code(String::from("`--jobs` must be greater than zero"), 2),
            debug,
            vec![
                String::from("DEBUG command=workspace.doctor"),
                String::from("DEBUG jobs=0"),
            ],
        );
    }

    let resolved_path = match resolve_workspace_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => CommandOutput::failure(workspace_target_resolution_text(
                        "WORKSPACE DOCTOR",
                        "ota workspace doctor",
                        &error.to_string(),
                    )),
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=workspace.doctor")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_workspace_path(&resolved_path);
    let debug_lines = vec![
        String::from("DEBUG command=workspace.doctor"),
        format!("DEBUG workspace_path={path_display}"),
        format!("DEBUG jobs={jobs}"),
        format!("DEBUG stream={stream}"),
        format!("DEBUG progress_json={progress_json}"),
        format!("DEBUG filter_status={:?}", filters.status),
        format!("DEBUG filter_severity={:?}", filters.severity),
        format!(
            "DEBUG filter_repo={}",
            filters.repo.as_deref().unwrap_or("-")
        ),
    ];

    if stream && matches!(format, OutputFormat::Json) {
        return finalize_debug(
            CommandOutput::failure_with_code(
                String::from("`--stream` is only supported for text output"),
                2,
            ),
            debug,
            debug_lines,
        );
    }

    let progress_mode = workspace_progress_mode(format, stream, progress_json);

    finalize_debug(
        match if stream || progress_mode.is_some() {
            load_and_diagnose_workspace_streaming(&resolved_path, jobs, progress_mode)
        } else {
            load_and_diagnose_workspace(&resolved_path, jobs)
        } {
            Ok(report) => {
                if let Some(target_repo) = filters.repo.as_deref() {
                    let known_repos = report
                        .repos
                        .iter()
                        .map(|repo| repo.name.as_str())
                        .collect::<Vec<_>>();
                    if !known_repos.contains(&target_repo) {
                        let known_list = if known_repos.is_empty() {
                            String::from("none")
                        } else {
                            known_repos.join(", ")
                        };
                        let error = format!(
                            "{}  {}\n{} {}\n{} unknown workspace repo `{target_repo}`\nKnown repos: {known_list}\n{} use `{}` to see known repos",
                            render_severity(FindingSeverity::Error),
                            paint("Workspace doctor filter failed", "1;37"),
                            paint_key("Where:"),
                            paint_code(&compact_path_display),
                            error_key("Why:"),
                            error_next_key("Next:"),
                            paint_code("ota workspace list")
                        );
                        return match format {
                            OutputFormat::Text => CommandOutput::failure(error),
                            OutputFormat::Json => {
                                CommandOutput::failure(to_json(&ValidateFailure {
                                    summary: None,
                                    ok: false,
                                    path: &path_display,
                                    errors: Vec::new(),
                                    error: Some(error),
                                    warnings: Vec::new(),
                                    warning_details: Vec::new(),
                                }))
                            }
                        };
                    }
                }

                let report = apply_workspace_doctor_filters(report, &filters);
                match format {
                    OutputFormat::Text => {
                        render_workspace_doctor_text(&compact_path_display, &report)
                    }
                    OutputFormat::Json => CommandOutput {
                        stdout: to_json(&WorkspaceDoctorSuccess {
                            ok: report.ok,
                            path: &path_display,
                            summary: workspace_doctor_summary(&report),
                            finding_groups: doctor_finding_group_summaries(
                                report.repos.iter().flat_map(|repo| repo.findings.iter()),
                                None,
                                None,
                            ),
                            repos: &report.repos,
                        }),
                        stderr: None,
                        exit_code: if report.ok { 0 } else { 1 },
                    },
                }
            }
            Err(WorkspaceProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_workspace_contract_output(
                    "WORKSPACE DOCTOR",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    workspace_invalid_contract_next_steps("ota workspace doctor", &resolved_path),
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    summary: None,
                    ok: false,
                    path: &path_display,
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                })),
            },
            Err(WorkspaceProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(workspace_contract_load_text(
                    "WORKSPACE DOCTOR",
                    &resolved_path,
                    "Workspace contract could not be loaded",
                    &error.to_string(),
                    &workspace_contract_load_next_steps("ota workspace doctor", &resolved_path),
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    summary: None,
                    ok: false,
                    path: &path_display,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

