pub fn workspace_refresh(
    path: Option<&Path>,
    file_override: Option<&Path>,
    jobs: usize,
    dry_run: bool,
    force: bool,
    prune: bool,
    git_ref: Option<&str>,
    quiet: bool,
    stream: bool,
    progress_json: bool,
    format: OutputFormat,
    debug: bool,
    show_receipt: bool,
) -> CommandOutput {
    if jobs == 0 {
        return finalize_debug(
            CommandOutput::failure_with_code(String::from("`--jobs` must be greater than zero"), 2),
            debug,
            vec![
                String::from("DEBUG command=workspace.refresh"),
                String::from("DEBUG jobs=0"),
            ],
        );
    }
    if stream && matches!(format, OutputFormat::Json) {
        return finalize_debug(
            CommandOutput::failure_with_code(
                String::from("`--stream` is only supported for text output"),
                2,
            ),
            debug,
            vec![
                String::from("DEBUG command=workspace.refresh"),
                String::from("DEBUG stream=true"),
            ],
        );
    }
    if stream && jobs != 1 {
        return finalize_debug(
            CommandOutput::failure_with_code(
                String::from("`--stream` currently requires `--jobs 1`"),
                2,
            ),
            debug,
            vec![
                String::from("DEBUG command=workspace.refresh"),
                format!("DEBUG jobs={jobs}"),
                String::from("DEBUG stream=true"),
            ],
        );
    }

    let resolved_path = match resolve_workspace_path(path, file_override) {
        Ok(path) => path,
        Err(error) => {
            return finalize_debug(
                match format {
                    OutputFormat::Text => CommandOutput::failure(workspace_target_resolution_text(
                        "WORKSPACE REFRESH",
                        "ota workspace refresh",
                        &error.to_string(),
                    )),
                    OutputFormat::Json => CommandOutput::failure(error.to_string()),
                },
                debug,
                vec![String::from("DEBUG command=workspace.refresh")],
            );
        }
    };
    let path_display = resolved_path.display().to_string();
    let compact_path_display = compact_workspace_path(&resolved_path);
    let debug_lines = vec![
        String::from("DEBUG command=workspace.refresh"),
        format!("DEBUG workspace_path={path_display}"),
        format!("DEBUG jobs={jobs}"),
        format!("DEBUG dry_run={dry_run}"),
        format!("DEBUG force={force}"),
        format!("DEBUG prune={prune}"),
        format!("DEBUG git_ref={:?}", git_ref),
        format!("DEBUG quiet={quiet}"),
        format!("DEBUG stream={stream}"),
        format!("DEBUG progress_json={progress_json}"),
    ];

    finalize_debug(
        match load_and_run_workspace_refresh(
            &resolved_path,
            jobs,
            WorkspaceRefreshOptions {
                dry_run,
                force,
                prune,
                git_ref: git_ref.map(str::to_owned),
            },
            workspace_progress_mode(format, !quiet, progress_json),
            stream,
        ) {
            Ok(report) => {
                render_workspace_refresh(&compact_path_display, &report, format, show_receipt)
            }
            Err(WorkspaceProblem::Validation(errors)) => match format {
                OutputFormat::Text => invalid_workspace_contract_output(
                    "WORKSPACE REFRESH",
                    &resolved_path,
                    &errors
                        .errors()
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>(),
                    workspace_invalid_contract_next_steps("ota workspace refresh", &resolved_path),
                    format,
                ),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    summary: None,
                    ok: false,
                    path: &path_display,
                    errors: errors.errors().iter().map(ToString::to_string).collect(),
                    error: None,
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                })),
            },
            Err(WorkspaceProblem::Load(error)) => match format {
                OutputFormat::Text => CommandOutput::failure(workspace_contract_load_text(
                    "WORKSPACE REFRESH",
                    &resolved_path,
                    "Workspace contract could not be loaded",
                    &error.to_string(),
                    &workspace_contract_load_next_steps("ota workspace refresh", &resolved_path),
                )),
                OutputFormat::Json => CommandOutput::failure(to_json(&ValidateFailure {
                    summary: None,
                    ok: false,
                    path: &path_display,
                    errors: Vec::new(),
                    error: Some(error.to_string()),
                    warnings: Vec::new(),
                    warning_details: Vec::new(),
                })),
            },
        },
        debug,
        debug_lines,
    )
}

