fn render_tool_bootstrap_prepare_text(
    source_kind: Option<&str>,
    cwd: Option<&str>,
    manager: Option<&str>,
    filter: Option<&str>,
    mode: Option<&str>,
    with_deps: bool,
    browsers: &[&str],
) -> String {
    match source_kind {
        Some("pip") => format!(
            "bootstrap tool `{}` with `python -m pip install --disable-pip-version-check -q {}`",
            mode.unwrap_or("tool"),
            mode.unwrap_or("tool")
        ),
        Some("node_package_manager") => {
            let cwd = cwd.unwrap_or(".");
            let manager = manager.unwrap_or("package manager");
            let browser_suffix = if browsers.is_empty() {
                String::new()
            } else {
                format!(" {}", browsers.join(" "))
            };
            let deps = if with_deps { " --with-deps" } else { "" };
            let command = match (manager, mode.unwrap_or("tool")) {
                ("npm", "playwright_browsers") => {
                    format!("npx playwright install{deps}{browser_suffix}")
                }
                ("npm", "cypress_browsers") => String::from("npx cypress install"),
                ("pnpm", "playwright_browsers") => {
                    match filter.filter(|value| !value.trim().is_empty()) {
                        Some(filter) => {
                            format!(
                                "pnpm --filter {filter} exec playwright install{deps}{browser_suffix}"
                            )
                        }
                        None => format!("pnpm exec playwright install{deps}{browser_suffix}"),
                    }
                }
                ("pnpm", "cypress_browsers") => String::from("pnpm cypress install"),
                ("yarn", "playwright_browsers") => {
                    format!("yarn playwright install{deps}{browser_suffix}")
                }
                ("yarn", "cypress_browsers") => String::from("yarn cypress install"),
                ("bun", "playwright_browsers") => {
                    format!("bunx playwright install{deps}{browser_suffix}")
                }
                ("bun", "cypress_browsers") => String::from("bunx cypress install"),
                _ => return String::from("-"),
            };
            format!(
                "bootstrap tool `{}` with `{command}` in `{cwd}`",
                mode.unwrap_or("tool")
            )
        }
        Some("poetry") => {
            let cwd = cwd.unwrap_or(".");
            let browser_suffix = if browsers.is_empty() {
                String::new()
            } else {
                format!(" {}", browsers.join(" "))
            };
            let deps = if with_deps { " --with-deps" } else { "" };
            let command = match mode.unwrap_or("tool") {
                "playwright_browsers" => {
                    format!("poetry run playwright install{deps}{browser_suffix}")
                }
                _ => return String::from("-"),
            };
            format!(
                "bootstrap tool `{}` with `{command}` in `{cwd}`",
                mode.unwrap_or("tool")
            )
        }
        _ => String::from("-"),
    }
}

fn render_dependency_hydration_prepare_text<T: AsRef<str>>(
    medium: Option<&str>,
    source_kind: Option<&str>,
    cwd: Option<&str>,
    file: Option<&str>,
    manager: Option<&str>,
    mode: Option<&str>,
    group_mode: Option<&str>,
    groups: &[T],
    frozen_lockfile: bool,
    inline_builds: bool,
    force: bool,
    no_root: bool,
    skip_tests: bool,
    targets: &[T],
    compose: Option<(&str, &str, &str, Option<&str>, bool, bool, bool)>,
) -> String {
    let medium = medium.unwrap_or("dependencies").replace('_', " ");
    let base = match source_kind {
        Some("docker_compose") => {
            let source = match (cwd, file) {
                (Some(cwd), Some(file)) => format!("docker compose `{cwd}/{file}`"),
                (None, Some(file)) => format!("docker compose `{file}`"),
                _ => String::from("docker compose"),
            };
            if targets.is_empty() {
                format!("hydrate {medium} from {source}")
            } else {
                format!(
                    "hydrate {medium} from {source} for {}",
                    targets
                        .iter()
                        .map(AsRef::as_ref)
                        .collect::<Vec<_>>()
                        .join(", ")
                )
            }
        }
        Some("node_package_manager") => {
            let cwd = cwd.unwrap_or(".");
            let manager = manager.unwrap_or("package manager");
            let mode = mode.unwrap_or("install");
            let mut command = format!("{manager} {mode}");
            if frozen_lockfile {
                command.push(' ');
                command.push_str(match manager {
                    "yarn" => "--immutable",
                    _ => "--frozen-lockfile",
                });
            }
            if inline_builds {
                command.push_str(" --inline-builds");
            }
            if force {
                command.push_str(" --force");
            }
            format!("hydrate {medium} with `{command}` in `{cwd}`")
        }
        Some("bundler") => {
            let cwd = cwd.unwrap_or(".");
            match file {
                Some(file) => {
                    format!("hydrate {medium} with `bundle install` in `{cwd}` using `{file}`")
                }
                None => format!("hydrate {medium} with `bundle install` in `{cwd}`"),
            }
        }
        Some("uv") => {
            let cwd = cwd.unwrap_or(".");
            let command = match mode.unwrap_or("sync") {
                "pip_requirements" => {
                    format!("uv pip install -r {}", file.unwrap_or("requirements.txt"))
                }
                _ => String::from("uv sync"),
            };
            format!("hydrate {medium} with `{command}` in `{cwd}`")
        }
        Some("poetry") => {
            let cwd = cwd.unwrap_or(".");
            let mut command = String::from("poetry install");
            if let Some(group_mode) = group_mode {
                let values = groups
                    .iter()
                    .map(AsRef::as_ref)
                    .collect::<Vec<_>>()
                    .join(",");
                if !values.is_empty() {
                    command.push_str(&format!(" --{group_mode} {values}"));
                }
            }
            if no_root {
                command.push_str(" --no-root");
            }
            format!("hydrate {medium} with `{command}` in `{cwd}`")
        }
        Some("go_modules") => {
            let cwd = cwd.unwrap_or(".");
            format!("hydrate {medium} with `go mod download` in `{cwd}`")
        }
        Some("maven") => {
            let cwd = cwd.unwrap_or(".");
            let manager = manager.unwrap_or("mvn");
            let goal = mode.unwrap_or("dependency:resolve");
            let command = if skip_tests {
                format!("{manager} -q -DskipTests {goal}")
            } else {
                format!("{manager} -q {goal}")
            };
            format!("hydrate {medium} with `{command}` in `{cwd}`")
        }
        Some("gradle") => {
            let cwd = cwd.unwrap_or(".");
            let manager = manager.unwrap_or("gradle");
            format!("hydrate {medium} with `{manager} dependencies` in `{cwd}`")
        }
        Some("cargo") => {
            let cwd = cwd.unwrap_or(".");
            format!("hydrate {medium} with `cargo fetch` in `{cwd}`")
        }
        Some("dotnet_restore") => {
            let cwd = cwd.unwrap_or(".");
            format!("hydrate {medium} with `dotnet restore` in `{cwd}`")
        }
        Some(other) => format!("hydrate {medium} from {}", other.replace('_', " ")),
        None => format!("hydrate {medium} from declared source"),
    };

    if let Some((engine, kind, service, workdir, rm, detach, tty)) = compose {
        let mut suffix = format!(" via {engine} compose {kind}");
        if detach {
            suffix.push_str(" -d");
        }
        if !tty {
            suffix.push_str(" -T");
        }
        if rm {
            suffix.push_str(" --rm");
        }
        if let Some(workdir) = workdir.filter(|workdir| !workdir.trim().is_empty()) {
            suffix.push_str(" -w ");
            suffix.push_str(workdir);
        }
        suffix.push(' ');
        suffix.push_str(service);
        format!("{base}{suffix}")
    } else {
        base
    }
}

fn render_task_mode_branches_filtered(
    task: &TaskSummary<'_>,
    include_default_mode: bool,
) -> String {
    let default_mode = render_task_default_mode(task);
    let branches = task
        .modes
        .iter()
        .filter(|mode| include_default_mode || mode.mode != default_mode)
        .collect::<Vec<_>>();

    if branches.is_empty() {
        return String::from("-");
    }

    branches
        .into_iter()
        .map(|mode| {
            let mut details = Vec::new();
            if let Some(context) = mode.context {
                details.push(format!("context={context}"));
            }
            if let Some(lifecycle) = mode.lifecycle {
                details.push(format!("lifecycle={lifecycle}"));
            }
            if let Some(kind) = mode.kind {
                details.push(format!("kind={kind}"));
            }
            if mode.has_runtime {
                details.push(String::from("runtime=yes"));
            }
            if details.is_empty() {
                mode.mode.to_string()
            } else {
                format!("{} ({})", mode.mode, details.join(", "))
            }
        })
        .collect::<Vec<_>>()
        .join("; ")
}

fn render_tasks_use_text(path: &str, tasks: &[TaskSummary<'_>]) -> String {
    let mut output = format_command_header("TASKS", path);
    output.push('\n');
    if tasks.is_empty() {
        output.push_str(&format!("\n{} none", info_bullet()));
        return output;
    }

    for task in tasks {
        let command_preview = render_task_command_preview(task);
        let mode_branches = render_task_mode_branches_filtered(task, false);
        let effects = render_task_effects_text(&task.effects);
        let safety_posture = render_task_safety_posture_text(task);
        output.push_str(&format!("\n\n{} {}", info_bullet(), paint(task.name, "1")));
        push_rendered_field(&mut output, "Context:", task.context.map(str::to_string));
        if let Some(description) = task.description {
            output.push_str(&format!("\n  {} {description}", paint_key("Description:")));
        }
        push_task_run_fields(&mut output, task);
        push_rendered_field(
            &mut output,
            "Preview:",
            render_non_placeholder(&command_preview),
        );
        output.push_str(&format!("\n  {} {}", paint_key("Kind:"), task.kind));
        if task.launch.is_some() {
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Launch:"),
                render_task_summary_launch_text(task)
            ));
        }
        if let Some(prepare) = task.prepare.as_ref() {
            output.push_str(&format!(
                "\n  {} {}",
                paint_key("Prepare:"),
                render_task_prepare_text(prepare)
            ));
        }
        push_rendered_field(
            &mut output,
            "Mode Branches:",
            render_non_placeholder(&mode_branches),
        );
        push_rendered_field(&mut output, "Safety Posture:", Some(safety_posture));
        push_rendered_field(
            &mut output,
            "Closure Blockers:",
            render_joined_or_none(&task.unsafe_closure_tasks),
        );
        push_rendered_field(&mut output, "Effects:", render_non_placeholder(&effects));
        if task.internal {
            output.push_str(&format!("\n  {} internal", paint_key("Visibility:")));
        }
        if !task.inputs.is_empty() {
            output.push_str(&format!("\n  {}", paint_key("Inputs")));
            output.push_str(&render_task_inputs_compact(&task.inputs));
        }
        output.push_str(&format!(
            "\n  {} `{}`",
            paint_key("Dry Run JSON:"),
            paint_code(&format!("ota run {} --dry-run --json", task.name))
        ));
    }
    output.push_str(&format!(
        "\n\n  {} `{}`",
        paint_key("Receipt After Run:"),
        paint_code("ota receipt --json --archive")
    ));
    output
}

fn render_workflow_summary_text(workflow: &WorkflowSummary<'_>, default: Option<bool>) -> String {
    let mut output = format!("{} {}", list_bullet(), paint(workflow.name, "1"));
    let workflow_selector = workflow_selector_from_summary(workflow);
    if let Some(intent) = workflow.intent
        && !intent.trim().is_empty()
    {
        output.push_str(&format!("\n  {} {}", paint_key("Intent:"), intent));
    }
    if let Some(instance) = workflow.instance.as_deref() {
        output.push_str(&format!("\n  {} {}", paint_key("Instance:"), instance));
    }
    if let Some(description) = workflow.description
        && !description.trim().is_empty()
    {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Description:"),
            description
        ));
    }
    push_lane_use_fields(&mut output, &workflow.usage);
    output.push_str(&format!(
        "\n  {} `{}`",
        paint_key("Proof:"),
        paint_code(&format!(
            "ota proof runtime --workflow {}",
            workflow_selector
        ))
    ));
    if let Some(prepare_task) = workflow.prepare_task {
        output.push_str(&format!(
            "\n  {} `{}`",
            paint_key("Prepare:"),
            paint_code(&format!("ota run {prepare_task}"))
        ));
    } else if let Some(prepare_action) = workflow.prepare_action.as_ref() {
        output.push_str(&format!(
            "\n  {} `{}`",
            paint_key("Prepare:"),
            paint_code(&format!(
                "workflow action {}",
                render_workflow_prepare_action_preview(prepare_action)
            ))
        ));
    }
    if let Some(setup_task) = workflow.setup_task {
        output.push_str(&format!(
            "\n  {} `{}`",
            paint_key("Setup:"),
            paint_code(&format!("ota run {setup_task}"))
        ));
    }
    if let Some(run_task) = workflow.run_task {
        output.push_str(&format!(
            "\n  {} `{}`",
            paint_key("Run:"),
            paint_code(&format!("ota run {run_task}"))
        ));
    }
    if let Some(attach_task) = workflow.attach_task {
        output.push_str(&format!(
            "\n  {} `{}`",
            paint_key("Attach:"),
            paint_code(&format!("ota run {attach_task}"))
        ));
    }
    if let Some(launch) = workflow.run_task_launch.as_ref() {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Run Launch:"),
            render_task_launch_text(launch)
        ));
    }
    if let Some(declared_safe) = workflow.declared_safe_for_agent {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Safe For Agent:"),
            if declared_safe { "true" } else { "false" }
        ));
    }
    if let Some(effective_safe) = workflow.effective_safe_for_agent {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Effective Safe For Agent:"),
            if effective_safe { "true" } else { "false" }
        ));
    }
    if let Some(safety_posture) = render_workflow_safety_posture_text(workflow) {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Safety Posture:"),
            safety_posture
        ));
    }
    push_rendered_field(
        &mut output,
        "Closure Blockers:",
        render_joined_or_none(&workflow.unsafe_closure_tasks),
    );
    push_rendered_field(
        &mut output,
        "Services:",
        render_joined_or_none(&workflow.required_services),
    );
    push_rendered_field(
        &mut output,
        "Readiness Checks:",
        render_joined_or_none(&workflow.readiness_checks),
    );
    push_rendered_field(
        &mut output,
        "Readiness Probes:",
        render_joined_or_none(&workflow.readiness_probes),
    );
    push_rendered_field(
        &mut output,
        "Readiness Surfaces:",
        render_joined_or_none(&workflow.readiness_surfaces),
    );
    push_rendered_field(
        &mut output,
        "Signal Checks:",
        render_joined_or_none(&workflow.signal_readiness_checks),
    );
    push_rendered_field(
        &mut output,
        "Signal Probes:",
        render_joined_or_none(&workflow.signal_readiness_probes),
    );
    push_rendered_field(
        &mut output,
        "Signal Surfaces:",
        render_joined_or_none(&workflow.signal_readiness_surfaces),
    );
    if let Some(notes) = workflow.notes
        && !notes.trim().is_empty()
    {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Notes:"),
            render_multiline_field(notes)
        ));
    }
    if !workflow.exposes.is_empty() || !workflow.expose_surfaces.is_empty() {
        output.push_str(&format!("\n  {}", paint_key("Exposes:")));
        if !workflow.expose_entries.is_empty() {
            for expose in &workflow.expose_entries {
                let detail = if let Some(surface) = expose.surface.as_deref() {
                    format!("{} (surface: {surface})", expose.url)
                } else {
                    expose.url.clone()
                };
                output.push_str(&format!("\n    {} {}", verdict_bullet(), detail));
            }
        } else {
            for expose in &workflow.exposes {
                output.push_str(&format!("\n    {} {}", verdict_bullet(), expose));
            }
            for surface in &workflow.expose_surfaces {
                output.push_str(&format!(
                    "\n    {} {}",
                    verdict_bullet(),
                    format!("surface: {surface}")
                ));
            }
        }
    }
    if let Some(default) = default {
        output.push_str(&format!(
            "\n  {} {}",
            paint_key("Default:"),
            if default { "true" } else { "false" }
        ));
    }
    output
}

fn workflow_selector_from_summary(workflow: &WorkflowSummary<'_>) -> String {
    workflow
        .instance
        .as_ref()
        .map(|instance| format!("{}@{instance}", workflow.name))
        .unwrap_or_else(|| workflow.name.to_string())
}

fn render_tasks_overview_text(
    _agent: Option<&AgentSummary<'_>>,
    tasks: &[TaskSummary<'_>],
) -> String {
    let safe_count = tasks
        .iter()
        .filter(|task| task.effective_safe_for_agent)
        .count();
    let mut lines = vec![paint_section_title("Overview")];
    lines.push(format!(
        " {}  {} {}",
        summary_bullet(),
        paint_key("Tasks:"),
        paint(&tasks.len().to_string(), "1;37")
    ));
    lines.push(format!(
        " {}  {} {}",
        summary_bullet(),
        paint_key("Agent-safe:"),
        paint(&safe_count.to_string(), "1;37")
    ));
    lines.join("\n")
}

fn render_multiline_field(value: &str) -> String {
    let mut lines = value.lines();
    let Some(first_line) = lines.next() else {
        return String::new();
    };

    let mut output = String::from(first_line);
    for line in lines {
        output.push('\n');
        output.push_str("  ");
        output.push_str(line);
    }
    output
}

fn render_task_run_mode(entry: &crate::output::LaneUseModeSummary, agent: bool) -> String {
    let mode = entry.mode.as_str();
    let mode_label = match mode {
        "container" => "Container",
        "native" => "Native",
        "remote" => "Remote",
        other => other,
    };
    if entry.availability == crate::output::LaneUseModeAvailability::Unavailable {
        return format!("{mode_label}: unavailable: not supported by this task");
    }

    let label = if entry.default {
        format!("{mode_label} (Default)")
    } else {
        mode_label.to_string()
    };
    let invocation = if agent { &entry.agent } else { &entry.human };
    match invocation.command.as_deref() {
        Some(command) => format!("{label}: `{}`", paint_code(command)),
        None => format!("{label}: unavailable: not callable in agent mode"),
    }
}

fn render_task_run_modes(task: &TaskSummary<'_>, agent: bool) -> Vec<String> {
    task.usage
        .modes
        .iter()
        .map(|entry| render_task_run_mode(entry, agent))
        .collect()
}

fn render_agent_run_unavailable(task: &TaskSummary<'_>) -> String {
    if !task.unsafe_closure_tasks.is_empty() {
        let blockers = task
            .unsafe_closure_tasks
            .iter()
            .map(|task| format!("`{task}`"))
            .collect::<Vec<_>>()
            .join(", ");
        let verb = if task.unsafe_closure_tasks.len() == 1 {
            "is"
        } else {
            "are"
        };
        return format!(
            "unavailable: dependency closure includes {blockers}, which {verb} not agent-callable"
        );
    }

    String::from("unavailable: task requires review before agent execution")
}

fn render_task_agent_policy(task: &TaskSummary<'_>) -> &'static str {
    match (task.safe_for_agent, task.effective_safe_for_agent) {
        (true, true) => "declared safe; full dependency closure is agent-callable",
        (true, false) => "declared safe, but the dependency closure requires review",
        (false, true) => "allowed by the contract agent-safe task policy",
        (false, false) => "not declared safe; review required before agent execution",
    }
}

fn push_task_run_fields(output: &mut String, task: &TaskSummary<'_>) {
    let host_unavailable = task
        .usage
        .modes
        .iter()
        .find(|mode| mode.default)
        .is_some_and(|mode| mode.reason.as_deref() == Some("unsupported_host_platform"));
    if host_unavailable {
        output.push_str(&format!(
            "\n  {} not callable on this host",
            paint_key("Humans:")
        ));
        output.push_str(&format!(
            "\n  {} not callable on this host",
            paint_key("Agents:")
        ));
        return;
    }
    output.push_str(&format!("\n  {}", paint_key("Human Run:")));
    for line in render_task_run_modes(task, false) {
        output.push_str(&format!("\n    {line}"));
    }

    output.push_str(&format!("\n  {}", paint_key("Agent Run:")));
    if task.usage.agent.callable {
        for line in render_task_run_modes(task, true) {
            output.push_str(&format!("\n    {line}"));
        }
    } else {
        output.push_str(&format!("\n    {}", render_agent_run_unavailable(task)));
    }

    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Agent Policy:"),
        render_task_agent_policy(task)
    ));
}

fn render_agent_lane_use_text(agent: &crate::output::AgentLaneUseSummary) -> String {
    if agent.callable {
        return agent
            .command
            .as_ref()
            .map(|command| format!("`{}`", paint_code(command)))
            .unwrap_or_else(|| String::from("not callable in agent mode"));
    }

    String::from("not callable in agent mode")
}

fn push_lane_use_fields(output: &mut String, usage: &crate::output::LaneUseSummary) {
    output.push_str(&format!(
        "\n  {} `{}`",
        paint_key("Humans:"),
        paint_code(&usage.human)
    ));
    output.push_str(&format!(
        "\n  {} {}",
        paint_key("Agents:"),
        render_agent_lane_use_text(&usage.agent)
    ));
}

fn render_task_inputs_compact(inputs: &BTreeMap<String, crate::schema::TaskInputSpec>) -> String {
    let labels = inputs
        .keys()
        .map(|name| format!("--{}", name.replace('_', "-")))
        .collect::<Vec<_>>();
    let label_width = labels.iter().map(|label| label.len()).max().unwrap_or(0);
    let detail_indent = format!("{}{}", "    ", " ".repeat(label_width + 13));
    let mut output = String::new();

    for ((_, spec), label) in inputs.iter().zip(labels.iter()) {
        let requirement = if spec.required {
            "required"
        } else {
            "optional"
        };
        let has_metadata = spec.default.is_some() || !spec.allowed.is_empty();
        let mut first_line_parts = Vec::new();
        if let Some(default) = spec.default.as_deref() {
            first_line_parts.push(format!("default=`{default}`"));
        }
        if !spec.allowed.is_empty() {
            first_line_parts.push(format!("allowed=`{}`", spec.allowed.join("|")));
        }
        if !has_metadata {
            if let Some(description) = spec.description.as_deref() {
                first_line_parts.push(description.to_string());
            }
        }

        output.push_str(&format!(
            "\n    {:<label_width$}  {}",
            label,
            requirement,
            label_width = label_width
        ));
        if !first_line_parts.is_empty() {
            output.push_str("   ");
            output.push_str(&first_line_parts.join(" "));
        }

        if has_metadata
            && let Some(description) = spec.description.as_deref()
            && !description.is_empty()
        {
            output.push('\n');
            output.push_str(&detail_indent);
            output.push_str(description);
        }
    }

    output
}

fn render_tasks_output_text(
    use_cmd: bool,
    path: &str,
    workflow: Option<&WorkflowSummary<'_>>,
    agent: Option<&AgentSummary<'_>>,
    tasks: &[TaskSummary<'_>],
) -> String {
    if use_cmd {
        let mut output = render_tasks_use_text(path, tasks);
        if let Some(workflow) = workflow {
            output.push_str("\n\n");
            output.push_str(&render_workflow_summary_text(workflow, None));
        }
        output
    } else {
        render_tasks_text(path, workflow, agent, tasks)
    }
}

fn render_workflows_output_text(
    path: &str,
    default: Option<&str>,
    workflows: &[ListedWorkflowSummary<'_>],
) -> String {
    let mut output = format_command_header("WORKFLOWS", path);
    output.push('\n');

    output.push_str(&format!("\n\n{}", paint_section_title("Overview")));
    output.push_str(&format!(
        "\n {}  {} {}",
        summary_bullet(),
        paint_key("Workflows:"),
        paint(&workflows.len().to_string(), "1;37")
    ));
    output.push_str(&format!(
        "\n {}  {} {}",
        summary_bullet(),
        paint_key("Default:"),
        default.unwrap_or("-")
    ));

    if workflows.is_empty() {
        output.push_str(&format!(
            "\n\n{} {}",
            list_bullet(),
            paint("No declared workflows.", "1")
        ));
        output.push_str(&format_next_timeline(&[
            String::from("run `ota tasks` to inspect task-level runnable entrypoints"),
            String::from("add `workflows` to `ota.yaml` when the repo has more than one meaningful operational path"),
        ]));
        return output;
    }

    for listed in workflows {
        output.push_str("\n\n");
        output.push_str(&render_workflow_summary_text(
            &listed.workflow,
            Some(listed.default),
        ));
    }

    output
}

pub fn annotations(
    mode: AnnotationMode,
    format: AnnotationFormat,
    title: Option<&str>,
    input: &Path,
) -> CommandOutput {
    let input = match read_annotations_input(input) {
        Ok(input) => input,
        Err(error) => return CommandOutput::failure(error),
    };
    let report: JsonValue = match serde_json::from_str(&input) {
        Ok(report) => report,
        Err(error) => return CommandOutput::failure(format!("invalid JSON input: {error}")),
    };

    let title = title.unwrap_or(match mode {
        AnnotationMode::Doctor => "ota doctor",
        AnnotationMode::WorkspaceDoctor => "ota workspace doctor",
        AnnotationMode::ReceiptDiff => "ota receipt diff",
    });

    if matches!(format, AnnotationFormat::Markdown) {
        let stdout = match mode {
            AnnotationMode::Doctor => render_annotations_markdown_doctor(title, &report),
            AnnotationMode::WorkspaceDoctor => {
                render_annotations_markdown_workspace_doctor(title, &report)
            }
            AnnotationMode::ReceiptDiff => render_annotations_markdown_receipt_diff(title, &report),
        };
        return CommandOutput::success(stdout);
    }

    if matches!(mode, AnnotationMode::ReceiptDiff) {
        return CommandOutput::failure(
            "receipt-diff summaries currently support only `--format markdown`".to_string(),
        );
    }

    let mut lines = Vec::new();

    match mode {
        AnnotationMode::Doctor => {
            let primary_blocker = report
                .get("summary")
                .and_then(|summary| summary.get("primary_blocker"))
                .and_then(annotation_primary_blocker);

            if let Some(primary_blocker) = primary_blocker {
                lines.push(render_annotation_primary_blocker(
                    format,
                    primary_blocker.severity,
                    &format!("{title} primary blocker"),
                    primary_blocker.summary,
                    primary_blocker.next,
                    primary_blocker.code,
                    primary_blocker.provenance,
                ));
            }

            if let Some(findings) = report.get("findings").and_then(|value| value.as_array()) {
                for finding in findings {
                    let Some(finding) = finding.as_object() else {
                        continue;
                    };
                    if primary_blocker.is_some_and(|blocker| {
                        annotation_finding_matches_primary_blocker(finding, None, blocker)
                    }) {
                        continue;
                    }
                    let severity = finding
                        .get("severity")
                        .and_then(|value| value.as_str())
                        .unwrap_or("warn");
                    let summary = finding
                        .get("summary")
                        .and_then(|value| value.as_str())
                        .unwrap_or("");
                    let next = finding
                        .get("next")
                        .and_then(|value| value.as_str())
                        .unwrap_or("");
                    let provenance = finding
                        .get("provenance")
                        .and_then(|value| value.as_str())
                        .filter(|value| !value.is_empty());
                    let code = finding
                        .get("code")
                        .and_then(|value| value.as_str())
                        .filter(|value| !value.is_empty());
                    lines.push(render_annotation_finding(
                        format,
                        severity,
                        &format!("{title} finding"),
                        summary,
                        next,
                        provenance,
                        code,
                    ));
                }
            }
        }
        AnnotationMode::WorkspaceDoctor => {
            let primary_blocker = report
                .get("summary")
                .and_then(|summary| summary.get("primary_blocker"))
                .and_then(annotation_primary_blocker);

            if let Some(primary_blocker) = primary_blocker {
                let repo = primary_blocker.repo.unwrap_or("");
                lines.push(render_annotation_primary_blocker(
                    format,
                    primary_blocker.severity,
                    &format!("{title} primary blocker [{repo}]"),
                    primary_blocker.summary,
                    primary_blocker.next,
                    primary_blocker.code,
                    primary_blocker.provenance,
                ));
            }

            if let Some(repos) = report.get("repos").and_then(|value| value.as_array()) {
                for repo in repos {
                    let Some(repo) = repo.as_object() else {
                        continue;
                    };
                    let name = repo
                        .get("name")
                        .and_then(|value| value.as_str())
                        .unwrap_or("");
                    let path = repo
                        .get("path")
                        .and_then(|value| value.as_str())
                        .unwrap_or("");
                    if let Some(findings) = repo.get("findings").and_then(|value| value.as_array())
                    {
                        for finding in findings {
                            let Some(finding) = finding.as_object() else {
                                continue;
                            };
                            if primary_blocker.is_some_and(|blocker| {
                                annotation_finding_matches_primary_blocker(
                                    finding,
                                    Some(name),
                                    blocker,
                                )
                            }) {
                                continue;
                            }
                            let severity = finding
                                .get("severity")
                                .and_then(|value| value.as_str())
                                .unwrap_or("warn");
                            let summary = finding
                                .get("summary")
                                .and_then(|value| value.as_str())
                                .unwrap_or("");
                            let next = finding
                                .get("next")
                                .and_then(|value| value.as_str())
                                .unwrap_or("");
                            let provenance = finding
                                .get("provenance")
                                .and_then(|value| value.as_str())
                                .filter(|value| !value.is_empty());
                            let code = finding
                                .get("code")
                                .and_then(|value| value.as_str())
                                .filter(|value| !value.is_empty());
                            lines.push(render_annotation_finding(
                                format,
                                severity,
                                &format!("{title} finding [{name}]"),
                                &format!("{path}: {summary}"),
                                next,
                                provenance,
                                code,
                            ));
                        }
                    }
                }
            }
        }
        AnnotationMode::ReceiptDiff => unreachable!("receipt diff handled earlier"),
    }

    CommandOutput::success(lines.join("\n"))
}

pub fn json_validate(
    schema: &str,
    input: Option<&Path>,
    allow_exit: &[i32],
    write_payload: Option<&Path>,
    assert_eq_rules: &[String],
    assert_in_rules: &[String],
    assert_type_rules: &[String],
    assert_non_empty_string_rules: &[String],
    assert_exit_map_rules: &[String],
    command: &[String],
    _debug: bool,
) -> CommandOutput {
    let allowed_exit_codes: Vec<i32> = if allow_exit.is_empty() {
        vec![0]
    } else {
        allow_exit.to_vec()
    };

    let mut source_label = String::from("command output");
    let (exit_code, payload) = if let Some(input_path) = input {
        if !allowed_exit_codes.contains(&0) {
            return CommandOutput::failure_with_code(
                format!(
                    "`--input` mode has synthetic exit code 0, but allowed exits are {:?}",
                    allowed_exit_codes
                ),
                2,
            );
        }
        source_label = if input_path == Path::new("-") {
            String::from("stdin")
        } else {
            input_path.display().to_string()
        };
        let payload = match read_text_input(input_path) {
            Ok(payload) => payload,
            Err(error) => return CommandOutput::failure(error),
        };
        if payload.trim().is_empty() {
            return CommandOutput::failure(format!("JSON input from {source_label} is empty"));
        }
        (0, payload)
    } else {
        let mut command = command.to_vec();
        if command.first().is_some_and(|value| value == "--") {
            command.remove(0);
        }
        if command.is_empty() {
            return CommandOutput::failure_with_code(
                String::from("missing command to execute; pass it after `--`"),
                2,
            );
        }

        let output = match Command::new(command[0].as_str())
            .args(&command[1..])
            .output()
        {
            Ok(output) => output,
            Err(error) => {
                return CommandOutput::failure(format!(
                    "failed to execute `{}`: {error}",
                    command.join(" ")
                ));
            }
        };
        let exit_code = output.status.code().unwrap_or(1);
        if !allowed_exit_codes.contains(&exit_code) {
            let stderr = String::from_utf8_lossy(&output.stderr);
            return CommandOutput::failure_with_code(
                format!(
                    "command exited with code {exit_code}, expected one of {:?}\n{}",
                    allowed_exit_codes, stderr
                ),
                exit_code,
            );
        }

        let stdout = String::from_utf8_lossy(&output.stdout).to_string();
        let stderr = String::from_utf8_lossy(&output.stderr).to_string();
        let payload = if stdout.trim().is_empty() {
            stderr
        } else {
            stdout
        };
        if payload.trim().is_empty() {
            return CommandOutput::failure("command produced no JSON payload".to_string());
        }
        (exit_code, payload)
    };

    if let Some(write_payload) = write_payload {
        if let Some(parent) = write_payload.parent()
            && let Err(error) = fs::create_dir_all(parent)
        {
            return CommandOutput::failure(format!(
                "failed to create payload output directory {}: {error}",
                parent.display()
            ));
        }
        if let Err(error) = fs::write(write_payload, &payload) {
            return CommandOutput::failure(format!(
                "failed to write payload to {}: {error}",
                write_payload.display()
            ));
        }
    }

    let payload_json: JsonValue = match serde_json::from_str(&payload) {
        Ok(payload_json) => payload_json,
        Err(error) => {
            return CommandOutput::failure(format!(
                "captured payload from {source_label} is not valid JSON: {error}"
            ));
        }
    };

    if let Err(error) = validate_payload_with_schema(schema, &payload_json) {
        return CommandOutput::failure(error);
    }
    if let Err(error) = apply_schema_assertions(
        &payload_json,
        exit_code,
        assert_eq_rules,
        assert_in_rules,
        assert_type_rules,
        assert_non_empty_string_rules,
        assert_exit_map_rules,
    ) {
        return CommandOutput::failure(error);
    }

    if let Some(write_payload) = write_payload {
        CommandOutput::success(format!(
            "validated {} against {}",
            write_payload.display(),
            schema
        ))
    } else {
        CommandOutput::success(format!("validated {source_label} against {schema}"))
    }
}

fn validate_payload_with_schema(schema_name: &str, payload: &JsonValue) -> Result<(), String> {
    let schema_file = PUBLISHED_JSON_SCHEMAS
        .get_file(schema_name)
        .ok_or_else(|| format!("published schema not found: {schema_name}"))?;
    let raw_schema = serde_json::from_slice(schema_file.contents())
        .map_err(|error| format!("failed to parse published schema `{schema_name}`: {error}"))?;
    let mut options = JSONSchema::options();
    options.with_draft(Draft::Draft202012);
    register_schema_documents(&mut options)?;
    let compiled = options
        .compile(&raw_schema)
        .map_err(|error| format!("failed to compile published schema `{schema_name}`: {error}"))?;
    if let Err(errors) = compiled.validate(payload) {
        let messages = errors.map(|error| error.to_string()).collect::<Vec<_>>();
        return Err(format!(
            "payload did not match schema `{}`:\n{}",
            schema_name,
            messages.join("\n")
        ));
    }
    Ok(())
}

fn register_schema_documents(options: &mut jsonschema::CompilationOptions) -> Result<(), String> {
    for file in PUBLISHED_JSON_SCHEMAS.files() {
        let document: JsonValue = serde_json::from_slice(file.contents()).map_err(|error| {
            format!(
                "failed to parse published schema `{}`: {error}",
                file.path().display()
            )
        })?;
        let Some(id) = document.get("$id").and_then(JsonValue::as_str) else {
            continue;
        };
        options.with_document(id.to_string(), document);
    }
    Ok(())
}

fn apply_schema_assertions(
    payload_json: &JsonValue,
    exit_code: i32,
    assert_eq_rules: &[String],
    assert_in_rules: &[String],
    assert_type_rules: &[String],
    assert_non_empty_string_rules: &[String],
    assert_exit_map_rules: &[String],
) -> Result<(), String> {
    for rule in assert_eq_rules {
        let (path, expected_raw) = split_once_or_error(rule, '=', "--assert-eq")?;
        let actual = resolve_payload_path(payload_json, path)?;
        let expected = parse_json_value_or_string(expected_raw);
        if actual != &expected {
            return Err(format!(
                "assert-eq failed for `{path}`: expected {expected:?}, got {actual:?}"
            ));
        }
    }

    for rule in assert_in_rules {
        let (path, expected_raw) = split_once_or_error(rule, '=', "--assert-in")?;
        let allowed = parse_json_value_or_string(expected_raw);
        let allowed = allowed
            .as_array()
            .ok_or_else(|| format!("assert-in for `{path}` expects a JSON array"))?;
        let actual = resolve_payload_path(payload_json, path)?;
        if !allowed.iter().any(|candidate| candidate == actual) {
            return Err(format!(
                "assert-in failed for `{path}`: value {actual:?} not in {allowed:?}"
            ));
        }
    }

    for rule in assert_type_rules {
        let (path, type_name) = split_once_or_error(rule, ':', "--assert-type")?;
        let actual = resolve_payload_path(payload_json, path)?;
        let ok = match type_name {
            "string" => actual.is_string(),
            "array" => actual.is_array(),
            "object" => actual.is_object(),
            "number" => actual.is_number(),
            "boolean" => actual.is_boolean(),
            _ => {
                return Err(format!(
                    "unsupported type `{type_name}` in --assert-type; use string|array|object|number|boolean"
                ));
            }
        };
        if !ok {
            return Err(format!(
                "assert-type failed for `{path}`: expected {type_name}, got {actual:?}"
            ));
        }
    }

    for path in assert_non_empty_string_rules {
        let actual = resolve_payload_path(payload_json, path)?;
        if !actual
            .as_str()
            .map(|value| !value.is_empty())
            .unwrap_or(false)
        {
            return Err(format!(
                "assert-non-empty-string failed for `{path}`: got {actual:?}"
            ));
        }
    }

    for rule in assert_exit_map_rules {
        let (path, mapping_raw) = split_once_or_error(rule, '=', "--assert-exit-map")?;
        let actual = resolve_payload_path(payload_json, path)?;
        let mut matched_exit = false;
        for clause in mapping_raw.split(';') {
            let (code_raw, allowed_raw) = split_once_or_error(clause, ':', "--assert-exit-map")?;
            let code: i32 = code_raw
                .parse()
                .map_err(|_| format!("invalid exit code `{code_raw}` in --assert-exit-map"))?;
            if code != exit_code {
                continue;
            }
            matched_exit = true;
            let allowed = parse_json_value_or_string(allowed_raw);
            let allowed = allowed.as_array().ok_or_else(|| {
                format!("assert-exit-map for `{path}` expects JSON array values per exit code")
            })?;
            if !allowed.iter().any(|candidate| candidate == actual) {
                return Err(format!(
                    "assert-exit-map failed for `{path}`: exit {exit_code} value {actual:?} not in {allowed:?}"
                ));
            }
        }
        if !matched_exit {
            return Err(format!(
                "assert-exit-map for `{path}` has no mapping for exit code {exit_code}"
            ));
        }
    }

    Ok(())
}

fn resolve_payload_path<'a>(payload: &'a JsonValue, path: &str) -> Result<&'a JsonValue, String> {
    let mut current = payload;
    for segment in path.split('.') {
        if segment.is_empty() {
            return Err(format!("invalid path `{path}`"));
        }
        current = match current {
            JsonValue::Object(map) => map
                .get(segment)
                .ok_or_else(|| format!("missing object segment `{segment}` in `{path}`"))?,
            JsonValue::Array(items) => {
                let index: usize = segment
                    .parse()
                    .map_err(|_| format!("invalid array segment `{segment}` in `{path}`"))?;
                items
                    .get(index)
                    .ok_or_else(|| format!("missing array index `{index}` in `{path}`"))?
            }
            _ => {
                return Err(format!(
                    "cannot traverse segment `{segment}` in `{path}` on scalar value"
                ));
            }
        };
    }
    Ok(current)
}

fn parse_json_value_or_string(raw: &str) -> JsonValue {
    serde_json::from_str(raw).unwrap_or_else(|_| JsonValue::String(raw.to_string()))
}

fn split_once_or_error<'a>(
    raw: &'a str,
    delimiter: char,
    flag: &str,
) -> Result<(&'a str, &'a str), String> {
    raw.split_once(delimiter).ok_or_else(|| {
        format!("invalid {flag} value `{raw}`; expected `path{delimiter}value` format")
    })
}

fn read_text_input(input: &Path) -> Result<String, String> {
    if input == Path::new("-") {
        let mut content = String::new();
        io::stdin()
            .read_to_string(&mut content)
            .map_err(|error| format!("failed to read stdin: {error}"))?;
        return Ok(content);
    }

    fs::read_to_string(input)
        .map_err(|error| format!("failed to read {}: {error}", input.display()))
}

fn read_annotations_input(input: &Path) -> Result<String, String> {
    read_text_input(input)
}

#[derive(Clone, Copy)]
struct AnnotationPrimaryBlocker<'a> {
    repo: Option<&'a str>,
    severity: &'a str,
    summary: &'a str,
    next: &'a str,
    code: Option<&'a str>,
    provenance: Option<&'a str>,
}

fn annotation_primary_blocker(value: &JsonValue) -> Option<AnnotationPrimaryBlocker<'_>> {
    let blocker = value.as_object()?;
    Some(AnnotationPrimaryBlocker {
        repo: blocker.get("repo").and_then(|value| value.as_str()),
        severity: blocker
            .get("severity")
            .and_then(|value| value.as_str())
            .unwrap_or("warn"),
        summary: blocker
            .get("summary")
            .and_then(|value| value.as_str())
            .unwrap_or(""),
        next: blocker
            .get("next")
            .and_then(|value| value.as_str())
            .unwrap_or(""),
        code: blocker
            .get("code")
            .and_then(|value| value.as_str())
            .filter(|value| !value.is_empty()),
        provenance: blocker
            .get("provenance")
            .and_then(|value| value.as_str())
            .filter(|value| !value.is_empty()),
    })
}

fn annotation_finding_matches_primary_blocker(
    finding: &serde_json::Map<String, JsonValue>,
    repo: Option<&str>,
    primary_blocker: AnnotationPrimaryBlocker<'_>,
) -> bool {
    finding
        .get("severity")
        .and_then(|value| value.as_str())
        .unwrap_or("warn")
        == primary_blocker.severity
        && finding
            .get("summary")
            .and_then(|value| value.as_str())
            .unwrap_or("")
            == primary_blocker.summary
        && finding
            .get("next")
            .and_then(|value| value.as_str())
            .unwrap_or("")
            == primary_blocker.next
        && finding
            .get("provenance")
            .and_then(|value| value.as_str())
            .filter(|value| !value.is_empty())
            == primary_blocker.provenance
        && repo == primary_blocker.repo
}

fn annotation_message(
    body: &str,
    next: &str,
    provenance: Option<&str>,
    code: Option<&str>,
) -> String {
    let mut parts = vec![body.to_string()];
    if let Some(code) = code.filter(|value| !value.is_empty()) {
        parts.push(format!("Code: {code}"));
    }
    if let Some(provenance) = provenance {
        parts.push(format!("Provenance: {provenance}"));
    }
    if !next.is_empty() {
        parts.push(format!("Next: {next}"));
    }
    parts.join(" | ")
}

fn annotation_markdown_severity(severity: &str) -> &'static str {
    match severity {
        "error" => "ERROR",
        "info" => "NOTICE",
        _ => "WARNING",
    }
}

fn annotation_markdown_status(ok: bool) -> &'static str {
    if ok { "READY" } else { "NOT READY" }
}

fn escape_markdown_text(value: &str) -> String {
    let mut out = String::with_capacity(value.len());
    for ch in value.chars() {
        match ch {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '\n' => out.push_str("<br>"),
            '\r' => {}
            '\\' | '`' | '*' | '_' | '{' | '}' | '[' | ']' | '(' | ')' | '#' | '+' | '-' | '!'
            | '|' => {
                out.push('\\');
                out.push(ch);
            }
            _ => out.push(ch),
        }
    }
    out
}

fn annotation_summary_counts(summary: &JsonValue) -> Option<String> {
    let error_count = summary.get("error_count")?.as_u64()?;
    let warn_count = summary.get("warn_count")?.as_u64()?;
    let info_count = summary.get("info_count")?.as_u64()?;
    Some(format!(
        "{error_count} error(s), {warn_count} warning(s), {info_count} info"
    ))
}

fn render_markdown_primary_blocker(
    lines: &mut Vec<String>,
    primary_blocker: AnnotationPrimaryBlocker<'_>,
) {
    let summary = match primary_blocker.repo {
        Some(repo) => format!(
            "[{}] {}",
            escape_markdown_text(repo),
            escape_markdown_text(primary_blocker.summary)
        ),
        None => escape_markdown_text(primary_blocker.summary),
    };
    lines.push(format!(
        "- **Primary blocker:** {}: {}",
        annotation_markdown_severity(primary_blocker.severity),
        summary
    ));
    if let Some(code) = primary_blocker.code {
        lines.push(format!("  - **Code:** {}", escape_markdown_text(code)));
    }
    if let Some(provenance) = primary_blocker.provenance {
        lines.push(format!(
            "  - **Provenance:** {}",
            escape_markdown_text(provenance)
        ));
    }
    if !primary_blocker.next.is_empty() {
        lines.push(format!(
            "  - **Next:** {}",
            escape_markdown_text(primary_blocker.next)
        ));
    }
}

fn render_markdown_finding(
    lines: &mut Vec<String>,
    severity: &str,
    summary: &str,
    next: &str,
    provenance: Option<&str>,
    code: Option<&str>,
) {
    lines.push(format!(
        "- **{}:** {}",
        annotation_markdown_severity(severity),
        escape_markdown_text(summary)
    ));
    if let Some(code) = code.filter(|value| !value.is_empty()) {
        lines.push(format!("  - **Code:** {}", escape_markdown_text(code)));
    }
    if let Some(provenance) = provenance {
        lines.push(format!(
            "  - **Provenance:** {}",
            escape_markdown_text(provenance)
        ));
    }
    if !next.is_empty() {
        lines.push(format!("  - **Next:** {}", escape_markdown_text(next)));
    }
}

fn render_annotations_markdown_doctor(title: &str, report: &JsonValue) -> String {
    let mut lines = vec![format!("## {}", escape_markdown_text(title))];
    let ok = report
        .get("ok")
        .and_then(|value| value.as_bool())
        .unwrap_or(false);
    lines.push(format!("**Status:** {}", annotation_markdown_status(ok)));
    if let Some(summary) = report.get("summary")
        && let Some(counts) = annotation_summary_counts(summary)
    {
        lines.push(format!("**Counts:** {counts}"));
    }

    let primary_blocker = report
        .get("summary")
        .and_then(|summary| summary.get("primary_blocker"))
        .and_then(annotation_primary_blocker);

    if let Some(primary_blocker) = primary_blocker {
        lines.push(String::new());
        render_markdown_primary_blocker(&mut lines, primary_blocker);
    }

    let mut finding_lines = Vec::new();
    if let Some(findings) = report.get("findings").and_then(|value| value.as_array()) {
        for finding in findings {
            let Some(finding) = finding.as_object() else {
                continue;
            };
            if primary_blocker.is_some_and(|blocker| {
                annotation_finding_matches_primary_blocker(finding, None, blocker)
            }) {
                continue;
            }
            render_markdown_finding(
                &mut finding_lines,
                finding
                    .get("severity")
                    .and_then(|value| value.as_str())
                    .unwrap_or("warn"),
                finding
                    .get("summary")
                    .and_then(|value| value.as_str())
                    .unwrap_or(""),
                finding
                    .get("next")
                    .and_then(|value| value.as_str())
                    .unwrap_or(""),
                finding
                    .get("provenance")
                    .and_then(|value| value.as_str())
                    .filter(|value| !value.is_empty()),
                finding
                    .get("code")
                    .and_then(|value| value.as_str())
                    .filter(|value| !value.is_empty()),
            );
        }
    }

    if !finding_lines.is_empty() {
        lines.push(String::new());
        lines.push(String::from("### Findings"));
        lines.extend(finding_lines);
    }

    lines.join("\n")
}

fn render_annotations_markdown_workspace_doctor(title: &str, report: &JsonValue) -> String {
    let mut lines = vec![format!("## {}", escape_markdown_text(title))];
    let ok = report
        .get("ok")
        .and_then(|value| value.as_bool())
        .unwrap_or(false);
    lines.push(format!("**Status:** {}", annotation_markdown_status(ok)));
    if let Some(summary) = report.get("summary")
        && let Some(counts) = annotation_summary_counts(summary)
    {
        lines.push(format!("**Counts:** {counts}"));
    }

    let primary_blocker = report
        .get("summary")
        .and_then(|summary| summary.get("primary_blocker"))
        .and_then(annotation_primary_blocker);

    if let Some(primary_blocker) = primary_blocker {
        lines.push(String::new());
        render_markdown_primary_blocker(&mut lines, primary_blocker);
    }

    let mut finding_lines = Vec::new();
    if let Some(repos) = report.get("repos").and_then(|value| value.as_array()) {
        for repo in repos {
            let Some(repo) = repo.as_object() else {
                continue;
            };
            let name = repo
                .get("name")
                .and_then(|value| value.as_str())
                .unwrap_or("");
            let path = repo
                .get("path")
                .and_then(|value| value.as_str())
                .unwrap_or("");
            if let Some(findings) = repo.get("findings").and_then(|value| value.as_array()) {
                for finding in findings {
                    let Some(finding) = finding.as_object() else {
                        continue;
                    };
                    if primary_blocker.is_some_and(|blocker| {
                        annotation_finding_matches_primary_blocker(finding, Some(name), blocker)
                    }) {
                        continue;
                    }
                    let finding_summary = finding
                        .get("summary")
                        .and_then(|value| value.as_str())
                        .unwrap_or("");
                    render_markdown_finding(
                        &mut finding_lines,
                        finding
                            .get("severity")
                            .and_then(|value| value.as_str())
                            .unwrap_or("warn"),
                        &format!("[{name}] {path}: {finding_summary}"),
                        finding
                            .get("next")
                            .and_then(|value| value.as_str())
                            .unwrap_or(""),
                        finding
                            .get("provenance")
                            .and_then(|value| value.as_str())
                            .filter(|value| !value.is_empty()),
                        finding
                            .get("code")
                            .and_then(|value| value.as_str())
                            .filter(|value| !value.is_empty()),
                    );
                }
            }
        }
    }

    if !finding_lines.is_empty() {
        lines.push(String::new());
        lines.push(String::from("### Findings"));
        lines.extend(finding_lines);
    }

    lines.join("\n")
}

fn annotation_receipt_diff_counts(summary: &JsonValue, key: &str) -> Option<String> {
    let counts = summary.get(key)?;
    let count = counts.get("count")?.as_u64()?;
    let error_count = counts.get("error_count")?.as_u64()?;
    let warn_count = counts.get("warn_count")?.as_u64()?;
    let info_count = counts.get("info_count")?.as_u64()?;
    Some(format!(
        "{count} (errors={error_count}, warnings={warn_count}, info={info_count})"
    ))
}

fn annotation_receipt_diff_gate(gate: &JsonValue) -> Option<String> {
    let passed = gate.get("passed")?.as_bool()?;
    let new_blocker_count = gate.get("new_blocker_count")?.as_u64()?;
    if passed {
        Some(String::from("fail on new blockers -> passed"))
    } else if new_blocker_count == 1 {
        Some(String::from(
            "fail on new blockers -> blocked (1 new blocker)",
        ))
    } else {
        Some(format!(
            "fail on new blockers -> blocked ({new_blocker_count} new blockers)"
        ))
    }
}

fn annotation_receipt_diff_finding_matches_gate_blocker(
    finding: &serde_json::Map<String, JsonValue>,
    gate: &JsonValue,
) -> bool {
    finding
        .get("severity")
        .and_then(|value| value.as_str())
        .unwrap_or("warn")
        == "error"
        && finding
            .get("summary")
            .and_then(|value| value.as_str())
            .unwrap_or("")
            == gate
                .get("blocking_summary")
                .and_then(|value| value.as_str())
                .unwrap_or("")
        && finding
            .get("next")
            .and_then(|value| value.as_str())
            .unwrap_or("")
            == gate
                .get("blocking_next")
                .and_then(|value| value.as_str())
                .unwrap_or("")
        && finding
            .get("provenance")
            .and_then(|value| value.as_str())
            .filter(|value| !value.is_empty())
            == gate
                .get("blocking_provenance")
                .and_then(|value| value.as_str())
                .filter(|value| !value.is_empty())
}

fn render_annotations_markdown_receipt_diff(title: &str, report: &JsonValue) -> String {
    let mut lines = vec![format!("## {}", escape_markdown_text(title))];

    let baseline_source = report
        .get("baseline")
        .and_then(|value| value.get("source"))
        .and_then(|value| value.as_str())
        .unwrap_or("-");
    let baseline_ok = report
        .get("summary")
        .and_then(|value| value.get("baseline_ok"))
        .and_then(|value| value.as_bool())
        .or_else(|| {
            report
                .get("baseline")
                .and_then(|value| value.get("ok"))
                .and_then(|value| value.as_bool())
        })
        .unwrap_or(false);
    let current_ok = report
        .get("summary")
        .and_then(|value| value.get("current_ok"))
        .and_then(|value| value.as_bool())
        .or_else(|| {
            report
                .get("current")
                .and_then(|value| value.get("ok"))
                .and_then(|value| value.as_bool())
        })
        .unwrap_or(false);
    let baseline_identity_label = report
        .get("summary")
        .and_then(|value| value.get("comparison"))
        .and_then(|value| value.get("baseline_identity_label"))
        .and_then(|value| value.as_str())
        .or_else(|| {
            report
                .get("baseline")
                .and_then(|value| value.get("contract_identity"))
                .and_then(|value| value.as_str())
        })
        .or_else(|| {
            report
                .get("baseline")
                .and_then(|value| value.get("contract"))
                .and_then(|value| value.as_str())
        })
        .unwrap_or("-");
    let current_identity_label = report
        .get("summary")
        .and_then(|value| value.get("comparison"))
        .and_then(|value| value.get("current_identity_label"))
        .and_then(|value| value.as_str())
        .or_else(|| {
            report
                .get("current")
                .and_then(|value| value.get("contract_identity"))
                .and_then(|value| value.as_str())
        })
        .or_else(|| {
            report
                .get("current")
                .and_then(|value| value.get("contract"))
                .and_then(|value| value.as_str())
        })
        .unwrap_or("-");
    let identity_changed = report
        .get("summary")
        .and_then(|value| value.get("comparison"))
        .and_then(|value| value.get("identity_changed"))
        .and_then(|value| value.as_bool())
        .unwrap_or(baseline_identity_label != current_identity_label);
    let readiness_change = report
        .get("summary")
        .and_then(|value| value.get("comparison"))
        .and_then(|value| value.get("readiness_change"))
        .and_then(|value| value.as_str())
        .unwrap_or("unchanged");
    let introduced = report
        .get("summary")
        .and_then(|summary| annotation_receipt_diff_counts(summary, "introduced"))
        .unwrap_or_else(|| String::from("-"));
    let resolved = report
        .get("summary")
        .and_then(|summary| annotation_receipt_diff_counts(summary, "resolved"))
        .unwrap_or_else(|| String::from("-"));
    let unchanged = report
        .get("summary")
        .and_then(|summary| annotation_receipt_diff_counts(summary, "unchanged"))
        .unwrap_or_else(|| String::from("-"));

    lines.push(format!(
        "**Baseline source:** {}",
        escape_markdown_text(baseline_source)
    ));
    lines.push(format!(
        "**Compare:** {} ({}) -> {} ({})",
        escape_markdown_text(baseline_identity_label),
        annotation_markdown_status(baseline_ok),
        escape_markdown_text(current_identity_label),
        annotation_markdown_status(current_ok)
    ));
    lines.push(format!(
        "**Drift:** identity {}; readiness {}",
        if identity_changed {
            "changed"
        } else {
            "unchanged"
        },
        match readiness_change {
            "improved" => "improved",
            "regressed" => "regressed",
            _ => "unchanged",
        }
    ));
    lines.push(format!(
        "**Counts:** introduced {}; resolved {}; unchanged {}",
        introduced, resolved, unchanged
    ));

    let gate = report.get("gate");
    if let Some(gate) = gate
        && let Some(label) = annotation_receipt_diff_gate(gate)
    {
        lines.push(format!("**Gate:** {label}"));
    }

    if let Some(gate) = gate
        && let Some(summary) = gate
            .get("blocking_summary")
            .and_then(|value| value.as_str())
    {
        lines.push(String::new());
        lines.push(format!(
            "- **Primary blocker:** ERROR: {}",
            escape_markdown_text(summary)
        ));
        if let Some(provenance) = gate
            .get("blocking_provenance")
            .and_then(|value| value.as_str())
        {
            lines.push(format!(
                "  - **Provenance:** {}",
                escape_markdown_text(provenance)
            ));
        }
        if let Some(next) = gate.get("blocking_next").and_then(|value| value.as_str()) {
            lines.push(format!("  - **Next:** {}", escape_markdown_text(next)));
        }
    }

    let mut introduced_lines = Vec::new();
    if let Some(findings) = report.get("introduced").and_then(|value| value.as_array()) {
        for finding in findings {
            let Some(finding) = finding.as_object() else {
                continue;
            };
            if gate.is_some_and(|gate| {
                annotation_receipt_diff_finding_matches_gate_blocker(finding, gate)
            }) {
                continue;
            }
            render_markdown_finding(
                &mut introduced_lines,
                finding
                    .get("severity")
                    .and_then(|value| value.as_str())
                    .unwrap_or("warn"),
                finding
                    .get("summary")
                    .and_then(|value| value.as_str())
                    .unwrap_or(""),
                finding
                    .get("next")
                    .and_then(|value| value.as_str())
                    .unwrap_or(""),
                finding
                    .get("provenance")
                    .and_then(|value| value.as_str())
                    .filter(|value| !value.is_empty()),
                finding
                    .get("code")
                    .and_then(|value| value.as_str())
                    .filter(|value| !value.is_empty()),
            );
        }
    }
    if !introduced_lines.is_empty() {
        lines.push(String::new());
        lines.push(String::from("### Introduced"));
        lines.extend(introduced_lines);
    }

    let mut resolved_lines = Vec::new();
    if let Some(findings) = report.get("resolved").and_then(|value| value.as_array()) {
        for finding in findings {
            let Some(finding) = finding.as_object() else {
                continue;
            };
            render_markdown_finding(
                &mut resolved_lines,
                finding
                    .get("severity")
                    .and_then(|value| value.as_str())
                    .unwrap_or("warn"),
                finding
                    .get("summary")
                    .and_then(|value| value.as_str())
                    .unwrap_or(""),
                finding
                    .get("next")
                    .and_then(|value| value.as_str())
                    .unwrap_or(""),
                finding
                    .get("provenance")
                    .and_then(|value| value.as_str())
                    .filter(|value| !value.is_empty()),
                finding
                    .get("code")
                    .and_then(|value| value.as_str())
                    .filter(|value| !value.is_empty()),
            );
        }
    }
    if !resolved_lines.is_empty() {
        lines.push(String::new());
        lines.push(String::from("### Resolved"));
        lines.extend(resolved_lines);
    }

    lines.join("\n")
}

fn render_annotation_finding(
    format: AnnotationFormat,
    severity: &str,
    heading: &str,
    body: &str,
    next: &str,
    provenance: Option<&str>,
    code: Option<&str>,
) -> String {
    let message = annotation_message(body, next, provenance, code);
    match format {
        AnnotationFormat::Github => {
            let severity = if severity == "error" {
                "error"
            } else {
                "warning"
            };
            format!(
                "::{} title={}::{}",
                severity,
                escape_github_value(heading),
                escape_github_value(&message)
            )
        }
        AnnotationFormat::Plain => {
            let severity = if severity == "error" {
                "ERROR"
            } else {
                "WARNING"
            };
            format!("{severity}: {heading}: {message}")
        }
        AnnotationFormat::Markdown => unreachable!("markdown handled earlier"),
    }
}

fn render_annotation_primary_blocker(
    format: AnnotationFormat,
    severity: &str,
    heading: &str,
    body: &str,
    next: &str,
    code: Option<&str>,
    provenance: Option<&str>,
) -> String {
    let message = annotation_message(body, next, provenance, code);
    match format {
        AnnotationFormat::Github => format!(
            "::{} title={}::{}",
            annotation_github_severity(severity),
            escape_github_value(heading),
            escape_github_value(&message)
        ),
        AnnotationFormat::Plain => {
            format!(
                "{}: {heading}: {message}",
                annotation_plain_severity(severity)
            )
        }
        AnnotationFormat::Markdown => unreachable!("markdown handled earlier"),
    }
}

fn annotation_github_severity(severity: &str) -> &'static str {
    match severity {
        "error" => "error",
        "info" => "notice",
        _ => "warning",
    }
}

fn annotation_plain_severity(severity: &str) -> &'static str {
    match severity {
        "error" => "ERROR",
        "info" => "NOTICE",
        _ => "WARNING",
    }
}

fn escape_github_value(value: &str) -> String {
    value
        .replace('%', "%25")
        .replace('\r', "%0D")
        .replace('\n', "%0A")
}

fn render_doctor_text(
    path: &str,
    contract_path: &Path,
    workflow: Option<&WorkflowSummary<'_>>,
    agent: Option<&AgentSummary<'_>>,
    execution: Option<&ExecutionSummary<'_>>,
    extensions: &BTreeMap<String, ExtensionSpec>,
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
    report: DoctorReport,
) -> CommandOutput {
    let summary = doctor_summary(&report, agent_verdict_from_summary(agent, workflow));
    let mut output = render_report_text(
        "DOCTOR",
        path,
        Some(contract_path),
        workflow,
        agent,
        execution,
        doctor_mode,
        doctor_lifecycle,
        report,
        Some(&summary),
    );
    if !extensions.is_empty() {
        output.stdout.push_str(&render_extensions_text(extensions));
    }
    output
}

fn doctor_summary(report: &DoctorReport, agent_verdict: DoctorVerdict) -> DoctorSummary {
    doctor_summary_from_findings(&report.findings, agent_verdict)
}

fn doctor_summary_from_findings(
    findings: &[Finding],
    agent_verdict: DoctorVerdict,
) -> DoctorSummary {
    let mut summary = DoctorSummary::default();
    summary.verdict = repo_verdict_from_findings(findings);
    summary.agent_verdict = agent_verdict;
    for finding in findings {
        match finding.severity {
            FindingSeverity::Error => summary.error_count += 1,
            FindingSeverity::Warn => summary.warn_count += 1,
            FindingSeverity::Info => summary.info_count += 1,
        }
    }
    summary.primary_blocker = primary_blocker_from_findings(findings);
    summary
}

fn add_doctor_summary(
    summary: &mut DoctorSummary,
    report: &DoctorReport,
    agent_verdict: DoctorVerdict,
) {
    add_doctor_summary_from_findings(summary, &report.findings, agent_verdict);
}

fn add_doctor_summary_from_findings(
    summary: &mut DoctorSummary,
    findings: &[Finding],
    agent_verdict: DoctorVerdict,
) {
    for finding in findings {
        match finding.severity {
            FindingSeverity::Error => summary.error_count += 1,
            FindingSeverity::Warn => summary.warn_count += 1,
            FindingSeverity::Info => summary.info_count += 1,
        }
    }
    summary.verdict = worse_verdict(summary.verdict, repo_verdict_from_findings(findings));
    summary.agent_verdict = worse_verdict(summary.agent_verdict, agent_verdict);
    if let Some(candidate) = primary_blocker_from_findings(findings) {
        summary.primary_blocker = match summary.primary_blocker.take() {
            Some(existing)
                if blocker_rank(existing.severity) >= blocker_rank(candidate.severity) =>
            {
                Some(existing)
            }
            _ => Some(candidate),
        };
    }
}

fn workspace_tasks_summary(repos: &[WorkspaceRepoTasksReport]) -> WorkspaceTasksSummary {
    let mut summary = WorkspaceTasksSummary {
        repo_count: repos.len(),
        ..WorkspaceTasksSummary::default()
    };

    for repo in repos {
        if repo.acquired {
            summary.acquired_count += 1;
        }
        summary.task_count += repo.tasks.len();
    }

    summary
}

fn workspace_doctor_summary(
    report: &crate::workspace::WorkspaceDoctorReport,
) -> WorkspaceDoctorSummary {
    let mut summary = WorkspaceDoctorSummary {
        repo_count: report.repos.len(),
        ..WorkspaceDoctorSummary::default()
    };

    for repo in &report.repos {
        if repo.ok {
            summary.ready_count += 1;
        } else {
            summary.not_ready_count += 1;
        }

        summary.agent_verdict = worse_verdict(summary.agent_verdict, repo.agent_verdict);

        for finding in &repo.findings {
            match finding.severity {
                FindingSeverity::Error => summary.error_count += 1,
                FindingSeverity::Warn => summary.warn_count += 1,
                FindingSeverity::Info => summary.info_count += 1,
            }
        }
    }

    summary.verdict = repo_verdict_from_findings(
        &report
            .repos
            .iter()
            .flat_map(|repo| repo.findings.iter())
            .cloned()
            .collect::<Vec<_>>(),
    );
    summary.primary_blocker = workspace_primary_blocker(report);
    summary
}

fn repo_verdict_from_findings(findings: &[Finding]) -> DoctorVerdict {
    if findings.iter().any(|finding| {
        finding.code() == "OTA_POLICY_PACK_VIOLATION" || finding.code() == "OTA_POLICY_PACK_INVALID"
    }) {
        return DoctorVerdict::PolicyBlocked;
    }

    if findings.iter().any(|finding| {
        finding.code().starts_with("OTA_AGENT_") && finding.severity == FindingSeverity::Error
    }) {
        return DoctorVerdict::AgentBlocked;
    }

    if findings
        .iter()
        .any(|finding| finding.severity == FindingSeverity::Error)
    {
        return DoctorVerdict::NotReady;
    }

    if findings
        .iter()
        .any(|finding| finding.severity == FindingSeverity::Warn)
    {
        return DoctorVerdict::Risky;
    }

    DoctorVerdict::Ready
}

fn agent_verdict_from_summary(
    agent: Option<&AgentSummary<'_>>,
    workflow: Option<&WorkflowSummary<'_>>,
) -> DoctorVerdict {
    let Some(agent) = agent else {
        return DoctorVerdict::NotReady;
    };

    if agent.entrypoint.is_none()
        && agent.default_task.is_none()
        && workflow.and_then(|workflow| workflow.run_task).is_none()
    {
        return DoctorVerdict::NotReady;
    }

    if agent.safe_tasks.is_empty()
        || (agent.writable_paths.is_empty() && agent.protected_paths.is_empty())
    {
        return DoctorVerdict::Risky;
    }

    if agent.inferred_boundary_reviewed == Some(false) {
        return DoctorVerdict::Risky;
    }

    DoctorVerdict::Ready
}

fn worse_verdict(existing: DoctorVerdict, candidate: DoctorVerdict) -> DoctorVerdict {
    if verdict_rank(candidate) >= verdict_rank(existing) {
        candidate
    } else {
        existing
    }
}

fn verdict_rank(verdict: DoctorVerdict) -> usize {
    match verdict {
        DoctorVerdict::Ready => 0,
        DoctorVerdict::Risky => 1,
        DoctorVerdict::NotReady => 2,
        DoctorVerdict::PolicyBlocked => 3,
        DoctorVerdict::AgentBlocked => 4,
    }
}

fn workspace_list_summary(repos: &[WorkspaceRepoListReport]) -> WorkspaceListSummary {
    let mut summary = WorkspaceListSummary {
        repo_count: repos.len(),
        ..WorkspaceListSummary::default()
    };

    for repo in repos {
        if repo.acquired {
            summary.acquired_count += 1;
        }
        if repo.status == "READY" {
            summary.ready_count += 1;
        } else {
            summary.not_ready_count += 1;
        }
        if !repo.contract_present {
            summary.missing_contract_count += 1;
        }
    }

    summary
}

fn primary_blocker_from_findings(findings: &[Finding]) -> Option<DoctorPrimaryBlocker> {
    findings.first().map(|finding| DoctorPrimaryBlocker {
        code: finding
            .identity
            .as_ref()
            .map(|identity| identity.code.clone()),
        severity: finding.severity,
        summary: finding.summary.clone(),
        why: finding.why.clone(),
        next: finding.next.clone(),
        provenance: finding.provenance(),
        provenance_key: finding.provenance_key(),
    })
}

fn blocker_rank(severity: FindingSeverity) -> usize {
    match severity {
        FindingSeverity::Error => 3,
        FindingSeverity::Warn => 2,
        FindingSeverity::Info => 1,
    }
}

fn workspace_primary_blocker(
    report: &crate::workspace::WorkspaceDoctorReport,
) -> Option<WorkspacePrimaryBlocker> {
    let mut fallback = None;

    for repo in &report.repos {
        for finding in &repo.findings {
            let blocker = WorkspacePrimaryBlocker {
                code: finding
                    .identity
                    .as_ref()
                    .map(|identity| identity.code.clone()),
                repo: repo.name.clone(),
                severity: finding.severity,
                summary: finding.summary.clone(),
                why: finding.why.clone(),
                next: finding.next.clone(),
                provenance: finding.provenance(),
                provenance_key: finding.provenance_key(),
            };
            if finding.severity == FindingSeverity::Error {
                return Some(blocker);
            }
            if fallback.is_none() {
                fallback = Some(blocker);
            }
        }
    }

    fallback
}

fn render_doctor_section(
    path: &str,
    contract_path: &Path,
    workflow: Option<&WorkflowSummary<'_>>,
    agent: Option<&AgentSummary<'_>>,
    execution: Option<&ExecutionSummary<'_>>,
    extensions: &BTreeMap<String, ExtensionSpec>,
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
    report: &DoctorReport,
) -> String {
    let summary = doctor_summary(report, agent_verdict_from_summary(agent, workflow));
    let mut output = render_report_section(
        "DOCTOR",
        path,
        Some(contract_path),
        workflow,
        agent,
        execution,
        doctor_mode,
        doctor_lifecycle,
        report,
        Some(&summary),
    );
    if !extensions.is_empty() {
        output.push_str(&render_extensions_text(extensions));
    }
    output
}

fn render_extensions_output_text(
    path: &str,
    extensions: &BTreeMap<String, ExtensionSpec>,
) -> String {
    let mut output = format_command_header("EXTENSIONS", path);
    output.push('\n');
    output.push_str(&render_extensions_text(extensions));
    output
}

fn render_extension_run_text(
    path: &str,
    extension_name: &str,
    extension: &ExtensionSpec,
    result: &CommandRunResult,
) -> String {
    let mut stdout = format_command_header("EXTENSION RUN", &format!("{extension_name} {path}"));
    stdout.push_str(&format!("\n  {} {}", paint_key("Name:"), extension_name));
    stdout.push_str(&format!(
        "\n  {} {}",
        paint_key("Kind:"),
        extension.kind.as_str()
    ));
    append_wrapped_detail(
        &mut stdout,
        "Command:",
        &extension.command,
        "  ",
        84,
        stylize_inline_text,
    );
    stdout.push_str(&format!(
        "\n  {} {}",
        paint_key("API Version:"),
        extension.api_version
    ));
    stdout.push_str(&format!(
        "\n  {} {}",
        paint_key("Exit Code:"),
        result.exit_code
    ));

    if !result.stdout.trim().is_empty() {
        stdout.push_str(&format!("\n\n{}", paint_key("Stdout:")));
        stdout.push_str(&format!("\n{}", result.stdout.trim_end()));
    }

    if !result.stderr.trim().is_empty() {
        stdout.push_str(&format!("\n\n{}", paint_key("Stderr:")));
        stdout.push_str(&format!("\n{}", result.stderr.trim_end()));
    }

    stdout
}

fn run_extension_descriptor(
    contract: &Contract,
    contract_path: &Path,
    text_path_display: &str,
    extension_name: &str,
    expected_kind: crate::schema::ExtensionKind,
    format: OutputFormat,
) -> CommandOutput {
    let extension = match contract.extensions.get(extension_name) {
        Some(extension) => extension,
        None => {
            return CommandOutput::failure_with_code(
                format!(
                    "extension `{extension_name}` is not declared in `{}`",
                    contract_path.display()
                ),
                2,
            );
        }
    };

    if extension.api_version != 1 {
        return CommandOutput::failure_with_code(
            format!(
                "extension `{extension_name}` declares unsupported `api_version {}`; expected `1`",
                extension.api_version
            ),
            2,
        );
    }

    if extension.kind != expected_kind {
        let mode = match expected_kind {
            crate::schema::ExtensionKind::CheckProvider => "run",
            crate::schema::ExtensionKind::ExportProvider => "publish",
            crate::schema::ExtensionKind::BackendProvider => {
                return CommandOutput::failure_with_code(
                    format!(
                        "extension `{extension_name}` kind `{}` is not executable with `ota extensions`; backend providers are reserved for task execution backends",
                        extension.kind.as_str()
                    ),
                    2,
                );
            }
        };
        return CommandOutput::failure_with_code(
            format!(
                "extension `{extension_name}` kind `{}` is not executable with `ota extensions --{mode}`; expected kind: `{}`",
                extension.kind.as_str(),
                expected_kind.as_str()
            ),
            2,
        );
    }

    let working_dir = contract_working_dir(contract_path);
    let result = match run_shell_command(
        &extension.command,
        working_dir,
        RepoExecutionMode::Capture,
        "Running extension",
    ) {
        Ok(result) => result,
        Err(error) => {
            return CommandOutput::failure_with_code(
                format!("failed to execute extension `{extension_name}`: {error}"),
                1,
            );
        }
    };

    match format {
        OutputFormat::Text => {
            let mut stdout =
                render_extension_run_text(text_path_display, extension_name, extension, &result);
            if result.exit_code != 0 {
                stdout.push_str(&format!("\n\n{}", error_key("Extension run failed.")));
            }
            CommandOutput {
                stdout,
                stderr: None,
                exit_code: result.exit_code,
            }
        }
        OutputFormat::Json => CommandOutput {
            stdout: to_json_value(json!({
                "ok": result.exit_code == 0,
                "path": contract_path.display().to_string(),
                "extension": {
                    "name": extension_name,
                    "kind": extension.kind,
                    "command": extension.command,
                    "api_version": extension.api_version,
                    "description": extension.description,
                    "config": extension.config,
                },
                "exit_code": result.exit_code,
                "stdout": result.stdout,
                "stderr": result.stderr,
            })),
            stderr: None,
            exit_code: result.exit_code,
        },
    }
}

fn render_extensions_text(extensions: &BTreeMap<String, ExtensionSpec>) -> String {
    if extensions.is_empty() {
        let mut stdout = String::from("\n\n");
        stdout.push_str(&format!(
            "{} {}",
            list_bullet(),
            paint("No staged extensions declared.", "1")
        ));
        stdout.push_str(&format_next_timeline(&[
            String::from("run `ota doctor` to inspect repo readiness without extensions"),
            String::from(
                "add `extensions` to `ota.yaml` when repo workflows need provider hooks or adapters",
            ),
        ]));
        return stdout;
    }

    let mut stdout = String::from("\n\n");
    stdout.push_str(&format!("\n{}", paint_key("Extensions:")));

    for (name, extension) in extensions {
        stdout.push_str(&format!("\n{} {}", list_bullet(), paint(name, "1")));
        stdout.push_str(&format!(
            "\n  {} {}",
            paint_key("Kind:"),
            extension.kind.as_str()
        ));
        append_wrapped_detail(
            &mut stdout,
            "Command:",
            &extension.command,
            "  ",
            84,
            stylize_inline_text,
        );
        stdout.push_str(&format!(
            "\n  {} {}",
            paint_key("API Version:"),
            extension.api_version
        ));
        if let Some(description) = extension.description.as_deref() {
            append_wrapped_detail(
                &mut stdout,
                "Description:",
                description,
                "  ",
                84,
                stylize_inline_text,
            );
        }
        if !extension.config.is_empty() {
            let keys = extension
                .config
                .keys()
                .map(String::as_str)
                .collect::<Vec<_>>()
                .join(",");
            stdout.push_str(&format!("\n  {} {}", paint_key("Config Keys:"), keys));
        }
    }

    stdout
}

const DOCTOR_DETAIL_WRAP_WIDTH: usize = 120;

fn render_report_text(
    command: &str,
    path: &str,
    contract_path: Option<&Path>,
    workflow: Option<&WorkflowSummary<'_>>,
    agent: Option<&AgentSummary<'_>>,
    execution: Option<&ExecutionSummary<'_>>,
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
    report: DoctorReport,
    summary: Option<&DoctorSummary>,
) -> CommandOutput {
    let stdout = render_report_section(
        command,
        path,
        contract_path,
        workflow,
        agent,
        execution,
        doctor_mode,
        doctor_lifecycle,
        &report,
        summary,
    );
    CommandOutput {
        stdout,
        stderr: None,
        exit_code: if report.ok { 0 } else { 1 },
    }
}

fn render_report_section(
    command: &str,
    path: &str,
    contract_path: Option<&Path>,
    workflow: Option<&WorkflowSummary<'_>>,
    agent: Option<&AgentSummary<'_>>,
    execution: Option<&ExecutionSummary<'_>>,
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
    report: &DoctorReport,
    summary: Option<&DoctorSummary>,
) -> String {
    let status = if command == "DOCTOR" || command == "CHECK" {
        summary
            .map(|summary| render_doctor_readiness_status(summary.verdict))
            .unwrap_or_else(|| render_readiness_status(report.ok))
    } else {
        render_readiness_status(report.ok)
    };
    let mut stdout = format!("{}\n\n{}", format_command_header(command, path), status);
    if let Some(summary) = summary {
        stdout.push_str("\n\n");
        stdout.push_str(&format!("{}\n", paint_section_title("Verdict")));
        stdout.push_str(&format!(
            " {}  {} {}",
            verdict_bullet(),
            paint_key("Repo:"),
            render_doctor_verdict(summary.verdict)
        ));
        stdout.push_str(&format!(
            "\n {}  {} {}",
            verdict_bullet(),
            paint_key("Agent:"),
            render_doctor_verdict(summary.agent_verdict)
        ));
        stdout.push_str("\n\n");
    }
    if let Some(workflow) = workflow {
        stdout.push_str(&render_workflow_summary_text(workflow, None));
        stdout.push_str("\n\n");
    }

    let skip_primary_finding = summary
        .and_then(|summary| summary.primary_blocker.as_ref())
        .filter(|finding| finding.severity != FindingSeverity::Info);
    let contractless_repo_root = contractless_repo_root(contract_path, path);
    let contractless_doctor =
        contractless_doctor_signal_findings(command, report, &skip_primary_finding);
    if let Some(primary_blocker) = skip_primary_finding {
        if !stdout.ends_with("\n\n") {
            stdout.push_str("\n\n");
        }
        if contractless_doctor.is_some() {
            stdout.push_str(&render_contractless_primary_finding_text(
                primary_blocker,
                doctor_mode,
                doctor_lifecycle,
                contract_path,
                contractless_repo_root.as_deref(),
            ));
        } else {
            stdout.push_str(&render_primary_finding_text(
                primary_blocker.severity,
                &primary_blocker.summary,
                &primary_blocker.why,
                &primary_blocker.next,
                primary_blocker.provenance.clone(),
                doctor_mode,
                doctor_lifecycle,
                contract_path,
            ));
        }
    }
    if command == "DOCTOR" && report.ok && report.findings.is_empty() {
        stdout.push_str(&render_doctor_ready_next(workflow, agent, contract_path));
    } else if command == "CHECK" && report.ok && report.findings.is_empty() {
        stdout.push_str(&render_check_ready_next(workflow, contract_path));
    }
    if let Some(execution) = execution {
        if !stdout.ends_with("\n\n") {
            stdout.push_str("\n\n");
        }
        if command == "DOCTOR" || command == "CHECK" {
            stdout.push_str(&render_doctor_execution_summary_text(
                execution,
                doctor_mode,
                doctor_lifecycle,
            ));
        } else {
            stdout.push_str(&render_execution_summary_text(execution));
        }
    }
    if let Some(agent) = agent {
        let summary = if command == "DOCTOR" || command == "CHECK" {
            render_doctor_agent_summary_text(agent, !report.ok)
        } else {
            render_agent_summary_line(agent, !report.ok)
        };
        if let Some(summary) = summary {
            stdout.push_str("\n\n");
            stdout.push_str(&summary);
        }
    }
    if let Some(findings) = contractless_doctor {
        if !findings.is_empty() {
            stdout.push_str(&render_contractless_doctor_signal_section(&findings));
        }
        return stdout;
    }
    let grouped_findings = group_doctor_findings(report.findings.iter().enumerate().filter_map(
        |(index, finding)| {
            if index == 0 && skip_primary_finding.is_some() {
                None
            } else {
                Some(finding)
            }
        },
    ));
    for group in grouped_findings {
        if group.findings.len() == 1 {
            let finding = group.findings[0];
            let (display_why, display_next, container_image) =
                render_container_image_finding_text(&finding.why, &finding.next, doctor_mode);
            let rewritten_next =
                rewrite_doctor_mode_command(&display_next, doctor_mode, doctor_lifecycle);
            if !concise_mode() {
                stdout.push_str("\n\n");
                if render_depends_on_boundary_doctor_finding(
                    &mut stdout,
                    finding.severity,
                    &finding.summary,
                    &display_why,
                    &rewritten_next,
                    contract_path,
                ) {
                    continue;
                }
            }
            let diagnosis =
                finding_diagnosis_text(&finding.summary, &display_why, container_image.as_deref());
            let why_lines =
                finding_why_lines(&finding.summary, &display_why, container_image.as_deref());
            let next_steps = finding_next_steps(&rewritten_next);
            let source_line = policy_finding_source(&finding.summary, &finding.why).map(|value| {
                format!(
                    "{} {}",
                    finding_detail_key(finding.severity, "Source:"),
                    value
                )
            });
            let source_block = source_line
                .as_ref()
                .map(|value| format!("\n{}", value))
                .unwrap_or_default();
            let provenance_line = finding.provenance().map(|value| {
                format!(
                    "\n{} {}",
                    finding_detail_key(finding.severity, "Provenance:"),
                    value
                )
            });
            if concise_mode() {
                let provenance_block = provenance_line.as_deref().unwrap_or("");
                stdout.push_str("\n\n");
                stdout.push_str(&format!(
                    "{}  {}{}{}",
                    render_severity(finding.severity),
                    render_finding_summary_with_count(
                        finding.severity,
                        &diagnosis,
                        single_finding_display_count(&finding.summary, &finding.why),
                    ),
                    source_block,
                    provenance_block,
                ));
                append_finding_section(
                    &mut stdout,
                    "Next:",
                    &next_steps,
                    finding.severity,
                    contract_path,
                );
            } else {
                stdout.push_str(&format!(
                    "{}  {}",
                    render_severity(finding.severity),
                    render_finding_summary_with_count(
                        finding.severity,
                        &diagnosis,
                        single_finding_display_count(&finding.summary, &finding.why),
                    ),
                ));
                append_finding_section(
                    &mut stdout,
                    "Why:",
                    &why_lines,
                    finding.severity,
                    contract_path,
                );
                if let Some(source_line) = source_line.as_deref() {
                    stdout.push('\n');
                    stdout.push_str(source_line);
                }
                if let Some(provenance_line) = provenance_line.as_deref() {
                    stdout.push_str(provenance_line);
                }
                append_finding_section(
                    &mut stdout,
                    "Next:",
                    &next_steps,
                    finding.severity,
                    contract_path,
                );
            }
            continue;
        }

        stdout.push_str(&render_grouped_doctor_findings(
            &group,
            contract_path,
            doctor_mode,
        ));
    }

    stdout
}

fn contractless_repo_root(contract_path: Option<&Path>, path: &str) -> Option<PathBuf> {
    contract_path
        .and_then(|path| path.parent().map(Path::to_path_buf))
        .or_else(|| {
            let path = Path::new(path);
            (!path.as_os_str().is_empty()).then(|| path.to_path_buf())
        })
}

fn contractless_doctor_signal_findings<'a>(
    command: &str,
    report: &'a DoctorReport,
    primary_blocker: &Option<&DoctorPrimaryBlocker>,
) -> Option<Vec<&'a Finding>> {
    if command != "DOCTOR" {
        return None;
    }
    let primary = primary_blocker.as_ref()?;
    if primary.summary != "Contract missing"
        || !primary
            .why
            .contains("Ota cannot validate repo readiness yet")
    {
        return None;
    }
    Some(report.findings.iter().skip(1).collect())
}

fn render_contractless_primary_finding_text(
    primary_blocker: &DoctorPrimaryBlocker,
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
    contract_path: Option<&Path>,
    repo_root: Option<&Path>,
) -> String {
    let mut stdout = String::new();
    let (display_why, _, container_image) = render_container_image_finding_text(
        &primary_blocker.why,
        &primary_blocker.next,
        doctor_mode,
    );
    let why_lines = finding_why_lines(
        &primary_blocker.summary,
        &display_why,
        container_image.as_deref(),
    );
    stdout.push_str(&format!(
        "{} {} {}",
        primary_error_marker(),
        paint("Primary Blocker", "1;38;2;255;168;168"),
        render_finding_summary_with_count(primary_blocker.severity, &primary_blocker.summary, 1,)
    ));
    if !concise_mode() {
        append_finding_section(
            &mut stdout,
            "Why:",
            &why_lines,
            primary_blocker.severity,
            contract_path,
        );
    }
    if let Some(provenance) = primary_blocker.provenance.as_deref() {
        append_wrapped_labeled_text(
            &mut stdout,
            "Provenance:",
            provenance,
            "",
            DOCTOR_DETAIL_WRAP_WIDTH,
            false,
            paint_key,
            |value| render_backticked_text(value, contract_path),
        );
    }
    let next_steps = repo_root
        .map(|root| contractless_repo_onboarding_next_steps(root, true))
        .unwrap_or_else(|| {
            vec![rewrite_doctor_mode_command(
                &primary_blocker.next,
                doctor_mode,
                doctor_lifecycle,
            )]
        });
    append_finding_section(
        &mut stdout,
        "Next:",
        &next_steps,
        primary_blocker.severity,
        None,
    );
    stdout
}

fn contractless_signal_line(finding: &Finding) -> String {
    match finding.summary.as_str() {
        "Could not inspect repo signals" => {
            format!(
                "Could not inspect repo signals: {}",
                paint_contractless_signal_value(&finding.why)
            )
        }
        "No strong repo signals were detected yet" => {
            String::from("No strong repo signals were detected yet")
        }
        _ => {
            if let Some((label, value)) = contractless_signal_summary_parts(&finding.summary) {
                format!("{label}: {}", paint_contractless_signal_value(value))
            } else {
                finding.summary.clone()
            }
        }
    }
}

fn contractless_signal_summary_parts(summary: &str) -> Option<(&str, &str)> {
    let (label, value) = summary.split_once(": ")?;
    if label.trim().is_empty() || value.trim().is_empty() {
        return None;
    }
    Some((label, value))
}

fn paint_contractless_signal_value(value: &str) -> String {
    paint(value, "1;37")
}

fn render_contractless_doctor_signal_section(findings: &[&Finding]) -> String {
    let mut stdout = format!(
        "\n\n{} {}\n",
        primary_info_marker(),
        paint_section_title("Repo Signals")
    );
    for finding in findings {
        stdout.push_str(&format!(
            " {}  {}",
            verdict_bullet(),
            contractless_signal_line(finding)
        ));
        stdout.push('\n');
    }
    while stdout.ends_with('\n') {
        stdout.pop();
    }
    stdout
}

fn render_doctor_ready_next(
    workflow: Option<&WorkflowSummary<'_>>,
    agent: Option<&AgentSummary<'_>>,
    contract_path: Option<&Path>,
) -> String {
    let mut items = Vec::new();
    if let Some(task) = workflow
        .and_then(|workflow| workflow.run_task)
        .filter(|task| !task.trim().is_empty())
    {
        let run_command = contract_path
            .map(|path| command_for_repo_contract_target(&format!("ota run {task}"), path))
            .unwrap_or_else(|| format!("ota run {task}"));
        items.push(format!(
            "run `{run_command}` to activate the canonical repo workflow"
        ));
    } else if let Some(task) = agent
        .and_then(|agent| agent.default_task.or(agent.entrypoint))
        .filter(|task| !task.trim().is_empty())
    {
        let run_command = contract_path
            .map(|path| command_for_repo_contract_target(&format!("ota run {task}"), path))
            .unwrap_or_else(|| format!("ota run {task}"));
        items.push(format!(
            "run `{run_command}` to execute the default repo task"
        ));
    } else {
        let tasks_command = contract_path
            .map(|path| command_for_repo_contract_target("ota tasks --use", path))
            .unwrap_or_else(|| String::from("ota tasks --use"));
        items.push(format!(
            "run `{tasks_command}` to inspect runnable task usage"
        ));
    }

    format_next_timeline(&items)
}

fn render_check_ready_next(
    workflow: Option<&WorkflowSummary<'_>>,
    contract_path: Option<&Path>,
) -> String {
    let up_command = contract_path
        .map(|path| command_for_repo_contract_target("ota up", path))
        .unwrap_or_else(|| String::from("ota up"));
    let mut items = vec![format!("run `{up_command}` to prepare the repo end to end")];
    if let Some(task) = workflow.and_then(|workflow| workflow.run_task) {
        let run_command = contract_path
            .map(|path| command_for_repo_contract_target(&format!("ota run {task}"), path))
            .unwrap_or_else(|| format!("ota run {task}"));
        items.push(format!(
            "run `{run_command}` to activate the canonical repo workflow"
        ));
    } else {
        let tasks_command = contract_path
            .map(|path| command_for_repo_contract_target("ota tasks --use", path))
            .unwrap_or_else(|| String::from("ota tasks --use"));
        items.push(format!(
            "run `{tasks_command}` to inspect runnable task usage"
        ));
    }
    format_next_timeline(&items)
}

fn title_case_word(value: &str) -> String {
    let mut chars = value.chars();
    match chars.next() {
        Some(first) => first.to_uppercase().collect::<String>() + chars.as_str(),
        None => String::new(),
    }
}

fn formatted_version_policy_item(item: &str) -> String {
    if let Some((subject, versions)) = item.split_once(" (versions ")
        && let Some((kind, name)) = subject.split_once(' ')
    {
        return format!(
            "{kind} `{name}` (versions `{}`)",
            versions.trim_end_matches(')')
        );
    }
    item.to_string()
}

fn container_provisioning_backend_and_name(summary: &str) -> Option<(&str, &str)> {
    if let Some(rest) = summary.strip_prefix("Container ")
        && let Some((backend, name)) = rest.split_once(" cannot install pinned version: ")
    {
        return Some((backend, name));
    }
    if let Some(rest) = summary.strip_prefix("Container ")
        && let Some((backend, name)) = rest.split_once(" cannot install requested prerequisite: ")
    {
        return Some((backend, name));
    }
    if let Some(rest) = summary.strip_prefix("Container ")
        && let Some((backend, name)) = rest.split_once(" cannot install pinned package version: ")
    {
        return Some((backend, name));
    }
    if let Some(rest) = summary.strip_prefix("Container ")
        && let Some((backend, name)) = rest.split_once(" cannot locate required package: ")
    {
        return Some((backend, name));
    }
    if let Some(rest) = summary.strip_prefix("Container ")
        && let Some((backend, name)) = rest.split_once(" cannot refresh configured sources: ")
    {
        return Some((backend, name));
    }
    None
}

fn container_provisioning_why_lines(why: &str, backend: &str) -> Option<Vec<String>> {
    let request_prefix = "the Linux/container target requests ";
    let request_and_rest = why.strip_prefix(request_prefix)?;
    let (request_part, failure_part) = request_and_rest
        .split_once(", but ")
        .or_else(|| request_and_rest.split_once(" but "))?;

    let mut lines = Vec::new();
    if let Some((request, resolution)) = request_part.split_once("; ") {
        lines.push(format!("{request_prefix}{request}"));
        lines.push(resolution.to_string());
    } else {
        lines.push(format!("{request_prefix}{request_part}"));
    }

    if let Some((head, _)) = failure_part.split_once(" inside container image `") {
        lines.push(format!(
            "{} in the configured container environment",
            head.trim_end()
        ));
    } else {
        lines.push(
            failure_part
                .replace(
                    "inside container image",
                    "in the configured container environment",
                )
                .replace(
                    "configured apt sources",
                    "configured `apt` provisioning path",
                ),
        );
    }

    if let Some(last) = lines.last_mut() {
        *last = last
            .replace("does not provide that version", "could not satisfy it")
            .replace(
                "configured apt sources",
                "configured `apt` provisioning path",
            );
        if !last.contains(&format!("`{backend}`")) && backend != "apt" {
            *last = last.replace(
                "the configured provisioning path",
                &format!("the configured `{backend}` provisioning path"),
            );
        }
    }

    Some(lines)
}

fn finding_diagnosis_text(summary: &str, why: &str, container_image: Option<&str>) -> String {
    if summary == "Adapter bootstrap sources are declared" {
        return String::from("Approved adapter bootstrap is configured");
    }
    if summary == "Policy-backed version rules are declared" {
        return String::from("Approved version policy is configured");
    }
    if summary == "Policy-backed provisioning sources are declared" {
        return String::from("Approved provisioning sources are configured");
    }
    if let Some((backend, name)) = container_provisioning_backend_and_name(summary) {
        return format!(
            "{} cannot be provisioned through `{backend}` in container mode",
            title_case_word(name)
        );
    }
    if let Some(tool) = summary.strip_prefix("Missing tool: ")
        && container_image.is_some()
        && why.contains("not available inside the configured")
    {
        return format!(
            "{} is missing from the configured container image",
            title_case_word(tool)
        );
    }
    if let Some(runtime) = summary.strip_prefix("Missing runtime: ")
        && container_image.is_some()
        && why.contains("not available inside the configured")
    {
        return format!(
            "{} is missing from the configured container image",
            title_case_word(runtime)
        );
    }
    summary.to_string()
}

fn split_top_level_policy_items(input: &str) -> Vec<String> {
    let mut items = Vec::new();
    let mut start = 0usize;
    let mut depth = 0usize;
    let bytes = input.as_bytes();
    let mut index = 0usize;

    while index + 1 < bytes.len() {
        match bytes[index] {
            b'(' => depth += 1,
            b')' => depth = depth.saturating_sub(1),
            b',' if depth == 0 && bytes[index + 1] == b' ' => {
                let item = input[start..index].trim();
                if !item.is_empty() {
                    items.push(item.to_string());
                }
                start = index + 2;
                index += 1;
            }
            _ => {}
        }
        index += 1;
    }

    let tail = input[start..].trim();
    if !tail.is_empty() {
        items.push(tail.to_string());
    }

    items
}

fn declared_policy_items(summary: &str, why: &str) -> Option<Vec<String>> {
    let (_, declared) = why.split_once(": ")?;
    let declared = match summary {
        "Policy-backed provisioning sources are declared" => declared
            .split_once(". This repo's declared prerequisites can be provisioned through: ")
            .map(|(sources, _)| sources)
            .unwrap_or(declared),
        _ => declared,
    };
    Some(split_top_level_policy_items(declared))
}

fn policy_surface_bullets(summary: &str, why: &str, lead: &str) -> Option<Vec<String>> {
    let declared = declared_policy_items(summary, why)?;
    let mut lines = vec![lead.to_string()];
    lines.extend(declared.into_iter().map(|item| {
        if let Some((subject, adapter)) = item.split_once(" via ") {
            format!("{subject} via `{adapter}`")
        } else {
            item.to_string()
        }
    }));
    Some(lines)
}

fn finding_why_lines(summary: &str, why: &str, container_image: Option<&str>) -> Vec<String> {
    if summary == "Adapter bootstrap sources are declared" {
        return policy_surface_bullets(
            summary,
            why,
            "`.ota/org-policy.yaml` approves bootstrap for missing adapter binaries",
        )
        .unwrap_or_else(|| vec![why.to_string()]);
    }
    if summary == "Policy-backed version rules are declared" {
        return policy_surface_bullets(
            summary,
            why,
            "`.ota/org-policy.yaml` approves repo version rules",
        )
        .map(|lines| {
            let mut rendered = Vec::with_capacity(lines.len());
            if let Some((first, rest)) = lines.split_first() {
                rendered.push(first.clone());
                rendered.extend(rest.iter().map(|item| formatted_version_policy_item(item)));
            }
            rendered
        })
        .unwrap_or_else(|| vec![why.to_string()]);
    }
    if summary == "Policy-backed provisioning sources are declared" {
        return policy_surface_bullets(
            summary,
            why,
            "`.ota/org-policy.yaml` approves provisioning for declared repo prerequisites",
        )
        .unwrap_or_else(|| vec![why.to_string()]);
    }
    if let Some((backend, _)) = container_provisioning_backend_and_name(summary)
        && let Some(lines) = container_provisioning_why_lines(why, backend)
    {
        return lines;
    }
    if let Some(tool) = summary.strip_prefix("Missing tool: ")
        && container_image.is_some()
        && why.contains("not available inside the configured")
    {
        return vec![
            format!("`{tool}` is declared in the contract"),
            String::from("it is not available in the configured container image"),
            format!(
                "`execution.backends.container.image = {}`",
                container_image.unwrap_or_default()
            ),
        ];
    }
    if let Some(runtime) = summary.strip_prefix("Missing runtime: ")
        && container_image.is_some()
        && why.contains("not available inside the configured")
    {
        return vec![
            format!("`{runtime}` is declared in the contract"),
            String::from("it is not available in the configured container image"),
            format!(
                "`execution.backends.container.image = {}`",
                container_image.unwrap_or_default()
            ),
        ];
    }
    vec![why.to_string()]
}

fn single_finding_display_count(summary: &str, why: &str) -> usize {
    match summary {
        "Policy-backed version rules are declared"
        | "Policy-backed provisioning sources are declared"
        | "Adapter bootstrap sources are declared" => declared_policy_items(summary, why)
            .map(|items| items.len())
            .unwrap_or(1),
        _ => 1,
    }
}

fn finding_next_steps(next: &str) -> Vec<String> {
    if let Some((first, rerun)) = next.split_once(", then rerun ") {
        return vec![first.trim().to_string(), format!("rerun {}", rerun.trim())];
    }
    if let Some((first, rerun)) = next.split_once(" and rerun ") {
        return vec![first.trim().to_string(), format!("rerun {}", rerun.trim())];
    }
    if let Some((first, alternative)) = next.split_once(", or ") {
        return vec![first.trim().to_string(), alternative.trim().to_string()];
    }
    vec![next.to_string()]
}

fn parse_depends_on_boundary_summary(summary: &str) -> Option<(&str, &str)> {
    let summary = summary.strip_prefix("Task `")?;
    let (parent, rest) = summary.split_once("` depends_on `")?;
    let dependency = rest.strip_suffix("` across different execution boundaries")?;
    Some((parent, dependency))
}

fn parse_depends_on_boundary_drift(why: &str) -> Option<&str> {
    let (_, rest) = why.split_once("edge (")?;
    let (drift, _) = rest.split_once(") so ")?;
    Some(drift)
}

fn concise_depends_on_boundary_why(drift: &str) -> &'static str {
    if drift.contains("context:") || drift.contains("backend:") {
        return "only durable external side effects survive this edge";
    }
    "in-process and container-local prep does not carry across"
}

fn render_depends_on_boundary_doctor_finding(
    output: &mut String,
    severity: FindingSeverity,
    summary: &str,
    why: &str,
    next: &str,
    contract_path: Option<&Path>,
) -> bool {
    let Some((parent, dependency)) = parse_depends_on_boundary_summary(summary) else {
        return false;
    };
    let Some(drift) = parse_depends_on_boundary_drift(why) else {
        return false;
    };

    output.push_str(&format!(
        "{}  {}",
        render_severity(severity),
        render_finding_summary_with_count(severity, &format!("`{parent}` → `{dependency}`"), 1),
    ));
    append_finding_section(
        output,
        "Why:",
        &[concise_depends_on_boundary_why(drift).to_string()],
        severity,
        contract_path,
    );
    append_finding_section(
        output,
        "Drift:",
        &[drift.replace(" -> ", " → ")],
        severity,
        contract_path,
    );
    append_finding_section(
        output,
        "Next:",
        &[next.to_string()],
        severity,
        contract_path,
    );
    true
}

fn append_error_detail_section(
    output: &mut String,
    label: &str,
    items: &[String],
    contract_path: Option<&Path>,
) {
    if items.len() == 1 {
        append_wrapped_labeled_text(
            output,
            label,
            &items[0],
            "",
            DOCTOR_DETAIL_WRAP_WIDTH,
            label == "Next:",
            error_key,
            |value| render_backticked_text(value, contract_path),
        );
        return;
    }
    output.push_str(&format!("\n{}", error_key(label)));
    for item in items {
        output.push_str(&format!(
            "\n  {} {}",
            finding_detail_bullet(FindingSeverity::Error),
            render_backticked_text(item, contract_path),
        ));
    }
}

fn append_finding_section(
    output: &mut String,
    label: &str,
    items: &[String],
    severity: FindingSeverity,
    contract_path: Option<&Path>,
) {
    if items.len() == 1 {
        append_wrapped_labeled_text(
            output,
            label,
            &items[0],
            "",
            DOCTOR_DETAIL_WRAP_WIDTH,
            label == "Next:",
            |key| finding_detail_key(severity, key),
            |value| render_backticked_text(value, contract_path),
        );
        return;
    }
    output.push_str(&format!("\n{}", finding_detail_key(severity, label)));
    for item in items {
        output.push_str(&format!(
            "\n  {} {}",
            finding_detail_bullet(severity),
            render_backticked_text(item, contract_path),
        ));
    }
}

fn render_primary_finding_text_with_next_rewriter(
    severity: FindingSeverity,
    summary: &str,
    why: &str,
    next: &str,
    provenance: Option<String>,
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
    contract_path: Option<&Path>,
    rewrite_next: fn(&str, Option<DoctorMode>, Option<Lifecycle>) -> String,
) -> String {
    let mut stdout = String::new();
    let (display_why, display_next, container_image) =
        render_container_image_finding_text(why, next, doctor_mode);
    let diagnosis = finding_diagnosis_text(summary, &display_why, container_image.as_deref());
    let why_lines = finding_why_lines(summary, &display_why, container_image.as_deref());
    let next_steps =
        finding_next_steps(&rewrite_next(&display_next, doctor_mode, doctor_lifecycle));
    let (marker, title_color, title) = match severity {
        FindingSeverity::Error => (
            primary_error_marker(),
            "1;38;2;255;168;168",
            "Primary Blocker",
        ),
        FindingSeverity::Warn => (
            primary_warn_marker(),
            "1;38;2;245;227;179",
            "Primary Finding",
        ),
        FindingSeverity::Info => (
            primary_info_marker(),
            "1;38;2;180;229;235",
            "Primary Finding",
        ),
    };
    stdout.push_str(&format!(
        "{} {} {}",
        marker,
        paint(
            match severity {
                FindingSeverity::Error => title,
                FindingSeverity::Warn => "WARN",
                FindingSeverity::Info => "INFO",
            },
            title_color
        ),
        render_finding_summary_with_count(
            severity,
            &diagnosis,
            single_finding_display_count(summary, &display_why),
        )
    ));
    if !concise_mode() {
        append_finding_section(&mut stdout, "Why:", &why_lines, severity, contract_path);
    }
    if let Some(provenance) = provenance.as_deref() {
        append_wrapped_labeled_text(
            &mut stdout,
            "Provenance:",
            provenance,
            "",
            DOCTOR_DETAIL_WRAP_WIDTH,
            false,
            paint_key,
            |value| render_backticked_text(value, contract_path),
        );
    }
    append_finding_section(&mut stdout, "Next:", &next_steps, severity, contract_path);
    stdout
}

fn render_primary_finding_text(
    severity: FindingSeverity,
    summary: &str,
    why: &str,
    next: &str,
    provenance: Option<String>,
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
    contract_path: Option<&Path>,
) -> String {
    render_primary_finding_text_with_next_rewriter(
        severity,
        summary,
        why,
        next,
        provenance,
        doctor_mode,
        doctor_lifecycle,
        contract_path,
        rewrite_doctor_mode_command,
    )
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum DoctorFindingGroupKind {
    ToolingVersion,
    AdapterBootstrap,
    EnvironmentValue,
    NativePrerequisite,
    ContractDrift,
    PolicySurface,
    ServiceHealth,
    CheckFailure,
    ExecutionBackend,
    SharedAction(String),
}

struct DoctorFindingGroup<'a> {
    group_key: String,
    action_key: String,
    kind: DoctorFindingGroupKind,
    severity: FindingSeverity,
    findings: Vec<&'a Finding>,
}

fn group_doctor_findings<'a, I>(findings: I) -> Vec<DoctorFindingGroup<'a>>
where
    I: IntoIterator<Item = &'a Finding>,
{
    let mut groups: Vec<DoctorFindingGroup<'a>> = Vec::new();

    for finding in findings {
        let kind = doctor_finding_group_kind(finding);
        let group_key = doctor_finding_group_key(finding);
        let action_key = doctor_finding_action_key(finding);
        if let Some(group) = groups.iter_mut().find(|group| group.group_key == group_key) {
            group.severity = group.severity.max(finding.severity);
            if !matches!(group.kind, DoctorFindingGroupKind::SharedAction(_)) && group.kind != kind
            {
                group.kind = DoctorFindingGroupKind::SharedAction(group_key.clone());
            }
            group.findings.push(finding);
            continue;
        }

        groups.push(DoctorFindingGroup {
            group_key,
            action_key,
            kind,
            severity: finding.severity,
            findings: vec![finding],
        });
    }

    groups
}

fn doctor_finding_group_summaries<'a, I>(
    findings: I,
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
) -> Vec<DoctorFindingGroupSummary>
where
    I: IntoIterator<Item = &'a Finding>,
{
    group_doctor_findings(findings)
        .into_iter()
        .map(|group| {
            let display_items = doctor_finding_group_display_items(&group);
            DoctorFindingGroupSummary {
                action_key: group.action_key.clone(),
                action_title: doctor_finding_group_title(&group.kind, &group.findings),
                action_next: doctor_finding_group_next(
                    &group.kind,
                    &group.findings,
                    doctor_mode,
                    doctor_lifecycle,
                ),
                count: display_items.len(),
            }
        })
        .collect()
}

fn doctor_finding_subject(finding: &Finding) -> &str {
    finding
        .summary
        .split_once(": ")
        .map(|(_, value)| value)
        .unwrap_or(&finding.summary)
}

fn doctor_code_group_slug(code: &str) -> String {
    doctor_group_slug(code.trim_start_matches("OTA_"))
}

fn doctor_finding_group_key(finding: &Finding) -> String {
    let summary = finding.summary.as_str();
    match finding.code() {
        "OTA_RUNTIME_VERSION_MISMATCH"
        | "OTA_RUNTIME_MISSING"
        | "OTA_RUNTIME_PROBE_FAILED"
        | "OTA_RUNTIME_VERSION_UNPARSEABLE"
        | "OTA_TOOL_VERSION_MISMATCH"
        | "OTA_TOOL_MISSING"
        | "OTA_TOOL_PROBE_FAILED"
        | "OTA_TOOL_VERSION_UNPARSEABLE" => String::from("tooling-version"),
        "OTA_NATIVE_PREREQUISITE_MISSING" | "OTA_NATIVE_PREREQUISITE_TIMED_OUT" => {
            String::from("native-prerequisite")
        }
        _ if summary.starts_with("Adapter bootstrap failed: ") => String::from("adapter-bootstrap"),
        "OTA_ENV_MISSING" => String::from("environment-missing"),
        "OTA_ENV_INVALID" => String::from("environment-invalid"),
        "OTA_CONTRACT_DRIFT" => String::from("contract-drift"),
        "OTA_POLICY_PROVISIONING_PACKAGE_MAPPING_MISSING" => String::from("policy-surface"),
        "OTA_POLICY_NATIVE_PACKAGE_NOT_APPROVED" => String::from("policy-native-package"),
        "OTA_POLICY_BACKED_PROVISIONING_DECLARED"
        | "OTA_POLICY_BACKED_ADAPTER_BOOTSTRAP_DECLARED" => String::from("policy-surface"),
        "OTA_BACKEND_CLI_MISSING" | "OTA_CONTAINER_BACKEND_CLI_MISSING" => {
            String::from("execution-backend")
        }
        "OTA_DOCTOR_FINDING_UNKNOWN"
            if summary == "Policy-backed provisioning sources are declared"
                || summary == "Adapter bootstrap sources are declared" =>
        {
            String::from("policy-surface")
        }
        "OTA_SERVICE_CHECK_FAILED" => format!(
            "service-health-failed-{}",
            doctor_group_slug(doctor_finding_subject(finding))
        ),
        "OTA_SERVICE_CHECK_TIMED_OUT" => format!(
            "service-health-timeout-{}",
            doctor_group_slug(doctor_finding_subject(finding))
        ),
        "OTA_SERVICE_UNVERIFIABLE" => format!(
            "service-health-unverifiable-{}",
            doctor_group_slug(doctor_finding_subject(finding))
        ),
        "OTA_CHECK_FAILED" | "OTA_FILE_CHECK_FAILED" => format!(
            "check-failed-{}",
            doctor_group_slug(doctor_finding_subject(finding))
        ),
        "OTA_CHECK_TIMED_OUT" | "OTA_FILE_CHECK_TIMED_OUT" => format!(
            "check-timeout-{}",
            doctor_group_slug(doctor_finding_subject(finding))
        ),
        _ => {
            let summary_key = doctor_group_slug(&compact_backticked_paths(&finding.summary));
            let code_key = doctor_code_group_slug(finding.code());
            if summary_key.is_empty() {
                code_key
            } else {
                format!("{code_key}-{summary_key}")
            }
        }
    }
}

fn doctor_finding_action_key(finding: &Finding) -> String {
    let summary = finding.summary.as_str();
    match finding.code() {
        "OTA_RUNTIME_VERSION_MISMATCH"
        | "OTA_RUNTIME_MISSING"
        | "OTA_RUNTIME_PROBE_FAILED"
        | "OTA_RUNTIME_VERSION_UNPARSEABLE"
        | "OTA_TOOL_VERSION_MISMATCH"
        | "OTA_TOOL_MISSING"
        | "OTA_TOOL_PROBE_FAILED"
        | "OTA_TOOL_VERSION_UNPARSEABLE" => String::from("tooling-version"),
        "OTA_NATIVE_PREREQUISITE_MISSING" | "OTA_NATIVE_PREREQUISITE_TIMED_OUT" => {
            String::from("native-prerequisite")
        }
        _ if summary.starts_with("Adapter bootstrap failed: ") => String::from("adapter-bootstrap"),
        "OTA_ENV_MISSING" => String::from("environment-missing"),
        "OTA_ENV_INVALID" => String::from("environment-invalid"),
        "OTA_CONTRACT_DRIFT" => String::from("contract-drift"),
        "OTA_POLICY_PROVISIONING_PACKAGE_MAPPING_MISSING" => String::from("policy-surface"),
        "OTA_POLICY_NATIVE_PACKAGE_NOT_APPROVED" => String::from("policy-native-package"),
        "OTA_POLICY_BACKED_PROVISIONING_DECLARED"
        | "OTA_POLICY_BACKED_ADAPTER_BOOTSTRAP_DECLARED" => String::from("policy-surface"),
        "OTA_BACKEND_CLI_MISSING" | "OTA_CONTAINER_BACKEND_CLI_MISSING" => {
            String::from("execution-backend")
        }
        "OTA_DOCTOR_FINDING_UNKNOWN"
            if summary == "Policy-backed provisioning sources are declared"
                || summary == "Adapter bootstrap sources are declared" =>
        {
            String::from("policy-surface")
        }
        "OTA_SERVICE_CHECK_FAILED" => format!(
            "service-health-failed-{}",
            doctor_group_slug(doctor_finding_subject(finding))
        ),
        "OTA_SERVICE_CHECK_TIMED_OUT" => format!(
            "service-health-timeout-{}",
            doctor_group_slug(doctor_finding_subject(finding))
        ),
        "OTA_SERVICE_UNVERIFIABLE" => format!(
            "service-health-unverifiable-{}",
            doctor_group_slug(doctor_finding_subject(finding))
        ),
        "OTA_CHECK_FAILED" | "OTA_FILE_CHECK_FAILED" => format!(
            "check-failed-{}",
            doctor_group_slug(doctor_finding_subject(finding))
        ),
        "OTA_CHECK_TIMED_OUT" | "OTA_FILE_CHECK_TIMED_OUT" => format!(
            "check-timeout-{}",
            doctor_group_slug(doctor_finding_subject(finding))
        ),
        _ => doctor_code_group_slug(finding.code()),
    }
}

fn doctor_finding_group_kind(finding: &Finding) -> DoctorFindingGroupKind {
    let summary = finding.summary.as_str();
    match finding.code() {
        "OTA_RUNTIME_VERSION_MISMATCH"
        | "OTA_RUNTIME_MISSING"
        | "OTA_RUNTIME_PROBE_FAILED"
        | "OTA_RUNTIME_VERSION_UNPARSEABLE"
        | "OTA_TOOL_VERSION_MISMATCH"
        | "OTA_TOOL_MISSING"
        | "OTA_TOOL_PROBE_FAILED"
        | "OTA_TOOL_VERSION_UNPARSEABLE" => DoctorFindingGroupKind::ToolingVersion,
        "OTA_NATIVE_PREREQUISITE_MISSING" | "OTA_NATIVE_PREREQUISITE_TIMED_OUT" => {
            DoctorFindingGroupKind::NativePrerequisite
        }
        _ if summary.starts_with("Adapter bootstrap failed: ") => {
            DoctorFindingGroupKind::AdapterBootstrap
        }
        "OTA_ENV_MISSING" | "OTA_ENV_INVALID" => DoctorFindingGroupKind::EnvironmentValue,
        "OTA_CONTRACT_DRIFT" => DoctorFindingGroupKind::ContractDrift,
        "OTA_POLICY_PACK_VIOLATION"
        | "OTA_POLICY_PACK_INVALID"
        | "OTA_POLICY_NATIVE_PACKAGE_NOT_APPROVED"
        | "OTA_POLICY_PROVISIONING_PACKAGE_MAPPING_MISSING"
        | "OTA_POLICY_BACKED_PROVISIONING_DECLARED"
        | "OTA_POLICY_BACKED_ADAPTER_BOOTSTRAP_DECLARED" => DoctorFindingGroupKind::PolicySurface,
        "OTA_SERVICE_CHECK_FAILED" | "OTA_SERVICE_CHECK_TIMED_OUT" | "OTA_SERVICE_UNVERIFIABLE" => {
            DoctorFindingGroupKind::ServiceHealth
        }
        "OTA_CHECK_FAILED"
        | "OTA_CHECK_TIMED_OUT"
        | "OTA_FILE_CHECK_FAILED"
        | "OTA_FILE_CHECK_TIMED_OUT" => DoctorFindingGroupKind::CheckFailure,
        "OTA_BACKEND_CLI_MISSING" | "OTA_CONTAINER_BACKEND_CLI_MISSING" => {
            DoctorFindingGroupKind::ExecutionBackend
        }
        "OTA_DOCTOR_FINDING_UNKNOWN"
            if summary == "Policy-backed provisioning sources are declared"
                || summary == "Adapter bootstrap sources are declared" =>
        {
            DoctorFindingGroupKind::PolicySurface
        }
        _ => DoctorFindingGroupKind::SharedAction(compact_backticked_paths(&finding.next)),
    }
}

fn doctor_group_slug(value: &str) -> String {
    let mut slug = String::new();
    let mut last_dash = false;
    for ch in value.chars().flat_map(|ch| ch.to_lowercase()) {
        if ch.is_ascii_alphanumeric() {
            slug.push(ch);
            last_dash = false;
        } else if !last_dash && !slug.is_empty() {
            slug.push('-');
            last_dash = true;
        }
    }
    while slug.ends_with('-') {
        slug.pop();
    }
    slug
}

fn doctor_group_provenance(group: &DoctorFindingGroup<'_>) -> Option<String> {
    let mut entries = group.findings.iter().map(|finding| {
        finding
            .provenance()
            .zip(finding.provenance_key())
            .map(|(provenance, key)| (provenance, key))
    });
    let first = entries.next().flatten()?;
    if entries.all(|entry| entry == Some((first.0.clone(), first.1.clone()))) {
        Some(first.0)
    } else {
        None
    }
}

fn render_grouped_doctor_findings(
    group: &DoctorFindingGroup<'_>,
    contract_path: Option<&Path>,
    doctor_mode: Option<DoctorMode>,
) -> String {
    let display_items = doctor_finding_group_display_items(group);
    let mut stdout = String::from("\n\n");
    stdout.push_str(&format!(
        "{}  {} {}",
        render_severity(group.severity),
        render_finding_summary(
            group.severity,
            &doctor_finding_group_title(&group.kind, &group.findings),
        ),
        paint_group_meta(&format!("({})", display_items.len()))
    ));
    if !concise_mode() {
        append_wrapped_labeled_text(
            &mut stdout,
            "Why:",
            &doctor_finding_group_why(&group.kind, &group.findings),
            "",
            DOCTOR_DETAIL_WRAP_WIDTH,
            false,
            paint_key,
            |value| render_backticked_text(value, contract_path),
        );
    }
    if let Some(source) = group
        .findings
        .iter()
        .find_map(|finding| policy_finding_source(&finding.summary, &finding.why))
    {
        stdout.push_str(&format!(
            "\n{} {}",
            finding_detail_key(group.severity, "Source:"),
            source
        ));
    }
    if let Some(provenance) = doctor_group_provenance(group) {
        stdout.push_str(&format!(
            "\n{} {}",
            finding_detail_key(group.severity, "Provenance:"),
            provenance
        ));
    }
    for item in display_items {
        append_wrapped_bullet_text(
            &mut stdout,
            finding_detail_bullet(group.severity),
            &item,
            "  ",
            84,
            |value| render_backticked_text(value, contract_path),
        );
    }
    append_wrapped_labeled_text(
        &mut stdout,
        "Next:",
        &doctor_finding_group_next(&group.kind, &group.findings, doctor_mode, None),
        "",
        DOCTOR_DETAIL_WRAP_WIDTH,
        true,
        |key| finding_detail_key(group.severity, key),
        |value| render_backticked_text(value, contract_path),
    );
    stdout
}

fn tooling_group_has_missing(findings: &[&Finding]) -> bool {
    findings
        .iter()
        .any(|finding| matches!(finding.code(), "OTA_RUNTIME_MISSING" | "OTA_TOOL_MISSING"))
}

fn tooling_group_has_probe_issues(findings: &[&Finding]) -> bool {
    findings.iter().any(|finding| {
        matches!(
            finding.code(),
            "OTA_RUNTIME_PROBE_FAILED"
                | "OTA_RUNTIME_VERSION_UNPARSEABLE"
                | "OTA_TOOL_PROBE_FAILED"
                | "OTA_TOOL_VERSION_UNPARSEABLE"
        )
    })
}

fn tooling_group_has_version_mismatches(findings: &[&Finding]) -> bool {
    findings.iter().any(|finding| {
        matches!(
            finding.code(),
            "OTA_RUNTIME_VERSION_MISMATCH" | "OTA_TOOL_VERSION_MISMATCH"
        )
    })
}

fn doctor_finding_group_title(kind: &DoctorFindingGroupKind, findings: &[&Finding]) -> String {
    let has_missing_tooling = tooling_group_has_missing(findings);
    let has_probe_issues = tooling_group_has_probe_issues(findings);
    let has_missing_env = findings
        .iter()
        .any(|finding| finding.code() == "OTA_ENV_MISSING");
    let has_invalid_env = findings
        .iter()
        .any(|finding| finding.code() == "OTA_ENV_INVALID");
    match kind {
        DoctorFindingGroupKind::ToolingVersion if has_missing_tooling => {
            String::from("Install required runtimes and tools")
        }
        DoctorFindingGroupKind::ToolingVersion if has_probe_issues => {
            String::from("Diagnose runtime and tool probes")
        }
        DoctorFindingGroupKind::ToolingVersion => String::from("Fix version mismatches"),
        DoctorFindingGroupKind::AdapterBootstrap => String::from("Adapter bootstrap failed"),
        DoctorFindingGroupKind::EnvironmentValue if has_missing_env && !has_invalid_env => {
            String::from("Set missing environment variables")
        }
        DoctorFindingGroupKind::EnvironmentValue if has_invalid_env && !has_missing_env => {
            String::from("Fix invalid environment values")
        }
        DoctorFindingGroupKind::EnvironmentValue => String::from("Fix environment values"),
        DoctorFindingGroupKind::NativePrerequisite => String::from("Install native prerequisites"),
        DoctorFindingGroupKind::ContractDrift => String::from("Review contract drift"),
        DoctorFindingGroupKind::PolicySurface => String::from("Review active policy surfaces"),
        DoctorFindingGroupKind::ServiceHealth => String::from("Fix service readiness"),
        DoctorFindingGroupKind::CheckFailure => String::from("Review checks"),
        DoctorFindingGroupKind::ExecutionBackend => {
            String::from("Install required execution backend")
        }
        DoctorFindingGroupKind::SharedAction(_) => String::from("Shared action"),
    }
}

fn doctor_finding_group_why(kind: &DoctorFindingGroupKind, findings: &[&Finding]) -> String {
    let has_missing_tooling = tooling_group_has_missing(findings);
    let has_probe_issues = tooling_group_has_probe_issues(findings);
    let has_missing_env = findings
        .iter()
        .any(|finding| finding.code() == "OTA_ENV_MISSING");
    let has_invalid_env = findings
        .iter()
        .any(|finding| finding.code() == "OTA_ENV_INVALID");
    match kind {
        DoctorFindingGroupKind::ToolingVersion if has_missing_tooling && has_probe_issues => {
            String::from(
                "one or more required runtimes or tools are missing, unprobeable, or do not match the contract",
            )
        }
        DoctorFindingGroupKind::ToolingVersion if has_missing_tooling => String::from(
            "one or more required runtimes or tools are missing or do not match the contract",
        ),
        DoctorFindingGroupKind::ToolingVersion if has_probe_issues => String::from(
            "one or more runtime or tool probes failed or returned unparseable versions",
        ),
        DoctorFindingGroupKind::ToolingVersion => {
            String::from("one or more runtime or tool entries do not match the contract")
        }
        DoctorFindingGroupKind::AdapterBootstrap => findings
            .first()
            .map(|finding| compact_backticked_paths(&finding.why))
            .unwrap_or_else(|| String::from("one or more adapter bootstrap paths failed")),
        DoctorFindingGroupKind::EnvironmentValue if has_missing_env && !has_invalid_env => {
            String::from("one or more required environment variables are not set")
        }
        DoctorFindingGroupKind::EnvironmentValue if has_invalid_env && !has_missing_env => {
            String::from("one or more environment values do not satisfy the contract")
        }
        DoctorFindingGroupKind::EnvironmentValue => {
            String::from("one or more environment values do not match the contract")
        }
        DoctorFindingGroupKind::NativePrerequisite => {
            String::from("one or more selected workflow tasks need host-native prerequisites")
        }
        DoctorFindingGroupKind::ContractDrift => {
            String::from("repo signals no longer match the declared contract")
        }
        DoctorFindingGroupKind::PolicySurface => String::from(
            "the active policy exposes approved version, provisioning, or bootstrap surfaces",
        ),
        DoctorFindingGroupKind::ServiceHealth => {
            String::from("one or more services failed readiness checks")
        }
        DoctorFindingGroupKind::CheckFailure => String::from("one or more checks failed"),
        DoctorFindingGroupKind::ExecutionBackend => {
            String::from("a required execution backend CLI is missing")
        }
        DoctorFindingGroupKind::SharedAction(_) => {
            String::from("multiple findings share the same remediation")
        }
    }
}

fn doctor_finding_group_next(
    kind: &DoctorFindingGroupKind,
    findings: &[&Finding],
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
) -> String {
    let has_missing_tooling = tooling_group_has_missing(findings);
    let has_probe_issues = tooling_group_has_probe_issues(findings);
    let has_version_mismatch = tooling_group_has_version_mismatches(findings);
    let has_missing_env = findings
        .iter()
        .any(|finding| finding.code() == "OTA_ENV_MISSING");
    let has_invalid_env = findings
        .iter()
        .any(|finding| finding.code() == "OTA_ENV_INVALID");
    let has_provisioning_surface = findings
        .iter()
        .any(|finding| finding.summary == "Policy-backed provisioning sources are declared");
    let next = match kind {
        DoctorFindingGroupKind::ToolingVersion
            if has_missing_tooling && has_probe_issues && has_version_mismatch =>
        {
            String::from(
                "install the missing runtimes and tools, fix the listed probes, align any mismatched versions, then rerun `ota doctor`",
            )
        }
        DoctorFindingGroupKind::ToolingVersion if has_missing_tooling && has_version_mismatch => {
            String::from("install or align the listed runtimes and tools, then rerun `ota doctor`")
        }
        DoctorFindingGroupKind::ToolingVersion if has_missing_tooling && has_probe_issues => {
            String::from(
                "install the missing runtimes and tools, fix the listed probes, then rerun `ota doctor`",
            )
        }
        DoctorFindingGroupKind::ToolingVersion if has_missing_tooling => {
            String::from("install the listed runtimes and tools, then rerun `ota doctor`")
        }
        DoctorFindingGroupKind::ToolingVersion if has_probe_issues && has_version_mismatch => {
            String::from(
                "fix the listed runtime and tool probes, align any mismatched versions, then rerun `ota doctor`",
            )
        }
        DoctorFindingGroupKind::ToolingVersion if has_probe_issues => String::from(
            "run the listed version probes directly, fix the resolved executables, then rerun `ota doctor`",
        ),
        DoctorFindingGroupKind::ToolingVersion => {
            String::from("install compatible runtimes and tools, then rerun `ota doctor`")
        }
        DoctorFindingGroupKind::AdapterBootstrap => findings
            .first()
            .map(|finding| compact_backticked_paths(&finding.next))
            .unwrap_or_else(|| String::from("rerun `ota up`")),
        DoctorFindingGroupKind::EnvironmentValue if has_missing_env && !has_invalid_env => {
            String::from(
                "run `ota env` to inspect the current precedence, set the listed environment variables, then rerun `ota doctor`",
            )
        }
        DoctorFindingGroupKind::EnvironmentValue if has_invalid_env && !has_missing_env => {
            String::from(
                "run `ota env` to inspect the current precedence, set the listed environment variables to allowed values, then rerun `ota doctor`",
            )
        }
        DoctorFindingGroupKind::EnvironmentValue => String::from(
            "run `ota env` to inspect the current precedence, fix the listed environment values, then rerun `ota doctor`",
        ),
        DoctorFindingGroupKind::NativePrerequisite => findings
            .first()
            .map(|finding| compact_backticked_paths(&finding.next))
            .unwrap_or_else(|| {
                String::from("install the native prerequisites, then rerun `ota doctor`")
            }),
        DoctorFindingGroupKind::ContractDrift => String::from(
            "run `ota detect --candidate-out .ota/candidates/detect.json .` to publish the reviewable additions; stale removals remain unapplied",
        ),
        DoctorFindingGroupKind::PolicySurface if has_provisioning_surface => String::from(
            "use `ota policy review` to inspect the active policy source, or keep these approved sources in mind when provisioning or bootstrap needs a governed path",
        ),
        DoctorFindingGroupKind::PolicySurface => String::from(
            "use `ota policy review` to inspect the active policy source, or keep these approved bootstrap surfaces in mind when adapter install needs approval or audit",
        ),
        DoctorFindingGroupKind::ServiceHealth | DoctorFindingGroupKind::CheckFailure => findings
            .first()
            .map(|finding| compact_backticked_paths(&finding.next))
            .unwrap_or_default(),
        DoctorFindingGroupKind::ExecutionBackend => {
            String::from("install a supported execution backend CLI, then rerun `ota doctor`")
        }
        DoctorFindingGroupKind::SharedAction(_) => findings
            .first()
            .map(|finding| compact_backticked_paths(&finding.next))
            .unwrap_or_default(),
    };

    rewrite_doctor_mode_command(&next, doctor_mode, doctor_lifecycle)
}

fn rewrite_doctor_mode_command(
    next: &str,
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
) -> String {
    let Some(command) = doctor_selected_command(doctor_mode, doctor_lifecycle) else {
        return next.to_string();
    };
    let mut sources = vec!["ota doctor"];
    match doctor_mode {
        Some(DoctorMode::Container) => sources.push("ota doctor --mode container"),
        Some(DoctorMode::Remote) => sources.push("ota doctor --mode remote"),
        Some(DoctorMode::Native) => sources.push("ota doctor --mode native"),
        None => {}
    }
    sources
        .into_iter()
        .fold(next.to_string(), |rewritten, source| {
            rewritten.replace(&format!("`{source}`"), &format!("`{command}`"))
        })
}

fn rewrite_repo_scoped_command_targets(next: &str, contract_path: &Path) -> String {
    [
        "ota doctor --mode container",
        "ota doctor --mode remote",
        "ota doctor --mode native",
        "ota doctor",
        "ota policy review",
        "ota up --mode container",
        "ota up --mode remote",
        "ota up --mode native",
        "ota up",
    ]
    .into_iter()
    .fold(next.to_string(), |rewritten, command| {
        let source = format!("`{command}`");
        let target = format!(
            "`{}`",
            command_for_repo_contract_target(command, contract_path)
        );
        rewritten.replace(&source, &target)
    })
}

fn rewrite_doctor_findings_for_contract(
    findings: &[Finding],
    contract_path: &Path,
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
) -> Vec<Finding> {
    findings
        .iter()
        .cloned()
        .map(|mut finding| {
            let next = rewrite_doctor_mode_command(&finding.next, doctor_mode, doctor_lifecycle);
            finding.next = rewrite_repo_scoped_command_targets(&next, contract_path);
            finding
        })
        .collect()
}

fn rewrite_up_preview_next_command(
    next: &str,
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
) -> String {
    let next = rewrite_doctor_mode_command(next, doctor_mode, doctor_lifecycle);
    let target = up_preview_selected_command(doctor_mode, doctor_lifecycle);
    let mut sources = vec![String::from("ota doctor")];
    if let Some(mode) = doctor_mode {
        sources.push(
            match mode {
                DoctorMode::Container => "ota doctor --mode container",
                DoctorMode::Remote => "ota doctor --mode remote",
                DoctorMode::Native => "ota doctor --mode native",
            }
            .to_string(),
        );
    }
    if let Some(selected_doctor_command) = doctor_selected_command(doctor_mode, doctor_lifecycle) {
        sources.push(selected_doctor_command);
    }
    sources.sort();
    sources.dedup();
    sources.into_iter().fold(next, |rewritten, source| {
        rewritten.replace(&format!("`{source}`"), &format!("`{target}`"))
    })
}

fn doctor_finding_group_display_items(group: &DoctorFindingGroup<'_>) -> Vec<String> {
    let include_tooling_commands = matches!(group.kind, DoctorFindingGroupKind::ToolingVersion)
        && group
            .findings
            .iter()
            .map(|finding| finding.next.as_str())
            .collect::<BTreeSet<_>>()
            .len()
            > 1;
    let mut items = Vec::new();
    for finding in &group.findings {
        let item = doctor_finding_group_item_text(&group.kind, finding, include_tooling_commands);
        if !items.contains(&item) {
            items.push(item);
        }
    }
    items
}

fn doctor_finding_group_item_text(
    kind: &DoctorFindingGroupKind,
    finding: &Finding,
    include_command_hint: bool,
) -> String {
    let subject = finding
        .summary
        .split_once(": ")
        .map(|(_, value)| value)
        .unwrap_or(&finding.summary);
    match kind {
        DoctorFindingGroupKind::ToolingVersion => {
            let command_hint = if include_command_hint {
                explicit_run_command(&finding.next)
                    .map(|command| format!("; run `{command}`"))
                    .unwrap_or_default()
            } else {
                String::new()
            };
            if matches!(finding.code(), "OTA_RUNTIME_MISSING" | "OTA_TOOL_MISSING") {
                return format!("{subject} is missing{command_hint}");
            }
            if matches!(
                finding.code(),
                "OTA_RUNTIME_PROBE_FAILED" | "OTA_TOOL_PROBE_FAILED"
            ) {
                let tokens = backticked_tokens(&finding.why);
                return match tokens.as_slice() {
                    [path, command, ..] => {
                        format!("{subject} probe failed via `{path}` using `{command}`")
                    }
                    _ => format!("{subject} probe failed"),
                };
            }
            if matches!(
                finding.code(),
                "OTA_RUNTIME_VERSION_UNPARSEABLE" | "OTA_TOOL_VERSION_UNPARSEABLE"
            ) {
                let tokens = backticked_tokens(&finding.why);
                return match tokens.as_slice() {
                    [path, command, ..] => format!(
                        "{subject} reported an unparseable version via `{path}` using `{command}`"
                    ),
                    _ => format!("{subject} reported an unparseable version"),
                };
            }
            let (display_why, _) = strip_container_image_from_why(&finding.why);
            let tokens = backticked_tokens(&display_why);
            match tokens.as_slice() {
                [observed, expected, ..] => {
                    format!("{subject} resolved `{observed}`, requires `{expected}`{command_hint}")
                }
                _ => format!("{subject}{command_hint}"),
            }
        }
        DoctorFindingGroupKind::AdapterBootstrap => {
            let subject = subject.trim();
            if let Some((adapter, source)) = subject.split_once(" via ") {
                format!("`{}` via `{}`", adapter.trim(), source.trim())
            } else {
                format!("`{subject}`")
            }
        }
        DoctorFindingGroupKind::ContractDrift => subject.to_string(),
        DoctorFindingGroupKind::PolicySurface => {
            let (display_why, container_image) = strip_container_image_from_why(&finding.why);
            finding_diagnosis_text(&finding.summary, &display_why, container_image.as_deref())
        }
        DoctorFindingGroupKind::EnvironmentValue
        | DoctorFindingGroupKind::NativePrerequisite
        | DoctorFindingGroupKind::ServiceHealth
        | DoctorFindingGroupKind::CheckFailure
        | DoctorFindingGroupKind::ExecutionBackend
        | DoctorFindingGroupKind::SharedAction(_) => finding.summary.clone(),
    }
}

fn render_doctor_verdict(verdict: DoctorVerdict) -> String {
    match verdict {
        DoctorVerdict::Ready => paint("ready", "1;38;2;0;255;120"),
        DoctorVerdict::Risky => paint("ready with warnings", "1;33"),
        DoctorVerdict::NotReady => paint("blocked", "1;38;2;255;235;59"),
        DoctorVerdict::PolicyBlocked => paint("blocked by policy", "1;31"),
        DoctorVerdict::AgentBlocked => paint("blocked for agents", "1;31"),
    }
}

fn render_doctor_readiness_status(verdict: DoctorVerdict) -> String {
    render_status_for_preview_semantics(
        doctor_preview_semantics(verdict).readiness_label,
        doctor_preview_semantics(verdict).style,
    )
}

fn render_preview_readiness_status(verdict: DoctorVerdict) -> String {
    render_status_for_preview_semantics(
        doctor_preview_semantics(verdict).preview_label,
        doctor_preview_semantics(verdict).style,
    )
}

fn doctor_readiness_status_label(verdict: DoctorVerdict) -> &'static str {
    doctor_preview_semantics(verdict).readiness_label
}

fn doctor_preview_status_label(verdict: DoctorVerdict) -> &'static str {
    doctor_preview_semantics(verdict).preview_label
}

fn doctor_verdict_blocks_preview(verdict: DoctorVerdict) -> bool {
    doctor_preview_semantics(verdict).blocks_preview
}

#[derive(Clone, Copy)]
enum PreviewStatusStyle {
    Success,
    Warning,
    Error,
}

#[derive(Clone, Copy)]
struct PreviewVerdictSemantics {
    readiness_label: &'static str,
    preview_label: &'static str,
    blocks_preview: bool,
    style: PreviewStatusStyle,
}

fn doctor_preview_semantics(verdict: DoctorVerdict) -> PreviewVerdictSemantics {
    match verdict {
        DoctorVerdict::Ready => PreviewVerdictSemantics {
            readiness_label: "READY",
            preview_label: "RUNNABLE",
            blocks_preview: false,
            style: PreviewStatusStyle::Success,
        },
        DoctorVerdict::Risky => PreviewVerdictSemantics {
            readiness_label: "READY WITH WARNINGS",
            preview_label: "RUNNABLE WITH WARNINGS",
            blocks_preview: false,
            style: PreviewStatusStyle::Warning,
        },
        DoctorVerdict::NotReady | DoctorVerdict::PolicyBlocked | DoctorVerdict::AgentBlocked => {
            PreviewVerdictSemantics {
                readiness_label: "BLOCKED",
                preview_label: "BLOCKED",
                blocks_preview: true,
                style: PreviewStatusStyle::Error,
            }
        }
    }
}

fn render_status_for_preview_semantics(label: &'static str, style: PreviewStatusStyle) -> String {
    match style {
        PreviewStatusStyle::Success => {
            render_named_status(label, primary_success_marker(), "1;38;2;0;255;120")
        }
        PreviewStatusStyle::Warning => {
            render_named_status(label, primary_warn_marker(), "1;38;2;255;214;95")
        }
        PreviewStatusStyle::Error => {
            render_named_status(label, primary_error_marker(), "1;38;2;255;122;122")
        }
    }
}

fn render_explain_section(
    path: &str,
    contract_path: &Path,
    report: &DoctorReport,
    summary: &ExplainSummary,
) -> String {
    let action_count = explain_action_count(&report.findings);
    let mut stdout = format!(
        "{}\n\n{}",
        format_command_header("EXPLAIN", path),
        render_explain_status(report.ok, action_count)
    );
    stdout.push_str(&render_explain_steps_text(&report.findings, contract_path));
    stdout.push_str(&render_explain_summary_text(summary, action_count));
    stdout
}

pub(super) fn render_explain_status(ready: bool, action_count: usize) -> String {
    if ready && action_count == 0 {
        render_readiness_status(true)
    } else {
        render_named_status("BLOCKED", primary_warn_marker(), "1;38;2;255;235;59")
    }
}

