fn render_execution_summary_text(execution: &ExecutionSummary<'_>) -> String {
    let mut stdout = String::new();
    stdout.push_str(&format!("{}\n", paint_section_title("Execution")));
    if let Some(default_context) = execution.default_context {
        stdout.push_str(&detail_list_row(
            &paint_key("Default Context:"),
            default_context,
        ));
    }
    if let Some(preferred) = execution.preferred {
        if execution.default_context.is_some() {
            stdout.push('\n');
        }
        stdout.push_str(&detail_list_row(&paint_key("Preferred:"), preferred));
    }
    if !execution.supported.is_empty() {
        stdout.push('\n');
        stdout.push_str(&detail_list_row(
            &paint_key("Supported:"),
            &execution.supported.join(", "),
        ));
    }
    if let Some(lifecycle) = execution.lifecycle {
        stdout.push('\n');
        stdout.push_str(&detail_list_row(&paint_key("Lifecycle:"), lifecycle));
    }
    if let Some(backends) = execution.backends.as_ref() {
        if let Some(container) = backends.container.as_ref() {
            stdout.push('\n');
            stdout.push_str(&detail_list_row(&paint_key("Image:"), container.image));
        }
        if let Some(remote) = backends.remote.as_ref() {
            stdout.push('\n');
            stdout.push_str(&detail_list_row(
                &paint_key("Remote Provider:"),
                remote.provider,
            ));
            if let Some(target) = remote.target {
                stdout.push('\n');
                stdout.push_str(&detail_list_row(&paint_key("Remote Target:"), target));
            }
            if let Some(cwd) = remote.cwd {
                stdout.push('\n');
                stdout.push_str(&detail_list_row(&paint_key("Remote Cwd:"), cwd));
            }
        }
    }
    if !execution.contexts.is_empty() {
        stdout.push('\n');
        stdout.push_str(&detail_list_row(
            &paint_key("Contexts:"),
            &execution
                .contexts
                .iter()
                .map(format_execution_context_brief)
                .collect::<Vec<_>>()
                .join(", "),
        ));
    }
    if !execution.env.is_empty() {
        stdout.push('\n');
        stdout.push_str(&detail_list_row(
            &paint_key("Env precedence:"),
            "org policy > process > declared env sources > contract default > required missing",
        ));
        stdout.push('\n');
        stdout.push_str(&format!("{} {}", detail_arrow(), paint_key("Env:")));
        for item in &execution.env {
            let mut details = Vec::new();
            if item.required {
                details.push("required".to_string());
            }
            if let Some(default) = item.default {
                details.push(format!("default={default}"));
            }
            if !item.allowed.is_empty() {
                details.push(format!("allowed={}", item.allowed.join(", ")));
            }
            stdout.push_str(&format!(
                "\n    {} {}",
                paint_key(item.name),
                details.join(", ")
            ));
            stdout.push_str(&format!("\n      {} {}", paint_key("Source:"), item.source));
        }
    }
    stdout
}

fn render_toolchain_summary_text(toolchains: &[ToolchainSelectionSummary]) -> String {
    if toolchains.is_empty() {
        return String::new();
    }

    let mut stdout = String::new();
    stdout.push_str(&paint_section_title("Toolchains"));
    for toolchain in toolchains {
        stdout.push_str(&format!(
            "\n{} {} via {}",
            summary_bullet(),
            paint_backticked_code(&toolchain.name),
            paint_backticked_code(&toolchain.provider)
        ));
        stdout.push_str(&format!(
            "\n  {} {}",
            paint_key("Selection:"),
            format!(
                "{}, {}, version {}, fulfillment {}, {}",
                toolchain.backend,
                toolchain.target_os,
                toolchain.version,
                toolchain.fulfillment,
                if toolchain.required {
                    "required"
                } else {
                    "optional"
                }
            )
        ));
        stdout.push_str(&format!(
            "\n  {} {}",
            paint_key("Owns runtime:"),
            paint_backticked_code(&toolchain.owns_runtime)
        ));
        if let Some(fulfilled) = toolchain.fulfilled {
            stdout.push_str(&format!(
                "\n  {} {}",
                paint_key("Fulfilled:"),
                toolchain_fulfillment_status_detail(&toolchain.fulfillment, fulfilled)
            ));
            for command in &toolchain.commands {
                stdout.push_str(&format!(
                    "\n  {} {}",
                    paint_key("Command:"),
                    paint_code(command)
                ));
            }
        }
        if !toolchain.owns_tools.is_empty() {
            let tools = toolchain
                .owns_tools
                .iter()
                .map(|tool| tool.as_str())
                .collect::<Vec<_>>();
            stdout.push_str(&format!(
                "\n  {} {}",
                paint_key("Owns tools:"),
                render_inline_code_list(&tools)
            ));
        }
        if !toolchain.components.is_empty() {
            let components = toolchain
                .components
                .iter()
                .map(|component| component.as_str())
                .collect::<Vec<_>>();
            stdout.push_str(&format!(
                "\n  {} {}",
                paint_key("Components:"),
                render_inline_code_list(&components)
            ));
        }
        if !toolchain.targets.is_empty() {
            let targets = toolchain
                .targets
                .iter()
                .map(|target| target.as_str())
                .collect::<Vec<_>>();
            stdout.push_str(&format!(
                "\n  {} {}",
                paint_key("Targets:"),
                render_inline_code_list(&targets)
            ));
        }
    }

    stdout
}

fn format_execution_context_brief(context: &ExecutionContextSummary<'_>) -> String {
    let mut details = vec![context.backend.to_string()];
    if let Some(lifecycle) = context.lifecycle {
        details.push(lifecycle.to_string());
    }
    if let Some(container) = context.container.as_ref() {
        details.push(format!("image={}", container.image));
    }
    if let Some(remote) = context.remote.as_ref() {
        details.push(format!("provider={}", remote.provider));
        if let Some(target) = remote.target {
            details.push(format!("target={target}"));
        }
    }
    if let Some(attachments) = context.attachments.as_ref()
        && !attachments.compose.is_empty()
    {
        details.push(format!("compose={}", attachments.compose.join("+")));
    }
    if let Some(attachments) = context.attachments.as_ref()
        && !attachments.isolated_paths.is_empty()
    {
        details.push(format!(
            "isolated={}",
            attachments.isolated_effective_paths.join("+")
        ));
    }

    format!("{} ({})", context.name, details.join(", "))
}

fn execution_context_plan_details(context: &ExecutionContextSummary<'_>) -> String {
    let mut details = vec![context.backend.to_string()];
    if let Some(lifecycle) = context.lifecycle {
        details.push(lifecycle.to_string());
    }
    if let Some(container) = context.container.as_ref() {
        details.push(format!("image={}", container.image));
    }
    if let Some(remote) = context.remote.as_ref() {
        details.push(format!("provider={}", remote.provider));
        if let Some(target) = remote.target {
            details.push(format!("target={target}"));
        }
    }
    if let Some(attachments) = context.attachments.as_ref()
        && !attachments.compose.is_empty()
    {
        details.push(format!("compose={}", attachments.compose.join("+")));
    }
    if let Some(attachments) = context.attachments.as_ref()
        && !attachments.isolated_effective_paths.is_empty()
    {
        details.push(format!(
            "isolated={}",
            attachments.isolated_effective_paths.join("+")
        ));
    }

    details.join(", ")
}

fn selected_execution_plan_context_name<'a>(
    execution: Option<&'a ExecutionSummary<'_>>,
    resolved: &ExecutionPlanResolved,
) -> Option<&'a str> {
    let execution = execution?;
    if resolved.backend_source == "default context" {
        return execution.default_context;
    }

    execution
        .contexts
        .iter()
        .find(|context| execution_context_matches_resolved(context, resolved))
        .map(|context| context.name)
}

fn execution_context_matches_resolved(
    context: &ExecutionContextSummary<'_>,
    resolved: &ExecutionPlanResolved,
) -> bool {
    context.backend == resolved.backend
        && (resolved.lifecycle.is_none() || context.lifecycle == resolved.lifecycle.as_deref())
        && match (context.container.as_ref(), resolved.image.as_deref()) {
            (Some(container), Some(image)) => container.image == image,
            (None, None) => true,
            _ => false,
        }
        && match (context.remote.as_ref(), resolved.provider.as_deref()) {
            (Some(remote), Some(provider)) => remote.provider == provider,
            (None, None) => true,
            _ => false,
        }
}

fn render_execution_plan_why_lines(
    workflow: Option<&WorkflowSummary<'_>>,
    selected_task: Option<&str>,
    declared_execution: Option<&ExecutionSummary<'_>>,
    resolved: &ExecutionPlanResolved,
    selected_context: Option<&str>,
) -> Vec<String> {
    let mut lines = Vec::new();

    match resolved.backend_source.as_str() {
        "default context" => {
            if let Some(default_context) =
                declared_execution.and_then(|execution| execution.default_context)
            {
                lines.push(format!(
                    "default execution comes from `execution.default_context: {default_context}`"
                ));
            }
        }
        "contract preferred" => {
            lines.push(String::from(
                "default execution comes from root shorthand `execution.preferred`",
            ));
        }
        "override" => {
            lines.push(format!(
                "execution backend was overridden at the command line to `{}`",
                resolved.backend
            ));
        }
        "workflow task" => {
            let task = selected_task.unwrap_or("workflow task");
            if let Some(workflow) = workflow {
                lines.push(format!(
                    "selected workflow `{}` drives execution planning through task `{task}`",
                    workflow.name
                ));
            } else {
                lines.push(format!(
                    "selected workflow task `{task}` drives execution planning"
                ));
            }
        }
        _ => {}
    }

    if let Some(context_name) = selected_context {
        lines.push(format!(
            "`{context_name}` resolves to `backend: {}`",
            resolved.backend
        ));
        if resolved.lifecycle_source.as_deref() == Some("context lifecycle")
            && let Some(lifecycle) = resolved.lifecycle.as_deref()
        {
            lines.push(format!(
                "`{context_name}` provides `lifecycle: {lifecycle}`"
            ));
        }
    } else if let Some(lifecycle) = resolved.lifecycle.as_deref() {
        lines.push(format!(
            "resolved execution uses `backend: {}` with `lifecycle: {lifecycle}`",
            resolved.backend
        ));
    } else {
        lines.push(format!(
            "resolved execution uses `backend: {}`",
            resolved.backend
        ));
    }

    lines
}

fn render_execution_plan_contexts_text(
    execution: &ExecutionSummary<'_>,
    selected_context: Option<&str>,
) -> String {
    let other_contexts = execution
        .contexts
        .iter()
        .filter(|context| Some(context.name) != selected_context)
        .collect::<Vec<_>>();
    if other_contexts.is_empty() {
        return String::new();
    }

    let mut stdout = String::new();
    stdout.push_str(&paint_section_title("Other Contexts"));
    for context in other_contexts {
        stdout.push_str(&format!(
            "\n{} {}{}",
            summary_bullet(),
            paint_backticked_code(context.name),
            if execution.default_context == Some(context.name) {
                paint(" (default)", "2")
            } else if selected_context == Some(context.name) {
                paint(" (selected)", "2")
            } else {
                String::new()
            }
        ));
        stdout.push_str(&format!("\n  {}", execution_context_plan_details(context)));
    }
    stdout
}

fn selected_execution_plan_context_summary<'a>(
    execution: Option<&'a ExecutionSummary<'_>>,
    selected_context: Option<&str>,
) -> Option<&'a ExecutionContextSummary<'a>> {
    let execution = execution?;
    let selected_context = selected_context?;
    execution
        .contexts
        .iter()
        .find(|context| context.name == selected_context)
}

fn render_execution_plan_selected_context_label(
    execution: Option<&ExecutionSummary<'_>>,
    selected_context: Option<&str>,
) -> Option<String> {
    let selected_context = selected_context?;
    let suffix =
        if execution.and_then(|execution| execution.default_context) == Some(selected_context) {
            " (default)"
        } else {
            ""
        };
    Some(format!(
        "{}{}",
        paint_backticked_code(selected_context),
        paint(suffix, "2")
    ))
}

fn render_execution_plan_text(
    path: &str,
    contract_path: &Path,
    contract_identity: &ContractIdentity,
    workflow: Option<&WorkflowSummary<'_>>,
    selected_task: Option<&str>,
    declared_execution: Option<&ExecutionSummary<'_>>,
    workflow_env_artifacts: &[EnvRenderedArtifactEntry],
    resolved: &ExecutionPlanResolved,
    overrides: Option<&ExecutionPlanOverrides>,
) -> String {
    let mut stdout = format!(
        "{}\n\n{}",
        format_command_header("EXECUTION PLAN", path),
        render_resolved_status()
    );
    let selected_context = selected_execution_plan_context_name(declared_execution, resolved);
    let selected_context_summary =
        selected_execution_plan_context_summary(declared_execution, selected_context);

    if let Some(workflow) = workflow {
        stdout.push_str(&format!(
            "\n\n{}",
            render_workflow_summary_text(workflow, None)
        ));
    }

    stdout.push_str(&format!(
        "\n\n{}\n",
        paint_section_title("Selected Execution")
    ));
    if let Some(task) = selected_task {
        stdout.push_str(&format!(
            "{} {} {}",
            summary_bullet(),
            paint_key("Task:"),
            paint_backticked_code(task)
        ));
        stdout.push('\n');
    }
    stdout.push_str(&format!(
        "{} {} {}",
        summary_bullet(),
        paint_key("Backend:"),
        paint_backticked_code(&resolved.backend)
    ));
    if let Some(lifecycle) = resolved.lifecycle.as_deref() {
        stdout.push_str(&format!(
            "\n{} {} {}",
            summary_bullet(),
            paint_key("Lifecycle:"),
            paint_backticked_code(lifecycle)
        ));
    }
    if let Some(image) = resolved.image.as_deref() {
        stdout.push_str(&format!(
            "\n{} {} {}",
            summary_bullet(),
            paint_key("Image:"),
            paint_backticked_code(image)
        ));
    }
    if let Some(engine) = resolved.engine.as_deref() {
        stdout.push_str(&format!(
            "\n{} {} {}",
            summary_bullet(),
            paint_key("Engine:"),
            paint_backticked_code(engine)
        ));
    }
    if let Some(context_label) =
        render_execution_plan_selected_context_label(declared_execution, selected_context)
    {
        stdout.push_str(&format!(
            "\n{} {} {}",
            summary_bullet(),
            paint_key("Context:"),
            context_label
        ));
    }
    if resolved.engine.is_none() && !resolved.engine_candidates.is_empty() {
        stdout.push_str(&format!(
            "\n{} {} {}",
            summary_bullet(),
            paint_key("Engine candidates:"),
            render_inline_code_list(&resolved.engine_candidates)
        ));
    }
    if let Some(provider) = resolved.provider.as_deref() {
        stdout.push_str(&format!(
            "\n{} {} {}",
            summary_bullet(),
            paint_key("Provider:"),
            paint_backticked_code(provider)
        ));
    }
    if let Some(target) = resolved.target.as_deref() {
        stdout.push_str(&format!(
            "\n{} {} {}",
            summary_bullet(),
            paint_key("Target:"),
            paint_backticked_code(target)
        ));
    }
    if let Some(attachments) =
        selected_context_summary.and_then(|context| context.attachments.as_ref())
        && !attachments.isolated_effective_paths.is_empty()
    {
        let paths = attachments
            .isolated_effective_paths
            .iter()
            .map(|path| path.as_str())
            .collect::<Vec<_>>();
        stdout.push_str(&format!(
            "\n{} {} {}",
            summary_bullet(),
            paint_key("Isolation:"),
            render_inline_code_list(&paths)
        ));
    }
    if let Some(cwd) = resolved.cwd.as_deref() {
        stdout.push_str(&format!(
            "\n{} {} {}",
            summary_bullet(),
            paint_key("Cwd:"),
            paint_backticked_code(cwd)
        ));
    }

    let why_lines = render_execution_plan_why_lines(
        workflow,
        selected_task,
        declared_execution,
        resolved,
        selected_context,
    );
    if !why_lines.is_empty() {
        stdout.push_str(&format!("\n\n{}", paint_section_title("Why")));
        for line in why_lines {
            stdout.push_str(&format!(
                "\n{} {}",
                summary_bullet(),
                render_backticked_text(&line, Some(contract_path))
            ));
        }
    }

    if !workflow_env_artifacts.is_empty() {
        stdout.push_str(&format!(
            "\n\n{}",
            paint_section_title("Workflow Env Artifacts")
        ));
        for artifact in workflow_env_artifacts {
            stdout.push_str(&render_env_rendered_artifact_text(artifact));
        }
    }

    if let Some(execution) = declared_execution {
        if execution.contexts.len() > 1 {
            let contexts_text = render_execution_plan_contexts_text(execution, selected_context);
            if !contexts_text.is_empty() {
                stdout.push_str(&format!("\n\n{contexts_text}"));
            }
        } else {
            stdout.push_str(&format!(
                "\n\n{}",
                render_contract_identity_text(contract_identity)
            ));
        }
    } else {
        stdout.push_str(&format!(
            "\n\n{}",
            render_contract_identity_text(contract_identity)
        ));
    }

    if let Some(overrides) = overrides {
        stdout.push_str(&format!("\n\n{}\n", paint_section_title("Overrides")));
        let mut first = true;
        if let Some(backend) = overrides.backend.as_deref() {
            stdout.push_str(&format!(
                "{} {} {}",
                if first { "" } else { "\n" },
                paint_key("Backend:"),
                paint_backticked_code(backend)
            ));
            first = false;
        }
        if let Some(lifecycle) = overrides.lifecycle.as_deref() {
            stdout.push_str(&format!(
                "{} {} {}",
                if first { "" } else { "\n" },
                paint_key("Lifecycle:"),
                paint_backticked_code(lifecycle)
            ));
        }
    }

    stdout
}

fn render_doctor_execution_summary_text(
    execution: &ExecutionSummary<'_>,
    doctor_mode: Option<DoctorMode>,
    doctor_lifecycle: Option<Lifecycle>,
) -> String {
    let mut lines = vec![paint_section_title("Execution")];
    if let Some(mode) = doctor_mode {
        lines.push(section_list_row(
            &summary_bullet(),
            &paint_key("Mode:"),
            &paint_backticked_code(mode.as_str()),
        ));
    }
    if let Some(default_context) = execution.default_context {
        lines.push(section_list_row(
            &summary_bullet(),
            &paint_key("Default Context:"),
            &paint_backticked_code(default_context),
        ));
    }
    if let Some(preferred) = execution.preferred {
        lines.push(section_list_row(
            &summary_bullet(),
            &paint_key("Preferred:"),
            &paint_backticked_code(preferred),
        ));
    }
    if !execution.supported.is_empty() {
        lines.push(section_list_row(
            &summary_bullet(),
            &paint_key("Supported:"),
            &render_inline_code_list(&execution.supported),
        ));
    }
    let selected_lifecycle = doctor_lifecycle
        .map(format_lifecycle)
        .or(execution.lifecycle);
    if let Some(lifecycle) = selected_lifecycle {
        lines.push(section_list_row(
            &summary_bullet(),
            &paint_key("Lifecycle:"),
            &paint_backticked_code(lifecycle),
        ));
    }
    if let (Some(selected), Some(declared)) =
        (doctor_lifecycle.map(format_lifecycle), execution.lifecycle)
        && selected != declared
    {
        lines.push(section_list_row(
            &summary_bullet(),
            &paint_key("Declared Lifecycle:"),
            &paint_backticked_code(declared),
        ));
    }
    if let Some(backends) = execution.backends.as_ref() {
        if let Some(container) = backends.container.as_ref() {
            lines.push(section_list_row(
                &summary_bullet(),
                &paint_key("Image:"),
                &paint_backticked_code(container.image),
            ));
        }
        if let Some(remote) = backends.remote.as_ref() {
            let mut details = vec![format!(
                "{} {}",
                paint_key("provider"),
                paint_backticked_code(remote.provider)
            )];
            if let Some(target) = remote.target {
                details.push(format!(
                    "{} {}",
                    paint_key("target"),
                    paint_backticked_code(target)
                ));
            }
            if let Some(cwd) = remote.cwd {
                details.push(format!(
                    "{} {}",
                    paint_key("cwd"),
                    paint_backticked_code(cwd)
                ));
            }
            lines.push(section_list_row(
                &summary_bullet(),
                &paint_key("Remote:"),
                &details.join(" "),
            ));
        }
    }
    if !execution.contexts.is_empty() {
        lines.push(section_list_row(
            &summary_bullet(),
            &paint_key("Contexts:"),
            "",
        ));
        for context in &execution.contexts {
            lines.push(format!(
                "    {}",
                format_doctor_execution_context_line(context)
            ));
        }
    }
    if !execution.env.is_empty() {
        lines.push(String::new());
        lines.push(paint_section_title("Environment"));
        lines.push(section_list_row(
            &summary_bullet(),
            &paint_key("Resolution:"),
            "org policy > process > declared env sources > contract default > required missing",
        ));
        lines.push(section_list_row(
            &summary_bullet(),
            &paint_key("Required missing:"),
            &paint_backticked_code(
                &execution
                    .env
                    .iter()
                    .filter(|item| {
                        item.required
                            && doctor_execution_env_source_kind(item)
                                == DoctorExecutionEnvSourceKind::Missing
                    })
                    .count()
                    .to_string(),
            ),
        ));

        append_doctor_execution_env_group(
            &mut lines,
            "Policy-backed Values",
            execution.env.iter().filter(|item| {
                doctor_execution_env_source_kind(item) == DoctorExecutionEnvSourceKind::Policy
            }),
            render_doctor_execution_env_named_source,
        );
        append_doctor_execution_env_group(
            &mut lines,
            "Process-backed Values",
            execution.env.iter().filter(|item| {
                doctor_execution_env_source_kind(item) == DoctorExecutionEnvSourceKind::Process
            }),
            render_doctor_execution_env_named_source,
        );
        append_doctor_execution_env_group(
            &mut lines,
            "Source-backed Values",
            execution.env.iter().filter(|item| {
                doctor_execution_env_source_kind(item)
                    == DoctorExecutionEnvSourceKind::DeclaredSource
            }),
            render_doctor_execution_env_named_source,
        );
        append_doctor_execution_env_group(
            &mut lines,
            "Defaulted Values",
            execution.env.iter().filter(|item| {
                doctor_execution_env_source_kind(item) == DoctorExecutionEnvSourceKind::Default
            }),
            render_doctor_execution_env_default_value,
        );
        append_doctor_execution_env_group(
            &mut lines,
            "Missing Required Env",
            execution.env.iter().filter(|item| {
                item.required
                    && doctor_execution_env_source_kind(item)
                        == DoctorExecutionEnvSourceKind::Missing
            }),
            render_doctor_execution_env_missing,
        );
        append_doctor_execution_env_group(
            &mut lines,
            "Source Resolution Issues",
            execution.env.iter().filter(|item| {
                doctor_execution_env_source_kind(item) == DoctorExecutionEnvSourceKind::Issue
            }),
            render_doctor_execution_env_issue,
        );
    }

    lines.join("\n")
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DoctorExecutionEnvSourceKind {
    Policy,
    Process,
    DeclaredSource,
    Default,
    Missing,
    Issue,
}

fn doctor_execution_env_source_kind(
    item: &ExecutionEnvSummary<'_>,
) -> DoctorExecutionEnvSourceKind {
    match item.source.as_str() {
        "process" => DoctorExecutionEnvSourceKind::Process,
        "default" => DoctorExecutionEnvSourceKind::Default,
        "missing" => DoctorExecutionEnvSourceKind::Missing,
        source
            if source.starts_with("missing required ")
                || source.starts_with("parse failed ")
                || source.starts_with("invalid structure ")
                || source.starts_with("collision ")
                || source == "invalid policy pack" =>
        {
            DoctorExecutionEnvSourceKind::Issue
        }
        source if item.policy.is_some() && source == "org policy" => {
            DoctorExecutionEnvSourceKind::Policy
        }
        _ => DoctorExecutionEnvSourceKind::DeclaredSource,
    }
}

fn append_doctor_execution_env_group<'a, I, F>(
    lines: &mut Vec<String>,
    title: &str,
    items: I,
    render: F,
) where
    I: Iterator<Item = &'a ExecutionEnvSummary<'a>>,
    F: Fn(&ExecutionEnvSummary<'_>) -> String,
{
    let entries: Vec<_> = items.collect();
    if entries.is_empty() {
        return;
    }
    lines.push(format!(
        "{} ({})",
        paint_section_title(title),
        entries.len()
    ));
    for item in entries {
        lines.push(format!(" {}  {}", verdict_bullet(), render(item)));
    }
}

fn render_doctor_execution_env_named_source(item: &ExecutionEnvSummary<'_>) -> String {
    format!(
        "{} from {}",
        paint_backticked_code(item.name),
        paint_backticked_code(&item.source)
    )
}

fn render_doctor_execution_env_default_value(item: &ExecutionEnvSummary<'_>) -> String {
    let value = item.default.unwrap_or("");
    paint_backticked_code(&format!("{}={value}", item.name))
}

fn render_doctor_execution_env_missing(item: &ExecutionEnvSummary<'_>) -> String {
    paint_backticked_code(item.name)
}

fn render_doctor_execution_env_issue(item: &ExecutionEnvSummary<'_>) -> String {
    format!("{} ({})", paint_backticked_code(item.name), item.source)
}

fn format_doctor_execution_context_line(context: &ExecutionContextSummary<'_>) -> String {
    let mut details = vec![context.backend.to_string()];
    if let Some(lifecycle) = context.lifecycle {
        details.push(lifecycle.to_string());
    }
    if let Some(container) = context.container.as_ref() {
        details.push(container.image.to_string());
    }
    if let Some(remote) = context.remote.as_ref() {
        details.push(format!("provider={}", remote.provider));
        if let Some(target) = remote.target {
            details.push(format!("target={target}"));
        }
    }
    if let Some(attachments) = context.attachments.as_ref()
        && !attachments.compose.is_empty()
    {
        details.push(format!("compose={}", attachments.compose.join("+")));
    }
    if let Some(attachments) = context.attachments.as_ref()
        && !attachments.isolated_paths.is_empty()
    {
        details.push(format!(
            "isolated={}",
            attachments.isolated_effective_paths.join("+")
        ));
    }

    format!("{}: {}", paint(context.name, "1;37"), details.join(" / "))
}

fn render_agent_summary_line(agent: &AgentSummary<'_>, include_notes: bool) -> Option<String> {
    render_agent_summary_text(agent, include_notes)
}

fn render_doctor_agent_summary_text(
    agent: &AgentSummary<'_>,
    include_notes: bool,
) -> Option<String> {
    render_agent_summary_text(agent, include_notes)
}

fn render_agents_markdown(
    contract: &Contract,
    contract_path: &Path,
    agent: Option<&AgentSummary<'_>>,
    source_display: &str,
) -> String {
    let workflow = WorkflowSummary::from_contract_with_path(contract, contract_path);
    let mut output = String::new();
    output.push_str("# AGENTS.md\n\n");
    output.push_str("Generated from `");
    output.push_str(source_display);
    output.push_str("` by `ota agents`.\n\n");
    output.push_str("## Repo\n\n");
    output.push_str("- `project`: `");
    output.push_str(&contract.project.name);
    output.push_str("`\n");
    if let Some(description) = contract.project.description.as_deref() {
        output.push_str("- `description`: `");
        output.push_str(description);
        output.push_str("`\n");
    }
    output.push('\n');
    if let Some(workflow) = workflow.as_ref() {
        output.push_str("## Default Workflow\n\n");
        output.push_str("- `name`: `");
        output.push_str(workflow.name);
        output.push_str("`\n");
        if let Some(intent) = workflow.intent {
            output.push_str("- `intent`: `");
            output.push_str(intent);
            output.push_str("`\n");
        }
        if let Some(prepare_task) = workflow.prepare_task {
            output.push_str("- `prepare`: `ota run ");
            output.push_str(prepare_task);
            output.push_str("`\n");
        } else if let Some(prepare_action) = workflow.prepare_action.as_ref() {
            output.push_str("- `prepare`: `workflow action ");
            output.push_str(&render_workflow_prepare_action_preview(prepare_action));
            output.push_str("`\n");
        }
        if let Some(setup_task) = workflow.setup_task {
            output.push_str("- `setup`: `ota run ");
            output.push_str(setup_task);
            output.push_str("`\n");
        }
        if let Some(run_task) = workflow.run_task {
            output.push_str("- `run`: `ota run ");
            output.push_str(run_task);
            output.push_str("`\n");
        }
        if !workflow.required_services.is_empty() {
            output.push_str("- `required_services`: ");
            output.push_str(
                &workflow
                    .required_services
                    .iter()
                    .map(|value| format!("`{value}`"))
                    .collect::<Vec<_>>()
                    .join(", "),
            );
            output.push('\n');
        }
        if !workflow.readiness_checks.is_empty() {
            output.push_str("- `readiness_checks`: ");
            output.push_str(
                &workflow
                    .readiness_checks
                    .iter()
                    .map(|value| format!("`{value}`"))
                    .collect::<Vec<_>>()
                    .join(", "),
            );
            output.push('\n');
        }
        if !workflow.readiness_probes.is_empty() {
            output.push_str("- `readiness_probes`: ");
            output.push_str(
                &workflow
                    .readiness_probes
                    .iter()
                    .map(|value| format!("`{value}`"))
                    .collect::<Vec<_>>()
                    .join(", "),
            );
            output.push('\n');
        }
        if !workflow.readiness_surfaces.is_empty() {
            output.push_str("- `readiness_surfaces`: ");
            output.push_str(
                &workflow
                    .readiness_surfaces
                    .iter()
                    .map(|value| format!("`{value}`"))
                    .collect::<Vec<_>>()
                    .join(", "),
            );
            output.push('\n');
        }
        if !workflow.signal_readiness_checks.is_empty() {
            output.push_str("- `signal_readiness_checks`: ");
            output.push_str(
                &workflow
                    .signal_readiness_checks
                    .iter()
                    .map(|value| format!("`{value}`"))
                    .collect::<Vec<_>>()
                    .join(", "),
            );
            output.push('\n');
        }
        if !workflow.signal_readiness_probes.is_empty() {
            output.push_str("- `signal_readiness_probes`: ");
            output.push_str(
                &workflow
                    .signal_readiness_probes
                    .iter()
                    .map(|value| format!("`{value}`"))
                    .collect::<Vec<_>>()
                    .join(", "),
            );
            output.push('\n');
        }
        if !workflow.signal_readiness_surfaces.is_empty() {
            output.push_str("- `signal_readiness_surfaces`: ");
            output.push_str(
                &workflow
                    .signal_readiness_surfaces
                    .iter()
                    .map(|value| format!("`{value}`"))
                    .collect::<Vec<_>>()
                    .join(", "),
            );
            output.push('\n');
        }
        output.push('\n');
    }
    output.push_str("## Agent Contract\n\n");

    if let Some(agent) = agent {
        output.push_str("Use declared `ota run <task>` paths before raw package-manager, compiler, or test commands when this contract already defines the task you need. Drop to raw commands only for narrow debugging or one-off checks that the contract does not model yet.\n\n");
        if let Some(entrypoint) = agent.entrypoint {
            output.push_str("- `entrypoint`: `");
            output.push_str(entrypoint);
            output.push_str("` (`ota run ");
            output.push_str(entrypoint);
            output.push_str("`)\n");
        }
        if let Some(default_task) = agent.default_task {
            output.push_str("- `default_task`: `");
            output.push_str(default_task);
            output.push_str("` (`ota run ");
            output.push_str(default_task);
            output.push_str("`)\n");
        }
        if !agent.safe_tasks.is_empty() {
            render_agents_task_list(&mut output, "safe_tasks", &agent.safe_tasks);
        }
        let safe_task_effect_names = contract
            .tasks
            .iter()
            .filter_map(|(task_name, task)| task.safe_for_agent.then_some(task_name.clone()))
            .chain(agent.safe_tasks.iter().cloned())
            .collect::<BTreeSet<_>>();
        let safe_task_effects = safe_task_effect_names
            .iter()
            .filter_map(|task_name| {
                contract.tasks.get(task_name).map(|task| {
                    (
                        task_name.as_str(),
                        crate::output::TaskEffectsSummary::from_spec(&task.effects),
                    )
                })
            })
            .filter(|(_, effects)| !effects.is_empty())
            .collect::<Vec<_>>();
        if !safe_task_effects.is_empty() {
            output.push_str("- `safe_task_risk_signals`:\n");
            for (task_name, effects) in safe_task_effects {
                output.push_str("  - `");
                output.push_str(task_name);
                output.push_str("`: ");
                output.push_str(&render_task_effects_text(&effects));
                output.push('\n');
            }
        }
        if !agent.verify_after_changes.is_empty() {
            render_agents_task_list(
                &mut output,
                "verify_after_changes",
                &agent.verify_after_changes,
            );
        }
        if !agent.writable_paths.is_empty() {
            output.push_str("- `writable_paths`: ");
            output.push_str(
                &agent
                    .writable_paths
                    .iter()
                    .map(|value| format!("`{value}`"))
                    .collect::<Vec<_>>()
                    .join(", "),
            );
            output.push('\n');
        }
        if !agent.protected_paths.is_empty() {
            output.push_str("- `protected_paths`: ");
            output.push_str(
                &agent
                    .protected_paths
                    .iter()
                    .map(|value| format!("`{value}`"))
                    .collect::<Vec<_>>()
                    .join(", "),
            );
            output.push('\n');
        }
        if let Some(bootstrap) = agent.bootstrap.as_ref()
            && let Some(ota) = bootstrap.ota.as_ref()
        {
            output.push_str("\n## Bootstrap\n\n");
            if let Some(note) = ota.note.as_deref() {
                output.push_str(note);
                output.push('\n');
                output.push('\n');
            } else {
                output.push_str(
                    "Only install `ota` if it is missing and installation is approved.\n\n",
                );
            }
            if let Some(source) = ota.source.as_ref() {
                output.push_str("- `source.kind`: `");
                match source.kind {
                    "version" => {
                        output.push_str("version`\n");
                        output.push_str("- `source.version`: `");
                        output.push_str(source.version.as_deref().unwrap_or_default());
                        output.push_str("`\n");
                    }
                    "git_rev" => {
                        output.push_str("git_rev`\n");
                        output.push_str("- `source.rev`: `");
                        output.push_str(source.rev.as_deref().unwrap_or_default());
                        output.push_str("`\n");
                    }
                    "branch" => {
                        output.push_str("branch`\n");
                        output.push_str("- `source.branch`: `");
                        output.push_str(source.branch.as_deref().unwrap_or_default());
                        output.push_str("`\n");
                    }
                    _ => {}
                }
            }
            if let Some(sh) = ota.sh.as_deref() {
                output.push_str("- `sh`: `");
                output.push_str(sh);
                output.push_str("`\n");
            }
            if let Some(powershell) = ota.powershell.as_deref() {
                output.push_str("- `powershell`: `");
                output.push_str(powershell);
                output.push_str("`\n");
            }
        }
        if let Some(notes) = agent.notes
            && !notes.trim().is_empty()
        {
            output.push_str("\n## Notes\n\n");
            for line in notes.lines() {
                output.push_str(line.trim_end());
                output.push('\n');
            }
        }
    } else {
        output.push_str("No explicit `agent` block is declared in `ota.yaml` yet.\n\n");
        output.push_str(
            "Review inferred `agent` defaults with `ota detect --dry-run` and compare the starter contract path with `ota init --dry-run` before writing `AGENTS.md`.\n",
        );
    }

    output
}

struct InferredMissingAgentContext {
    signal_findings: Vec<Finding>,
}

fn inferred_agents_missing_block_context(
    repo_root: &Path,
    report: &DetectReport,
) -> InferredMissingAgentContext {
    let mut signal_findings = Vec::new();
    append_contractless_repo_findings(repo_root, report, &mut signal_findings);

    let mut inferred_contract = report.contract.clone();
    apply_detected_starter_contract_defaults(&mut inferred_contract, report);
    if let Some(agent) = inferred_contract
        .agent
        .as_ref()
        .and_then(AgentSummary::from_config)
    {
        if !agent.safe_tasks.is_empty() {
            signal_findings.push(contractless_signal_finding(
                FindingSeverity::Info,
                format!("Inferred safe tasks: {}", agent.safe_tasks.join(", ")),
                String::from("detector-backed starter agent defaults identified safe tasks"),
                String::from("review the inferred agent boundary before writing it"),
            ));
        }
        if !agent.writable_paths.is_empty() {
            signal_findings.push(contractless_signal_finding(
                FindingSeverity::Info,
                format!(
                    "Inferred starter writable paths: {}",
                    agent.writable_paths.join(", ")
                ),
                String::from(
                    "detector-backed starter agent defaults identified writable source roots",
                ),
                String::from("review the inferred agent boundary before writing it"),
            ));
        }
        if !agent.protected_paths.is_empty() {
            signal_findings.push(contractless_signal_finding(
                FindingSeverity::Info,
                format!(
                    "Inferred protected paths: {}",
                    agent.protected_paths.join(", ")
                ),
                String::from(
                    "detector-backed starter agent defaults identified protected control files",
                ),
                String::from("review the inferred agent boundary before writing it"),
            ));
        }
    }

    InferredMissingAgentContext { signal_findings }
}

