    #[test]
    fn github_projection_sync_and_check_share_one_renderer() {
        let repo = tempdir().expect("repo tempdir");
        let contract_path = repo.path().join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: github-projection-fixture
tasks:
  verify:
    run: echo verify
workflows:
  default: verify
  verify:
    intent: ci_verification
    run:
      task: verify
agent:
  safe_tasks:
    - verify
"#,
        )
        .expect("contract fixture should write");
        let output = Path::new(".github/workflows/ota-governance.yml");
        let render = ci_github_render(
            Some(contract_path.as_path()),
            None,
            "verify",
            Some(output),
            "ubuntu-latest",
            Some("native"),
            "linux",
            OutputFormat::Json,
            false,
        );
        assert_eq!(render.exit_code, 0);
        let rendered: serde_json::Value = serde_json::from_str(&render.stdout).unwrap();
        assert_eq!(
            rendered["projection"]["projection"]["governance"]["agent_admission"]["decision"],
            "allow"
        );
        let identity = rendered["projection"]["projection"]["identity"]
            .as_str()
            .unwrap();
        let escaped = ci_github_render(
            Some(contract_path.as_path()),
            None,
            "verify",
            Some(Path::new("../outside.yml")),
            "ubuntu-latest",
            Some("native"),
            "linux",
            OutputFormat::Json,
            false,
        );
        assert_eq!(escaped.exit_code, 1);
        let unsafe_contract_path = repo.path().join("unsafe-ota.yaml");
        fs::write(
            &unsafe_contract_path,
            r#"
version: 1
project:
  name: unsafe-github-projection-fixture
tasks:
  verify:
    run: echo verify
workflows:
  default: verify
  verify:
    run:
      task: verify
"#,
        )
        .unwrap();
        let refused = ci_github_render(
            Some(unsafe_contract_path.as_path()),
            None,
            "verify",
            Some(output),
            "ubuntu-latest",
            Some("native"),
            "linux",
            OutputFormat::Json,
            false,
        );
        assert_eq!(refused.exit_code, 1);
        let refused: serde_json::Value = serde_json::from_str(&refused.stdout).unwrap();
        assert_eq!(refused["code"], "requested_task_not_safe");
        let inspectable_refusal = ci_projection(
            Some(unsafe_contract_path.as_path()),
            None,
            "verify",
            Some("native"),
            "linux",
            None,
            OutputFormat::Json,
        );
        assert_eq!(inspectable_refusal.exit_code, 1);
        let inspectable_refusal: serde_json::Value =
            serde_json::from_str(inspectable_refusal.stderr.as_deref().unwrap()).unwrap();
        assert_eq!(inspectable_refusal["operation"], "projection");
        assert_eq!(
            inspectable_refusal["projection"]["governance"]["agent_admission"]["decision"],
            "deny"
        );
        let unsafe_setup_contract_path = repo.path().join("unsafe-setup-ota.yaml");
        fs::write(
            &unsafe_setup_contract_path,
            r#"
version: 1
project:
  name: unsafe-setup-github-projection-fixture
tasks:
  setup:
    command:
      exe: sh
      args: ["-c", "true"]
  verify:
    safe_for_agent: true
    command:
      exe: sh
      args: ["-c", "true"]
workflows:
  default: verify
  verify:
    setup:
      task: setup
    run:
      task: verify
agent:
  safe_tasks: [verify]
"#,
        )
        .unwrap();
        let unsafe_setup = ci_projection_for_contract(
            &parse_contract_str(
                &unsafe_setup_contract_path,
                &fs::read_to_string(&unsafe_setup_contract_path).unwrap(),
            )
            .unwrap(),
            &unsafe_setup_contract_path,
            "verify",
            Some("native"),
            "linux",
        )
        .expect_err("an unsafe setup phase must refuse CI projection");
        assert_eq!(unsafe_setup.0, "requested_task_not_safe");
        let denied_projection = unsafe_setup.2.expect("denial remains inspectable");
        assert_eq!(denied_projection.task, "verify");
        assert_eq!(
            denied_projection.governance.agent_admission.decision,
            "deny"
        );
        assert_eq!(
            denied_projection.governance.agent_admission.basis,
            ["requested_task_not_safe"]
        );
        let unsafe_proof_contract_path = repo.path().join("unsafe-proof-ota.yaml");
        fs::write(
            &unsafe_proof_contract_path,
            r#"
version: 1
project:
  name: trusted-proof-github-projection-fixture
tasks:
  verify:
    run: echo verify
workflows:
  default: verify
  verify:
    run:
      task: verify
    proof:
      claim: bounded
"#,
        )
        .unwrap();
        let unsafe_proof = ci_projection_for_contract(
            &parse_contract_str(
                &unsafe_proof_contract_path,
                &fs::read_to_string(&unsafe_proof_contract_path).unwrap(),
            )
            .unwrap(),
            &unsafe_proof_contract_path,
            "verify",
            Some("native"),
            "linux",
        )
        .expect_err("a proof claim must not bypass agent admission");
        assert_eq!(unsafe_proof.0, "requested_task_not_safe");
        let strict_proof_contract_path = repo.path().join("strict-proof-ota.yaml");
        fs::write(
            &strict_proof_contract_path,
            r#"
version: 1
project:
  name: strict-proof-github-projection-fixture
tasks:
  verify:
    safe_for_agent: true
    command:
      exe: sh
      args: ["-c", "true"]
workflows:
  default: verify
  verify:
    run:
      task: verify
    proof:
      claim: bounded
agent:
  safe_tasks: [verify]
"#,
        )
        .unwrap();
        fs::create_dir_all(repo.path().join(".ota")).unwrap();
        fs::write(
            repo.path().join(".ota/org-policy.yaml"),
            r#"
policies:
  agent:
    claim_assurance:
      proof_breadth:
        minimum_status: supported
        on_insufficient: deny
"#,
        )
        .unwrap();
        let proof_policy_denial = ci_projection(
            Some(strict_proof_contract_path.as_path()),
            None,
            "verify",
            Some("native"),
            "linux",
            None,
            OutputFormat::Json,
        );
        assert_eq!(proof_policy_denial.exit_code, 1);
        let proof_policy_denial: serde_json::Value =
            serde_json::from_str(proof_policy_denial.stderr.as_deref().unwrap()).unwrap();
        assert_eq!(proof_policy_denial["code"], "proof_assurance_policy_deny");
        assert_eq!(
            proof_policy_denial["projection"]["governance"]["proof_assurance"]["policy_decision"],
            "deny"
        );
        let caller_path = repo.path().join(".github/workflows/ci.yml");
        fs::create_dir_all(caller_path.parent().unwrap()).unwrap();
        fs::write(
            &caller_path,
            format!(
                "jobs:\n  ota:\n    uses: ./.github/workflows/ota-governance.yml\n    with:\n      ota_projection_identity: {identity}\n      ota_target_os: linux\n"
            ),
        )
        .unwrap();

        let sync = ci_github_check(
            Some(contract_path.as_path()),
            None,
            "verify",
            output,
            Path::new(".github/workflows/ci.yml"),
            "ubuntu-latest",
            Some("native"),
            "linux",
            true,
            OutputFormat::Json,
            false,
        );
        assert_eq!(sync.exit_code, 0, "{}", sync.stdout);
        let repeated_sync = ci_github_check(
            Some(contract_path.as_path()),
            None,
            "verify",
            output,
            Path::new(".github/workflows/ci.yml"),
            "ubuntu-latest",
            Some("native"),
            "linux",
            true,
            OutputFormat::Json,
            false,
        );
        assert_eq!(repeated_sync.exit_code, 0, "{}", repeated_sync.stdout);
        let repeated_sync: serde_json::Value = serde_json::from_str(&repeated_sync.stdout).unwrap();
        assert_eq!(repeated_sync["mutated"], false);
        let check = ci_github_check(
            Some(contract_path.as_path()),
            None,
            "verify",
            output,
            Path::new(".github/workflows/ci.yml"),
            "ubuntu-latest",
            Some("native"),
            "linux",
            false,
            OutputFormat::Json,
            false,
        );
        assert_eq!(check.exit_code, 0, "{}", check.stdout);

        let output_path = repo.path().join(output);
        let managed = fs::read_to_string(&output_path).unwrap();
        fs::write(
            &output_path,
            managed.replacen("ota up --workflow", "echo bypassed && ota up --workflow", 1),
        )
        .unwrap();
        let stale = ci_github_check(
            Some(contract_path.as_path()),
            None,
            "verify",
            output,
            Path::new(".github/workflows/ci.yml"),
            "ubuntu-latest",
            Some("native"),
            "linux",
            false,
            OutputFormat::Json,
            false,
        );
        assert_eq!(stale.exit_code, 1);
        let stale: serde_json::Value = serde_json::from_str(&stale.stdout).unwrap();
        assert_eq!(stale["code"], "managed_output_stale");

        fs::write(repo.path().join(output), "name: externally-owned\n").unwrap();
        let rejected = ci_github_check(
            Some(contract_path.as_path()),
            None,
            "verify",
            output,
            Path::new(".github/workflows/ci.yml"),
            "ubuntu-latest",
            Some("native"),
            "linux",
            true,
            OutputFormat::Json,
            false,
        );
        assert_eq!(rejected.exit_code, 1);
        let rejected: serde_json::Value = serde_json::from_str(&rejected.stdout).unwrap();
        assert_eq!(rejected["code"], "managed_output_unowned");
    }

    #[test]
    fn ci_projection_rejects_a_target_os_outside_the_task_contract() {
        let repo = tempdir().expect("repo tempdir");
        let contract_path = repo.path().join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: target-os-fixture
tasks:
  verify:
    run: echo verify
    only_on: [linux]
workflows:
  default: verify
  verify:
    run:
      task: verify
agent:
  safe_tasks: [verify]
"#,
        )
        .expect("contract fixture should write");

        let result = ci_projection(
            Some(contract_path.as_path()),
            None,
            "verify",
            Some("native"),
            "windows",
            None,
            OutputFormat::Json,
        );
        assert_eq!(result.exit_code, 1);
        let payload: serde_json::Value =
            serde_json::from_str(&result.stdout).expect("failure JSON should parse");
        assert_eq!(payload["code"], "projection_mode_unavailable");
    }

    #[test]
    fn ci_projection_carries_replay_policy_requirement_without_observed_checkout_identity() {
        let repo = tempdir().expect("repo tempdir");
        let contract_path = repo.path().join("ota.yaml");
        fs::write(repo.path().join("fixture.txt"), "frozen").unwrap();
        let identity = crate::replay_inputs::sha256_identity(b"frozen");
        let contract_yaml = format!(
            r#"
version: 1
project:
  name: replay-policy-projection
tasks:
  verify:
    safe_for_agent: true
    after_success: [report]
    replay_inputs:
      - id: fixture
        kind: static_file
        path: fixture.txt
        expected_identity: {identity}
    command:
      exe: sh
      args: ["-c", "true"]
  report:
    safe_for_agent: true
    command:
      exe: sh
      args: ["-c", "true"]
workflows:
  default: verify
  verify:
    run:
      task: verify
agent:
  safe_tasks: [verify, report]
"#,
        );
        fs::write(&contract_path, &contract_yaml).unwrap();
        fs::create_dir_all(repo.path().join(".ota")).unwrap();
        fs::write(
            repo.path().join(".ota/org-policy.yaml"),
            r#"
policies:
  replay_inputs:
    identity:
      workflows:
        verify:
          on_insufficient: review
"#,
        )
        .unwrap();
        let contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .unwrap();

        let projection = ci_projection_for_contract(
            &contract,
            &contract_path,
            "verify",
            Some("native"),
            "linux",
        )
        .expect("matching checkout identity should permit projection");
        let requirement = projection
            .governance
            .replay_input_policy
            .as_ref()
            .expect("policy requirement should be projected");
        assert_eq!(
            requirement.rule_identities,
            ["replay_inputs:identity:workflow:verify"]
        );
        assert!(requirement.policy_identity.starts_with("sha256:"));
        assert_eq!(requirement.selected_closure, ["report", "verify"]);
        assert!(requirement.unknown_selector_identities.is_empty());
        let projection_json = serde_json::to_string(&projection).unwrap();
        assert!(!projection_json.contains("observed_identity"));
        assert!(!projection_json.contains(identity.as_str()));

        let unpinned_yaml =
            contract_yaml.replace(&format!("        expected_identity: {identity}\n"), "");
        let unpinned_contract = parse_contract_str(&contract_path, &unpinned_yaml).unwrap();
        let review = ci_projection_for_contract(
            &unpinned_contract,
            &contract_path,
            "verify",
            Some("native"),
            "linux",
        )
        .expect_err("review remains a refusing CI projection decision");
        assert_eq!(review.0, "replay_input_policy_review");

        fs::write(repo.path().join("fixture.txt"), "changed").unwrap();
        let refusal = ci_projection_for_contract(
            &contract,
            &contract_path,
            "verify",
            Some("native"),
            "linux",
        )
        .expect_err("provider checkout must re-evaluate the declared identity");
        assert_eq!(refusal.0, "replay_input_policy_deny");
        assert!(
            refusal
                .2
                .expect("denial projection should remain inspectable")
                .governance
                .replay_input_policy
                .is_some()
        );

        fs::write(
            repo.path().join(".ota/org-policy.yaml"),
            r#"
policies:
  replay_inputs:
    identity:
      tasks:
        missing:
          on_insufficient: deny
"#,
        )
        .unwrap();
        let unknown = ci_projection_for_contract(
            &contract,
            &contract_path,
            "verify",
            Some("native"),
            "linux",
        )
        .expect_err("unknown selectors must refuse projection");
        assert_eq!(unknown.0, "replay_input_policy_selector_unknown");
        assert_eq!(
            unknown
                .2
                .expect("unknown-selector projection should remain inspectable")
                .governance
                .replay_input_policy
                .expect("policy requirement should be present")
                .unknown_selector_identities,
            ["replay_inputs:identity:task:missing"]
        );
    }

    #[test]
    fn ci_projection_reuses_one_loaded_policy_across_all_governance_domains() {
        let repo = tempdir().expect("repo tempdir");
        let contract_path = repo.path().join("ota.yaml");
        fs::write(repo.path().join("fixture.txt"), "frozen").unwrap();
        let identity = crate::replay_inputs::sha256_identity(b"frozen");
        fs::write(
            &contract_path,
            format!(
                r#"
version: 1
project:
  name: projection-policy-snapshot
tasks:
  verify:
    safe_for_agent: true
    replay_inputs:
      - id: fixture
        kind: static_file
        path: fixture.txt
        expected_identity: {identity}
    command:
      exe: sh
      args: ["-c", "true"]
workflows:
  default: verify
  verify:
    run:
      task: verify
    proof:
      claim: bounded
agent:
  safe_tasks: [verify]
"#
            ),
        )
        .unwrap();
        fs::create_dir_all(repo.path().join(".ota")).unwrap();
        let policy_path = repo.path().join(".ota/org-policy.yaml");
        fs::write(
            &policy_path,
            r#"
policies:
  replay_inputs:
    identity:
      workflows:
        verify:
          on_insufficient: deny
"#,
        )
        .unwrap();
        let contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .unwrap();
        let loaded_policy = super::load_org_policy_pack_auto_details(&contract_path)
            .expect("policy should load")
            .expect("policy should exist");
        let policy_identity = loaded_policy
            .source_identity
            .clone()
            .expect("policy snapshot should have an identity");

        fs::write(&policy_path, "policies: [changed after command load]\n").unwrap();
        let projection = super::apply_ci_projection_governance(
            &contract,
            &contract_path,
            "verify",
            "native",
            super::build_ci_projection(&contract, "verify", "native", "linux").unwrap(),
            Some(&loaded_policy),
        )
        .expect("all governance domains must consume the already loaded policy");
        assert_eq!(
            projection
                .governance
                .replay_input_policy
                .expect("replay requirement")
                .policy_identity,
            policy_identity
        );
        assert_eq!(projection.governance.agent_admission.decision, "allow");
        assert_eq!(
            projection
                .governance
                .proof_assurance
                .expect("proof assurance")
                .policy_decision,
            "allow"
        );

        let failure = ci_projection_for_contract(
            &contract,
            &contract_path,
            "verify",
            Some("native"),
            "linux",
        )
        .expect_err("a new command must observe the changed invalid policy");
        assert_eq!(failure.0, "org_policy_unavailable");
    }

    #[test]
    fn ci_projection_re_evaluates_typed_effect_policy_on_the_provider_checkout() {
        use crate::policy_pack::PolicyEffectDecision;
        use sha2::{Digest as _, Sha256};

        let repo = tempdir().expect("repo tempdir");
        let contract_path = repo.path().join("ota.yaml");
        fs::create_dir_all(repo.path().join("migrations")).expect("migration directory");
        fs::create_dir_all(repo.path().join(".ota")).expect("policy directory");
        let migration_bytes = b"create table ci_projection_policy ();\n";
        fs::write(repo.path().join("migrations/001.sql"), migration_bytes)
            .expect("migration should write");
        let file_identity = format!("sha256:{:x}", Sha256::digest(migration_bytes));
        let manifest = serde_json::json!({
            "schema_version": 1,
            "root": "migrations",
            "files": [{ "path": "001.sql", "identity": file_identity }]
        });
        let mut manifest_identity_bytes = b"ota.schema-migration-manifest.v1\0".to_vec();
        manifest_identity_bytes
            .extend(serde_jcs::to_vec(&manifest).expect("manifest canonicalizes"));
        let manifest_identity = format!("sha256:{:x}", Sha256::digest(manifest_identity_bytes));
        let contract_yaml = format!(
            "version: 1\nproject:\n  name: ci-projection-typed-policy\nresource_bindings:\n  primary:\n    kind: database\n    provider: postgresql\n    namespace: {{ authority: dns:example.org, environment: production }}\neffect_definitions:\n  migration:\n    kind: database_schema_mutation\n    action: apply_migration_set\n    resource: {{ engine: postgresql, target_ref: primary, schema: public }}\n    bounds:\n      migration_set: {{ root: migrations, content_identity: {manifest_identity} }}\n      start_state: any_within_set\ntasks:\n  migrate:\n    safe_for_agent: true\n    action: {{ kind: database_schema_mutation, effect: migration }}\n    effects:\n      declared: [migration]\nworkflows:\n  default: migrate\n  migrate:\n    run:\n      task: migrate\nagent:\n  safe_tasks: [migrate]\n"
        );
        fs::write(&contract_path, contract_yaml).expect("contract should write");
        let contract = parse_contract_str(
            &contract_path,
            &fs::read_to_string(&contract_path).expect("contract should read"),
        )
        .expect("contract should parse");
        let policy_path = repo.path().join(".ota/org-policy.yaml");
        fs::write(
            &policy_path,
            "policies:\n  effects:\n    mode: compatibility\n",
        )
        .expect("compatibility policy should write");

        let projected = ci_projection_for_contract(
            &contract,
            &contract_path,
            "migrate",
            Some("native"),
            "linux",
        )
        .expect("compatibility policy should permit projection");
        assert_eq!(
            projected
                .governance
                .effect_policy_decision
                .as_ref()
                .expect("typed decision should be identity-bound")
                .aggregate_decision,
            PolicyEffectDecision::Warn
        );

        fs::write(
            &policy_path,
            "policies:\n  effects:\n    mode: compatibility\n    typed:\n      rules:\n        - id: deny_production_migration\n          selector:\n            kind: database_schema_mutation\n            actions: [apply_migration_set]\n            resource:\n              match: exact\n              engine: postgresql\n              namespace: { authority: dns:example.org, environment: production }\n              schema: public\n          decision: deny\n",
        )
        .expect("denying policy should write");
        let denied = ci_projection_for_contract(
            &contract,
            &contract_path,
            "migrate",
            Some("native"),
            "linux",
        )
        .expect_err("provider checkout must refuse a newly denied typed effect");
        assert_eq!(denied.0, "effect_policy_denied");
        assert_eq!(
            denied
                .2
                .expect("denial projection should remain inspectable")
                .governance
                .effect_policy_decision
                .expect("denial decision should be retained")
                .aggregate_decision,
            PolicyEffectDecision::Deny
        );
    }

    #[test]
    fn run_receipt_preserves_pre_execution_replay_policy_evidence() {
        let repo = tempdir().expect("repo tempdir");
        let contract_path = repo.path().join("ota.yaml");
        let expected = crate::replay_inputs::sha256_identity(b"frozen");
        fs::write(repo.path().join("fixture.txt"), "frozen").unwrap();
        fs::write(
            &contract_path,
            format!(
                r#"
version: 1
project:
  name: replay-policy-receipt
tasks:
  mutate:
    replay_inputs:
      - id: fixture
        kind: static_file
        path: fixture.txt
        expected_identity: {expected}
    run: printf changed > fixture.txt
"#
            ),
        )
        .unwrap();
        fs::create_dir_all(repo.path().join(".ota")).unwrap();
        fs::write(
            repo.path().join(".ota/org-policy.yaml"),
            r#"
policies:
  replay_inputs:
    identity:
      tasks:
        mutate:
          on_insufficient: deny
"#,
        )
        .unwrap();
        let contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .unwrap();
        let preflight = super::task_replay_input_preflight(&contract, &contract_path, "mutate");

        let success = super::run_single_contract_target_captured(
            "mutate",
            ExecutionOverrides::default(),
            None,
            super::LoadedContractTarget {
                contract,
                contract_path: contract_path.clone(),
            },
            &[],
            false,
            None,
            false,
            "inspect task usage",
            false,
            preflight,
        )
        .unwrap_or_else(|failure| panic!("matching input should be admitted: {}", failure.message));

        assert_eq!(
            fs::read_to_string(repo.path().join("fixture.txt")).unwrap(),
            "changed"
        );
        let evaluation = success
            .receipt
            .replay_input_policy
            .expect("receipt should retain pre-execution policy evidence");
        assert_eq!(evaluation.decision, "allow");
        assert_eq!(evaluation.inputs[0].status, "matched");
        assert_eq!(
            evaluation.inputs[0].observed_identity.as_deref(),
            Some(expected.as_str())
        );

        fs::write(repo.path().join("fixture.txt"), "frozen").unwrap();
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: replay-policy-refusal
tasks:
  mutate:
    replay_inputs:
      - id: fixture
        kind: static_file
        path: fixture.txt
    run: touch should-not-exist
"#,
        )
        .unwrap();
        let denied_contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .unwrap();
        let denied_preflight =
            super::task_replay_input_preflight(&denied_contract, &contract_path, "mutate");
        let failure = match super::run_single_contract_target_captured(
            "mutate",
            ExecutionOverrides::default(),
            None,
            super::LoadedContractTarget {
                contract: denied_contract,
                contract_path: contract_path.clone(),
            },
            &[],
            false,
            None,
            true,
            "inspect task usage",
            false,
            denied_preflight,
        ) {
            Ok(_) => {
                panic!("low-level execution boundary must refuse insufficient identity policy")
            }
            Err(failure) => failure,
        };
        assert!(
            failure
                .message
                .contains("Replay-input identity policy denies")
        );
        assert!(!repo.path().join("should-not-exist").exists());
    }

