    #[test]
    fn wait_for_proof_runtime_readiness_short_circuits_on_immediate_up_exit() {
        let _guard = cwd_mutex_lock();
        let contract_dir = TempDir::new().unwrap();
        let contract_path = contract_dir.path().join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: proof-runtime-regression
checks:
  - name: failing-check
    kind: precondition
    severity: error
    run: missing-check-command
    timeout: 10
tasks:
  app:
    command:
      exe: echo
      args:
        - ok
workflows:
  default: app
"#,
        )
        .unwrap();

        let contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .unwrap();

        let mut child = if cfg!(windows) {
            Command::new("cmd").args(["/C", "exit 1"]).spawn().unwrap()
        } else {
            Command::new("sh").args(["-c", "exit 1"]).spawn().unwrap()
        };

        let (report, phase, proof_ok, up_failure) = super::wait_for_proof_runtime_readiness(
            &contract,
            &contract_path,
            None,
            ExecutionOverrides::default(),
            &mut child,
            "ota up --stream",
            &contract_path,
            None,
            None,
            DoctorPolicySnapshot {
                loaded: None,
                load_error: None,
            },
        )
        .unwrap();

        assert!(!proof_ok);
        assert_eq!(phase, "readiness");
        let reason = up_failure.as_deref().unwrap_or_default();
        assert!(reason.contains("exit code 1"));
        assert!(!report.ok);

        let exit = child.wait().unwrap();
        assert!(!exit.success());
    }

    #[test]
    fn wait_for_proof_runtime_readiness_prefers_terminal_up_failure_before_doctor() {
        let _guard = cwd_mutex_lock();
        let contract_dir = TempDir::new().unwrap();
        let contract_path = contract_dir.path().join("ota.yaml");
        let up_log_path = contract_dir.path().join("up.log");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: proof-runtime-regression
checks:
  - name: failing-check
    kind: precondition
    severity: error
    run: missing-check-command
    timeout: 10
tasks:
  app:
    command:
      exe: echo
      args:
        - ok
workflows:
  default: app
"#,
        )
        .unwrap();
        fs::write(
            &up_log_path,
            "🦦 UP ./ota.yaml\n\n◉ ERROR  Listener bind conflict\nWhy: port 3000 is in use\n",
        )
        .unwrap();

        let contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .unwrap();

        let mut child = if cfg!(windows) {
            Command::new("cmd").args(["/C", "exit 1"]).spawn().unwrap()
        } else {
            Command::new("sh").args(["-c", "exit 1"]).spawn().unwrap()
        };

        let started = Instant::now();
        let (report, phase, proof_ok, up_failure) = super::wait_for_proof_runtime_readiness(
            &contract,
            &contract_path,
            None,
            ExecutionOverrides::default(),
            &mut child,
            "ota up --stream",
            &up_log_path,
            None,
            None,
            DoctorPolicySnapshot {
                loaded: None,
                load_error: None,
            },
        )
        .unwrap();

        assert!(started.elapsed() < Duration::from_secs(4));
        assert!(!proof_ok);
        assert_eq!(phase, "run");
        assert_eq!(
            report
                .findings
                .first()
                .map(|finding| finding.summary.as_str()),
            Some("Run task exited before readiness")
        );
        assert!(
            report
                .findings
                .first()
                .map(|finding| finding.why.contains("Listener bind conflict"))
                .unwrap_or(false),
            "{report:?}"
        );
        assert!(
            up_failure
                .as_deref()
                .map(|failure| failure.contains("Listener bind conflict"))
                .unwrap_or(false)
        );

        let exit = child.wait().unwrap();
        assert!(!exit.success());
    }

    #[test]
    fn wait_for_proof_runtime_readiness_observes_terminal_up_log_during_startup_grace() {
        let _guard = cwd_mutex_lock();
        let contract_dir = TempDir::new().unwrap();
        let contract_path = contract_dir.path().join("ota.yaml");
        let up_log_path = contract_dir.path().join("up.log");
        let slow_failing_check = if cfg!(windows) {
            "cmd /C ping -n 6 127.0.0.1 >NUL && exit 1"
        } else {
            "sh -c 'sleep 5; exit 1'"
        };
        fs::write(
            &contract_path,
            format!(
                r#"
version: 1
project:
  name: proof-runtime-regression
checks:
  - name: slow-failing-check
    kind: precondition
    severity: error
    run: {slow_failing_check}
tasks:
  app:
    command:
      exe: echo
      args:
        - ok
workflows:
  default: app
"#
            ),
        )
        .unwrap();
        fs::write(&up_log_path, "").unwrap();

        let contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .unwrap();

        let log_path = up_log_path.clone();
        let writer = thread::spawn(move || {
            thread::sleep(Duration::from_millis(200));
            fs::write(
                &log_path,
                "🦦 UP ./ota.yaml\n\n◉ ERROR  Listener bind conflict\nWhy: port 3000 is in use\n",
            )
            .unwrap();
        });

        let mut child = if cfg!(windows) {
            Command::new("cmd")
                .args(["/C", "ping -n 30 127.0.0.1 >NUL"])
                .spawn()
                .unwrap()
        } else {
            Command::new("sh").args(["-c", "sleep 30"]).spawn().unwrap()
        };

        let started = Instant::now();
        let (report, phase, proof_ok, up_failure) = super::wait_for_proof_runtime_readiness(
            &contract,
            &contract_path,
            None,
            ExecutionOverrides::default(),
            &mut child,
            "ota up --stream",
            &up_log_path,
            Some(Duration::from_secs(5)),
            None,
            DoctorPolicySnapshot {
                loaded: None,
                load_error: None,
            },
        )
        .unwrap();

        let _ = child.kill();
        let _ = child.wait();
        writer.join().unwrap();

        assert!(started.elapsed() < Duration::from_secs(4));
        assert!(!proof_ok);
        assert_eq!(phase, "run");
        assert_eq!(
            report
                .findings
                .first()
                .map(|finding| finding.summary.as_str()),
            Some("Run task exited before readiness")
        );
        assert!(
            up_failure
                .as_deref()
                .map(|failure| failure.contains("Listener bind conflict"))
                .unwrap_or(false)
        );
    }

    #[test]
    fn wait_for_proof_runtime_readiness_captures_final_doctor_once_probe_is_observed() {
        let _guard = cwd_mutex_lock();
        let listener = TcpListener::bind("127.0.0.1:0").expect("listener should bind");
        let port = listener.local_addr().unwrap().port();
        let server = thread::spawn(move || {
            for _ in 0..2 {
                let (mut stream, _) = listener.accept().expect("probe should connect");
                let mut buffer = [0u8; 256];
                let _ = stream.read(&mut buffer);
                stream
                    .write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 0\r\nConnection: close\r\n\r\n")
                    .expect("probe response should write");
            }
        });
        let failing_check = if cfg!(windows) {
            "cmd /C exit 1"
        } else {
            "sh -c 'exit 1'"
        };

        let contract_dir = TempDir::new().unwrap();
        let contract_path = contract_dir.path().join("ota.yaml");
        fs::write(
            &contract_path,
            format!(
                r#"
version: 1
project:
  name: proof-runtime-regression
readiness:
  probes:
    backend-ready:
      kind: http
      url: http://127.0.0.1:{port}/healthz/readiness
      timeout: 1000
checks:
  - name: setup-complete
    kind: health
    severity: error
    run: {failing_check}
tasks:
  app:
    command:
      exe: echo
      args:
        - ok
workflows:
  default: app
  app:
    run:
      task: app
    readiness:
      probes:
        - backend-ready
      checks:
        - setup-complete
"#
            ),
        )
        .unwrap();

        let contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .unwrap();

        let mut child = if cfg!(windows) {
            Command::new("cmd")
                .args(["/C", "ping -n 30 127.0.0.1 >NUL"])
                .spawn()
                .unwrap()
        } else {
            Command::new("sh").args(["-c", "sleep 30"]).spawn().unwrap()
        };

        let started = Instant::now();
        let (report, phase, proof_ok, up_failure) = super::wait_for_proof_runtime_readiness(
            &contract,
            &contract_path,
            Some("app"),
            ExecutionOverrides::default(),
            &mut child,
            "ota up --stream",
            &contract_path,
            None,
            None,
            DoctorPolicySnapshot {
                loaded: None,
                load_error: None,
            },
        )
        .unwrap();

        child.kill().unwrap();
        let _ = child.wait();
        server.join().expect("probe server should finish");

        assert!(started.elapsed() < Duration::from_secs(5));
        assert!(!proof_ok);
        assert_eq!(phase, "readiness");
        assert!(up_failure.is_none());
        assert!(!report.ok);
        assert!(
            report
                .findings
                .iter()
                .any(|finding| finding.summary == "Check failed: setup-complete"),
            "{report:?}"
        );
    }

