    #[test]
    fn receipt_uses_workflow_scoped_archive_identity_for_latest_baseline() {
        let fixture = TempDir::new().unwrap();
        let contract_path = fixture.path().join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: ota
tasks:
  build:
    run: echo build
workflows:
  default: app
  app:
    run:
      task: build
  docs:
    run:
      task: build
"#,
        )
        .unwrap();

        let app_archive = super::receipt(
            Some(contract_path.as_path()),
            None,
            None,
            Some("app"),
            ExecutionOverrides::default(),
            OutputFormat::Json,
            None,
            None,
            false,
            false,
            crate::cli::ReceiptHistorySource::Local,
            None,
            true,
            false,
            false,
        );
        let app_archive_body: serde_json::Value =
            serde_json::from_str(&app_archive.stdout).unwrap();
        assert_eq!(app_archive_body["workflow"], "app");

        let docs_archive = super::receipt(
            Some(contract_path.as_path()),
            None,
            None,
            Some("docs"),
            ExecutionOverrides::default(),
            OutputFormat::Json,
            None,
            None,
            false,
            false,
            crate::cli::ReceiptHistorySource::Local,
            None,
            true,
            false,
            false,
        );
        let docs_archive_body: serde_json::Value =
            serde_json::from_str(&docs_archive.stdout).unwrap();
        assert_eq!(docs_archive_body["workflow"], "docs");

        let diff = super::receipt(
            Some(contract_path.as_path()),
            None,
            None,
            Some("app"),
            ExecutionOverrides::default(),
            OutputFormat::Json,
            None,
            Some("latest"),
            false,
            false,
            crate::cli::ReceiptHistorySource::Local,
            None,
            false,
            false,
            false,
        );
        let diff_body: serde_json::Value = serde_json::from_str(&diff.stdout).unwrap();

        assert_eq!(
            diff_body["baseline"]["contract_identity"],
            "ota.yaml#workflow:app"
        );
        assert_eq!(
            diff_body["current"]["contract_identity"],
            "ota.yaml#workflow:app"
        );
    }

    #[test]
    fn proof_runtime_marks_declared_service_exercise_as_not_proved_without_observation() {
        let contract_path = Path::new("ota.yaml");
        let contract = parse_contract_str(
            contract_path,
            r#"
version: 1
project:
  name: proof-seam
tasks:
  verify:
    run: "true"
    requires_services:
      - postgres
workflows:
  default: verify
  verify:
    run:
      task: verify
"#,
        )
        .expect("parse proof seam contract");

        let not_proved =
            super::proof_runtime_not_proved(&contract, contract_path, Some("verify"), &[]);
        let seam = not_proved
            .iter()
            .find(|entry| entry.kind == "dependency_exercise_not_proved")
            .expect("declared service seam stays unproved without observed interaction");
        assert_eq!(seam.dependency_id.as_deref(), Some("service:postgres"));
        assert_eq!(
            seam.reason.as_deref(),
            Some("no_independent_dependency_evidence")
        );
        assert_eq!(seam.declared_by_tasks, ["verify"]);
        assert_eq!(seam.declared_by_workflows, ["verify"]);
        assert_eq!(
            not_proved.first().map(|entry| entry.kind.as_str()),
            Some("dependency_exercise_not_proved"),
            "a direct declared seam must outrank the generic proof remainder"
        );
    }

