    #[test]
    fn proof_runtime_marks_caller_side_service_attempt_without_exercised_evidence() {
        let contract_path = Path::new("ota.yaml");
        let contract = parse_contract_str(
            contract_path,
            r#"
version: 1
project:
  name: proof-seam
services:
  postgres:
    manager:
      kind: compose
      service: postgres
    readiness:
      kind: compose_health
tasks:
  verify:
    run: "true"
    requires_services:
      - postgres
workflows:
  default: verify
  verify:
    services:
      required:
        - postgres
    run:
      task: verify
"#,
        )
        .expect("parse proof seam contract");

        let evidence = super::proof_runtime_dependency_evidence(
            &contract,
            Some("verify"),
            false,
            Some(
                &super::ProofRuntimeLikelyCause::DnsServiceNameResolutionFailure {
                    artifact: PathBuf::from("./.ota/proof/verify/up.log"),
                    host: Some(String::from("postgres")),
                    signal: String::from("getaddrinfo ENOTFOUND postgres"),
                },
            ),
        );
        assert_eq!(evidence.len(), 1);
        assert_eq!(evidence[0].dependency_id, "service:postgres");
        assert_eq!(evidence[0].level, None);
        assert!(evidence[0].interaction_attempted);
        assert_eq!(evidence[0].observation.origin, "caller_side");

        let not_proved =
            super::proof_runtime_not_proved(&contract, contract_path, Some("verify"), &evidence);
        let seam = not_proved
            .iter()
            .find(|entry| entry.kind == "dependency_exercise_not_proved")
            .expect("declared seam should remain not proved");
        assert_eq!(seam.reason.as_deref(), Some("caller_side_only_evidence"));
    }

    #[test]
    fn proof_runtime_marker_observation_removes_only_that_seam_boundary() {
        let contract_path = Path::new("ota.yaml");
        let contract = parse_contract_str(
            contract_path,
            r#"
version: 1
project:
  name: proof-seam
services:
  postgres:
    manager:
      kind: compose
      service: postgres
    readiness:
      kind: compose_health
tasks:
  verify:
    run: "true"
    requires_services:
      - postgres
workflows:
  default: verify
  verify:
    services:
      required:
        - postgres
    run:
      task: verify
"#,
        )
        .expect("parse proof seam contract");
        let evidence = vec![crate::output::ProofRuntimeDependencyEvidence {
            dependency_id: String::from("service:postgres"),
            proof_obligation_id: Some(String::from("postgres-marker")),
            level: Some(String::from("exercised")),
            interaction_attempted: false,
            observation: crate::output::ProofRuntimeDependencyObservation {
                origin: String::from("round_trip_effect"),
                evidence_class: ExecutionEvidenceClass::Attested,
            },
            declared_by_tasks: vec![String::from("observe-marker")],
            declared_by_workflows: vec![String::from("verify")],
            negative_control: None,
        }];

        let not_proved =
            super::proof_runtime_not_proved(&contract, contract_path, Some("verify"), &evidence);
        assert!(
            !not_proved.iter().any(|entry| {
                entry.kind == "dependency_exercise_not_proved"
                    && entry.dependency_id.as_deref() == Some("service:postgres")
            }),
            "an attested marker observation must close only its declared seam boundary"
        );

        let mut fault_tested = evidence.clone();
        fault_tested[0].level = Some(String::from("fault_tested"));
        let fault_tested_not_proved = super::proof_runtime_not_proved(
            &contract,
            contract_path,
            Some("verify"),
            &fault_tested,
        );
        assert!(
            !fault_tested_not_proved.iter().any(|entry| {
                entry.kind == "dependency_exercise_not_proved"
                    && entry.dependency_id.as_deref() == Some("service:postgres")
            }),
            "fault-tested evidence must continue to satisfy the underlying exercised seam"
        );
    }

