    #[test]
    fn proof_runtime_negative_control_rejects_nonzero_exit_without_failure_attestation() {
        let fixture = TempDir::new().unwrap();
        let contract_path = fixture.path().join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: negative-control
tasks:
  control:
    run: "exit 1"
"#,
        )
        .unwrap();
        let control = crate::schema::WorkflowNegativeControlSpec {
            id: String::from("postgres-down"),
            dependency: String::from("postgres"),
            obligation: String::from("postgres-marker"),
            task: String::from("control"),
            intervention: crate::schema::WorkflowNegativeControlInterventionSpec {
                kind: crate::schema::WorkflowNegativeControlInterventionKind::DependencyDisruption,
            },
            expected_failure:
                crate::schema::WorkflowNegativeControlFailureKind::DependencyUnavailable,
        };
        let obligation = crate::output::ProofRuntimeSeamObservation {
            id: String::from("postgres-marker"),
            dependency_id: String::from("service:postgres"),
            producer_task: String::from("write-marker"),
            transaction_id: String::from("sha256:transaction"),
            observer_task: String::from("observe-marker"),
            marker_env: String::from("OTA_PROOF_POSTGRES_MARKER"),
            outcome: crate::output::ProofRuntimeSeamObservationOutcome::Observed,
            proof_scope_ref: String::from("workflow:app/seam_observation:postgres-marker"),
            evidence_class: ExecutionEvidenceClass::Attested,
            attestation_digest: Some(String::from("sha256:attestation")),
            exit_code: Some(0),
            detail: None,
        };

        let record = super::proof_runtime_execute_negative_control(
            &contract_path,
            &control,
            Some("app"),
            ExecutionOverrides::default(),
            Some(&obligation),
            true,
            fixture.path(),
        );

        assert_eq!(
            record.outcome,
            crate::output::ProofRuntimeNegativeControlOutcome::NonzeroExitObserved
        );
        assert_eq!(record.dependency_id, "service:postgres");
        assert!(record.exit_code.is_some_and(|exit_code| exit_code != 0));
        assert_eq!(record.evidence_class, ExecutionEvidenceClass::Attested);
        assert_eq!(
            record.status,
            crate::output::ProofRuntimeNegativeControlStatus::Invalid
        );
        assert_eq!(
            record.failure_mode,
            Some(crate::output::ProofRuntimeNegativeControlFailureMode::UnclassifiedNonzero)
        );
        assert_eq!(record.intervention.kind, "dependency_disruption");
        assert!(record.failure_attestation_digest.is_none());
        assert_eq!(
            record.proof_scope_ref,
            "workflow:app/negative_control:postgres-down"
        );
    }

    #[test]
    fn proof_runtime_negative_control_attestation_requires_same_transaction_and_obligation() {
        let fixture = TempDir::new().unwrap();
        let attestation_path = fixture.path().join("control.json");
        let control = crate::schema::WorkflowNegativeControlSpec {
            id: String::from("postgres-down"),
            dependency: String::from("postgres"),
            obligation: String::from("postgres-marker"),
            task: String::from("control"),
            intervention: crate::schema::WorkflowNegativeControlInterventionSpec {
                kind: crate::schema::WorkflowNegativeControlInterventionKind::DependencyDisruption,
            },
            expected_failure:
                crate::schema::WorkflowNegativeControlFailureKind::DependencyUnavailable,
        };
        let obligation = crate::output::ProofRuntimeSeamObservation {
            id: String::from("postgres-marker"),
            dependency_id: String::from("service:postgres"),
            producer_task: String::from("write-marker"),
            transaction_id: String::from("sha256:transaction"),
            observer_task: String::from("observe-marker"),
            marker_env: String::from("OTA_PROOF_POSTGRES_MARKER"),
            outcome: crate::output::ProofRuntimeSeamObservationOutcome::Observed,
            proof_scope_ref: String::from("workflow:app/seam_observation:postgres-marker"),
            evidence_class: ExecutionEvidenceClass::Attested,
            attestation_digest: Some(String::from("sha256:attestation")),
            exit_code: Some(0),
            detail: None,
        };
        fs::write(
            &attestation_path,
            r#"{"transaction_id":"sha256:transaction","control_id":"postgres-down","obligation_id":"postgres-marker","failure_kind":"dependency_unavailable"}"#,
        )
        .unwrap();
        let digest = super::proof_runtime_read_negative_control_attestation(
            &attestation_path,
            &control,
            &obligation,
        )
        .expect("matching negative-control attestation should validate");
        assert!(digest.starts_with("sha256:"));

        fs::write(
            &attestation_path,
            r#"{"transaction_id":"sha256:other","control_id":"postgres-down","obligation_id":"postgres-marker","failure_kind":"dependency_unavailable"}"#,
        )
        .unwrap();
        let mismatched = super::proof_runtime_read_negative_control_attestation(
            &attestation_path,
            &control,
            &obligation,
        )
        .expect_err("a stale control attestation must not promote fault-tested evidence");
        assert!(mismatched.detail.contains("different proof transaction"));
        assert_eq!(
            mismatched.failure_mode,
            crate::output::ProofRuntimeNegativeControlFailureMode::UnclassifiedNonzero
        );

        fs::write(
            &attestation_path,
            r#"{"transaction_id":"sha256:transaction","control_id":"postgres-down","obligation_id":"postgres-marker","failure_kind":"unexpected_failure"}"#,
        )
        .unwrap();
        let wrong_failure = super::proof_runtime_read_negative_control_attestation(
            &attestation_path,
            &control,
            &obligation,
        )
        .expect_err("a mismatched failure kind must not promote fault-tested evidence");
        assert!(wrong_failure.detail.contains("instead of expected"));
        assert_eq!(
            wrong_failure.failure_mode,
            crate::output::ProofRuntimeNegativeControlFailureMode::WrongAssertion
        );
    }

    #[test]
    fn proof_runtime_negative_control_promotes_only_validated_same_obligation_evidence() {
        let evidence = || crate::output::ProofRuntimeDependencyEvidence {
            dependency_id: String::from("service:postgres"),
            proof_obligation_id: Some(String::from("postgres-marker")),
            level: Some(String::from("exercised")),
            interaction_attempted: false,
            observation: crate::output::ProofRuntimeDependencyObservation {
                origin: String::from("round_trip_effect"),
                evidence_class: ExecutionEvidenceClass::Attested,
            },
            declared_by_tasks: vec![String::from("observe-marker")],
            declared_by_workflows: vec![String::from("app")],
            negative_control: None,
        };
        let control = |status| crate::output::ProofRuntimeNegativeControl {
            id: String::from("postgres-down"),
            dependency_id: String::from("service:postgres"),
            obligation_id: String::from("postgres-marker"),
            transaction_id: Some(String::from("sha256:transaction")),
            control_task: String::from("control"),
            intervention: crate::output::ProofRuntimeNegativeControlIntervention {
                kind: String::from("dependency_disruption"),
                id: String::from("postgres-down"),
            },
            expected_failure: String::from("dependency_unavailable"),
            outcome: crate::output::ProofRuntimeNegativeControlOutcome::ExpectedObligationFailed,
            status,
            failure_mode: Some(
                crate::output::ProofRuntimeNegativeControlFailureMode::ExpectedMissingEffect,
            ),
            proof_scope_ref: String::from("workflow:app/negative_control:postgres-down"),
            evidence_class: ExecutionEvidenceClass::Attested,
            failure_attestation_digest: Some(String::from("sha256:failure")),
            exit_code: Some(1),
            detail: None,
        };

        let validated_control =
            control(crate::output::ProofRuntimeNegativeControlStatus::Validated);
        let mut validated = vec![evidence()];
        super::proof_runtime_apply_negative_control_projection(&mut validated, &validated_control);
        assert_eq!(validated[0].level.as_deref(), Some("fault_tested"));
        assert_eq!(
            validated[0]
                .negative_control
                .as_ref()
                .map(|value| (value.status, value.evidence_class)),
            Some((
                crate::output::ProofRuntimeNegativeControlStatus::Validated,
                ExecutionEvidenceClass::Derived
            ))
        );
        let projected_control = validated[0]
            .negative_control
            .as_ref()
            .expect("validated controls must project onto their matching dependency evidence");
        assert_eq!(
            validated[0].proof_obligation_id.as_deref(),
            Some(validated_control.obligation_id.as_str())
        );
        assert_eq!(
            projected_control.failure_attestation_digest.as_deref(),
            validated_control.failure_attestation_digest.as_deref()
        );
        assert_eq!(
            projected_control.negative_control_id.as_deref(),
            Some(validated_control.id.as_str())
        );
        assert!(projected_control.same_obligation);
        let mut fault_tested_boundaries = Vec::new();
        super::proof_runtime_append_dependency_scope_boundaries(
            &mut fault_tested_boundaries,
            &validated,
            Some("app"),
        );
        assert!(fault_tested_boundaries.iter().any(|entry| {
            entry.kind == "dependency_output_shaping_not_proved"
                && entry.dependency_id.as_deref() == Some("service:postgres")
                && entry.proof_obligation_id.as_deref() == Some("postgres-marker")
                && entry.reason.as_deref()
                    == Some("causal_evidence_scoped_to_declared_seam_obligation")
        }));
        assert!(
            !fault_tested_boundaries
                .iter()
                .any(|entry| entry.kind == "dependency_causality_not_proved")
        );
        let depth_boundary = fault_tested_boundaries
            .iter()
            .find(|entry| entry.kind == "dependency_output_shaping_not_proved")
            .expect("fault-tested evidence must retain its output-shaping boundary");
        let depth_boundary_json = serde_json::to_value(depth_boundary).unwrap();
        assert_eq!(
            depth_boundary_json["proof_obligation_id"].as_str(),
            Some("postgres-marker")
        );

        // Every marker-bound seam keeps its own depth boundary, even when a neighboring seam has
        // a validated negative control and is promoted to fault-tested evidence.
        let mut redis_evidence = evidence();
        redis_evidence.dependency_id = String::from("service:redis");
        redis_evidence.proof_obligation_id = Some(String::from("redis-marker"));
        redis_evidence.declared_by_tasks = vec![String::from("observe-redis-marker")];
        let mut multi_seam_boundaries = Vec::new();
        super::proof_runtime_append_dependency_scope_boundaries(
            &mut multi_seam_boundaries,
            &[validated[0].clone(), redis_evidence],
            Some("app"),
        );
        let output_shaping_boundaries = multi_seam_boundaries
            .iter()
            .filter(|entry| entry.kind == "dependency_output_shaping_not_proved")
            .map(|entry| {
                (
                    entry.dependency_id.as_deref(),
                    entry.proof_obligation_id.as_deref(),
                )
            })
            .collect::<Vec<_>>();
        assert_eq!(
            output_shaping_boundaries,
            vec![
                (Some("service:postgres"), Some("postgres-marker")),
                (Some("service:redis"), Some("redis-marker")),
            ]
        );

        let mut invalid = vec![evidence()];
        super::proof_runtime_apply_negative_control_projection(
            &mut invalid,
            &control(crate::output::ProofRuntimeNegativeControlStatus::Invalid),
        );
        assert_eq!(invalid[0].level.as_deref(), Some("exercised"));
        assert_eq!(
            invalid[0].negative_control.as_ref().map(|value| (
                value.same_obligation,
                value.negative_control_id.as_deref(),
                value.failure_attestation_digest.as_deref()
            )),
            Some((false, None, None))
        );
        let mut boundaries = Vec::new();
        super::proof_runtime_append_dependency_scope_boundaries(
            &mut boundaries,
            &invalid,
            Some("app"),
        );
        assert!(boundaries.iter().any(|entry| {
            entry.kind == "dependency_causality_not_proved"
                && entry.reason.as_deref() == Some("negative_control_invalid")
        }));
        assert!(boundaries.iter().any(|entry| {
            entry.kind == "dependency_output_shaping_not_proved"
                && entry.reason.as_deref() == Some("seam_evidence_scoped_to_declared_obligation")
        }));

        let mut unrun = vec![evidence()];
        super::proof_runtime_apply_negative_control_projection(
            &mut unrun,
            &control(crate::output::ProofRuntimeNegativeControlStatus::Unrun),
        );
        assert_eq!(unrun[0].level.as_deref(), Some("exercised"));
        assert_eq!(
            unrun[0].negative_control.as_ref().map(|value| (
                value.same_obligation,
                value.negative_control_id.as_deref(),
                value.failure_attestation_digest.as_deref()
            )),
            Some((false, None, None))
        );

        let mut malformed_validated =
            control(crate::output::ProofRuntimeNegativeControlStatus::Validated);
        malformed_validated.failure_mode =
            Some(crate::output::ProofRuntimeNegativeControlFailureMode::UnclassifiedNonzero);
        let mut malformed = vec![evidence()];
        super::proof_runtime_apply_negative_control_projection(
            &mut malformed,
            &malformed_validated,
        );
        assert_eq!(malformed[0].level.as_deref(), Some("exercised"));
        assert_eq!(
            malformed[0]
                .negative_control
                .as_ref()
                .map(|value| value.same_obligation),
            Some(false)
        );
        let mut malformed_boundaries = Vec::new();
        super::proof_runtime_append_dependency_scope_boundaries(
            &mut malformed_boundaries,
            &malformed,
            Some("app"),
        );
        assert!(malformed_boundaries.iter().any(|entry| {
            entry.kind == "dependency_causality_not_proved"
                && entry.reason.as_deref() == Some("negative_control_invalid")
        }));
        assert!(malformed_boundaries.iter().any(|entry| {
            entry.kind == "dependency_output_shaping_not_proved"
                && entry.reason.as_deref() == Some("seam_evidence_scoped_to_declared_obligation")
        }));

        let mut unselected_boundaries = Vec::new();
        super::proof_runtime_append_dependency_scope_boundaries(
            &mut unselected_boundaries,
            &[evidence()],
            Some("app"),
        );
        assert!(unselected_boundaries.iter().any(|entry| {
            entry.kind == "dependency_causality_not_proved"
                && entry.reason.as_deref() == Some("no_negative_control_selected")
        }));
        assert!(unselected_boundaries.iter().any(|entry| {
            entry.kind == "dependency_output_shaping_not_proved"
                && entry.reason.as_deref() == Some("seam_evidence_scoped_to_declared_obligation")
        }));
    }

