    #[test]
    fn workflow_summary_resolves_surface_exposes_to_urls() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
surfaces:
  backend:
    kind: http
    port: 5678
tasks:
  dev:be:
    run: pnpm dev:be
    runtime:
      kind: service
      surfaces:
        backend:
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 5678
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: 3000
              path: /app
              primary: true
workflows:
  default: backend
  backend:
    run:
      task: dev:be
    exposes:
      - surface: backend
"#,
        )
        .unwrap();

        let workflow =
            crate::output::WorkflowSummary::from_contract_selected(&contract, Some("backend"))
                .expect("workflow summary should exist");

        assert_eq!(
            workflow.exposes,
            vec![String::from("http://127.0.0.1:3000/app")]
        );
        assert_eq!(workflow.expose_surfaces, vec![String::from("backend")]);
    }

    #[test]
    fn workflow_summary_includes_transitive_task_required_services() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: ota
tasks:
  setup:
    run: pnpm install
    requires_services:
      - postgres
  app:
    run: pnpm dev
    depends_on:
      - setup
    requires_services:
      - redis
workflows:
  default: app
  app:
    run:
      task: app
    services:
      required:
        - docker
"#,
        )
        .unwrap();

        let workflow =
            crate::output::WorkflowSummary::from_contract_selected(&contract, Some("app"))
                .expect("workflow summary should exist");
        assert_eq!(
            workflow.required_services,
            vec![
                String::from("docker"),
                String::from("postgres"),
                String::from("redis"),
            ]
        );
    }

