    #[test]
    fn receipt_artifact_routing_uses_explicit_snapshot_selection_path() {
        let receipt = crate::output::ExecutionReceipt {
            ok: true,
            path: String::from("/tmp/demo"),
            scope: String::from("repo"),
            contract: String::from("/tmp/demo/contracts/custom-ota.yaml"),
            contract_identity: None,
            contract_snapshot_hash: Some(String::from("sha256:abc")),
            contract_snapshot_ref: Some(String::from(".ota/contracts/sha256-abc.json")),
            assumption_set_hash: None,
            evaluated_inputs: Vec::new(),
            witnessed_observations: crate::output::ExecutionReceiptWitnessedObservations::default(),
            crossing: None,
            refusal: None,
            typed_effect_policy_refusal: None,
            replay_input_policy: None,
            workspace: None,
            backend: None,
            context: None,
            lifecycle: None,
            image: None,
            container_memory_bytes: None,
            target: None,
            provider: None,
            cwd: None,
            acquired: Vec::new(),
            env: BTreeMap::new(),
            env_sources: Vec::new(),
            workflow_env_artifacts: Vec::new(),
            native_prerequisites: Vec::new(),
            toolchains: Vec::new(),
            runtime: None,
            service_termination: None,
            host_service_cleanup: Vec::new(),
            backend_fulfillment: None,
            logs: None,
            workloads: BTreeMap::new(),
            policy: Vec::new(),
            dependency_steps: Vec::new(),
            steps: Vec::new(),
            status: None,
            failed_task: None,
            failed_dependency: None,
            failure_origin: None,
            blocked: Vec::new(),
            summary: crate::output::ExecutionReceiptSummary {
                error_count: 0,
                warn_count: 0,
                info_count: 0,
                step_count: 0,
                repo_count: None,
                ready_count: None,
                not_ready_count: None,
            },
            next: None,
        };

        let routes = super::receipt_artifact_routing(
            Path::new("/tmp/demo/contracts/custom-ota.yaml"),
            Some("dev"),
            &receipt,
            Some(".ota/receipts/repo-receipt.json"),
        );

        let snapshot = routes
            .iter()
            .find(|route| route.kind == "contract_snapshot")
            .expect("snapshot route should exist");
        let snapshot_command = snapshot
            .command
            .as_deref()
            .expect("snapshot route should include inspect command")
            .replace('\\', "/");

        assert!(
            snapshot_command.starts_with("ota receipt --snapshot .ota/contracts/sha256-abc.json "),
            "unexpected snapshot command prefix: {snapshot_command}"
        );
        assert!(
            snapshot_command.ends_with("/tmp/demo/contracts/custom-ota.yaml"),
            "unexpected snapshot contract target path: {snapshot_command}"
        );
        assert_eq!(
            snapshot.path.as_deref(),
            Some(".ota/contracts/sha256-abc.json")
        );
    }

