    #[test]
    fn clean_text_reports_single_runtime_projection_load_issue_concisely() {
        let _guard = cwd_mutex_lock();
        let repo = tempfile::tempdir().expect("repo tempdir");
        let contract_path = repo.path().join("ota.yaml");
        std::fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: ota
execution:
  default_context: host
  contexts:
    host:
      backend: native
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/dev:latest
tasks:
  dev:
    context: app
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 3000
          project:
            host:
              address: 127.0.0.1
              port: {}
"#,
        )
        .expect("write contract");

        let cwd = env::current_dir().expect("current dir");
        env::set_current_dir(repo.path()).expect("set current dir");

        let output = strip_ansi_codes(
            super::clean(
                Some(repo.path()),
                None,
                &[],
                false,
                false,
                OutputFormat::Text,
                false,
            )
            .stderr
            .as_deref()
            .expect("stderr"),
        );

        assert!(
            output.contains("Field: tasks.dev.runtime.listeners.http.project.host.port.mode"),
            "{output}"
        );
        assert!(
            output.contains("task `dev` listener `http` host publication port is missing `mode`")
        );
        assert!(output.contains(
            "set `project.host.port.mode` to `auto` if you want Ota to choose the host port"
        ));
        assert!(output.contains("rerun `ota clean .`") || output.contains("rerun `ota clean`"));
        assert!(!output.contains("inspect ./ota.yaml"));
        assert!(!output.contains("rerun `ota validate ./ota.yaml`"));

        env::set_current_dir(cwd).expect("restore current dir");
    }

    #[test]
    fn detect_dry_run_json_prefers_python_toolchain_contract_when_provider_is_shipped() {
        let repo = tempfile::tempdir().expect("repo tempdir");
        fs::write(
            repo.path().join("pyproject.toml"),
            "[project]\nname = 'demo'\nrequires-python = '>=3.12'\n",
        )
        .expect("write pyproject");
        fs::write(repo.path().join("uv.lock"), "version = 1\n").expect("write uv.lock");
        fs::write(repo.path().join(".python-version"), "3.12\n").expect("write .python-version");

        let output = super::detect(
            Some(repo.path()),
            false,
            true,
            false,
            false,
            &[],
            false,
            false,
            false,
            None,
            OutputFormat::Json,
            false,
        );

        assert_eq!(output.exit_code, 0, "{}", output.stdout);
        let json: serde_json::Value =
            serde_json::from_str(&output.stdout).expect("parse detect json");
        assert!(
            json["config"]["toolchains"]["python"]["provider"].is_null(),
            "{json}"
        );
        assert_eq!(
            json["config"]["toolchains"]["python"]["version"],
            serde_json::Value::String(String::from("3.12"))
        );
        assert!(json["config"]["runtimes"]["python"].is_null(), "{json}");
        assert!(json["config"]["tools"]["uv"].is_null(), "{json}");
        assert!(
            json["toolchain_opportunities"].as_array().is_none(),
            "{json}"
        );
    }

