    #[test]
    fn run_agent_refuses_task_outside_safe_surface() {
        let repo = tempfile::tempdir().expect("repo tempdir");
        fs::write(
            repo.path().join("ota.yaml"),
            r#"
version: 1
project:
  name: demo
tasks:
  publish:
    run: echo publish
agent:
  safe_tasks: []
"#,
        )
        .expect("write contract");

        let output = super::run_command_with_agent(
            "publish",
            Some(repo.path()),
            None,
            OutputFormat::Text,
            ExecutionOverrides::default(),
            &[],
            &[],
            &[],
            true,
            false,
            false,
            false,
            false,
            false,
        );

        assert_eq!(output.exit_code, 1);
        let stderr = strip_ansi_codes(output.stderr.as_deref().unwrap_or_default());
        assert!(stderr.contains("AGENT EXECUTION REFUSED"), "{stderr}");
        assert!(stderr.contains("Agent execution refused"), "{stderr}");
        assert!(
            stderr.contains("task `publish` is outside the declared agent-safe surface"),
            "{stderr}"
        );
        assert!(stderr.contains("Refusal:"), "{stderr}");
        assert!(
            stderr.contains("reason: `requested_task_not_safe`"),
            "{stderr}"
        );
        assert!(
            stderr.contains("cause: `agent_safety_boundary`"),
            "{stderr}"
        );
        assert!(stderr.contains("closure status: `unsafe`"), "{stderr}");
        let normalized = stderr.split_whitespace().collect::<Vec<_>>().join(" ");
        assert!(
            normalized.contains("refused before run-path evaluation"),
            "{stderr}"
        );
        assert!(stderr.contains("RUN SUMMARY"), "{stderr}");
        assert!(!stderr.contains("Operation failed"), "{stderr}");
        assert!(!stderr.contains("\nContract\n"), "{stderr}");
        assert!(
            stderr.contains("rerun `ota run publish --agent`"),
            "{stderr}"
        );
        assert!(stderr.contains("ota tasks --safe --use"), "{stderr}");
    }

    #[test]
    fn run_agent_refuses_declared_safe_task_with_unsafe_dependency_closure() {
        let repo = tempfile::tempdir().expect("repo tempdir");
        fs::write(
            repo.path().join("ota.yaml"),
            r#"
version: 1
project:
  name: demo
tasks:
  setup:
    run: echo setup
  verify:
    safe_for_agent: true
    depends_on:
      - setup
    run: echo verify
agent:
  safe_tasks:
    - verify
"#,
        )
        .expect("write contract");

        let output = super::run_command_with_agent(
            "verify",
            Some(repo.path()),
            None,
            OutputFormat::Text,
            ExecutionOverrides::default(),
            &[],
            &[],
            &[],
            true,
            false,
            false,
            false,
            false,
            false,
        );

        assert_eq!(output.exit_code, 1);
        let stderr = strip_ansi_codes(output.stderr.as_deref().unwrap_or_default());
        assert!(
            stderr.contains("reachable execution closure includes `setup`"),
            "{stderr}"
        );
        assert!(
            stderr.contains("refused before run-path evaluation"),
            "{stderr}"
        );
        assert!(stderr.contains("blocked task: `setup`"), "{stderr}");
        assert!(stderr.contains("path: `verify -> setup`"), "{stderr}");
    }

