    #[cfg(unix)]
    #[test]
    fn streamed_run_command_persists_logs_when_interrupted() {
        let _guard = crate::test_support::env_mutex_lock();
        let _interrupt_guard = isolate_run_interrupt_for_test();
        let repo = tempfile::tempdir().expect("repo tempdir");
        fs::write(
            repo.path().join("ota.yaml"),
            r#"
version: 1
project:
  name: demo
tasks:
  dev:
    run: sh -c 'printf "stdout line\n"; printf "stderr line\n" >&2; touch started; sleep 0.2; exit 130'
"#,
        )
        .expect("write contract");

        let started_marker = repo.path().join("started");
        let interrupt_thread = std::thread::spawn(move || {
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
            while !started_marker.exists() && std::time::Instant::now() < deadline {
                std::thread::sleep(std::time::Duration::from_millis(10));
            }
            assert!(started_marker.exists(), "streamed task should start");
            simulate_run_interrupt_for_test();
        });

        let output = super::run_command(
            "dev",
            Some(repo.path()),
            None,
            OutputFormat::Text,
            ExecutionOverrides::default(),
            &[],
            &[],
            &[],
            false,
            false,
            false,
            true,
            true,
        );

        interrupt_thread
            .join()
            .expect("interrupt thread should finish");

        assert_eq!(output.exit_code, 130);
        let stderr = strip_ansi_codes(output.stderr.as_deref().unwrap_or_default());
        assert!(stderr.contains("INFO  Task interrupted"), "{stderr}");
        assert!(stderr.contains("Status:      interrupted"), "{stderr}");
        assert!(stderr.contains(".ota/state/logs/"), "{stderr}");

        let logs_root = repo.path().join(".ota").join("state").join("logs");
        let run_dirs = fs::read_dir(&logs_root)
            .expect("read logs root")
            .filter_map(|entry| entry.ok())
            .map(|entry| entry.path())
            .collect::<Vec<_>>();
        assert_eq!(run_dirs.len(), 1, "expected one run log directory");
        let run_dir = &run_dirs[0];
        assert_eq!(
            fs::read_to_string(run_dir.join("stdout.log")).expect("read stdout log"),
            "stdout line\n"
        );
        let stderr_log = fs::read_to_string(run_dir.join("stderr.log")).expect("read stderr log");
        assert_eq!(
            stderr_log.lines().next(),
            Some("stderr line"),
            "{stderr_log}"
        );
    }

    #[cfg(unix)]
    #[test]
    fn streamed_run_command_reports_interrupt_when_child_exits_one() {
        let _guard = crate::test_support::env_mutex_lock();
        let _interrupt_guard = isolate_run_interrupt_for_test();
        let repo = tempfile::tempdir().expect("repo tempdir");
        fs::write(
            repo.path().join("ota.yaml"),
            r#"
version: 1
project:
  name: demo
tasks:
  dev:
    run: sh -c 'touch started; sleep 0.2; exit 1'
"#,
        )
        .expect("write contract");

        let started_marker = repo.path().join("started");
        let interrupt_thread = std::thread::spawn(move || {
            let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
            while !started_marker.exists() && std::time::Instant::now() < deadline {
                std::thread::sleep(std::time::Duration::from_millis(10));
            }
            assert!(started_marker.exists(), "streamed task should start");
            simulate_run_interrupt_for_test();
        });
        let output = super::run_command(
            "dev",
            Some(repo.path()),
            None,
            OutputFormat::Text,
            ExecutionOverrides::default(),
            &[],
            &[],
            &[],
            false,
            false,
            false,
            true,
            true,
        );
        interrupt_thread.join().expect("interrupt thread");

        assert_eq!(output.exit_code, 130);
        let stderr = strip_ansi_codes(output.stderr.as_deref().unwrap_or_default());
        assert!(stderr.contains("INFO  Task interrupted"), "{stderr}");
        assert!(stderr.contains("Status:      interrupted"), "{stderr}");
        assert!(!stderr.contains("Task Failed"), "{stderr}");
    }

