    #[cfg(unix)]
    #[test]
    fn run_command_blocks_container_preconditions_before_task_processes() {
        let _guard = crate::test_support::env_mutex_lock();
        let repo = tempfile::tempdir().expect("repo tempdir");
        let bin_dir = repo.path().join("bin");
        fs::create_dir_all(&bin_dir).expect("create fake bin");
        write_executable_script(
            &fake_command_path(&bin_dir, "docker"),
            "#!/bin/sh\nif [ \"$1\" = \"info\" ]; then exit 0; fi\nif [ \"$1\" = \"run\" ]; then\n  case \"$*\" in\n    *\"command -v 'docker'\"*) exit 127 ;;\n  esac\nfi\necho unexpected docker invocation: \"$*\" >&2\nexit 1\n",
        );
        let proof_file = repo.path().join("should-not-exist");
        fs::write(
            repo.path().join("ota.yaml"),
            format!(
                r#"
version: 1
project:
  name: demo
execution:
  default_context: app
  contexts:
    app:
      backend: container
      lifecycle: ephemeral
      container:
        image: node:24-bookworm
        engines:
          - docker
tasks:
  ci:
    context: app
    run: sh -c 'touch "{}"'
    requirements:
      tools:
        docker: "*"
"#,
                proof_file.display()
            ),
        )
        .expect("write contract");

        let original_path = env::var_os("PATH");
        unsafe {
            env::set_var(
                "PATH",
                env::join_paths([bin_dir.as_path(), Path::new("/usr/bin"), Path::new("/bin")])
                    .unwrap(),
            );
        }

        let output = super::run_command(
            "ci",
            Some(repo.path()),
            None,
            OutputFormat::Text,
            ExecutionOverrides {
                backend: Some(Backend::Container),
                ..ExecutionOverrides::default()
            },
            &[],
            &[],
            &[],
            false,
            false,
            false,
            false,
            false,
        );

        match original_path.as_ref() {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }

        assert_ne!(output.exit_code, 0);
        assert!(
            !proof_file.exists(),
            "blocked preconditions must stop the task process"
        );
        let stderr = strip_ansi_codes(output.stderr.as_deref().unwrap_or_default());
        assert!(
            stderr.contains("Docker is missing from the configured container image")
                || stderr.contains("Tool probe failed: docker"),
            "{stderr}"
        );
        assert!(!stderr.contains("Task Failed"), "{stderr}");
    }

    #[cfg(not(windows))]
    #[test]
    fn run_command_blocks_version_mismatch_before_dependency_processes() {
        let _guard = crate::test_support::env_mutex_lock();
        let repo = tempfile::tempdir().expect("repo tempdir");
        let proof_file = repo.path().join("should-not-exist");
        fs::write(
            repo.path().join("ota.yaml"),
            format!(
                r#"
version: 1
project:
  name: demo
runtimes:
  node: "999.0.0"
tasks:
  setup:
    run: sh -c 'touch "{}"'
  verify:
    aggregate:
      tasks:
        - setup
"#,
                proof_file.display()
            ),
        )
        .expect("write contract");

        let output = super::run_command(
            "verify",
            Some(repo.path()),
            None,
            OutputFormat::Text,
            ExecutionOverrides::default(),
            &[],
            &[],
            &[],
            false,
            false,
            false,
            false,
            false,
        );

        assert_ne!(output.exit_code, 0);
        assert!(
            !proof_file.exists(),
            "blocked version preconditions must stop dependency task processes"
        );
        let stderr = strip_ansi_codes(output.stderr.as_deref().unwrap_or_default());
        assert!(
            stderr.contains("task `verify` is blocked (runtime mismatch: node)")
                || stderr.contains("Missing runtime: node"),
            "{stderr}"
        );
        assert!(
            stderr.contains("Field: tasks.verify.requirements"),
            "{stderr}"
        );
        let missing_runtime = stderr.contains("Missing runtime: node");
        if missing_runtime {
            assert!(
                stderr.contains("install node and make it available on PATH"),
                "{stderr}"
            );
        } else {
            assert!(stderr.contains("task requires `node@999.0.0`"), "{stderr}");
            assert!(stderr.contains("resolved runtime is `node@"), "{stderr}");
        }
        assert!(
            stderr.contains("run `ota doctor` to confirm readiness")
                || stderr.contains("run `ota doctor`")
                || stderr.contains("rerun `ota doctor`"),
            "{stderr}"
        );
        assert!(!stderr.contains("and rerun `ota doctor`"), "{stderr}");
        if !missing_runtime {
            assert!(stderr.contains("run `ota run verify`"), "{stderr}");
        }
        assert!(!stderr.contains("Task Failed"), "{stderr}");
    }

    #[test]
    fn run_version_mismatch_formatter_uses_unified_container_tool_layout() {
        let rendered = strip_ansi_codes(
            &super::render_run_version_mismatch_precondition_text(
                "./ota.yaml",
                "test:backend",
                None,
                Backend::Container,
                "Version mismatch for tool: poetry",
                "poetry resolved to `2.4.1` inside the configured container image but the contract requires `>=2.3.4,<2.4.0`",
                "update `execution.backends.container.image` so `poetry` satisfies `>=2.3.4,<2.4.0`, then rerun `ota doctor --mode container --lifecycle ephemeral`",
            )
            .expect("formatted mismatch"),
        );

        assert!(
            rendered.contains("task `test:backend` is blocked (container tool mismatch: poetry)"),
            "{rendered}"
        );
        assert!(
            rendered.contains("Field: tasks.test:backend.requirements"),
            "{rendered}"
        );
        assert!(
            rendered.contains("task requires `poetry@>=2.3.4,<2.4.0`"),
            "{rendered}"
        );
        assert!(
            rendered.contains("resolved tool is `poetry@2.4.1` in the configured container image"),
            "{rendered}"
        );
        assert!(
            rendered.contains("run `ota doctor --mode container --lifecycle ephemeral`"),
            "{rendered}"
        );
        assert!(
            rendered.contains("run `ota run test:backend --mode container`"),
            "{rendered}"
        );
    }

    #[test]
    fn run_version_mismatch_formatter_splits_and_rerun_steps() {
        let rendered = strip_ansi_codes(
            &super::render_run_version_mismatch_precondition_text(
                "./ota.yaml",
                "verify",
                None,
                Backend::Native,
                "Version mismatch for runtime: node",
                "node resolved to `26.0.0` but the contract requires `22`; ota probed `/Users/bobai/.local/bin/mise` with `node --version`",
                "run `mise install node@22` and rerun `ota doctor`",
            )
            .expect("formatted mismatch"),
        );

        assert!(
            rendered.contains("run `mise install node@22`"),
            "{rendered}"
        );
        assert!(rendered.contains("run `ota doctor`"), "{rendered}");
        assert!(!rendered.contains("and rerun `ota doctor`"), "{rendered}");
    }

