    #[test]
    fn dry_run_toolchain_targets_preserve_each_container_steps_declared_os() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: demo
execution:
  contexts:
    linux:
      backend: container
      container:
        image: node:24-bookworm
        platform: linux/amd64
    windows:
      backend: container
      container:
        image: nanoserver
        platform: windows/amd64
toolchains:
  node:
    provider: corepack
    version: "24"
    platforms:
      windows:
        version: "22"
tasks:
  prepare:
    context: windows
    run: node --version
    requirements:
      toolchains:
        - node
  verify:
    context: linux
    run: node --version
    requirements:
      toolchains:
        - node
"#,
        )
        .expect("contract should parse");
        let steps = vec![
            crate::runner::RunPlanStep {
                task: String::from("prepare"),
                parent: Some(String::from("verify")),
                backend: Backend::Container,
                context: Some(String::from("windows")),
                backend_selection_source: String::from("task"),
            },
            crate::runner::RunPlanStep {
                task: String::from("verify"),
                parent: None,
                backend: Backend::Container,
                context: Some(String::from("linux")),
                backend_selection_source: String::from("task"),
            },
        ];

        let targets = super::toolchain_targets_for_run_plan_steps(
            &contract,
            &steps,
            ExecutionOverrides::default(),
        );

        assert!(targets.contains(&(String::from("node"), String::from("windows"))));
        assert!(targets.contains(&(String::from("node"), String::from("linux"))));
    }

    #[test]
    fn run_dry_run_json_expands_aggregate_child_plan() {
        let _guard = crate::test_support::env_mutex_lock();
        let repo = tempfile::tempdir().expect("repo tempdir");
        fs::write(
            repo.path().join("ota.yaml"),
            r#"
version: 1
project:
  name: demo
tasks:
  lint:backend:
    run: echo backend
  lint:frontend:
    run: echo frontend
  lint:
    aggregate:
      tasks:
        - lint:backend
        - lint:frontend
"#,
        )
        .expect("write contract");

        let output = super::run_command(
            "lint",
            Some(repo.path()),
            None,
            OutputFormat::Json,
            ExecutionOverrides::default(),
            &[],
            &[],
            &[],
            true,
            false,
            false,
            false,
            false,
        );

        let json: serde_json::Value =
            serde_json::from_str(&output.stdout).expect("dry-run json preview");
        let chain = json["plan"]["dependency_chain"]
            .as_array()
            .expect("dependency chain array")
            .iter()
            .filter_map(|value| value.as_str())
            .collect::<Vec<_>>();
        assert_eq!(chain, vec!["lint:backend", "lint:frontend", "lint"]);
        let actions = json["plan"]["actions"]
            .as_array()
            .expect("actions array")
            .iter()
            .filter_map(|value| value.as_str())
            .collect::<Vec<_>>();
        assert!(
            actions.contains(&"would run planned step `lint:backend` before `lint`"),
            "{actions:?}"
        );
        assert!(
            actions.contains(&"would run planned step `lint:frontend` before `lint`"),
            "{actions:?}"
        );
        assert!(
            actions.contains(&"would complete aggregate task `lint` on the host"),
            "{actions:?}"
        );
        let dependency_steps = json["plan"]["dependency_steps"]
            .as_array()
            .expect("dependency steps array");
        assert_eq!(dependency_steps.len(), 3);
        assert_eq!(dependency_steps[0]["task"], "lint:backend");
        assert_eq!(dependency_steps[0]["backend"], "native");
        assert_eq!(dependency_steps[0]["backend_selection_source"], "default");
        assert_eq!(dependency_steps[2]["task"], "lint");
    }

    #[test]
    fn run_dry_run_json_includes_dependency_activation_truth_for_aggregate_task() {
        let _guard = crate::test_support::env_mutex_lock();
        let repo = tempfile::tempdir().expect("repo tempdir");
        fs::write(
            repo.path().join("ota.yaml"),
            r#"
version: 1
project:
  name: demo
toolchains:
  node:
    version: "*"
    package_managers:
      pnpm: "*"
tools:
  devbox:
    version: "*"
    acquisition:
      provider: command
      shell: bash
      run: curl -fsSL https://get.jetify.com/devbox | bash -s -- -f
orchestrators:
  devbox:
    kind: devbox
    required: true
    config_files:
      - devbox.json
    prepare:
      install: true
tasks:
  setup:
    prepare:
      kind: dependency_hydration
      medium: package_dependencies
      source:
        kind: node_package_manager
        cwd: .
        manager: pnpm
        mode: install
    execution:
      orchestrator:
        ref: devbox
        mode: exec
    requirements:
      toolchains:
        - node
    effects:
      writes:
        - node_modules
      network: true
      network_kind: dependency_hydration
    internal: true
  test:
    command:
      exe: pnpm
      args:
        - run
        - test
    execution:
      orchestrator:
        ref: devbox
        mode: exec
    depends_on:
      - setup
  verify:
    aggregate:
      tasks:
        - test
"#,
        )
        .expect("write contract");

        let output = super::run_command(
            "verify",
            Some(repo.path()),
            None,
            OutputFormat::Json,
            ExecutionOverrides::default(),
            &[],
            &[],
            &[],
            true,
            false,
            false,
            false,
            false,
        );

        let json: serde_json::Value =
            serde_json::from_str(&output.stdout).expect("dry-run json preview");
        let actions = json["plan"]["actions"]
            .as_array()
            .expect("actions array")
            .iter()
            .filter_map(|value| value.as_str())
            .collect::<Vec<_>>();
        assert!(
            actions.contains(&"activate tool `devbox` via `bash` command"),
            "{actions:?}"
        );
        let requirements = json["plan"]["requirement_lines"]
            .as_array()
            .expect("requirement lines array")
            .iter()
            .filter_map(|value| value.as_str())
            .collect::<Vec<_>>();
        assert!(
            requirements
                .iter()
                .any(|line| line.contains("tool `devbox` version `*`, acquisition `command`")),
            "{requirements:?}"
        );
        assert_ne!(json["preview_status"], "RUNNABLE");
    }

