    #[test]
    fn up_preview_surfaces_prerequisite_workflow_instances_before_selected_instance() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: preview-up-instance-topology
tasks:
  dev:
    run: echo dev
workflows:
  default: app
  app:
    run:
      task: dev
    instances:
      default: ws0
      ws0: {}
      ws1:
        topology:
          requires_instances:
            - ws0
"#,
        )
        .unwrap();
        let preflight = DoctorReport {
            ok: true,
            provisioning: None,
            adapter_bootstrap: None,
            execution_target: None,
            findings: Vec::new(),
        };

        let preview = build_up_preview(
            &contract,
            Path::new("/tmp/ota.yaml"),
            ExecutionOverrides::default(),
            Some("app@ws1"),
            super::UpRunBehaviorPreference::Auto,
            &preflight,
        );

        assert_eq!(
            preview.plan.actions,
            vec![
                String::from(
                    "activate prerequisite workflow instance `app@ws0` before the selected instance"
                ),
                String::from("re-check repo readiness"),
            ]
        );
    }

    #[test]
    fn contract_adjusted_for_selected_workflow_env_profile_merges_profile_into_selected_tasks() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: env-profile
env:
  profiles:
    docker-build:
      sources:
        - kind: dotenv
          path: .env.docker-build
      env_files:
        - .env.docker-build
      env:
        REDIS_HOST: redis
        NEXTAUTH_URL: http://web:3000
tasks:
  build:
    env_files:
      - .env.local
    env:
      NEXTAUTH_URL: http://localhost:3000
    run: pnpm build
workflows:
  default: docker-build
  docker-build:
    env:
      profile: docker-build
    run:
      task: build
"#,
        )
        .unwrap();

        let adjusted = super::contract_adjusted_for_selected_workflow_env_profile(
            &contract,
            Some("docker-build"),
        )
        .expect("workflow env profile should adjust contract");
        assert_eq!(
            adjusted
                .env
                .sources
                .first()
                .map(|source| source.path.as_str()),
            Some(".env.docker-build")
        );
        let task = adjusted.tasks.get("build").expect("task should exist");
        assert_eq!(
            task.env_files,
            vec![
                String::from(".env.docker-build"),
                String::from(".env.local")
            ]
        );
        assert_eq!(
            task.env.get("REDIS_HOST").map(String::as_str),
            Some("redis")
        );
        assert_eq!(
            task.env.get("NEXTAUTH_URL").map(String::as_str),
            Some("http://localhost:3000")
        );
    }

