    #[cfg(unix)]
    #[test]
    fn execution_plan_mode_container_uses_named_context_shape() {
        use std::os::unix::fs::PermissionsExt;

        let _guard = env_mutex_lock();
        let fixture = TempDir::new().unwrap();
        let bin_dir = fixture.path().join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let docker_path = bin_dir.join("docker");
        write_executable_script(&docker_path, "#!/bin/sh\nexit 0\n");
        let mut permissions = fs::metadata(&docker_path).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&docker_path, permissions).unwrap();

        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(env::split_paths(existing));
        }
        let joined_path = env::join_paths(path_entries).unwrap();
        unsafe {
            env::set_var("PATH", &joined_path);
        }

        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: execution-plan
execution:
  default_context: host
  contexts:
    host:
      backend: native
    app-base:
      backend: container
      lifecycle: ephemeral
      container:
        image: ghcr.io/ota/dev:latest
        engines:
          - docker
    app:
      extends: app-base
tasks:
  dev:
    context: app
    run: echo dev
"#,
        )
        .unwrap();

        let resolved = super::resolve_execution_plan(
            &contract,
            Path::new("/tmp/ota.yaml"),
            ExecutionOverrides {
                backend: Some(Backend::Container),
                ..ExecutionOverrides::default()
            },
            None,
        )
        .expect("generic container plan should resolve from the named context");

        match original_path {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }

        assert_eq!(resolved.backend, "container");
        assert_eq!(resolved.backend_source, "override");
        assert_eq!(resolved.lifecycle.as_deref(), Some("ephemeral"));
        assert_eq!(
            resolved.lifecycle_source.as_deref(),
            Some("context lifecycle")
        );
        assert_eq!(resolved.image.as_deref(), Some("ghcr.io/ota/dev:latest"));
    }

    #[test]
    fn execution_plan_uses_policy_resolved_backend_environment_image() {
        let _guard = env_mutex_lock();
        let fixture = TempDir::new().unwrap();
        let contract_path = fixture.path().join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: execution-plan
execution:
  default_context: app
  contexts:
    app:
      backend: container
      lifecycle: persistent
      container:
        image: ghcr.io/ota/raw:latest
        engines:
          - docker
  shared_backends:
    workbench:
      scope: local
      backend: container
      lifecycle: persistent
      context: app
      environment:
        profile: java-node-workbench
tasks:
  dev:
    run: echo dev
    runtime:
      kind: service
      backend_binding: workbench
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 8080
"#,
        )
        .unwrap();
        fs::create_dir_all(fixture.path().join(".ota")).unwrap();
        fs::write(
            fixture.path().join(".ota").join("org-policy.yaml"),
            r#"
policies:
  backend_environment:
    profiles:
      java-node-workbench:
        image: ghcr.io/ota/workbench:2026.04
        source: curated
"#,
        )
        .unwrap();

        let contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .unwrap();

        let original_path = env::var_os("PATH");
        unsafe {
            env::set_var("PATH", "");
        }

        let resolved = super::resolve_execution_plan(
            &contract,
            &contract_path,
            ExecutionOverrides::default(),
            None,
        )
        .expect("execution plan should resolve policy-backed backend environment");

        match original_path {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }

        assert_eq!(
            resolved.image.as_deref(),
            Some("ghcr.io/ota/workbench:2026.04")
        );
    }

