    fn write_cross_member_target_root_contract(root: &Path) -> crate::workspace::WorkspaceRepoRef {
        fs::write(
            root.join("ota.yaml"),
            r#"
version: 1
project:
  name: ota-monorepo
workspace:
  type: monorepo
  members:
    - api
execution:
  default_context: host
  contexts:
    host:
      backend: native
tasks:
  sandbox:
    run: echo sandbox
    targets:
      api:
        service:
          member: api
          task: dev
          listener: http
          address_view: host
"#
            .trim_start(),
        )
        .unwrap();
        fs::create_dir_all(root.join("api")).unwrap();
        fs::write(
            root.join("api").join("ota.yaml"),
            r#"
tasks:
  dev:
    run: echo api
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 127.0.0.1
            port:
              mode: fixed
              value: 8080
          project:
            host:
              address: 127.0.0.1
              port:
                mode: fixed
                value: 8080
"#
            .trim_start(),
        )
        .unwrap();

        crate::workspace::WorkspaceRepoRef {
            name: String::from("monorepo"),
            path: root.to_path_buf(),
            contract_path: root.join("ota.yaml"),
            workflow: None,
            task_bindings: BTreeMap::new(),
            required: true,
            depends_on: Vec::new(),
            present: true,
            source_url: None,
            source_ref: None,
            policy_env: BTreeMap::new(),
        }
    }

