    #[test]
    fn doctor_json_exports_group_summaries() {
        let findings = [
            Finding {
                identity: None,
                severity: FindingSeverity::Error,
                summary: String::from("Version mismatch for runtime: java"),
                why: String::from("java resolved to `25.0.2` but the contract requires `21`"),
                next: String::from(
                    "install a compatible java version that satisfies `21`, then rerun `ota doctor`",
                ),
            },
            Finding {
                identity: None,
                severity: FindingSeverity::Error,
                summary: String::from("Version mismatch for tool: curl"),
                why: String::from("curl resolved to `8.13.0` but the contract requires `8.7.1`"),
                next: String::from(
                    "install a compatible curl version that satisfies `8.7.1`, then rerun `ota doctor`",
                ),
            },
        ];

        let groups = super::doctor_finding_group_summaries(findings.iter(), None, None);
        assert_eq!(groups.len(), 1);
        assert_eq!(groups[0].action_key, "tooling-version");
        assert_eq!(groups[0].action_title, "Fix version mismatches");
        assert_eq!(
            groups[0].action_next,
            "install compatible runtimes and tools, then rerun `ota doctor`"
        );
        assert_eq!(groups[0].count, 2);
    }

    #[test]
    fn doctor_json_includes_selected_toolchains() {
        let _guard = env_mutex_lock();
        let fixture = TempDir::new().expect("temp dir");
        let contract_path = fixture.path().join("ota.yaml");
        let bin_dir = fixture.path().join("bin");
        fs::create_dir_all(&bin_dir).expect("create fake bin dir");
        if cfg!(windows) {
            write_executable_script(
                &fake_command_path(&bin_dir, "rustc"),
                "@echo off\r\necho rustc 1.94.0\r\nexit /b 0\r\n",
            );
            write_executable_script(
                &fake_command_path(&bin_dir, "rustup"),
                "@echo off\r\nif \"%1\"==\"component\" if \"%2\"==\"list\" if \"%3\"==\"--installed\" (\r\n  echo rustfmt-x86_64-pc-windows-msvc\r\n  exit /b 0\r\n)\r\nif \"%1\"==\"toolchain\" if \"%2\"==\"install\" exit /b 0\r\nexit /b 0\r\n",
            );
        } else {
            write_executable_script(
                &fake_command_path(&bin_dir, "rustc"),
                "#!/bin/sh\necho rustc 1.94.0\nexit 0\n",
            );
            write_executable_script(
                &fake_command_path(&bin_dir, "rustup"),
                "#!/bin/sh\nif [ \"$1\" = \"component\" ] && [ \"$2\" = \"list\" ] && [ \"$3\" = \"--installed\" ]; then\n  echo rustfmt-x86_64-unknown-linux-gnu\n  exit 0\nfi\nif [ \"$1\" = \"toolchain\" ] && [ \"$2\" = \"install\" ]; then\n  exit 0\nfi\nexit 0\n",
            );
        }
        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(env::split_paths(existing));
        } else if cfg!(unix) {
            path_entries.push(PathBuf::from("/usr/bin"));
            path_entries.push(PathBuf::from("/bin"));
        }
        unsafe {
            env::set_var("PATH", env::join_paths(path_entries).expect("join PATH"));
        }
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: ota
toolchains:
  rust:
    provider: rustup
    version: "1.94.0"
    components:
      - rustfmt
tasks:
  setup:
    run: cargo fetch
    requirements:
      toolchains:
        - rust
workflows:
  default: app
  app:
    setup:
      task: setup
"#,
        )
        .expect("write contract");

        let output = super::doctor(
            Some(fixture.path()),
            None,
            &[],
            Some("app"),
            false,
            false,
            ExecutionOverrides::default(),
            OutputFormat::Json,
            false,
        );
        match original_path.as_ref() {
            Some(path) => unsafe { env::set_var("PATH", path) },
            None => unsafe { env::remove_var("PATH") },
        }

        let json: serde_json::Value =
            serde_json::from_str(&output.stdout).expect("doctor json should parse");
        let toolchains = json["toolchains"]
            .as_array()
            .expect("toolchains array should be present");
        assert_eq!(toolchains.len(), 1, "{json}");
        let toolchain = &toolchains[0];
        assert_eq!(toolchain["name"], "rust");
        assert_eq!(toolchain["provider"], "rustup");
        assert_eq!(toolchain["backend"], "native");
        assert_eq!(
            toolchain["target_os"],
            super::current_requirement_platform()
        );
        assert_eq!(toolchain["fulfillment"], "none");
        assert_eq!(toolchain["owns_runtime"], "rust");
        assert!(
            toolchain["owns_tools"]
                .as_array()
                .is_some_and(|tools| tools.iter().any(|tool| tool == "cargo"))
        );
        assert!(
            toolchain["owns_tools"]
                .as_array()
                .is_some_and(|tools| tools.iter().any(|tool| tool == "rustfmt"))
        );
    }

