    #[test]
    fn receipt_next_renders_after_summary_block() {
        let receipt = ExecutionReceipt {
            ok: true,
            path: String::from("./ota.yaml"),
            scope: String::from("repo"),
            contract: String::from("./ota.yaml"),
            contract_identity: None,
            contract_snapshot_hash: None,
            contract_snapshot_ref: None,
            assumption_set_hash: None,
            evaluated_inputs: Vec::new(),
            witnessed_observations: crate::output::ExecutionReceiptWitnessedObservations::default(),
            crossing: None,
            refusal: None,
            typed_effect_policy_refusal: None,
            replay_input_policy: None,
            workspace: None,
            backend: Some(String::from("native")),
            context: None,
            lifecycle: None,
            image: None,
            container_memory_bytes: None,
            target: None,
            provider: None,
            cwd: None,
            acquired: Vec::new(),
            env: BTreeMap::new(),
            env_sources: Vec::new(),
            workflow_env_artifacts: Vec::new(),
            native_prerequisites: Vec::new(),
            toolchains: Vec::new(),
            runtime: None,
            logs: None,
            service_termination: None,
            host_service_cleanup: Vec::new(),
            backend_fulfillment: None,
            workloads: BTreeMap::new(),
            policy: Vec::new(),
            dependency_steps: Vec::new(),
            steps: vec![execution_receipt_step(1, "dev", "OK", None, Some(0))],
            blocked: Vec::new(),
            status: None,
            failed_task: None,
            failed_dependency: None,
            failure_origin: None,
            summary: ExecutionReceiptSummary::default(),
            next: Some(String::from(
                "run `ota tasks --use` to inspect runnable task usage",
            )),
        };

        let mut rendered =
            render_execution_receipt_summary_block(&receipt, Some("dev"), "RUN SUMMARY");
        super::append_receipt_next_block(&mut rendered, &receipt);
        let rendered = strip_ansi_codes(&rendered);

        assert!(rendered.contains("RUN SUMMARY"), "{rendered}");
        let summary = rendered.find("RUN SUMMARY").expect("summary");
        let status = rendered.find("\nStatus:").expect("status");
        let note = rendered.find("\nNote:").expect("note");
        let next = rendered.rfind("\nNext:").expect("next");
        assert!(status > summary, "{rendered}");
        assert!(note > status, "{rendered}");
        assert!(next > note, "{rendered}");
        assert!(
            rendered.contains("Note:        running on the host environment"),
            "{rendered}"
        );
        assert!(
            rendered.contains("Next: run `ota tasks --use` to inspect runnable task usage"),
            "{rendered}"
        );
        assert!(
            rendered.contains("Note:        running on the host environment\n\nNext:"),
            "{rendered}"
        );
        assert!(
            !rendered.contains("Note:        running on the host environment\n\n\nNext:"),
            "{rendered}"
        );
    }

