    #[test]
    fn resolve_up_run_behavior_uses_selected_mode_runtime_shape() {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: up-behavior
tasks:
  dev:
    run: echo native
    execution:
      modes:
        native:
          run: echo native
        container:
          run: echo container
          runtime:
            kind: service
            listeners:
              http:
                protocol: http
                bind:
                  address: 0.0.0.0
                  port:
                    mode: fixed
                    value: 3000
workflows:
  default: app
  app:
    run:
      task: dev
"#,
        )
        .unwrap();

        let native_behavior = super::resolve_up_run_behavior(
            &contract,
            None,
            ExecutionOverrides {
                backend: Some(Backend::Native),
                ..ExecutionOverrides::default()
            },
            super::UpRunBehaviorPreference::Auto,
        );
        let container_behavior = super::resolve_up_run_behavior(
            &contract,
            None,
            ExecutionOverrides {
                backend: Some(Backend::Container),
                ..ExecutionOverrides::default()
            },
            super::UpRunBehaviorPreference::Auto,
        );

        assert_eq!(native_behavior, super::UpRunBehavior::Attach);
        assert_eq!(
            container_behavior,
            super::UpRunBehavior::DetachedProofTeardown
        );
    }

