    #[test]
    fn resolve_up_run_behavior_attach_preference_keeps_service_running_when_workflow_declares_attach_task()
     {
        let contract = parse_contract_str(
            Path::new("ota.yaml"),
            r#"
version: 1
project:
  name: up-behavior
tasks:
  dev:
    run: echo dev
    runtime:
      kind: service
      listeners:
        http:
          protocol: http
          bind:
            address: 0.0.0.0
            port:
              mode: fixed
              value: 3000
  attach:
    requirements:
      tools:
        docker: "*"
    compose:
      kind: attach
      service: app
      exe: tmux
      args:
        - attach
        - -t
        - app
workflows:
  default: app
  app:
    run:
      task: dev
    attach:
      task: attach
"#,
        )
        .unwrap();

        let behavior = super::resolve_up_run_behavior(
            &contract,
            None,
            ExecutionOverrides::default(),
            super::UpRunBehaviorPreference::Attach,
        );
        assert_eq!(behavior, super::UpRunBehavior::DetachedLeaveRunning);
        let overrides = ExecutionOverrides {
            backend: Some(Backend::Native),
            host_port: Some(4000),
            ..ExecutionOverrides::default()
        };
        assert_eq!(
            super::selected_up_host_port_task_name(&contract, None, overrides),
            Some("dev")
        );
        assert_eq!(
            super::up_execution_overrides_for_task(&contract, None, "dev", overrides).host_port,
            Some(4000)
        );
        assert_eq!(
            super::up_execution_overrides_for_task(&contract, None, "attach", overrides).host_port,
            None
        );
    }

