    #[test]
    fn preview_receipt_tracks_selected_workflow_toolchains() {
        let contract = parse_contract_str(
            Path::new("./ota.yaml"),
            r#"
version: 1
project:
  name: target-test
execution:
  default_context: app
  contexts:
    app:
      backend: container
      lifecycle: ephemeral
      container:
        image: ghcr.io/ota/dev:latest
toolchains:
  rust:
    provider: rustup
    version: "1.94.0"
    components:
      - rustfmt
tasks:
  setup:
    context: app
    run: cargo fetch
    requirements:
      toolchains:
        - rust
workflows:
  default: app
  app:
    setup:
      task: setup
"#,
        )
        .unwrap();

        let receipt = super::preview_receipt(
            &contract,
            Path::new("./ota.yaml"),
            ExecutionOverrides::default(),
            Some("app"),
            "READY",
            &[],
        );

        assert_eq!(receipt.toolchains.len(), 1);
        let toolchain = &receipt.toolchains[0];
        assert_eq!(toolchain.name, "rust");
        assert_eq!(toolchain.provider, "rustup");
        assert_eq!(toolchain.backend, "container");
        assert_eq!(toolchain.target_os, "linux");
        assert_eq!(toolchain.fulfillment, "none");
        assert_eq!(toolchain.owns_runtime, "rust");
        assert!(toolchain.owns_tools.iter().any(|tool| tool == "cargo"));
        assert!(toolchain.owns_tools.iter().any(|tool| tool == "rustfmt"));
    }

    #[test]
    fn preview_receipt_policy_lines_follow_selected_workflow_toolchains() {
        let fixture = TempDir::new().unwrap();
        let contract_path = fixture.path().join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: target-test
toolchains:
  rust:
    provider: rustup
    version: "1.94.0"
  node:
    provider: corepack
    version: "22"
tasks:
  setup:
    run: cargo fetch
    requirements:
      toolchains:
        - rust
  test:
    run: node --version
    requirements:
      toolchains:
        - node
workflows:
  default: app
  app:
    setup:
      task: setup
    run:
      task: test
"#,
        )
        .unwrap();
        fs::create_dir_all(fixture.path().join(".ota")).unwrap();
        fs::write(
            fixture.path().join(".ota").join("org-policy.yaml"),
            r#"
policies:
  provisioning:
    rust:
      source: mise
      approved_versions:
        - "1.94.0"
    node:
      source: mise
      approved_versions:
        - "22"
"#,
        )
        .unwrap();

        let contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .unwrap();
        let loaded_policy = super::load_org_policy_pack_auto_details(&contract_path)
            .expect("load policy pack")
            .expect("policy pack exists");
        let receipt = super::preview_receipt_with_policy_snapshot(
            &contract,
            &contract_path,
            ExecutionOverrides::default(),
            Some("app"),
            "READY",
            &[],
            Some(DoctorPolicySnapshot {
                loaded: Some(&loaded_policy),
                load_error: None,
            }),
        );

        assert_eq!(receipt.toolchains.len(), 2, "{:?}", receipt.toolchains);
        assert_eq!(receipt.policy.len(), 2, "{:?}", receipt.policy);
        assert!(
            receipt
                .policy
                .iter()
                .any(|line| line.contains("runtime rust 1.94.0 via mise")),
            "{:?}",
            receipt.policy
        );
        assert!(
            receipt
                .policy
                .iter()
                .any(|line| line.contains("runtime node 22 via mise")),
            "{:?}",
            receipt.policy
        );
    }

