    #[test]
    fn up_runs_workflow_prepare_before_setup() {
        let _guard = env_mutex_lock();
        let repo = TempDir::new().unwrap();
        let contract_path = repo.path().join("ota.yaml");

        let contract = parse_contract_str(
            contract_path.as_path(),
            r#"
version: 1
project:
  name: prepare-up
tasks:
  setup:env:local:
    execution:
      default_mode: native
    action:
      kind: copy_if_missing
      from: .env.example
      to: .env.local
  setup:
    run: test -f .env.local && echo setup >> run.log
    depends_on:
      - setup:env:local
  dev:
    run: echo dev
workflows:
  default: app
  app:
    prepare:
      task: setup:env:local
    setup:
      task: setup
    run:
      task: dev
"#,
        )
        .unwrap();
        fs::write(repo.path().join(".env.example"), "TOKEN=test\n").unwrap();

        let result = execute_repo_up(
            &contract,
            contract_path.as_path(),
            ExecutionOverrides::default(),
            Some("app"),
            None,
            false,
            RepoExecutionMode::Capture,
        )
        .unwrap();

        assert!(
            result.ok,
            "status={} phase={} findings={:?} stdout=\n{}\nstderr=\n{}",
            result.status,
            result.phase,
            result
                .report
                .findings
                .iter()
                .map(|finding| finding.summary.as_str())
                .collect::<Vec<_>>(),
            result.stdout,
            result.stderr
        );
        assert_eq!(result.status, "READY");
        assert!(repo.path().join(".env.local").exists());
        assert_eq!(
            result
                .stdout
                .matches("copied `.env.example` to `.env.local`")
                .count(),
            1
        );
        assert_eq!(
            fs::read_to_string(repo.path().join("run.log"))
                .unwrap()
                .lines()
                .collect::<Vec<_>>(),
            vec!["setup"]
        );
    }

    #[test]
    fn up_required_interaction_blocks_before_workflow_setup() {
        let _guard = env_mutex_lock();
        let repo = TempDir::new().unwrap();
        let contract_path = repo.path().join("ota.yaml");
        let contract = parse_contract_str(
            contract_path.as_path(),
            r#"
version: 1
project:
  name: required-interaction-up
tasks:
  setup:
    run: echo setup > setup-ran
  login:
    command:
      exe: sh
      args: [-c, "echo login"]
      interaction: required
workflows:
  default: app
  app:
    setup:
      task: setup
    run:
      task: login
"#,
        )
        .unwrap();

        let result = execute_repo_up(
            &contract,
            contract_path.as_path(),
            ExecutionOverrides::default(),
            Some("app"),
            None,
            false,
            RepoExecutionMode::Capture,
        )
        .unwrap();

        assert!(!result.ok);
        assert_eq!(result.status, "BLOCKED");
        assert_eq!(result.phase, "preconditions");
        assert_eq!(result.task.as_deref(), Some("login"));
        assert!(result.report.findings.iter().any(|finding| {
            finding
                .identity
                .as_ref()
                .is_some_and(|identity| identity.code == "OTA_INTERACTION_REQUIRED")
        }));
        assert!(!repo.path().join("setup-ran").exists());
    }

