    #[cfg(unix)]
    #[test]
    fn up_runs_workflow_owned_prepare_action_before_setup() {
        let _guard = env_mutex_lock();
        let repo = TempDir::new().unwrap();
        let contract_path = repo.path().join("ota.yaml");

        let bin_dir = repo.path().join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        let state_dir = repo.path().join("docker-state");
        fs::create_dir_all(&state_dir).unwrap();
        let docker_path = bin_dir.join("docker");
        fs::write(
            &docker_path,
            format!(
                r#"#!/bin/sh
state_dir="{state_dir}"
mkdir -p "$state_dir"

if [ "$1" = "network" ] && [ "$2" = "inspect" ]; then
  if [ -f "$state_dir/$3" ]; then
    exit 0
  fi
  exit 1
fi

if [ "$1" = "network" ] && [ "$2" = "create" ]; then
  : > "$state_dir/$3"
  exit 0
fi

exit 1
"#,
                state_dir = state_dir.display()
            ),
        )
        .unwrap();
        let mut permissions = fs::metadata(&docker_path).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&docker_path, permissions).unwrap();

        let original_path = env::var_os("PATH");
        let mut path_entries = vec![bin_dir.clone()];
        if let Some(existing) = original_path.as_ref() {
            path_entries.extend(env::split_paths(existing));
        }
        let joined_path = env::join_paths(path_entries).unwrap();
        unsafe {
            env::set_var("PATH", &joined_path);
        }

        let contract = parse_contract_str(
            contract_path.as_path(),
            r#"
version: 1
project:
  name: prepare-up-inline-action
tasks:
  setup:
    run: test -f .env.local && echo setup >> run.log
  dev:
    run: echo dev
workflows:
  default: app
  app:
    prepare:
      action:
        kind: ensure_bundle
        steps:
          - kind: ensure_container_network
            name: local-dev
          - kind: copy_if_missing
            from: .env.example
            to: .env.local
    setup:
      task: setup
    run:
      task: dev
"#,
        )
        .unwrap();
        fs::write(repo.path().join(".env.example"), "TOKEN=test\n").unwrap();

        let result = execute_repo_up(
            &contract,
            contract_path.as_path(),
            ExecutionOverrides::default(),
            Some("app"),
            None,
            false,
            RepoExecutionMode::Capture,
        )
        .unwrap();

        match original_path {
            Some(path) => unsafe {
                env::set_var("PATH", path);
            },
            None => unsafe {
                env::remove_var("PATH");
            },
        }

        assert!(
            result.ok,
            "status={} phase={} findings={:?} stdout=\n{}\nstderr=\n{}",
            result.status,
            result.phase,
            result
                .report
                .findings
                .iter()
                .map(|finding| finding.summary.as_str())
                .collect::<Vec<_>>(),
            result.stdout,
            result.stderr
        );
        assert_eq!(result.status, "READY");
        assert!(repo.path().join(".env.local").exists());
        assert!(repo.path().join("docker-state").join("local-dev").exists());
        assert!(
            result
                .stdout
                .contains("ensured docker container network `local-dev`")
        );
        assert_eq!(
            fs::read_to_string(repo.path().join("run.log"))
                .unwrap()
                .lines()
                .collect::<Vec<_>>(),
            vec!["setup"]
        );
    }

