    #[cfg(unix)]
    #[test]
    fn proof_lifecycle_rolls_back_multi_service_closure_in_reverse_order() {
        use std::os::unix::fs::PermissionsExt;

        let _guard = env_mutex_lock();
        let fixture = TempDir::new().unwrap();
        let contract_path = fixture.path().join("ota.yaml");
        let bin_dir = fixture.path().join("bin");
        let database_state = fixture.path().join("database-running");
        let cache_state = fixture.path().join("cache-running");
        let log_path = fixture.path().join("docker.log");
        fs::create_dir_all(&bin_dir).unwrap();
        let docker = bin_dir.join("docker");
        fs::write(
            &docker,
            format!(
                "#!/bin/sh\nprintf '%s\\n' \"$*\" >> '{}'\ncase \"$*\" in\n  *'ps --status running -q'*database*) [ -f '{}' ] && printf running ;;\n  *'ps --status running -q'*cache*) [ -f '{}' ] && printf running ;;\n  *'up -d database'*) touch '{}' ;;\n  *'up -d cache'*) touch '{}'; exit 7 ;;\n  *'stop cache'*) rm -f '{}' ;;\n  *'stop database'*) rm -f '{}' ;;\nesac\n",
                log_path.display(),
                database_state.display(),
                cache_state.display(),
                database_state.display(),
                cache_state.display(),
                cache_state.display(),
                database_state.display(),
            ),
        )
        .unwrap();
        let mut permissions = fs::metadata(&docker).unwrap().permissions();
        permissions.set_mode(0o755);
        fs::set_permissions(&docker, permissions).unwrap();
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: lifecycle-rollback
services:
  database:
    manager:
      kind: compose
      name: lifecycle-rollback
      file: compose.yaml
      service: database
    lifecycle:
      teardown_assertion: manager_inactive
  cache:
    depends_on: [database]
    manager:
      kind: compose
      name: lifecycle-rollback
      file: compose.yaml
      service: cache
    lifecycle:
      teardown_assertion: manager_inactive
tasks:
  build:
    run: echo build
workflows:
  default: smoke
  smoke:
    run:
      task: build
    proof:
      lifecycle:
        services: [cache]
"#,
        )
        .unwrap();

        let original_path = env::var_os("PATH");
        unsafe {
            env::set_var(
                "PATH",
                env::join_paths([bin_dir.as_path(), Path::new("/usr/bin"), Path::new("/bin")])
                    .unwrap(),
            )
        };
        let output = super::proof_lifecycle(
            Some(fixture.path()),
            None,
            None,
            Some("smoke"),
            None,
            false,
            crate::runner::ExecutionOverrides::default(),
            false,
            OutputFormat::Json,
            false,
        );
        match original_path.as_ref() {
            Some(path) => unsafe { env::set_var("PATH", path) },
            None => unsafe { env::remove_var("PATH") },
        }

        assert_eq!(output.exit_code, 1, "{}", output.stdout);
        let json: serde_json::Value = serde_json::from_str(&output.stdout).unwrap();
        assert_eq!(json["services"][0]["service"], "database");
        assert_eq!(json["services"][1]["service"], "cache");
        assert_eq!(json["services"][1]["start"]["state"], "command_failed");
        assert_eq!(json["finalization"]["state"], "completed");
        assert!(!database_state.exists());
        assert!(!cache_state.exists());
        let log = fs::read_to_string(&log_path).unwrap();
        let cache_stop = log.find("stop cache").unwrap();
        let database_stop = log.find("stop database").unwrap();
        assert!(cache_stop < database_stop, "{log}");
        assert_eq!(log.matches("stop cache").count(), 1, "{log}");
        assert_eq!(log.matches("stop database").count(), 1, "{log}");

        fs::write(
            &docker,
            format!(
                "#!/bin/sh\nprintf '%s\\n' \"$*\" >> '{}'\ncase \"$*\" in\n  *'ps --status running -q'*database*) [ -f '{}' ] && printf running ;;\n  *'ps --status running -q'*cache*) if [ -f '{}' ]; then exit 9; fi; [ -f '{}' ] && printf running ;;\n  *'up -d database'*) touch '{}' ;;\n  *'up -d cache'*) touch '{}'; touch '{}'; exit 7 ;;\n  *'stop cache'*) exit 9 ;;\n  *'stop database'*) rm -f '{}' ;;\nesac\n",
                log_path.display(),
                database_state.display(),
                fixture.path().join("cache-observe-fails").display(),
                cache_state.display(),
                database_state.display(),
                cache_state.display(),
                fixture.path().join("cache-observe-fails").display(),
                database_state.display(),
            ),
        )
        .unwrap();
        fs::write(&log_path, "").unwrap();
        unsafe {
            env::set_var(
                "PATH",
                env::join_paths([bin_dir.as_path(), Path::new("/usr/bin"), Path::new("/bin")])
                    .unwrap(),
            )
        };
        let teardown_failure = super::proof_lifecycle(
            Some(fixture.path()),
            None,
            None,
            Some("smoke"),
            None,
            false,
            crate::runner::ExecutionOverrides::default(),
            false,
            OutputFormat::Json,
            false,
        );
        match original_path.as_ref() {
            Some(path) => unsafe { env::set_var("PATH", path) },
            None => unsafe { env::remove_var("PATH") },
        }

        assert_eq!(teardown_failure.exit_code, 1, "{}", teardown_failure.stdout);
        let json: serde_json::Value = serde_json::from_str(&teardown_failure.stdout).unwrap();
        assert_eq!(json["services"][1]["teardown"]["state"], "command_failed");
        assert_eq!(
            json["services"][1]["teardown_assertion"]["state"],
            "state_observed"
        );
        assert_eq!(json["services"][1]["cleanup_lease"], "released");
        assert_eq!(json["finalization"]["state"], "completed");
        assert!(
            !database_state.exists(),
            "other leased services must still finalize"
        );
        let log = fs::read_to_string(&log_path).unwrap();
        assert_eq!(log.matches("stop cache").count(), 1, "{log}");
        assert_eq!(log.matches("stop database").count(), 1, "{log}");

        fs::write(
            &docker,
            format!(
                "#!/bin/sh\nprintf '%s\\n' \"$*\" >> '{}'\ncase \"$*\" in\n  *'ps --status running -q'*database*) [ -f '{}' ] && printf running ;;\n  *'ps --status running -q'*cache*) [ -f '{}' ] && printf running ;;\n  *'up -d database'*) touch '{}' ;;\n  *'up -d cache'*) touch '{}'; exit 130 ;;\n  *'stop cache'*) rm -f '{}' ;;\n  *'stop database'*) rm -f '{}' ;;\nesac\n",
                log_path.display(),
                database_state.display(),
                cache_state.display(),
                database_state.display(),
                cache_state.display(),
                cache_state.display(),
                database_state.display(),
            ),
        )
        .unwrap();
        fs::remove_file(fixture.path().join("cache-observe-fails")).ok();
        fs::remove_file(&cache_state).ok();
        fs::write(&log_path, "").unwrap();
        unsafe {
            env::set_var(
                "PATH",
                env::join_paths([bin_dir.as_path(), Path::new("/usr/bin"), Path::new("/bin")])
                    .unwrap(),
            )
        };
        let interrupted = super::proof_lifecycle(
            Some(fixture.path()),
            None,
            None,
            Some("smoke"),
            None,
            false,
            crate::runner::ExecutionOverrides::default(),
            true,
            OutputFormat::Json,
            false,
        );
        match original_path.as_ref() {
            Some(path) => unsafe { env::set_var("PATH", path) },
            None => unsafe { env::remove_var("PATH") },
        }

        assert_eq!(interrupted.exit_code, 130, "{}", interrupted.stdout);
        let json: serde_json::Value = serde_json::from_str(&interrupted.stdout).unwrap();
        assert_eq!(json["services"][1]["start"]["state"], "interrupted");
        assert_eq!(
            json["finalization"]["state"],
            "completed_after_interruption"
        );
        assert_eq!(json["finalization"]["after_interruption"], true);
        let archive_path = fixture
            .path()
            .join(json["archive"]["path"].as_str().unwrap());
        super::verify_lifecycle_proof_archive(
            &archive_path,
            json["archive"]["identity"].as_str().unwrap(),
            fixture.path(),
        )
        .unwrap();
        let archive: serde_json::Value =
            serde_json::from_slice(&fs::read(&archive_path).unwrap()).unwrap();
        assert_eq!(
            archive["scope"]["service_closure"],
            serde_json::json!(["database", "cache"])
        );
        assert_eq!(archive["proof"]["services"].as_array().unwrap().len(), 2);
        assert_eq!(
            archive["proof"]["finalization"]["state"],
            "completed_after_interruption"
        );
        let log = fs::read_to_string(&log_path).unwrap();
        let cache_stop = log.find("stop cache").unwrap();
        let database_stop = log.find("stop database").unwrap();
        assert!(cache_stop < database_stop, "{log}");
        assert_eq!(log.matches("stop cache").count(), 1, "{log}");
        assert_eq!(log.matches("stop database").count(), 1, "{log}");
    }

    #[cfg(unix)]
    #[test]
    fn proof_runtime_activates_mise_paths_before_parent_re_diagnosis() {
        let _guard = env_mutex_lock();
        let fixture = TempDir::new().unwrap();
        let contract_path = fixture.path().join("ota.yaml");
        let bin_dir = fixture.path().join("bin");
        let fake_home = TempDir::new().unwrap();
        let local_bin = fake_home.path().join(".local").join("bin");
        fs::create_dir_all(&bin_dir).unwrap();
        fs::create_dir_all(&local_bin).unwrap();

        write_executable_script(
            &fake_command_path(&bin_dir, "node"),
            "#!/bin/sh\necho 'v23.11.0'\n",
        );
        write_executable_script(&local_bin.join("mise"), "#!/bin/sh\necho 'mise 2025.1.0'\n");
        write_executable_script(&local_bin.join("node"), "#!/bin/sh\necho 'v22.12.0'\n");

        let original_home = env::var_os("HOME");
        let original_path = env::var_os("PATH");
        let joined_path =
            env::join_paths([bin_dir.as_path(), Path::new("/usr/bin"), Path::new("/bin")]).unwrap();
        unsafe {
            env::set_var("HOME", fake_home.path());
            env::set_var("PATH", &joined_path);
        }

        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: proof-runtime-mise
execution:
  default_context: host
  contexts:
    host:
      backend: native
toolchains:
  node:
    version: "^22.12.0"
tasks:
  dev:
    context: host
    launch:
      kind: command
      exe: node
      args:
        - --version
    requirements:
      toolchains:
        - node
workflows:
  default: app
  app:
    run:
      task: dev
"#,
        )
        .unwrap();

        let output = super::proof_runtime(
            Some(fixture.path()),
            None,
            None,
            Some("app"),
            None,
            true,
            None,
            ExecutionOverrides::default(),
            OutputFormat::Json,
            false,
        );

        match original_home {
            Some(path) => unsafe { env::set_var("HOME", path) },
            None => unsafe { env::remove_var("HOME") },
        }
        match original_path {
            Some(path) => unsafe { env::set_var("PATH", path) },
            None => unsafe { env::remove_var("PATH") },
        }

        assert_eq!(output.exit_code, 0, "{}", output.stdout);
        let json: serde_json::Value =
            serde_json::from_str(&output.stdout).expect("proof runtime json");
        assert_eq!(json["ok"], true, "{}", output.stdout);
        assert_eq!(json["execution_boundary"]["target_freshness"], "unknown");
        let archive_identity = json["archive"]["identity"]
            .as_str()
            .expect("proof archive identity");
        assert!(archive_identity.starts_with("sha256:"));
        let archive_path = json["archive"]["path"]
            .as_str()
            .expect("proof archive path");
        let archive_path = fixture.path().join(archive_path.trim_start_matches("./"));
        let archive_bytes = fs::read(&archive_path).expect("proof archive should exist");
        assert_eq!(
            archive_identity,
            super::contract_snapshot_hash(&archive_bytes)
        );
        let archive: serde_json::Value =
            serde_json::from_slice(&archive_bytes).expect("proof archive json");
        assert_eq!(archive["kind"], "runtime_proof");
        assert_eq!(archive["version"], 6);
        assert_eq!(archive["replay_posture"], "witness_only");
        assert_eq!(
            archive["execution_boundary"]["identity"],
            json["execution_boundary"]["identity"]
        );
        assert_eq!(archive["scope"]["workflow"], "app");
        assert_eq!(archive["scope"]["backend"], "native");
        assert!(
            archive["contract_snapshot_hash"]
                .as_str()
                .is_some_and(|hash| hash.starts_with("sha256:"))
        );
        let snapshot_ref = archive["contract_snapshot_ref"]
            .as_str()
            .expect("archived contract snapshot reference");
        assert!(
            fixture
                .path()
                .join(snapshot_ref.trim_start_matches("./"))
                .is_file()
        );
    }

    #[test]
    fn proof_runtime_archive_rejects_tampered_content() {
        let fixture = TempDir::new().unwrap();
        let content = b"trusted runtime proof";
        let identity = super::contract_snapshot_hash(content);
        let archive_path = fixture.path().join("runtime-proof.json");
        fs::write(&archive_path, b"tampered runtime proof").unwrap();

        let error = super::verify_proof_runtime_archive_identity(&archive_path, &identity)
            .expect_err("tampered archive must not validate");
        assert!(error.contains("does not match its content-addressed identity"));
    }

    #[test]
    fn proof_runtime_archive_rejects_tampered_negative_control_projection() {
        let fixture = TempDir::new().expect("archive fixture");
        let contract_path = fixture.path().join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: archive-negative-control
tasks:
  verify:
    run: echo verify
  observe:
    run: echo observe
  postgres-down:
    run: echo control
workflows:
  default: app
  app:
    run:
      task: verify
    proof:
      seam_observations:
        - id: postgres-marker
          dependency: postgres
          producer_task: verify
          task: observe
          marker_env: OTA_PROOF_POSTGRES_MARKER
      negative_controls:
        - id: postgres-unavailable
          dependency: postgres
          obligation: postgres-marker
          task: postgres-down
          intervention:
            kind: dependency_disruption
          expected_failure: dependency_unavailable
"#,
        )
        .expect("write contract");
        let contract = parse_contract_str(
            &contract_path,
            &fs::read_to_string(&contract_path).expect("read contract"),
        )
        .expect("parse contract");
        let snapshot = super::build_contract_snapshot_artifact(fixture.path(), &contract, true)
            .expect("archive snapshot");
        let scope = super::proof_runtime_archive_scope(
            &contract,
            &contract_path,
            Some("app"),
            ExecutionOverrides::default(),
            vec![
                CrossingProofInvocation {
                    id: String::from("seam_observation:postgres-marker"),
                    kind: String::from("seam_observation"),
                    task: String::from("observe"),
                    order: 0,
                },
                CrossingProofInvocation {
                    id: String::from("negative_control:postgres-unavailable"),
                    kind: String::from("negative_control"),
                    task: String::from("postgres-down"),
                    order: 1,
                },
            ],
            None,
        );
        let archive_path = fixture.path().join("runtime-proof.json");
        let record = serde_json::json!({
            "kind": "runtime_proof",
            "version": 6,
            "contract_snapshot_hash": snapshot.hash,
            "contract_snapshot_ref": super::receipt_storage_path_display(
                snapshot.archive_path.as_deref().expect("snapshot path")
            ),
            "replay_posture": "witness_only",
            "scope": scope,
            "proof": {
                "ok": true,
                "proof_verdict": "passed_with_unproven_boundaries",
                "negative_control": {
                    "id": "postgres-unavailable",
                    "dependency_id": "service:postgres",
                    "obligation_id": "postgres-marker",
                    "control_task": "test:without-postgres",
                    "intervention": { "kind": "environment", "id": "postgres-url" },
                    "expected_failure": "postgres marker fails",
                    "outcome": "expected_obligation_failed",
                    "status": "validated",
                    "failure_mode": "expected_missing_effect",
                    "proof_scope_ref": "workflow:app",
                    "evidence_class": "attested",
                    "failure_attestation_digest": "sha256:canonical"
                },
                "dependency_evidence": [{
                    "dependency_id": "service:postgres",
                    "proof_obligation_id": "postgres-marker",
                    "level": "fault_tested",
                    "observation": { "origin": "negative_control", "evidence_class": "derived" },
                    "negative_control": {
                        "evidence_class": "derived",
                        "status": "validated",
                        "same_obligation": true,
                        "negative_control_id": "postgres-unavailable",
                        "failure_mode": "expected_missing_effect",
                        "failure_attestation_digest": "sha256:canonical"
                    }
                }]
            }
        });
        let assert_refused = |record: serde_json::Value, case: &str| {
            let bytes = serde_json::to_vec(&record).expect("archive json");
            let identity = super::contract_snapshot_hash(&bytes);
            fs::write(&archive_path, bytes).expect("archive write");
            let error = super::verify_emitted_proof_runtime_archive(
                fixture.path(),
                &archive_path,
                &identity,
            )
            .expect_err("tampered negative-control archive must refuse");
            assert!(
                error.contains("negative-control evidence is invalid"),
                "{case}: {error}"
            );
        };

        let mut changed_digest = record.clone();
        changed_digest["proof"]["dependency_evidence"][0]["negative_control"]["failure_attestation_digest"] =
            serde_json::json!("sha256:substituted");
        assert_refused(changed_digest, "digest");

        let mut changed_id = record.clone();
        changed_id["proof"]["dependency_evidence"][0]["negative_control"]["negative_control_id"] =
            serde_json::json!("other-control");
        assert_refused(changed_id, "control id");

        let mut changed_dependency = record.clone();
        changed_dependency["proof"]["dependency_evidence"][0]["dependency_id"] =
            serde_json::json!("service:other");
        assert_refused(changed_dependency, "dependency");

        let mut changed_obligation = record.clone();
        changed_obligation["proof"]["dependency_evidence"][0]["proof_obligation_id"] =
            serde_json::json!("other-obligation");
        assert_refused(changed_obligation, "obligation");

        let mut changed_status = record.clone();
        changed_status["proof"]["negative_control"]["status"] = serde_json::json!("invalid");
        assert_refused(changed_status, "canonical status");

        let mut changed_outcome = record.clone();
        changed_outcome["proof"]["negative_control"]["outcome"] =
            serde_json::json!("unexpected_success");
        assert_refused(changed_outcome, "canonical outcome");

        let mut changed_failure_mode = record.clone();
        changed_failure_mode["proof"]["negative_control"]["failure_mode"] =
            serde_json::json!("timeout");
        assert_refused(changed_failure_mode, "canonical failure mode");

        let mut missing_projection = record.clone();
        missing_projection["proof"]["dependency_evidence"] = serde_json::json!([]);
        assert_refused(missing_projection, "missing projection");

        let mut duplicate_projection = record.clone();
        let projection = duplicate_projection["proof"]["dependency_evidence"][0].clone();
        duplicate_projection["proof"]["dependency_evidence"]
            .as_array_mut()
            .expect("dependency evidence array")
            .push(projection);
        assert_refused(duplicate_projection, "duplicate projection");

        let mut stripped_evidence = record;
        stripped_evidence["proof"]["dependency_evidence"] = serde_json::json!([]);
        stripped_evidence["proof"]["negative_control"] = serde_json::Value::Null;
        assert_refused(stripped_evidence, "stripped canonical and projection");
    }

    #[test]
    fn proof_archive_v6_with_unsafe_seam_requires_direct_crossing_evidence() {
        let repo = TempDir::new().expect("repo tempdir");
        let contract_path = repo.path().join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: governed-proof-archive
governance:
  crossing_authority:
    authority_id: release-authority
tasks:
  verify:
    run: true
    safe_for_agent: true
  observe:
    run: true
    safe_for_agent: false
workflows:
  default: verify
  verify:
    run:
      task: verify
    proof:
      claim: bounded
      seam_observations:
      - id: result
        dependency: result
        producer_task: verify
        task: observe
        marker_env: OTA_PROOF_RESULT_MARKER
"#,
        )
        .expect("write contract");
        let contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .expect("parse contract");
        let snapshot = super::build_contract_snapshot_artifact(repo.path(), &contract, true)
            .expect("snapshot");
        let scope = super::proof_runtime_archive_scope(
            &contract,
            &contract_path,
            Some("verify"),
            ExecutionOverrides::default(),
            vec![CrossingProofInvocation {
                id: String::from("seam_observation:result"),
                kind: String::from("seam_observation"),
                task: String::from("observe"),
                order: 0,
            }],
            Some(Duration::from_secs(45)),
        );
        let derived = super::proof_runtime_archive_crossing_scope(&contract, &scope, 6)
            .expect("scope is derived from contract");
        assert!(derived.0);
        let proof_scope = derived.1.expect("proof crossing scope");
        assert_eq!(
            proof_scope
                .proof_transaction_selection
                .as_ref()
                .and_then(|selection| selection.ready_timeout_seconds),
            Some(45)
        );
        let live_scope = super::evaluate_proof_workflow_crossing_grant(
            &contract,
            &contract_path,
            Some("verify"),
            ExecutionOverrides::default(),
            &scope.proof_invocations,
            CrossingProofTransactionSelection {
                selected_services: Vec::new(),
                service_closure: Vec::new(),
                ready_timeout_seconds: Some(45),
            },
            "runtime_proof",
            false,
            None,
        )
        .expect_err("governed proof without a grant must refuse")
        .semantic_scope
        .expect("live proof admission scope");
        assert_eq!(proof_scope, live_scope);
        let mut explicit_native = scope.clone();
        explicit_native.backend_override = Some(String::from("native"));
        let explicit_native_scope =
            super::proof_runtime_archive_crossing_scope(&contract, &explicit_native, 6)
                .and_then(|(_, scope)| scope)
                .expect("explicit native override scope");
        assert_ne!(proof_scope.identity, explicit_native_scope.identity);
        let mut timeout_mismatch = scope.clone();
        timeout_mismatch.ready_timeout_seconds = Some(90);
        let timeout_scope =
            super::proof_runtime_archive_crossing_scope(&contract, &timeout_mismatch, 6)
                .and_then(|(_, scope)| scope)
                .expect("timeout mismatch scope");
        assert_ne!(proof_scope.identity, timeout_scope.identity);
        let mut memory_mismatch = scope.clone();
        memory_mismatch.memory = Some(512);
        let memory_scope =
            super::proof_runtime_archive_crossing_scope(&contract, &memory_mismatch, 6)
                .and_then(|(_, scope)| scope)
                .expect("memory mismatch scope");
        assert_ne!(proof_scope.identity, memory_scope.identity);
        let mut dependency_mismatch = scope.clone();
        dependency_mismatch.skip_dependencies = true;
        let dependency_scope =
            super::proof_runtime_archive_crossing_scope(&contract, &dependency_mismatch, 6)
                .and_then(|(_, scope)| scope)
                .expect("dependency mismatch scope");
        assert_ne!(proof_scope.identity, dependency_scope.identity);
        let ordinary_workflow_scope = crossing_scope_for_workflow(
            &contract,
            Some("verify"),
            ExecutionOverrides::default(),
            &[],
            None,
            "auto",
            None,
            "heavier_workflow",
            "escalated",
        )
        .expect("ordinary workflow scope");
        assert_ne!(proof_scope.identity, ordinary_workflow_scope.identity);
        let mut platform_mismatch = scope.clone();
        platform_mismatch
            .target_platform
            .as_mut()
            .expect("recorded platform")
            .architecture = String::from("mismatch");
        assert!(
            super::proof_runtime_archive_crossing_scope(&contract, &platform_mismatch, 6).is_none()
        );
        let record = serde_json::json!({
            "kind": "runtime_proof",
            "version": 6,
            "contract_snapshot_hash": snapshot.hash,
            "contract_snapshot_ref": super::receipt_storage_path_display(
                snapshot.archive_path.as_deref().expect("snapshot path")
            ),
            "replay_posture": "witness_only",
            "scope": scope,
            "proof": {
                "ok": true,
                "proof_verdict": "passed_with_unproven_boundaries"
            }
        });
        let bytes = serde_json::to_vec_pretty(&record).expect("archive json");
        let identity = super::contract_snapshot_hash(&bytes);
        let path = repo.path().join(".ota/proof/archives").join(format!(
            "runtime-proof-{}.json",
            identity.strip_prefix("sha256:").expect("sha identity")
        ));
        fs::create_dir_all(path.parent().expect("archive parent")).expect("archive directory");
        fs::write(path, bytes).expect("archive write");

        assert!(super::load_proof_runtime_archive_candidates(repo.path()).is_empty());
    }

    #[test]
    fn proof_archive_rejects_crossing_scope_from_a_different_invocation() {
        let repo = TempDir::new().expect("repo tempdir");
        let contract_path = repo.path().join("ota.yaml");
        fs::write(
            &contract_path,
            r#"
version: 1
project:
  name: governed-proof-scope
governance:
  crossing_authority:
    authority_id: release-authority
tasks:
  verify:
    run: true
    safe_for_agent: true
  observe:
    run: true
    safe_for_agent: false
workflows:
  default: verify
  verify:
    run:
      task: verify
    proof:
      claim: bounded
      seam_observations:
      - id: result
        dependency: result
        producer_task: verify
        task: observe
        marker_env: OTA_PROOF_RESULT_MARKER
"#,
        )
        .expect("write contract");
        let contract =
            parse_contract_str(&contract_path, &fs::read_to_string(&contract_path).unwrap())
                .expect("parse contract");
        let snapshot = super::build_contract_snapshot_artifact(repo.path(), &contract, true)
            .expect("snapshot");
        let scope = super::proof_runtime_archive_scope(
            &contract,
            &contract_path,
            Some("verify"),
            ExecutionOverrides::default(),
            vec![CrossingProofInvocation {
                id: String::from("seam_observation:result"),
                kind: String::from("seam_observation"),
                task: String::from("observe"),
                order: 0,
            }],
            None,
        );
        let wrong_scope = crossing_scope_for_workflow(
            &contract,
            Some("verify"),
            ExecutionOverrides::default(),
            &[],
            None,
            "auto",
            None,
            "heavier_workflow",
            "escalated",
        )
        .expect("ordinary workflow scope");
        assert_ne!(
            super::proof_runtime_archive_crossing_scope(&contract, &scope, 5)
                .and_then(|(_, scope)| scope)
                .expect("proof scope")
                .identity,
            wrong_scope.identity
        );

        // This reference has a valid canonical crossing scope, but it belongs to ordinary
        // workflow execution rather than this proof invocation. The loader must refuse before
        // that receipt can contribute evidence to proof assurance.
        let record = serde_json::json!({
            "kind": "runtime_proof",
            "version": 5,
            "contract_snapshot_hash": snapshot.hash,
            "contract_snapshot_ref": super::receipt_storage_path_display(
                snapshot.archive_path.as_deref().expect("snapshot path")
            ),
            "replay_posture": "witness_only",
            "scope": scope,
            "proof": {
                "ok": true,
                "proof_verdict": "passed_with_unproven_boundaries",
                "crossing_evidence": {
                    "receipt_archive_identity": "sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
                    "receipt_archive_path": ".ota/receipts/repo-receipt-other-scope.json",
                    "transaction_id": "crossing-other-scope",
                    "scope_identity": wrong_scope.identity
                }
            }
        });
        let bytes = serde_json::to_vec_pretty(&record).expect("archive json");
        let identity = super::contract_snapshot_hash(&bytes);
        let path = repo.path().join(".ota/proof/archives").join(format!(
            "runtime-proof-{}.json",
            identity.strip_prefix("sha256:").expect("sha identity")
        ));
        fs::create_dir_all(path.parent().expect("archive parent")).expect("archive directory");
        fs::write(path, bytes).expect("archive write");

        assert!(super::load_proof_runtime_archive_candidates(repo.path()).is_empty());
    }

