fn build_workspace_init_merge_state(
    workspace_path: &Path,
    draft: &WorkspaceInitDraft,
) -> Result<WorkspaceInitMergeState, String> {
    let contents = fs::read_to_string(workspace_path).map_err(|error| {
        format!(
            "failed to read `{}`: {error}",
            compact_workspace_path(workspace_path)
        )
    })?;
    let mut document: YamlValue = serde_yaml::from_str(&contents).map_err(|error| {
        format!(
            "failed to parse existing workspace contract `{}` for merge: {error}",
            compact_workspace_path(workspace_path)
        )
    })?;
    let repos = document
        .as_mapping()
        .and_then(|root| root.get(YamlValue::String(String::from("repos"))))
        .and_then(YamlValue::as_mapping)
        .ok_or_else(|| {
            format!(
                "existing workspace contract `{}` must contain a `repos` mapping for merge",
                compact_workspace_path(workspace_path)
            )
        })?;

    let mut additions = Vec::new();
    for repo in &draft.included {
        if !repos.contains_key(YamlValue::String(repo.name.clone())) {
            additions.push(repo.clone());
        }
    }

    let root = document.as_mapping_mut().ok_or_else(|| {
        format!(
            "existing workspace contract `{}` must be a mapping for merge",
            compact_workspace_path(workspace_path)
        )
    })?;
    let repos_key = YamlValue::String(String::from("repos"));
    if !root.contains_key(&repos_key) {
        root.insert(repos_key.clone(), YamlValue::Mapping(Mapping::new()));
    }
    let repos = root
        .get_mut(&repos_key)
        .and_then(YamlValue::as_mapping_mut)
        .ok_or_else(|| {
            format!(
                "existing workspace contract `{}` must contain a `repos` mapping for merge",
                compact_workspace_path(workspace_path)
            )
        })?;

    for repo in &additions {
        let repo_key = YamlValue::String(repo.name.clone());
        let spec =
            draft.contract.repos.get(&repo.name).ok_or_else(|| {
                format!("internal merge error: missing repo spec `{}`", repo.name)
            })?;
        let mut spec_map = Mapping::new();
        spec_map.insert(
            YamlValue::String(String::from("path")),
            YamlValue::String(spec.path.clone()),
        );
        spec_map.insert(
            YamlValue::String(String::from("required")),
            YamlValue::Bool(spec.required),
        );
        repos.insert(repo_key, YamlValue::Mapping(spec_map));
    }

    let yaml = serde_yaml::to_string(&document).map_err(|error| {
        format!(
            "failed to serialize merged workspace contract `{}`: {error}",
            compact_workspace_path(workspace_path)
        )
    })?;
    let contract =
        parse_workspace_contract_str(workspace_path, &yaml).map_err(|error| error.to_string())?;
    validate_workspace_contract(workspace_path, &contract).map_err(|error| error.to_string())?;
    Ok(WorkspaceInitMergeState {
        yaml,
        contract,
        comparison: WorkspaceInitComparison {
            existing_contract: true,
            additions,
        },
    })
}

fn apply_workspace_init_merge(
    workspace_path: &Path,
    draft: &WorkspaceInitDraft,
) -> Result<WorkspaceInitMergeState, String> {
    let state = build_workspace_init_merge_state(workspace_path, draft)?;
    if !state.comparison.additions.is_empty() {
        fs::write(workspace_path, &state.yaml).map_err(|error| {
            format!(
                "failed to write `{}`: {error}",
                compact_workspace_path(workspace_path)
            )
        })?;
    }
    Ok(state)
}

fn resolve_workspace_init_target(path: Option<&Path>) -> Result<(PathBuf, PathBuf), String> {
    match path {
        Some(path)
            if path
                .file_name()
                .and_then(|name| name.to_str())
                .is_some_and(|name| name == DEFAULT_WORKSPACE_FILE) =>
        {
            let root = path
                .parent()
                .filter(|parent| !parent.as_os_str().is_empty())
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from("."));
            Ok((root, path.to_path_buf()))
        }
        Some(path) if path.is_dir() => {
            let root = path.to_path_buf();
            let workspace_path = root.join(DEFAULT_WORKSPACE_FILE);
            Ok((root, workspace_path))
        }
        Some(path) => Err(format!(
            "workspace init path must be a directory or `{DEFAULT_WORKSPACE_FILE}` target path: {}",
            path.display()
        )),
        None => {
            let root = std::env::current_dir()
                .map_err(|error| format!("failed to resolve current directory: {error}"))?;
            let workspace_path = root.join(DEFAULT_WORKSPACE_FILE);
            Ok((root, workspace_path))
        }
    }
}

fn build_workspace_init_draft(workspace_root: &Path) -> Result<WorkspaceInitDraft, String> {
    let mut candidates = discover_workspace_candidates(workspace_root)?;
    let has_any_candidates = !candidates.is_empty();
    candidates.sort_by(|left, right| left.path.cmp(&right.path));

    let mut included = Vec::new();
    let mut missing_contract = Vec::new();
    for candidate in candidates {
        if candidate.has_contract {
            included.push(WorkspaceInitRepoSummary {
                name: candidate.name,
                path: candidate.path,
            });
        } else {
            missing_contract.push(WorkspaceInitRepoSummary {
                name: candidate.name,
                path: candidate.path,
            });
        }
    }

    if !has_any_candidates {
        return Err(format!(
            "workspace init could not find any repos to bootstrap; add repo contracts first before writing `ota.workspace.yaml`{}",
            format_next_timeline(&[
                String::from("create repo contracts with `ota init <repo-path>`"),
                String::from("or preview repo contracts with `ota detect --dry-run <repo-path>`"),
                String::from(
                    "then compare `ota workspace detect --dry-run <workspace-root>` with `ota workspace init --dry-run <workspace-root>` before writing a workspace contract"
                ),
            ]),
        ));
    }

    let mut repos = BTreeMap::new();
    for repo in &included {
        repos.insert(
            repo.name.clone(),
            WorkspaceInitRepoSpec {
                path: repo.path.clone(),
                required: true,
            },
        );
    }

    let workspace_name = workspace_root
        .file_name()
        .and_then(|name| name.to_str())
        .filter(|name| !name.trim().is_empty())
        .unwrap_or("ota-workspace")
        .to_string();

    Ok(WorkspaceInitDraft {
        contract: WorkspaceInitContract {
            version: 1,
            workspace: WorkspaceInitWorkspace {
                name: workspace_name,
                description: None,
            },
            repos,
        },
        included,
        missing_contract,
    })
}

fn auto_provision_workspace_repo_contracts(
    workspace_root: &Path,
    missing_contract: &[WorkspaceInitRepoSummary],
) -> WorkspaceAutoProvisionResult {
    let mut result = WorkspaceAutoProvisionResult {
        provisioned: Vec::new(),
        skipped: Vec::new(),
    };

    for repo in missing_contract {
        let repo_root = workspace_root.join(&repo.path);
        let contract_path = repo_root.join(DEFAULT_CONTRACT_FILE);
        if contract_path.is_file() {
            result.provisioned.push(repo.clone());
            continue;
        }

        let report = match detect_repo(&repo_root) {
            Ok(report) => report,
            Err(error) => {
                result
                    .skipped
                    .push((repo.clone(), format!("detect failed: {error}")));
                continue;
            }
        };

        let Some(candidate) = build_detect_write_candidate(&report) else {
            match minimal_repo_contract_yaml(&repo.name) {
                Ok(yaml) => {
                    if let Err(error) = fs::write(&contract_path, yaml) {
                        result
                            .skipped
                            .push((repo.clone(), format!("write failed: {error}")));
                        continue;
                    }
                    result.provisioned.push(repo.clone());
                    continue;
                }
                Err(error) => {
                    result.skipped.push((repo.clone(), error));
                    continue;
                }
            }
        };
        let candidate_yaml = match serde_yaml::to_string(&candidate) {
            Ok(yaml) => yaml,
            Err(error) => {
                result
                    .skipped
                    .push((repo.clone(), format!("serialize failed: {error}")));
                continue;
            }
        };

        let yaml_to_write = if contract_yaml_valid(&contract_path, &candidate_yaml) {
            candidate_yaml
        } else {
            match minimal_repo_contract_yaml(&repo.name) {
                Ok(yaml) => yaml,
                Err(error) => {
                    result.skipped.push((repo.clone(), error));
                    continue;
                }
            }
        };

        if let Err(error) = fs::write(&contract_path, yaml_to_write) {
            result
                .skipped
                .push((repo.clone(), format!("write failed: {error}")));
            continue;
        }
        result.provisioned.push(repo.clone());
    }

    result
}

fn rewrite_workspace_repo_contracts(
    workspace_root: &Path,
    included: &[WorkspaceInitRepoSummary],
    missing_contract: &[WorkspaceInitRepoSummary],
) -> WorkspaceRepoRewriteResult {
    let mut result = WorkspaceRepoRewriteResult {
        rewritten: Vec::new(),
        skipped: Vec::new(),
    };
    let repos = included
        .iter()
        .chain(missing_contract.iter())
        .cloned()
        .collect::<Vec<_>>();

    for repo in repos {
        let repo_root = workspace_root.join(&repo.path);
        let contract_path = repo_root.join(DEFAULT_CONTRACT_FILE);
        let report = match detect_repo(&repo_root) {
            Ok(report) => report,
            Err(error) => {
                result
                    .skipped
                    .push((repo.clone(), format!("detect failed: {error}")));
                continue;
            }
        };

        let Some(candidate) = build_detect_write_candidate(&report) else {
            match minimal_repo_contract_yaml(&repo.name) {
                Ok(yaml) => {
                    if contract_path.is_file()
                        && let Err(error) = create_timestamped_backup(&contract_path)
                    {
                        result
                            .skipped
                            .push((repo.clone(), format!("backup failed: {error}")));
                        continue;
                    }
                    if let Err(error) = fs::write(&contract_path, yaml) {
                        result
                            .skipped
                            .push((repo.clone(), format!("write failed: {error}")));
                        continue;
                    }
                    result.rewritten.push(repo);
                    continue;
                }
                Err(error) => {
                    result.skipped.push((repo.clone(), error));
                    continue;
                }
            }
        };
        let candidate_yaml = match serde_yaml::to_string(&candidate) {
            Ok(yaml) => yaml,
            Err(error) => {
                result
                    .skipped
                    .push((repo.clone(), format!("serialize failed: {error}")));
                continue;
            }
        };

        let yaml_to_write = if contract_yaml_valid(&contract_path, &candidate_yaml) {
            candidate_yaml
        } else {
            match minimal_repo_contract_yaml(&repo.name) {
                Ok(yaml) => yaml,
                Err(error) => {
                    result.skipped.push((repo.clone(), error));
                    continue;
                }
            }
        };

        if contract_path.is_file()
            && let Err(error) = create_timestamped_backup(&contract_path)
        {
            result
                .skipped
                .push((repo.clone(), format!("backup failed: {error}")));
            continue;
        }

        if let Err(error) = fs::write(&contract_path, yaml_to_write) {
            result
                .skipped
                .push((repo.clone(), format!("write failed: {error}")));
            continue;
        }
        result.rewritten.push(repo);
    }

    result
}

fn contract_yaml_valid(path: &Path, yaml: &str) -> bool {
    parse_contract_str(path, yaml)
        .map_err(|error| error.to_string())
        .and_then(|contract| {
            validate_contract_with_path(&contract, Some(path)).map_err(|error| error.to_string())
        })
        .is_ok()
}

fn minimal_repo_contract_yaml(project_name: &str) -> Result<String, String> {
    let mut root = Mapping::new();
    root.insert(
        YamlValue::String(String::from("version")),
        YamlValue::Number(1u64.into()),
    );
    let mut project = Mapping::new();
    project.insert(
        YamlValue::String(String::from("name")),
        YamlValue::String(project_name.to_string()),
    );
    root.insert(
        YamlValue::String(String::from("project")),
        YamlValue::Mapping(project),
    );
    let yaml = serde_yaml::to_string(&YamlValue::Mapping(root))
        .map_err(|error| format!("failed to build minimal contract: {error}"))?;

    if !contract_yaml_valid(Path::new(DEFAULT_CONTRACT_FILE), &yaml) {
        return Err(String::from(
            "failed to build a valid minimal contract for auto-provision",
        ));
    }

    Ok(yaml)
}

#[derive(Clone)]
struct WorkspaceCandidate {
    name: String,
    path: String,
    has_contract: bool,
}

fn discover_workspace_candidates(workspace_root: &Path) -> Result<Vec<WorkspaceCandidate>, String> {
    let mut rel_paths = BTreeSet::new();
    collect_child_repo_dirs(workspace_root, workspace_root, &mut rel_paths)?;

    for group in ["apps", "services", "repos", "packages"] {
        let container = workspace_root.join(group);
        if container.is_dir() {
            collect_child_repo_dirs(workspace_root, &container, &mut rel_paths)?;
        }
    }

    let mut used_names = BTreeSet::new();
    let mut candidates = Vec::new();
    for rel_path in rel_paths {
        let repo_root = workspace_root.join(&rel_path);
        if !looks_like_repo_candidate(&repo_root) {
            continue;
        }
        let has_contract = repo_root.join(DEFAULT_CONTRACT_FILE).is_file();
        let name = make_workspace_repo_name(&rel_path, &mut used_names);
        candidates.push(WorkspaceCandidate {
            name,
            path: rel_path,
            has_contract,
        });
    }

    Ok(candidates)
}

fn collect_child_repo_dirs(
    workspace_root: &Path,
    parent: &Path,
    rel_paths: &mut BTreeSet<String>,
) -> Result<(), String> {
    let entries = fs::read_dir(parent)
        .map_err(|error| format!("failed to inspect `{}`: {error}", parent.display()))?;
    for entry in entries {
        let entry =
            entry.map_err(|error| format!("failed to inspect `{}`: {error}", parent.display()))?;
        let path = entry.path();
        if !path.is_dir() {
            continue;
        }
        let Some(name) = path.file_name().and_then(|value| value.to_str()) else {
            continue;
        };
        if name.starts_with('.') {
            continue;
        }

        let rel = match path.strip_prefix(workspace_root) {
            Ok(rel) => rel,
            Err(_) => continue,
        };
        rel_paths.insert(path_to_contract_style(rel));
    }
    Ok(())
}

fn path_to_contract_style(path: &Path) -> String {
    path.components()
        .map(|component| component.as_os_str().to_string_lossy().into_owned())
        .collect::<Vec<_>>()
        .join("/")
}

fn make_workspace_repo_name(rel_path: &str, used_names: &mut BTreeSet<String>) -> String {
    let base = rel_path
        .rsplit('/')
        .next()
        .filter(|value| !value.trim().is_empty())
        .unwrap_or("repo")
        .to_string();
    if used_names.insert(base.clone()) {
        return base;
    }

    let mut normalized = rel_path.replace('/', "-");
    if normalized.is_empty() {
        normalized = String::from("repo");
    }
    if used_names.insert(normalized.clone()) {
        return normalized;
    }

    let mut suffix = 2;
    loop {
        let candidate = format!("{normalized}-{suffix}");
        if used_names.insert(candidate.clone()) {
            return candidate;
        }
        suffix += 1;
    }
}

fn looks_like_repo_candidate(repo_root: &Path) -> bool {
    if repo_root.join(DEFAULT_CONTRACT_FILE).is_file() || repo_root.join(".git").exists() {
        return true;
    }

    const MARKERS: [&str; 12] = [
        "package.json",
        "pyproject.toml",
        "requirements.txt",
        "go.mod",
        "Cargo.toml",
        "pom.xml",
        "build.gradle",
        "build.gradle.kts",
        "composer.json",
        "CMakeLists.txt",
        "mix.exs",
        "Project.toml",
    ];

    MARKERS
        .iter()
        .any(|marker| repo_root.join(marker).is_file())
}

#[derive(Clone, Debug)]
struct RunLogCaptureResult {
    logs: Option<ExecutionReceiptLogs>,
    warning: Option<String>,
}

#[derive(Clone, Debug)]
struct PreparedStreamingRunLogs {
    capture: RunLogCaptureResult,
    live_log: Option<StreamLogTee>,
}

fn capture_durable_run_logs(
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    stdout: &str,
    stderr: &str,
    enabled: bool,
) -> RunLogCaptureResult {
    if !enabled {
        return RunLogCaptureResult {
            logs: None,
            warning: None,
        };
    }

    match write_durable_run_logs(contract_path, task_name, member, stdout, stderr) {
        Ok(logs) => RunLogCaptureResult {
            logs: Some(logs),
            warning: None,
        },
        Err(error) => RunLogCaptureResult {
            logs: None,
            warning: Some(format!("log capture failed: {error}")),
        },
    }
}

fn prepare_streaming_durable_run_logs(
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    enabled: bool,
) -> PreparedStreamingRunLogs {
    if !enabled {
        return PreparedStreamingRunLogs {
            capture: RunLogCaptureResult {
                logs: None,
                warning: None,
            },
            live_log: None,
        };
    }

    match create_durable_run_log_paths(contract_path, task_name, member) {
        Ok((logs, stdout_path, stderr_path)) => {
            let stdout = StreamLogFile::create(&stdout_path).map_err(|error| {
                format!(
                    "failed to create stdout log `{}`: {error}",
                    compact_path(&stdout_path, ".")
                )
            });
            let stderr = StreamLogFile::create(&stderr_path).map_err(|error| {
                format!(
                    "failed to create stderr log `{}`: {error}",
                    compact_path(&stderr_path, ".")
                )
            });
            match (stdout, stderr) {
                (Ok(stdout), Ok(stderr)) => PreparedStreamingRunLogs {
                    capture: RunLogCaptureResult {
                        logs: Some(logs),
                        warning: None,
                    },
                    live_log: Some(StreamLogTee {
                        stdout: Arc::new(Mutex::new(stdout)),
                        stderr: Arc::new(Mutex::new(stderr)),
                    }),
                },
                (Err(error), _) | (_, Err(error)) => PreparedStreamingRunLogs {
                    capture: RunLogCaptureResult {
                        logs: None,
                        warning: Some(format!("log capture failed: {error}")),
                    },
                    live_log: None,
                },
            }
        }
        Err(error) => PreparedStreamingRunLogs {
            capture: RunLogCaptureResult {
                logs: None,
                warning: Some(format!("log capture failed: {error}")),
            },
            live_log: None,
        },
    }
}

fn capture_streaming_structured_error_logs(
    prepared_logs: &PreparedStreamingRunLogs,
    error_detail: &str,
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    enabled: bool,
) -> RunLogCaptureResult {
    if let (Some(logs), Some(live_log)) = (
        prepared_logs.capture.logs.clone(),
        prepared_logs.live_log.as_ref(),
    ) {
        match live_log.stderr.lock() {
            Ok(mut stderr) => match stderr.write_all(error_detail.as_bytes()) {
                Ok(()) => {
                    let _ = stderr.flush();
                    RunLogCaptureResult {
                        logs: Some(logs),
                        warning: prepared_logs.capture.warning.clone(),
                    }
                }
                Err(error) => RunLogCaptureResult {
                    logs: Some(logs),
                    warning: Some(format!("log capture failed: {error}")),
                },
            },
            Err(_) => RunLogCaptureResult {
                logs: Some(logs),
                warning: Some(String::from(
                    "log capture failed: durable log handle lock was poisoned",
                )),
            },
        }
    } else {
        capture_durable_run_logs(contract_path, task_name, member, "", error_detail, enabled)
    }
}

fn create_durable_run_log_paths(
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
) -> Result<(ExecutionReceiptLogs, PathBuf, PathBuf), String> {
    let repo_root = contract_path.parent().unwrap_or_else(|| Path::new("."));
    let logs_root = repo_root.join(".ota").join("state").join("logs");
    fs::create_dir_all(&logs_root).map_err(|error| {
        format!(
            "failed to create log directory `{}`: {error}",
            compact_path(&logs_root, ".")
        )
    })?;

    let stamp = OffsetDateTime::now_utc()
        .format(&format_description!(
            "[year][month][day]-[hour][minute][second]-[subsecond digits:3]Z"
        ))
        .map_err(|error| format!("failed to format run log timestamp: {error}"))?;
    let task_slug = sanitize_log_component(task_name, "task");
    let member_suffix = member.map(|value| format!("-{}", sanitize_log_component(value, "member")));
    let run_id = format!(
        "{stamp}-{task_slug}{}-{}",
        member_suffix.unwrap_or_default(),
        std::process::id()
    );
    let run_dir = logs_root.join(run_id);
    fs::create_dir_all(&run_dir).map_err(|error| {
        format!(
            "failed to create run log directory `{}`: {error}",
            compact_path(&run_dir, ".")
        )
    })?;

    let stdout_path = run_dir.join("stdout.log");
    let stderr_path = run_dir.join("stderr.log");
    Ok((
        ExecutionReceiptLogs {
            dir: repo_relative_log_path(repo_root, &run_dir),
            stdout: repo_relative_log_path(repo_root, &stdout_path),
            stderr: repo_relative_log_path(repo_root, &stderr_path),
        },
        stdout_path,
        stderr_path,
    ))
}

fn write_durable_run_logs(
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    stdout: &str,
    stderr: &str,
) -> Result<ExecutionReceiptLogs, String> {
    let (logs, stdout_path, stderr_path) =
        create_durable_run_log_paths(contract_path, task_name, member)?;
    fs::write(&stdout_path, stdout).map_err(|error| {
        format!(
            "failed to write stdout log `{}`: {error}",
            compact_path(&stdout_path, ".")
        )
    })?;
    fs::write(&stderr_path, stderr).map_err(|error| {
        format!(
            "failed to write stderr log `{}`: {error}",
            compact_path(&stderr_path, ".")
        )
    })?;

    Ok(logs)
}

fn sanitize_log_component(value: &str, fallback: &str) -> String {
    let mut output = value
        .chars()
        .map(|ch| if ch.is_ascii_alphanumeric() { ch } else { '-' })
        .collect::<String>();
    while output.contains("--") {
        output = output.replace("--", "-");
    }
    let output = output.trim_matches('-');
    if output.is_empty() {
        fallback.to_string()
    } else {
        output.to_string()
    }
}

fn repo_relative_log_path(repo_root: &Path, path: &Path) -> String {
    path.strip_prefix(repo_root)
        .map(|relative| relative.to_string_lossy().to_string())
        .unwrap_or_else(|_| compact_path(path, "."))
}

fn run_contract_targets(
    task_name: &str,
    resolved_path: &Path,
    overrides: ExecutionOverrides,
    members: &[String],
    task_inputs: &[String],
    effect_overrides: &[String],
    agent: bool,
    grant: Option<&str>,
    sandbox_target: Option<&str>,
    reason: Option<&str>,
    show_receipt: bool,
    force_stream: bool,
    stream_output: bool,
    persist_logs: bool,
) -> Result<String, RunCommandFailure> {
    if members.is_empty() {
        let target = load_and_validate_target(resolved_path, None).map_err(|error| {
            render_run_contract_problem_failure(resolved_path, None, task_name, error)
        })?;
        return run_single_contract_target(
            task_name,
            overrides,
            None,
            target,
            task_inputs,
            effect_overrides,
            agent,
            grant,
            sandbox_target,
            reason,
            show_receipt,
            force_stream,
            stream_output,
            persist_logs,
        );
    }

    let mut stderr_sections = Vec::new();
    for member in members {
        let target =
            load_and_validate_target(resolved_path, Some(member.as_str())).map_err(|error| {
                render_run_contract_problem_failure(
                    resolved_path,
                    Some(member.as_str()),
                    task_name,
                    error,
                )
            })?;
        stderr_sections.push(run_single_contract_target(
            task_name,
            overrides,
            Some(member.as_str()),
            target,
            task_inputs,
            effect_overrides,
            agent,
            grant,
            sandbox_target,
            reason,
            show_receipt,
            force_stream,
            stream_output,
            persist_logs,
        )?);
    }

    Ok(stderr_sections.join("\n"))
}

fn run_single_contract_target(
    task_name: &str,
    overrides: ExecutionOverrides,
    member: Option<&str>,
    target: LoadedContractTarget,
    task_inputs: &[String],
    effect_overrides: &[String],
    agent: bool,
    grant: Option<&str>,
    sandbox_target: Option<&str>,
    reason: Option<&str>,
    show_receipt: bool,
    force_stream: bool,
    stream_output: bool,
    persist_logs: bool,
) -> Result<String, RunCommandFailure> {
    let details_footer = task_use_details_footer(Some(&target.contract_path), member);
    let selected_task_name = canonical_declared_task_name(&target.contract, task_name);
    let typed_effect_admission = enforce_typed_effect_pre_execution_boundary(
        &target.contract,
        &target.contract_path,
        selected_task_name.as_str(),
        overrides,
    )?;
    let typed_policy_observed = typed_effect_admission.is_typed();
    let CommandTypedEffectAdmission {
        typed: typed_effect_admission,
        loaded_policy,
    } = typed_effect_admission;
    let replay_input_preflight = task_replay_input_preflight_with_retained_policy(
        &target.contract,
        &target.contract_path,
        selected_task_name.as_str(),
        typed_policy_observed,
        loaded_policy,
    );
    enforce_task_replay_input_preflight(
        &target.contract,
        &target.contract_path,
        selected_task_name.as_str(),
        member,
        overrides,
        show_receipt,
        &replay_input_preflight,
    )?;
    if agent
        && let Some(failure) = run_agent_execution_refusal(
            task_name,
            overrides,
            member,
            &target.contract,
            &target.contract_path,
            show_receipt,
            replay_input_preflight.doctor_policy_snapshot(),
        )
    {
        return Err(failure);
    }
    let initial_grant_admission = evaluate_task_crossing_grant(
        &target.contract,
        &target.contract_path,
        selected_task_name.as_str(),
        overrides,
        task_inputs,
        effect_overrides,
        agent,
        grant,
        sandbox_target,
    )
    .map_err(|error| {
        crossing_grant_run_failure(
            &target.contract,
            &target.contract_path,
            task_name,
            member,
            overrides,
            show_receipt,
            agent,
            reason,
            grant,
            &error,
        )
    })?;
    let sandbox_admission = resolve_task_sandbox_admission(
        &target.contract,
        &target.contract_path,
        selected_task_name.as_str(),
        overrides,
        agent,
        sandbox_target,
        &typed_effect_admission,
        replay_input_preflight.loaded_policy.as_ref(),
    )
    .map_err(|error| {
        sandbox_admission_run_failure(
            &target.contract,
            &target.contract_path,
            task_name,
            member,
            overrides,
            show_receipt,
            agent,
            reason,
            &error,
        )
    })?;
    // Closure-wide interaction preflight: refuse before any dependency or task execution when
    // any task in the full dependency closure has `interaction: required` and no interactive
    // terminal is available. This check covers the entire planned execution set so that Ota
    // never starts a dependency only to fail partway through the closure.
    let mut closure_allows_terminal_passthrough = false;
    let closure_plan = plan_task_execution_with_overrides(&target.contract, task_name, overrides)
        .map_err(|error| RunCommandFailure {
        message: stylize_text_failure("ota run", &render_run_error(error)),
        summary: None,
        exit_code: 1,
        receipt: None,
    })?;
    for step in &closure_plan.steps {
        let closure_task = &step.task;
        let Some(posture) = task_command_interaction_posture_for_backend(
            &target.contract,
            closure_task,
            ExecutionOverrides {
                backend: Some(step.backend),
                ..overrides
            },
        ) else {
            continue;
        };

        let is_native = step.backend == Backend::Native;
        let task_terminal_available =
            resolve_command_terminal_passthrough(posture, agent, is_native);

        if posture == CommandInteractionPosture::Required && !task_terminal_available {
            let error = RunError::InteractionRequired {
                task: closure_task.clone(),
            };
            let blocked = run_error_receipt_blocked_entries(&error);
            let message = render_run_error(error);
            let mut receipt = run_execution_receipt_with_shared(
                &target.contract,
                &target.contract_path,
                None,
                overrides,
                task_name,
                member,
                &[],
                &[],
                &[],
                &[],
                &[],
                None,
                &[],
                None,
                1,
                false,
                None,
                None,
                Some(format!(
                    "rerun task `{closure_task}` from a human native terminal"
                )),
            );
            receipt.blocked = blocked;
            refresh_execution_receipt_status(&mut receipt);
            let summary =
                render_execution_receipt_summary_block(&receipt, Some(task_name), "RUN SUMMARY");
            return Err(RunCommandFailure {
                message: stylize_text_failure("ota run", &message),
                summary: Some(summary),
                exit_code: 1,
                receipt: show_receipt.then(|| render_execution_receipt_text(&receipt)),
            });
        }

        if task_terminal_available
            && (!force_stream || posture == CommandInteractionPosture::Required)
        {
            closure_allows_terminal_passthrough = true;
        }
    }

    let use_terminal_passthrough =
        should_use_command_terminal_passthrough(closure_allows_terminal_passthrough);

    let grant_admission = if initial_grant_admission.is_some() {
        evaluate_task_crossing_grant(
            &target.contract,
            &target.contract_path,
            selected_task_name.as_str(),
            overrides,
            task_inputs,
            effect_overrides,
            agent,
            grant,
            sandbox_target,
        )
        .map_err(|error| {
            crossing_grant_run_failure(
                &target.contract,
                &target.contract_path,
                task_name,
                member,
                overrides,
                show_receipt,
                agent,
                reason,
                grant,
                &error,
            )
        })?
    } else {
        None
    };
    if grant_admission.is_some()
        && let Some(failure) = run_selected_precondition_failure(
            selected_task_name.as_str(),
            overrides,
            member,
            &target.contract,
            &target.contract_path,
            show_receipt,
            &replay_input_preflight,
            agent,
            reason,
            false,
        )
    {
        return Err(failure);
    }
    let (_crossing_grant_guard, _crossing_transaction_guard) = match grant_admission {
        Some(plan) => {
            let (authority, transaction) =
                activate_crossing_authority_plan(contract_working_dir(&target.contract_path), plan)
                    .map_err(|error| {
                        crossing_grant_run_failure(
                            &target.contract,
                            &target.contract_path,
                            task_name,
                            member,
                            overrides,
                            show_receipt,
                            agent,
                            reason,
                            grant,
                            &error,
                        )
                    })?;
            (Some(authority), Some(transaction))
        }
        None => (None, None),
    };
    let crossing_failure_contract = target.contract.clone();
    let crossing_failure_contract_path = target.contract_path.clone();
    let result = crate::runner::with_oci_local_application_plan(
        sandbox_admission
            .as_ref()
            .and_then(|admission| admission.plan.as_ref()),
        || {
            if let Some(failure) = run_selected_precondition_failure(
                selected_task_name.as_str(),
                overrides,
                member,
                &target.contract,
                &target.contract_path,
                show_receipt,
                &replay_input_preflight,
                agent,
                reason,
                true,
            ) {
                return Err(failure);
            }
            if stream_output
                || use_terminal_passthrough
                || task_requires_interactive_stream(&target.contract, task_name, overrides)
            {
                run_single_contract_target_streaming(
                    task_name,
                    overrides,
                    member,
                    target,
                    task_inputs,
                    agent,
                    reason,
                    show_receipt,
                    &details_footer,
                    persist_logs,
                    use_terminal_passthrough,
                    replay_input_preflight,
                )
            } else {
                run_single_contract_target_captured(
                    task_name,
                    overrides,
                    member,
                    target,
                    task_inputs,
                    agent,
                    reason,
                    show_receipt,
                    &details_footer,
                    persist_logs,
                    replay_input_preflight,
                )
                .map(|result| result.output)
            }
        },
    );
    result.map_err(|failure| {
        ensure_crossing_run_failure_evidence(
            failure,
            &crossing_failure_contract,
            &crossing_failure_contract_path,
            task_name,
            member,
            overrides,
            show_receipt,
            agent,
            reason,
        )
    })
}

fn enforce_typed_effect_pre_execution_boundary(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    overrides: ExecutionOverrides,
) -> Result<CommandTypedEffectAdmission, RunCommandFailure> {
    let roots = [EffectPolicyInvocation {
        task: task_name.to_string(),
        origin: String::from("run"),
    }];
    let admission = admit_command_typed_effect_closure(
        contract,
        contract_path,
        None,
        &roots,
        overrides,
        Some(&current_effect_governance_overrides()),
    )
    .map_err(|error| RunCommandFailure {
        message: stylize_text_failure("ota run", &render_run_error(*error)),
        summary: None,
        exit_code: 1,
        receipt: None,
    })?;
    if let Some(error) = typed_effect_admission_refusal(&admission.typed) {
        return Err(RunCommandFailure {
            message: stylize_text_failure("ota run", &render_run_error(error)),
            summary: None,
            exit_code: 1,
            receipt: None,
        });
    }
    Ok(admission)
}

fn selected_workflow_phase_task_roots(
    contract: &Contract,
    workflow_name: Option<&str>,
) -> Vec<EffectPolicyInvocation> {
    [
        (
            "prepare",
            contract.selected_prepare_task_name_for(workflow_name),
        ),
        (
            "setup",
            contract.selected_setup_task_name_for(workflow_name),
        ),
        ("run", contract.selected_run_task_name_for(workflow_name)),
        (
            "attach",
            contract.selected_attach_task_name_for(workflow_name),
        ),
    ]
    .into_iter()
    .filter_map(|(origin, task)| {
        task.map(|task| EffectPolicyInvocation {
            task: task.to_string(),
            origin: origin.to_string(),
        })
    })
    .collect()
}

fn typed_effect_closure_refusal(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    roots: &[EffectPolicyInvocation],
    overrides: ExecutionOverrides,
) -> Result<Option<RunError>, RunError> {
    let admission =
        typed_effect_closure_admission(contract, contract_path, workflow_name, roots, overrides)?;
    Ok(typed_effect_admission_refusal(&admission))
}

fn typed_effect_closure_admission(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    roots: &[EffectPolicyInvocation],
    overrides: ExecutionOverrides,
) -> Result<TypedEffectAdmission, RunError> {
    let adjusted_contract =
        contract_adjusted_for_selected_workflow_env_profile(contract, workflow_name);
    let contract = adjusted_contract.as_ref().unwrap_or(contract);
    admit_typed_effect_closure(
        contract,
        contract_path,
        workflow_name,
        roots,
        overrides,
        Some(&current_effect_governance_overrides()),
    )
    .map_err(|error| *error)
}

#[derive(Debug, Clone)]
struct ResolvedSandboxAdmission {
    effect_policy_decision: Option<crate::effect_policy::EffectPolicyDecision>,
    policy: crate::sandbox_policy::SandboxPolicy,
    effective: crate::sandbox_policy::EffectiveSandboxPolicy,
    evaluation: crate::sandbox_policy::ProviderApplicationEvaluation,
    plan: Option<crate::sandbox_policy::OciLocalApplicationPlan>,
    resolution: &'static str,
}

#[derive(Debug, Clone, Serialize)]
struct SandboxAdmissionError {
    kind: &'static str,
    requested_target: Option<String>,
    resolved_target: Option<String>,
    canonical_policy_identity: Option<String>,
    restriction_overlay_identities: Vec<String>,
    effective_policy_identity: Option<String>,
    refusals: Vec<crate::sandbox_policy::SandboxAdmissionRefusal>,
    supported_alternatives: Vec<String>,
    message: String,
}

fn sandbox_admission_json(admission: &ResolvedSandboxAdmission) -> JsonValue {
    json!({
        "decision": "admitted",
        "resolution": admission.resolution,
        "provider_target": admission.evaluation.provider_target,
        "effect_policy_decision": admission.effect_policy_decision,
        "canonical_policy": admission.policy,
        "restriction_overlay_identities": admission.effective.restriction_overlay_identities,
        "effective_policy": admission.effective,
        "provider_evaluation": admission.evaluation,
        "application_plan_identity": admission.plan.as_ref().map(|plan| plan.identity.as_str()),
    })
}

fn sandbox_typed_effect_policy_decision(
    admission: &TypedEffectAdmission,
) -> Result<Option<crate::effect_policy::EffectPolicyDecision>, SandboxAdmissionError> {
    if admission.closure.application_plans.is_empty() {
        return Ok(None);
    }
    let Some(decision) = admission.policy_decision.as_ref() else {
        return Err(SandboxAdmissionError {
            kind: "sandbox_effect_policy_unavailable",
            requested_target: None,
            resolved_target: None,
            canonical_policy_identity: None,
            restriction_overlay_identities: Vec::new(),
            effective_policy_identity: None,
            refusals: Vec::new(),
            supported_alternatives: Vec::new(),
            message: String::from(
                "typed sandbox admission requires a command-scoped effect-policy decision",
            ),
        });
    };
    if decision.aggregate_decision == PolicyEffectDecision::Deny {
        return Err(SandboxAdmissionError {
            kind: "sandbox_effect_policy_denied",
            requested_target: None,
            resolved_target: None,
            canonical_policy_identity: None,
            restriction_overlay_identities: Vec::new(),
            effective_policy_identity: None,
            refusals: Vec::new(),
            supported_alternatives: Vec::new(),
            message: format!(
                "typed effect-policy decision `{}` denied provider admission before sandbox capability evaluation",
                decision.identity
            ),
        });
    }
    Ok(Some(decision.clone()))
}

fn render_sandbox_admission_preview(admission: &ResolvedSandboxAdmission) -> String {
    format!(
        "\n\n{}\n{}\n{}\n{}\n{}",
        paint_section_title("Sandbox Admission"),
        detail_list_row(&paint_key("Decision:"), "admitted"),
        detail_list_row(
            &paint_key("Target:"),
            &paint_backticked_code(admission.evaluation.provider_target.as_str()),
        ),
        detail_list_row(&paint_key("Resolution:"), admission.resolution,),
        detail_list_row(
            &paint_key("Policy:"),
            &paint_backticked_code(admission.effective.identity.as_str()),
        ),
    )
}

fn render_sandbox_admission_json_preview(admission: &JsonValue) -> String {
    let decision = admission
        .get("decision")
        .and_then(JsonValue::as_str)
        .unwrap_or("unknown");
    let target = admission
        .get("provider_target")
        .and_then(JsonValue::as_str)
        .unwrap_or("unresolved");
    let resolution = admission
        .get("resolution")
        .and_then(JsonValue::as_str)
        .unwrap_or("unknown");
    let policy = admission
        .pointer("/effective_policy/identity")
        .and_then(JsonValue::as_str)
        .unwrap_or("unavailable");
    format!(
        "\n\n{}\n{}\n{}\n{}\n{}",
        paint_section_title("Sandbox Admission"),
        detail_list_row(&paint_key("Decision:"), decision),
        detail_list_row(&paint_key("Target:"), &paint_backticked_code(target)),
        detail_list_row(&paint_key("Resolution:"), resolution),
        detail_list_row(&paint_key("Policy:"), &paint_backticked_code(policy)),
    )
}

fn resolve_task_sandbox_admission(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    overrides: ExecutionOverrides,
    agent: bool,
    requested_target: Option<&str>,
    typed_effect_admission: &TypedEffectAdmission,
    loaded_policy: Option<&LoadedOrgPolicyPack>,
) -> Result<Option<ResolvedSandboxAdmission>, SandboxAdmissionError> {
    let requested_target = requested_target
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if requested_target.is_some_and(|target| target != crate::sandbox_policy::OCI_LOCAL_TARGET) {
        return Err(SandboxAdmissionError {
            kind: "sandbox_target_unavailable",
            requested_target: requested_target.map(str::to_string),
            resolved_target: None,
            canonical_policy_identity: None,
            restriction_overlay_identities: Vec::new(),
            effective_policy_identity: None,
            refusals: Vec::new(),
            supported_alternatives: vec![crate::sandbox_policy::OCI_LOCAL_TARGET.to_string()],
            message: format!(
                "sandbox target `{}` is not available; the first enforcing target is `{}`",
                requested_target.unwrap_or_default(),
                crate::sandbox_policy::OCI_LOCAL_TARGET
            ),
        });
    }
    if !agent && requested_target.is_none() {
        return Ok(None);
    }
    let effect_policy_decision = sandbox_typed_effect_policy_decision(typed_effect_admission)?;
    let task_has_runtime_boundary = contract
        .execution
        .as_ref()
        .and_then(|execution| execution.runtime_boundary.as_ref())
        .is_some_and(|boundary| !boundary.is_empty())
        || contract
            .task_execution_closure_names([task_name.to_string()])
            .iter()
            .any(|closure_task| {
                contract
                    .tasks
                    .get(closure_task)
                    .and_then(|task| task.runtime_boundary.as_ref())
                    .is_some_and(|boundary| !boundary.is_empty())
            });
    let policy_has_runtime_boundary = loaded_policy
        .and_then(|loaded| loaded.pack.policies.sandbox.as_ref())
        .is_some_and(|sandbox| sandbox.filesystem.is_some() || sandbox.network.is_some());
    if !task_has_runtime_boundary && !policy_has_runtime_boundary {
        if requested_target.is_some() {
            return Err(SandboxAdmissionError {
                kind: "sandbox_policy_not_declared",
                requested_target: requested_target.map(str::to_string),
                resolved_target: None,
                canonical_policy_identity: None,
                restriction_overlay_identities: Vec::new(),
                effective_policy_identity: None,
                refusals: Vec::new(),
                supported_alternatives: Vec::new(),
                message: String::from(
                    "the selected lane and loaded policy do not declare an authoritative runtime boundary; Ota will not convert provider defaults into policy",
                ),
            });
        }
        return Ok(None);
    }
    let policy = crate::sandbox_policy::sandbox_policy_for_task(contract, task_name, overrides)
        .map_err(|message| SandboxAdmissionError {
            kind: "sandbox_policy_unavailable",
            requested_target: requested_target.map(str::to_string),
            resolved_target: None,
            canonical_policy_identity: None,
            restriction_overlay_identities: Vec::new(),
            effective_policy_identity: None,
            refusals: Vec::new(),
            supported_alternatives: Vec::new(),
            message,
        })?;
    resolve_sandbox_policy_admission(
        policy,
        effect_policy_decision,
        contract_path,
        overrides,
        agent,
        requested_target,
        loaded_policy,
    )
}

fn resolve_workflow_sandbox_admission(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    agent: bool,
    requested_target: Option<&str>,
    typed_effect_admission: &TypedEffectAdmission,
    loaded_policy: Option<&LoadedOrgPolicyPack>,
) -> Result<Option<ResolvedSandboxAdmission>, SandboxAdmissionError> {
    let requested_target = requested_target
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if requested_target.is_some_and(|target| target != crate::sandbox_policy::OCI_LOCAL_TARGET) {
        return Err(SandboxAdmissionError {
            kind: "sandbox_target_unavailable",
            requested_target: requested_target.map(str::to_string),
            resolved_target: None,
            canonical_policy_identity: None,
            restriction_overlay_identities: Vec::new(),
            effective_policy_identity: None,
            refusals: Vec::new(),
            supported_alternatives: vec![crate::sandbox_policy::OCI_LOCAL_TARGET.to_string()],
            message: format!(
                "sandbox target `{}` is not available; the first enforcing target is `{}`",
                requested_target.unwrap_or_default(),
                crate::sandbox_policy::OCI_LOCAL_TARGET
            ),
        });
    }
    let workflow_has_runtime_boundary = contract
        .execution
        .as_ref()
        .and_then(|execution| execution.runtime_boundary.as_ref())
        .is_some_and(|boundary| !boundary.is_empty())
        || contract
            .selected_workflow(workflow_name)
            .and_then(|(_, workflow)| workflow.runtime_boundary.as_ref())
            .is_some_and(|boundary| !boundary.is_empty())
        || contract
            .task_execution_closure_names(
                contract.selected_workflow_task_closure_names(workflow_name),
            )
            .iter()
            .map(String::as_str)
            .chain(contract.selected_attach_task_name_for(workflow_name))
            .any(|task_name| {
                contract
                    .tasks
                    .get(task_name)
                    .and_then(|task| task.runtime_boundary.as_ref())
                    .is_some_and(|boundary| !boundary.is_empty())
            });
    let policy_has_runtime_boundary = loaded_policy
        .and_then(|loaded| loaded.pack.policies.sandbox.as_ref())
        .is_some_and(|sandbox| sandbox.filesystem.is_some() || sandbox.network.is_some());
    if requested_target.is_none() && !workflow_has_runtime_boundary && !policy_has_runtime_boundary
    {
        return Ok(None);
    }
    let effect_policy_decision = sandbox_typed_effect_policy_decision(typed_effect_admission)?;
    let policy =
        crate::sandbox_policy::sandbox_policy_for_workflow(contract, workflow_name, overrides)
            .map_err(|message| SandboxAdmissionError {
                kind: "sandbox_policy_unavailable",
                requested_target: requested_target.map(str::to_string),
                resolved_target: None,
                canonical_policy_identity: None,
                restriction_overlay_identities: Vec::new(),
                effective_policy_identity: None,
                refusals: Vec::new(),
                supported_alternatives: Vec::new(),
                message,
            })?;
    resolve_sandbox_policy_admission(
        policy,
        effect_policy_decision,
        contract_path,
        overrides,
        agent,
        requested_target,
        loaded_policy,
    )
}

fn resolve_sandbox_policy_admission(
    policy: crate::sandbox_policy::SandboxPolicy,
    effect_policy_decision: Option<crate::effect_policy::EffectPolicyDecision>,
    contract_path: &Path,
    overrides: ExecutionOverrides,
    agent: bool,
    requested_target: Option<&str>,
    loaded_policy: Option<&LoadedOrgPolicyPack>,
) -> Result<Option<ResolvedSandboxAdmission>, SandboxAdmissionError> {
    let restriction_authority = crate::sandbox_policy::restriction_authority_from_loaded_policy(
        loaded_policy,
    )
    .map_err(|message| SandboxAdmissionError {
        kind: "sandbox_policy_authority_unavailable",
        requested_target: requested_target.map(str::to_string),
        resolved_target: Some(crate::sandbox_policy::OCI_LOCAL_TARGET.to_string()),
        canonical_policy_identity: Some(policy.identity.clone()),
        restriction_overlay_identities: Vec::new(),
        effective_policy_identity: None,
        refusals: Vec::new(),
        supported_alternatives: Vec::new(),
        message,
    })?;
    let overlays = crate::sandbox_policy::restriction_overlays_from_loaded_policy(loaded_policy)
        .map_err(|message| SandboxAdmissionError {
            kind: "sandbox_policy_authority_unavailable",
            requested_target: requested_target.map(str::to_string),
            resolved_target: Some(crate::sandbox_policy::OCI_LOCAL_TARGET.to_string()),
            canonical_policy_identity: Some(policy.identity.clone()),
            restriction_overlay_identities: Vec::new(),
            effective_policy_identity: None,
            refusals: Vec::new(),
            supported_alternatives: Vec::new(),
            message,
        })?;
    let effective =
        crate::sandbox_policy::effective_sandbox_policy(&policy, &overlays).map_err(|message| {
            SandboxAdmissionError {
                kind: "sandbox_policy_conflict",
                requested_target: requested_target.map(str::to_string),
                resolved_target: Some(crate::sandbox_policy::OCI_LOCAL_TARGET.to_string()),
                canonical_policy_identity: Some(policy.identity.clone()),
                restriction_overlay_identities: Vec::new(),
                effective_policy_identity: None,
                refusals: Vec::new(),
                supported_alternatives: Vec::new(),
                message,
            }
        })?;
    let has_authoritative_controls =
        crate::sandbox_policy::policy_has_authoritative_runtime_controls(&policy)
            || crate::sandbox_policy::effective_policy_has_authoritative_runtime_controls(
                &effective,
            );
    if !has_authoritative_controls {
        if requested_target.is_some() {
            return Err(SandboxAdmissionError {
                kind: "sandbox_policy_not_declared",
                requested_target: requested_target.map(str::to_string),
                resolved_target: None,
                canonical_policy_identity: Some(policy.identity),
                restriction_overlay_identities: effective.restriction_overlay_identities,
                effective_policy_identity: Some(effective.identity),
                refusals: Vec::new(),
                supported_alternatives: Vec::new(),
                message: String::from(
                    "the selected lane and loaded policy do not declare an authoritative runtime boundary; Ota will not convert provider defaults into policy",
                ),
            });
        }
        return Ok(None);
    }
    if !agent && requested_target.is_none() {
        return Ok(None);
    }
    let repo_root = contract_path.parent().unwrap_or_else(|| Path::new("."));
    let (evaluation, plan) = crate::sandbox_policy::evaluate_oci_local_application(
        &policy,
        &effective,
        restriction_authority.as_ref(),
        repo_root,
        overrides,
    )
    .map_err(|message| SandboxAdmissionError {
        kind: "sandbox_provider_evaluation_failed",
        requested_target: requested_target.map(str::to_string),
        resolved_target: Some(crate::sandbox_policy::OCI_LOCAL_TARGET.to_string()),
        canonical_policy_identity: Some(policy.identity.clone()),
        restriction_overlay_identities: effective.restriction_overlay_identities.clone(),
        effective_policy_identity: Some(effective.identity.clone()),
        refusals: Vec::new(),
        supported_alternatives: Vec::new(),
        message,
    })?;
    if !evaluation.admitted {
        return Err(SandboxAdmissionError {
            kind: "sandbox_policy_refused",
            requested_target: requested_target.map(str::to_string),
            resolved_target: Some(crate::sandbox_policy::OCI_LOCAL_TARGET.to_string()),
            canonical_policy_identity: Some(policy.identity.clone()),
            restriction_overlay_identities: effective.restriction_overlay_identities.clone(),
            effective_policy_identity: Some(effective.identity.clone()),
            refusals: evaluation.refusals.clone(),
            supported_alternatives: Vec::new(),
            message: evaluation
                .refusals
                .first()
                .map(|refusal| refusal.reason.clone())
                .unwrap_or_else(|| String::from("sandbox provider refused the selected policy")),
        });
    }
    Ok(Some(ResolvedSandboxAdmission {
        effect_policy_decision,
        policy,
        effective,
        evaluation,
        plan,
        resolution: if requested_target.is_some() {
            "explicit"
        } else {
            "automatic"
        },
    }))
}

fn render_sandbox_admission_command_output(
    command: &str,
    format: OutputFormat,
    contract_path: &Path,
    member: Option<&str>,
    task: Option<&str>,
    dry_run: bool,
    error: &SandboxAdmissionError,
) -> CommandOutput {
    match format {
        OutputFormat::Text => CommandOutput::failure(stylize_text_failure(
            &format!("ota {}", command.to_ascii_lowercase()),
            &format!(
                "{}\nWhere: {}\nNext: declare a compatible ephemeral container lane or remove the unsupported sandbox request",
                error.message,
                display_contract_target(&compact_contract_path(contract_path), member)
            ),
        )),
        OutputFormat::Json => CommandOutput::failure(to_json_value(json!({
            "ok": false,
            "command": command.to_ascii_lowercase(),
            "path": contract_path.display().to_string(),
            "member": member,
            "task": task,
            "dry_run": dry_run,
            "execution_started": false,
            "sandbox_admission": error,
        }))),
    }
}

#[allow(clippy::too_many_arguments)]
fn sandbox_admission_run_failure(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    overrides: ExecutionOverrides,
    show_receipt: bool,
    _agent: bool,
    _reason: Option<&str>,
    error: &SandboxAdmissionError,
) -> RunCommandFailure {
    let mut receipt = run_execution_receipt_with_shared(
        contract,
        contract_path,
        None,
        overrides,
        task_name,
        member,
        &[],
        &[],
        &[],
        &[],
        &[],
        None,
        &[],
        None,
        1,
        false,
        None,
        None,
        Some(String::from(
            "declare a compatible ephemeral container lane or remove the unsupported sandbox request",
        )),
    );
    receipt.blocked.push(format!(
        "OTA_SANDBOX_POLICY_REFUSED:{}:{}",
        error
            .refusals
            .first()
            .map(|refusal| refusal.segment_id.as_str())
            .unwrap_or(task_name),
        error.message
    ));
    refresh_execution_receipt_status(&mut receipt);
    let summary = render_execution_receipt_summary_block(&receipt, Some(task_name), "RUN SUMMARY");
    RunCommandFailure {
        message: stylize_text_failure("ota run", &error.message),
        summary: Some(summary),
        exit_code: 1,
        receipt: show_receipt.then(|| render_execution_receipt_text(&receipt)),
    }
}

#[allow(clippy::too_many_arguments)]
fn crossing_grant_run_failure(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    overrides: ExecutionOverrides,
    show_receipt: bool,
    _agent: bool,
    _reason: Option<&str>,
    grant: Option<&str>,
    error: &GrantAdmissionError,
) -> RunCommandFailure {
    let mut receipt = run_execution_receipt_with_shared(
        contract,
        contract_path,
        None,
        overrides,
        task_name,
        member,
        &[],
        &[],
        &[],
        &[],
        &[],
        None,
        &[],
        None,
        1,
        false,
        None,
        None,
        Some(String::from(
            "supply an exact live grant from the contract-bound authority, or select a closure that does not require a crossing",
        )),
    );
    receipt
        .blocked
        .push(format!("OTA_CROSSING_GRANT_REFUSED:{}", error.reason));
    receipt.refusal = Some(crossing_grant_refusal_record(
        contract, task_name, grant, error,
    ));
    refresh_execution_receipt_status(&mut receipt);
    let summary = render_execution_receipt_summary_block(&receipt, Some(task_name), "RUN SUMMARY");
    RunCommandFailure {
        message: stylize_text_failure(
            "ota run",
            &format!(
                "Crossing grant admission refused: {error}\nWhere: {}",
                display_contract_target(&compact_contract_path(contract_path), member)
            ),
        ),
        summary: Some(summary),
        exit_code: 1,
        receipt: show_receipt.then(|| render_execution_receipt_text(&receipt)),
    }
}

#[allow(clippy::too_many_arguments)]
fn crossing_grant_up_result(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    dry_run: bool,
    _agent: bool,
    _run_behavior_preference: UpRunBehaviorPreference,
    grant: Option<&str>,
    error: GrantAdmissionError,
) -> RepoUpResult {
    let finding = Finding {
        identity: Some(FindingIdentity {
            code: String::from("OTA_CROSSING_GRANT_REFUSED"),
            category: String::from("policy"),
            owner: String::from("agent_safety"),
        }),
        severity: FindingSeverity::Error,
        summary: String::from("Crossing grant admission refused"),
        why: error.to_string(),
        next: String::from(
            "supply an exact live grant from the contract-bound authority, or select a workflow closure that does not require a crossing",
        ),
    };
    let task_name = contract
        .selected_run_task_name_for(workflow_name)
        .map(str::to_string);
    let context = task_name
        .as_deref()
        .map(|task_name| {
            task_phase_execution_context(contract, contract_path, task_name, overrides, None)
        })
        .unwrap_or_else(native_phase_execution_context);
    let mut receipt = repo_execution_receipt_with_overrides(
        contract_path,
        contract,
        context,
        "BLOCKED",
        "preconditions",
        workflow_name,
        None,
        task_name.as_deref(),
        std::slice::from_ref(&finding),
        None,
        Some(finding.next.clone()),
        Some(overrides),
    );
    receipt.failure_origin = Some(format!("crossing_grant_{}", error.reason));
    receipt
        .blocked
        .push(format!("OTA_CROSSING_GRANT_REFUSED:{}", error.reason));
    receipt.refusal = Some(crossing_grant_refusal_record(
        contract,
        workflow_name.unwrap_or("default"),
        grant,
        &error,
    ));
    refresh_execution_receipt_status(&mut receipt);
    RepoUpResult {
        ok: false,
        status: "BLOCKED",
        phase: if dry_run { "preview" } else { "preconditions" },
        report: DoctorReport {
            ok: false,
            provisioning: None,
            adapter_bootstrap: None,
            execution_target: None,
            findings: vec![finding],
        },
        preview: None,
        governance_preflight: None,
        receipt,
        service: None,
        service_command: None,
        task: task_name,
        task_command: None,
        exit_code: None,
        stdout: String::new(),
        stderr: String::new(),
    }
}

fn crossing_grant_refusal_record(
    contract: &Contract,
    lane_name: &str,
    grant: Option<&str>,
    error: &GrantAdmissionError,
) -> crate::output::GovernanceRefusalRecord {
    crate::output::GovernanceRefusalRecord {
        reason_family: error.reason.to_string(),
        boundary_family: String::from("crossing_grant_authority"),
        closure_status: String::from("admission_refused"),
        requested_task: lane_name.to_string(),
        blocked_task: lane_name.to_string(),
        closure_path: vec![lane_name.to_string()],
        evidence_class: String::from("runner_evaluated"),
        authority_source: Some(
            error
                .authority_source
                .unwrap_or("prebound_file")
                .to_string(),
        ),
        authority_id: contract
            .governance
            .crossing_authority
            .as_ref()
            .map(|authority| authority.authority_id.clone()),
        requested_grant_id: grant.map(str::to_string),
        scope_identity: error
            .semantic_scope
            .as_ref()
            .map(|scope| scope.identity.clone()),
        contract_identity: error
            .semantic_scope
            .as_ref()
            .map(|scope| scope.contract_identity.clone()),
        scope_boundary_family: error
            .semantic_scope
            .as_ref()
            .map(|scope| scope.boundary_family.clone()),
        scope_classification: error
            .semantic_scope
            .as_ref()
            .map(|scope| scope.classification.clone()),
        evaluation_details: Some(error.public_details()),
        execution_started: Some(false),
    }
}

