// Capture declared, lockfile-strict hydration inputs as the receipt is issued. Receipt comparison
// must use these stored identities rather than re-reading the repository later.
#[cfg(test)]
fn receipt_evaluated_inputs(
    contract: &Contract,
    contract_path: &Path,
    task_names: impl IntoIterator<Item = String>,
    overrides: ExecutionOverrides,
) -> Vec<ExecutionReceiptEvaluatedInput> {
    let loaded_policy = load_org_policy_pack_auto_details(contract_path)
        .ok()
        .flatten();
    receipt_evaluated_inputs_with_policy_snapshot(
        contract,
        contract_path,
        task_names,
        overrides,
        Some(DoctorPolicySnapshot {
            loaded: loaded_policy.as_ref(),
            load_error: None,
        }),
    )
}

fn receipt_evaluated_inputs_with_policy_snapshot(
    contract: &Contract,
    contract_path: &Path,
    task_names: impl IntoIterator<Item = String>,
    overrides: ExecutionOverrides,
    policy_snapshot: Option<DoctorPolicySnapshot<'_>>,
) -> Vec<ExecutionReceiptEvaluatedInput> {
    let task_names = task_names.into_iter().collect::<Vec<_>>();
    let root = contract_path.parent().unwrap_or_else(|| Path::new("."));
    let mut inputs = BTreeMap::new();
    collect_receipt_source_identity_input(root, &mut inputs);
    collect_receipt_policy_ruleset_identity_input(policy_snapshot, root, &mut inputs);
    collect_receipt_declared_env_source_inputs(contract, contract_path, &task_names, &mut inputs);
    for task_name in task_names {
        let Some(task) = contract.tasks.get(&task_name) else {
            continue;
        };
        let backend = effective_task_execution(contract, task_name.as_str(), overrides).backend;
        if let Some(prepare) = task.prepare.as_ref() {
            collect_receipt_hydration_inputs(prepare, root, &mut inputs);
        }
        collect_receipt_compose_image_inputs(task, root, backend, &mut inputs);
        collect_receipt_generated_artifact_inputs(
            contract,
            root,
            task_name.as_str(),
            task,
            &mut inputs,
        );
    }
    inputs.into_values().collect()
}

// Clean git HEAD is the first honest source-identity carrier. Dirty trees and non-git directories
// remain outside the replay-grade claim rather than pretending HEAD alone pinned the source.
fn collect_receipt_source_identity_input(
    root: &Path,
    inputs: &mut BTreeMap<String, ExecutionReceiptEvaluatedInput>,
) {
    let Ok(head) = git_head_identity(root) else {
        return;
    };
    inputs.insert(
        String::from("source:git_head"),
        ExecutionReceiptEvaluatedInput {
            id: String::from("source:git_head"),
            kind: String::from("source_identity"),
            input_class: ReplayInputClass::SourceIdentity,
            identity: head,
            expected_identity: None,
            execution_started: None,
            hydration_provenance: None,
            artifact_lineage: None,
        },
    );
}

fn git_head_identity(root: &Path) -> Result<String, String> {
    git_head_identity_excluding(root, &[])
}

/// Computes one clean Git identity while excluding the generated baseline outputs that an
/// authorized producer is expected to update. It never excludes ordinary source changes.
fn git_head_identity_excluding(root: &Path, excluded_paths: &[String]) -> Result<String, String> {
    let exclusion_patterns = excluded_paths
        .iter()
        .map(|path| format!(":(exclude,literal){path}"))
        .collect::<Vec<_>>();
    let mut status_args = vec![
        "status",
        "--porcelain",
        "--untracked-files=all",
        "--",
        ".",
        ":(exclude,literal).ota",
    ];
    status_args.extend(exclusion_patterns.iter().map(String::as_str));
    let status = run_git_command(
        // `.ota` is Ota-owned runtime state. Declared baseline outputs are the only producer
        // mutations that do not invalidate source identity; all other source changes stay dirty.
        &status_args,
        Some(root),
        RepoExecutionMode::Capture,
    )
    .map_err(|error| error.to_string())?;
    if status.exit_code != 0 {
        return Err(status.stderr.trim().to_string());
    }
    if !status.stdout.trim().is_empty() {
        return Err(String::from("working tree is dirty"));
    }
    let head = run_git_command(
        &["rev-parse", "HEAD"],
        Some(root),
        RepoExecutionMode::Capture,
    )
    .map_err(|error| error.to_string())?;
    if head.exit_code != 0 {
        return Err(head.stderr.trim().to_string());
    }
    let identity = head.stdout.trim();
    if identity.is_empty() {
        return Err(String::from("HEAD is empty"));
    }
    Ok(format!("git:{identity}"))
}

// A loaded org policy pack is part of execution truth. When it changes, replay should report
// named policy/ruleset drift instead of leaving governance movement ambient.
fn collect_receipt_policy_ruleset_identity_input(
    policy_snapshot: Option<DoctorPolicySnapshot<'_>>,
    root: &Path,
    inputs: &mut BTreeMap<String, ExecutionReceiptEvaluatedInput>,
) {
    let Some(loaded_policy) = policy_snapshot.and_then(|snapshot| snapshot.loaded) else {
        return;
    };
    let policy_identity = loaded_policy
        .source_identity
        .clone()
        .or_else(|| semantic_contract_identity(&loaded_policy.pack).ok());
    let Some(policy_identity) = policy_identity else {
        return;
    };
    let policy_path = loaded_policy.path.as_path();
    let display_path = policy_path
        .strip_prefix(root)
        .ok()
        .and_then(|path| path.to_str())
        .map(compact_path_separator_style)
        .unwrap_or_else(|| native_path_display_text(&normalized_display_path(&policy_path)));
    inputs.insert(
        String::from("policy:org_ruleset"),
        ExecutionReceiptEvaluatedInput {
            id: String::from("policy:org_ruleset"),
            kind: String::from("policy_ruleset_identity"),
            input_class: ReplayInputClass::PolicyRulesetIdentity,
            identity: policy_identity,
            expected_identity: None,
            execution_started: None,
            hydration_provenance: None,
            artifact_lineage: Some(crate::output::ExecutionReceiptArtifactLineage {
                producer: String::from("org_policy_pack"),
                paths: vec![display_path],
                inputs: Vec::new(),
                replay_authority: None,
            }),
        },
    );
}

// Declared env source files are replay-grade only when the selected lane actually resolved env
// from them. Matching source-file identity clears that named env-source class, but does not claim
// process env, policy env, or undeclared ambient environment held still.
fn collect_receipt_declared_env_source_inputs(
    contract: &Contract,
    contract_path: &Path,
    task_names: &[String],
    inputs: &mut BTreeMap<String, ExecutionReceiptEvaluatedInput>,
) {
    let root = contract_path.parent().unwrap_or_else(|| Path::new("."));
    let policy_env = load_policy_env_overlay(contract_path).ok();
    let declared_sources = load_declared_env_sources(contract, contract_path);
    let mut used_labels = BTreeSet::new();

    for task_name in task_names {
        let Ok(resolved) = resolve_task_env_details_for_task_with_policy(
            contract,
            contract_path,
            task_name,
            None,
            policy_env.as_ref().map(|overlay| &overlay.values),
        ) else {
            continue;
        };
        for resolved in resolved.values() {
            if let EnvResolutionSource::Source(label) = &resolved.source {
                used_labels.insert(label.clone());
            }
        }
    }

    for source in &declared_sources {
        let label = source.label();
        if !used_labels.contains(&label) || source.status != DeclaredEnvSourceStatus::Loaded {
            continue;
        }
        let Ok(bytes) = fs::read(root.join(&source.path)) else {
            continue;
        };
        let id = format!("env_source:{label}");
        inputs.insert(
            id.clone(),
            ExecutionReceiptEvaluatedInput {
                id,
                kind: String::from("env_source_identity"),
                input_class: ReplayInputClass::DeclaredEnvSourceIdentity,
                identity: contract_snapshot_hash(&bytes),
                expected_identity: None,
                execution_started: None,
                hydration_provenance: None,
                artifact_lineage: None,
            },
        );
    }
}

#[derive(Debug, Clone, Serialize)]
struct ReplayInputIdentityMismatch {
    kind: &'static str,
    task: String,
    input_id: String,
    path: String,
    input_kind: String,
    input_class: ReplayInputClass,
    expected_identity: String,
    observed_identity: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    identity_error: Option<String>,
    execution_started: bool,
}

impl ReplayInputIdentityMismatch {
    fn message(&self) -> String {
        if let Some(error) = self.identity_error.as_deref() {
            return format!(
                "{}: declared replay input `{}` for task `{}` expected `{}` but could not be read before execution: {error}",
                self.kind, self.input_id, self.task, self.expected_identity
            );
        }
        format!(
            "{}: declared replay input `{}` for task `{}` expected `{}` but observed `{}` before execution",
            self.kind, self.input_id, self.task, self.expected_identity, self.observed_identity
        )
    }
}

#[derive(Debug)]
enum ReplayInputCaptureError {
    Capture(String),
    IdentityMismatch(ReplayInputIdentityMismatch),
}

impl std::fmt::Display for ReplayInputCaptureError {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::Capture(message) => formatter.write_str(message),
            Self::IdentityMismatch(mismatch) => formatter.write_str(&mismatch.message()),
        }
    }
}

fn capture_replay_inputs_before_execution(
    contract: &Contract,
    contract_path: &Path,
    roots: impl IntoIterator<Item = String>,
) -> Result<Vec<ExecutionReceiptEvaluatedInput>, ReplayInputCaptureError> {
    let roots = roots.into_iter().collect::<Vec<_>>();
    let root = contract_path.parent().unwrap_or_else(|| Path::new("."));
    let observations = observe_replay_inputs(contract, root, roots.clone());
    capture_replay_inputs_from_observations(contract, contract_path, roots, &observations)
}

fn capture_replay_inputs_from_observations(
    contract: &Contract,
    contract_path: &Path,
    roots: impl IntoIterator<Item = String>,
    observations: &ReplayInputPolicyObservations,
) -> Result<Vec<ExecutionReceiptEvaluatedInput>, ReplayInputCaptureError> {
    let mut captured = BTreeMap::new();
    for task_name in contract.task_execution_closure_names(roots) {
        let Some(task) = contract.tasks.get(&task_name) else {
            continue;
        };
        for input in &task.replay_inputs {
            let path = input.path.trim();
            let (kind, input_class) = replay_input_capture_surface(input.kind);
            let observation = observations
                .get(&replay_input_observation_key(&task_name, &input.id))
                .cloned()
                .unwrap_or_else(
                    || crate::replay_input_policy::ReplayInputPolicyInputRecord {
                        task: task_name.clone(),
                        id: input.id.clone(),
                        path: input.path.clone(),
                        expected_identity: input.expected_identity.clone(),
                        observed_identity: None,
                        status: String::from("observation_unavailable"),
                        error: Some(String::from(
                            "replay input was not captured by the command preflight",
                        )),
                    },
                );
            let observed = observation.observed_identity.clone().ok_or_else(|| {
                observation
                    .error
                    .clone()
                    .unwrap_or_else(|| String::from("replay input identity was not observed"))
            });
            let id = format!("replay_input:{task_name}:{}", input.id.trim());
            if let Some(evaluation) = evaluate_replay_input_identity(input, observed.clone()) {
                match evaluation {
                    ReplayInputIdentityEvaluation::Match { .. } => {}
                    ReplayInputIdentityEvaluation::Mismatch {
                        expected_identity,
                        observed_identity,
                    } => {
                        return Err(ReplayInputCaptureError::IdentityMismatch(
                            ReplayInputIdentityMismatch {
                                kind: "replay_input_identity_mismatch",
                                task: task_name.clone(),
                                input_id: input.id.trim().to_string(),
                                path: path.to_string(),
                                input_kind: kind.to_string(),
                                input_class,
                                expected_identity,
                                observed_identity,
                                identity_error: None,
                                execution_started: false,
                            },
                        ));
                    }
                    ReplayInputIdentityEvaluation::Missing {
                        expected_identity,
                        error,
                    } => {
                        return Err(ReplayInputCaptureError::IdentityMismatch(
                            ReplayInputIdentityMismatch {
                                kind: "replay_input_identity_missing",
                                task: task_name.clone(),
                                input_id: input.id.trim().to_string(),
                                path: path.to_string(),
                                input_kind: kind.to_string(),
                                input_class,
                                expected_identity,
                                observed_identity: String::from("unavailable"),
                                identity_error: Some(error),
                                execution_started: false,
                            },
                        ));
                    }
                }
            }
            let identity = observed.map_err(|error| {
                ReplayInputCaptureError::Capture(format!(
                    "declared replay input `{}` for task `{task_name}` could not be captured before execution: {error}",
                    input.id
                ))
            })?;
            captured.insert(
                id.clone(),
                ExecutionReceiptEvaluatedInput {
                    id,
                    kind: kind.to_string(),
                    input_class,
                    identity,
                    expected_identity: input.expected_identity.clone(),
                    execution_started: None,
                    hydration_provenance: None,
                    artifact_lineage: None,
                },
            );
        }
        if let Some(crate::schema::TaskPrepareSpec::DependencyHydration(hydration)) =
            task.prepare.as_ref()
        {
            capture_uv_local_project_inputs_before_execution(
                contract_path,
                task_name.as_str(),
                &hydration.source,
            )?;
        }
    }
    Ok(captured.into_values().collect())
}

fn capture_uv_local_project_inputs_before_execution(
    contract_path: &Path,
    task_name: &str,
    source: &crate::schema::TaskDependencyHydrationSourceSpec,
) -> Result<(), ReplayInputCaptureError> {
    let crate::schema::TaskDependencyHydrationSourceSpec::Uv(source) = source else {
        return Ok(());
    };
    let Some(resolved) =
        crate::hydration_provenance::resolve_uv_local_project_identity(contract_path, source)
    else {
        return Ok(());
    };
    if let Some(error) = resolved.resolution_error {
        return Err(ReplayInputCaptureError::Capture(format!(
            "declared uv local project inputs for task `{task_name}` could not be captured before execution: {error}",
        )));
    }
    Ok(())
}

fn replay_input_identity_mismatch_finding(mismatch: &ReplayInputIdentityMismatch) -> Finding {
    let missing = mismatch.identity_error.is_some();
    Finding {
        identity: Some(FindingIdentity {
            code: String::from(if missing {
                "OTA_REPLAY_INPUT_IDENTITY_MISSING"
            } else {
                "OTA_REPLAY_INPUT_IDENTITY_MISMATCH"
            }),
            category: String::from("replay"),
            owner: String::from("execution"),
        }),
        severity: FindingSeverity::Error,
        summary: format!(
            "Replay input identity {}: {}",
            if missing { "missing" } else { "mismatch" },
            mismatch.input_id
        ),
        why: mismatch.message(),
        next: format!(
            "restore `{}` to the declared identity or update `tasks.{}.replay_inputs` through reviewed contract change before rerunning",
            mismatch.path, mismatch.task
        ),
    }
}

fn replay_input_identity_mismatch_evaluated_input(
    mismatch: &ReplayInputIdentityMismatch,
) -> ExecutionReceiptEvaluatedInput {
    ExecutionReceiptEvaluatedInput {
        id: format!("replay_input:{}:{}", mismatch.task, mismatch.input_id),
        kind: mismatch.input_kind.clone(),
        input_class: mismatch.input_class,
        identity: mismatch.observed_identity.clone(),
        expected_identity: Some(mismatch.expected_identity.clone()),
        execution_started: Some(false),
        hydration_provenance: None,
        artifact_lineage: None,
    }
}

fn replay_input_identity_run_failure(
    contract: &Contract,
    contract_path: &Path,
    task_name: &str,
    member: Option<&str>,
    overrides: ExecutionOverrides,
    show_receipt: bool,
    mismatch: ReplayInputIdentityMismatch,
    replay_input_policy: Option<ReplayInputPolicyEvaluation>,
) -> RunCommandFailure {
    let finding = replay_input_identity_mismatch_finding(&mismatch);
    let mut receipt = repo_execution_receipt_with_overrides(
        contract_path,
        contract,
        task_phase_execution_context(
            contract,
            contract_path,
            task_name,
            overrides,
            member.map(str::to_string),
        ),
        "BLOCKED",
        "preconditions",
        None,
        member,
        Some(task_name),
        std::slice::from_ref(&finding),
        None,
        Some(finding.next.clone()),
        Some(overrides),
    );
    receipt.evaluated_inputs = vec![replay_input_identity_mismatch_evaluated_input(&mismatch)];
    receipt.replay_input_policy = replay_input_policy;
    receipt.failure_origin = Some(mismatch.kind.to_string());
    receipt.blocked = vec![mismatch.kind.to_string()];
    refresh_execution_receipt_status(&mut receipt);
    RunCommandFailure {
        message: stylize_text_failure("ota run", &mismatch.message()),
        summary: Some(render_execution_receipt_summary_block(
            &receipt,
            Some(task_name),
            "RUN SUMMARY",
        )),
        exit_code: 1,
        receipt: show_receipt.then(|| render_execution_receipt_text(&receipt)),
    }
}

