fn up_replay_input_identity_mismatch_result(
    contract: &Contract,
    resolved_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    mismatch: ReplayInputIdentityMismatch,
) -> RepoUpResult {
    let finding = replay_input_identity_mismatch_finding(&mismatch);
    let mut receipt = repo_execution_receipt_with_overrides(
        resolved_path,
        contract,
        task_phase_execution_context(
            contract,
            resolved_path,
            mismatch.task.as_str(),
            overrides,
            None,
        ),
        "BLOCKED",
        "preconditions",
        workflow_name,
        None,
        Some(mismatch.task.as_str()),
        std::slice::from_ref(&finding),
        None,
        Some(finding.next.clone()),
        Some(overrides),
    );
    receipt.evaluated_inputs = vec![replay_input_identity_mismatch_evaluated_input(&mismatch)];
    receipt.failure_origin = Some(mismatch.kind.to_string());
    receipt.blocked = vec![mismatch.kind.to_string()];
    refresh_execution_receipt_status(&mut receipt);
    RepoUpResult {
        ok: false,
        status: "BLOCKED",
        phase: "preconditions",
        report: DoctorReport {
            ok: false,
            provisioning: None,
            adapter_bootstrap: None,
            execution_target: None,
            findings: vec![finding],
        },
        preview: None,
        governance_preflight: None,
        receipt,
        service: None,
        service_command: None,
        task: Some(mismatch.task),
        task_command: None,
        exit_code: None,
        stdout: String::new(),
        stderr: String::new(),
    }
}

fn replay_input_class_closes_hermetic_replay(class: ReplayInputClass) -> bool {
    matches!(
        class,
        ReplayInputClass::DeclaredDependencyResolution
            | ReplayInputClass::SelectedRuntimeArtifact
            | ReplayInputClass::ExecutionPresentationProfile
            | ReplayInputClass::PromotedReplayBaseline
    )
}

fn replay_hidden_input_candidates(
    report: &RepoReceiptDiffReport,
    failure_kind: Option<UpReplayFailureKind>,
) -> Vec<String> {
    if failure_kind != Some(UpReplayFailureKind::HiddenInputSuspicion) {
        return Vec::new();
    }
    let artifacts = &report.summary.comparison.artifact_trust;
    let has_class = |target: ReplayInputClass| {
        artifacts
            .iter()
            .any(|artifact| artifact.input_classes.contains(&target))
    };
    let has_dependency_resolution = has_class(ReplayInputClass::DeclaredDependencyResolution);
    let has_runtime_identity = has_class(ReplayInputClass::SelectedRuntimeVersion)
        || has_class(ReplayInputClass::SelectedRuntimeArtifact);
    let has_presentation_profile = has_class(ReplayInputClass::ExecutionPresentationProfile);
    let has_env_identity = has_class(ReplayInputClass::DeclaredEnvSourceIdentity);
    let has_comparator = has_class(ReplayInputClass::ComparatorSemantics);
    let has_static_replay_input = has_class(ReplayInputClass::DeclaredReplayInput);
    let has_witnessed_query_output = !report
        .baseline
        .witnessed_observations
        .query_traces
        .is_empty()
        || !report
            .current
            .witnessed_observations
            .query_traces
            .is_empty();

    let mut candidates = Vec::new();
    if !has_dependency_resolution {
        candidates.push(String::from("dependency_resolution"));
    }
    if !has_runtime_identity {
        candidates.push(String::from("runtime_or_machine"));
    }
    if !has_presentation_profile
        && (has_comparator || has_static_replay_input || has_witnessed_query_output)
    {
        candidates.push(String::from("execution_presentation"));
    }
    if !has_env_identity {
        candidates.push(String::from("ambient_environment"));
    }
    candidates.push(String::from("live_external_state"));
    candidates
}

fn replay_input_capture_surface(
    kind: crate::schema::TaskReplayInputKind,
) -> (&'static str, ReplayInputClass) {
    match kind {
        crate::schema::TaskReplayInputKind::StaticFile => {
            ("static_file", ReplayInputClass::DeclaredReplayInput)
        }
        crate::schema::TaskReplayInputKind::PresentationProfile => (
            "presentation_profile",
            ReplayInputClass::ExecutionPresentationProfile,
        ),
        crate::schema::TaskReplayInputKind::ComparatorProfile => {
            ("comparator_profile", ReplayInputClass::ComparatorSemantics)
        }
    }
}

// Query traces are attested observations from a recorded run. Capture their immutable source
// before execution, but keep them separate from evaluated decision inputs in the receipt.
fn capture_witnessed_observations_before_execution(
    contract: &Contract,
    contract_path: &Path,
    roots: impl IntoIterator<Item = String>,
) -> Result<ExecutionReceiptWitnessedObservations, String> {
    let root = contract_path.parent().unwrap_or_else(|| Path::new("."));
    let mut query_traces = BTreeMap::new();
    for task_name in contract.task_dependency_closure_names(roots) {
        let Some(task) = contract.tasks.get(&task_name) else {
            continue;
        };
        for trace in &task.witnessed_observations.query_traces {
            let source_path = trace.path.trim();
            let source_bytes = fs::read(root.join(source_path)).map_err(|error| {
                format!(
                    "declared witnessed query trace `{}` for task `{task_name}` could not be captured before execution: {error}",
                    trace.id
                )
            })?;
            let source_identity = contract_snapshot_hash(&source_bytes);
            let content = String::from_utf8(source_bytes).map_err(|error| {
                format!(
                    "declared witnessed query trace `{}` for task `{task_name}` must be valid UTF-8: {error}",
                    trace.id
                )
            })?;
            let mut records = Vec::new();
            for (line_index, line) in content.lines().enumerate() {
                if line.trim().is_empty() {
                    continue;
                }
                let value: serde_json::Value = serde_json::from_str(line).map_err(|error| {
                    format!(
                        "witnessed query trace `{}` for task `{task_name}` has invalid JSON on line {}: {error}",
                        trace.id,
                        line_index + 1
                    )
                })?;
                let subject = value.get("id").and_then(serde_json::Value::as_str).filter(|value| !value.trim().is_empty()).ok_or_else(|| {
                    format!("witnessed query trace `{}` for task `{task_name}` needs a non-empty string `id` on line {}", trace.id, line_index + 1)
                })?;
                let run = value.get("run").and_then(serde_json::Value::as_u64).ok_or_else(|| {
                    format!("witnessed query trace `{}` for task `{task_name}` needs a non-negative integer `run` on line {}", trace.id, line_index + 1)
                })?;
                let sql = value.get("sql").and_then(serde_json::Value::as_str).filter(|value| !value.trim().is_empty()).ok_or_else(|| {
                    format!("witnessed query trace `{}` for task `{task_name}` needs a non-empty string `sql` on line {}", trace.id, line_index + 1)
                })?;
                // `run` locates the observation. Identity must represent the query alone or a
                // stable query repeated across K runs would be falsely classified as divergent.
                let identity = contract_snapshot_hash(
                    &serde_json::to_vec(&(subject, sql))
                        .expect("query trace identity must serialize"),
                );
                records.push(ExecutionReceiptQueryTraceRecord {
                    subject: subject.to_string(),
                    run,
                    identity,
                });
            }
            records.sort_by(|left, right| {
                left.subject
                    .cmp(&right.subject)
                    .then(left.run.cmp(&right.run))
                    .then(left.identity.cmp(&right.identity))
            });
            let mut identities_by_subject = BTreeMap::<String, BTreeSet<String>>::new();
            for record in &records {
                identities_by_subject
                    .entry(record.subject.clone())
                    .or_default()
                    .insert(record.identity.clone());
            }
            let divergent_subjects = identities_by_subject
                .into_iter()
                .filter_map(|(subject, identities)| {
                    (identities.len() > 1).then_some(ExecutionReceiptQueryTraceDivergence {
                        subject,
                        distinct_identities: identities.len(),
                    })
                })
                .collect::<Vec<_>>();
            let id = format!("query_trace:{task_name}:{}", trace.id.trim());
            query_traces.insert(
                id.clone(),
                ExecutionReceiptQueryTraceObservation {
                    id,
                    source_path: source_path.to_string(),
                    source_identity,
                    evidence_class: ExecutionEvidenceClass::Attested,
                    summary: ExecutionReceiptQueryTraceSummary {
                        subjects: records
                            .iter()
                            .map(|record| record.subject.as_str())
                            .collect::<BTreeSet<_>>()
                            .len(),
                        records: records.len(),
                        divergent_subjects,
                    },
                    records,
                },
            );
        }
    }
    Ok(ExecutionReceiptWitnessedObservations {
        query_traces: query_traces.into_values().collect(),
        replay_baseline_recordings: Vec::new(),
        sandbox_application: None,
    })
}

// Resolve source posture before the selected lane runs so the receipt records what Ota actually
// used instead of reconstructing feed truth from a later filesystem read.
fn capture_hydration_provenance_before_execution(
    contract: &Contract,
    contract_path: &Path,
    roots: impl IntoIterator<Item = String>,
) -> Vec<ExecutionReceiptEvaluatedInput> {
    let mut provenance = Vec::new();
    for task_name in contract.task_dependency_closure_names(roots) {
        let Some(task) = contract.tasks.get(&task_name) else {
            continue;
        };
        let Some(prepare) = task.prepare.as_ref() else {
            continue;
        };
        collect_hydration_provenance_for_prepare(
            &mut provenance,
            &task_name,
            prepare,
            contract_path,
        );
    }
    provenance.sort_by(|left, right| left.id.cmp(&right.id));
    provenance.dedup_by(|left, right| left.id == right.id);
    provenance
}

fn collect_hydration_provenance_for_prepare(
    records: &mut Vec<ExecutionReceiptEvaluatedInput>,
    task_name: &str,
    prepare: &crate::schema::TaskPrepareSpec,
    contract_path: &Path,
) {
    match prepare {
        crate::schema::TaskPrepareSpec::DependencyHydration(spec) => {
            collect_hydration_provenance_for_hydration(records, task_name, spec, contract_path);
        }
        crate::schema::TaskPrepareSpec::Sequence(sequence) => {
            for step in &sequence.steps {
                collect_hydration_provenance_for_sequence_step(
                    records,
                    task_name,
                    step,
                    contract_path,
                );
            }
        }
        crate::schema::TaskPrepareSpec::ToolBootstrap(_) => {}
    }
}

fn collect_hydration_provenance_for_sequence_step(
    records: &mut Vec<ExecutionReceiptEvaluatedInput>,
    task_name: &str,
    step: &crate::schema::TaskPrepareSequenceStepSpec,
    contract_path: &Path,
) {
    match step {
        crate::schema::TaskPrepareSequenceStepSpec::DependencyHydration(spec) => {
            collect_hydration_provenance_for_hydration(records, task_name, spec, contract_path);
        }
        crate::schema::TaskPrepareSequenceStepSpec::Sequence(sequence) => {
            for nested in &sequence.steps {
                collect_hydration_provenance_for_sequence_step(
                    records,
                    task_name,
                    nested,
                    contract_path,
                );
            }
        }
        _ => {}
    }
}

fn collect_hydration_provenance_for_hydration(
    records: &mut Vec<ExecutionReceiptEvaluatedInput>,
    task_name: &str,
    hydration: &crate::schema::TaskDependencyHydrationPrepareSpec,
    contract_path: &Path,
) {
    let (source_kind, declared, resolved, local_project) = match &hydration.source {
        crate::schema::TaskDependencyHydrationSourceSpec::DotnetRestore(source) => (
            "dotnet_restore",
            ExecutionReceiptHydrationSourcePosture {
                source_posture: source.source_posture().to_string(),
                config_file: source.config_file.clone(),
                sources: source.sources.clone(),
                offline: false,
                source_identities: Vec::new(),
                resolution: None,
                resolution_error: None,
            },
            receipt_hydration_source_posture(resolved_dotnet_hydration_provenance(
                contract_path,
                source,
            )),
            None,
        ),
        crate::schema::TaskDependencyHydrationSourceSpec::Uv(source) => (
            "uv",
            ExecutionReceiptHydrationSourcePosture {
                source_posture: source.source_posture().to_string(),
                config_file: None,
                sources: source.declared_sources(),
                offline: source.offline,
                source_identities: Vec::new(),
                resolution: None,
                resolution_error: None,
            },
            receipt_hydration_source_posture(resolved_uv_hydration_provenance(source)),
            receipt_uv_local_project_provenance(contract_path, source),
        ),
        _ => return,
    };
    let provenance = ExecutionReceiptHydrationProvenance {
        task: task_name.to_string(),
        source_kind: String::from(source_kind),
        declared,
        resolved,
        local_project,
    };
    let identity = contract_snapshot_hash(
        &serde_json::to_vec(&provenance)
            .expect("hydration provenance must serialize for receipt identity"),
    );
    records.push(ExecutionReceiptEvaluatedInput {
        id: format!("hydration:{task_name}:{source_kind}:{identity}"),
        kind: String::from("hydration_provenance"),
        input_class: ReplayInputClass::DeclaredDependencyResolution,
        identity,
        expected_identity: None,
        execution_started: None,
        hydration_provenance: Some(provenance),
        artifact_lineage: None,
    });
}

fn receipt_uv_local_project_provenance(
    contract_path: &Path,
    source: &crate::schema::TaskUvHydrationSourceSpec,
) -> Option<crate::output::ExecutionReceiptUvLocalProjectProvenance> {
    let resolved =
        crate::hydration_provenance::resolve_uv_local_project_identity(contract_path, source)?;
    Some(crate::output::ExecutionReceiptUvLocalProjectProvenance {
        path: resolved.path,
        editable: resolved.editable,
        extras: resolved.extras,
        groups: resolved.groups,
        manifest_path: resolved.manifest_path,
        manifest_identity: resolved.manifest_identity,
        source_identity: resolved.source_identity,
        source_identity_error: resolved.source_identity_error,
        lockfile_path: resolved.lockfile_path,
        lockfile_identity: resolved.lockfile_identity,
        resolution: String::from(resolved.resolution),
        resolution_error: resolved.resolution_error,
    })
}

fn receipt_hydration_source_posture(
    summary: WorkspaceTaskHydrationProvenanceSummary,
) -> ExecutionReceiptHydrationSourcePosture {
    ExecutionReceiptHydrationSourcePosture {
        source_posture: summary.source_posture.to_string(),
        config_file: summary.config_file,
        sources: summary.sources,
        offline: summary.offline,
        source_identities: summary
            .source_identities
            .into_iter()
            .map(|source| ExecutionReceiptHydrationSourceIdentity {
                name: source.name,
                url: source.url,
            })
            .collect(),
        resolution: summary.resolution,
        resolution_error: summary.resolution_error,
    }
}

fn replay_input_policy_refusal_finding(evaluation: &ReplayInputPolicyEvaluation) -> Finding {
    if let Some(selector) = evaluation.unknown_selectors.first() {
        return Finding::identified(
            "OTA_POLICY_REPLAY_INPUT_SELECTOR_UNKNOWN",
            "policy",
            "org_policy",
            FindingSeverity::Error,
            format!(
                "Replay-input policy references unknown {} `{}`",
                selector.subject.kind, selector.subject.name
            ),
            format!(
                "active policy contains rule `{}`, but the selected contract does not declare that {}",
                selector.identity, selector.subject.kind
            ),
            format!(
                "correct or remove `{}` in the active policy before governed execution",
                selector.identity
            ),
        );
    }
    let code = if evaluation.decision == "deny" {
        "OTA_REPLAY_INPUT_POLICY_DENIED"
    } else {
        "OTA_REPLAY_INPUT_POLICY_REVIEW_REQUIRED"
    };
    Finding::identified(
        code,
        "policy",
        "org_policy",
        FindingSeverity::Error,
        format!(
            "Replay-input identity policy {} selected {} `{}`",
            if evaluation.decision == "deny" {
                "denies"
            } else {
                "requires review for"
            },
            evaluation.subject.kind,
            evaluation.subject.name
        ),
        format!(
            "policy coverage is `{}` with decision `{}`",
            evaluation.coverage, evaluation.decision
        ),
        String::from(
            "declare and verify every required replay input identity, then rerun `ota doctor`",
        ),
    )
}

fn replay_input_policy_unavailable_finding(error: &str) -> Finding {
    Finding::identified(
        "OTA_REPLAY_INPUT_POLICY_UNAVAILABLE",
        "policy",
        "org_policy",
        FindingSeverity::Error,
        String::from("Replay-input policy could not be loaded"),
        format!(
            "Ota cannot establish replay-input admission because the active policy source failed to load: {error}"
        ),
        String::from(
            "repair or remove the invalid active policy source, then rerun `ota doctor` before execution",
        ),
    )
}

fn up_replay_input_policy_refusal_result(
    contract: &Contract,
    resolved_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    evaluation: ReplayInputPolicyEvaluation,
) -> RepoUpResult {
    let finding = replay_input_policy_refusal_finding(&evaluation);
    let task_name = contract
        .selected_run_task_name_for(workflow_name)
        .map(str::to_string)
        .or_else(|| (evaluation.subject.kind == "task").then(|| evaluation.subject.name.clone()));
    let context = task_name
        .as_deref()
        .map(|task_name| {
            task_phase_execution_context(contract, resolved_path, task_name, overrides, None)
        })
        .unwrap_or_else(native_phase_execution_context);
    let mut receipt = repo_execution_receipt_with_overrides(
        resolved_path,
        contract,
        context,
        "BLOCKED",
        "preconditions",
        workflow_name,
        None,
        task_name.as_deref(),
        std::slice::from_ref(&finding),
        None,
        Some(finding.next.clone()),
        Some(overrides),
    );
    receipt.failure_origin = Some(format!("replay_input_policy_{}", evaluation.decision));
    receipt.blocked = vec![format!("replay_input_policy_{}", evaluation.decision)];
    receipt.replay_input_policy = Some(evaluation);
    refresh_execution_receipt_status(&mut receipt);
    RepoUpResult {
        ok: false,
        status: "BLOCKED",
        phase: "preconditions",
        report: DoctorReport {
            ok: false,
            provisioning: None,
            adapter_bootstrap: None,
            execution_target: None,
            findings: vec![finding],
        },
        preview: None,
        governance_preflight: None,
        receipt,
        service: None,
        service_command: None,
        task: task_name,
        task_command: None,
        exit_code: None,
        stdout: String::new(),
        stderr: String::new(),
    }
}

fn up_replay_input_policy_unavailable_result(
    contract: &Contract,
    resolved_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    error: String,
) -> RepoUpResult {
    let finding = replay_input_policy_unavailable_finding(&error);
    let task_name = contract
        .selected_run_task_name_for(workflow_name)
        .map(str::to_string);
    let context = task_name
        .as_deref()
        .map(|task_name| {
            task_phase_execution_context(contract, resolved_path, task_name, overrides, None)
        })
        .unwrap_or_else(native_phase_execution_context);
    let mut receipt = repo_execution_receipt_with_overrides(
        resolved_path,
        contract,
        context,
        "BLOCKED",
        "preconditions",
        workflow_name,
        None,
        task_name.as_deref(),
        std::slice::from_ref(&finding),
        None,
        Some(finding.next.clone()),
        Some(overrides),
    );
    receipt.failure_origin = Some(String::from("replay_input_policy_unavailable"));
    receipt.blocked = vec![String::from("replay_input_policy_unavailable")];
    refresh_execution_receipt_status(&mut receipt);
    RepoUpResult {
        ok: false,
        status: "BLOCKED",
        phase: "preconditions",
        report: DoctorReport {
            ok: false,
            provisioning: None,
            adapter_bootstrap: None,
            execution_target: None,
            findings: vec![finding],
        },
        preview: None,
        governance_preflight: None,
        receipt,
        service: None,
        service_command: None,
        task: task_name,
        task_command: None,
        exit_code: None,
        stdout: String::new(),
        stderr: String::new(),
    }
}

fn attach_pre_execution_replay_inputs(
    receipt: &mut ExecutionReceipt,
    captured: &[ExecutionReceiptEvaluatedInput],
) {
    receipt.evaluated_inputs.extend_from_slice(captured);
    receipt
        .evaluated_inputs
        .sort_by(|left, right| left.id.cmp(&right.id));
    receipt
        .evaluated_inputs
        .dedup_by(|left, right| left.id == right.id);
}

fn attach_witnessed_observations(
    receipt: &mut ExecutionReceipt,
    captured: &ExecutionReceiptWitnessedObservations,
) {
    receipt
        .witnessed_observations
        .query_traces
        .extend(captured.query_traces.iter().cloned());
    receipt
        .witnessed_observations
        .query_traces
        .sort_by(|left, right| left.id.cmp(&right.id));
    receipt
        .witnessed_observations
        .query_traces
        .dedup_by(|left, right| left.id == right.id);
    if let Some(evidence) = crate::runner::current_oci_local_application_evidence() {
        receipt.witnessed_observations.sandbox_application = Some(evidence);
    }
}

fn archive_sandbox_execution_receipt(
    contract: &Contract,
    contract_path: &Path,
    receipt: &mut ExecutionReceipt,
    terminal_exit_code: Option<i32>,
) -> Result<Option<PathBuf>, String> {
    finalize_and_attach_active_crossing_transaction(receipt, terminal_exit_code)?;
    let application = receipt.witnessed_observations.sandbox_application.as_ref();
    let crossing_authority = receipt
        .crossing
        .as_ref()
        .and_then(|crossing| crossing.authority.as_ref());
    if application.is_none() && crossing_authority.is_none() {
        return Ok(None);
    }
    if let Some(application) = application {
        crate::sandbox_policy::validate_application_evidence_against_contract(
            contract,
            application,
        )?;
        validate_sandbox_application_against_receipt_steps(application, &receipt.steps)?;
    }
    let root = contract_working_dir(contract_path);
    let snapshot = build_contract_snapshot_artifact(root, contract, true)?;
    let normalized_snapshot = normalized_contract_snapshot_value(contract)?;
    receipt.contract_snapshot_hash = Some(snapshot.hash);
    receipt.contract_snapshot_ref = snapshot
        .archive_path
        .as_deref()
        .map(receipt_storage_path_display);
    receipt.assumption_set_hash = Some(assumption_set_hash_from_snapshot(&normalized_snapshot)?);
    let archive_path = next_receipt_archive_path(root, "repo-receipt")?;
    let archive_path_display = receipt_storage_path_display(&archive_path);
    let path_display = compact_path(contract_path, ".");
    let workflow = application
        .filter(|application| {
            application.lane.kind == crate::sandbox_policy::SandboxLaneKind::Workflow
        })
        .map(|application| application.lane.name.as_str())
        .or_else(|| {
            receipt
                .crossing
                .as_ref()
                .filter(|crossing| crossing.lane_kind == "workflow")
                .and_then(|crossing| crossing.lane_id.strip_prefix("workflow:"))
        });
    let authority_scope = crossing_authority
        .map(|authority| {
            serde_json::from_value::<ArchivedCrossingAuthorityEvidence>(
                authority.archive_evidence.clone(),
            )
            .map(|archived| archived.semantic_scope().clone())
            .map_err(|error| {
                format!("crossing authority evidence cannot supply an archive scope: {error}")
            })
        })
        .transpose()?;
    let archive_context = if let Some(application) = application {
        crate::output::ReceiptArchiveContext {
            schema_version: authority_scope.as_ref().map_or(1, |_| 2),
            kind: String::from("execution"),
            lane_kind: Some(match application.lane.kind {
                crate::sandbox_policy::SandboxLaneKind::Task => String::from("task"),
                crate::sandbox_policy::SandboxLaneKind::Workflow => String::from("workflow"),
            }),
            lane_name: Some(application.lane.name.clone()),
            semantic_scope: authority_scope.clone(),
            effect_policy_refusal: None,
        }
    } else if let Some(crossing) = receipt.crossing.as_ref() {
        crate::output::ReceiptArchiveContext {
            schema_version: authority_scope.as_ref().map_or(1, |_| 2),
            kind: String::from("execution"),
            lane_kind: Some(crossing.lane_kind.clone()),
            lane_name: crossing
                .lane_id
                .split_once(':')
                .map(|(_, lane_name)| lane_name.to_string()),
            semantic_scope: authority_scope,
            effect_policy_refusal: None,
        }
    } else {
        return Err(String::from(
            "execution receipt archive is missing immutable lane context",
        ));
    };
    let findings = Vec::<Finding>::new();
    let payload = ReceiptSuccess {
        ok: receipt.ok,
        path: path_display.as_str(),
        mode: "receipt",
        workflow,
        summary: receipt.summary,
        receipt: receipt.clone(),
        archive_path: Some(archive_path_display.as_str()),
        archive_context: Some(archive_context),
        promoted_baseline: None,
        artifact_routing: receipt_artifact_routing(
            contract_path,
            workflow,
            receipt,
            Some(archive_path_display.as_str()),
        ),
        findings: &findings,
    };
    write_receipt_archive_create_new_durable(&archive_path, &payload)?;
    let archive_bytes = read_durable_receipt_archive(&archive_path)?;
    let receipt_archive_identity = format!("sha256:{:x}", Sha256::digest(&archive_bytes));
    write_proof_runtime_crossing_handoff(root, receipt, &archive_path)?;
    #[cfg(unix)]
    persist_active_crossing_systemd_completion(
        receipt,
        receipt_archive_identity.as_str(),
        terminal_exit_code,
    )?;
    prune_receipt_archives(
        root,
        "repo-receipt",
        RECEIPT_ARCHIVE_LIMIT,
        Some(&archive_path),
    )?;
    Ok(Some(archive_path))
}

fn validate_sandbox_application_against_receipt_steps(
    application: &crate::sandbox_policy::SandboxApplicationEvidence,
    steps: &[ExecutionReceiptStep],
) -> Result<(), String> {
    if application.status
        == crate::sandbox_policy::SandboxApplicationStatus::EnforcedThroughCompletion
    {
        for segment in application.segments.iter().filter(|segment| {
            segment.purpose
                == crate::sandbox_policy::SandboxSegmentApplicationPurpose::TaskExecution
        }) {
            let task = segment.segment_id.strip_prefix("task:").ok_or_else(|| {
                String::from("sandbox application segment has an invalid task identity")
            })?;
            if !steps.iter().any(|step| {
                step.task.as_deref() == Some(task)
                    && step.generation == Some(segment.invocation_generation)
                    && step.exit_code.is_some()
            }) {
                return Err(format!(
                    "completed sandbox segment `{task}` generation {} has no matching archived execution outcome",
                    segment.invocation_generation
                ));
            }
        }
        for step in steps.iter().filter(|step| {
            step.task.is_some() && step.generation.is_some() && step.exit_code.is_some()
        }) {
            let segment_id = format!("task:{}", step.task.as_deref().unwrap_or_default());
            if !application.segments.iter().any(|segment| {
                segment.segment_id == segment_id
                    && segment.purpose
                        == crate::sandbox_policy::SandboxSegmentApplicationPurpose::TaskExecution
                    && Some(segment.invocation_generation) == step.generation
            }) {
                return Err(format!(
                    "archived task outcome `{}` generation {} has no matching completed sandbox segment",
                    step.task.as_deref().unwrap_or_default(),
                    step.generation.unwrap_or_default()
                ));
            }
        }
    }
    for edge in &application.selected_edges {
        let executed_task = edge.executed_segment.strip_prefix("task:").ok_or_else(|| {
            String::from("selected sandbox edge has an invalid executed-segment identity")
        })?;
        if edge.state == crate::sandbox_policy::SandboxSelectedEdgeState::Entered
            && !steps.iter().any(|step| {
                step.task.as_deref() == Some(executed_task)
                    && step.generation == Some(edge.generation)
                    && step.exit_code.is_some()
            })
        {
            return Err(format!(
                "entered sandbox edge for `{executed_task}` generation {} has no matching archived execution outcome",
                edge.generation
            ));
        }
        if let (Some(source_exit_code), Some(source_generation)) =
            (edge.source_exit_code, edge.source_generation)
        {
            let source_task = edge.source.strip_prefix("task:").ok_or_else(|| {
                String::from("selected sandbox edge has an invalid source-segment identity")
            })?;
            if !steps.iter().any(|step| {
                step.task.as_deref() == Some(source_task)
                    && step.generation == Some(source_generation)
                    && step.exit_code == Some(source_exit_code)
            }) {
                return Err(format!(
                    "conditional sandbox edge source `{source_task}` generation {source_generation} does not match an archived execution outcome"
                ));
            }
        }
    }
    Ok(())
}

fn archive_sandbox_run_receipt(
    contract: &Contract,
    contract_path: &Path,
    receipt: &mut ExecutionReceipt,
    terminal_exit_code: Option<i32>,
) -> Result<(), RunCommandFailure> {
    archive_sandbox_execution_receipt(contract, contract_path, receipt, terminal_exit_code)
        .map(|_| ())
        .map_err(|message| RunCommandFailure {
            message: stylize_text_failure(
                "ota run",
                &format!("sandbox enforcement evidence could not be archived: {message}"),
            ),
            summary: None,
            exit_code: 1,
            receipt: Some(render_execution_receipt_text(receipt)),
        })
}

// Generated artifacts are contract lineage, not freshness proof. Capture the exact declaration
// while issuing the receipt so consumers do not reconstruct producer ownership from task text.
fn collect_receipt_generated_artifact_inputs(
    contract: &Contract,
    root: &Path,
    task_name: &str,
    task: &TaskSpec,
    inputs: &mut BTreeMap<String, ExecutionReceiptEvaluatedInput>,
) {
    for artifact_name in &task.requires_artifacts {
        let Some(artifact) = contract.artifacts.get(artifact_name) else {
            continue;
        };
        let replay_authority =
            if contract.task_consumes_artifact_as_replay(task_name, artifact_name) {
                artifact.replay.as_ref().and_then(|replay| {
                    crate::replay_baseline::verify_promoted_replay_baseline(
                        root,
                        artifact_name,
                        &artifact.paths,
                        &replay.authority_manifest,
                    )
                    .ok()
                    .map(|manifest| {
                        crate::output::ExecutionReceiptReplayBaselineAuthority {
                            authority_manifest: replay.authority_manifest.clone(),
                            trust_root: String::from("scm_review"),
                            selected_attestation_identity: manifest.selected_attestation_identity,
                            promotion_identity: manifest.promotion_identity,
                            consumption: match replay.consumption {
                                crate::schema::ReplayBaselineConsumption::ReadOnly => {
                                    String::from("read_only")
                                }
                                crate::schema::ReplayBaselineConsumption::VerifyUnchanged => {
                                    String::from("verify_unchanged")
                                }
                            },
                        }
                    })
                })
            } else {
                None
            };
        let lineage = ExecutionReceiptArtifactLineage {
            producer: artifact.producer.clone(),
            paths: artifact.paths.clone(),
            inputs: artifact.inputs.clone(),
            replay_authority,
        };
        let identity = contract_snapshot_hash(
            &serde_json::to_vec(&lineage)
                .expect("generated artifact lineage must serialize for receipt identity"),
        );
        let id = format!("generated_artifact:{artifact_name}");
        inputs.insert(
            id.clone(),
            ExecutionReceiptEvaluatedInput {
                id,
                kind: if lineage.replay_authority.is_some() {
                    String::from("promoted_replay_baseline")
                } else {
                    String::from("generated_artifact_lineage")
                },
                input_class: if lineage.replay_authority.is_some() {
                    ReplayInputClass::PromotedReplayBaseline
                } else {
                    ReplayInputClass::GeneratedArtifactLineage
                },
                identity: lineage
                    .replay_authority
                    .as_ref()
                    .map(|authority| authority.promotion_identity.clone())
                    .unwrap_or(identity),
                expected_identity: None,
                execution_started: None,
                hydration_provenance: None,
                artifact_lineage: Some(lineage),
            },
        );
    }
}

// Compose image references are execution inputs only when the task selects a declared Compose
// file and service set. Keep this intentionally strict: interpolation, inferred default files,
// and mutable tags are not immutable runtime evidence.
fn collect_receipt_compose_image_inputs(
    task: &TaskSpec,
    root: &Path,
    backend: Backend,
    inputs: &mut BTreeMap<String, ExecutionReceiptEvaluatedInput>,
) {
    let mut services = BTreeSet::new();
    let mut selects_all_services = false;
    collect_compose_invocation_services(
        task.compose.as_ref().map(|compose| &compose.invocation),
        &mut services,
        &mut selects_all_services,
    );
    if let Some(crate::schema::TaskLaunchSpec::Compose(launch)) = task.launch.as_ref() {
        if launch.services.is_empty() {
            selects_all_services = true;
        } else {
            services.extend(
                launch
                    .services
                    .iter()
                    .map(|service| service.trim())
                    .filter(|service| !service.is_empty())
                    .map(str::to_string),
            );
        }
    }
    if let Some(prepare) = task.prepare.as_ref() {
        collect_prepare_compose_invocation_services(
            prepare,
            &mut services,
            &mut selects_all_services,
        );
    }

    let cwd = task
        .compose_adapter_cwd_for_backend(backend)
        .unwrap_or_default();
    let files = task.compose_adapter_files_for_backend(backend);
    for file in files {
        collect_receipt_compose_images_from_file(
            root,
            cwd.as_str(),
            file.as_str(),
            &services,
            selects_all_services,
            inputs,
        );
    }
    if let Some(prepare) = task.prepare.as_ref() {
        collect_prepare_docker_compose_image_inputs(prepare, root, inputs);
    }
}

fn collect_compose_invocation_services(
    invocation: Option<&crate::schema::TaskComposeInvocationSpec>,
    services: &mut BTreeSet<String>,
    selects_all_services: &mut bool,
) {
    let Some(invocation) = invocation else {
        return;
    };
    let service = invocation.service.trim();
    if !service.is_empty() {
        services.insert(service.to_string());
    }
    services.extend(
        invocation
            .services
            .iter()
            .map(|service| service.trim())
            .filter(|service| !service.is_empty())
            .map(str::to_string),
    );
    if service.is_empty() && invocation.services.is_empty() {
        *selects_all_services = true;
    }
}

fn collect_prepare_compose_invocation_services(
    prepare: &TaskPrepareSpec,
    services: &mut BTreeSet<String>,
    selects_all_services: &mut bool,
) {
    match prepare {
        TaskPrepareSpec::DependencyHydration(spec) => collect_compose_invocation_services(
            spec.source.compose_invocation(),
            services,
            selects_all_services,
        ),
        TaskPrepareSpec::Sequence(sequence) => {
            for step in &sequence.steps {
                match step {
                    crate::schema::TaskPrepareSequenceStepSpec::DependencyHydration(spec) => {
                        collect_compose_invocation_services(
                            spec.source.compose_invocation(),
                            services,
                            selects_all_services,
                        );
                    }
                    crate::schema::TaskPrepareSequenceStepSpec::Sequence(sequence) => {
                        collect_prepare_compose_invocation_services(
                            &TaskPrepareSpec::Sequence(sequence.clone()),
                            services,
                            selects_all_services,
                        );
                    }
                    _ => {}
                }
            }
        }
        TaskPrepareSpec::ToolBootstrap(_) => {}
    }
}

fn collect_prepare_docker_compose_image_inputs(
    prepare: &TaskPrepareSpec,
    root: &Path,
    inputs: &mut BTreeMap<String, ExecutionReceiptEvaluatedInput>,
) {
    match prepare {
        TaskPrepareSpec::DependencyHydration(spec) => {
            let TaskDependencyHydrationSourceSpec::DockerCompose(source) = &spec.source else {
                return;
            };
            let services = spec
                .targets
                .iter()
                .map(|target| target.trim())
                .filter(|target| !target.is_empty())
                .map(str::to_string)
                .collect::<BTreeSet<_>>();
            let selects_all_services = services.is_empty();
            for file in source.effective_files() {
                collect_receipt_compose_images_from_file(
                    root,
                    source.cwd.as_str(),
                    file,
                    &services,
                    selects_all_services,
                    inputs,
                );
            }
        }
        TaskPrepareSpec::Sequence(sequence) => {
            for step in &sequence.steps {
                match step {
                    crate::schema::TaskPrepareSequenceStepSpec::DependencyHydration(spec) => {
                        collect_prepare_docker_compose_image_inputs(
                            &TaskPrepareSpec::DependencyHydration(spec.clone()),
                            root,
                            inputs,
                        );
                    }
                    crate::schema::TaskPrepareSequenceStepSpec::Sequence(sequence) => {
                        collect_prepare_docker_compose_image_inputs(
                            &TaskPrepareSpec::Sequence(sequence.clone()),
                            root,
                            inputs,
                        );
                    }
                    _ => {}
                }
            }
        }
        TaskPrepareSpec::ToolBootstrap(_) => {}
    }
}

fn collect_receipt_compose_images_from_file(
    root: &Path,
    cwd: &str,
    file: &str,
    selected_services: &BTreeSet<String>,
    selects_all_services: bool,
    inputs: &mut BTreeMap<String, ExecutionReceiptEvaluatedInput>,
) {
    let file = file.trim();
    if file.is_empty() {
        return;
    }
    let relative_path = if cwd.trim().is_empty() || cwd.trim() == "." {
        PathBuf::from(file)
    } else {
        PathBuf::from(cwd.trim()).join(file)
    };
    let Ok(contents) = fs::read_to_string(root.join(&relative_path)) else {
        return;
    };
    let Ok(document) = serde_yaml::from_str::<YamlValue>(&contents) else {
        return;
    };
    let Some(services) = document
        .as_mapping()
        .and_then(|root| root.get(YamlValue::String(String::from("services"))))
        .and_then(YamlValue::as_mapping)
    else {
        return;
    };
    let selected_services =
        compose_selected_service_closure(services, selected_services, selects_all_services);
    let file_id = relative_path.to_string_lossy().replace('\\', "/");
    for (service_name, service) in services {
        let Some(service_name) = service_name
            .as_str()
            .map(str::trim)
            .filter(|name| !name.is_empty())
        else {
            continue;
        };
        if !selected_services.contains(service_name) {
            continue;
        }
        let Some(image) = service
            .as_mapping()
            .and_then(|service| service.get(YamlValue::String(String::from("image"))))
            .and_then(YamlValue::as_str)
        else {
            continue;
        };
        let Some(digest) = static_sha256_digest(image) else {
            continue;
        };
        let id = format!("compose_image:{file_id}#services.{service_name}");
        inputs.insert(
            id.clone(),
            ExecutionReceiptEvaluatedInput {
                id,
                kind: String::from("container_image_digest"),
                input_class: ReplayInputClass::SelectedRuntimeArtifact,
                identity: digest,
                expected_identity: None,
                execution_started: None,
                hydration_provenance: None,
                artifact_lineage: None,
            },
        );
    }
}

fn compose_selected_service_closure(
    services: &serde_yaml::Mapping,
    selected_services: &BTreeSet<String>,
    selects_all_services: bool,
) -> BTreeSet<String> {
    let mut closure = if selects_all_services {
        services
            .keys()
            .filter_map(YamlValue::as_str)
            .map(str::trim)
            .filter(|service| !service.is_empty())
            .map(str::to_string)
            .collect()
    } else {
        selected_services.clone()
    };
    let mut pending = closure.iter().cloned().collect::<Vec<_>>();
    while let Some(service_name) = pending.pop() {
        let Some(service) = services.get(YamlValue::String(service_name)) else {
            continue;
        };
        for dependency in compose_service_depends_on(service) {
            if closure.insert(dependency.clone()) {
                pending.push(dependency);
            }
        }
    }
    closure
}

fn compose_service_depends_on(service: &YamlValue) -> Vec<String> {
    let Some(depends_on) = service
        .as_mapping()
        .and_then(|service| service.get(YamlValue::String(String::from("depends_on"))))
    else {
        return Vec::new();
    };
    let names = match depends_on {
        YamlValue::Sequence(dependencies) => dependencies
            .iter()
            .filter_map(YamlValue::as_str)
            .collect::<Vec<_>>(),
        YamlValue::Mapping(dependencies) => dependencies
            .keys()
            .filter_map(YamlValue::as_str)
            .collect::<Vec<_>>(),
        YamlValue::String(dependency) => vec![dependency.as_str()],
        _ => Vec::new(),
    };
    names
        .into_iter()
        .map(str::trim)
        .filter(|name| !name.is_empty())
        .map(str::to_string)
        .collect()
}

fn static_sha256_digest(image: &str) -> Option<String> {
    let digest = image.trim().rsplit_once("@sha256:")?.1;
    (digest.len() == 64 && digest.bytes().all(|byte| byte.is_ascii_hexdigit()))
        .then(|| format!("sha256:{}", digest.to_ascii_lowercase()))
}

fn collect_receipt_hydration_inputs(
    prepare: &TaskPrepareSpec,
    root: &Path,
    inputs: &mut BTreeMap<String, ExecutionReceiptEvaluatedInput>,
) {
    match prepare {
        TaskPrepareSpec::DependencyHydration(spec) => {
            collect_receipt_hydration_source_inputs(&spec.source, root, inputs);
        }
        TaskPrepareSpec::Sequence(sequence) => {
            for step in &sequence.steps {
                match step {
                    crate::schema::TaskPrepareSequenceStepSpec::DependencyHydration(spec) => {
                        collect_receipt_hydration_source_inputs(&spec.source, root, inputs);
                    }
                    crate::schema::TaskPrepareSequenceStepSpec::Sequence(sequence) => {
                        collect_receipt_hydration_inputs(
                            &TaskPrepareSpec::Sequence(sequence.clone()),
                            root,
                            inputs,
                        );
                    }
                    _ => {}
                }
            }
        }
        TaskPrepareSpec::ToolBootstrap(_) => {}
    }
}

fn collect_receipt_hydration_source_inputs(
    source: &TaskDependencyHydrationSourceSpec,
    root: &Path,
    inputs: &mut BTreeMap<String, ExecutionReceiptEvaluatedInput>,
) {
    let TaskDependencyHydrationSourceSpec::NodePackageManager(source) = source else {
        return;
    };
    let cwd = source.cwd.trim();
    let lockfile_name = match source.manager {
        TaskNodePackageManagerKind::Pnpm if source.frozen_lockfile => "pnpm-lock.yaml",
        // npm ci is the lockfile-strict npm lane. npm gives shrinkwrap precedence when both
        // files exist, so capture the input it will actually resolve from.
        TaskNodePackageManagerKind::Npm
            if matches!(
                source.mode,
                crate::schema::TaskNodePackageManagerHydrationMode::Ci
            ) =>
        {
            let base = if cwd.is_empty() || cwd == "." {
                root.to_path_buf()
            } else {
                root.join(cwd)
            };
            if base.join("npm-shrinkwrap.json").is_file() {
                "npm-shrinkwrap.json"
            } else {
                "package-lock.json"
            }
        }
        _ => return,
    };
    let relative_path = if cwd.is_empty() || cwd == "." {
        PathBuf::from(lockfile_name)
    } else {
        PathBuf::from(cwd).join(lockfile_name)
    };
    let lockfile_path = root.join(&relative_path);
    let Ok(bytes) = fs::read(lockfile_path) else {
        return;
    };
    let id = relative_path.to_string_lossy().replace('\\', "/");
    inputs.insert(
        id.clone(),
        ExecutionReceiptEvaluatedInput {
            id,
            kind: String::from("lockfile"),
            input_class: ReplayInputClass::DeclaredDependencyResolution,
            identity: contract_snapshot_hash(&bytes),
            expected_identity: None,
            execution_started: None,
            hydration_provenance: None,
            artifact_lineage: None,
        },
    );
    if let Some(version) = command_version_in_working_dir("node", root) {
        inputs.insert(
            String::from("runtime:node"),
            ExecutionReceiptEvaluatedInput {
                id: String::from("runtime:node"),
                kind: String::from("runtime_version"),
                input_class: ReplayInputClass::SelectedRuntimeVersion,
                identity: version,
                expected_identity: None,
                execution_started: None,
                hydration_provenance: None,
                artifact_lineage: None,
            },
        );
    }
}

fn run_execution_receipt_with_shared(
    contract: &Contract,
    contract_path: &Path,
    policy_snapshot: Option<DoctorPolicySnapshot<'_>>,
    overrides: ExecutionOverrides,
    task_name: &str,
    _member: Option<&str>,
    executed_steps: &[ExecutedTaskStep],
    step_target_resolutions: &[Vec<TaskTargetResolutionEvidence>],
    target_resolutions: &[TaskTargetResolutionEvidence],
    fulfilled_toolchains: &[ToolchainFulfillmentEvidence],
    step_backend_fulfillments: &[Option<crate::runner::BackendFulfillmentEvidence>],
    backend_fulfillment: Option<crate::runner::BackendFulfillmentEvidence>,
    step_shared_local_backends: &[Option<SharedLocalBackendEvidence>],
    shared_local_backend: Option<SharedLocalBackendEvidence>,
    _exit_code: i32,
    ok: bool,
    target: Option<String>,
    runtime: Option<crate::runner::ResolvedTaskRuntime>,
    next: Option<String>,
) -> ExecutionReceipt {
    let effective = effective_task_execution(contract, task_name, overrides);
    let resolved_backend = resolve_execution_backend_with_contract_path(
        contract,
        task_name,
        overrides,
        Some(contract_path),
    )
    .ok();
    let shared_backend_lifecycle = shared_local_backend
        .as_ref()
        .and_then(
            |shared_local_backend| match shared_local_backend.lifecycle.as_str() {
                "persistent" => Some(Lifecycle::Persistent),
                "ephemeral" => Some(Lifecycle::Ephemeral),
                _ => None,
            },
        );
    let task_shared_backend_lifecycle = shared_backend_lifecycle.or_else(|| {
        (effective.backend == Backend::Container)
            .then(|| {
                contract
                    .tasks
                    .get(task_name)
                    .and_then(|task| task.backend_binding_for_backend(Backend::Container))
                    .and_then(|shared_backend_binding| {
                        contract
                            .execution
                            .as_ref()
                            .and_then(|execution| {
                                execution.shared_backends.get(shared_backend_binding)
                            })
                            .filter(|shared_backend| shared_backend.backend == Backend::Container)
                            .map(|shared_backend| shared_backend.lifecycle)
                    })
            })
            .flatten()
    });
    let backend = resolved_backend
        .as_ref()
        .map(|backend| match backend {
            ResolvedExecutionBackend::Native { .. } => Backend::Native,
            ResolvedExecutionBackend::Container { .. } => Backend::Container,
            ResolvedExecutionBackend::Remote { .. }
            | ResolvedExecutionBackend::BackendProvider { .. } => Backend::Remote,
        })
        .unwrap_or(effective.backend);
    let lifecycle = match resolved_backend.as_ref() {
        Some(ResolvedExecutionBackend::Container { lifecycle, .. }) => Some(*lifecycle),
        _ => match backend {
            Backend::Native if overrides.lifecycle.is_none() => None,
            _ => overrides
                .lifecycle
                .or(task_shared_backend_lifecycle)
                .or(effective.lifecycle),
        },
    };
    let image = match resolved_backend.as_ref() {
        Some(ResolvedExecutionBackend::Container { image, .. }) => Some(image.clone()),
        _ => match backend {
            Backend::Container => effective.container.map(|container| container.image.clone()),
            Backend::Native | Backend::Remote => None,
        },
    };
    let container_memory_bytes = match resolved_backend.as_ref() {
        Some(ResolvedExecutionBackend::Container { memory_bytes, .. }) => *memory_bytes,
        _ => match backend {
            Backend::Container => {
                receipt_container_memory_bytes(effective.container, overrides.memory)
            }
            Backend::Native | Backend::Remote => None,
        },
    };
    let context =
        reported_task_context_for_backend(contract, task_name, backend).map(str::to_string);
    let provider = resolved_backend.as_ref().and_then(|backend| match backend {
        ResolvedExecutionBackend::Remote { provider, .. }
        | ResolvedExecutionBackend::BackendProvider { provider, .. } => Some(provider.clone()),
        ResolvedExecutionBackend::Native { .. } | ResolvedExecutionBackend::Container { .. } => {
            None
        }
    });
    let cwd = resolved_backend.as_ref().and_then(|backend| match backend {
        ResolvedExecutionBackend::Remote { cwd, .. }
        | ResolvedExecutionBackend::BackendProvider { cwd, .. } => cwd.clone(),
        ResolvedExecutionBackend::Native { .. } | ResolvedExecutionBackend::Container { .. } => {
            None
        }
    });
    let target = target.or_else(|| effective_task_execution_target(contract_path, effective));
    let effective_task_env = match (resolved_backend.as_ref(), contract.tasks.get(task_name)) {
        (Some(resolved_backend), Some(task)) => Some(effective_task_env_for_backend(
            contract,
            task,
            resolved_backend,
            contract_working_dir(contract_path),
        )),
        _ => contract
            .tasks
            .get(task_name)
            .map(|task| task.env_for_backend(contract.execution.as_ref(), backend)),
    };
    let env_details = resolve_task_env_details_for_task(
        contract,
        contract_path,
        task_name,
        effective_task_env.as_ref(),
    )
    .unwrap_or_default();
    let declared_sources = load_declared_env_sources(contract, contract_path);
    let steps = executed_steps
        .iter()
        .enumerate()
        .map(|(index, step)| {
            let mut receipt_step = execution_receipt_step(
                index + 1,
                step.name.clone(),
                if step.exit_code == 0 {
                    "READY".to_string()
                } else {
                    "FAILED".to_string()
                },
                execution_receipt_step_detail(step, task_name),
                Some(step.exit_code),
            );
            receipt_step.stage_family = String::from("verify");
            receipt_step.task = Some(step.name.clone());
            receipt_step.generation = Some(step.generation);
            let (relation, parent) = execution_receipt_step_relation(&step.relation);
            receipt_step.execution_relation = Some(relation.to_string());
            receipt_step.execution_parent = parent.map(str::to_string);
            if let Some(step_resolutions) = step_target_resolutions.get(index)
                && !step_resolutions.is_empty()
            {
                receipt_step.target_resolutions = step_resolutions.clone();
            } else if step.name == task_name
                && matches!(step.relation, TaskExecutionRelation::Requested)
            {
                receipt_step.target_resolutions = target_resolutions.to_vec();
            }
            if let Some(step_fulfillment) = step_backend_fulfillments.get(index).cloned().flatten()
            {
                receipt_step.backend_fulfillment = Some(step_fulfillment);
            } else if step.name == task_name
                && matches!(step.relation, TaskExecutionRelation::Requested)
            {
                receipt_step.backend_fulfillment = backend_fulfillment.clone();
            }
            if let Some(step_shared_backend) =
                step_shared_local_backends.get(index).cloned().flatten()
            {
                receipt_step.shared_local_backend = Some(step_shared_backend);
            } else if step.name == task_name
                && matches!(step.relation, TaskExecutionRelation::Requested)
            {
                receipt_step.shared_local_backend = shared_local_backend.clone();
            }
            receipt_step
        })
        .collect::<Vec<_>>();
    let step_count = steps.len();
    let status = aggregate_execution_summary_status(ok, &steps, &[]);
    let failure_context = execution_receipt_failure_context(executed_steps, task_name, ok);
    let native_prerequisites = receipt_native_prerequisites(
        contract,
        Some(task_name),
        backend,
        current_requirement_platform(),
        true,
    );
    let mut toolchains = selected_task_toolchain_summaries(contract, task_name, overrides);
    apply_toolchain_fulfillment_evidence(&mut toolchains, fulfilled_toolchains);
    let toolchain_names = toolchain_summary_names(&toolchains);
    let mut policy_lines = execution_policy_lines_for_toolchain_names(
        contract,
        contract_path,
        backend,
        &toolchain_names,
        policy_snapshot,
    );
    policy_lines.extend(safe_task_effect_policy_lines(
        contract,
        task_name,
        overrides,
        policy_snapshot.and_then(|snapshot| snapshot.loaded),
    ));
    let evaluated_inputs = receipt_evaluated_inputs_with_policy_snapshot(
        contract,
        contract_path,
        executed_steps
            .iter()
            .map(|step| step.name.clone())
            .chain(std::iter::once(task_name.to_string())),
        overrides,
        policy_snapshot,
    );

    ExecutionReceipt {
        ok,
        path: contract_path.display().to_string(),
        scope: String::from("repo"),
        contract: contract_path.display().to_string(),
        contract_identity: Some(repo_contract_identity(contract)),
        contract_snapshot_hash: None,
        contract_snapshot_ref: None,
        assumption_set_hash: None,
        evaluated_inputs,
        witnessed_observations: crate::output::ExecutionReceiptWitnessedObservations::default(),
        crossing: None,
        refusal: None,
        typed_effect_policy_refusal: None,
        replay_input_policy: None,
        workspace: None,
        backend: Some(format_backend(backend).to_string()),
        context,
        lifecycle: lifecycle.map(format_lifecycle).map(str::to_string),
        image,
        container_memory_bytes,
        target,
        provider,
        cwd,
        acquired: Vec::new(),
        env: env_details
            .iter()
            .map(|(name, value)| (name.clone(), receipt_env_value(value)))
            .collect(),
        env_sources: env_details
            .iter()
            .map(|(name, value)| receipt_env_source_entry(name, value, &declared_sources))
            .collect(),
        workflow_env_artifacts: Vec::new(),
        native_prerequisites,
        toolchains,
        runtime,
        logs: None,
        service_termination: None,
        host_service_cleanup: Vec::new(),
        backend_fulfillment,
        workloads: BTreeMap::new(),
        policy: policy_lines,
        dependency_steps: planned_dependency_steps_for_task(
            contract,
            Some(task_name),
            Some(overrides),
        ),
        steps,
        status: Some(status),
        failed_task: failure_context
            .as_ref()
            .map(|context| context.failed_task.clone()),
        failed_dependency: failure_context
            .as_ref()
            .and_then(|context| context.failed_dependency.clone()),
        failure_origin: failure_context
            .as_ref()
            .map(|context| context.failure_origin.clone()),
        blocked: Vec::new(),
        summary: ExecutionReceiptSummary {
            error_count: if ok { 0 } else { 1 },
            warn_count: 0,
            info_count: 0,
            step_count,
            repo_count: None,
            ready_count: None,
            not_ready_count: None,
        },
        next,
    }
}

fn execution_receipt_step_detail(step: &ExecutedTaskStep, requested_task: &str) -> Option<String> {
    let relation_detail = match &step.relation {
        TaskExecutionRelation::Requested => {
            if step.name == requested_task {
                Some(String::from("requested task"))
            } else {
                None
            }
        }
        TaskExecutionRelation::DependsOn { parent } => {
            if step.generation == 0 {
                Some(format!("depends_on for `{parent}`"))
            } else {
                Some(format!("dependency of rerun `{parent}`"))
            }
        }
        TaskExecutionRelation::AggregateMember { parent } => {
            if step.generation == 0 {
                Some(format!("aggregate member of `{parent}`"))
            } else {
                Some(format!("rerun aggregate member of `{parent}`"))
            }
        }
        TaskExecutionRelation::AfterSuccess { parent } => {
            if step.generation == 0 {
                Some(format!("after_success for `{parent}`"))
            } else {
                Some(format!("rerun via after_success for `{parent}`"))
            }
        }
        TaskExecutionRelation::AfterFailure { parent } => {
            if step.generation == 0 {
                Some(format!("after_failure for `{parent}`"))
            } else {
                Some(format!("rerun via after_failure for `{parent}`"))
            }
        }
        TaskExecutionRelation::AfterAlways { parent } => {
            if step.generation == 0 {
                Some(format!("after_always for `{parent}`"))
            } else {
                Some(format!("rerun via after_always for `{parent}`"))
            }
        }
    };

    if let Some(note) = step.execution_note.as_deref() {
        return match &step.relation {
            TaskExecutionRelation::Requested if step.name == requested_task => {
                Some(format!("requested task; {note}"))
            }
            _ => relation_detail
                .map(|detail| format!("{detail}; {note}"))
                .or_else(|| Some(note.to_string())),
        };
    }

    relation_detail
}

fn execution_receipt_step_relation(
    relation: &TaskExecutionRelation,
) -> (&'static str, Option<&str>) {
    match relation {
        TaskExecutionRelation::Requested => ("requested", None),
        TaskExecutionRelation::DependsOn { parent } => ("depends_on", Some(parent.as_str())),
        TaskExecutionRelation::AggregateMember { parent } => {
            ("aggregate_member", Some(parent.as_str()))
        }
        TaskExecutionRelation::AfterSuccess { parent } => ("after_success", Some(parent.as_str())),
        TaskExecutionRelation::AfterFailure { parent } => ("after_failure", Some(parent.as_str())),
        TaskExecutionRelation::AfterAlways { parent } => ("after_always", Some(parent.as_str())),
    }
}

struct RunCommandFailure {
    message: String,
    summary: Option<String>,
    exit_code: i32,
    receipt: Option<String>,
}

fn render_run_preferred_backend_validation_text(
    resolved_path: &Path,
    member: Option<&str>,
    task_name: &str,
    errors: &ValidationErrors,
) -> Option<String> {
    if errors.errors().len() != 1 {
        return None;
    }

    let error = errors.errors()[0].to_string();
    let text_path_display = display_contract_target(&compact_contract_path(resolved_path), member);

    let (summary, why_lines, next_steps) = if error
        == "`execution.preferred: container` requires `execution.backends.container.image`"
    {
        (
            "Container run is not configured",
            vec![
                format!("task `{task_name}` resolves to container execution by default"),
                String::from("this contract sets `execution.preferred: container`"),
                String::from("this contract does not declare `execution.backends.container.image`"),
            ],
            vec![
                format!(
                    "run {} to inspect the selected execution path before changing the contract",
                    paint_code(&format!(
                        "`{}`",
                        repo_execution_plan_command(resolved_path, member, Backend::Container)
                    ))
                ),
                String::from("add `execution.backends.container.image` to the repo contract"),
                String::from(
                    "or change the default execution mode if this repo should not prefer containers",
                ),
                format!(
                    "or rerun with a different supported mode if the repo allows it: `{}`",
                    match member {
                        Some(member) =>
                            format!("ota run --member {member} {task_name} --mode native"),
                        None => format!("ota run {task_name} --mode native"),
                    }
                ),
                task_use_details_step(Some(resolved_path), member),
            ],
        )
    } else if error == "`execution.preferred: container` requires an explicit `execution.lifecycle`"
    {
        (
            "Container run lifecycle is not configured",
            vec![
                format!("task `{task_name}` resolves to container execution by default"),
                String::from("this contract sets `execution.preferred: container`"),
                String::from("this contract does not declare `execution.lifecycle`"),
            ],
            vec![
                format!(
                    "run {} to inspect the selected execution path before changing the contract",
                    paint_code(&format!(
                        "`{}`",
                        repo_execution_plan_command(resolved_path, member, Backend::Container)
                    ))
                ),
                String::from("add `execution.lifecycle` to the repo contract"),
                String::from(
                    "or change the default execution mode if this repo should not prefer containers",
                ),
                format!(
                    "or rerun with a different supported mode if the repo allows it: `{}`",
                    match member {
                        Some(member) =>
                            format!("ota run --member {member} {task_name} --mode native"),
                        None => format!("ota run {task_name} --mode native"),
                    }
                ),
                task_use_details_step(Some(resolved_path), member),
            ],
        )
    } else if error == "`execution.preferred: remote` requires `execution.backends.remote.provider`"
    {
        (
            "Remote run is not configured",
            vec![
                format!("task `{task_name}` resolves to remote execution by default"),
                String::from("this contract sets `execution.preferred: remote`"),
                String::from("this contract does not declare `execution.backends.remote.provider`"),
            ],
            vec![
                format!(
                    "run {} to inspect the selected execution path before changing the contract",
                    paint_code(&format!(
                        "`{}`",
                        repo_execution_plan_command(resolved_path, member, Backend::Remote)
                    ))
                ),
                String::from("add `execution.backends.remote.provider` to the repo contract"),
                String::from(
                    "or change the default execution mode if this repo should not prefer remote execution",
                ),
                format!(
                    "or rerun with a different supported mode if the repo allows it: `{}`",
                    match member {
                        Some(member) =>
                            format!("ota run --member {member} {task_name} --mode native"),
                        None => format!("ota run {task_name} --mode native"),
                    }
                ),
                task_use_details_step(Some(resolved_path), member),
            ],
        )
    } else {
        return None;
    };

    Some(structured_error_text(
        "RUN",
        &text_path_display,
        summary,
        &why_lines,
        &next_steps,
    ))
}

fn render_run_runtime_validation_text(
    resolved_path: &Path,
    member: Option<&str>,
    task_name: &str,
    errors: &ValidationErrors,
) -> Option<String> {
    let text_path_display = display_contract_target(&compact_contract_path(resolved_path), member);
    if let Some(issue) = parse_runtime_projection_primary_issue(errors) {
        if issue.task_name != task_name {
            return None;
        }

        let field = format!("tasks.{task_name}.runtime.listeners");
        let listeners = issue
            .listeners
            .iter()
            .map(|listener| format!("`{listener}`"))
            .collect::<Vec<_>>()
            .join(", ");

        let (why_lines, mut next_steps) = match issue.kind {
            RuntimeProjectionPrimaryIssueKind::MissingPrimary => (
                vec![
                    format!(
                        "task `{task_name}` projects multiple listeners ({listeners}) but none is marked primary"
                    ),
                    String::from(
                        "ota needs one primary projected listener to pick `OTA_PUBLIC_URL` and the summary endpoint deterministically",
                    ),
                ],
                vec![
                    String::from(
                        "set `project.host.primary: true` on exactly one projected listener",
                    ),
                    String::from("leave all other projected listeners unset or `false`"),
                ],
            ),
            RuntimeProjectionPrimaryIssueKind::MultiplePrimaries => (
                vec![
                    format!(
                        "task `{task_name}` marks multiple projected listeners as primary ({listeners})"
                    ),
                    String::from(
                        "`OTA_PUBLIC_URL` and primary endpoint rendering require exactly one primary projected listener",
                    ),
                ],
                vec![
                    String::from(
                        "keep `project.host.primary: true` on one projected listener only",
                    ),
                    String::from(
                        "set all other projected listeners to `primary: false` or remove the field",
                    ),
                ],
            ),
        };
        next_steps.extend([
            format!(
                "rerun {} to revalidate the contract",
                paint_code(&format!(
                    "`{}`",
                    command_for_repo_contract_target("ota validate", resolved_path)
                ))
            ),
            format!(
                "rerun {}",
                paint_code(&format!(
                    "`{}`",
                    match member {
                        Some(member) => format!("ota run --member {member} {task_name}"),
                        None => format!("ota run {task_name}"),
                    }
                ))
            ),
            task_use_details_step(Some(resolved_path), member),
        ]);

        return Some(structured_field_error_text(
            "RUN",
            &text_path_display,
            &field,
            "Task runtime projection is invalid",
            &why_lines,
            &next_steps,
        ));
    }

    let Some((parsed_task_name, listener_name, issue_kind)) =
        parse_runtime_projection_issue(errors)
    else {
        return None;
    };
    if parsed_task_name != task_name {
        return None;
    }

    match issue_kind {
        RuntimeProjectionIssueKind::BindPortModeAuto => {
            let field =
                format!("tasks.{task_name}.runtime.listeners.{listener_name}.bind.port.mode");
            let why_lines = vec![
                format!(
                    "task `{task_name}` listener `{listener_name}` with `bind.port.mode: auto` is invalid"
                ),
                String::from("`bind.port.mode` only supports `fixed` or `discover`"),
                String::from("`auto` is only valid on `project.host.port.mode`"),
            ];
            let next_steps = vec![
                String::from("change this field to `fixed` or `discover`"),
                format!(
                    "rerun {} to revalidate the contract",
                    paint_code(&format!(
                        "`{}`",
                        command_for_repo_contract_target("ota validate", resolved_path)
                    ))
                ),
                format!(
                    "rerun {}",
                    paint_code(&format!(
                        "`{}`",
                        match member {
                            Some(member) => format!("ota run --member {member} {task_name}"),
                            None => format!("ota run {task_name}"),
                        }
                    ))
                ),
                task_use_details_step(Some(resolved_path), member),
            ];

            Some(structured_field_error_text(
                "RUN",
                &text_path_display,
                &field,
                "Task runtime projection is invalid",
                &why_lines,
                &next_steps,
            ))
        }
        RuntimeProjectionIssueKind::ContainerProjectionRequiresFixedBind => {
            let field =
                format!("tasks.{task_name}.runtime.listeners.{listener_name}.bind.port.mode");
            let why_lines = vec![
                format!(
                    "task `{task_name}` listener `{listener_name}` must use `bind.port.mode: fixed` when `project.host` is declared in a container context"
                ),
                String::from(
                    "container workloads with `project.host` declared must use a fixed internal bind port",
                ),
                String::from(
                    "`project.host.port.mode: auto` can stay auto so Ota can choose the published host port",
                ),
            ];
            let next_steps = vec![
                format!(
                    "change `bind.port.mode` to `fixed` for `tasks.{task_name}.runtime.listeners.{listener_name}`"
                ),
                String::from("set `bind.port.value` to the port the app listens on"),
                String::from(
                    "keep `project.host.port.mode: auto` if you want Ota to choose the host port",
                ),
                format!(
                    "rerun {} to revalidate the contract",
                    paint_code(&format!(
                        "`{}`",
                        command_for_repo_contract_target("ota validate", resolved_path)
                    ))
                ),
                format!(
                    "rerun {}",
                    paint_code(&format!(
                        "`{}`",
                        match member {
                            Some(member) => format!("ota run --member {member} {task_name}"),
                            None => format!("ota run {task_name}"),
                        }
                    ))
                ),
                task_use_details_step(Some(resolved_path), member),
            ];

            Some(structured_field_error_text(
                "RUN",
                &text_path_display,
                &field,
                "Task runtime projection is invalid",
                &why_lines,
                &next_steps,
            ))
        }
        RuntimeProjectionIssueKind::FixedBindPortValueMissing => {
            let field =
                format!("tasks.{task_name}.runtime.listeners.{listener_name}.bind.port.value");
            let why_lines = vec![format!(
                "task `{task_name}` listener `{listener_name}` with `bind.port.mode: fixed` must declare `bind.port.value`"
            )];
            let next_steps = vec![
                format!(
                    "set `bind.port.value` for `tasks.{task_name}.runtime.listeners.{listener_name}`"
                ),
                format!(
                    "rerun {} to revalidate the contract",
                    paint_code(&format!(
                        "`{}`",
                        command_for_repo_contract_target("ota validate", resolved_path)
                    ))
                ),
                task_use_details_step(Some(resolved_path), member),
            ];

            Some(structured_field_error_text(
                "RUN",
                &text_path_display,
                &field,
                "Task runtime projection is invalid",
                &why_lines,
                &next_steps,
            ))
        }
        RuntimeProjectionIssueKind::FixedHostPortValueMissing => {
            let field = format!(
                "tasks.{task_name}.runtime.listeners.{listener_name}.project.host.port.value"
            );
            let why_lines = vec![String::from(
                "`project.host.port.mode: fixed` requires `project.host.port.value`",
            )];
            let next_steps = vec![
                format!(
                    "set `project.host.port.value` for `tasks.{task_name}.runtime.listeners.{listener_name}`"
                ),
                String::from("or change `project.host.port.mode` to `auto`"),
                format!(
                    "rerun {} to revalidate the contract",
                    paint_code(&format!(
                        "`{}`",
                        command_for_repo_contract_target("ota validate", resolved_path)
                    ))
                ),
                task_use_details_step(Some(resolved_path), member),
            ];

            Some(structured_field_error_text(
                "RUN",
                &text_path_display,
                &field,
                "Task runtime projection is invalid",
                &why_lines,
                &next_steps,
            ))
        }
    }
}

fn parse_invalid_bind_port_mode_error(error: &str) -> Option<(String, String)> {
    let error = error.strip_prefix("task `")?;
    let (task_name, remainder) = error.split_once("` listener `")?;
    let (listener_name, remainder) =
        remainder.split_once("` with `bind.port.mode: auto` is invalid")?;
    if !remainder.is_empty() {
        return None;
    }

    Some((task_name.to_string(), listener_name.to_string()))
}

fn parse_missing_bind_port_value_error(error: &str) -> Option<(String, String)> {
    let error = error.strip_prefix("task `")?;
    let (task_name, remainder) = error.split_once("` listener `")?;
    let (listener_name, remainder) =
        remainder.split_once("` with `bind.port.mode: fixed` must declare `bind.port.value`")?;
    if !remainder.is_empty() {
        return None;
    }

    Some((task_name.to_string(), listener_name.to_string()))
}

fn parse_container_host_projection_bind_mode_error(error: &str) -> Option<(String, String)> {
    let error = error.strip_prefix("task `")?;
    let (task_name, remainder) = error.split_once("` listener `")?;
    let (listener_name, remainder) = remainder.split_once(
        "` in a container context must use `bind.port.mode: fixed` when `project.host` is declared",
    )?;
    if !remainder.is_empty() {
        return None;
    }

    Some((task_name.to_string(), listener_name.to_string()))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RuntimeProjectionPrimaryIssueKind {
    MissingPrimary,
    MultiplePrimaries,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct RuntimeProjectionPrimaryIssue {
    task_name: String,
    listeners: Vec<String>,
    kind: RuntimeProjectionPrimaryIssueKind,
}

fn parse_listener_list_from_group(group: &str) -> Option<Vec<String>> {
    let listeners = group
        .split(',')
        .map(str::trim)
        .map(|listener| {
            listener
                .strip_prefix('`')
                .and_then(|value| value.strip_suffix('`'))
                .map(str::to_string)
        })
        .collect::<Option<Vec<_>>>()?;
    if listeners.is_empty() {
        return None;
    }
    Some(listeners)
}

fn parse_missing_primary_listener_error(error: &str) -> Option<(String, Vec<String>)> {
    let error = error.strip_prefix("task `")?;
    let (task_name, remainder) = error.split_once("` declares multiple projected listeners (")?;
    let (listeners, remainder) = remainder.split_once(") but none sets `project.host.primary: true`; mark exactly one projected listener as primary")?;
    if !remainder.is_empty() {
        return None;
    }
    Some((
        task_name.to_string(),
        parse_listener_list_from_group(listeners)?,
    ))
}

fn parse_multiple_primary_listener_error(error: &str) -> Option<(String, Vec<String>)> {
    let error = error.strip_prefix("task `")?;
    let (task_name, remainder) =
        error.split_once("` declares multiple listeners with `project.host.primary: true` (")?;
    let (listeners, remainder) =
        remainder.split_once("); mark exactly one projected listener as primary")?;
    if !remainder.is_empty() {
        return None;
    }
    Some((
        task_name.to_string(),
        parse_listener_list_from_group(listeners)?,
    ))
}

fn parse_runtime_projection_primary_issue(
    errors: &ValidationErrors,
) -> Option<RuntimeProjectionPrimaryIssue> {
    let mut issue: Option<RuntimeProjectionPrimaryIssue> = None;
    for error in errors.errors() {
        let error = error.to_string();
        let (task_name, listeners, kind) = if let Some((task_name, listeners)) =
            parse_missing_primary_listener_error(&error)
        {
            (
                task_name,
                listeners,
                RuntimeProjectionPrimaryIssueKind::MissingPrimary,
            )
        } else if let Some((task_name, listeners)) = parse_multiple_primary_listener_error(&error) {
            (
                task_name,
                listeners,
                RuntimeProjectionPrimaryIssueKind::MultiplePrimaries,
            )
        } else {
            return None;
        };

        match &issue {
            Some(existing)
                if existing.task_name != task_name
                    || existing.listeners != listeners
                    || existing.kind != kind =>
            {
                return None;
            }
            Some(_) => {}
            None => {
                issue = Some(RuntimeProjectionPrimaryIssue {
                    task_name,
                    listeners,
                    kind,
                });
            }
        }
    }
    issue
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RuntimeProjectionIssueKind {
    BindPortModeAuto,
    FixedBindPortValueMissing,
    FixedHostPortValueMissing,
    ContainerProjectionRequiresFixedBind,
}

fn parse_runtime_projection_issue(
    errors: &ValidationErrors,
) -> Option<(String, String, RuntimeProjectionIssueKind)> {
    let mut target: Option<(String, String)> = None;
    let mut has_bind_port_mode_auto = false;
    let mut has_fixed_bind_port_value_missing = false;
    let mut has_fixed_host_port_value_missing = false;
    let mut has_container_projection_requires_fixed_bind = false;

    for error in errors.errors() {
        let error = error.to_string();
        let (task_name, listener_name, kind) = if let Some((task_name, listener_name)) =
            parse_invalid_bind_port_mode_error(&error)
        {
            has_bind_port_mode_auto = true;
            (
                task_name,
                listener_name,
                RuntimeProjectionIssueKind::BindPortModeAuto,
            )
        } else if let Some((task_name, listener_name)) = parse_missing_bind_port_value_error(&error)
        {
            has_fixed_bind_port_value_missing = true;
            (
                task_name,
                listener_name,
                RuntimeProjectionIssueKind::FixedBindPortValueMissing,
            )
        } else if let Some((task_name, listener_name)) =
            parse_container_host_projection_bind_mode_error(&error)
        {
            has_container_projection_requires_fixed_bind = true;
            (
                task_name,
                listener_name,
                RuntimeProjectionIssueKind::ContainerProjectionRequiresFixedBind,
            )
        } else if let Some((task_name, listener_name)) = parse_fixed_host_projection_error(&error) {
            has_fixed_host_port_value_missing = true;
            (
                task_name,
                listener_name,
                RuntimeProjectionIssueKind::FixedHostPortValueMissing,
            )
        } else {
            return None;
        };

        match &target {
            Some((existing_task, existing_listener))
                if existing_task != &task_name || existing_listener != &listener_name =>
            {
                return None;
            }
            Some(_) => {}
            None => target = Some((task_name, listener_name)),
        }

        if matches!(
            kind,
            RuntimeProjectionIssueKind::ContainerProjectionRequiresFixedBind
        ) {
            has_container_projection_requires_fixed_bind = true;
        }
    }

    let (task_name, listener_name) = target?;
    let kind = if has_container_projection_requires_fixed_bind {
        RuntimeProjectionIssueKind::ContainerProjectionRequiresFixedBind
    } else if has_fixed_host_port_value_missing {
        RuntimeProjectionIssueKind::FixedHostPortValueMissing
    } else if has_fixed_bind_port_value_missing {
        RuntimeProjectionIssueKind::FixedBindPortValueMissing
    } else if has_bind_port_mode_auto {
        RuntimeProjectionIssueKind::BindPortModeAuto
    } else {
        return None;
    };

    Some((task_name, listener_name, kind))
}

fn parse_runtime_projection_load_issue(error: &str) -> Option<RuntimeProjectionLoadIssue> {
    let parse_detail = error
        .strip_prefix("failed to parse contract `")?
        .split_once("`: ")?
        .1;
    let (path, detail) = parse_detail.split_once(": ")?;
    if !path.starts_with("tasks.") || !path.contains(".runtime") {
        return None;
    }

    let (detail, location) = split_yaml_error_location(detail);
    if let Some(field) = detail
        .strip_prefix("missing field `")
        .and_then(|field| field.strip_suffix('`'))
    {
        return build_runtime_projection_missing_field_issue(path, field, location.as_deref());
    }

    if let Some((field, expected)) = parse_unknown_field_error_detail(detail) {
        return build_runtime_projection_unknown_field_issue(
            path,
            field,
            expected,
            location.as_deref(),
        );
    }

    if let Some((value, expected)) = parse_unknown_variant_error_detail(detail) {
        return build_runtime_projection_unknown_variant_issue(
            path,
            value,
            expected,
            location.as_deref(),
        );
    }

    None
}

fn split_yaml_error_location(detail: &str) -> (&str, Option<String>) {
    let Some((detail, tail)) = detail.rsplit_once(" at line ") else {
        return (detail, None);
    };
    let Some((line, column)) = tail.split_once(" column ") else {
        return (detail, None);
    };
    if !line.chars().all(|ch| ch.is_ascii_digit()) || !column.chars().all(|ch| ch.is_ascii_digit())
    {
        return (detail, None);
    }

    (
        detail,
        Some(format!("parser stopped at line {line}, column {column}")),
    )
}

fn parse_unknown_field_error_detail(detail: &str) -> Option<(&str, &str)> {
    let detail = detail.strip_prefix("unknown field `")?;
    let (field, expected) = detail.split_once("`, expected ")?;
    Some((field, expected))
}

fn parse_unknown_variant_error_detail(detail: &str) -> Option<(&str, &str)> {
    let detail = detail.strip_prefix("unknown variant `")?;
    let (value, expected) = detail.split_once("`, expected ")?;
    Some((value, expected))
}

fn append_runtime_projection_location(why_lines: &mut Vec<String>, location: Option<&str>) {
    if let Some(location) = location {
        why_lines.push(location.to_string());
    }
}

fn build_runtime_projection_missing_field_issue(
    path: &str,
    missing_field: &str,
    location: Option<&str>,
) -> Option<RuntimeProjectionLoadIssue> {
    let segments = path.split('.').collect::<Vec<_>>();
    let (field, mut why_lines, next_steps) = match (segments.as_slice(), missing_field) {
        (["tasks", task, "runtime"], "kind") => (
            format!("tasks.{task}.runtime.kind"),
            vec![
                format!("task `{task}` runtime is missing `kind`"),
                String::from("`runtime.kind` must be `service`"),
            ],
            vec![String::from("set `runtime.kind` to `service`")],
        ),
        (["tasks", task, "runtime", "listeners", listener], "protocol") => (
            format!("tasks.{task}.runtime.listeners.{listener}.protocol"),
            vec![
                format!("task `{task}` listener `{listener}` is missing `protocol`"),
                String::from("`protocol` must be `http`, `https`, or `tcp`"),
            ],
            vec![String::from("set `protocol` to `http`, `https`, or `tcp`")],
        ),
        (["tasks", task, "runtime", "listeners", listener], "bind") => (
            format!("tasks.{task}.runtime.listeners.{listener}.bind"),
            vec![
                format!("task `{task}` listener `{listener}` is missing `bind`"),
                String::from(
                    "listeners must declare where the workload binds inside its execution context",
                ),
            ],
            vec![String::from("add a `bind` block with `address` and `port`")],
        ),
        (["tasks", task, "runtime", "listeners", listener, "bind"], "address") => (
            format!("tasks.{task}.runtime.listeners.{listener}.bind.address"),
            vec![
                format!("task `{task}` listener `{listener}` bind settings are missing `address`"),
                String::from("`bind.address` is the interface the workload listens on"),
            ],
            vec![String::from(
                "set `bind.address` to the interface the app listens on, for example `0.0.0.0`",
            )],
        ),
        (["tasks", task, "runtime", "listeners", listener, "bind"], "port") => (
            format!("tasks.{task}.runtime.listeners.{listener}.bind.port"),
            vec![
                format!("task `{task}` listener `{listener}` bind settings are missing `port`"),
                String::from("`bind.port` must declare `mode` and, when fixed, `value`"),
            ],
            vec![String::from(
                "add a `bind.port` block with `mode` and, when using `fixed`, `value`",
            )],
        ),
        (
            [
                "tasks",
                task,
                "runtime",
                "listeners",
                listener,
                "bind",
                "port",
            ],
            "mode",
        ) => (
            format!("tasks.{task}.runtime.listeners.{listener}.bind.port.mode"),
            vec![
                format!("task `{task}` listener `{listener}` bind port is missing `mode`"),
                String::from("`bind.port.mode` must be `fixed` or `discover`"),
            ],
            vec![
                String::from("set `bind.port.mode` to `fixed` or `discover`"),
                String::from("use `fixed` when this listener is published through `project.host`"),
            ],
        ),
        (
            [
                "tasks",
                task,
                "runtime",
                "listeners",
                listener,
                "project",
                "host",
            ],
            "address",
        ) => (
            format!("tasks.{task}.runtime.listeners.{listener}.project.host.address"),
            vec![
                format!(
                    "task `{task}` listener `{listener}` host publication is missing `address`"
                ),
                String::from(
                    "`project.host.address` is the host-visible address for this listener",
                ),
            ],
            vec![String::from(
                "set `project.host.address` to the host-visible address, for example `127.0.0.1`",
            )],
        ),
        (
            [
                "tasks",
                task,
                "runtime",
                "listeners",
                listener,
                "project",
                "host",
            ],
            "port",
        ) => (
            format!("tasks.{task}.runtime.listeners.{listener}.project.host.port"),
            vec![
                format!("task `{task}` listener `{listener}` host publication is missing `port`"),
                String::from("`project.host.port` must declare `mode` and, when fixed, `value`"),
            ],
            vec![String::from(
                "add a `project.host.port` block with `mode` and, when using `fixed`, `value`",
            )],
        ),
        (
            [
                "tasks",
                task,
                "runtime",
                "listeners",
                listener,
                "project",
                "host",
                "port",
            ],
            "mode",
        ) => (
            format!("tasks.{task}.runtime.listeners.{listener}.project.host.port.mode"),
            vec![
                format!(
                    "task `{task}` listener `{listener}` host publication port is missing `mode`"
                ),
                String::from("`project.host.port.mode` must be `fixed` or `auto`"),
            ],
            vec![
                String::from(
                    "set `project.host.port.mode` to `auto` if you want Ota to choose the host port",
                ),
                String::from(
                    "or set `project.host.port.mode` to `fixed` and add `project.host.port.value`",
                ),
            ],
        ),
        _ => return None,
    };

    append_runtime_projection_location(&mut why_lines, location);
    Some(RuntimeProjectionLoadIssue {
        field,
        why_lines,
        next_steps,
    })
}

