fn finding_detail_key(severity: FindingSeverity, key: &str) -> String {
    if plain_mode() {
        return key.to_string();
    }
    if key == "Why:" {
        return paint_why_key();
    }
    if key == "Next:" {
        return paint_next_key();
    }
    match severity {
        FindingSeverity::Error => error_key(key),
        _ => paint_key(key),
    }
}

