fn skip_deps_next(
    task_name: &str,
    member: Option<&str>,
    overrides: ExecutionOverrides,
    existing: Option<String>,
) -> String {
    let rerun_command = repo_run_stream_command_with_overrides(
        task_name,
        member,
        ExecutionOverrides {
            skip_deps: false,
            ..overrides
        },
        &[],
    );
    let override_note = format!(
        "rerun `{rerun_command}` without `--skip-deps` to validate the full declared task flow"
    );
    match existing {
        Some(existing) if !existing.trim().is_empty() => format!("{override_note}; {existing}"),
        _ => override_note,
    }
}

