fn workspace_next_steps(next: Option<&str>) -> Vec<String> {
    next.map(|next| {
        next.split("; ")
            .map(str::trim)
            .filter(|part| !part.is_empty() && !part.starts_with("log capture failed:"))
            .map(str::to_string)
            .collect()
    })
    .unwrap_or_default()
}

fn workspace_refresh_receipt_next(repos: &[WorkspaceRepoUpReport]) -> Option<String> {
    if repos.is_empty() || repos.iter().any(|repo| repo.phase != "refresh") {
        return None;
    }

    if repos.iter().any(|repo| repo.status == "PREVIEW") {
        return Some(String::from(
            "review the `Refresh command:` lines, then rerun `ota workspace refresh` to apply the selected sync; run `ota workspace status` after refresh to confirm readiness and drift together",
        ));
    }

    if repos
        .iter()
        .all(|repo| matches!(repo.status.as_str(), "READY" | "SKIPPED"))
    {
        return Some(String::from(
            "run `ota workspace status` to confirm readiness and drift together, or `ota workspace diff` when you want a drift-only recheck",
        ));
    }

    None
}

fn normalize_workspace_up_repo_followups(repos: &mut [WorkspaceRepoUpReport]) {
    for repo in repos {
        let next = repo
            .findings
            .iter()
            .map(|finding| finding.next.as_str())
            .find(|next| !next.trim().is_empty())
            .map(str::to_string);
        repo.next_steps = workspace_next_steps(next.as_deref());
        repo.next = next;
    }
}

fn normalize_workspace_run_repo_followups(repos: &mut [WorkspaceRepoRunReport]) {
    for repo in repos {
        let next = repo
            .findings
            .iter()
            .map(|finding| finding.next.as_str())
            .find(|next| !next.trim().is_empty())
            .map(str::to_string);
        repo.next_steps = workspace_next_steps(next.as_deref());
        repo.next = next;
    }
}

fn normalize_workspace_diff_followups(report: &mut WorkspaceDiffReport) {
    for repo in &mut report.repos {
        let next = repo
            .findings
            .iter()
            .map(|finding| finding.next.as_str())
            .find(|next| !next.trim().is_empty())
            .map(str::to_string);
        repo.next_steps = workspace_next_steps(next.as_deref());
        repo.next = next;
    }

    report.next_steps = workspace_diff_next_steps(&report.repos);
    report.next = if report.next_steps.is_empty() {
        None
    } else {
        Some(report.next_steps.join("; "))
    };
}

fn normalize_workspace_status_followups(report: &mut WorkspaceStatusReport) {
    for repo in &mut report.repos {
        let next = repo
            .findings
            .iter()
            .map(|finding| finding.next.as_str())
            .find(|next| !next.trim().is_empty())
            .map(str::to_string);
        repo.next_steps = workspace_next_steps(next.as_deref());
        repo.next = next;
    }

    report.next_steps = workspace_status_next_steps(&report.repos);
    report.next = if report.next_steps.is_empty() {
        None
    } else {
        Some(report.next_steps.join("; "))
    };
}

fn workspace_diff_next_steps(repos: &[WorkspaceRepoDiffReport]) -> Vec<String> {
    let has_missing = repos.iter().any(|repo| repo.status == "MISSING");
    let has_drift = repos
        .iter()
        .any(|repo| matches!(repo.status.as_str(), "DIRTY" | "DIFFERENT"));
    let has_upstream_fallback_drift = repos.iter().any(|repo| {
        matches!(repo.status.as_str(), "DIRTY" | "DIFFERENT")
            && repo.target_source.as_deref() == Some("upstream_branch")
    });
    let has_unresolved = repos
        .iter()
        .any(|repo| matches!(repo.status.as_str(), "UNRESOLVED" | "MISSING CONTRACT"));

    let mut next_steps = Vec::new();
    if has_unresolved {
        next_steps.push(String::from(
            "inspect the per-repo findings above, then rerun `ota workspace diff` once the comparison blockers are repaired",
        ));
    }
    if has_missing {
        next_steps.push(String::from(
            "run `ota workspace up --dry-run` to preview repo acquisition and setup before repairing missing workspace repos",
        ));
        next_steps.push(String::from(
            "run `ota workspace up` when you are ready to acquire the missing repos",
        ));
    }
    if has_drift {
        next_steps.push(String::from(
            "run `ota workspace refresh --dry-run` to preview the sync commands before mutating repo state",
        ));
        next_steps.push(String::from(
            "run `ota workspace refresh` when you are ready to reconcile workspace drift",
        ));
        if has_upstream_fallback_drift {
            next_steps.push(String::from(
                "declare `source.ref` for repos that should use a contract-owned refresh target instead of local upstream-branch fallback",
            ));
        }
    }
    if has_missing || has_drift {
        next_steps.push(String::from(
            "run `ota workspace status` after workspace changes to confirm readiness and drift together",
        ));
    }
    next_steps
}

fn workspace_status_next_steps(repos: &[WorkspaceRepoStatusReport]) -> Vec<String> {
    let has_missing = repos
        .iter()
        .any(|repo| repo.readiness_status == "NOT ACQUIRED");
    let has_not_ready = repos
        .iter()
        .any(|repo| repo.readiness_status == "NOT READY");
    let has_drift = repos
        .iter()
        .any(|repo| matches!(repo.drift_status.as_str(), "DIRTY" | "DIFFERENT"));
    let has_upstream_fallback_drift = repos.iter().any(|repo| {
        matches!(repo.drift_status.as_str(), "DIRTY" | "DIFFERENT")
            && repo.target_source.as_deref() == Some("upstream_branch")
    });
    let has_unresolved = repos.iter().any(|repo| {
        matches!(
            repo.drift_status.as_str(),
            "UNRESOLVED" | "MISSING CONTRACT" | "MISSING"
        )
    });

    let mut next_steps = Vec::new();
    if has_missing {
        next_steps.push(String::from(
            "run `ota workspace up --dry-run` to preview repo acquisition and setup for the missing workspace repos",
        ));
        next_steps.push(String::from(
            "run `ota workspace up` when you are ready to acquire the missing repos",
        ));
    }
    if has_not_ready {
        next_steps.push(String::from(
            "run `ota workspace doctor` to inspect the readiness blockers before retrying workspace execution",
        ));
    }
    if has_drift {
        next_steps.push(String::from(
            "run `ota workspace refresh --dry-run` to preview the sync commands before reconciling workspace drift",
        ));
        next_steps.push(String::from(
            "run `ota workspace refresh` when you are ready to reconcile workspace drift",
        ));
        if has_upstream_fallback_drift {
            next_steps.push(String::from(
                "declare `source.ref` for repos that should use a contract-owned refresh target instead of local upstream-branch fallback",
            ));
        }
    }
    if has_unresolved && !has_drift {
        next_steps.push(String::from(
            "inspect the per-repo findings above, then rerun `ota workspace status` once the workspace comparison blockers are repaired",
        ));
    }
    next_steps
}

fn workspace_repo_needs_acquisition(repo: &WorkspaceRepoRef) -> bool {
    !repo.present && repo.source_url.is_some() && !repo.path.is_dir()
}

fn acquire_workspace_repo(
    repo: &WorkspaceRepoRef,
    mode: RepoExecutionMode,
) -> Result<CommandRunResult, String> {
    if !workspace_repo_needs_acquisition(repo) {
        return Ok(CommandRunResult {
            exit_code: 0,
            executed_tasks: Vec::new(),
            task_steps: Vec::new(),
            stdout: String::new(),
            stderr: String::new(),
            target: None,
            runtime: None,
            service_termination: None,
            fulfilled_toolchains: Vec::new(),
            host_service_cleanup: Vec::new(),
        });
    }

    let source_url = repo
        .source_url
        .as_deref()
        .ok_or_else(|| format!("workspace repo `{}` has no acquisition source", repo.name))?;

    if let Some(parent) = repo.path.parent() {
        fs::create_dir_all(parent).map_err(|error| {
            format!(
                "failed to create parent directory `{}`: {}",
                parent.display(),
                error
            )
        })?;
    }

    let mut stdout = String::new();
    let mut stderr = String::new();

    let clone = run_git_command(
        &["clone", "--", source_url, &repo.path.display().to_string()],
        None,
        mode,
    )
    .map_err(|error| format!("failed to start git clone for `{}`: {}", repo.name, error))?;
    stdout.push_str(&clone.stdout);
    stderr.push_str(&clone.stderr);
    if clone.exit_code != 0 {
        return Ok(CommandRunResult {
            exit_code: clone.exit_code,
            executed_tasks: Vec::new(),
            task_steps: Vec::new(),
            stdout,
            stderr,
            target: None,
            runtime: None,
            service_termination: None,
            fulfilled_toolchains: Vec::new(),
            host_service_cleanup: Vec::new(),
        });
    }

    if let Some(git_ref) = repo.source_ref.as_deref() {
        let checkout =
            run_git_command(&["checkout", git_ref], Some(&repo.path), mode).map_err(|error| {
                format!(
                    "failed to start git checkout for `{}`: {}",
                    repo.name, error
                )
            })?;
        stdout.push_str(&checkout.stdout);
        stderr.push_str(&checkout.stderr);
        if checkout.exit_code != 0 {
            return Ok(CommandRunResult {
                exit_code: checkout.exit_code,
                executed_tasks: Vec::new(),
                task_steps: Vec::new(),
                stdout,
                stderr,
                target: None,
                runtime: None,
                service_termination: None,
                fulfilled_toolchains: Vec::new(),
                host_service_cleanup: Vec::new(),
            });
        }
    }

    Ok(CommandRunResult {
        exit_code: 0,
        executed_tasks: Vec::new(),
        task_steps: Vec::new(),
        stdout,
        stderr,
        target: None,
        runtime: None,
        service_termination: None,
        fulfilled_toolchains: Vec::new(),
        host_service_cleanup: Vec::new(),
    })
}

fn run_git_command(
    args: &[&str],
    cwd: Option<&Path>,
    mode: RepoExecutionMode,
) -> Result<CommandRunResult, std::io::Error> {
    let mut command = Command::new("git");
    command.args(args);
    if let Some(cwd) = cwd {
        command.current_dir(cwd);
    }

    match mode {
        RepoExecutionMode::Capture => {
            let output = command.output()?;
            Ok(CommandRunResult {
                exit_code: output.status.code().unwrap_or(1),
                executed_tasks: Vec::new(),
                task_steps: Vec::new(),
                stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
                target: None,
                runtime: None,
                service_termination: None,
                fulfilled_toolchains: Vec::new(),
                host_service_cleanup: Vec::new(),
            })
        }
        RepoExecutionMode::Stream => {
            let status = command.status()?;
            Ok(CommandRunResult {
                exit_code: status.code().unwrap_or(1),
                executed_tasks: Vec::new(),
                task_steps: Vec::new(),
                stdout: String::new(),
                stderr: String::new(),
                target: None,
                runtime: None,
                service_termination: None,
                fulfilled_toolchains: Vec::new(),
                host_service_cleanup: Vec::new(),
            })
        }
    }
}

fn resolve_provisioning_execution_target(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
) -> Result<ProvisioningExecutionTarget, Finding> {
    let Some(task_name) = selected_up_primary_task_name(contract, workflow_name) else {
        let (backend, _) = effective_execution(contract, overrides);
        if !matches!(backend, Backend::Container) {
            return Ok(ProvisioningExecutionTarget::Native);
        }
        return Err(Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: String::from("Container execution could not be resolved"),
            why: String::from(
                "`ota up --mode container` requires a canonical workflow task so ota can provision and prepare the selected execution boundary deterministically",
            ),
            next: String::from(
                "declare a default workflow with `prepare`, `setup`, or `run`, or add a repo `setup` task before rerunning `ota up --mode container`",
            ),
        });
    };
    let backend = effective_task_execution(contract, task_name, overrides).backend;
    if !matches!(backend, Backend::Container) {
        return Ok(ProvisioningExecutionTarget::Native);
    }

    match resolve_execution_backend(contract, task_name, overrides) {
        Ok(ResolvedExecutionBackend::Container {
            image,
            platform,
            engine,
            lifecycle,
            ..
        }) => {
            if let Some(failure) = container_backend_probe_failure(&engine) {
                return Err(Finding {
                    identity: None,
                    severity: FindingSeverity::Error,
                    summary: format!("Container execution backend unavailable: {engine}"),
                    why: format!(
                        "container preparation resolved `{engine}`, but `{engine} info` could not reach a usable container backend: {}",
                        failure.details
                    ),
                    next: String::from(
                        "start or repair the selected container engine, or use `--mode native` if the contract allows it, then rerun `ota up`",
                    ),
                });
            }
            Ok(ProvisioningExecutionTarget::Container {
                image,
                platform,
                engine,
                lifecycle,
                container_name: None,
            })
        }
        Ok(ResolvedExecutionBackend::Native { .. }) => Err(Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: String::from("Container execution could not be resolved"),
            why: String::from(
                "`ota up --mode container` selected container execution, but setup resolved to the native host instead of the declared container boundary",
            ),
            next: String::from(
                "inspect `execution.backends.container`, `execution.lifecycle`, and `--mode`, then rerun `ota up --mode container`",
            ),
        }),
        Ok(ResolvedExecutionBackend::Remote { provider, .. }) => Err(Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: String::from("Container execution could not be resolved"),
            why: format!(
                "`ota up --mode container` selected container execution, but setup resolved to remote provider `{provider}` instead of the declared container boundary"
            ),
            next: String::from(
                "inspect `execution.backends.container`, `execution.lifecycle`, and `--mode`, then rerun `ota up --mode container`",
            ),
        }),
        Ok(ResolvedExecutionBackend::BackendProvider { provider, .. }) => Err(Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: String::from("Container execution could not be resolved"),
            why: format!(
                "`ota up --mode container` selected container execution, but setup resolved through backend provider `{provider}` instead of the declared container boundary"
            ),
            next: String::from(
                "inspect `execution.backends.container`, `execution.lifecycle`, and `--mode`, then rerun `ota up --mode container`",
            ),
        }),
        Err(RunError::MissingContainerImage { .. }) => Err(Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: String::from("Container execution is not configured"),
            why: String::from(
                "container preparation requires `execution.backends.container.image` so ota can provision and run setup inside the execution image instead of on the host",
            ),
            next: String::from(
                "add `execution.backends.container.image`, then rerun `ota up --mode container`",
            ),
        }),
        Err(RunError::MissingContainerLifecycle { .. }) => Err(Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: String::from("Container execution lifecycle is not configured"),
            why: String::from(
                "container preparation requires an explicit `execution.lifecycle` so ota can keep provisioning and setup in the same execution boundary",
            ),
            next: String::from("add `execution.lifecycle`, then rerun `ota up --mode container`"),
        }),
        Err(RunError::MissingContainerBackendCli { engines, .. }) => Err(Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: format!("Missing container execution backend CLI: {engines}"),
            why: format!(
                "container execution requires one of these CLIs to be available on PATH: {engines}"
            ),
            next: String::from(
                "install one of the supported container engines, then rerun `ota up --mode container`",
            ),
        }),
        Err(error) => Err(Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: String::from("Container execution could not be resolved"),
            why: render_run_error(error),
            next: String::from(
                "repair the declared container execution settings, then rerun `ota up --mode container`",
            ),
        }),
    }
}

fn up_doctor_mode(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
) -> DoctorMode {
    if let Some(task_name) = selected_up_primary_task_name(contract, workflow_name) {
        return match effective_task_execution(contract, task_name, overrides).backend {
            Backend::Container => DoctorMode::Container,
            Backend::Native | Backend::Remote => DoctorMode::Native,
        };
    }

    match effective_execution(contract, overrides).0 {
        Backend::Container => DoctorMode::Container,
        Backend::Native | Backend::Remote => DoctorMode::Native,
    }
}

fn provisionable_target_key_for_finding(finding: &Finding) -> Option<String> {
    if let Some(name) = finding.summary.strip_prefix("Missing runtime: ") {
        return Some(format!("runtime:{}", strip_finding_context_suffix(name)));
    }
    if let Some(name) = finding
        .summary
        .strip_prefix("Version mismatch for runtime: ")
    {
        return Some(format!("runtime:{}", strip_finding_context_suffix(name)));
    }
    if let Some(name) = finding.summary.strip_prefix("Runtime probe failed: ") {
        return Some(format!("runtime:{}", strip_finding_context_suffix(name)));
    }
    if let Some(name) = finding
        .summary
        .strip_prefix("Unparseable version for runtime: ")
    {
        return Some(format!("runtime:{}", strip_finding_context_suffix(name)));
    }
    if let Some(name) = finding.summary.strip_prefix("Missing tool: ") {
        return Some(format!("tool:{}", strip_finding_context_suffix(name)));
    }
    if let Some(name) = finding.summary.strip_prefix("Version mismatch for tool: ") {
        return Some(format!("tool:{}", strip_finding_context_suffix(name)));
    }
    if let Some(name) = finding.summary.strip_prefix("Tool probe failed: ") {
        return Some(format!("tool:{}", strip_finding_context_suffix(name)));
    }
    if let Some(name) = finding
        .summary
        .strip_prefix("Unparseable version for tool: ")
    {
        return Some(format!("tool:{}", strip_finding_context_suffix(name)));
    }
    None
}

fn strip_finding_context_suffix(name: &str) -> String {
    name.rsplit_once(" (context ").map_or_else(
        || name.trim().to_string(),
        |(name, _)| name.trim().to_string(),
    )
}

fn provisioning_action_key(action: &crate::policy_pack::ProvisioningAction) -> String {
    format!(
        "{}:{}",
        action.target_kind.to_string().to_ascii_lowercase(),
        action.name.trim()
    )
}

fn selected_workflow_task_requirement_surface(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
) -> Option<RequirementSurface> {
    let task_names = contract.selected_workflow_task_closure_names(workflow_name);
    if task_names.is_empty() {
        return None;
    }
    let mut surface = RequirementSurface::default();
    let mut scoped_runtimes = false;
    let mut scoped_tools = false;
    let mut selected_tool_names = BTreeSet::new();
    let retains_global_tool_fallback = task_names.iter().any(|task_name| {
        contract.tasks.get(task_name.as_str()).is_some_and(|task| {
            let effective = effective_task_execution(contract, task_name.as_str(), overrides);
            let target_os = crate::runner::target_os_for_declared_backend(
                effective.backend,
                effective.container,
                current_os(),
            );
            contract
                .resolved_task_requirement_surface_for_execution_for_os(
                    task,
                    effective.backend,
                    effective.context_name,
                    target_os,
                )
                .tools
                .is_empty()
                && matches!(effective.backend, Backend::Native)
        })
    });

    for task_name in &task_names {
        let Some(task) = contract.tasks.get(task_name.as_str()) else {
            continue;
        };
        let effective = effective_task_execution(contract, task_name.as_str(), overrides);
        let target_os = crate::runner::target_os_for_declared_backend(
            effective.backend,
            effective.container,
            current_os(),
        );
        let scoped = contract.resolved_task_requirement_surface_for_execution_for_os(
            task,
            effective.backend,
            effective.context_name,
            target_os,
        );
        if !scoped.runtimes.is_empty() {
            scoped_runtimes = true;
        }
        if !scoped.tools.is_empty() {
            scoped_tools = true;
        }
        for (name, requirement) in &scoped.runtimes {
            surface.runtimes.insert(
                name.clone(),
                contract.resolve_scoped_runtime_requirement(name, requirement),
            );
        }
        for (name, requirement) in &scoped.tools {
            selected_tool_names.insert(name.clone());
            surface.tools.insert(
                name.clone(),
                contract.resolve_scoped_tool_requirement(name, requirement),
            );
        }
        if let Some(exe) =
            task.effective_command_launch_executable_for_backend(effective.backend, target_os)
        {
            selected_tool_names.insert(exe.clone());
            surface
                .tools
                .entry(exe)
                .or_insert(crate::schema::ToolRequirement::Simple(String::from("*")));
        }
        if let Some(context_name) = effective.context_name
            && let Some((_, context)) = named_execution_context(contract, context_name)
        {
            for name in context.requirements.tools.keys() {
                selected_tool_names.insert(name.clone());
            }
            surface.merge(&contract.resolved_context_requirement_surface(context));
        }
        if matches!(effective.backend, Backend::Native) {
            let scoped_native = task.scoped_native_requirements_for_execution_for_os(
                effective.backend,
                effective.context_name,
                target_os,
            );
            surface.merge(
                &contract.native_prerequisite_requirement_surface_for_os(scoped_native, target_os),
            );
        }
    }

    if !scoped_runtimes {
        let mut merged_runtimes = contract.runtimes.clone();
        merged_runtimes.extend(surface.runtimes);
        surface.runtimes = merged_runtimes;
    }
    if !scoped_tools && retains_global_tool_fallback {
        let mut merged_tools = contract.tools.clone();
        merged_tools.extend(surface.tools);
        surface.tools = merged_tools;
    } else if !retains_global_tool_fallback {
        surface
            .tools
            .retain(|tool_name, _| selected_tool_names.contains(tool_name));
    }
    for tool_name in &selected_tool_names {
        if let Some(requirement) = surface.tools.get_mut(tool_name) {
            requirement.force_required();
        }
    }

    let required_tool_names = surface.tools.keys().cloned().collect::<BTreeSet<_>>();
    for (toolchain_name, target_os) in selected_workflow_toolchain_targets(
        contract,
        overrides,
        workflow_name,
        effective_execution(contract, overrides).0,
    ) {
        surface = requirement_surface_with_toolchain_owned_tools_for_required_tools(
            contract,
            &surface,
            &BTreeSet::from([toolchain_name]),
            target_os.as_str(),
            Some(&required_tool_names),
        );
    }

    Some(surface)
}

fn up_requirement_surface(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
) -> RequirementSurface {
    if let Some(surface) =
        selected_workflow_task_requirement_surface(contract, overrides, workflow_name)
    {
        return surface;
    }

    let mut surface = RequirementSurface {
        runtimes: contract.runtimes.clone(),
        tools: contract.tools.clone(),
        presence_only_tools: BTreeSet::new(),
    };
    let (backend, _) = effective_execution(contract, overrides);
    surface.merge(&contract.context_requirement_surface_for_backend(backend));
    surface
}

fn up_policy_requirement_surface(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
) -> RequirementSurface {
    let mut surface = up_requirement_surface(contract, overrides, workflow_name);
    let required_tool_names = surface.tools.keys().cloned().collect::<BTreeSet<_>>();
    let task_names = contract.selected_workflow_task_closure_names(workflow_name);
    if task_names.is_empty() {
        let toolchain_names = contract.selected_workflow_required_toolchain_names(workflow_name);
        return requirement_surface_with_toolchain_owned_capabilities_for_required_tools(
            contract,
            &surface,
            &toolchain_names.into_iter().collect(),
            requirement_target_os_for_backend(effective_execution(contract, overrides).0),
            Some(&required_tool_names),
        );
    }

    for (toolchain_name, target_os) in selected_workflow_toolchain_targets(
        contract,
        overrides,
        workflow_name,
        effective_execution(contract, overrides).0,
    ) {
        surface = requirement_surface_with_toolchain_owned_capabilities_for_required_tools(
            contract,
            &surface,
            &BTreeSet::from([toolchain_name]),
            target_os.as_str(),
            Some(&required_tool_names),
        );
    }

    surface
}

fn requirement_surface_targets_provisioning_action(
    requirement_surface: &RequirementSurface,
    action: &crate::policy_pack::ProvisioningAction,
) -> bool {
    match action.target_kind {
        crate::policy_pack::ProvisioningTargetKind::Runtime => requirement_surface
            .runtimes
            .contains_key(action.name.as_str()),
        crate::policy_pack::ProvisioningTargetKind::Tool => {
            requirement_surface.tools.contains_key(action.name.as_str())
        }
    }
}

fn selected_up_provisioning_actions(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
    preflight: &DoctorReport,
) -> Vec<crate::policy_pack::ProvisioningAction> {
    let requirement_surface = up_policy_requirement_surface(contract, overrides, workflow_name);
    let mut actions: Vec<crate::policy_pack::ProvisioningAction> = preflight
        .provisioning
        .as_ref()
        .map(|provisioning| {
            provisioning
                .request
                .actions
                .iter()
                .filter(|action| {
                    requirement_surface_targets_provisioning_action(&requirement_surface, action)
                        && preflight
                            .findings
                            .iter()
                            .any(|finding| finding_targets_provisioning_action(finding, action))
                })
                .cloned()
                .collect()
        })
        .unwrap_or_default();
    actions.extend(selected_up_native_package_provisioning_actions(
        contract,
        overrides,
        workflow_name,
        preflight,
    ));
    actions
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct RequirementActivationAction {
    tool_name: String,
    backend: Backend,
    acquisition: ToolAcquisitionSpec,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeRequirementActivationAction {
    prerequisite_name: String,
    activation: crate::schema::NativePrerequisiteActivationSpec,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeRequirementPreparationAction {
    prerequisite_name: String,
    summary: String,
}

fn requirement_surface_activation_actions(
    requirement_surface: &RequirementSurface,
    target_os: &str,
    backend: Backend,
) -> Vec<RequirementActivationAction> {
    requirement_surface
        .tools
        .iter()
        .filter_map(|(name, requirement)| {
            requirement
                .acquisition_for_os(target_os)
                .filter(|acquisition| acquisition.provider.is_activation_provider())
                .cloned()
                .map(|acquisition| RequirementActivationAction {
                    tool_name: name.clone(),
                    backend,
                    acquisition,
                })
        })
        .collect()
}

fn activation_action_command(action: &RequirementActivationAction) -> String {
    match action.acquisition.provider {
        ToolAcquisitionProvider::Corepack => format!(
            "corepack enable && corepack prepare {}@{} --activate",
            action
                .acquisition
                .package
                .as_deref()
                .expect("validated corepack acquisition package"),
            action
                .acquisition
                .version
                .as_deref()
                .expect("validated corepack acquisition version")
        ),
        ToolAcquisitionProvider::Command => {
            let shell = action
                .acquisition
                .shell
                .expect("validated command acquisition shell");
            let run = action
                .acquisition
                .run
                .as_deref()
                .expect("validated command acquisition run");
            match shell {
                crate::schema::NativePrerequisiteActivationShell::Sh
                | crate::schema::NativePrerequisiteActivationShell::Bash
                | crate::schema::NativePrerequisiteActivationShell::Zsh => format!(
                    "{} -lc {}",
                    native_prerequisite_activation_shell_label(shell),
                    shell_single_quote(run)
                ),
                crate::schema::NativePrerequisiteActivationShell::Pwsh => format!(
                    "pwsh -NoProfile -NonInteractive -Command {}",
                    shell_single_quote(run)
                ),
                crate::schema::NativePrerequisiteActivationShell::Cmd => {
                    format!("cmd /d /s /c {}", shell_single_quote(run))
                }
            }
        }
        ToolAcquisitionProvider::Apt
        | ToolAcquisitionProvider::ReleaseAsset
        | ToolAcquisitionProvider::Brew
        | ToolAcquisitionProvider::Winget
        | ToolAcquisitionProvider::Choco
        | ToolAcquisitionProvider::Scoop => {
            unreachable!("provisioning-owned tool acquisition is not activation-owned")
        }
    }
}

fn activation_action_key(action: &RequirementActivationAction) -> String {
    format!("tool:{}", action.tool_name)
}

fn finding_targets_activation_action(
    finding: &Finding,
    action: &RequirementActivationAction,
) -> bool {
    if let Some(key) = provisionable_target_key_for_finding(finding) {
        return key == activation_action_key(action);
    }

    if finding
        .summary
        .strip_prefix("Missing tool: ")
        .is_some_and(|name| name.trim() == action.tool_name)
    {
        return true;
    }

    match action.acquisition.provider {
        ToolAcquisitionProvider::Corepack => {
            finding.summary == "Missing tool activation provider: corepack"
                && finding.why.contains(action.tool_name.as_str())
        }
        ToolAcquisitionProvider::Command => {
            let shell = action
                .acquisition
                .shell
                .expect("validated command acquisition shell");
            finding.summary
                == format!(
                    "Missing tool activation provider: {}",
                    native_prerequisite_activation_shell_label(shell)
                )
                && finding.why.contains(action.tool_name.as_str())
        }
        ToolAcquisitionProvider::Apt
        | ToolAcquisitionProvider::ReleaseAsset
        | ToolAcquisitionProvider::Brew
        | ToolAcquisitionProvider::Winget
        | ToolAcquisitionProvider::Choco
        | ToolAcquisitionProvider::Scoop => false,
    }
}

fn selected_up_activation_actions(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
    preflight: &DoctorReport,
) -> Vec<RequirementActivationAction> {
    selected_activation_actions_for_mode(
        contract,
        overrides,
        workflow_name,
        preflight,
        up_doctor_mode(contract, overrides, workflow_name),
    )
}

fn selected_doctor_activation_actions(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
    preflight: &DoctorReport,
    mode: DoctorMode,
) -> Vec<RequirementActivationAction> {
    if mode != DoctorMode::Native {
        return Vec::new();
    }
    selected_activation_actions_for_mode(contract, overrides, workflow_name, preflight, mode)
}

fn selected_activation_actions_for_mode(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
    preflight: &DoctorReport,
    mode: DoctorMode,
) -> Vec<RequirementActivationAction> {
    let fallback_backend = match mode {
        DoctorMode::Container => Backend::Container,
        DoctorMode::Native => Backend::Native,
        DoctorMode::Remote => Backend::Remote,
    };
    let policy_provisioned_tools =
        selected_up_policy_provisioned_tool_names(contract, overrides, workflow_name, preflight);

    selected_workflow_activation_candidates(contract, overrides, workflow_name, fallback_backend)
        .into_iter()
        .filter(|action| {
            !policy_provisioned_tools.contains(action.tool_name.as_str())
                && (preflight
                    .findings
                    .iter()
                    .any(|finding| finding_targets_activation_action(finding, action))
                    || corepack_activation_is_required_for_native_execution(action)
                    || activation_action_needs_local_bootstrap(action))
        })
        .collect()
}

fn selected_workflow_activation_candidates(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
    fallback_backend: Backend,
) -> Vec<RequirementActivationAction> {
    let task_names = contract.selected_workflow_task_closure_names(workflow_name);
    if task_names.is_empty() {
        return requirement_surface_activation_actions(
            &up_activation_requirement_surface(contract, overrides, workflow_name),
            requirement_target_os_for_backend(fallback_backend),
            fallback_backend,
        );
    }

    let mut actions = Vec::new();
    for task_name in task_names {
        let effective = effective_task_execution(contract, task_name.as_str(), overrides);
        let target_os = crate::runner::target_os_for_declared_backend(
            effective.backend,
            effective.container,
            current_os(),
        );
        let Some(requirement_surface) =
            selected_task_requirement_surface(contract, task_name.as_str(), overrides)
        else {
            continue;
        };
        for action in requirement_surface_activation_actions(
            &requirement_surface,
            target_os,
            effective.backend,
        ) {
            if !actions.contains(&action) {
                actions.push(action);
            }
        }
    }
    actions
}

fn corepack_activation_is_required_for_native_execution(
    action: &RequirementActivationAction,
) -> bool {
    action.backend == Backend::Native
        && matches!(
            action.acquisition.provider,
            ToolAcquisitionProvider::Corepack
        )
}

fn activation_action_needs_local_bootstrap(action: &RequirementActivationAction) -> bool {
    match action.acquisition.provider {
        ToolAcquisitionProvider::Corepack => {
            !crate::doctor::command_available("corepack") && crate::doctor::command_available("npm")
        }
        ToolAcquisitionProvider::Command => false,
        ToolAcquisitionProvider::Apt
        | ToolAcquisitionProvider::ReleaseAsset
        | ToolAcquisitionProvider::Brew
        | ToolAcquisitionProvider::Winget
        | ToolAcquisitionProvider::Choco
        | ToolAcquisitionProvider::Scoop => false,
    }
}

fn up_activation_requirement_surface(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
) -> RequirementSurface {
    let requirement_surface = up_requirement_surface(contract, overrides, workflow_name);
    let required_tool_names = requirement_surface
        .tools
        .keys()
        .cloned()
        .collect::<BTreeSet<_>>();
    let task_names = contract.selected_workflow_task_closure_names(workflow_name);
    if task_names.is_empty() {
        let toolchain_names = contract.selected_workflow_required_toolchain_names(workflow_name);
        return requirement_surface_with_toolchain_owned_tools_for_required_tools(
            contract,
            &requirement_surface,
            &toolchain_names.into_iter().collect(),
            requirement_target_os_for_backend(effective_execution(contract, overrides).0),
            Some(&required_tool_names),
        );
    }

    let mut surface = requirement_surface;

    for (toolchain_name, target_os) in selected_workflow_toolchain_targets(
        contract,
        overrides,
        workflow_name,
        effective_execution(contract, overrides).0,
    ) {
        surface = requirement_surface_with_toolchain_owned_tools_for_required_tools(
            contract,
            &surface,
            &BTreeSet::from([toolchain_name]),
            target_os.as_str(),
            Some(&required_tool_names),
        );
    }

    surface
}

fn current_requirement_platform() -> &'static str {
    match std::env::consts::OS {
        "macos" => "macos",
        "windows" => "windows",
        other => other,
    }
}

fn requirement_target_os_for_backend(backend: Backend) -> &'static str {
    match backend {
        Backend::Container => "linux",
        Backend::Native | Backend::Remote => current_requirement_platform(),
    }
}

fn selected_workflow_toolchain_targets(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
    fallback_backend: Backend,
) -> BTreeSet<(String, String)> {
    let task_names = contract.selected_workflow_task_closure_names(workflow_name);
    if task_names.is_empty() {
        let target_os = requirement_target_os_for_backend(fallback_backend).to_string();
        return contract
            .selected_workflow_required_toolchain_names(workflow_name)
            .into_iter()
            .map(|name| (name, target_os.clone()))
            .collect();
    }

    let mut targets = BTreeSet::new();
    for task_name in task_names {
        let effective = effective_task_execution(contract, task_name.as_str(), overrides);
        let target_os = crate::runner::target_os_for_declared_backend(
            effective.backend,
            effective.container,
            current_os(),
        )
        .to_string();
        targets.extend(
            selected_task_scoped_toolchain_names(contract, task_name.as_str(), overrides)
                .into_iter()
                .map(|name| (name, target_os.clone())),
        );
    }
    targets
}

fn selected_up_toolchain_preview_actions(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
    fallback_backend: Backend,
) -> Vec<String> {
    let required_tool_names =
        selected_workflow_task_requirement_surface(contract, overrides, workflow_name)
            .map(|surface| surface.tools.into_keys().collect::<BTreeSet<_>>())
            .unwrap_or_else(|| {
                up_requirement_surface(contract, overrides, workflow_name)
                    .tools
                    .into_keys()
                    .collect()
            });
    let task_names = contract.selected_workflow_task_closure_names(workflow_name);
    let mut actions = Vec::new();
    let mut seen = BTreeSet::new();

    if task_names.is_empty() {
        let target_os = requirement_target_os_for_backend(fallback_backend);
        for toolchain_name in contract.selected_workflow_required_toolchain_names(workflow_name) {
            let Some(toolchain) = contract.toolchains.get(toolchain_name.as_str()) else {
                continue;
            };
            if !toolchain.active_for_os(target_os) {
                continue;
            }
            let action = declared_toolchain_preview_action_for_required_tools(
                toolchain_name.as_str(),
                toolchain,
                target_os,
                &required_tool_names,
            );
            if seen.insert(action.clone()) {
                actions.push(action);
            }
        }
        return actions;
    }

    for (toolchain_name, target_os) in
        selected_workflow_toolchain_targets(contract, overrides, workflow_name, fallback_backend)
    {
        let Some(toolchain) = contract.toolchains.get(toolchain_name.as_str()) else {
            continue;
        };
        if !toolchain.active_for_os(target_os.as_str()) {
            continue;
        }
        let action = declared_toolchain_preview_action_for_required_tools(
            toolchain_name.as_str(),
            toolchain,
            target_os.as_str(),
            &required_tool_names,
        );
        if seen.insert(action.clone()) {
            actions.push(action);
        }
    }

    actions
}

fn selected_up_toolchain_run_fulfillment_targets(
    contract: &Contract,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
    fallback_backend: Backend,
) -> Vec<ToolchainRunFulfillmentTarget> {
    let task_names = contract.selected_workflow_task_closure_names(workflow_name);
    let mut targets = BTreeSet::new();

    if task_names.is_empty() {
        let target_os = requirement_target_os_for_backend(fallback_backend);
        for toolchain_name in contract.selected_workflow_required_toolchain_names(workflow_name) {
            let Some(toolchain) = contract.toolchains.get(toolchain_name.as_str()) else {
                continue;
            };
            if toolchain.fulfillment_mode() != crate::schema::ToolchainFulfillmentMode::Run
                || !toolchain.active_for_os(target_os)
            {
                continue;
            }
            targets.insert(ToolchainRunFulfillmentTarget {
                toolchain_name,
                target_os: target_os.to_string(),
            });
        }
        return targets.into_iter().collect();
    }

    for (toolchain_name, target_os) in
        selected_workflow_toolchain_targets(contract, overrides, workflow_name, fallback_backend)
    {
        let Some(toolchain) = contract.toolchains.get(toolchain_name.as_str()) else {
            continue;
        };
        if toolchain.fulfillment_mode() != crate::schema::ToolchainFulfillmentMode::Run
            || !toolchain.active_for_os(target_os.as_str())
        {
            continue;
        }
        targets.insert(ToolchainRunFulfillmentTarget {
            toolchain_name,
            target_os,
        });
    }

    targets.into_iter().collect()
}

