fn render_up_preview_activation_action(action: &RequirementActivationAction) -> String {
    match action.acquisition.provider {
        ToolAcquisitionProvider::Corepack => format!(
            "activate tool `{}` via `corepack` (`{}@{}`)",
            action.tool_name,
            action
                .acquisition
                .package
                .as_deref()
                .expect("validated corepack acquisition package"),
            action
                .acquisition
                .version
                .as_deref()
                .expect("validated corepack acquisition version")
        ),
        ToolAcquisitionProvider::Command => format!(
            "activate tool `{}` via `{}` command",
            action.tool_name,
            action
                .acquisition
                .shell
                .map(native_prerequisite_activation_shell_label)
                .unwrap_or("command")
        ),
        ToolAcquisitionProvider::Apt
        | ToolAcquisitionProvider::ReleaseAsset
        | ToolAcquisitionProvider::Brew
        | ToolAcquisitionProvider::Winget
        | ToolAcquisitionProvider::Choco
        | ToolAcquisitionProvider::Scoop => {
            unreachable!("provisioning-owned tool acquisition is not activation-owned")
        }
    }
}

