fn append_up_preview_service_actions_for_workflow(
    contract: &Contract,
    contract_path: &Path,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
    run_behavior_preference: UpRunBehaviorPreference,
    plan: &mut UpPreviewPlan,
) {
    for selector in selected_workflow_instance_prerequisite_selectors(contract, workflow_name) {
        push_preview_plan_action(
            &mut plan.actions,
            &mut plan.staged_actions,
            "prepare",
            format!(
                "activate prerequisite workflow instance `{selector}` before the selected instance"
            ),
        );
    }
    let pre_setup_services = up_pre_setup_service_closure(contract, workflow_name);
    let post_setup_services =
        remaining_up_required_service_closure(contract, workflow_name, &pre_setup_services);
    let setup_task = selected_up_setup_task_name(contract, workflow_name);
    let activation_task = selected_up_activation_task_name(contract, workflow_name);

    if let Some(prepare_task) = selected_up_prepare_task_name(contract, workflow_name) {
        push_preview_plan_action(
            &mut plan.actions,
            &mut plan.staged_actions,
            "prepare",
            format!("run host prepare task `{prepare_task}`"),
        );
    } else if let Some(prepare_action) = selected_up_prepare_action(contract, workflow_name) {
        push_preview_plan_action(
            &mut plan.actions,
            &mut plan.staged_actions,
            "prepare",
            format!(
                "run workflow-owned host prepare action `{}`",
                prepare_action.preview()
            ),
        );
    }
    append_up_preview_service_phase_actions(
        contract,
        &pre_setup_services,
        &mut plan.actions,
        &mut plan.staged_actions,
        setup_task.map(|task| format!("before `{task}`")).as_deref(),
    );
    if let Some(setup_task) = setup_task {
        push_preview_plan_action(
            &mut plan.actions,
            &mut plan.staged_actions,
            "setup",
            format!("run task `{setup_task}`"),
        );
    }

    append_up_preview_service_phase_actions(
        contract,
        &post_setup_services,
        &mut plan.actions,
        &mut plan.staged_actions,
        setup_task.map(|task| format!("after `{task}`")).as_deref(),
    );

    if let Some(run_task) = activation_task {
        let requested_task = contract.tasks.get(run_task).map(|task| {
            let effective = effective_task_execution(contract, run_task, overrides);
            let target_os = crate::runner::target_os_for_declared_backend(
                effective.backend,
                effective.container,
                current_os(),
            );
            TaskSummary::from_spec_with_overrides(run_task, task, target_os, contract, overrides)
        });
        let execution_plan =
            resolve_execution_plan_for_task(contract, contract_path, run_task, overrides).ok();
        if let (Some(requested_task), Some(execution_plan)) = (requested_task, execution_plan) {
            let effective_execution = effective_task_execution(contract, run_task, overrides);
            let effective_depends_on = contract
                .tasks
                .get(run_task)
                .map(|task| task.depends_on_for_backend(effective_execution.backend))
                .unwrap_or_default();
            let dependency_chain = if overrides.skip_deps {
                vec![run_task.to_string()]
            } else if let Ok(task_plan) =
                crate::runner::plan_task_execution_with_overrides(contract, run_task, overrides)
            {
                task_plan.tasks.clone()
            } else {
                vec![run_task.to_string()]
            };

            plan.dependency_chain = dependency_chain;
            plan.dependency_steps =
                planned_dependency_steps_for_task(contract, Some(run_task), Some(overrides));

            if !overrides.skip_deps {
                for dependency in plan
                    .dependency_chain
                    .iter()
                    .take(plan.dependency_chain.len().saturating_sub(1))
                {
                    push_preview_plan_action(
                        &mut plan.actions,
                        &mut plan.staged_actions,
                        dependency_task_stage_family(contract, dependency, overrides),
                        format!("would run planned step `{dependency}` before `{run_task}`"),
                    );
                }
            } else if !effective_depends_on.is_empty() {
                push_preview_plan_action(
                    &mut plan.actions,
                    &mut plan.staged_actions,
                    "prepare",
                    format!("skip declared depends_on before requested task `{run_task}`"),
                );
            }
            push_preview_plan_action(
                &mut plan.actions,
                &mut plan.staged_actions,
                dependency_task_stage_family(contract, run_task, overrides),
                run_preview_task_execution_action(
                    contract,
                    run_task,
                    overrides,
                    &requested_task,
                    &execution_plan,
                ),
            );
            if matches!(effective_execution.lifecycle, Some(Lifecycle::Persistent)) {
                push_preview_plan_action(
                    &mut plan.actions,
                    &mut plan.staged_actions,
                    "proof",
                    String::from("would persist durable task logs under `.ota/state/logs/`"),
                );
            }
        } else {
            push_preview_plan_action(
                &mut plan.actions,
                &mut plan.staged_actions,
                "verify",
                format!("activate workflow task `{run_task}`"),
            );
        }
    }
    if plan.dependency_steps.is_empty() {
        let preview_task = selected_up_setup_task_name(contract, workflow_name)
            .or_else(|| selected_up_prepare_task_name(contract, workflow_name));
        if let Some(task_name) = preview_task {
            plan.dependency_chain = vec![task_name.to_string()];
            plan.dependency_steps =
                planned_dependency_steps_for_task(contract, Some(task_name), Some(overrides));
        }
    }
    if matches!(run_behavior_preference, UpRunBehaviorPreference::Attach)
        && let Some(attach_task) = selected_up_attach_task_name(contract, workflow_name)
    {
        push_preview_plan_action(
            &mut plan.actions,
            &mut plan.staged_actions,
            "verify",
            format!("attach to the declared interactive workflow session via task `{attach_task}`"),
        );
    }
}

fn append_up_preview_service_phase_actions(
    contract: &Contract,
    selected_services: &BTreeSet<String>,
    actions: &mut Vec<String>,
    staged_actions: &mut Vec<crate::output::PreviewStageAction>,
    phase_suffix: Option<&str>,
) {
    for service_name in service_start_order_for(contract, selected_services) {
        let service = contract
            .services
            .get(service_name.as_str())
            .expect("validated service should exist");

        if let Some(producer) = service.producer.as_ref() {
            let action = format!(
                "start workspace repo `{}` task `{}` for service `{service_name}`",
                producer.repo, producer.task
            );
            match phase_suffix {
                Some(phase_suffix) => push_preview_plan_action(
                    actions,
                    staged_actions,
                    "setup",
                    format!("{action} {phase_suffix}"),
                ),
                None => push_preview_plan_action(actions, staged_actions, "setup", action),
            }
        } else if service.start_command(service_name.as_str()).is_some() {
            match phase_suffix {
                Some(phase_suffix) => push_preview_plan_action(
                    actions,
                    staged_actions,
                    "setup",
                    format!("start service `{service_name}` {phase_suffix}"),
                ),
                None => push_preview_plan_action(
                    actions,
                    staged_actions,
                    "setup",
                    format!("start service `{service_name}`"),
                ),
            }
        }
    }

    for service_name in selected_services {
        let service = contract
            .services
            .get(service_name.as_str())
            .expect("validated service should exist");
        if service.producer.is_some()
            || service.healthcheck.is_some()
            || service.readiness.is_some()
            || !service.endpoints.is_empty()
        {
            match phase_suffix {
                Some(phase_suffix) => push_preview_plan_action(
                    actions,
                    staged_actions,
                    "proof",
                    format!("verify service `{service_name}` readiness {phase_suffix}"),
                ),
                None => push_preview_plan_action(
                    actions,
                    staged_actions,
                    "proof",
                    format!("verify service `{service_name}` readiness"),
                ),
            }
        }
    }
}

#[cfg(test)]
fn build_up_preview(
    contract: &Contract,
    resolved_path: &Path,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
    run_behavior_preference: UpRunBehaviorPreference,
    preflight: &DoctorReport,
) -> RepoUpPreview {
    build_up_preview_with_actor(
        contract,
        resolved_path,
        overrides,
        workflow_name,
        run_behavior_preference,
        preflight,
        false,
    )
}

fn build_up_preview_with_actor(
    contract: &Contract,
    resolved_path: &Path,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
    run_behavior_preference: UpRunBehaviorPreference,
    preflight: &DoctorReport,
    agent: bool,
) -> RepoUpPreview {
    let primary_task = selected_up_primary_task_name(contract, workflow_name);
    let (backend, lifecycle, target, context, image) = if let Some(task_name) = primary_task {
        let effective = effective_task_execution(contract, task_name, overrides);
        (
            effective.backend,
            effective.lifecycle,
            effective_task_execution_target(resolved_path, effective),
            reported_task_context_for_backend(contract, task_name, effective.backend)
                .map(str::to_string),
            effective
                .container
                .map(|container| container.image.clone())
                .filter(|_| matches!(effective.backend, Backend::Container)),
        )
    } else {
        let (backend, lifecycle) = effective_execution(contract, overrides);
        (
            backend,
            lifecycle,
            phase_execution_target(contract, resolved_path, backend, lifecycle, None),
            None,
            None,
        )
    };
    let mut actions = Vec::new();
    let mut staged_actions = Vec::new();
    let mut skipped = Vec::new();
    let mut staged_skipped = Vec::new();
    let selected_actions =
        selected_up_provisioning_actions(contract, overrides, workflow_name, preflight);
    let native_preparation_actions =
        selected_up_native_preparation_actions(contract, overrides, workflow_name, preflight);
    let activation_actions =
        selected_up_activation_actions(contract, overrides, workflow_name, preflight);
    let toolchain_actions =
        selected_up_toolchain_preview_actions(contract, overrides, workflow_name, backend);
    let toolchain_fulfillment_targets =
        selected_up_toolchain_run_fulfillment_targets(contract, overrides, workflow_name, backend);
    let policy_provisioned_tools =
        selected_up_policy_provisioned_tool_names(contract, overrides, workflow_name, preflight);

    if let Some(provisioning) = preflight.provisioning.as_ref() {
        for action in &provisioning.request.actions {
            if selected_actions.contains(action) {
                push_preview_plan_action(
                    &mut actions,
                    &mut staged_actions,
                    "prepare",
                    render_up_preview_provision_action(action),
                );
            } else {
                push_preview_plan_action(
                    &mut skipped,
                    &mut staged_skipped,
                    "prepare",
                    render_up_preview_skip_action(action),
                );
            }
        }
    }

    for action in &native_preparation_actions {
        push_preview_plan_action(
            &mut actions,
            &mut staged_actions,
            "prepare",
            render_up_preview_native_preparation_action(action),
        );
    }
    if let Some(action) =
        selected_workflow_env_profile_render_preview_action(contract, workflow_name)
    {
        push_preview_plan_action(&mut actions, &mut staged_actions, "prepare", action);
    }
    for action in toolchain_actions {
        push_preview_plan_action(&mut actions, &mut staged_actions, "prepare", action);
    }
    for action in &activation_actions {
        push_preview_plan_action(
            &mut actions,
            &mut staged_actions,
            "setup",
            render_up_preview_activation_action(action),
        );
    }
    for action in selected_up_native_activation_actions(contract, overrides, workflow_name) {
        push_preview_plan_action(
            &mut actions,
            &mut staged_actions,
            "setup",
            render_up_preview_native_activation_action(&action),
        );
    }
    let fallback_backend = match up_doctor_mode(contract, overrides, workflow_name) {
        DoctorMode::Container => Backend::Container,
        DoctorMode::Native => Backend::Native,
        DoctorMode::Remote => Backend::Remote,
    };
    let mut seen_skipped_activation = BTreeSet::new();
    for action in selected_workflow_activation_candidates(
        contract,
        overrides,
        workflow_name,
        fallback_backend,
    ) {
        let rendered = render_up_preview_skipped_activation_action(&action);
        if policy_provisioned_tools.contains(action.tool_name.as_str())
            && seen_skipped_activation.insert(rendered.clone())
        {
            push_preview_plan_action(&mut skipped, &mut staged_skipped, "setup", rendered);
        }
    }

    let mut plan = UpPreviewPlan {
        actions: Vec::new(),
        staged_actions: Vec::new(),
        skipped: Vec::new(),
        staged_skipped: Vec::new(),
        dependency_chain: Vec::new(),
        dependency_steps: Vec::new(),
    };
    plan.actions = actions;
    plan.staged_actions = staged_actions;
    plan.skipped = skipped;
    plan.staged_skipped = staged_skipped;

    append_up_preview_service_actions_for_workflow(
        contract,
        resolved_path,
        overrides,
        workflow_name,
        run_behavior_preference,
        &mut plan,
    );
    enrich_hydration_provenance_for_run_plan(contract, resolved_path, &mut plan.dependency_steps);

    push_preview_plan_action(
        &mut plan.actions,
        &mut plan.staged_actions,
        "proof",
        String::from("re-check repo readiness"),
    );

    let mut summary = doctor_preview_summary_for_resolution(
        preflight,
        crate::workspace::agent_verdict_from_agent(contract.agent.as_ref()),
        &selected_actions,
        &activation_actions,
    );
    if matches!(summary.verdict, DoctorVerdict::NotReady)
        && preview_errors_are_fully_resolvable_with_toolchain_fulfillment(
            &preflight.findings,
            &selected_actions,
            &activation_actions,
            &toolchain_fulfillment_targets,
        )
    {
        summary.verdict = DoctorVerdict::Risky;
    }

    RepoUpPreview {
        summary: summary.clone(),
        contract_identity: repo_contract_identity(contract),
        execution: UpPreviewExecution {
            backend: format_backend(backend).to_string(),
            context,
            lifecycle: lifecycle.map(format_lifecycle).map(str::to_string),
            image,
            target,
            task: primary_task.map(String::from),
        },
        overrides: execution_plan_overrides(overrides),
        plan,
        governance: governance_evaluation_for_workflow_preview(
            contract,
            workflow_name,
            overrides,
            run_behavior_preference,
            &summary,
            agent,
            None,
        ),
        sandbox_admission: None,
        crossing_grant_admission: None,
        blockers: preflight
            .findings
            .iter()
            .filter(|finding| {
                finding.severity == FindingSeverity::Error
                    && !activation_actions
                        .iter()
                        .any(|action| finding_targets_activation_action(finding, action))
                    && !selected_actions
                        .iter()
                        .any(|action| finding_targets_provisioning_action(finding, action))
                    && !toolchain_fulfillment_targets
                        .iter()
                        .any(|target| finding_targets_toolchain_run_fulfillment(finding, target))
            })
            .cloned()
            .collect(),
    }
}

#[cfg(test)]
fn preview_receipt(
    contract: &Contract,
    resolved_path: &Path,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
    status: &'static str,
    findings: &[Finding],
) -> ExecutionReceipt {
    preview_receipt_with_policy_snapshot(
        contract,
        resolved_path,
        overrides,
        workflow_name,
        status,
        findings,
        None,
    )
}

fn preview_receipt_with_policy_snapshot(
    contract: &Contract,
    resolved_path: &Path,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
    status: &'static str,
    findings: &[Finding],
    policy_snapshot: Option<DoctorPolicySnapshot<'_>>,
) -> ExecutionReceipt {
    let preview_task = selected_up_setup_task_name(contract, workflow_name)
        .or_else(|| selected_up_prepare_task_name(contract, workflow_name))
        .or_else(|| selected_up_primary_task_name(contract, workflow_name));
    let preview_backend = preview_task
        .map(|task_name| effective_task_execution(contract, task_name, overrides).backend)
        .unwrap_or_else(|| {
            phase_execution_backend(&selected_phase_execution_context(
                contract,
                resolved_path,
                overrides,
            ))
            .unwrap_or(Backend::Native)
        });
    let mut receipt = repo_execution_receipt_with_overrides_and_policy_snapshot(
        resolved_path,
        contract,
        if let Some(task_name) = preview_task {
            task_phase_execution_context(contract, resolved_path, task_name, overrides, None)
        } else {
            selected_phase_execution_context(contract, resolved_path, overrides)
        },
        status,
        "preview",
        workflow_name,
        None,
        preview_task,
        findings,
        None,
        findings.first().map(|finding| finding.next.clone()),
        preview_task.map(|_| overrides),
        policy_snapshot,
    );
    receipt.toolchains =
        selected_workflow_toolchain_summaries(contract, overrides, workflow_name, preview_backend);
    receipt.policy = execution_policy_lines_for_toolchain_names(
        contract,
        resolved_path,
        preview_backend,
        &toolchain_summary_names(&receipt.toolchains),
        policy_snapshot,
    );
    receipt
}

fn run_up_task(
    contract: &Contract,
    resolved_path: &Path,
    task_name: &str,
    overrides: ExecutionOverrides,
    policy_env: Option<&BTreeMap<String, String>>,
    mode: RepoExecutionMode,
    agent: bool,
) -> Result<CommandRunResult, RunError> {
    match mode {
        RepoExecutionMode::Stream => {
            let terminal_passthrough =
                plan_task_execution_with_overrides(contract, task_name, overrides)
                    .ok()
                    .is_some_and(|plan| {
                        plan.steps.iter().any(|step| {
                            let Some(posture) = task_command_interaction_posture_for_backend(
                                contract,
                                step.task.as_str(),
                                ExecutionOverrides {
                                    backend: Some(step.backend),
                                    ..overrides
                                },
                            ) else {
                                return false;
                            };
                            resolve_command_terminal_passthrough(
                                posture,
                                agent,
                                step.backend == Backend::Native,
                            )
                        })
                    });
            run_task_with_progress_and_args_and_overrides_with_policy(
                contract,
                resolved_path,
                task_name,
                true,
                &[],
                overrides,
                !terminal_passthrough,
                None,
                terminal_passthrough,
                policy_env,
            )
        }
        .map(|outcome| CommandRunResult {
            exit_code: outcome.exit_code,
            executed_tasks: outcome.executed_tasks,
            task_steps: outcome.task_steps,
            stdout: String::new(),
            stderr: String::new(),
            target: outcome.target,
            runtime: outcome.runtime,
            service_termination: outcome.service_termination,
            fulfilled_toolchains: outcome.fulfilled_toolchains,
            host_service_cleanup: outcome.host_service_cleanup,
        })
        .map_err(|error| error),
        RepoExecutionMode::Capture => run_task_captured_with_args_with_overrides_with_policy(
            contract,
            resolved_path,
            task_name,
            &[],
            overrides,
            policy_env,
        )
        .map(|outcome| CommandRunResult {
            exit_code: outcome.exit_code,
            executed_tasks: outcome.executed_tasks,
            task_steps: outcome.task_steps,
            stdout: outcome.stdout,
            stderr: outcome.stderr,
            target: outcome.target,
            runtime: outcome.runtime,
            service_termination: outcome.service_termination,
            fulfilled_toolchains: outcome.fulfilled_toolchains,
            host_service_cleanup: outcome.host_service_cleanup,
        })
        .map_err(|error| error),
    }
}

fn run_phase_failure_exit_code(outcome: &CommandRunResult) -> Option<i32> {
    if outcome.exit_code != 0 {
        return Some(outcome.exit_code);
    }

    outcome
        .service_termination
        .as_ref()
        .map(|termination| termination.exit_code.unwrap_or(1))
}

fn selected_up_run_task_is_service(
    contract: &Contract,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
) -> bool {
    let Some(task_name) = selected_up_activation_task_name(contract, workflow_name) else {
        return false;
    };
    let Some(task) = contract.tasks.get(task_name) else {
        return false;
    };
    let backend = effective_task_execution(contract, task_name, overrides).backend;
    task.service_runtime_for_backend(backend)
        .is_some_and(|runtime| runtime.kind == TaskRuntimeKind::Service)
}

fn resolve_up_run_behavior(
    contract: &Contract,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    preference: UpRunBehaviorPreference,
) -> UpRunBehavior {
    match preference {
        UpRunBehaviorPreference::Attach => {
            if selected_up_attach_task_name(contract, workflow_name).is_some()
                && selected_up_run_task_is_service(contract, workflow_name, overrides)
            {
                UpRunBehavior::DetachedLeaveRunning
            } else {
                UpRunBehavior::Attach
            }
        }
        UpRunBehaviorPreference::Detach => UpRunBehavior::DetachedLeaveRunning,
        UpRunBehaviorPreference::Auto => {
            if selected_up_run_task_is_service(contract, workflow_name, overrides) {
                UpRunBehavior::DetachedProofTeardown
            } else {
                UpRunBehavior::Attach
            }
        }
    }
}

fn up_task_execution_overrides(
    contract: &Contract,
    resolved_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    run_behavior: UpRunBehavior,
) -> ExecutionOverrides {
    let should_force_ephemeral = matches!(overrides.backend, Some(Backend::Container))
        || selected_up_activation_task_name(contract, workflow_name)
            .and_then(|task_name| {
                resolve_execution_backend_with_contract_path(
                    contract,
                    task_name,
                    overrides,
                    Some(resolved_path),
                )
                .ok()
            })
            .is_some_and(|backend| matches!(backend, ResolvedExecutionBackend::Container { .. }));

    if matches!(run_behavior, UpRunBehavior::DetachedProofTeardown)
        && selected_up_run_task_is_service(contract, workflow_name, overrides)
        && should_force_ephemeral
    {
        ExecutionOverrides {
            lifecycle: Some(Lifecycle::Ephemeral),
            ..overrides
        }
    } else {
        overrides
    }
}

fn up_success_execution_context(
    contract: &Contract,
    resolved_path: &Path,
    workflow_name: Option<&str>,
    run_behavior: UpRunBehavior,
    activation_task: Option<&str>,
    task_execution_overrides: ExecutionOverrides,
    doctor_mode: DoctorMode,
    overrides: ExecutionOverrides,
    report: &DoctorReport,
) -> PhaseExecutionContext {
    if matches!(run_behavior, UpRunBehavior::DetachedLeaveRunning)
        && selected_up_run_task_is_service(contract, workflow_name, task_execution_overrides)
        && let Some(task_name) = activation_task
    {
        return task_phase_execution_context(
            contract,
            resolved_path,
            task_name,
            task_execution_overrides,
            None,
        );
    }

    doctor_report_execution_context(
        contract,
        resolved_path,
        doctor_mode,
        overrides.lifecycle,
        report,
    )
}

fn is_workflow_surface_readiness_finding(finding: &Finding) -> bool {
    finding.summary.starts_with("Surface readiness failed:")
        || finding.summary.starts_with("Surface readiness timed out:")
        || finding
            .summary
            .starts_with("Surface readiness could not be evaluated:")
        || finding
            .summary
            .starts_with("Signal surface readiness failed:")
        || finding
            .summary
            .starts_with("Signal surface readiness timed out:")
        || finding
            .summary
            .starts_with("Signal surface readiness could not be evaluated:")
}

#[cfg(test)]
fn report_without_workflow_surface_readiness_findings(mut report: DoctorReport) -> DoctorReport {
    report
        .findings
        .retain(|finding| !is_workflow_surface_readiness_finding(finding));
    report.ok = !report
        .findings
        .iter()
        .any(|finding| finding.severity == FindingSeverity::Error);
    report
}

fn run_up_task_detached_until_ready(
    contract: &Contract,
    resolved_path: &Path,
    workflow_name: Option<&str>,
    task_name: &str,
    overrides: ExecutionOverrides,
    policy_env: Option<&BTreeMap<String, String>>,
    ready_timeout: Option<Duration>,
    keep_running: bool,
    replay_input_preflight: &TaskReplayInputPreflight,
) -> Result<CommandRunResult, String> {
    let repo_root = contract_working_dir(resolved_path);
    let artifact_dir = proof_runtime_artifact_dir(repo_root, None, workflow_name);
    fs::create_dir_all(&artifact_dir).map_err(|error| {
        format!(
            "failed to create detached up artifact directory `{}`: {error}",
            compact_path(&artifact_dir, ".")
        )
    })?;
    let run_log_artifact_path = artifact_dir.join("up-detached-run.log");
    let run_log_artifact = compact_path(&run_log_artifact_path, ".");
    let mut run_process = spawn_up_detached_run_process(
        resolved_path,
        task_name,
        false,
        overrides,
        policy_env,
        &run_log_artifact_path,
        keep_running,
    )?;
    let proof_owner_pid = run_process.id();
    let (proof_report, _, proof_ok, run_process_failure) = wait_for_proof_runtime_readiness(
        contract,
        resolved_path,
        workflow_name,
        overrides,
        &mut run_process,
        &format!("ota run {task_name} --stream"),
        &run_log_artifact_path,
        ready_timeout,
        replay_input_preflight.policy.as_ref(),
        replay_input_preflight.doctor_policy_snapshot(),
    )?;

    if proof_ok {
        crate::runner::attest_pnpm_boundary_after_runtime_readiness(
            contract, task_name, overrides, repo_root,
        )?;
        if !keep_running {
            stop_proof_runtime_up_process(&mut run_process).map_err(|error| {
                format!(
                    "readiness proved, but ota could not stop the proof run process: {error}\ninspect `{run_log_artifact}` for detached run task logs"
                )
            })?;
            cleanup_proof_owned_containers(proof_owner_pid).map_err(|error| {
                format!(
                    "readiness proved, but ota could not clean proof-owned runtime containers: {error}\ninspect `{run_log_artifact}` for detached run task logs"
                )
            })?;
        }
        return Ok(CommandRunResult {
            exit_code: 0,
            executed_tasks: Vec::new(),
            task_steps: Vec::new(),
            stdout: String::new(),
            stderr: String::new(),
            target: None,
            runtime: None,
            service_termination: None,
            fulfilled_toolchains: Vec::new(),
            host_service_cleanup: Vec::new(),
        });
    }

    let _ = stop_proof_runtime_up_process(&mut run_process);
    if !keep_running {
        let _ = cleanup_proof_owned_containers(proof_owner_pid);
    }
    let summary = doctor_summary(
        &proof_report,
        crate::workspace::agent_verdict_from_agent(contract.agent.as_ref()),
    );
    let failure = run_process_failure.unwrap_or_else(|| {
        summary
            .primary_blocker
            .as_ref()
            .map(|blocker| blocker.summary.clone())
            .unwrap_or_else(|| String::from("detached run task did not reach readiness"))
    });
    let mut failure_details = Vec::new();
    if let Some(hint) = detached_run_failure_hint_from_log(&run_log_artifact_path) {
        let hint_message = hint.message();
        if !failure.contains(hint_message.as_str()) {
            failure_details.push(hint_message);
        }
    }
    if let Some(endpoint_hint) =
        up_declared_readiness_endpoint_hint(contract, resolved_path, workflow_name, overrides)
        && !failure.contains(endpoint_hint.as_str())
    {
        failure_details.push(endpoint_hint);
    }
    Ok(CommandRunResult {
        exit_code: 1,
        executed_tasks: Vec::new(),
        task_steps: Vec::new(),
        stdout: String::new(),
        stderr: render_detached_run_failure_output(
            &failure,
            &failure_details,
            run_log_artifact.as_str(),
        ),
        target: None,
        runtime: None,
        service_termination: None,
        fulfilled_toolchains: Vec::new(),
        host_service_cleanup: Vec::new(),
    })
}

fn render_detached_run_failure_output(
    failure: &str,
    failure_details: &[String],
    run_log_artifact: &str,
) -> String {
    let mut lines = vec![failure.to_string()];
    if !failure_details.is_empty() {
        lines.push(format!("\n{}", error_key("Why:")));
        lines.extend(failure_details.iter().map(|detail| {
            format!(
                "  {} {}",
                finding_detail_bullet(FindingSeverity::Error),
                detail
            )
        }));
    }
    lines.push(format!("\n{}", error_key("Next:")));
    if let Some(port) = detached_run_bind_conflict_port_hint(failure, failure_details) {
        lines.push(format!(
            "  {} free port {port} or change the task's published port",
            finding_detail_bullet(FindingSeverity::Error),
        ));
    }
    lines.push(format!(
        "  {} inspect `{run_log_artifact}` for detached run task logs",
        finding_detail_bullet(FindingSeverity::Error),
    ));
    lines.push(String::new());
    lines.join("\n")
}

fn detached_run_bind_conflict_port_hint(failure: &str, failure_details: &[String]) -> Option<u16> {
    let bind_conflict = failure.contains("EADDRINUSE")
        || failure.contains("address already in use")
        || failure_details.iter().any(|detail| {
            detail.contains("EADDRINUSE") || detail.contains("address already in use")
        });
    if !bind_conflict {
        return None;
    }

    for detail in failure_details {
        let Some(endpoint) = detail.strip_prefix("declared readiness endpoint: ") else {
            continue;
        };
        let endpoint = endpoint.trim();
        let after_scheme = endpoint
            .split_once("://")
            .map(|(_, rest)| rest)
            .unwrap_or(endpoint);
        let host_port = after_scheme.split('/').next().unwrap_or(after_scheme);
        let candidate = host_port.rsplit(':').next().unwrap_or_default().trim();
        if let Ok(port) = candidate.parse::<u16>() {
            return Some(port);
        }
    }
    None
}

fn parse_port_from_line(line: &str) -> Option<u16> {
    for token in line.split(|ch: char| ch.is_whitespace() || ch == ')' || ch == '(' || ch == ',') {
        let candidate = token.rsplit(':').next().unwrap_or_default().trim();
        if let Ok(port) = candidate.parse::<u16>() {
            return Some(port);
        }
    }
    None
}

fn detached_run_failure_hint_from_log(path: &Path) -> Option<ProofRuntimeLikelyCause> {
    let contents = fs::read_to_string(path).ok()?;
    if let Some(details) = extract_container_engine_unavailable_details("", &contents) {
        let lowered = contents.to_ascii_lowercase();
        let engine = if lowered.contains("podman") {
            "podman"
        } else {
            "docker"
        };
        return Some(ProofRuntimeLikelyCause::ContainerEngineUnavailable {
            artifact: path.to_path_buf(),
            engine: String::from(engine),
            details: normalize_container_engine_unavailable_details(&details),
        });
    }
    for raw_line in contents.lines() {
        let line = strip_ansi_codes(raw_line).trim().to_string();
        let lowered = line.to_ascii_lowercase();
        if lowered.contains("eaddrinuse") || lowered.contains("address already in use") {
            return Some(ProofRuntimeLikelyCause::BindConflict {
                artifact: path.to_path_buf(),
                port: parse_port_from_line(&line),
            });
        }
    }
    for raw_line in contents.lines() {
        let line = strip_ansi_codes(raw_line).trim().to_string();
        if let Some(title) = line.strip_prefix("◉ ERROR") {
            let title = title.trim();
            if !title.is_empty() {
                return Some(ProofRuntimeLikelyCause::DetachedRunOutput {
                    artifact: path.to_path_buf(),
                    signal: format!("error: {title}"),
                });
            }
        }
    }

    let mut fallback = None;
    for raw_line in contents.lines().rev() {
        let line = strip_ansi_codes(raw_line).trim().to_string();
        if line.is_empty()
            || line == "RUN SUMMARY"
            || line == "UP SUMMARY"
            || line == "Next:"
            || line.starts_with("Status:")
            || line.starts_with("Scope:")
            || line.starts_with("Path:")
            || line.starts_with("Contract:")
            || line.starts_with("Mode:")
            || line.starts_with("Task:")
            || line.starts_with("Context:")
            || line.starts_with("Lifecycle:")
            || line.starts_with("Image:")
            || line.starts_with("Memory:")
            || line.starts_with("Cause:")
            || line.starts_with("External:")
            || line.starts_with("Internal:")
            || line.starts_with("Note:")
            || line.starts_with("» ")
            || line.starts_with("- ")
        {
            continue;
        }
        if line.contains("EADDRINUSE") {
            return Some(ProofRuntimeLikelyCause::DetachedRunOutput {
                artifact: path.to_path_buf(),
                signal: String::from("address already in use (EADDRINUSE)"),
            });
        }
        if line.contains("address already in use") || line.starts_with("Error:") {
            return Some(ProofRuntimeLikelyCause::DetachedRunOutput {
                artifact: path.to_path_buf(),
                signal: line,
            });
        }
        if (line.starts_with("warning:")
            || line.contains("failed")
            || line.contains("timed out")
            || line.contains("cannot"))
            && fallback.is_none()
        {
            fallback = Some(line);
        }
    }
    fallback.map(|line| ProofRuntimeLikelyCause::DetachedRunOutput {
        artifact: path.to_path_buf(),
        signal: line,
    })
}

fn runtime_loopback_drift_hint_from_log(path: &Path) -> Option<ProofRuntimeLikelyCause> {
    let contents = fs::read_to_string(path).ok()?;
    for raw_line in contents.lines() {
        let line = strip_ansi_codes(raw_line);
        let lowered = line.to_ascii_lowercase();
        if !(lowered.contains("econnrefused")
            || lowered.contains("connection refused")
            || lowered.contains("connect refused"))
        {
            continue;
        }
        if !(lowered.contains("127.0.0.1") || lowered.contains("localhost")) {
            continue;
        }

        let (service, port) = if lowered.contains(":6379") {
            ("Redis", Some(6379))
        } else if lowered.contains(":5432") {
            ("Postgres", Some(5432))
        } else if lowered.contains(":8123") {
            ("ClickHouse", Some(8123))
        } else if lowered.contains(":9000") {
            ("ClickHouse", Some(9000))
        } else {
            (
                "a dependent service",
                parse_port_from_line(lowered.as_str()),
            )
        };
        let host = if lowered.contains("localhost") {
            String::from("localhost")
        } else {
            String::from("127.0.0.1")
        };

        return Some(ProofRuntimeLikelyCause::LoopbackServiceDrift {
            artifact: path.to_path_buf(),
            service: service.to_string(),
            host,
            port,
        });
    }
    None
}

fn up_declared_readiness_endpoint_hint(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
) -> Option<String> {
    let targets =
        proof_runtime_readiness_targets(contract, contract_path, workflow_name, overrides).ok()?;
    let target = targets.first()?;
    let endpoint = match target.protocol.url_scheme() {
        Some(scheme) => {
            let path = target
                .request
                .as_ref()
                .map(|request| request.path.as_str())
                .unwrap_or("/");
            format!("{scheme}://{}:{}{path}", target.address, target.port)
        }
        None => format!("tcp://{}:{}", target.address, target.port),
    };
    Some(format!("declared readiness endpoint: {endpoint}"))
}

fn cleanup_proof_owned_containers(owner_pid: u32) -> Result<(), String> {
    let mut failures = Vec::new();
    for engine in crate::execution::available_container_engines() {
        let owner_filter = format!("label=dev.ota.owner_pid={owner_pid}");
        let list_output = match Command::new(&engine)
            .args(["ps", "-aq", "--filter", "label=dev.ota.managed=true"])
            .arg("--filter")
            .arg(owner_filter)
            .output()
        {
            Ok(output) => output,
            Err(_) => continue,
        };
        if !list_output.status.success() {
            continue;
        }
        let container_ids = String::from_utf8_lossy(&list_output.stdout)
            .lines()
            .map(str::trim)
            .filter(|id| !id.is_empty())
            .map(String::from)
            .collect::<Vec<_>>();
        if container_ids.is_empty() {
            continue;
        }
        let remove_output = match Command::new(&engine)
            .arg("rm")
            .arg("-f")
            .args(container_ids.iter())
            .output()
        {
            Ok(output) => output,
            Err(error) => {
                failures.push(format!(
                    "failed to clean proof-owned containers with `{engine} rm -f`: {error}"
                ));
                continue;
            }
        };
        if !remove_output.status.success() {
            let stderr = String::from_utf8_lossy(&remove_output.stderr)
                .trim()
                .to_string();
            failures.push(if stderr.is_empty() {
                format!("`{engine} rm -f` failed while removing proof-owned containers")
            } else {
                format!("`{engine} rm -f` failed while removing proof-owned containers: {stderr}")
            });
        }
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(failures.join("; "))
    }
}

fn contract_adjusted_for_up_setup_phase(
    contract: &Contract,
    task_name: &str,
    overrides: ExecutionOverrides,
    prepare_task_name: Option<&str>,
) -> Option<Contract> {
    let task = contract.tasks.get(task_name)?;
    let setup_plan =
        crate::runner::plan_task_execution_with_overrides(contract, task_name, overrides).ok();
    let should_remove_prepare = prepare_task_name.is_some_and(|prepare_name| {
        setup_plan
            .as_ref()
            .is_some_and(|plan| plan.tasks.iter().any(|task| task == prepare_name))
    });
    if task.requires_services.is_empty() && !should_remove_prepare {
        return None;
    }

    let mut adjusted = contract.clone();
    if let Some(task) = adjusted.tasks.get_mut(task_name) {
        task.requires_services.clear();
    }
    if let Some(prepare_name) = prepare_task_name
        && should_remove_prepare
        && let Some(plan) = setup_plan
    {
        for planned_task in plan.tasks {
            if let Some(task) = adjusted.tasks.get_mut(&planned_task) {
                task.depends_on
                    .retain(|dependency| dependency != prepare_name);
            }
        }
    }
    Some(adjusted)
}

fn contract_adjusted_for_selected_workflow_env_profile(
    contract: &Contract,
    workflow_name: Option<&str>,
) -> Option<Contract> {
    let selected_instance = contract
        .resolved_selected_workflow_instance(workflow_name)
        .map(|resolved| resolved.spec);
    let has_workflow_env_or_adapter_inputs = contract
        .selected_workflow(workflow_name)
        .is_some_and(|(_, workflow)| workflow.env.is_some() || !workflow.adapter_inputs.is_empty());
    if !has_workflow_env_or_adapter_inputs && selected_instance.is_none() {
        return None;
    }

    let mut adjusted = contract.clone();
    let task_names = adjusted.selected_workflow_task_closure_names(workflow_name);
    if let Some(instance) = selected_instance.as_ref() {
        for (surface_name, overlay) in &instance.surfaces {
            let Some(surface) = adjusted.surfaces.get_mut(surface_name.as_str()) else {
                continue;
            };
            if let Some(port) = overlay.port {
                surface.port = port;
            }
            if let Some(path) = overlay.path.as_ref() {
                surface.path = Some(path.clone());
            }
        }

        for task_name in &task_names {
            let Some(task) = adjusted.tasks.get_mut(task_name.as_str()) else {
                continue;
            };
            for (name, value) in &instance.env {
                task.env.insert(name.clone(), value.clone());
            }
            if let Some(task_overlay) = instance.tasks.get(task_name.as_str()) {
                for (name, value) in &task_overlay.env {
                    task.env.insert(name.clone(), value.clone());
                }
                if !task_overlay.adapter_inputs.is_empty() {
                    apply_workflow_instance_task_adapter_inputs(task, &task_overlay.adapter_inputs);
                }
                if let Some(runtime_overlay) = task_overlay.runtime.as_ref() {
                    apply_workflow_instance_task_runtime(task, runtime_overlay);
                }
            }
        }
    }

    let profile = adjusted
        .selected_workflow_env_profile(workflow_name)
        .cloned()
        .unwrap_or_default();
    let adapter_task_names = adjusted.selected_workflow_run_task_closure_names(workflow_name);
    let rendered_dotenv_path = profile
        .render
        .as_ref()
        .and_then(|render| render.dotenv.as_ref())
        .map(|dotenv| dotenv.path.clone());
    let compose_env_file_services =
        adjusted.selected_workflow_compose_env_file_service_names(workflow_name);
    let mut workflow_adapter_inputs = adjusted
        .selected_workflow_adapter_overlay(workflow_name)
        .into_task_adapter_inputs();
    if let Some(path) = rendered_dotenv_path.as_ref() {
        let compose = workflow_adapter_inputs
            .compose
            .get_or_insert_with(crate::schema::TaskComposeAdapterInputsSpec::default);
        if !compose.env_files.iter().any(|existing| existing == path) {
            compose.env_files.insert(0, path.clone());
        }
    }
    if task_names.is_empty()
        && profile.sources.is_empty()
        && compose_env_file_services.is_empty()
        && workflow_adapter_inputs.is_empty()
        && selected_instance.is_none()
    {
        return None;
    }
    let mut merged_sources = profile.sources.clone();
    for source in &adjusted.env.sources {
        if !merged_sources.iter().any(|existing| existing == source) {
            merged_sources.push(source.clone());
        }
    }
    adjusted.env.sources = merged_sources;

    for task_name in task_names {
        let Some(task) = adjusted.tasks.get_mut(task_name.as_str()) else {
            continue;
        };
        let adapter_bound = adapter_task_names.iter().any(|name| name == &task_name)
            && bind_workflow_adapter_overlays(task, &workflow_adapter_inputs);
        if let Some(path) = rendered_dotenv_path.as_ref()
            && !task
                .projected_env_materialization_paths
                .iter()
                .any(|existing| existing == path)
        {
            task.projected_env_materialization_paths.push(path.clone());
        }
        if !adapter_bound {
            if let Some(path) = rendered_dotenv_path.as_ref()
                && !task.env_files.iter().any(|existing| existing == path)
            {
                task.env_files.insert(0, path.clone());
            }
        }
        if rendered_dotenv_path.is_some() {
            if !profile.env_files.is_empty() {
                let mut merged_env_files = profile.env_files.clone();
                for path in &task.env_files {
                    if !merged_env_files.iter().any(|existing| existing == path) {
                        merged_env_files.push(path.clone());
                    }
                }
                task.env_files = merged_env_files;
            }
        } else if !profile.env_files.is_empty() {
            let mut merged_env_files = profile.env_files.clone();
            for path in &task.env_files {
                if !merged_env_files.iter().any(|existing| existing == path) {
                    merged_env_files.push(path.clone());
                }
            }
            task.env_files = merged_env_files;
        }
        if !profile.env.is_empty() {
            let mut merged_env = profile.env.clone();
            merged_env.extend(task.env.clone());
            task.env = merged_env;
        }
    }

    if let Some(path) = rendered_dotenv_path.as_ref() {
        for service_name in compose_env_file_services {
            let Some(service) = adjusted.services.get_mut(service_name.as_str()) else {
                continue;
            };
            let Some(manager) = service.manager.as_mut() else {
                continue;
            };
            if manager.kind == crate::schema::ServiceManagerKind::Compose {
                manager.env_file = Some(path.clone());
                if !manager.env_files.iter().any(|existing| existing == path) {
                    manager.env_files.insert(0, path.clone());
                }
            }
        }
    }

    Some(adjusted)
}

fn apply_workflow_instance_task_adapter_inputs(
    task: &mut TaskSpec,
    overlay: &crate::schema::TaskAdapterInputsSpec,
) {
    for (family, family_overlay) in &overlay.overlays {
        task.adapter_inputs
            .overlays
            .insert(family.clone(), family_overlay.clone());
    }

    if let Some(compose) = overlay.compose.as_ref() {
        let task_compose = task
            .adapter_inputs
            .compose
            .get_or_insert_with(crate::schema::TaskComposeAdapterInputsSpec::default);
        if compose.cwd.is_some() {
            task_compose.cwd = compose.cwd.clone();
        }
        if !compose.env_files.is_empty() {
            task_compose.env_files = compose.env_files.clone();
        }
        if !compose.files.is_empty() {
            task_compose.files = compose.files.clone();
        }
        if !compose.profiles.is_empty() {
            task_compose.profiles = compose.profiles.clone();
        }
        if compose.project_name.is_some() {
            task_compose.project_name = compose.project_name.clone();
        }
    }

    if let Some(bake) = overlay.bake.as_ref() {
        let task_bake = task
            .adapter_inputs
            .bake
            .get_or_insert_with(crate::schema::TaskBakeAdapterInputsSpec::default);
        if bake.cwd.is_some() {
            task_bake.cwd = bake.cwd.clone();
        }
        if !bake.files.is_empty() {
            task_bake.files = bake.files.clone();
        }
    }

    if let Some(helm) = overlay.helm.as_ref() {
        let task_helm = task
            .adapter_inputs
            .helm
            .get_or_insert_with(crate::schema::TaskHelmAdapterInputsSpec::default);
        if helm.cwd.is_some() {
            task_helm.cwd = helm.cwd.clone();
        }
        if !helm.values_files.is_empty() {
            task_helm.values_files = helm.values_files.clone();
        }
        if helm.chart.is_some() {
            task_helm.chart = helm.chart.clone();
        }
        if helm.release_name.is_some() {
            task_helm.release_name = helm.release_name.clone();
        }
        if helm.namespace.is_some() {
            task_helm.namespace = helm.namespace.clone();
        }
    }
}

fn apply_workflow_instance_task_runtime(
    task: &mut TaskSpec,
    overlay: &crate::schema::WorkflowInstanceTaskRuntimeOverlaySpec,
) {
    let Some(runtime) = task.runtime.as_mut() else {
        return;
    };

    if let Some(backend_binding) = overlay.backend_binding.as_ref() {
        runtime.backend_binding = Some(backend_binding.clone());
    }

    if let Some(readiness_overlay) = overlay.readiness.as_ref() {
        let readiness = runtime
            .readiness
            .get_or_insert_with(empty_task_runtime_readiness);
        merge_runtime_readiness_overlay(readiness, readiness_overlay);
    }

    for (listener_name, listener_overlay) in &overlay.listeners {
        let Some(listener) = runtime.listeners.get_mut(listener_name.as_str()) else {
            continue;
        };
        merge_runtime_listener_overlay(listener, listener_overlay);
    }
}

fn empty_task_runtime_readiness() -> crate::schema::TaskRuntimeReadinessSpec {
    crate::schema::TaskRuntimeReadinessSpec {
        probe: None,
        signal_probes: Vec::new(),
        kind: None,
        listener: None,
        method: None,
        path: None,
        headers: BTreeMap::new(),
        success: None,
        body: None,
        interval: None,
        timeout: None,
        retries: None,
        start_period: None,
    }
}

fn merge_runtime_readiness_overlay(
    target: &mut crate::schema::TaskRuntimeReadinessSpec,
    overlay: &crate::schema::TaskRuntimeReadinessSpec,
) {
    if overlay.probe.is_some() {
        target.probe = overlay.probe.clone();
    }
    if !overlay.signal_probes.is_empty() {
        target.signal_probes = overlay.signal_probes.clone();
    }
    if overlay.kind.is_some() {
        target.kind = overlay.kind;
    }
    if overlay.listener.is_some() {
        target.listener = overlay.listener.clone();
    }
    if overlay.method.is_some() {
        target.method = overlay.method;
    }
    if overlay.path.is_some() {
        target.path = overlay.path.clone();
    }
    if !overlay.headers.is_empty() {
        target.headers = overlay.headers.clone();
    }
    if overlay.success.is_some() {
        target.success = overlay.success.clone();
    }
    if overlay.body.is_some() {
        target.body = overlay.body.clone();
    }
    if overlay.interval.is_some() {
        target.interval = overlay.interval.clone();
    }
    if overlay.timeout.is_some() {
        target.timeout = overlay.timeout.clone();
    }
    if overlay.retries.is_some() {
        target.retries = overlay.retries;
    }
    if overlay.start_period.is_some() {
        target.start_period = overlay.start_period.clone();
    }
}

fn merge_runtime_listener_overlay(
    target: &mut crate::schema::TaskRuntimeListenerSpec,
    overlay: &crate::schema::WorkflowInstanceTaskRuntimeListenerOverlaySpec,
) {
    if let Some(bind_overlay) = overlay.bind.as_ref() {
        if let Some(address) = bind_overlay.address.as_ref() {
            target.bind.address = address.clone();
        }
        if let Some(port_overlay) = bind_overlay.port.as_ref() {
            if let Some(mode) = port_overlay.mode {
                target.bind.port.mode = mode;
            }
            if port_overlay.value.is_some() {
                target.bind.port.value = port_overlay.value;
            }
        }
    }

    if let Some(project_overlay) = overlay.project.as_ref()
        && let Some(host_overlay) = project_overlay.host.as_ref()
    {
        let host = target.project.host.get_or_insert_with(|| {
            crate::schema::TaskRuntimeHostProjectionSpec {
                address: String::from("127.0.0.1"),
                port: crate::schema::TaskRuntimeHostPortSpec {
                    mode: crate::schema::TaskRuntimeHostPortMode::Fixed,
                    value: None,
                },
                primary: false,
                path: None,
            }
        });
        if let Some(address) = host_overlay.address.as_ref() {
            host.address = address.clone();
        }
        if let Some(port_overlay) = host_overlay.port.as_ref() {
            if let Some(mode) = port_overlay.mode {
                host.port.mode = mode;
            }
            if port_overlay.value.is_some() {
                host.port.value = port_overlay.value;
            }
        }
        if let Some(primary) = host_overlay.primary {
            host.primary = primary;
        }
        if host_overlay.path.is_some() {
            host.path = host_overlay.path.clone();
        }
    }
}

fn workflow_env_profile_applies_to_task(
    contract: &Contract,
    workflow_name: Option<&str>,
    task_name: &str,
) -> bool {
    contract
        .selected_workflow_task_closure_names(workflow_name)
        .iter()
        .any(|declared| declared == task_name)
}

fn materialize_selected_workflow_env_profile_for_task(
    target: &mut LoadedContractTarget,
    workflow_name: Option<&str>,
    task_name: &str,
) -> Result<(), String> {
    let task_name = canonical_declared_task_name(&target.contract, task_name);
    let has_workflow_env_or_adapter_inputs = target
        .contract
        .selected_workflow(workflow_name)
        .is_some_and(|(_, workflow)| workflow.env.is_some() || !workflow.adapter_inputs.is_empty());
    if !has_workflow_env_or_adapter_inputs
        || !workflow_env_profile_applies_to_task(
            &target.contract,
            workflow_name,
            task_name.as_str(),
        )
    {
        return Ok(());
    }

    if target
        .contract
        .selected_workflow_env_profile_name(workflow_name)
        .is_some()
    {
        let policy_env =
            load_policy_env_overlay(&target.contract_path).map_err(|error| error.to_string())?;
        render_selected_workflow_env_profile_artifacts(
            &target.contract,
            &target.contract_path,
            workflow_name,
            Some(&policy_env.values),
        )?;
    }
    if let Some(adjusted) =
        contract_adjusted_for_selected_workflow_env_profile(&target.contract, workflow_name)
    {
        target.contract = adjusted;
    }
    Ok(())
}

fn selected_workflow_env_profile_render_preview_action(
    contract: &Contract,
    workflow_name: Option<&str>,
) -> Option<String> {
    let profile_name = contract.selected_workflow_env_profile_name(workflow_name)?;
    let render = contract
        .selected_workflow_env_profile(workflow_name)?
        .render
        .as_ref()?;
    let mut artifacts = Vec::new();
    if let Some(dotenv) = render.dotenv.as_ref() {
        artifacts.push(dotenv.path.trim().to_string());
    }
    artifacts.extend(
        render
            .files
            .iter()
            .map(|file| file.path.trim().to_string())
            .filter(|path| !path.is_empty()),
    );
    match artifacts.len() {
        0 => None,
        1 => Some(format!(
            "render workflow env artifact `{}` from profile `{profile_name}`",
            artifacts[0]
        )),
        count => Some(format!(
            "render {count} workflow env artifacts from profile `{profile_name}`"
        )),
    }
}

fn render_selected_workflow_env_profile_artifacts(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    policy_env: Option<&BTreeMap<String, String>>,
) -> Result<Vec<String>, String> {
    let profile_name = match contract.selected_workflow_env_profile_name(workflow_name) {
        Some(name) => name.to_string(),
        None => return Ok(Vec::new()),
    };
    let Some(profile) = contract.selected_workflow_env_profile(workflow_name) else {
        return Ok(Vec::new());
    };
    let Some(render) = profile.render.as_ref() else {
        return Ok(Vec::new());
    };

    let adjusted = contract_adjusted_for_selected_workflow_env_profile(contract, workflow_name)
        .unwrap_or_else(|| contract.clone());
    let render_env = selected_workflow_instance_render_env(
        contract,
        workflow_name,
        contract_working_dir(contract_path),
    );
    let resolved_overrides = profile.env.clone();
    let resolved = crate::runner::resolve_task_env_details_with_policy(
        &adjusted,
        contract_path,
        Some(&resolved_overrides),
        policy_env,
    )
    .map_err(|error| error.to_string())?;
    let mut rendered_messages = Vec::new();

    if let Some(dotenv) = render.dotenv.as_ref() {
        let output_path = contract_working_dir(contract_path).join(dotenv.path.trim());
        if let Some(parent) = output_path.parent()
            && !parent.exists()
        {
            fs::create_dir_all(parent).map_err(|error| {
                format!(
                    "workflow env profile `{profile_name}` could not create parent directory for `{}`: {error}",
                    dotenv.path.trim()
                )
            })?;
        }

        let template_content = if let Some(template) = dotenv.template.as_deref() {
            let template_path = contract_working_dir(contract_path).join(template.trim());
            if !template_path.is_file() {
                return Err(format!(
                    "workflow env profile `{profile_name}` could not render dotenv `{}` because template `{}` is not a file",
                    dotenv.path.trim(),
                    template.trim()
                ));
            }
            fs::read_to_string(&template_path).map_err(|error| {
                format!(
                    "workflow env profile `{profile_name}` could not read template `{}` for rendered dotenv `{}`: {error}",
                    template.trim(),
                    dotenv.path.trim()
                )
            })?
        } else {
            String::new()
        };

        let mut updates = Vec::new();
        for name in &dotenv.include {
            let value = if let Some(resolved_value) = resolved.get(name) {
                resolved_value.value.clone()
            } else if let Some(value) = profile.env.get(name) {
                value.clone()
            } else {
                return Err(format!(
                    "workflow env profile `{profile_name}` could not resolve `{name}` for rendered dotenv `{}`",
                    dotenv.path.trim()
                ));
            };
            updates.push((
                name.clone(),
                Some(value),
                crate::schema::TaskEnsureEnvVarMode::Replace,
            ));
        }

        for (name, value) in &profile.env {
            if !dotenv.include.iter().any(|included| included == name) {
                updates.push((
                    name.clone(),
                    Some(value.clone()),
                    crate::schema::TaskEnsureEnvVarMode::Replace,
                ));
            }
        }

        let (next, _, _, _) =
            crate::runner::apply_ensure_env_updates(template_content.as_str(), &updates);
        fs::write(&output_path, next).map_err(|error| {
            format!(
                "workflow env profile `{profile_name}` could not render dotenv `{}`: {error}",
                dotenv.path.trim()
            )
        })?;
        rendered_messages.push(format!(
            "rendered workflow env artifact `{}` from profile `{profile_name}`\n",
            dotenv.path.trim()
        ));
    }

    for file in &render.files {
        render_workflow_profile_structured_file(
            profile_name.as_str(),
            file,
            contract_path,
            &render_env,
            &mut rendered_messages,
        )?;
    }

    Ok(rendered_messages)
}

fn selected_workflow_env_profile_rendered_artifact_entries(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
) -> Vec<EnvRenderedArtifactEntry> {
    let Some(profile_name) = contract
        .selected_workflow_env_profile_name(workflow_name)
        .map(str::to_string)
    else {
        return Vec::new();
    };
    let Some(profile) = contract.selected_workflow_env_profile(workflow_name) else {
        return Vec::new();
    };
    let Some(render) = profile.render.as_ref() else {
        return Vec::new();
    };
    let adjusted = contract_adjusted_for_selected_workflow_env_profile(contract, workflow_name)
        .unwrap_or_else(|| contract.clone());
    let dotenv_path = render
        .dotenv
        .as_ref()
        .map(|dotenv| dotenv.path.trim().to_string());
    let mut consumers = Vec::new();
    for task_name in contract.selected_workflow_task_closure_names(workflow_name) {
        let Some(task) = adjusted.tasks.get(task_name.as_str()) else {
            continue;
        };
        if dotenv_path.as_deref().is_some_and(|path| {
            task.env_files
                .iter()
                .any(|existing| existing.trim() == path)
        }) {
            consumers.push(format!("task:{task_name}"));
        }
    }
    for service_name in contract.selected_workflow_required_service_names(workflow_name) {
        let Some(service) = adjusted.services.get(service_name.as_str()) else {
            continue;
        };
        if service
            .manager
            .as_ref()
            .and_then(|manager| manager.env_file.as_deref())
            .is_some_and(|existing| {
                dotenv_path
                    .as_deref()
                    .is_some_and(|path| existing.trim() == path)
            })
        {
            consumers.push(format!("service:{service_name}"));
        }
    }
    let mut entries = Vec::new();
    if let Some(dotenv) = render.dotenv.as_ref() {
        let path = dotenv.path.trim().to_string();
        let rendered_path = contract_working_dir(contract_path).join(dotenv.path.trim());
        entries.push(EnvRenderedArtifactEntry {
            path,
            kind: String::from("dotenv"),
            includes: dotenv.include.clone(),
            sources: Vec::new(),
            exists: rendered_path.is_file(),
            profile: Some(profile_name.clone()),
            consumers: consumers.clone(),
        });
    }
    for file in &render.files {
        let path = file.path.trim().to_string();
        let rendered_path = contract_working_dir(contract_path).join(file.path.trim());
        entries.push(EnvRenderedArtifactEntry {
            path,
            kind: file.format.to_string(),
            includes: Vec::new(),
            sources: file.sources.clone(),
            exists: rendered_path.is_file(),
            profile: Some(profile_name.clone()),
            consumers: Vec::new(),
        });
    }
    entries
}

fn selected_workflow_instance_render_env(
    contract: &Contract,
    workflow_name: Option<&str>,
    working_dir: &Path,
) -> BTreeMap<String, String> {
    let mut values = BTreeMap::new();
    let Some(instance) = contract.resolved_selected_workflow_instance(workflow_name) else {
        return values;
    };
    for (name, value) in &instance.spec.env {
        values.insert(
            name.clone(),
            expand_render_template_env_value(value, working_dir),
        );
    }
    values
}

fn expand_render_template_env_value(value: &str, working_dir: &Path) -> String {
    let mut rendered = value.to_string();
    let host_workspace = working_dir.display().to_string();
    rendered = rendered.replace("${OTA_HOST_WORKSPACE}", host_workspace.as_str());
    rendered = rendered.replace("$OTA_HOST_WORKSPACE", host_workspace.as_str());
    if let Some(host_home) = env::var_os("HOME") {
        let host_home = PathBuf::from(host_home).display().to_string();
        rendered = rendered.replace("${OTA_HOST_HOME}", host_home.as_str());
        rendered = rendered.replace("$OTA_HOST_HOME", host_home.as_str());
    }
    if let Some(host_uid) = crate::runner::host_uid_template_value(working_dir) {
        rendered = rendered.replace("${OTA_HOST_UID}", host_uid.as_str());
        rendered = rendered.replace("$OTA_HOST_UID", host_uid.as_str());
    }
    if let Some(host_gid) = crate::runner::host_gid_template_value(working_dir) {
        rendered = rendered.replace("${OTA_HOST_GID}", host_gid.as_str());
        rendered = rendered.replace("$OTA_HOST_GID", host_gid.as_str());
    }
    rendered
}

fn expand_structured_render_placeholders(
    content: &str,
    values: &BTreeMap<String, String>,
) -> String {
    let mut rendered = content.to_string();
    for (name, value) in values {
        rendered = rendered.replace(format!("${{{name}}}").as_str(), value);
    }
    rendered
}

fn render_workflow_profile_structured_file(
    profile_name: &str,
    spec: &crate::schema::EnvProfileStructuredFileRenderSpec,
    contract_path: &Path,
    render_env: &BTreeMap<String, String>,
    messages: &mut Vec<String>,
) -> Result<(), String> {
    let output_path = contract_working_dir(contract_path).join(spec.path.trim());
    if let Some(parent) = output_path.parent()
        && !parent.exists()
    {
        fs::create_dir_all(parent).map_err(|error| {
            format!(
                "workflow env profile `{profile_name}` could not create parent directory for `{}`: {error}",
                spec.path.trim()
            )
        })?;
    }

    match spec.format {
        crate::schema::EnvProfileStructuredFileRenderFormat::Json => {
            let merged = render_workflow_profile_json_file(
                profile_name,
                spec,
                contract_path,
                render_env,
                output_path.as_path(),
            )?;
            let content = serde_json::to_string_pretty(&merged).map_err(|error| {
                format!(
                    "workflow env profile `{profile_name}` could not serialize rendered json `{}`: {error}",
                    spec.path.trim()
                )
            })?;
            fs::write(&output_path, format!("{content}\n")).map_err(|error| {
                format!(
                    "workflow env profile `{profile_name}` could not render json `{}`: {error}",
                    spec.path.trim()
                )
            })?;
        }
        crate::schema::EnvProfileStructuredFileRenderFormat::Toml => {
            let merged = render_workflow_profile_toml_file(
                profile_name,
                spec,
                contract_path,
                render_env,
                output_path.as_path(),
            )?;
            let content = toml::to_string_pretty(&merged).map_err(|error| {
                format!(
                    "workflow env profile `{profile_name}` could not serialize rendered toml `{}`: {error}",
                    spec.path.trim()
                )
            })?;
            fs::write(&output_path, format!("{content}\n")).map_err(|error| {
                format!(
                    "workflow env profile `{profile_name}` could not render toml `{}`: {error}",
                    spec.path.trim()
                )
            })?;
        }
    }

    messages.push(format!(
        "rendered workflow env artifact `{}` from profile `{profile_name}`\n",
        spec.path.trim()
    ));
    Ok(())
}

fn render_workflow_profile_json_file(
    profile_name: &str,
    spec: &crate::schema::EnvProfileStructuredFileRenderSpec,
    contract_path: &Path,
    render_env: &BTreeMap<String, String>,
    output_path: &Path,
) -> Result<JsonValue, String> {
    let mut merged = if spec.merge_into_existing && output_path.is_file() {
        parse_render_source_json(profile_name, spec.path.trim(), output_path, render_env)?
    } else {
        JsonValue::Object(serde_json::Map::new())
    };

    for source in &spec.sources {
        let source_path = contract_working_dir(contract_path).join(source.trim());
        let parsed =
            parse_render_source_json(profile_name, spec.path.trim(), &source_path, render_env)?;
        deep_merge_json_value(&mut merged, parsed);
    }
    Ok(merged)
}

fn render_workflow_profile_toml_file(
    profile_name: &str,
    spec: &crate::schema::EnvProfileStructuredFileRenderSpec,
    contract_path: &Path,
    render_env: &BTreeMap<String, String>,
    output_path: &Path,
) -> Result<TomlValue, String> {
    let mut merged = if spec.merge_into_existing && output_path.is_file() {
        parse_render_source_toml(profile_name, spec.path.trim(), output_path, render_env)?
    } else {
        TomlValue::Table(toml::map::Map::new())
    };

    for source in &spec.sources {
        let source_path = contract_working_dir(contract_path).join(source.trim());
        let parsed =
            parse_render_source_toml(profile_name, spec.path.trim(), &source_path, render_env)?;
        deep_merge_toml_value(&mut merged, parsed);
    }
    Ok(merged)
}

fn parse_render_source_json(
    profile_name: &str,
    output_label: &str,
    source_path: &Path,
    render_env: &BTreeMap<String, String>,
) -> Result<JsonValue, String> {
    let raw = fs::read_to_string(source_path).map_err(|error| {
        format!(
            "workflow env profile `{profile_name}` could not read source `{}` for rendered json `{output_label}`: {error}",
            source_path.display()
        )
    })?;
    let expanded = expand_structured_render_placeholders(raw.as_str(), render_env);
    serde_json::from_str(&expanded).map_err(|error| {
        format!(
            "workflow env profile `{profile_name}` could not parse source `{}` for rendered json `{output_label}`: {error}",
            source_path.display()
        )
    })
}

fn parse_render_source_toml(
    profile_name: &str,
    output_label: &str,
    source_path: &Path,
    render_env: &BTreeMap<String, String>,
) -> Result<TomlValue, String> {
    let raw = fs::read_to_string(source_path).map_err(|error| {
        format!(
            "workflow env profile `{profile_name}` could not read source `{}` for rendered toml `{output_label}`: {error}",
            source_path.display()
        )
    })?;
    let expanded = expand_structured_render_placeholders(raw.as_str(), render_env);
    toml::from_str(&expanded).map_err(|error| {
        format!(
            "workflow env profile `{profile_name}` could not parse source `{}` for rendered toml `{output_label}`: {error}",
            source_path.display()
        )
    })
}

fn deep_merge_json_value(base: &mut JsonValue, overlay: JsonValue) {
    match (base, overlay) {
        (JsonValue::Object(base_map), JsonValue::Object(overlay_map)) => {
            for (key, value) in overlay_map {
                if let Some(existing) = base_map.get_mut(key.as_str()) {
                    deep_merge_json_value(existing, value);
                } else {
                    base_map.insert(key, value);
                }
            }
        }
        (base, overlay) => *base = overlay,
    }
}

fn deep_merge_toml_value(base: &mut TomlValue, overlay: TomlValue) {
    match (base, overlay) {
        (TomlValue::Table(base_map), TomlValue::Table(overlay_map)) => {
            for (key, value) in overlay_map {
                if let Some(existing) = base_map.get_mut(key.as_str()) {
                    deep_merge_toml_value(existing, value);
                } else {
                    base_map.insert(key, value);
                }
            }
        }
        (base, overlay) => *base = overlay,
    }
}

fn run_up_required_services_phase(
    contract: &Contract,
    resolved_path: &Path,
    workflow_name: Option<&str>,
    selected_services: &BTreeSet<String>,
    phase: &'static str,
    mode: RepoExecutionMode,
    stdout: &mut String,
    stderr: &mut String,
) -> Result<Option<RepoUpResult>, String> {
    if selected_services.is_empty() {
        return Ok(None);
    }

    let working_dir = contract_working_dir(resolved_path);
    for name in service_start_order_for(contract, selected_services) {
        let service = contract
            .services
            .get(name.as_str())
            .expect("validated service should exist");

        if let Some(start) = service.start_command(name.as_str()) {
            match crate::runner::run_service_start_command(
                name.as_str(),
                service,
                working_dir,
                match mode {
                    RepoExecutionMode::Stream => crate::runner::TaskExecutionMode::Stream {
                        emit_progress: false,
                        capture_output: true,
                        live_log: None,
                        allow_terminal_passthrough: false,
                    },
                    RepoExecutionMode::Capture => crate::runner::TaskExecutionMode::Capture,
                },
            ) {
                Ok(command) if command.exit_code == 0 => {
                    stdout.push_str(&command.stdout);
                    stderr.push_str(&command.stderr);
                }
                Ok(command) => {
                    stdout.push_str(&command.stdout);
                    stderr.push_str(&command.stderr);
                    return Ok(Some(RepoUpResult {
                        ok: false,
                        status: "SERVICE START FAILED",
                        phase,
                        preview: None,
                        governance_preflight: None,
                        receipt: repo_execution_receipt(
                            resolved_path,
                            contract,
                            native_phase_execution_context(),
                            "SERVICE START FAILED",
                            phase,
                            workflow_name,
                            Some(name.as_str()),
                            None,
                            &[],
                            Some(command.exit_code),
                            None,
                        ),
                        report: DoctorReport {
                            ok: false,
                            provisioning: None,
                            adapter_bootstrap: None,
                            execution_target: None,
                            findings: Vec::new(),
                        },
                        service: Some(name.clone()),
                        service_command: Some(start.clone()),
                        task: None,
                        task_command: None,
                        exit_code: Some(command.exit_code),
                        stdout: stdout.clone(),
                        stderr: stderr.clone(),
                    }));
                }
                Err(error) => return Err(error),
            }
        }

        let service_report = diagnose_service(contract, resolved_path, name.as_str());
        if !service_report.ok {
            return Ok(Some(RepoUpResult {
                ok: false,
                status: "NOT READY",
                phase,
                preview: None,
                governance_preflight: None,
                receipt: repo_execution_receipt(
                    resolved_path,
                    contract,
                    native_phase_execution_context(),
                    "NOT READY",
                    phase,
                    workflow_name,
                    Some(name.as_str()),
                    None,
                    &service_report.findings,
                    None,
                    service_report
                        .findings
                        .first()
                        .map(|finding| finding.next.clone()),
                ),
                report: service_report,
                service: Some(name),
                service_command: None,
                task: None,
                task_command: None,
                exit_code: None,
                stdout: stdout.clone(),
                stderr: stderr.clone(),
            }));
        }
    }

    Ok(None)
}

fn resolve_up_workloads(
    setup_task: Option<&str>,
    setup_runtime: Option<&ResolvedTaskRuntime>,
    run_task: Option<&str>,
    run_runtime: Option<&ResolvedTaskRuntime>,
) -> BTreeMap<String, ResolvedTaskRuntime> {
    let mut workloads = BTreeMap::new();

    if let Some((task_name, runtime)) = setup_task.zip(setup_runtime.cloned()) {
        workloads.insert(task_name.to_string(), runtime);
    }

    if let Some((task_name, runtime)) = run_task.zip(run_runtime.cloned()) {
        workloads.insert(task_name.to_string(), runtime);
    }

    workloads
}

fn activation_failure_finding(action: &RequirementActivationAction, exit_code: i32) -> Finding {
    match action.acquisition.provider {
        ToolAcquisitionProvider::Corepack => Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: format!("Requirement activation failed: {}", action.tool_name),
            why: format!(
                "ota could not activate `{}` through Corepack; `{}` exited with code {exit_code}",
                action.tool_name,
                activation_action_command(action)
            ),
            next: format!(
                "run `{}` directly, repair the activation path, and rerun `ota up`",
                activation_action_command(action)
            ),
        },
        ToolAcquisitionProvider::Command => Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: format!("Requirement activation failed: {}", action.tool_name),
            why: format!(
                "ota could not activate `{}` through `{}`; `{}` exited with code {exit_code}",
                action.tool_name,
                action
                    .acquisition
                    .shell
                    .map(native_prerequisite_activation_shell_label)
                    .unwrap_or("command"),
                activation_action_command(action)
            ),
            next: format!(
                "run `{}` directly, repair the acquisition path, and rerun `ota up`",
                activation_action_command(action)
            ),
        },
        ToolAcquisitionProvider::Apt
        | ToolAcquisitionProvider::ReleaseAsset
        | ToolAcquisitionProvider::Brew
        | ToolAcquisitionProvider::Winget
        | ToolAcquisitionProvider::Choco
        | ToolAcquisitionProvider::Scoop => {
            unreachable!("provisioning-owned tool acquisition is not activation-owned")
        }
    }
}

fn run_activation_action(
    action: &RequirementActivationAction,
    working_dir: &Path,
    mode: RepoExecutionMode,
) -> Result<CommandRunResult, String> {
    match action.acquisition.provider {
        ToolAcquisitionProvider::Corepack => {
            if action.backend == Backend::Container {
                return Ok(CommandRunResult {
                    exit_code: 0,
                    executed_tasks: Vec::new(),
                    task_steps: Vec::new(),
                    stdout: String::new(),
                    stderr: String::new(),
                    target: None,
                    runtime: None,
                    service_termination: None,
                    fulfilled_toolchains: Vec::new(),
                    host_service_cleanup: Vec::new(),
                });
            }
            run_corepack_activation_action(&action.acquisition, working_dir, mode)
        }
        ToolAcquisitionProvider::Command => {
            run_command_activation_action(&action.acquisition, working_dir, mode)
        }
        ToolAcquisitionProvider::Apt
        | ToolAcquisitionProvider::ReleaseAsset
        | ToolAcquisitionProvider::Brew
        | ToolAcquisitionProvider::Winget
        | ToolAcquisitionProvider::Choco
        | ToolAcquisitionProvider::Scoop => Err(String::from(
            "provisioning-owned tool acquisition is not activation-owned",
        )),
    }
}

fn run_corepack_activation_action(
    acquisition: &ToolAcquisitionSpec,
    working_dir: &Path,
    mode: RepoExecutionMode,
) -> Result<CommandRunResult, String> {
    let mut stdout = String::new();
    let mut stderr = String::new();

    if !crate::doctor::command_available("corepack") && crate::doctor::command_available("npm") {
        let bootstrap = run_process_command(
            "npm",
            &["install", "-g", "corepack"],
            working_dir,
            mode,
            "Bootstrapping Corepack",
        );
        stdout.push_str(&bootstrap.stdout);
        stderr.push_str(&bootstrap.stderr);
        if bootstrap.exit_code != 0 {
            return Ok(CommandRunResult {
                exit_code: bootstrap.exit_code,
                executed_tasks: Vec::new(),
                task_steps: Vec::new(),
                stdout,
                stderr,
                target: None,
                runtime: None,
                service_termination: None,
                fulfilled_toolchains: Vec::new(),
                host_service_cleanup: Vec::new(),
            });
        }
    }

    let enable = run_process_command(
        "corepack",
        &["enable"],
        working_dir,
        mode,
        "Enabling Corepack",
    );
    stdout.push_str(&enable.stdout);
    stderr.push_str(&enable.stderr);
    if enable.exit_code != 0 {
        return Ok(CommandRunResult {
            exit_code: enable.exit_code,
            executed_tasks: Vec::new(),
            task_steps: Vec::new(),
            stdout,
            stderr,
            target: None,
            runtime: None,
            service_termination: None,
            fulfilled_toolchains: Vec::new(),
            host_service_cleanup: Vec::new(),
        });
    }

    let package_spec = format!(
        "{}@{}",
        acquisition
            .package
            .as_deref()
            .expect("validated corepack acquisition package"),
        acquisition
            .version
            .as_deref()
            .expect("validated corepack acquisition version")
    );
    let prepare = run_process_command(
        "corepack",
        &["prepare", package_spec.as_str(), "--activate"],
        working_dir,
        mode,
        "Activating prerequisite",
    );

    Ok(CommandRunResult {
        exit_code: prepare.exit_code,
        executed_tasks: Vec::new(),
        task_steps: Vec::new(),
        stdout: format!("{stdout}{}", prepare.stdout),
        stderr: format!("{stderr}{}", prepare.stderr),
        target: None,
        runtime: None,
        service_termination: None,
        fulfilled_toolchains: Vec::new(),
        host_service_cleanup: Vec::new(),
    })
}

fn run_command_activation_action(
    acquisition: &ToolAcquisitionSpec,
    working_dir: &Path,
    mode: RepoExecutionMode,
) -> Result<CommandRunResult, String> {
    let shell = acquisition
        .shell
        .expect("validated command acquisition shell");
    let run = acquisition
        .run
        .as_deref()
        .expect("validated command acquisition run");
    run_tool_acquisition_shell_command(shell, run, working_dir, mode, "Activating prerequisite")
}

fn run_tool_acquisition_shell_command(
    shell: crate::schema::NativePrerequisiteActivationShell,
    command: &str,
    working_dir: &Path,
    mode: RepoExecutionMode,
    loader_label: &str,
) -> Result<CommandRunResult, String> {
    let (program, args) = match shell {
        crate::schema::NativePrerequisiteActivationShell::Sh => {
            ("sh", vec!["-lc".to_string(), command.to_string()])
        }
        crate::schema::NativePrerequisiteActivationShell::Bash => {
            ("bash", vec!["-lc".to_string(), command.to_string()])
        }
        crate::schema::NativePrerequisiteActivationShell::Zsh => {
            ("zsh", vec!["-lc".to_string(), command.to_string()])
        }
        crate::schema::NativePrerequisiteActivationShell::Pwsh => (
            "pwsh",
            vec![
                "-NoProfile".to_string(),
                "-NonInteractive".to_string(),
                "-Command".to_string(),
                command.to_string(),
            ],
        ),
        crate::schema::NativePrerequisiteActivationShell::Cmd => (
            "cmd",
            vec![
                "/d".to_string(),
                "/s".to_string(),
                "/c".to_string(),
                command.to_string(),
            ],
        ),
    };
    let arg_refs = args.iter().map(String::as_str).collect::<Vec<_>>();
    Ok(run_process_command(
        program,
        &arg_refs,
        working_dir,
        mode,
        loader_label,
    ))
}

fn run_process_command(
    program: &str,
    args: &[&str],
    working_dir: &Path,
    mode: RepoExecutionMode,
    loader_label: &str,
) -> CommandRunResult {
    let program_path = resolve_command_path(program).unwrap_or_else(|| PathBuf::from(program));
    let mut command = Command::new(program_path);
    command.args(args).current_dir(working_dir);
    let command_label = command_label(program, args);

    match mode {
        RepoExecutionMode::Capture => match command.output() {
            Ok(output) => CommandRunResult {
                exit_code: output.status.code().unwrap_or(1),
                executed_tasks: Vec::new(),
                task_steps: Vec::new(),
                stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
                target: None,
                runtime: None,
                service_termination: None,
                fulfilled_toolchains: Vec::new(),
                host_service_cleanup: Vec::new(),
            },
            Err(error) => command_spawn_failure_result(&command_label, error),
        },
        RepoExecutionMode::Stream => {
            match run_streaming_command_with_loader(&mut command, loader_label) {
                Ok(exit_code) => CommandRunResult {
                    exit_code,
                    executed_tasks: Vec::new(),
                    task_steps: Vec::new(),
                    stdout: String::new(),
                    stderr: String::new(),
                    target: None,
                    runtime: None,
                    service_termination: None,
                    fulfilled_toolchains: Vec::new(),
                    host_service_cleanup: Vec::new(),
                },
                Err(error) => command_spawn_failure_result(&command_label, error),
            }
        }
    }
}

fn command_label(program: &str, args: &[&str]) -> String {
    std::iter::once(program)
        .chain(args.iter().copied())
        .collect::<Vec<_>>()
        .join(" ")
}

fn command_spawn_failure_result(command_label: &str, error: io::Error) -> CommandRunResult {
    let exit_code = if error.kind() == io::ErrorKind::NotFound {
        127
    } else {
        1
    };
    CommandRunResult {
        exit_code,
        executed_tasks: Vec::new(),
        task_steps: Vec::new(),
        stdout: String::new(),
        stderr: format!("failed to execute `{command_label}`: {error}\n"),
        target: None,
        runtime: None,
        service_termination: None,
        fulfilled_toolchains: Vec::new(),
        host_service_cleanup: Vec::new(),
    }
}

fn has_native_prerequisite_blocker(report: &DoctorReport) -> bool {
    report.findings.iter().any(|finding| {
        finding.severity == FindingSeverity::Error
            && matches!(
                finding.code(),
                "OTA_NATIVE_PREREQUISITE_MISSING" | "OTA_NATIVE_PREREQUISITE_TIMED_OUT"
            )
    })
}

fn has_effect_governance_policy_blocker(report: &DoctorReport) -> bool {
    report
        .findings
        .iter()
        .any(|finding| is_effect_governance_policy_block_summary(&finding.summary))
}

fn remote_up_blocker_finding(
    phase_task: Option<&str>,
    setup_task: bool,
    context_name: Option<&str>,
    remote: Option<&crate::schema::RemoteBackend>,
) -> Finding {
    let provider = remote
        .map(|remote| remote.provider.trim())
        .filter(|provider| !provider.is_empty())
        .unwrap_or("unknown");
    let target = remote
        .and_then(|remote| remote.target.as_deref())
        .filter(|target| !target.trim().is_empty());
    let context_suffix = context_name
        .map(|context| format!(" context `{context}`"))
        .unwrap_or_default();
    let target_suffix = target
        .map(|target| format!(" targeting `{target}`"))
        .unwrap_or_default();

    match phase_task {
        Some(task) => Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: if setup_task {
                String::from("Remote setup contexts are not supported by `ota up` yet")
            } else {
                String::from("Remote workflow tasks are not supported by `ota up` yet")
            },
            why: format!(
                "task `{task}` resolves to remote{context_suffix} via provider `{provider}`{target_suffix}, but current `ota up` orchestration only prepares native and container workload planes authoritatively"
            ),
            next: format!(
                "use `ota run {task}`, `ota execution plan --mode remote`, and `ota doctor` together, or move the selected {} to a native/container context until remote `ota up` support ships",
                if setup_task {
                    "setup task"
                } else {
                    "workflow task"
                }
            ),
        },
        None => Finding {
            identity: None,
            severity: FindingSeverity::Error,
            summary: String::from("Remote repo execution is not supported by `ota up` yet"),
            why: format!(
                "the selected repo execution resolves to remote{context_suffix} via provider `{provider}`{target_suffix}, but current `ota up` orchestration only prepares native and container workload planes authoritatively"
            ),
            next: String::from(
                "use `ota execution plan --mode remote` plus explicit remote task execution, or move the repo default execution to a native/container context until remote `ota up` support ships",
            ),
        },
    }
}

fn up_remote_execution_blocker(
    contract: &Contract,
    resolved_path: &Path,
    overrides: ExecutionOverrides,
    workflow_name: Option<&str>,
) -> Option<(PhaseExecutionContext, Option<String>, Finding)> {
    if let Some(task_name) = selected_up_primary_task_name(contract, workflow_name) {
        let effective = effective_task_execution(contract, task_name, overrides);
        if effective.backend == Backend::Remote {
            let setup_task =
                selected_up_setup_task_name(contract, workflow_name) == Some(task_name);
            return Some((
                task_phase_execution_context(contract, resolved_path, task_name, overrides, None),
                Some(task_name.to_string()),
                remote_up_blocker_finding(
                    Some(task_name),
                    setup_task,
                    reported_task_context_for_backend(contract, task_name, effective.backend),
                    effective.remote,
                ),
            ));
        }
    } else {
        let (backend, _) = effective_execution(contract, overrides);
        if backend == Backend::Remote {
            let context = selected_phase_execution_context(contract, resolved_path, overrides);
            let context_name = context.context.clone();
            let remote = contract
                .execution
                .as_ref()
                .and_then(|execution| execution.default_context())
                .filter(|(_, selected)| selected.backend == Backend::Remote)
                .and_then(|(name, _)| named_execution_context(contract, name))
                .and_then(|(_, context)| context.remote.as_ref())
                .or_else(|| {
                    contract
                        .execution
                        .as_ref()
                        .and_then(|execution| execution.backends.as_ref())
                        .and_then(|backends| backends.remote.as_ref())
                });
            return Some((
                context,
                None,
                remote_up_blocker_finding(None, false, context_name.as_deref(), remote),
            ));
        }
    }

    None
}

fn append_up_safe_task_effect_policy_findings(
    contract: &Contract,
    workflow_name: Option<&str>,
    overrides: ExecutionOverrides,
    loaded_policy: Option<&LoadedOrgPolicyPack>,
    report: &mut DoctorReport,
) {
    let mut task_names = BTreeSet::new();
    if let Some(setup_task) = selected_up_setup_task_name(contract, workflow_name) {
        task_names.insert(setup_task.to_string());
    }
    if let Some(activation_task) = selected_up_activation_task_name(contract, workflow_name) {
        task_names.insert(activation_task.to_string());
    }
    for task_name in task_names {
        append_safe_task_effect_policy_findings(
            contract,
            &task_name,
            overrides,
            loaded_policy,
            report,
        );
    }
}

fn append_uv_local_project_findings(
    contract: &Contract,
    contract_path: &Path,
    workflow_name: Option<&str>,
    findings: &mut Vec<Finding>,
) {
    for task_name in contract.selected_workflow_task_closure_names(workflow_name) {
        let Some(task) = contract.tasks.get(task_name.as_str()) else {
            continue;
        };
        let Some(crate::schema::TaskPrepareSpec::DependencyHydration(hydration)) =
            task.prepare.as_ref()
        else {
            continue;
        };
        let crate::schema::TaskDependencyHydrationSourceSpec::Uv(source) = &hydration.source else {
            continue;
        };
        let Some(local_project) =
            crate::hydration_provenance::resolve_uv_local_project_identity(contract_path, source)
        else {
            continue;
        };
        if let Some(why) = local_project.resolution_error {
            let target = local_project
                .lockfile_path
                .unwrap_or(local_project.manifest_path.clone());
            findings.push(Finding {
                identity: Some(FindingIdentity {
                    code: String::from("OTA_UV_LOCAL_PROJECT_INPUT_UNAVAILABLE"),
                    category: String::from("environment"),
                    owner: String::from("repo_contract"),
                }),
                severity: FindingSeverity::Error,
                summary: format!("Typed uv local-project input unavailable: {task_name}"),
                why,
                next: format!(
                    "restore `{target}` or repair `tasks.{task_name}.prepare.source.local_project` before rerunning `ota doctor` or execution"
                ),
            });
        }
        if let Some(why) = local_project.source_identity_error {
            findings.push(Finding {
                identity: Some(FindingIdentity {
                    code: String::from("OTA_UV_LOCAL_PROJECT_SOURCE_IDENTITY_UNAVAILABLE"),
                    category: String::from("replay"),
                    owner: String::from("repo_contract"),
                }),
                severity: FindingSeverity::Warn,
                summary: format!("Typed uv local-project source identity unavailable: {task_name}"),
                why,
                next: String::from(
                    "use a clean Git worktree for replay-grade local-project provenance; execution can continue but source replay identity remains unavailable",
                ),
            });
        }
    }
}

